    rep(i,0,v.sz-1){
      ll a3 = max(0LL,r1-v[i].fi+1);
      ll b3 = max(0LL,segmn1.query(i+1,v.sz)-l2+1);
      mx = max(mx,a3+b3);
    }
  }
