  pair<ll,ll>right = {0,1'000'000'001};
  ll ans = maxsingle;
  per(i,1,n){
    if(lr[i].first == minrl)break;
    // 第i个移动到右侧
    right.first = max(right.first,lr[i].first);
    right.second = min(right.second,lr[i].second);
    if(right.second < right.first)break; // 右侧为0
    if(lr[i-1].first > minr)continue; // 左侧为0
    ans = max(ans,(minr-lr[i-1].first+1)+(right.second-right.first+1));
  }
  if(right.first == 0){ // 全部包裹了最小段
    cout<<max(ans,maxsingle+(minr-minrl+1))<<endl;
    return 0;
  }
  cout<<ans<<endl;
  return 0;
}

