    rep11(i,n) ans = max(ans, memol[i-1] + memor[i]);

    rep(i,n) memol[i] = memor[i] = 0, swap(v[i].fi, v[i].se);
    sort(all(v));
    c = v[0].se;
    rep(i,n) {
        c = max(c, v[i].se);
        memol[i] = max(0LL, v[0].fi - c + 1);
    }
    c = v[n-1].se;
    C = v[n-1].fi;
    repm(i,n) {
        c = max(c, v[i].se);
        C = min(C, v[i].fi);
        memor[i] = max(0LL, C - c + 1);
    }
    rep11(i,n) ans = max(ans, memol[i-1] + memor[i]);
    cout << ans << endl;
}

