int main() {
  int N;
  cin >> N;
  vector<pair<int, int>> lr = vector<pair<int, int>>(N);
  REP(i, N) {
    int L, R;
    cin >> L >> R;
    lr[i] = {L, R};
  }
  int INF = 1000000001;
  auto solve = [&]() {
    vector<int> max_s = vector<int>(N, 0);
    vector<int> min_e = vector<int>(N, INF);
    REP(i, N) {
      int s = lr[i].first;
      int e = lr[i].second;
      if(i == 0) {
        max_s[i] = max(s, 0);
        min_e[i] = min(e, INF);
      } else {
        max_s[i] = max(s, max_s[i - 1]);
        min_e[i] = min(e, min_e[i - 1]);
      }
    }
    // dump(max_s, min_e);
    vector<int> max_sr = vector<int>(N, 0);
    vector<int> min_er = vector<int>(N, INF);
    for(int i = N - 1; i >= 0; i--) {
      int s = lr[i].first;
      int e = lr[i].second;
      if(i == N - 1) {
        max_sr[i] = max(s, 0);
        min_er[i] = min(e, INF);
      } else {
        max_sr[i] = max(s, max_sr[i + 1]);
        min_er[i] = min(e, min_er[i + 1]);
      }
    }
    // dump(max_sr, min_er);
    ll ans = 0;
    REP(i, N - 1) {
      ll sum = 0;
      sum += min_e[i] - max_s[i] + 1;
      sum += min_er[i + 1] - max_sr[i + 1] + 1;
      ans = max(sum, ans);
    }
    return ans;
  };
  sort(ALL(lr), comp_by_first);
  ll ans1 = solve();
  sort(ALL(lr), comp_by_second);
