ll unite(ll l1, ll r1, ll l2, ll r2){
    if(r1 < l2 || r2 < l1) return 0;
    else return min(r1,r2)-max(l1,l2)+1;
}

P newsec(P sec, ll l, ll r){
    if(unite(sec.first, sec.second, l, r) == 0) return P(-1,-2);
    else return P(max(sec.first,l), min(sec.second,r));
}

