        b[i] = min(b[i - 1], w[i].r);
    }
    c[n] = w[n].l, d[n] = w[n].r;
    for (register int i = n - 1; i >= 1; --i) {
        c[i] = max(c[i + 1], w[i].l);
        d[i] = min(d[i + 1], w[i].r);
    }
    for (register int i = 1; i < n; ++i) {
