inline ll read(void){
	reg bool f=false;
	reg char ch=getchar();
	reg ll res=0;
	while(ch<'0'||'9'<ch)f|=(ch=='-'),ch=getchar();
	while('0'<=ch&&ch<='9')res=10*res+ch-'0',ch=getchar();
	return f?-res:res;
}

const int MAXN=100000+5;

struct Interval{
	ll l,r;
	inline void Read(void){
		l=read(),r=read();
		return;
	}
	inline bool operator<(const Interval& a)const{
		return r==a.r?l<a.l:r<a.r;
	}
	inline ll len(void){
		return r-l+1;
	}
};

int n;
Interval a[MAXN];
int pre[MAXN];

inline void Read(void);
inline void Work(void);
inline Interval Jiao(const Interval& a,const Interval& b);

int main(void){
	Read();
	Work();
	return 0;
}

inline void Read(void){
	reg int i;
	n=read();
	for(i=1;i<=n;++i)
		a[i].Read();
	return; 
}

inline void Work(void){
	reg int i;
	ll ans=0;
	static Interval temp;
	sort(a+1,a+n+1);
	temp=a[1];
	pre[1]=temp.len();
	for(i=2;i<=n;++i){
		temp=Jiao(temp,a[i]);
		pre[i]=temp.len();
	}
	temp=a[n];
	ans=max(ans,pre[n-1]+temp.len());
	for(i=n-1;i>=2;--i){
		temp=Jiao(temp,a[i]);
		ans=max(ans,pre[i-1]+temp.len());
	}
	printf("%lld\n",ans);
	return;
}

inline Interval Jiao(const Interval& a,const Interval& b){
	Interval res;
	res.l=max(a.l,b.l);
	res.r=min(a.r,b.r);
	if(res.l>res.r)
		res.l=res.r=0;
	return res;
}

