int baga() {
    dp[2] = {v[0], v[1]};
    for (int i = 3; i <= n; ++i) {
        auto &sg0 = dp[i - 1].first;
        auto &sg1 = dp[i - 1].second;
        int lost0 = sg0.second - sg0.first + 1 - max(min(sg0.second, v[i].second) - max(sg0.first, v[i].first) + 1, 0);
        int lost1 = sg1.second - sg1.first + 1 - max(min(sg1.second, v[i].second) - max(sg1.first, v[i].first) + 1, 0);
        if (lost0 < lost1) {
            dp[i] = {{max(sg0.first, v[i].first), max(min(sg0.second, v[i].second), max(sg0.first, v[i].first))}, sg1};
        }
        else {
            dp[i] = {{max(sg1.first, v[i].first), max(min(sg1.second, v[i].second), max(sg1.first, v[i].first))}, sg0};
        }
    }
    return (dp[n].second.second + dp[n].first.second - dp[n].second.first - dp[n].first.first + 2);
}

