	for(int i = 0; i < n; ++i) {
		int l, r; cin >> l >> r;
		++r;
		lmax = max(lmax, l);
		rmin = min(rmin, r);
		p[i] = {l, -r};
	}
	sort(p, p + n);
	int ans = 0;
	{ // same
		bool flg = false;
		int ans1 = max(0, rmin - lmax), ans2 = 0;
		for(int i = 0; i < n; ++i) {
			int l, r;
			tie(l, r) = p[i];
			r = -r;
			if(l == lmax or r == rmin) {
				if(l == lmax and r == rmin) {
					flg = true;
				}
				continue;
			}
			ans2 = max(ans2, r - l);
		}
		if(flg) {
			ans = ans1 + ans2;
			cout << ans << '\n';
			return 0;
		}
	}
	// (lmax, r) (l, rmin)
	{ // diff
		multiset<int> r1, l2;
		int idx = -1;
		for(int i = 0; i < n; ++i) {
			int l, r;
			tie(l, r) = p[i];
			r = -r;
			if(r == rmin) {
				if(idx == -1) {
					l2.insert(l);
					idx = i;
				}
			} else {
				r1.insert(r);
			}
		}
		for(int i = 0; i < n; ++i) {
			if(idx == i) continue;
			int l, r;
			tie(l, r) = p[i];
			r = -r;
			int ansp, ansc;
			{ // not changed
				int ans1 = max(0, *r1.begin() - lmax);
				int ans2 = max(0, rmin - *l2.rbegin());
				ansp = ans1 + ans2;
			}
			{ // changed
				r1.erase(r1.find(r));
				l2.insert(l);
				int ans1 = max(0, *r1.begin() - lmax);
				int ans2 = max(0, rmin - *l2.rbegin());
