		if(i==0){
			Left_R_min[i] = r;
			Left_L_MAX[i] = l;
		}else{
			Left_L_MAX[i] = max(l,Left_L_MAX[i-1]);
			Left_R_min[i] = min(r,Left_R_min[i-1]);
		}
	}
	//次に、右から見る
	for(ll i = n -1 ; i >= 0 ; i--){
		ll l,r;
		tie(r,l) = RL[i];
		if(i==n-1){
			Right_R_min[n-1] = r;
			Right_L_MAX[n-1] = l;
		}else{
			Right_L_MAX[i] = max(r,Right_L_MAX[i+1]);
			Right_R_min[i] = min(l,Right_R_min[i+1]);
		}
	}
	ll ansRL = 0;
	rep(i,n-1){
		ll nowfront = Left_R_min[i] - Left_L_MAX[i]+1;
		if(nowfront<0) nowfront = 0;

		ll nowback  = Right_R_min[i+1] - Right_L_MAX[i+1]+1;
		if(nowback<0) nowback = 0;

		ansRL = max(ansRL,nowback + nowfront);

	}
	ll ANS = max(ans,ansRL);
	cout << ANS << endl;
}

