    }
    sort(arr, arr + n, [](auto a, auto b) {
        return a.first == b.first ? a.second > b.second : a.first < b.first;
    });

    // [l|r, {ids}]
    map<int, unordered_set<int>> by_left, by_right;
    auto get_cur_b = [&by_left, &by_right] {
        return by_right.begin()->first - (--by_left.end())->first + 1;
    };

    for (int i = 0; i < n; ++i) {
        by_left[arr[i].first].insert(i);
        by_right[arr[i].second].insert(i);
    }
    int res = get_cur_b();
    auto cur_a = pair<int, int>{0, 1e9};
    auto get_cur_a = [&cur_a] {
        return cur_a.second - cur_a.first + 1;
    };

    for (int i = 0; i < n; ++i) {
        auto l = arr[i].first;
        auto r = arr[i].second;
        cur_a.first = max(cur_a.first, l);
        cur_a.second = min(cur_a.second, r);
        if (cur_a.first > cur_a.second) cur_a.first = cur_a.second + 1;

        auto erase_from_map = [](int i, auto& mp, int val) {
            auto it = mp.find(val);
