    }

    auto it = max_element(interval.begin(), interval.end() );
    mx = *it; interval.erase(it);


    sort(interval.begin(), interval.end(), [&](pair<int, int> i, pair<int, int> j) { return i.second < j.second; });

    int mxInterval = 0;
    for (auto _ : interval) mxInterval = max(mxInterval, _.second - _.first + 1);
    ans = max(ans, mxInterval + max(0, min(interval[0].second, mx.second) - mx.first + 1) );

//    cerr << mx.first << ' ' << mx.second << '\n';
//    for (auto _ : interval) cerr << _.first << ' ' << _.second << '\n';

    pair<int, int> pref = { -inf, inf };
    int prv = 0;
    for (int i = 0; i < (int)interval.size(); ++i) {
        while (prv < (int)interval.size() && interval[prv].second < interval[i].second) {
            pref = pref + interval[prv];
            ++prv;
        }
        if (prv) {
            ans = max(ans, max(0, interval[i].second - mx.first + 1) + max(0, pref.second - pref.first + 1) );
        }
    }
    while (prv < (int)interval.size() ) {
        pref = pref + interval[prv];
        ++prv;
    }
    ans = max(ans, max(0, mx.second - mx.first + 1) + max(0, pref.second - pref.first + 1) );

    cout << ans;

    return 0;
}
