  class Data {
   public:
    int l, r;
	int range() const {return r-l+1;}
	Data() = default;
	Data(int il, int ir) : l(il), r(ir) {}
	Data unite(const Data& x) {
	  return {max(l, x.l), min(r, x.r)};
	}
  };
  vector<Data> LR(N); for (auto& lr : LR) cin>>lr.l>>lr.r;

  auto sl = LR[0], sr = LR[1];
  for (int i = 2; i < N; i++) {
    auto clr = LR[i];
    auto s1 = sl.unite(clr);
    auto s2 = sr.unite(clr);
    auto s3 = sl.unite(sr);
    auto r1 = s1.range() + sr.range();
    auto r2 = s2.range() + sl.range();
    auto r3 = s3.range() + clr.range();
    if (r1 >= r2 and r1 >= r3) {
      sl = s1;
    } else if (r2 >= r3) {
      sr = s2;
    } else {
      sl = s3;
      sr = clr;
    }
  }

  auto ans = sl.range() + sr.range();
  cout << ans << endl;

  return 0;
}

