  REP(i, n){
    if(i!=lidx && i!=ridx){
      ord.push_back(i);
    }
  }
  sort(ALL(ord), [&l, &r](int x, int y){
    if(r[x]==r[y]) return l[x]<l[y];
    return r[x]>r[y];
  });
  ord.push_back(ridx);
  int lb=0;
  FORR(i, 0, n-1){
    CHMAX(lb, l[ord[i]]);
    // 1回目
    int tmp=max(0ll, r[ridx]-lb);
    // ２回目
    tmp+=max(0ll, min(r[lidx], (i>0 ? r[ord[i-1]] : r[lidx]))-l[lidx]);
    CHMAX(ans, tmp);
  }
  cout<<ans<<'\n';
  return 0;
}

