pair<int, int> ps[maxn];

void solve() {
  int rr = inf, ll = 0;
  for (int i = 0; i < n; i++) {
    rr = min(rr, rs[i]);
    ll = max(ll, ls[i]);
  }
  for (int i = 0; i < n; i++) {
    ps[i] = make_pair(max(0, rr - ls[i]), max(0, rs[i] - ll));
