        vector<pair<int,int>> lol;
        if(j!=s.begin())
        {
            j--;
            while(1)
            {
                lol.push_back(*j);
                curl.insert({p[j->second].first,j->second});
                curr.insert({p[j->second].second,j->second});
                if(j==s.begin())
                    break;
                j--;
            }
        }
        for(auto j:lol)
                s.erase(j);
        if(!curl.empty())
        {
            int z=max(0LL,v[i]-mmx+1);
            auto tt=curl.end();
            tt--;
            z+=max(0LL,curr.begin()->first-tt->first+1);
