        }
    }

    curl.clear();
    curr.clear();
    for(int i=1;i<=n;i++)
    {
        curr.insert({p[i].second,i});
        curl.insert({p[i].first,i});
    }
    for(int i=1;i<=n;i++)
    {        
        curr.erase({p[i].second,i});
        curl.erase({p[i].first,i});
        auto tt=curl.end();
        tt--;
        mx=max(mx,p[i].second-p[i].first+1+max(0LL,curr.begin()->first-tt->first+1));
        curr.insert({p[i].second,i});
        curl.insert({p[i].first,i});
    }
    cout<<mx;

}

