    pref[0] = r - l + 1;
    for (int i = 1; i < n; i++) {
        l = max(a[i].first, l);
        r = min(a[i].second, r);
        pref[i] = max(0, r - l + 1);
    }
    l = a[n - 1].first, r = a[n - 1].second;
    suf[n - 1] = r - l + 1;
    for (int i = n - 2; i >= 0; i--) {
        l = max(a[i].first, l);
        r = min(a[i].second, r);
        suf[i] = max(0, r - l + 1);
    }
    for (int i = 0; i < n - 1; i++) {
        ans = max(ans, pref[i] + suf[i + 1]);
    }
    cout << ans;
}

