using namespace std;

#define REP(i,n) for(int i=0;i<(int)(n);++i)

typedef long long Int;

void solve(long long N, std::vector<long long> L, std::vector<long long> R){
	vector<pair<Int,Int> > p;
	REP(i,N)p.push_back({L[i], R[i]});
	sort(p.begin(),p.end());
	REP(i,N)L[i] = p[i].first, R[i] = p[i].second;
	Int ans = 0;
	vector<pair<Int,int> > v;
	REP(i,N)v.push_back({R[i] - L[i] + 1, i});
	sort(v.begin(), v.end());
	for(int vi = N - 1;vi >= N - 2;vi--){
		int i = v[vi].second;
		Int Lmax = -1e+12, Rmin = 1e+12;
		REP(j, N){
			if(i == j)continue;
			Lmax = max(Lmax, p[j].first);
			Rmin = min(Rmin, p[j].second);
		}

		if(Lmax <= Rmin){
			Int t = 0;
			ans = max(ans, t = R[i] - L[i] + 1 + Rmin - Lmax + 1);
		}
	}

	Int Rmin = 1e+12;
	int Rmin_id = -1;
	for(int i = 0;i < N;i++){
		if(Rmin > p[i].second){
			Rmin = R[i];
			Rmin_id = i;
		}
	}
	Int Lmax2 = -1e+12, Rmin2 = 1e+12;
	for(int i = N - 1;i >= 0;i--){
		if(p[i].first > Rmin){
			Lmax2 = max(Lmax2, p[i].first);
			Rmin2 = min(Rmin2, p[i].second);
			continue;
		}
		if(Lmax2 >= 0 and Rmin2 >= Lmax2)ans = max(ans, Rmin2 - Lmax2 + 1 + Rmin - p[i].first + 1);
//		ans = max(ans, Rmin2 - Lmax2 + 1 + Rmin - p[i].first + 1);
		if(i == Rmin_id){
			break;
		}
		Lmax2 = max(Lmax2, p[i].first);
		Rmin2 = min(Rmin2, p[i].second);
	}
	if(Lmax2 >= 0 and Rmin2 >= Lmax2)ans = max(ans, Rmin2 - Lmax2 + 1 + Rmin - p[Rmin_id].first + 1);
	cout<<ans<<endl;
}

