/**
 *	セグメント木を構成する
 *	2methodの変更により調整
 */
template<class T>
class SegmentTree {
public:
	const T initialValue = T(-1, 1e10);
	const T ignoreValue = T(-1, 1e10);

	const ll m_size;
	vector<T> m_node;

	ll calcSize(ll n) {
		ll size = 1;
		while (size < n) {
			size *= 2;
		}
		return size;
	}

	/**
	 * 値の更新(更新:=, 加算:+=, etc...)
	 */
	void update(ll k, T x) {
		m_node[k] = x;
	}

	/**
	* 値の併合
	*/
	T merge(T xl, T xr) {
		ll l = std::max(xl.first, xr.first);
		ll r = std::min(xl.second, xr.second);
		if (l > r) {
			return {-100,-1000};
		}
		return {l,r};
	}
public:
	SegmentTree(ll n) :
		m_size(calcSize(n)),
		m_node(m_size * 2 - 1, initialValue) {}

	void add(ll itr, T val) {
		ll i = itr + m_size - 1;
		update(i, val);

		while (i > 0) {
			i = (i - 1) / 2;
			m_node[i] = merge(m_node[i * 2 + 1], m_node[i * 2 + 2]);
		}
		/**
		cout << "-- tree -- " << endl;
		REP(i, 2 * m_size - 1) {
			cout << m_node[i] << endl;
		}
		/*//**/
	}

	T query(ll a, ll b) { return query(a, b + 1, 0, 0, m_size); }
	T query(ll a, ll b, ll k, ll l, ll r) {
		if (r <= a || b <= l) { return ignoreValue; }
		if (a <= l && r <= b) { return m_node[k]; }
		return merge(
			query(a, b, 2 * k + 1, l, (l + r) / 2),
			query(a, b, 2 * k + 2, (l + r) / 2, r)
		);
	}
};

signed main() {
	ll n;
	cin >> n;
	V<PAIR> v; v.reserve(n);
	REP(_, n) {
		ll a, b; cin >> a >> b;
		v.emplace_back(a, b);
	}
	ll ans = 0;
	{
		SORT(v);

		auto tree = SegmentTree<PAIR>(n);
		REP(i, n) {
			tree.add(i, v[i]);
		}

		REP(i, n - 1) {
			auto q1 = tree.query(0LL, i);;
			ll r1 = q1.second - q1.first + 1;
			if (r1 > 1e9) { r1 = 0; }MAX(r1, 0LL);

			auto q2 = tree.query(i + 1, n);
			ll r2 = q2.second - q2.first + 1;
			if (r2 > 1e9) { r2 = 0; }MAX(r2, 0LL);
			MAX(ans, r1 + r2);
		}

		{// 2
			VL lmn(n), rmx(n + 1, 1e10);
			lmn[0] = v[0].second;
			FOR(i, 1, n) { lmn[i] = std::min(v[i].second, lmn[i - 1]); }
			rmx[n - 1] = v[n - 1].first;
			RFOR(i, 0, n - 1) { rmx[i] = std::max(v[i].second, rmx[i + 1]); }

			unordered_map<ll, ll> toI;
			REP(i, n) {
				toI[v[i].first] = i;
			}
			FOR(i, 1, n) {
				ll ok = toI[v[i].first];
				ll val = v[i].second - v[i].first + 1;
				ll lr = lmn[i - 1] - rmx[ok + 1] + 1;
				MAX(lr, 0LL);
				val += lr;
				MAX(ans, val);
			}
		}
	}
	cout << ans << endl;
	//dump(v);
}

