int n;
ll l[100005], r[100005];
void solve() {
    cin >> n;

    ll left = -inf, right = inf;
    rep(i, n) {
        cin >> l[i] >> r[i];

        ++r[i];
        maxs(left, l[i]);
        mins(right, r[i]);
    }

    ll ans = 0;
    rep(i, n) maxs(ans, max<ll>(0, right - left) + r[i] - l[i]);

    vector<pair<ll, ll>> v(n);
    rep(i, n) { v[i].first = max<ll>(0, r[i] - left); v[i].second = -max<ll>(0, right - l[i]); }
    all(sort, v);

    ll w = inf;
    rep(i, n) {
        v[i].second *= -1;
        if (i != 0) maxs(ans, w + v[i].first);
        mins(w, v[i].second);
    }

    cout << ans << endn;

}

