const int  INF = 1 << 29;
const ll INFL = 1LL << 60;
const ll mod = 1000000007;

struct Segment_tree_min {
	using T = ll;

	int n;
	vector<T> data;
	const T out = 1e9 + 5;

	inline T vmerge(T l, T r) { return min(l, r); }

	Segment_tree_min(int n) :n(n) { data.assign(2 * n, out); }

	void update(int p, T x) {  // set value at position p
		for (data[p += n] = x; p > 1; p >>= 1) {
			data[p >> 1] = vmerge(data[p], data[p ^ 1]);
		}
	}

	T query(int l, int r) {  // sum on interval [l, r)
		T resl = out, resr = out;
		for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
			if (l & 1) resl = vmerge(data[l++], resl);
			if (r & 1) resr = vmerge(resr, data[--r]);
		}
		return vmerge(resl, resr);
	}
};

struct Segment_tree_max {
	using T = ll;

	int n;
	vector<T> data;
	const T out = 0;

	inline T vmerge(T l, T r) { return max(l, r); }

	Segment_tree_max(int n) :n(n) { data.assign(2 * n, out); }

	void update(int p, T x) {  // set value at position p
		for (data[p += n] = x; p > 1; p >>= 1) {
			data[p >> 1] = vmerge(data[p], data[p ^ 1]);
		}
	}

	T query(int l, int r) {  // sum on interval [l, r)
		T resl = out, resr = out;
		for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
			if (l & 1) resl = vmerge(data[l++], resl);
			if (r & 1) resr = vmerge(resr, data[--r]);
		}
		return vmerge(resl, resr);
	}
};


int main() {

	int n;
	cin >> n;
	VP v(n);
	REP(i, n) {
		int a, b;
		cin >> a >> b;
		v[i] = { b,a };
	}
	sort(ALL(v));

	Segment_tree_min rmq1(n), rmq2(n);
	Segment_tree_max rmq3(n), rmq4(n);

	REP(i, n) {
		rmq1.update(i, v[i].first);
		rmq3.update(i, v[i].second);
	}

	int ans = 0;

	REP(i, n) {
		int cnt = v[i].first - v[i].second + 1;
		rmq1.update(i, INF);
		rmq3.update(i, 0);
		int a = rmq1.query(0, n) - rmq3.query(0, n) + 1;
		a = max(0, a);
		ans = max(ans, a + cnt);
		rmq1.update(i, v[i].first);
		rmq3.update(i, v[i].second);
	}
	REP(i, n - 1) {
		rmq1.update(i, INF);
		rmq3.update(i, 0);
		rmq2.update(i, v[i].first);
		rmq4.update(i, v[i].second);
		int a = rmq1.query(0, n) - rmq3.query(0, n) + 1;
		int b = rmq2.query(0, n) - rmq4.query(0, n) + 1;
		a = max(a, 0);
		b = max(b, 0);
		ans = max(ans, a + b);
	}
	cout << ans << endl;
}

