pll lo(pll a, pll b)
{
	return {max(a.first, b.first), min(a.second, b.second)};
}

ll daja()
{
	if (al.empty())
		return -inf;
	auto it=al.end();
	it--;
	auto jt=ar.begin();
	return max(0LL, (*jt)-(*it)+1);
}

ll dajb()
{
	if (bl.empty())
		return -inf;
	auto it=bl.end();
	it--;
	auto jt=br.begin();
	return max(0LL, (*jt)-(*it)+1);
}

int main()
{
	scanf("%d", &n);
	for (int i=1; i<=n; i++)
	{
		scanf("%lld%lld", &l[i], &r[i]);
		eve.push_back({l[i], i});
		eve.push_back({r[i]+1, -i});
		al.insert(l[i]);
		ar.insert(r[i]);
	}
	sort(eve.begin(), eve.end());
	for (auto i : eve)
	{
		int x=abs(i.second);
		if (i.second>0)
		{
			al.erase(al.find(l[x]));
			ar.erase(ar.find(r[x]));
			bl.insert(l[x]);
			br.insert(r[x]);
		}
		else
		{
			bl.erase(bl.find(l[x]));
			br.erase(br.find(r[x]));
			al.insert(l[x]);
			ar.insert(r[x]);
		}
		wyn=max(wyn, daja()+dajb());
	}
	pre[0]=suf[n+1]={-inf, inf};
	for (int i=1; i<=n; i++)
		pre[i]=lo(pre[i-1], {l[i], r[i]});
	for (int i=n; i; i--)
		suf[i]=lo(suf[i+1], {l[i], r[i]});
	for (int i=1; i<=n; i++)
	{
		pll w=lo(pre[i-1], suf[i+1]);
		wyn=max(wyn, max(0LL, w.second-w.first+1)+r[i]-l[i]+1);
	}

	printf("%lld\n", wyn);
	return 0;
}

