template<typename Monoid>
class segment_tree {
	using value_type = Monoid;
	using size_type = size_t;

	using binary_function = std::function<value_type(value_type, value_type)>;
	using checker = std::function<bool(value_type)>;

	const size_type size_;
	size_type height_;

	const value_type id;
	const binary_function bi_func;
	std::vector<value_type> data;

	private:
	const size_type get_height(const size_type& size) const {
		size_type height = 1;
		while(1 << height < size) height++;
		return height;
	}
	const size_type base_size() const {
		return 1 << height_;
	}
	void meld(const size_type& index) {
		data[index] = bi_func(data[index << 1 ^ 0], data[index << 1 ^ 1]);
	}

	public:
	segment_tree(const size_type& size, const binary_function& bi_func, const value_type& id)
		: size_(size),
		  bi_func(bi_func),
		  id(id) {
		height_ = get_height(size);
		data.assign(base_size() << 1, id);
	}
	value_type fold(size_type left, size_type right) {
		value_type l_value = id,
				   r_value = id;

		for(left += base_size(), right += base_size();
			left < right;
			left >>= 1, right >>= 1) {
			if(left & 1)  l_value = bi_func(l_value, data[left++]);
			if(right & 1) r_value = bi_func(data[--right], r_value); 
		}
		return bi_func(std::move(l_value), std::move(r_value));
	}
	void update(size_type index, const value_type& value) {
		index += base_size();
		data[index] = bi_func(data[index], value);

		while(index >>= 1) meld(index);
	}
	void change(size_type index, const value_type& value) {
		index += base_size();
		data[index] = value;

		while(index >>= 1) meld(index);
	}
	const size_type search(const size_type & left, const checker & check) {
		value_type val = id;
		size_t base_size_ = base_size();
		auto find = [&](auto&& find, size_type k, size_type l, size_type r) -> int {
			if(l + 1 == r) {
				val = bi_func(val, data[k]);

				return (check(val) ? k - base_size_ : -1);
			}

			const size_type mid = (l + r) >> 1;
			if(mid <= left) return find(find, k << 1 ^ 1, mid, r);
			if(left <= l and !check(bi_func(val, data[k]))) {
				val = bi_func(val, data[k]);
				return -1;
			}

			const int left_ret = find(find, k << 1 ^ 0, l, mid);
			if(left_ret == -1) return find(find, k << 1 ^ 1, mid, r);
			return left_ret;
		};

		return find(find, 1, 0, base_size_); 
	}

	value_type operator[](const size_type& index) const {
		return data[index + base_size()];
	}
	const size_type size() const {
		return size_;
	}
	const bool empty() const {
		return data.empty();
	}
};

int main() {
	int n; scanf("%d", &n);
	std::vector<int> L(n), R(n), com;
	std::vector<std::pair<int, int>> X, Y;
	for(int i = 0; i < n; i++) {
		scanf("%d%d", &L[i], &R[i]);
		L[i]--;

		X.push_back({L[i], R[i]});
		Y.push_back({R[i], L[i]});
		com.push_back(L[i]);
		com.push_back(R[i]);
	}
	sort(begin(X), end(X)); sort(begin(Y), end(Y));
	sort(begin(com), end(com));
	com.push_back(1e9);
	com.erase(unique(begin(com), end(com)), end(com));

	auto ind = [&](i64 t) { return lower_bound(begin(com), end(com), t) - begin(com); };

	int N = com.size();
	auto f = [&](i64 a, i64 b) { return a + b; };	
	segment_tree<i64> A(N + 1, f, 0), B(N + 1, f, 0);

	int cnt = n;
	auto count = [&]() {
		int ok = 1, ng = N + 1;
		while(std::abs(ok - ng) > 1) {
			int mid = (ok + ng) >> 1;

			if(A.fold(0, mid) >= 0) ok = mid;
			else ng = mid;
		}
	//	cout << "[0, " << ok << "): " << B.fold(0, ok) << " " << cnt << endl;
		if(B.fold(0, ok) != cnt) return -1;

		int tmp = ok; ok = tmp, ng = -1;
		while(std::abs(ok - ng) > 1) {
			int mid = (ok + ng) >> 1;

			if(B.fold(0, mid + 1) == cnt) ok = mid;
			else ng = mid;
		}
	//	cout << com[ok] << " " << com[tmp] << endl;
		return com[tmp] - com[ok];
	};

//	for(auto v: com) cout << v << " "; cout << endl;

	int ans = 0;
	for(int loop = 0; loop < 2; loop++) {
		for(int i = 0; i < N + 1; i++) {
			A.change(i, 0);
			B.change(i, 0);
		}
		for(int i = 0; i < n; i++) {
			A.update(ind(R[i]), -1);

			B.update(ind(L[i]), 1);
			B.update(ind(R[i]), -1);
		}

		int tmp = 1 << 30, tan = 0; cnt = n;
		for(auto v: X) {
			int x = v.first, y = v.second;
			if(loop) std::swap(x, y);
			if(y <= tan or tmp <= x) break;

			tan = std::max(tan, x);
			tmp = std::min(tmp, y);
			A.update(ind(y), 1);
			B.update(ind(x), -1);
			B.update(ind(y), 1);
			cnt--;

	//		cout << "A: "; for(int i = 0; i < com.size(); i++) cout << A[i] << " "; cout << endl;
	//		cout << "B: "; for(int i = 0; i < com.size(); i++) cout << B[i] << " "; cout << endl;

			int malta = count();

		//	cout << loop << " " << x << " " << y << " " << tan << " " << tmp << " -> " << malta << endl;

			if(malta != -1) ans = std::max(ans, (tmp - tan) + malta);
		}

		X.swap(Y);
	}
	printf("%d\n", ans);
	return 0;
}

