const ll INF = 1LL << 60;
const int INF32 = 1 << 29;
const ll MOD = 998244353;

template<int MOD> struct Fp {
	long long val;
	Fp(long long v = 0) noexcept : val(v % MOD) {
		if (val < 0) v += MOD;
	}
	int getmod() { return MOD; }
	Fp operator - () const noexcept {
		return val ? MOD - val : 0;
	}
	Fp operator + (const Fp& r) const noexcept { return Fp(*this) += r; }
	Fp operator - (const Fp& r) const noexcept { return Fp(*this) -= r; }
	Fp operator * (const Fp& r) const noexcept { return Fp(*this) *= r; }
	Fp operator / (const Fp& r) const noexcept { return Fp(*this) /= r; }
	Fp& operator += (const Fp& r) noexcept {
		val += r.val;
		if (val >= MOD) val -= MOD;
		return *this;
	}
	Fp& operator -= (const Fp& r) noexcept {
		val -= r.val;
		if (val < 0) val += MOD;
		return *this;
	}
	Fp& operator *= (const Fp& r) noexcept {
		val = val * r.val % MOD;
		return *this;
	}
	Fp& operator /= (const Fp& r) noexcept {
		long long a = r.val, b = MOD, u = 1, v = 0;
		while (b) {
			long long t = a / b;
			a -= t * b; swap(a, b);
			u -= t * v; swap(u, v);
		}
		val = val * u % MOD;
		if (val < 0) val += MOD;
		return *this;
	}
	bool operator == (const Fp& r) const noexcept {
		return this->val == r.val;
	}
	bool operator != (const Fp& r) const noexcept {
		return this->val != r.val;
	}
	friend ostream& operator << (ostream &os, const Fp<MOD>& x) noexcept {
		return os << x.val;
	}
	friend istream& operator >> (istream &is, Fp<MOD>& x) noexcept {
		return is >> x.val;
	}
	friend Fp<MOD> modpow(const Fp<MOD> &a, long long n) noexcept {
		if (n == 0) return 1;
		auto t = modpow(a, n / 2);
		t = t * t;
		if (n & 1) t = t * a;
		return t;
	}
};

using mint = Fp<MOD>;

int main() {
	ll N; cin >> N;
	vector<pll> vec(N);
	for (int i = 0; i < N; ++i) cin >> vec[i].first >> vec[i].second;
	sort(vec.begin(), vec.end());

	ll L = N - 1;

	ll R = -1, tmp = INF;
	for (int i = 0; i < N; ++i) {
		if (tmp > vec[i].second) {
			R = i;
			tmp = vec[i].second;
		}
		else if (tmp == vec[i].second && vec[R].first < vec[i].first) {
			R = i;
		}
	}

	if (L == R) {
		// 最大区間と最小区間の和
		ll LONGEST = 0;
		for (int i = 0; i < N; ++i) LONGEST = max(LONGEST, vec[i].second - vec[i].first);
		ll SHORTEST = vec[R].second - vec[R].first;
		cout << LONGEST + SHORTEST + 2 << endl;
	}
	else {
		vector<ll> tR(N+1, INF);
		for (int i = N-1; i >= 0; --i) {
			tR[i] = min(tR[i + 1], vec[i].second);
		}

		ll ans = 0, tL = 0;
		for (int i = 0; i < N; ++i) {
			if (i == L || i == R)continue;
			tL = max(tL, vec[i].first);
			ll tmp = max(0LL, vec[R].second-tL) + max(0LL, tR[i+1] - vec[L].first);
			ans = max(ans, tmp);
		}
		cout << ans+2 << endl;
	}

	return 0;
}

