    using P = std::pair<ll, ll>;
    vector<P> q(N);
    for (int i = 0; i < N; i++) {
        ll l, r;
        cin >> l >> r;
        q[i] = std::make_pair(l, r);
    }
    std::sort(q.begin(), q.end());
    P p1, p2;
    p1 = q[0];
    p2 = q[N-1];
    ll c1, c2;
    c1 = std::max(p1.second - p1.first + 1, 0LL);
    c2 = std::max(p2.second - p2.first + 1, 0LL);
    ll ans = c1 + c2;
    for (int i = 1; i < N-1; i++) {
