        if (c1 - scr1 > c2 - scr2) {
            p2.first = std::max(p2.first, p.first);
            p2.second = std::min(p2.second, p.second);
        } else {
            p1.first = std::max(p1.first, p.first);
            p1.second = std::min(p1.second, p.second);
        }
        c1 = std::max(p1.second - p1.first + 1, 0LL);
        c2 = std::max(p2.second - p2.first + 1, 0LL);
        ans = c1 + c2;
    }

