struct LmaQ {
    int siz = 1;
    vector<int>dat;
    LmaQ(int n) {
        while (siz < n)siz *= 2;
        dat.resize(siz * 2 - 1, 0);
        rep(i, n)dat[i + siz - 1] = p[i].first;
        for (int i = siz - 2; i >= 0; i--)dat[i] = max(dat[i * 2 + 1], dat[i * 2 + 2]);
    }
    int query(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r == -1)r = siz;
        if (a <= l && r <= b)return dat[k];
        if (r <= a || b <= l)return 0;
        int vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
        int vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
        return max(vl, vr);
    }
};
struct RmiQ {
    int siz = 1;
    vector<int>dat;
    RmiQ(int n) {
        while (siz < n)siz *= 2;
        dat.resize(siz * 2 - 1, INF);
        rep(i, n)dat[i + siz - 1] = p[i].second;
        for (int i = siz - 2; i >= 0; i--)dat[i] = min(dat[i * 2 + 1], dat[i * 2 + 2]);
    }
    int query(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r == -1)r = siz;
        if (a <= l && r <= b)return dat[k];
        if (r <= a || b <= l)return INF;
        int vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
        int vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
        return min(vl, vr);
    }
};
