int getMin( int idArbre, int rLeft,int  rRight,int  qLeft,int  qRight){

	if( qRight<rLeft || rRight < qLeft ){ //intervalles disjoints
		return INF;
	}

	if( qLeft <= rLeft && rRight <= qRight ){
		return arbreMin[idArbre];
	}

	int milieu= (rLeft+rRight)/2;

	return min( getMin( 2*idArbre, rLeft, milieu, qLeft, qRight), getMin( 2*idArbre+1, milieu+1, rRight, qLeft, qRight));
}

int getMax( int idArbre, int rLeft,int  rRight,int  qLeft,int  qRight){

	if( qRight<rLeft || rRight < qLeft ){ //intervalles disjoints
		return -1;
	}

	if( qLeft <= rLeft && rRight <= qRight ){
		return arbreMax[idArbre];
	}

	int milieu= (rLeft+rRight)/2;

	return max( getMax( 2*idArbre, rLeft, milieu, qLeft, qRight), getMax( 2*idArbre+1, milieu+1, rRight, qLeft, qRight));
}


int joyfulness(int a,int b){

	return 1+getMin( 1, 0 , TMAX-1, a, b) - getMax( 1, 0 , TMAX-1, a, b);
}
