using namespace std;
typedef pair<int, int> P;

void solve() {
    int N;
    cin >> N;
    vector<P> ranges, A(N), B(N);

    for(int i = 0; i < N; ++i) {
        int l, r;
        cin >> l >> r;
        ++r;
        ranges.emplace_back(l, r);
    }
    sort(ranges.begin(), ranges.end());

    A[0] = ranges[0];
    for(int i = 1; i < N; ++i) {
        A[i] = ranges[i];
        A[i].second = min(A[i].second, A[i - 1].second);
    }

    B[N - 1] = ranges[N - 1];
    for(int i = N - 2; i >= 0; --i) {
        B[i] = ranges[i];
        B[i].first = max(B[i].first, B[i + 1].first);
        B[i].second = min(B[i].second, B[i + 1].second);
    }

    int ans = 0;
    for(int i = 1; i < N - 1; ++i) {
        int l = max(A[i - 1].first, B[i + 1].first);
        int r = min(A[i - 1].second, B[i + 1].second);
        int score = ranges[i].second - ranges[i].first + max(0, r - l);
        ans = max(ans, score);
    }

    for(int i = 0; i < N - 1; ++i) {
        int scoreA = max(0, A[i].second - A[i].first);
        int scoreB = max(0, B[i + 1].second - B[i + 1].first);
        ans = max(ans, scoreA + scoreB);
    }

    cout << ans << '\n';
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    solve();
    return 0;
}

