        ll resTmp2 = 0;
        resTmp2 += max(min(r2, rMin)- l2 + 1, 0LL);
        resTmp2 += max(r1 - l1 + 1, 0LL);

        res = max(res, max(resTmp1, resTmp2));

        rMin = min(rMin, r1);
    }

    cout << res << endl;


    return 0;
}

