struct Seg {
  int l , r;
  Seg() {} Seg( int l , int r ):l( l ) , r( r ) {}
  bool operator < ( const Seg & rhs ) const { return l < rhs.l; }
  Seg operator ^ ( const Seg & rhs ) const { return Seg( max( l , rhs.l ) , min( r , rhs.r ) ); }
  int length( void ) { return max( 0 , r - l + 1 ); }
} dat[N] , pre[N] , suf[N];

