  pre[0] = suf[n + 1] = Seg( 0 , 1e9 );
  for( int i = 1 ; i <= n ; ++i ) pre[i] = pre[i - 1] ^ dat[i];
  for( int i = n ; i ; --i ) suf[i] = suf[i + 1] ^ dat[i];
  for( int i = 1 ; i <= n ; ++i )
