            maxL_idx = i;
        }

        if (R[minR_idx] > R[i] || (R[i] == R[minR_idx] && L[i] > L[minR_idx])) {
            minR_idx = i;
        }
    }

    ll ans = max(R[minR_idx] - L[maxL_idx] + 1, 0LL);
    {
        ll tmp = 0;
        for (int i = 0; i < n; i++) {
            if (i == minR_idx || i == maxL_idx) continue;
            tmp = max(tmp, R[i] - L[i] + 1);
        }
        ans += tmp;
    }

    if (minR_idx == maxL_idx) {
        cout << ans << "\n";
        return 0;
    }

    ll L1 = L[minR_idx], R1 = R[minR_idx], L2 = L[maxL_idx], R2 = R[maxL_idx];
    for (int i = 0; i < n; i++) {
        if (i == minR_idx || i == maxL_idx) continue;
        ll nex_L1 = max(L1, L[i]);
        ll nex_R1 = min(R1, R[i]);
        ll diff1 = max(R1 - L1 + 1, 0LL) - max(nex_R1 - nex_L1 + 1, 0LL);

        ll nex_L2 = max(L2, L[i]);
        ll nex_R2 = min(R2, R[i]);
        ll diff2 = max(R2 - L2 + 1, 0LL) - max(nex_R2 - nex_L2 + 1, 0LL);
        if (diff1 < diff2) {
            L1 = nex_L1;
            R1 = nex_R1;
        } else {
            L2 = nex_L2;
            R2 = nex_R2;
        }
    }
    ans = max(ans, max(R1 - L1 + 1, 0LL) + max(R2 - L2 + 1, 0LL));
    cout << ans << "\n";
    return 0;
}

