using namespace std;

#define MAXN 100000
#define l first
#define r second

int n;
pair<int,int> a[MAXN];

int input() {
	if (scanf("%d", &n) < 0) return 0;
	for (int i=0; i<n; i++) {
		scanf("%d %d", &a[i].l, &a[i].r);
		a[i].r++;
	}
	return 1;
}

void init() {
}

long solve() {
	long ans = 0;
	for (int i=0; i<n; i++) {
		int d = a[i].r - a[i].l;
		if (d > ans) {
			ans = d;
		}
	}
	int maxl = INT_MIN, minr = INT_MAX;
	for (int i=0; i<n; i++) {
		maxl = max(maxl, a[i].l);
		minr = min(minr, a[i].r);
	}
	ans += max(0, minr - maxl);

	sort(a, a+n);
	int rx = INT_MAX;
	for (int i=n-1; i>0; i--) {
		rx = min(rx, a[i].r);
		long t = (long)max(0, rx-maxl) + max(0,minr-a[i-1].l);
		ans = max(ans, t);
	}
	return ans;
}

void output(long ans) {
	printf("%ld\n", ans);
}

void cleanup() {
}

int main() {
	//int ca; scanf("%d", &ca);
	while (input()) {
		init();
		output(solve());
		cleanup();
		//break;
	}
}

