    SegmentTree<int> Lmax(lmax, -INF, [](int a, int b) { return max(a, b); });
    SegmentTree<int> Rmin(rmin, INF, [](int a, int b) { return min(a, b); });
    for(int i = 0; i < n; i++) {
        Lmax.update(i, LR[i].first);
        Rmin.update(i, LR[i].second);
    }

