const int inf = 0x3fffffff; const ll INF = 0x3fffffffffffffff;
//template end

template<typename M,typename O=M>struct SegmentTree{
    using F=function<M(M,M)>; using G=function<M(M,O)>;
    int sz; vector<M> data; const F f; const G g; const M m1;
    SegmentTree(int n,const F f,const G g,const M &m1):f(f),g(g),m1(m1){
        sz=1; while(sz<n)sz<<=1; data.assign(2*sz,m1);
    }
    void build(vector<M> v){
        rep(i,0,v.size())data[i+sz]=v[i];
        rrep(k,sz-1,0)data[k]=f(data[2*k],data[2*k+1]);
    }
    void update(int k,const O &x){
        k+=sz; data[k]=g(data[k],x);
        while(k>>=1)data[k]=f(data[2*k],data[2*k+1]);
    }
    M query(int a,int b){
        M L=m1,R=m1;
        for(a+=sz,b+=sz;a<b;a>>=1,b>>=1){
            if(a&1)L=f(L,data[a++]);
            if(b&1)R=f(data[--b],R);
        } return f(L,R);
    }
    M operator[](const int &k)const{return data[k+sz];}
};

int main(){
    int n; scanf("%d",&n);
    vector<P> r(n);
    rep(i,0,n)scanf("%d%d",&r[i].first,&r[i].second),r[i].first--;
    int lmax=0,idx,rmin=inf,idx2;
    rep(i,0,n){
        if(chmax(lmax,r[i].first))idx=i;
        if(chmin(rmin,r[i].second))idx2=i;
    }
    if(idx==idx2){
        int rangemax=0;
        rep(i,0,n)if(i!=idx)chmax(rangemax,r[i].second-r[i].first);
        printf("%d\n",rangemax+max(0,rmin-lmax));
        return 0;
    }
    sort(ALL(r));
    SegmentTree<int> minn(n,
    [](int a,int b){return min(a,b);},[](int a,int b){return b;},inf);
    rep(i,0,n)minn.update(i,r[i].second);
    int ans=0;
    rep(i,0,n-1){
        int lmax2=r[i].first,rmin2=minn.query(i+1,n);
        cerr<<lmax2<<rmin2<<endl;
        chmax(ans,max(0,rmin-lmax2)+max(0,rmin2-lmax));
    }
    printf("%d\n",ans);
    return 0;
}

