const ll MOD = 1e9+7;

class SegmentTree{
    int n;
    vector<ll> node;
    bool mx;

    public:
    SegmentTree(vector<ll> v, bool mxmx){
        mx = mxmx;
        int sz = v.size();
        n = 1;
        while(sz > n) n *= 2;
        node.resize(2*n-1);

        for(int i = 0; i < sz; i++)
            node[i+n-1] = v[i];
        for(int i = n-2; i >= 0; i--){
            if(mx)
                node[i] = max(node[2*i+1], node[2*i+2]);
            else
                node[i] = min(node[2*i+1], node[2*i+2]);
        }
    }

    void update(int x, ll val){
        x += n-1;
        node[x] = val;
        while(x > 0){
            x = (x-1) / 2;
            if(mx)
                node[x] = max(node[2*x+1], node[2*x+2]);
            else
                node[x] = min(node[2*x+1], node[2*x+2]);
        }
    }

    ll getval(int a, int b, int k=0, int l=0, int r=-1){
        if(r < 0)
            r = n;

        if(r <= a || b <= l){
            if(mx) return 0;
            else return 1e12;
        }

        if(a <= l && r <= b)
            return node[k];

        ll lval = getval(a, b, 2*k+1, l, (l+r)/2);
        ll rval = getval(a, b, 2*k+2, (l+r)/2, r);
        if(mx) return max(lval, rval);
        else return min(lval, rval);
    }
};

int main(){
    ll N;
