    vector<ll> L;
    vector<ll> R;
    REP(i,N){
        ll l, r;
        scanf("%lld %lld", &l, &r);
        LR[i] = mp(l, -r);
    }

    sort(LR.begin(), LR.end());

    for(auto&& p : LR){
        L.push_back(p.first);
        R.push_back(-p.second);
    }

    SegmentTree treeL(L, true);
    SegmentTree treeR(R, false);

    ll maxl1 = -1;
    ll minr1 = 1e10;
    ll ans = 0;
    REP(i,N-1){
        ll tmp = 0;
        auto p = LR[i];
        chmax(maxl1, p.first);
        chmin(minr1, -p.second);

        ll maxl2 = treeL.getval(i+1, N);
        ll minr2 = treeR.getval(i+1, N);

        tmp = max(0LL, minr1-maxl1+1) + max(0LL, minr2-maxl2+1);
        chmax(ans, tmp);
    }

    REP(i,N){
        ll tmp = 0;
        auto p = LR[i];
        ll maxl1 = p.first;
        ll minr1 = -p.second;

        ll maxl2, minr2;
        maxl2 = treeL.getval(0, i);
        chmax(maxl2, treeL.getval(i+1, N));

        minr2 = treeR.getval(0, i);
        chmin(minr2, treeR.getval(i+1, N));

        tmp = max(0LL, minr1-maxl1+1) + max(0LL, minr2-maxl2+1);
        chmax(ans, tmp);
    }

    cout << ans << endl;
    return 0;
}

