int n,res,st[N],ins[N],top;pi a[N],Pre[N],suf[N];
inline pi operator +(const pi &a,const pi &b){return pi(max(a.fi,b.fi),min(a.se,b.se));}
inline int Len(const pi &b){return max(b.se-b.fi+1,0);}
int main(){
//	freopen("testdata.in","r",stdin);
    scanf("%d",&n);
