ll N;
ll L[100010], R[100010];
ll maL, miR = INF;
ll li, ri;
std::vector<P> ps;
ll right[100010];

int main()
{
  std::cin >> N;

  rep( i, N )
  {
    std::cin >> L[i] >> R[i];

    if( chmax( maL, L[i] ) )
      li = i;
    if( chmin( miR, R[i] ) )
      ri = i;

    ps.emplace_back( L[i], R[i] );
  }

  if( li == ri )
  {
    ll ans = 0;

    rep( i, N ) if( i != li )
      chmax( ans, R[i]-L[i]+1 );

    ans += R[li]-L[li]+1;

    std::cout << ans << std::endl;

    return 0;
  }

  std::sort( all(ps) );

  right[N] = INF;

  repd( i, N )
    right[i] = std::min( right[i+1], ps[i].second );

  ll l = L[ri];
  ll ans = 0;

  rep( i, N )
  {
    chmax( ans, miR-l+1+right[i]-maL+1 );
    chmax( l, ps[i].first );
  }

  std::cout << ans << std::endl;

  return 0;
}

