int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.precision(10);
    cout << fixed;

    ll n;
    cin >> n;
    ll maxl = 0, minr = 1e9;
    ll mxsz = 0;
    for(ll i=1; i<=n; i++){
        cin >> niz[i].l >> niz[i].r;
        mxsz = max(mxsz, niz[i].r-niz[i].l+1);
        maxl = max(niz[i].l, maxl);
        minr = min(niz[i].r, minr);
    }
    for(ll i=1; i<=n; i++){
        if(maxl == niz[i].l && minr == niz[i].r){
            cout << mxsz + minr-maxl+1;
            return 0;
        }
    }
    ll a=0, b=0;
    for(ll i=1; i<=n; i++){
        if(minr == niz[i].r && (b == 0 || niz[b].l > niz[i].l)){
            b = i;
        }
    }
    drugir.insert({-niz[b].l, niz[b].r});
    for(ll i=1; i<=n; i++){
        if(i != b){
            prvir.insert({niz[i].r, niz[i].l});
            prvil.insert({niz[i].l, niz[i].r});
        }
    }
    ll l2 = -drugir.begin()->first;
    ll r1 = prvir.begin()->first;
