void drop(T a);

bool compare(PL a, PL b) {
  if (a.first == b.first) return a.second > b.second;
  return a < b;
}

void solve() {
  ll N;
  cin >> N;

  ll max_l = 0;
  ll min_r = 1e18;

  VPL originals(N);
  rep(i, N) {
    ll l, r;
    cin >> l >> r;
    // [l, r)
    r++;
    originals[i] = {l, r};
    chmax(max_l, l);
    chmin(min_r, r);
  }

  ll res = 0;

  // max_l, min_r を与えるものを同一グループにするケース
  {
    ll max_range =0;
    rep(i, N) {
      auto p = originals[i];
      chmax(max_range, p.second - p.first);
    }

    chmax(res, min_r - max_l + max_range);
  }

  // max_l, min_r を与えるものを同一グループにしないケース
  {
    VPL ps(N);  // f: max(r_i - max_l, 0), s: max(min_r - l_i, 0)

    rep(i, N) {
      ps[i] = {
          max(originals[i].second - max_l, 0ll),
          max(min_r - originals[i].first, 0ll),
      };
    }

    sort(ps.begin(), ps.end(), compare);

    multiset<ll> b_firsts;
    for (auto p : ps) b_firsts.insert(p.first);

    ll a_min_second = 1e18;

    rep(i, N - 1) {
      PL new_a = ps[i];

      chmin(a_min_second, new_a.second);

      b_firsts.erase(new_a.first);
      ll b_min_first = *b_firsts.begin();

      chmax(res, a_min_second + b_min_first);
    }
  }

  cout << res << endl;
}

