template<typename T>
struct Segtree {
    int n;
    T e;
    vector<T> dat;
    typedef function<T(T a, T b)> Func;
    Func f;

    Segtree(){}
    Segtree(int n_input, Func f_input, T e_input){
        initialize(n_input, f_input, e_input);
    }
    void initialize(int n_input, Func f_input, T e_input){
        f = f_input;
        e = e_input;
        n = 1;
        while(n < n_input) n <<= 1;
        dat.resize(2*n-1, e);
    }

    void update(int k, T a){
        k += n - 1;
        dat[k] = a;
        while(k > 0){
            k = (k - 1)/2;
            dat[k] = f(dat[2*k+1], dat[2*k+2]);
        }
    }

    T get(int k){
        return dat[k+n-1];
    }

    T between(int a, int b){
        return query(a, b+1, 0, 0, n);
    }

    T query(int a, int b, int k, int l, int r){
        if(r<=a || b<=l) return e;
        if(a<=l && r<=b) return dat[k];
        T vl = query(a, b, 2*k+1, l, (l+r)/2);
        T vr = query(a, b, 2*k+2, (l+r)/2, r);
        return f(vl, vr);
    }
};

int main(){
    int N;
    cin >> N;
    vector<pair<int, int>> LR(N);
    for(int i=0; i<N; i++) {
        int l, r;
        cin >> l >> r;
        LR[i] = {l, r};
    }
    sort(LR.begin(), LR.end());

    Segtree<int> Lmax(N, [](int a, int b){ return max(a, b); }, -1e9);
    Segtree<int> Rmax(N, [](int a, int b){ return max(a, b); }, -1e9);
    Segtree<int> Lmin(N, [](int a, int b){ return min(a, b); }, 1e9);
    Segtree<int> Rmin(N, [](int a, int b){ return min(a, b); }, 1e9);
    for(int i=0; i<N; i++){
        Lmax.update(i, LR[i].first);
        Lmin.update(i, LR[i].first);
        Rmax.update(i, LR[i].second);
        Rmin.update(i, LR[i].second);
    }
    int ans = 0;
    for(int i=0; i<N; i++){
        int res1 = LR[i].second - LR[i].first + 1;
        int r2 = min(Rmin.between(0, i-1), Rmin.between(i+1, N-1));
        int l2 = max(Lmax.between(0, i-1), Lmax.between(i+1, N-1));
        int res2 = max(0, r2-l2+1);
        ans = max(ans, res1 + res2);
    }
    for(int i=1; i<N; i++){
        int res1 = Rmin.between(0, i-1) - Lmax.between(0, i-1) + 1;
        int res2 = Rmin.between(i, N-1) - Lmax.between(i, N-1) + 1;
        int res = max(0, res1) + max(0, res2);
        ans = max(ans, res);
    }
    cout << ans << endl;
    return 0;
}

