inline int calc_len(const pii &x) {
    return x.second - x.first + 1;
}

bool cmp1(const pii &lhs, const pii &rhs) {
    return (calc_len(lhs) == calc_len(rhs)) ? lhs.first < rhs.first : calc_len(lhs) > calc_len(rhs);
}

bool cmp2(const pii &lhs, const pii &rhs) {
    return (calc_len(lhs) == calc_len(rhs)) ? lhs.second > rhs.second : calc_len(lhs) > calc_len(rhs);
}

inline int calc_cost(const pair<pii, pii> &asc) {
    return max(0,  calc_len(asc.first)) + max(0, calc_len(asc.second));
}

inline pii intersect(const pii &x, const pii &y) {
    return make_pair(max(x.first, y.first), min(x.second, y.second));
}

