    sort(ALL(sec), cmp1);
    asc.first = sec[0];
    sec.erase(sec.begin());
    sort(ALL(sec), cmp2);
    asc.second = sec[0];
    sec.erase(sec.begin());
    REP(i, n - 2) {
        auto cnd1 = asc;
        auto cnd2 = asc;
        cnd1.first = intersect(cnd1.first, sec[i]);
        cnd2.second = intersect(cnd2.second, sec[i]);
        if(calc_cost(cnd1) > calc_cost(cnd2)) asc = cnd1;
        else asc = cnd2;
    }

    cout << calc_cost(asc) << "\n";

    return 0;
}

