struct Conj{
	ll l, r;
	bool empty;
	void build(){
		empty=1;
	}
	ll check(ll _l,ll _r){
		if( empty) return _r-_l+1;
		return min(r,_r) - max(l,_l) +1;
	}
	void add(ll _l, ll _r){
		if(empty){
			empty=0;
			l=_l;
			r=_r;
		}else{
			l = max(l,_l);
			r = min(r, _r);
		}
	}
	ll tam(){
		if(empty) return -INF;
		return r-l+1;
	}
} dp[2][2];

