int n;
int l[125252], r[125252];
pii ranges[125252];
pii lsum[125252], rsum[125252];

set<pii> sl, sr;
set<pii> tl, tr;
int calc(){
	int ret = (sr.begin()->first - sl.rbegin()->first + 1);
	ret += (tr.begin()->first - tl.rbegin()->first + 1);
	return ret;
}

int main(){
	scanf("%d",&n);
	REP(i,n)scanf("%d%d",l+i,r+i);
	// 区間 [li, ri] が N 個与えられる
	// この非空2分割であって、|∩ a| + |∩ b| を最大化せよ
	// 性質: 連結なので連結の∩は連結
	// 最小の長さを minlen とすればどちらかは必ず minlen 以下になる
	// -> 片方が minlen 以下として、もう片方を最大化する問題？
	// 自明な下界: maxlen + 0
	// 自明な上界: maxlen + minlen
	// Sから要素(l,r)を抜くと
	// min(r)-max(l)+1
	// (min(r)==r ? min2(r) : min(r)) - (max(r)==r ? max2(r) : max(r)) + 1
	int mxlenid = 0;
	FOR(i,1,n)if(r[i]-l[i] > r[mxlenid]-l[mxlenid]){
		mxlenid = i;
	}

	int ans = 0;
	REP(i,n)if(i != mxlenid)sl.insert(pii(l[i],i));
	REP(i,n)if(i != mxlenid)sr.insert(pii(r[i],i));
	tl.insert(pii(l[mxlenid],mxlenid));
	tr.insert(pii(r[mxlenid],mxlenid));
	ans = calc();
	while(sl.size() >= 2){
		vi cands;
		cands.push_back(sl.rbegin()->second);
		cands.push_back(sr.begin()->second);
		int bestid = -1;
		int bestval = -1;
		for(int id : cands){
			sl.erase(pii(l[id],id));
			sr.erase(pii(r[id],id));
			tl.insert(pii(l[id],id));
			tr.insert(pii(r[id],id));
			int val = calc();
			if(val > bestval){
				bestval = val;
				bestid = id;
			}
			sl.insert(pii(l[id],id));
			sr.insert(pii(r[id],id));
			tl.erase(pii(l[id],id));
			tr.erase(pii(r[id],id));
		}
		{
			int id = bestid;
			sl.erase(pii(l[id],id));
			sr.erase(pii(r[id],id));
			tl.insert(pii(l[id],id));
			tr.insert(pii(r[id],id));
			CHMAX(ans, calc());
		}
	}
	printf("%d\n",ans);
	return 0;
}

