typedef pair < int , int > pii ;
typedef pair < long long  , long long > pll ;

const int N = 2e5 + 123;

int n , m , k , q , sf[N];
pii p[N];
int ans = 0;
void flex(){
	int MxL = 0 , MnR = 2e9;
	for(int i = n; i >= 1 ; i--){
		MxL = max(p[i].fi , MxL);
		MnR = min(p[i].se , MnR);
		sf[i] = max(MnR - MxL + 1 , 0ll);
	}
	int MinR = 2e9 ;
	for(int i = 1; i <= n; i++){
		MinR = min(MinR , p[i].se);
		if(p[i].fi > MinR)
			break;
		int cur = MinR - p[i].fi + 1;
		cur += sf[i + 1];
		ans = max(ans , cur);
	}
}
main(){
	ios_base::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	cin >> n;
	for(int i = 1; i <= n ; i++){
		cin >> p[i].fi >> p[i].se;
		ans = max(p[i].se - p[i].fi + 1, ans);
	}
	sort(p + 1, p + 1 + n);
	flex();
	for(int i = 1; i <= n ; i++){
		p[i].se = -p[i].se;
	}
	sort(p + 1 , p + 1 + n);
	for(int i = 1; i <= n; i++)
		p[i].se = -p[i].se;
	flex();
	for(int i = 1 ; i <= n; i++){
		p[i].fi = 1e9 - p[i].fi + 1;
		p[i].se = 1e9 - p[i].se + 1;
		swap(p[i].fi,p[i].se);
	}	
	sort(p + 1, p + 1 + n);
	flex();
	for(int i = 1; i <= n; i++)
		p[i].se = -p[i].se;
	sort(p + 1, p + 1 + n);
	for(int i = 1; i <= n; i++)
		p[i].se = -p[i].se;

	flex();
	cout << ans;

}

