    }
    for(int i=1; i<=n; i++){
        if(maxl == niz[i].l && minr == niz[i].r){
            cout << mxsz + max(0, minr-maxl+1);
            return 0;
        }
    }
    int a=0, b=0;
    for(int i=1; i<=n; i++){
        if(minr == niz[i].r && (b == 0 || niz[b].l < niz[i].l)){
            b = i;
        }
        if(maxl == niz[i].l && (a == 0 || niz[a].r > niz[i].l)){
            a = i;
        }
    }
    int mx1 = 0;
    for(int i=1; i<=n; i++){
        if(i != a && i != b) mx1 = max(mx1, niz[i].r - niz[i].l+1);
    }
