                prvir.insert({niz[i].r, niz[i].l});
                prvil.insert({niz[i].l, niz[i].r});
            }
            else{
                drugir.insert({-niz[i].l, niz[i].r});
            }
        }
    }
    int l2 = -drugir.begin()->first;
    int r1 = prvir.begin()->first;
    int l1 = prvil.rbegin()->first;
    res = max(res, max(0, minr-l2+1)+max(0, r1-l1+1));
    while(prvil.size() > 1){
        pair <int, int> pii = *prvil.begin();
        prvil.erase(prvil.find(pii));
        prvir.erase(prvir.find({pii.second, pii.first}));
