int n;
vector<ii> range;
multiset<int> mina,maxa,minb,maxb;
int main(){
    scanf("%d",&n);
    int a,b;
    int ans=0;
    for (int x=0;x<n;x++){
        scanf("%d%d",&a,&b);
        range.push_back(ii(a,b));
        mina.insert(a);
        maxa.insert(b);
    }

    for (vector<ii>::iterator it=range.begin();it!=range.end();it++){
        mina.erase(mina.find((*it).first));
        maxa.erase(maxa.find((*it).second));
        ans=max(ans,(*it).second-(*it).first+1);
        mina.insert((*it).first);
        maxa.insert((*it).second);
    }

    sort(range.begin(),range.end(),[](ii i,ii j){
        return i.first+i.second<j.first+j.second;
    });

    while (range.size()!=1){
        minb.insert(range.back().first);
        maxb.insert(range.back().second);
        mina.erase(mina.find(range.back().first));
        maxa.erase(maxa.find(range.back().second));
        range.pop_back();
        ans=max(ans,max(0,*maxa.begin()-*mina.rbegin()+1)+max(0,*maxb.begin()-*minb.rbegin()+1));
    }

    printf("%d\n",ans);
}

