ll calc(const vPll &lr, int N) {
    ll ret = 0;
    repr(i, 1, (1 << N) - 1) {
        ll ans = 0;
        ll ma = 0, mi = INFL;
        rep(j, N) {
            if ((i & (1 << j)) != 0) {
                chmin(mi, lr[j].second);
                chmax(ma, lr[j].first);
            }
        }
        ans += max(0LL, mi - ma + 1);

        ma = 0, mi = INFL;
        rep(j, N) {
            if ((i & (1 << j)) == 0) {
                chmin(mi, lr[j].second);
                chmax(ma, lr[j].first);
            }
        }
        ans += max(0LL, mi - ma + 1);
        chmax(ret, ans);
    }
    return ret;
}

int main(void) {
    int N;
    cin >> N;
    vPll LR(N);
    vll left(N + 1, 0), right(N + 1, 0);
    vll maxLleft(N + 1, 0), minRleft(N + 1, INF);
    vll maxLright(N + 1, 0), minRright(N + 1, INF);

    rep(i, N) {
        ll l, r;
        cin >> l >> r;
        LR[i] = mp(l, r);
    }

    sort(all(LR));
    dump(LR);

    rep(i, N) {
        maxLleft[i + 1] = max(maxLleft[i], LR[i].first);
        minRleft[i + 1] = min(minRleft[i], LR[i].second);
    }
    reprev(i, N) {
        maxLright[i] = max(maxLright[i + 1], LR[i].first);
        minRright[i] = min(minRright[i + 1], LR[i].second);
    }

    dump(maxLleft);
    dump(minRleft);
    dump(maxLright);
    dump(minRright);

    ll ma = 0;
    ll mi = INFL;
    rep(i, N) {
        chmin(mi, LR[i].second);
        chmax(ma, LR[i].first);
        left[i + 1] = max(0LL, mi - ma + 1);
    }

    ma = 0;
    mi = INFL;
    reprev(i, N) {
        chmin(mi, LR[i].second);
        chmax(ma, LR[i].first);
        right[i] = max(0LL, mi - ma + 1);
    }

    dump(left);
    dump(right);

    ll ans = 0;
    repr(i, 1, N) {
        chmax(ans, left[i] + right[i]);
    }
    rep(i, N) {
        dump(i, LR[i].second - LR[i].first + 1,
             max(0LL, min(minRleft[i], minRright[i + 1]) -
                          max(maxLleft[i], maxLright[i + 1]) + 1));
        chmax(ans, LR[i].second - LR[i].first + 1 +
                       max(0LL, min(minRleft[i], minRright[i + 1]) -
                                    max(maxLleft[i], maxLright[i + 1]) + 1));
    }
    cout << ans << endl;

    // cout << calc(LR, N) << endl;

    return 0;
}

