    for(int i = 0; i < N; i++){
      a[i] = {max(R[i]-Lp,0LL),i};
    }


    // min{a[i]}(i∈S) + min{b[i]}(i∈T)を最大化する　ただしS,Tは{1,2,,,,N}の分割

