  memo[current_pair.first] = current_pair;
  for (long i = 1; i < RL.size(); i++) {
    auto xxx = RL[i];
    pair<long, long> next_pair = make_pair(min(current_pair.first, xxx.first), max(current_pair.second, xxx.second));
