        L2[i] = std::max(L[I[i]], L2[i+1]);
        R2[i] = std::min(R[I[i]], R2[i+1]);
    }

    int64_t zero = 0;

    int64_t ll=L[I[0]], rr=R[I[0]];
    result = std::max(zero, rr-ll+1) + std::max(zero, R2[1]-L2[1]+1);
    for (int i=1;i<n-1;++i)
    {
        // std::clog << ll << " : " << rr << "     " << L2[i+1] << " : " << R2[i+1] << std::endl;
        ll = std::max(L[I[i]], ll);
        rr = std::min(R[I[i]], rr);
        result = std::max(result, std::max(zero, rr-ll+1) + std::max(zero, R2[i+1]-L2[i+1]+1));
    }
    // std::clog << ll << " : " << rr << "     " << L2[n-1] << " : " << R2[n-1] << std::endl;
    std::cout << result;
    return 0;
}

