struct UnionFind{
    int size;
    vector<int> par;
    vector<int> rank;
    UnionFind(int x){
        size=x;
        par=vector<int> (x);
        rank=vector<int> (x,1);
        for (int i=0;i<x;i++){
            par[i]=i;
        }
    }
    int root(int x){
        if(par[x]==x){
            return x;
        }
        else{
            return par[x]=root(par[x]);
        }
    }
    void unite(int x,int y){
        x=root(x);y=root(y);
        if(x==y){
            return;
        }
        if(rank[x]<rank[y]){
            par[x]=y;
        }
        else{
            par[y]=x;
        }
        if(rank[x]==rank[y]){
            rank[x]++;
        }
    }
    bool check(int x,int y){
        return root(x)==root(y);
    }
    void initialize(){
        for (int i=0;i<size;i++){
            par[i]=i;
            rank[i]=1;
        }
    }
};
struct SegTree{ //0indexed
    vector<int> nod;
    int size;
    SegTree(int x){
        size=1;
        while(x>size){
            size*=2;
        }
        nod=vector<int>(size*2-1,0);
    }
    void update(int k,int a){
        k+=size-1;
        nod[k]+=a;//最下の処理
        while(k>0){
            k=(k-1)/2;
            nod[k]+=a; //下から上へ 
        }
    }
    int query(int a,int b,int k,int l,int r){
        //[a,b)について
        //kは節点の番号,[l,r)はその節点がカバーする範囲
        if(r<=a||b<=l){ //[a,b)と[l,r)が重なって無いとき
            return 0;
        }
        if(a<=l && r<=b){ //[a,b)が[l,r)を完全に含んでいるとき
            return nod[k];
        }
        else{
            return query(a,b,k*2+1,l,(l+r)/2)+query(a,b,k*2+2,(l+r)/2,r);
        }
    }
    void deb(){ //全ノードの出力
		for(int i=0;i<size*2-1;i++){
			if(i==size*2-2){
				cout << nod[i] << endl;
			}
			else{
				cout << nod[i] << ' ';
			}
		}
		return;
	}
};
struct BIT{
    vector<long long> li;
    int size;
    BIT (int n){
        li=vector<long long>(n+1,0);
        size=n;
    }
    long long sum (int i){
        long long s=0;
        while(i>0){
            s+=li[i];
            i-=i & -i;
        }
        return s;
    }
    void add(int i,long long x){
        while(i<=size){
            li[i]+=x;
            i+=i & -i;
        }
    }
};
struct complex{ //except for (0,0)
    double real;
    double imag;
    complex (double x,double y){
        real=x;
        imag=y;
    }
    double dist(){
        return sqrt(real*real+imag*imag);
    }
};
complex operator+(const complex &x,const complex &y){
    return complex(x.real+y.real,x.imag+y.imag);
}
complex operator-(const complex &x,const complex &y){
    return complex(x.real-y.real,x.imag-y.imag);
}
complex operator*(const complex &x,const complex &y){
    return complex(x.real*y.real-x.imag*y.imag,x.real*y.imag+x.imag*y.imag);
}
complex operator*(const complex &x,const double y){
    return complex(x.real*y,x.imag*y);
}
complex operator/(const complex &x,const double &y){
    return x*(1/y);
}
complex operator/(const complex &x,const complex &y){
    complex ret(y.real,-y.imag);
    double div=ret.dist();
    ret=x*ret;
    return ret/div;
}
bool operator>(const complex &x,const complex &y){//偏角、絶対値の順で
    if (x.imag==0 && y.imag==0){
        return x.real<y.real;
    }
    else if (x.imag==0 && y.imag>0){
        return x.real<0;
    }
    else if (x.imag==0 && y.imag<0){
        return false;
    }
    else if (x.imag>0 && y.imag==0){
        return y.real > 0;
    }
    else if (x.imag<0 && y.imag==0){
        return true;
    }
    else if(x.imag*y.imag>0){
        return y.real/y.imag > x.real/x.imag;
    }
    else if(x.imag*y.imag<0){
        return x.imag<y.imag;
    }
}
