      //[a,b]が[c,d]に含まれるので[c,d]を消す
      LR2.pop_back();
    }
  }
  if (LR2.size()==1){
    cout << MaxLen + MinLen;
  } else {
    int M = LR2.size();
    int Max = 0;
    for (int i = 0; i < M-1; i++){
      Max = max(Max,LR2[0].second-LR2[i].first+1+LR2[i+1].second-LR2[M-1].first+1);
    }
    cout << max(Max,MaxLen);
  }
}

