  for (int i = 0; i < n; ++i) {
    scanf("%lld %lld", &(l[i]), &(r[i]));
    // max_l = max(max_l, l[i]);
    // min_r = min(min_r, r[i]);
  }

  int max_l_ind = 0;
  int min_r_ind = 0;

  for (int i = 1; i < n; ++i) {
    if (l[i] > l[max_l_ind]) max_l_ind = i;
    if (r[i] < r[min_r_ind]) min_r_ind = i;
  }

  if (n == 2) {
    ll ans = -1L;
    // ll ans = max(r[min_r_ind] - l[max_l_ind] + 1L, 0LL);
    printf("%lld\n", ans);
    return 0;
  }

  ll ans = 0L;

  // for case that a part of group is singleton
  for (int i = 0; i < n; ++i) {
    if (i == min_r_ind || i == max_l_ind) continue;

    ans = max(ans, max(r[min_r_ind] - l[max_l_ind] + 1, 0LL) + r[i] - l[i] + 1L);
  }

  vector<pair<ll, ll>> p;

  for (int i = 0; i < n; ++i) {
    if (i == min_r_ind || i == max_l_ind) continue;

    pair<ll, ll> tmp;

    tmp.first = max(r[min_r_ind] - l[i] + 1L, 0LL);   // first: fixed right
    tmp.second = max(r[i] - l[max_l_ind] + 1L, 0LL);  // second: fixed left

    p.push_back(tmp);
  }

  ll score_fixed_right = r[min_r_ind] - l[min_r_ind] + 1L;
  ll score_fixed_left = r[max_l_ind] - l[max_l_ind] + 1L;

  sort(p.begin(), p.end(), cmp);

  ans = max(ans, score_fixed_left + p[0].first);

  for (int i = 0; i < p.size(); ++i) {
    ans = max(ans, p[i].second);
  }

  ll part = p[0].second;
  for (int i = 1; i < p.size(); ++i) {
    ans = max(ans, part + p[i].first);
    part = min(part, p[i].second);
  }

  ans = max(ans, score_fixed_right + part);

  printf("%lld\n", ans);

  return 0;
}

