int range(int l, int r) {
    if (l > r) {
        return 0;
    } else {
        return r - l + 1;
    }
}

int range_and(int l1, int r1, int l2, int r2) {
    if (l1 > r1 && l2 > r2) {
        return 0;
    } else if (l1 > r1) {
        return range(l2, r2);
    } else if (l2 > r2) {
        return range(l1, r1);
    } else {
        int r = min(r1, r2);
        int l = max(l1, l2);
        return range(l, r);
    }
}

