// 範囲 [l, r] のものを 1 問目、それ以外を 2 問目にした場合の
// 楽しさ
ll GetFun(ll l, ll r) {
    ll l_max[2] = { -LLINF, -LLINF };
    ll r_min[2] = { LLINF, LLINF };
    bool isValid[2] = {};

    for(auto& lr : LR) {
        if(l <= lr.first && lr.second <= r) {
            l_max[0] = max(l_max[0], lr.first);
            r_min[0] = min(r_min[0], lr.second);
            isValid[0] = true;
        }
        else {
            l_max[1] = max(l_max[1], lr.first);
            r_min[1] = min(r_min[1], lr.second);
            isValid[1] = true;
        }
    }

    ll ret1 = r_min[0] - l_max[0] + 1;
    if(!isValid[0] || ret1 < 0) { ret1 = 0; }
    ll ret2 = r_min[1] - l_max[1] + 1;
    if(!isValid[1] || ret2 < 0) { ret2 = 0; }

    return ret1 + ret2;
}

signed main() {
    cin.tie(0); cout.tie(0);
    ios::sync_with_stdio(false);

    cin >> N;

    ll l_min = LLINF;   // L の中で最小のもの
    ll r_max = -LLINF;  // R の中で最大のもの

    ll ans = -LLINF;
    REP(i, N) {
        ll l, r;
        cin >> l >> r;
        L.push_back(l);
        R.push_back(r);
        LR.push_back(make_pair(l, r));

        l_min = min(l_min, l);
        r_max = max(r_max, r);

        ans = max(ans, r - l + 1);
    }
    SORT(L);
    SORT(R);

    R.erase(unique(R.begin(), R.end()), R.end());
    ll lb = 0, ub = R.size() - 1;
    while(ub - lb > 100) {
        // 100 分探索
        ll sub = (ub - lb) / 100;
        ll next_val = -LLINF;
        ll next_ind = -1;
        for(int i = lb; i <= ub; i += sub) {
            ll cand_val = GetFun(l_min, R[i]);
            if(next_val < cand_val) {
                next_val = cand_val;
                next_ind = i;
            }
        }
        lb = max(0LL, next_ind - sub / 2LL);
        ub = min(static_cast<ll>(R.size()) - 1LL, next_ind + sub / 2LL);
    }

    for(ll i = lb; i <= ub; ++i) {
        ll cand = GetFun(l_min, R[i]);
        DBG("GetFun(%lld, %lld): %lld\n", l_min, R[i], cand);
        ans = max(ans, GetFun(l_min, R[i]));
    }

    printf("%lld\n", ans);

    return 0;
}

