int main(int argc, char *argv[])
{
    int n;
    std::vector<std::pair<int,int>> range;
    int ans;

    std::cin >> n;

    range.reserve(n);
    for (int i = 0; i < n; i++) {
        int l, r;
        std::cin >> l >> r;
        range.push_back(std::make_pair(l, r));
    }

    std::sort(range.begin(), range.end(), 
        [](const std::pair<int,int> &lhs, const std::pair<int,int> &rhs) {
            const int lhs_len = lhs.second - lhs.first + 1;
            const int rhs_len = rhs.second - rhs.first + 1;
            return (lhs_len != rhs_len)?(lhs_len < rhs_len):(lhs.first < rhs.first);
        }
    );

#ifdef _DEBUG
    for (int i = 0; i < n; i++) {
        std::cout << range[i].first << ", " << range[i].second << ", len = " << (range[i].second - range[i].first + 1) << std::endl;
    }
#endif

    int a_min = range[0].first, a_max = range[0].second;
    int b_min = range[n - 1].first, b_max = range[n - 1].second;

    for (int i = 1; i < n - 1; i++) {
        int i_min = range[i].first;
        int i_max = range[i].second;

        int a_score = std::max(0, std::min(a_max, i_max) - std::max(a_min, i_min) + 1) + std::max(0, b_max - b_min + 1);
        int b_score = std::max(0, std::min(b_max, i_max) - std::max(b_min, i_min) + 1) + std::max(0, a_max - a_min + 1);

        if (a_score < b_score) {
            b_max = std::min(b_max, i_max);
            b_min = std::max(b_min, i_min);
        } else {
            a_max = std::min(a_max, i_max);
            a_min = std::max(a_min, i_min);
        }
    }

    ans = std::max(0, a_max - a_min + 1) + std::max(0, b_max - b_min + 1);
    std::cout << ans << std::endl;

    return 0;
}

