		v.push_back({ r, l });

	}
	VSORT(v);
	REP(i, N) {
		int l = v[i].second;
		int r = v[i].first;
		update(i, l);
		update2(i, r);
	}
	int l = v[0].second, r = v[0].first;
	REP(i, N) {
		l = max(l, v[i].second);
		if (l > r)break;
		dp1[i + 1] = (r - l + 1);
	}
	l = v[N - 1].second, r = v[N - 1].first;
	REPR(i, N) {
		r = min(r, v[i].first);
		l = max(l, v[i].second);
		if (l > r)break;
		dp2[i] = (r - l + 1);
	}
	ll ans = 0;
	REP(i, N) {
		int L = v[i].first - v[i].second + 1;
		int mnR = INF;
		if(i<N-1)mnR=query2(i + 1, N, 0, 0, n);
		if (i > 0)mnR = min(mnR,query2(0, i, 0, 0, n));
		int mxL = 0;
		if(i>0)mxL=query(0, i, 0, 0, n);
		if(i<N-1)mxL = max(mxL, query(i + 1, N, 0, 0, n));
		if (mnR >= mxL)L += (mnR - mxL + 1);
		//print(i);
		//pe(v[i].second); print(v[i].first);
		//pe(mxL); print(mnR);
		//if (L >= 1e5)print(i);
		ans = max(ans, L);
		ans = max(ans, dp1[i] + dp2[i]);
	}
	print(ans);
}

