int modpow(int a, int b) {
    int ans = 1;
    while(b) {
        if(b%2) ans = mul(ans, a);    
        b /= 2; a = mul(a, a);
    }   return ans;
}

bool cmp(P a, P b) {
    if(a.first == b.first) {
        return a.second < b.second;
    } 
    return a.first < b.first;
}

