void _main()
{
    ll n; llin(n);
    S V<t2> lrlist; llinl2(lrlist, n); sort_reverse(lrlist);

    ll left2 = get<0>(lrlist[0]);
    ll right2_max = get<1>(lrlist[0]);

    priority_queue<t3> q;
    srep (i, 1, n) {
        ll left = get<0>(lrlist[i]);
        ll right = get<1>(lrlist[i]);
        q.push(t3(left, right, i));
    }

    set<t3> bothset;
    srep (i, 1, n) {
        ll left = get<0>(lrlist[i]);
        ll right = get<1>(lrlist[i]);
        bothset.insert(t3(right, left, i));
    }

    ll ans = 0;

    while (q.size()) {
        auto item = q.top(); q.pop();
        ll left1 = get<0>(item);
        ll right1_max = get<1>(item);
        ll idx = get<2>(item);

        bothset.erase(t3(right1_max, left1, idx));
        auto iter = bothset.begin();
        ll right_new = 1e18;
        if (iter != bothset.end()) right_new = get<0>(*iter);

        debug_printf("left1=%lld right1_max=%lld "
                     "left2=%lld right2_max=%lld "
                     "right_new=%lld\n",
                     left1, right1_max, left2, right2_max, right_new);

        ll cand1 = 0;
        cand1 += max(0LL, min(right1_max, right_new) - left1 + 1LL);
        cand1 += max(0LL, right2_max - left2 + 1LL);
        ll cand2 = 0;
        cand2 += max(0LL, right1_max - left1 + 1LL);
        cand2 += max(0LL, min(right2_max, right_new) - left2 + 1LL);

        ans = max({ans, cand1, cand2});

        right2_max = min(right2_max, right1_max);
    }

    debug_printf("--- ans\n");
    cout << ans << endl;
}

