#include <bits/stdc++.h>

using namespace std;

#define ff first
#define ss second
#define pb push_back

using ll = long long;
using ii = pair<int ,int>;

const int N = 1e5 + 5;


bool k = 0;
bool cmp(ii a, ii b){
	if(k){
		swap(a.ff, a.ss);
		swap(b.ff, b.ss);
	}
	return a < b;
}
int main(){
	int n;
	vector<ii> v;
	vector<ii> v2;
	scanf("%d", &n);
	for(int i = 0; i < n; i++){
		ii x;
		scanf("%d %d", &x.ff, &x.ss);
		v.pb(x);
		swap(x.ff, x.ss);
		v2.pb(x);
	}
	int t = 2;
	ll ans = 0;
	while(t--){
		sort(v.begin(), v.end(), cmp);
		ii g1 = v.back();
		v.pop_back();
		sort(v.rbegin(), v.rend(), cmp);
		set<ii> lef, rig;
		k ^= 1;
		for(int i = 0; i < (int)v.size(); i++){
			lef.insert({v[i].ff, i});
			rig.insert({v[i].ss, i});
		}
		ans = max(ans, (ll)g1.ss - g1.ff + 1) + max(0, -lef.rbegin()->ff + rig.begin()->ff + 1);
		//cerr << ans << endl;
		//cerr << g1.ff << " " << g1.ss << endl;
		for(int i = 0; i < (int)v.size()-1; i++){
			ll aux = max(0, min(g1.ss, v[i].ss) - g1.ff + 1);
			lef.erase({v[i].ff, i});
			rig.erase({v[i].ss, i});
			//cerr << ans << " aux " << aux << endl;
			//cerr << v[i].ff << " ~ " << v[i].ss << endl;
			//cerr << lef.rbegin()->ff << " --- " << rig.begin()->ff << endl;
			aux += max(0, -lef.rbegin()->ff + rig.begin()->ff + 1);
			ans = max(ans, aux);
		}
		v = v2;
	}
	printf("%lld\n", ans);
	return 0;
}

