#include <bits/stdc++.h>
using namespace std;

struct SegmentTree {
    using T = int;
    static T op(const T& a, const T& b) { return min(a, b); }
    static constexpr T e() { return numeric_limits<int>::max(); }
    const int n;
    vector<T> t;
    SegmentTree(int _n) : n(_n), t(2 * n, e()) {}
    T& operator[](int i) { return t[i + n]; }
    T query(int l, int r) const {
        T resl = e(), resr = e();
        for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
            if (l & 1) resl = op(resl, t[l++]);
            if (r & 1) resr = op(t[--r], resr);
        }
        return op(resl, resr);
    }
    void update(int i, const T& a) {
        t[i += n] = a;
        while (i >>= 1) t[i] = op(t[2 * i], t[2 * i + 1]);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;
    vector<pair<int, int>> as;
    for (int i = 0; i < n; i++) {
        int a, b;
        cin >> a >> b;
        as.emplace_back(a, b);
    }
    sort(as.begin(), as.end());
    SegmentTree seg(n);
    for (int i = 0; i < n; i++) {
        seg.update(i, as[i].second);
    }

    int ans = 0;
    for (int i = 1; i < n; i++) {
        int ll = as[i - 1].first;
        int lr = seg.query(0, i);
        int L = max(lr - ll + 1, 0);
        int rl = as[n - 1].first;
        int rr = seg.query(i, n);
        int R = max(rr - rl + 1, 0);
        ans = max(ans, L + R);
    }
    cout << ans << endl;
}

