int64_t solve()
{
	int N;
	scanf("%d", &N);

	using Span = std::pair<int64_t, int64_t>;
	std::vector<Span> lr(N);
	for (auto& e: lr)
	{
		scanf("%lld%lld", &e.first, &e.second);
		e.first--;
	}
	std::sort(lr.begin(), lr.end());
	int64_t min_r{1ll << 60};
	for (auto& e: lr)
		min_r = std::min(min_r, e.second);
	Span smaller{-1, 1ll << 60}, larger{-1, 1ll << 60};
	std::vector<Span> undefined;
	for (auto& e: lr)
	{
		if (e.first >= min_r)
		{
			larger.first = std::max(larger.first, e.first);
			larger.second = std::min(larger.second, e.second);
		}
		else
			undefined.push_back(e);
	}
	int64_t ans{};
	if (larger.first == -1)
	{
		int max_i{};
		for (int i{}; i < N; i++)
			if (lr[i].second - lr[i].first > lr[max_i].second - lr[max_i].first)
				max_i = i;
		larger = {-1, 1ll << 60};
		smaller = lr[max_i];
		for (int i{}; i < N; i++)
		{
			if (i == max_i) continue;
			larger.first = std::max(larger.first, lr[i].first);
			larger.second = std::min(larger.second, lr[i].second);
		}
		ans = larger.second - larger.first + smaller.second - smaller.first;

		larger = {-1, 1ll << 60};
		smaller = lr.back();
		for (int i{}; i < N - 1; i++)
		{
			larger.first = std::max(larger.first, lr[i].first);
			larger.second = std::min(larger.second, lr[i].second);
		}
		ans = std::max(ans, larger.second - larger.first + smaller.second - smaller.first);
	}
	else
	{
		std::priority_queue<Span> pq;
		for (auto& e: undefined) pq.push(e);
		while (!pq.empty())
		{
			larger.second = std::min(larger.second, pq.top().second);
			if (larger.first >= larger.second) break;
			pq.pop();
			ans = std::max(ans, min_r - pq.top().first + larger.second - larger.first);
		}
	}
	return ans;
}

