	for (int i = 0; i < n; i++) {
		LL l, r; cin >> l >> r;
		range.emplace_back(l, r);
	}


	LL best = 0; PII tot(1, MAX);
	for (auto& e: range) {
		best = max(best, len(e));
		tot = merge(tot, e);
	}
	LL ans = len(tot) + best;
	cout << ans << endl;

#ifdef LOCAL_EXEC
	brute(range, ans);
#endif

	return 0;
}

