#define int ll

struct mint {
	int64_t value;
	mint() :value(0) {}
	mint(int64_t value_) : value(value_% MOD) {}
	inline mint& operator += (const mint& rhs) {
		value += rhs.value;
		if (value >= MOD) { value -= MOD; }
		return *this;
	}
	inline mint& operator -= (const mint& rhs) {
		value -= rhs.value;
		if (value < 0) {
			value += MOD;
		}
		return *this;
	}
	inline mint& operator *= (const mint& rhs) {
		value *= rhs.value;
		value %= MOD;
		return *this;
	}
	inline mint& operator %= (const mint& rhs) {
		return *this;
	}
};

// x^n % mod
// O(log n)
mint mod_pow(mint x, uint64_t n) {
	mint res = 1;
	while (n > 0) {
		if (n & 1) res *= x;
		x *= x;
		n >>= 1;
	}
	return res;
}

inline mint operator + (const mint& lhs, const mint& rhs) { mint res = lhs; res += rhs; return res; }
inline mint operator - (const mint& lhs, const mint& rhs) { mint res = lhs;	res -= rhs;	return res; }
inline mint operator * (const mint& lhs, const mint& rhs) { mint res = lhs;	res *= rhs;	return res; }
inline mint operator % (const mint& lhs, const uint64_t& rhs) { return lhs; }

ostream& operator << (ostream& out, mint n) { return out << n.value; }

// fact(n)%MOD, invFact(n)%MOD, inv(n)%MOD, nCk
// Constructor O(N)
// other O(1)
template<typename T>
class Choose {
public:
	vector<T> fact, inv, invFact;

	Choose(T N):fact(N), inv(N), invFact(N){
		inv[1] = 1;
		FOR(i, 2, inv.size()) inv[i] = MOD - (MOD / i) * inv[MOD%i] % MOD;
		fact[0] = invFact[0] = 1;
		FOR(i, 1, fact.size()) {
			fact[i] = fact[i - 1] * i % MOD;
			invFact[i] = (invFact[i - 1] * inv[i]) % MOD;
		}
	}

	//Get nCk
	T operator () (T n, T k) const {
		if (not ((T)0 <= k and k <= n)) return 0;
		return (((fact[n] * invFact[k]) % MOD)*invFact[n - k]) % MOD;
	}
};

void solve() {
	int N; cin >> N;
	vector<pii> LR(N);
	vector<pii> L;
	vector<pii> R;
	REP(i,N){
		auto& a = LR[i];
		cin >> a.first >> a.second;
		L.emplace_back(a.first, i);
		R.emplace_back(a.second, i);
	}
	sort(ALL(L));
	sort(ALL(R), greater<pii>());

	int res = 0;

	// 片方に一つだけで、もう片方に全部を押し付けるパターン O(N)
	for (auto& lr : LR) {
		int l, r; tie(l, r) = lr;
		int l2 = 0;
		if (L[L.size()-1].first == l) {
			l2 = L[L.size()-2].first;
		}
		else {
			l2 = L[L.size()-1].first;
		}
		int r2 = 0;
		if (R[R.size()-1].first == r) {
			r2 = R[R.size()-2].first;
		}
		else {
			r2 = R[R.size()-1].first;
		}
		res = max(max((r - l) + 1, 0LL) + max((r2 - l2) + 1, 0LL), res);
	}

	// Lが最大値のとき
	{
		int maxIndex = 0;
		pii maxValue;
		REP(i, N) {
			if (maxValue.first < LR[i].first) {
				maxValue = LR[i];
				maxIndex = i;
			}
			else if(maxValue.first == LR[i].first and maxValue.second < LR[i].second) {
				maxValue = LR[i];
				maxIndex = i;
			}
		}

		vector<pii> rangeLeft;

		{
			int firstIndex = R.back().second;
			rangeLeft.push_back(LR[firstIndex]);
		}

		// Rちっちゃい順
		FOR(i,1,N){
			int index = R[N - i - 1].second;
			if (index == maxIndex) {
				continue;
			}
			rangeLeft.push_back(rangeLeft.back());
			int l, r; tie(l, r) = LR[index];
			rangeLeft.back().first = max(rangeLeft.back().first, l);
			rangeLeft.back().second = min(rangeLeft.back().second, r);
		}

		vector<pii> rangeRight;
		rangeRight.push_back(maxValue);
		// Rおっきいじゅん
		FOR(i,1,N){
			int index = R[i].second;
			if (index == maxIndex) {
				continue;
			}
			rangeRight.push_back(rangeRight.back());
			int l, r; tie(l, r) = LR[index];
			rangeRight.back().first = max(rangeRight.back().first, l);
			rangeRight.back().second = min(rangeRight.back().second, r);
		}

		REP(i, N-1) {
			int a = max(rangeLeft[i].second - rangeLeft[i].first + 1, 0LL);
			int b = max(rangeRight[N-i-2].second - rangeRight[N-i-2].first + 1, 0LL);
			res = max(a + b, res);
		}
	}

	// Rが最小値のとき
	{
		int maxIndex = 0;
		pii maxValue = { inf, inf };
		REP(i, N) {
			if (maxValue.first > LR[i].first) {
				maxValue = LR[i];
				maxIndex = i;
			}
			else if(maxValue.first == LR[i].first and maxValue.second > LR[i].second) {
				maxValue = LR[i];
				maxIndex = i;
			}
		}

		vector<pii> rangeLeft;

		{
			int firstIndex = L.back().second;
			rangeLeft.push_back(LR[firstIndex]);
		}

		// Lおっきいじゅん
		FOR(i,1,N){
			int index = L[N - i - 1].second;
			if (index == maxIndex) {
				continue;
			}
			rangeLeft.push_back(rangeLeft.back());
			int l, r; tie(l, r) = LR[index];
			rangeLeft.back().first = max(rangeLeft.back().first, l);
			rangeLeft.back().second = min(rangeLeft.back().second, r);
		}

		vector<pii> rangeRight;
		rangeRight.push_back(maxValue);
		// Lちっちゃいじゅん
		FOR(i,1,N){
			rangeRight.push_back(rangeRight.back());
			int index = L[i].second;
			if (index == maxIndex) {
				continue;
			}
			int l, r; tie(l, r) = LR[index];
			rangeRight.back().first = max(rangeRight.back().first, l);
			rangeRight.back().second = min(rangeRight.back().second, r);
		}

		REP(i, N-1) {
			int a = max(rangeLeft[i].second - rangeLeft[i].first + 1, 0LL);
			int b = max(rangeRight[N-i-2].second - rangeRight[N-i-2].first + 1, 0LL);
			res = max(a + b, res);
		}
	}

	cout << res << endl;
}

