struct abc{
    ll l,r;
    bool operator<(const abc& rhs) const{
        return (r-l) < (rhs.r-rhs.l);
    }
};

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    ll n;
    cin >> n;
    vector <abc> arr(n);
    for (int z=0;z<n;z++){
        cin >> arr[z].l >> arr[z].r;
    }
    sort(arr.rbegin(),arr.rend());
    abc first = arr[0];
    abc second;
    ll i = 0;
    ll maxi = 0;
    for (int z=1;z<n;z++){
        if (arr[z].l > first.r || arr[z].r < first.l){
            second = arr[z];
            i = 0;
            break;
        }
        ll a = first.r-first.l-min(first.r,arr[z].r)+max(first.l,arr[z].l);
        if (a > maxi){
            maxi = a;
            i = z;
        }
    }
    if (i != 0){
        second = arr[i];
    }
    ll ans = 0;
    for (int z=0;z<n;z++){
        if (z == i) continue;
        if (arr[z].l > first.r || arr[z].r < first.l){
            if (arr[z].l > second.r || arr[z].r < second.l){
                ans = max(first.r-first.l+1,second.r-second.l+1);
                break;
            } else {
                second.l = max(second.l,arr[z].l);
                second.r = min(second.r,arr[z].r);
            }
