template <typename T>
struct SegmentTree
{
private:
    int n;
    T E;
    vector<T> node;
    inline void updatef(T &x, T &y)
    {
        x = y;
        //x += y;
        //x = max(x,y);
        //x = min(x,y);
    }
    inline T queryf(T &x, T &y)
    {
        //return x*y;
        //return x+y;
        //return max(x,y);
        return min(x, y);
    }

public:
    SegmentTree(int sz, T E_) : E(E_)
    {
        n = 1;
        while (n < sz)
            n <<= 1;
        node.resize(2 * n - 1, E);
    }

    SegmentTree(vector<T> &A, T E_) : E(E_)
    {
        int sz = A.size();
        n = 1;
        while (n < sz)
            n <<= 1;
        node.resize(2 * n - 1, E);
        rep(i, sz) node[i + n - 1] = A[i];
        for (int i = n - 2; i >= 0; --i)
        {
            node[i] = queryf(node[2 * i + 1], node[2 * i + 2]);
        }
    }
    void update(int k, T x)
    {
        k += n - 1;
        updatef(node[k], x);
        while (k > 0)
        {
            k = (k - 1) / 2;
            node[k] = queryf(node[2 * k + 1], node[2 * k + 2]);
        }
    }
    //[a,b)での和を返す
    T get(int a, int b, int k = 0, int l = 0, int r = -1)
    {
        if (r < 0)
            r = n;
        if (r <= a || b <= l)
            return E;
        if (a <= l && r <= b)
            return node[k];
        T xl = get(a, b, 2 * k + 1, l, (l + r) / 2);
        T xr = get(a, b, 2 * k + 2, (l + r) / 2, r);
        return queryf(xl, xr);
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

