    SegmentTree<int> sg(N+1, inf/2), sg2(N+1, inf/2);
    rep(i, N) {
        sg.update(i, -s[i]);
        sg2.update(i, -s2[i]);
    }
    int res = 0;
    rep(i, N) {
        int l = sg.get(0, i+1);
        l = -l;
        int r = sg.get(i+1, N);
        r = -r;
        res = max(res, s2[i] - l + s2[N-1] - r);
    }
    cout << res << endl;
}

