	for(int i = 1; i <= n; i++){
		MinR = min(MinR , p[i].se);
		MaxL = max(MaxL , p[i].fi);
		int cur = MinR - MaxL + 1;
		if(cur <= 0)break;
		cur += sf[i + 1];
		ans = max(ans , cur);
	}
}
vector < int > v;
void plex(){
	int MxL = 0 , MnR = 2e9;
	for(int i = n; i >= 1 ; i--){
		MxL = max(p[v[i - 1]].fi , MxL);
		MnR = min(p[v[i - 1]].se , MnR);
		if(MxL > MnR)
			break;
		sf[i] = max(MnR - MxL + 1 , 0ll);
	}
	int MinR = 2e9 , MaxL = 0;
	for(int i = 1; i <= n; i++){
		MinR = min(MinR , p[v[i - 1]].se);
		MaxL = max(MaxL , p[v[i - 1]].fi);
		int cur = MinR - MaxL + 1;
		if(cur <= 0)break;
		cur += sf[i + 1];
		ans = max(ans , cur);
	}
}	
void rev(){
	for(int i = 1 ; i <= n; i++){
		p[i].fi = 1e9 - p[i].fi + 1;
		p[i].se = 1e9 - p[i].se + 1;
		swap(p[i].fi,p[i].se);
	}
