	}

	// L最大はソートしたため右端の要素
	ll L = vec[N - 1].first;
	ll LR = vec[N - 1].second;
	// R最小を探す
	ll R = INF, tmp = -1, RL = 0;
	for (int i = 0; i < N; ++i) {
		if (R > vec[i].second) {
			tmp = i;
			R = vec[i].second;
			RL = vec[i].first;
		}
	}

	if (tmp == N - 1) {
		// 最大区間と最小区間の和
		ll LONGEST = 0;
		for (int i = 0; i < N; ++i) LONGEST = max(LONGEST, vec[i].second - vec[i].first);
