		for (int i = N - 1; i >= 0; --i) {
			tR[i] = min(tR[i + 1], vec[i].second);
		}
		vector<ll> tL(N + 1, RL);
		for (int i = 0; i < N; ++i) {
			tL[i+1] = max(tL[i], vec[i].first);
		}

		ll ans = 0;
		for (int i = 0; i < N + 1; ++i) {
			ll tmp = max(0LL, R - tL[i]) + max(0LL, tR[i] - L);
			ans = max(ans, tmp);
		}
		cout << ans << endl;
	}

	return 0;
}

