typedef long long LL;

const LL MAXN = 1e6+7;

///--------------------------------------------///

struct Node{
    LL l, r;
};
vector<Node> g;
vector<Node> f;
LL n, ans, dp[MAXN];

void process(){
    for(int i = 0; i < n; ++i){
        if(i){
            LL l = max(f[i-1].l, g[i].l);
            LL r = min(f[i-1].r, g[i].r);
            f.push_back({l, r});
        }
        else f[0] = g[i];
        dp[i] = max(0ll, f[i].r - f[i].l + 1);
    }
    f.push_back({0ll, (LL)1e12});
    for(int i = n - 1; i > 0; --i){
        if(i < n - 1){
            LL l = max(f[i-1].l, f[i+1].l);
            LL r = min(f[i-1].r, f[i+1].r);
            ans = max(ans, max(0ll, r-l+1) + max(0ll, g[i].r - g[i].l + 1));
        }
        LL l = max(f[i+1].l, g[i].l);
        LL r = min(f[i+1].r, g[i].r);
        f[i] = {l, r};
        ans = max(ans, dp[i-1] + max(0ll, r - l + 1));
        //cout<<i<<" "<<dp[i-1]<<" "<<l<<" "<<r<<" "<<ans << endl;
    }
    f.pop_back();
}

int main()
{
    cin >> n;
    g.resize(n); f.resize(n);
    for(int i = 0; i < n; ++i) {
        cin >> g[i].l >> g[i].r;
        ans = max(ans, g[i].r - g[i].l + 1);
    }
    sort(g.begin(), g.end(), [](Node a, Node b){
        return a.l < b.l || (a.l == b.l && a.r < b.r);
    });
    process();
    sort(g.begin(), g.end(), [](Node a, Node b){
        LL l = a.r - a.l + 1, r = b.r - b.l + 1;
        return (l > r) || (l == r && (a.l < b.l || (a.l == b.l && a.r < b.r))) ;
    });
    process();

    cout << ans << endl;
    return 0;
}

