  for(int i = 0; i < N - 1; i++){
    long long L1 = LR[i].first;
    long long R1 = LR[i].second;
    long long L2 = LR[N - 1].first;
    long long R2 = R_right_min[i + 1];
    if(i == 0){
      ans = max(ans, max((long long) 0, R1 - L1 + 1) + max((long long) 0, R2 - L2 + 1));
    } else {
      ans = max(ans, max((long long) 0, min(R1, R_left_min[i - 1]) - L1 + 1) 
            + max((long long) 0, R2 - L2 + 1));
      ans = max(ans, max((long long) 0, R1 - L1 + 1) 
            + max((long long) 0, min(R2, R_left_min[i - 1]) - L2 + 1));
    }
  }
  cout << ans << endl;
  return 0;
}

