            from_start[i] = to - from+1;
            cur_s = from;
            cur_e = to;
        }
        else {
            from_start[i] = cur_e - from + 1;
            cur_s = from;
        }
    }

    // from_last
    cur_s = p[n-1].first;
    cur_e = p[n-1].second;
    from_last[n-1]= cur_e - cur_s + 1;
    REPE_R(i,n-2,0) {
        lli from = p[i].first;
        lli to = p[i].second;
        //cout1(i);
        //cout2(cur_s, cur_e);
        //cout2(from, to);
        if (to < cur_s) {
            from_last[i] = 0;
        }
        else if (to <= cur_e) {
            from_last[i] = to - cur_s+1;
            cur_e = to;
        }
        else {
            from_last[i] = cur_e - cur_s + 1;
        }
    }
    lli ans = 0;
    REP(i,1,n) {
        //cout3(i,from_start[i-1], from_last[i]);
        ans = max(ans, from_start[i-1] + from_last[i]);
    }
    if ((ans == from_start[0] + from_last[1] && (from_start[0] == 0 || from_last[1] == 0)) ||
        (ans == from_start[n-2] + from_last[n-1] && (from_start[n-2] == 0 || from_last[n-1] == 0))) {
        // この場合は、特定の区間だけやれば良い
        REP(i,0,n) {
            ans = max(ans, p[i].second - p[i].first + 1);
        }
    }
    cout << ans << endl;
}

