    a.emplace_back(x);
    a.emplace_back(y);
  }
  std::sort(all(a));
  a.resize(std::unique(all(a)) - a.begin());
  auto rev = [&] (int x) {
    auto lb = std::lower_bound(all(a), x);
    assert(*lb == x);
    return lb - a.begin();
  };
  for (auto & pair : pairs) {
    pair.first = rev(pair.first);
    pair.second = rev(pair.second);
  }

  int R = 1e9;
  int longest = 0;
  for (auto pair : pairs) {
    cmn(R, pair.second);
    cmx(longest, a.at(pair.second) - a.at(pair.first));
  }

