  for (int L = R - 1; 0 <= L; L--) {
    while (!red.empty()) {
      int l, r; std::tie(l, r) = red.back();
      if (l <= L) break;
      blue.emplace_back(l, r);
      cmx(blueL, l);
      cmn(blueR, r);
      red.pop_back();
    }
