    if (blue.empty()) {
      int x = a.at(R) - a.at(L);
      int y = longest;
      cmx(ans, x + y);
    } else {
      int x = a.at(R) - a.at(L);
      int y = std::max(0, a.at(blueR) - a.at(blueL));
      cmx(ans, x + y);
    }
  }
  std::cout << ans << std::endl;
  return 0;
}

