    int N; cin >> N;
    ii LR[N];
    int p = 0, q = 0, r = 0;
    FOR(i,0,N-1){
        cin >> LR[i].fi >> LR[i].sc;
        if (LR[i].fi > LR[p].fi) p = i;
        if (LR[i].sc < LR[q].sc) q = i;
        if (LR[i].sc-LR[i].fi+1 > LR[r].sc-LR[r].fi+1) r = i;
    }

    int ans1 = LR[r].sc-LR[r].fi+1;
