        ab[i] = ii(max(0,LR[i].sc-LR[p].fi+1), max(0,LR[q].sc-LR[i].fi+1));
    }
    sort(ab,ab+N,[](ii a, ii b) {
        if (a.fi == b.fi) return a.sc > b.sc;
        else return a.fi < b.fi;
    });
    int cur = ab[0].sc;
