        int max_len = 0;
        for(int i = 1;i <= n;i++){
            max_len = max(max_len,segm[i].first.second - segm[i].first.first + 1);
        }
        for(int i = 1;i <= n;i++){
            segm[i].first.second -= (sect.second - sect.first + 1);
