    for(int i = 0;i < (int)posx.size();i++){
        segm[++n] = {{posx[i],fst.second},1};
        if(posx[i] == fst.second){
            break;
        }
    }

    sort(segm + 1,segm + 1 + n,[&](pair<pair<int,int>,int> &a,pair<pair<int,int>,int> &b){if(a.first.first != b.first.first)return a.first.first < b.first.first;return a.first.second > b.first.second;});

    suff_sect[n + 1] = {0,1e9};

    for(int i = n;i;i--){
        if(segm[i].second == 1){
            suff_sect[i] = suff_sect[i + 1];
