using P=pair<ll,ll>;
int main(){
  int n; cin>>n;
  vector<P> lr(n);
  ll maxl=0,minr=1000000010;
  for(int i=0;i<n;i++){
    ll x,y; cin>>x>>y;
    y++; //半開区間にしたほうが
    lr[i]=P(x,y);
    if(maxl<x) maxl=x;//最も大きなl
    if(minr>y) minr=y;//最も小さなr
  }
  ll ans=0;
  for(int i=0;i<n;i++){
    ans=max(ans,max(0ll,minr-maxl)+lr[i].second-lr[i].first);
    //場合分け一、最大のlと最小のrが同一のグループ
  }
  //以下同一でないグループに所属した場合
  vector<P> lrre(n),lrre2(n);
  for(int i=0;i<n;i++){
    ll x=max(0ll,minr-lr[i].first);
    //最小のrが所属するグループに所属させたとき
    ll y=max(0ll,lr[i].second-maxl);
    //最大のlが所属するグループに所属させたとき
    lrre[i]=P(y,x);
  }
  sort(lrre.begin(),lrre.end());
  ll w=1000000010;
  for(int i=0;i<n;i++){
    if(i){//i=0以外の時
      ans=max(ans,lrre[i].first+w);
      //昇順なので、i番目以降が同一のグループに所属するとき
      //lrre[i].firstが最も小さい範囲になるのでi-1番目までの
      //最小範囲別途、記録すればよい
    }
    if(w>lrre[i].second) w=lrre[i].second;
  }
  cout<<ans<<endl;
}

