inline int front(multiset<int> &x) {
	assert(!x.empty());
	return *(x.begin());
}

inline int back(multiset<int> &x) {
	assert(!x.empty());
	return *(--x.end());
}

inline void erase(multiset<int> &x, int val) {
	x.erase(x.find(val));
}

inline void insert(multiset<int> &x, int val) {
	x.insert(val);
}

multiset<int> fr[2], to[2];

int calval() {
	if(fr[0].empty() or fr[1].empty()) return 0;
	int ret = max(0, front(to[0]) - back(fr[0]) + 1) + max(0, front(to[1]) - back(fr[1]) + 1);
	return ret;
}

int main() {
	FastIO;

	int n;
	cin >> n;
	for(int i=0; i<n; ++i) cin >> a[i].first >> a[i].second;

	vector<int> pos;
	for(int i=0; i<n; ++i) {
		st[a[i].first].push_back(a[i]);
		en[a[i].second].push_back(a[i]);
		pos.push_back(a[i].first);
		pos.push_back(a[i].second);
	}
	sort(all(pos));
	pos.erase(unique(all(pos)), pos.end());

	int maxlen = 0;
	for(int i=0; i<n; ++i) {
		maxlen = max(a[i].second - a[i].first + 1, maxlen);
	}

	for(int i=0; i<n; ++i) {
		insert(to[1], a[i].second);
		insert(fr[1], a[i].first);
	}

	int res = max(front(to[1]) - back(to[1]) + 1, 0) + maxlen;
	for(int p : pos) {
		auto &vec = en[p];
		sort(all(vec));
		for(auto ran : vec) {
			erase(fr[0], ran.first);
			erase(to[0], ran.second);
			insert(fr[1], ran.first);
			insert(to[1], ran.second);
			res = max(res, calval());
		}

		vec = st[p];
		sort(all(vec), [&] (pii &p, pii &q) { return p.second > q.second; } );
		for(auto ran : vec) {
			erase(fr[1], ran.first);
			erase(to[1], ran.second);
			insert(fr[0], ran.first);
			insert(to[0], ran.second);
			res = max(res, calval());
		}
	}

	cout << res << "\n";

	return 0;
}

