struct tmp{
    int first, second;
    tmp(){first = 0; second = 0;}
    const bool operator<(const tmp &t) const {
        if (second == t.second) {
            return first > t.first;
        }
        return second < t.second;
    }
};

int n;
tmp p[100010];
int a[600010];
vector<int> dict;

void input() {
    cin >> n;
    for (int i = 0; i < n; i++) {
        cin >> p[i].se >> p[i].fi;
    }
}

void solve() {
    sort(p,p+n);
    map<int,int> left,right;
    for (int i = 0; i < n; i++) {
        left[p[i].se]++;
        right[p[i].fi]++;
    }
    int ma = 0;
    int l, r;
    for (int i = 0; i < n - 1; i++) {
        if (i == 0) {
            l = p[0].se;
            r = p[0].fi;
        } else {
            l = max(l, p[i].se);
            r = min(r, p[i].fi);
        }
        left[p[i].se]--;
        right[p[i].fi]--;
        if (left[p[i].se] == 0) left.erase(p[i].se);
        if (right[p[i].fi] == 0) right.erase(p[i].fi);
        auto it = left.end();
        it--;
        int ll = (*it).fi;
        int rr = (*right.begin()).fi;
        ma = max(ma, max(0, r - l + 1) + max(0, rr - ll + 1));
        // cout << l << " " << r << " , " << ll << " " << rr << ": ";
        // cout << max(0,r-l+1) << " " << max(0,rr-ll+1) << " " << max(0, r - l + 1) + max(0, rr - ll + 1) << endl;
    }
    cout << ma << endl;
}

int main(int argc, char *argv[]){
    input();
    solve();
    return 0;
}

