			pair<ll,ll> tmp;
			if(up[i-1].first!=-1){
				tmp=insec(v[i],up[i-1]);
			}
			if(tmp.first>tmp.second||up[i-1].first==-1){
				tmp.first=-1;
				tmp.second=-2;
			}
			up[i]=tmp;
		}
