			pair<ll,ll> tmp;
			if(down[i+1].first!=-1){
				tmp=insec(v[i],down[i+1]);
			}
			if(tmp.first>tmp.second||down[i+1].first==-1){
				tmp.first=-1;
				tmp.second=-2;
			}
			down[i]=tmp;

		}
		for(int i=0;i<n-1;i++){
			ans=max(ans,calc(up[i],down[i+1]));
			// cout<<"cal:"<<calc(up[i],down[i+1])<<endl;
