const int MAXN = 100000 + 10;

struct Seg{
	int l, r;

	bool operator < (const Seg b) const { return r < b.r; }
};
int n;
Seg a[MAXN];
int f[MAXN];

inline int calc(const Seg a, const int p) { return std::max(a.r - std::max(a.l, p) + 1, 0); }
inline int len(const Seg a) { return std::max(a.r - a.l + 1, 0); }

int main() {
	int i, ans = 0;
	Seg x;

	scanf("%d", &n);
	for(i=1; i<=n; i++) 
		scanf("%d %d", &a[i].l, &a[i].r);
	std::sort(a+1, a+1+n);

	f[n] = a[n].l;
	for(i=n - 1; i; i--) 
		f[i] = std::max(a[i].l, f[i + 1]);

	x.l = a[1].l;
	x.r = a[1].r;
	for(i=2; i<=n; i++) {
		ans = std::max(ans, std::max(calc(x, f[i + 1]) + len(a[i]), calc(a[i], f[i + 1]) + len(x)));
		x.l = std::max(x.l, a[i].l);
		x.r = std::min(x.r, a[i].r);
	}
	printf("%d\n", ans);
	return 0;
}

