signed main(void) {
	int n, ans = 0;
	int minR = 1000000009, maxL = 0;
	pair<pii, int>  Rid = { {1000000009, 0}, 0 }, Lid = { { 0, 1000000009 },0 };
	cin >> n;
	vector<pii> e(n);
	REP(i, n) {
		cin >> e[i].first >> e[i].second;
		ans = max(ans, e[i].second - e[i].first + 1);

		if (minR > e[i].second)
			minR = e[i].second;
		if (maxL < e[i].first)
			maxL = e[i].first;

		Rid = min(Rid, { {e[i].second, -e[i].first}, i });
		Lid = max(Lid, { {e[i].first, -e[i].second}, i });
	}

	sort(ALL(e));
	int rinR = 1000000009, raxL = 0;

	for (int i = n - 1; 1 <= i; i--) {
		rinR = min(rinR, e[i].second);
		raxL = max(raxL, e[i].first);

		int cl = max(0,minR - e[i-1].first + 1);
		int cr = max(0,rinR - raxL + 1);
		ans = max(ans, cl + cr);
		if (e[i].second == minR) break;
	}



	REP(i, n) {
		if (i == Rid.second || i == Lid.second) continue;

		ans = max(ans, e[i].second - e[i].first + 1 + (minR - maxL + 1));
	}

	cout << ans << endl;

	return 0;
}

