pii inter(pii a, pii b) {
    return make_pair(max(a.first, b.first), min(a.second, b.second));
}

int len(pii x) { return x.second - x.first; }

vector<pii> cum(const vector<pii> &p) {
    int n = si(p);
    vector<pii> res(n+1);
    res[0] = make_pair(-INF,INF);
    forn(i,n) res[i+1] = inter(res[i], p[i]);
    return res;
}

