ll solve1(ll N, vector<pair<ll, ll>> lr) {
    ll fres = 0;

    vector<ll> resL(N), resR(N);
    ll minr = 1ll << 60;
    rep(i, N) {
        ll l = lr[i].first;
        minr = min(minr, lr[i].second);
        resL[i] = max(0ll, minr - l + 1);
    }

    ll maxl = -(1ll << 60);
    minr = 1ll << 60;
    for (int i = N - 1; i >= 0; i--) {
        maxl = max(maxl, lr[i].first);
        minr = min(minr, lr[i].second);
        resR[i] = max(0ll, minr - maxl + 1);
    }
    rep(i, N - 1)fres = max(fres, resL[i] + resR[i + 1]);
    return fres;
}

ll solve2(ll N, vector<pair<ll, ll>> lr) {
    set<ll> stl, str;
    map<ll, ll> cntl, cntr;
    for (auto p : lr) {
        ll l, r;
        tie(l, r) = p;
        stl.insert(l);
        str.insert(r);
        cntl[l]++;
        cntr[r]++;
    }

    ll res = 0;
    for (auto p : lr) {
        ll l, r, tres;
        tie(l, r) = p;
        tres = r - l + 1;

        if (cntl[l] == 1)stl.erase(l);
        if (cntr[r] == 1)str.erase(r);

        auto itrl = stl.end();
        itrl--;
        ll ml = *itrl;
        ll mr = *str.begin();
        if (ml <= mr)tres += mr - ml + 1;
        res = max(res, tres);

        stl.insert(l);
        str.insert(r);
    }
    return res;
}

