inline bool cmp(const pair <int, int> &a, const pair <int, int> &b) {
  if (a.second != b.second) {
    return a.second < b.second;
  }
  return (a.first != b.first ? a.first < b.first : 0);
}

vector < pair <int, int> > vec;

int left(int x) {
  return (x << 1);
}

int right(int x) {
  return (x << 1) + 1;
}

int st[4 * N];
int n;

void build(int p, int L, int R) {
  if (L == R) {
    st[p] = vec[L].first;
  } else {
    int mid = (L + R) >> 1;
    build(left(p), L, mid);
    build(right(p), mid + 1, R);
    st[p] = max(st[left(p)], st[right(p)]);
  }
}

int query(int p, int L, int R, int i, int j) {
  if (L > j || R < i) return -inf;
  if (L >= i && R <= j) {
    return st[p];
  }
  int mid = (L + R) >> 1;
  return max(query(left(p), L, mid, i, j),
             query(right(p), mid + 1, R, i, j));
}

int f(int l, int r) {
  if (l > r) return 0;
  int x = vec[l].second - query(1, 0, n - 1, l, r) + 1;
  return max(0ll, x);
}

int comb(int a, int b, int c, int d) {
  int x, low = -inf;
  if (a <= b) {
    x = vec[a].second;
  } else if (c <= d) {
    x = vec[c].second;
  } else {
    return 0;
  }
  if (a <= b && a >= 0) {
    low = max(low, query(1, 0, n - 1, a, b));
  }
  if (c <= d && c >= 0) {
    low = max(low, query(1, 0, n - 1, c, d));
  }
  if (low == -inf) return 0;
  return max(0ll, x - low + 1);
}

