constexpr int INF = 1 << 30;

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int n;
    cin >> n;
    vector<Pii> sections(n);
    for(int i=0;i<n;++i){
        cin >>sections[i].first >> sections[i].second;
    }

    int a, b, al = 0, ar = INF, bl = 0, br = INF;
    for(int i=0;i<n;++i) {
        if(sections[i].second < ar) {
            a = i;
            al = sections[i].first;
            ar = sections[i].second;
        }
        if(bl < sections[i].first) {
            b = i;
            bl = sections[i].first;
            br = sections[i].second;
        }
    }

    // a と b を同じ区間にする
    int c, cl = 0, cr = 0, dl = 0, dr = INF;
    for(int i=0;i<n;++i) {
        if(cr-cl < sections[i].second-sections[i].first) {
            c = i;
            cl = sections[i].first;
            cr = sections[i].second;
        }
    }
    for(int i=0;i<n;++i) {
        if(i == c) continue;
        dl = max(dl, sections[i].first);
        dr = min(dr, sections[i].second);
    }
    int ans = max(cr-cl+1, 0) + max(dr-dl+1, 0);

    if(a == b) {
        cout << ans << endl;
        return 0;
    }

    // a と b を違う区間にする
    sort(
        sections.begin(), sections.end(), 
        [&](Pii p, Pii q) { 
            int p_diff = max(0, p.second - bl), q_diff = max(0, q.second - bl);
            if(p_diff != q_diff) return p_diff > q_diff;
            return max(0, ar - p.first) < max(0, ar - q.first);
        }
    );

    // for(Pii p: sections) {
    //     cerr << p.first << " " << p.second << endl;
    // }
    // cerr << endl;

    vector<int> min_r_bl(n);
    min_r_bl[0] = sections[0].second;
    for(int i=1;i<n;++i) {
        min_r_bl[i] = min(min_r_bl[i-1], sections[i].second);
    }

    vector<int> max_l_ar(n);
    max_l_ar[n-1] = sections[n-1].first;
    for(int i=n-2;i>=0;--i) {
        max_l_ar[i] = max(max_l_ar[i+1], sections[i].first);
    }

    for(int i=1;i<n;++i) {
        // cerr << min_r_bl[i-1] << "-" << bl << " " << ar << "-" << max_l_ar[i] << endl;
        ans = max(ans, max(0, min_r_bl[i-1] - bl + 1) + max(0, ar - max_l_ar[i] + 1));
    }
    cout << ans << endl;
}

