    rep(i,0,n)if(chmin(rmin,r[i]))idx=i;
    rep(i,0,n)if(chmax(lmax,l[i]))idx2=i;
    if(idx==idx2){
        int rmax=0,lmin=inf;
        rep(i,0,n)chmax(rmax,r[i]);
        rep(i,0,n)chmin(lmin,l[i]);
        printf("%d\n",max(0,rmin-lmax+1)+max(0,rmax-lmin+1));
        return 0;
    }
    vector<P> rem; 
    int l_0=l[idx],r_0=r[idx2];
    rep(i,0,n){
        if(l_0<=l[i]&&r[i]<=r_0&&i!=idx&&i!=idx2)rem.push_back({l[i],r[i]});
    }
    if(rem.empty()){
        cerr<<rmin<<lmax<<l_0<<r_0<<endl;
        printf("%d\n",max(0,r_0-lmax+1)+max(0,rmin-l_0+1));
        return 0;
    }
    sort(ALL(rem),cmp);
    SegmentTree<int> minn(n,
    [](int a,int b){return min(a,b);},[](int a,int b){return b;},inf);
    SegmentTree<int> maxx(n,
    [](int a,int b){return max(a,b);},[](int a,int b){return b;},0);
    rep(i,0,rem.size())minn.update(i,rem[i].second),maxx.update(i,rem[i].first);
    int ans=0;
    rep(i,0,rem.size()+1){
        int lmax2=l_0,rmin2=r_0;
        if(i==0){
            rmin2=rem[0].second;
        }
        else if(i==rem.size()){
            lmax2=maxx.query(0,rem.size());
        }
        else{
            lmax2=maxx.query(0,i); rmin2=rem[i].second;
        }
        cerr<<lmax2<<rmin2<<endl;
        chmax(ans,max(0,rmin2-lmax+1)+max(0,rmin-lmax2+1));
    }
    printf("%d\n",ans);
    return 0;
}

