void solve() {
    int n;
    cin >> n;
    vector<pair<int, int>> v(n);
    int l, r;
    REP(i, n) {
        cin >> l >> r;
        l--; r--;
        v[i] = make_pair(l, r);
    }
    sort(ALL(v));
    vector<int> lmin(n);
    vector<int> rmin(n);
    int mn = INF;
    REP(i, n) {
        chmin(mn, v[i].second);
        lmin[i] = mn;
    }
    mn = INF;
    REPR(i, n) {
        chmin(mn, v[i].second);
        rmin[i] = mn;
    }
    int ans = 0;
    REP(i, n - 1) {
        int x = lmin[i] - v[i].first + 1;
        if (x <= 0) x = 0;
        int y = rmin[i + 1] - v[n - 1].first + 1;
        if (y <= 0) y = 0;
        chmax(ans, x + y);
    }
    cout << ans << EOL;
}

