	REP(i, n - 1) {
		auto itr = lll.end();
		itr--;
		chmax(ma, *itr);
		lll.erase(itr);

		auto rrr = llr.lower_bound(lr[i].second);
		chmin(mi, *rrr);
		llr.erase(rrr);


		itr = lll.end();
		itr--;
		rrr = llr.begin();

		ll sum = max(0LL, *rrr - *itr + 1) + max(0LL, mi - ma + 1);
		chmax(ans, sum);



		auto rrr2 = llr2.begin();
		chmin(mi2, *rrr2);
		llr2.erase(rrr2);

		auto itr2 = lll2.lower_bound(lr2[i].first);
		chmax(ma2, *itr2);
		lll2.erase(itr2);

		rrr2 = llr2.begin();
		itr2 = lll2.end();
		itr2--;

		ll sum2 = max(0LL, *rrr2 - *itr2 + 1) + max(0LL, mi2 - ma2 + 1);
		chmax(ans, sum);
	}





	cout << ans << endl;


	return 0;
}

