int main(){
    int n;
    scanf("%d", &n);
    for (int i = 0; i < n; ++ i){
        scanf("%d%d", &l[i], &r[i]);
    }
    int posl = std::max_element(l, l + n) - l;
    int posr = std::min_element(r, r + n) - r;
    if (posl == posr){
        int max = 0;
        for (int i = 0; i < n; ++ i){
            if (i == posl){
                continue;
            }
            max = std::max(max, r[i] - l[i] + 1);
        }
