    for (int i = 0; i < n; ++ i){
        max = std::max(max, r[i] - l[i] + 1);
        if (i != posl && i != posr){
            p[cnt ++] = {l[i], r[i]};
            max1 = std::max(max1, r[i] - l[i] + 1);
        }
    }
    max = std::max(max, max1 + std::max(0, r[posr] - l[posl] + 1));
