ll solve(ll n, vector<pair<ll,ll>> q){
	ll l,r;
	sort(q.begin(),q.end());
	vector<ll> f1(n), f2(n);
	l = 0; r = pow(10,9);
	rep(i,n){
		if(q[i].first > l) l = q[i].first;
		if(-q[i].second < r) r = -q[i].second;
		if(l <= r){
			f1[i] = r-l+1;
		}else{
			f1[i] = 0;
		}
	}
	l = 0; r = pow(10,9);
	for(ll i(n-1);i>=0;--i){
		if(q[i].first > l) l = q[i].first;
		if(-q[i].second < r) r = -q[i].second;
		if(l <= r){
			f2[i] = r-l+1;
		}else{
			f2[i] = 0;
		}
	}
	ll ans(0);
	rep(i,n-1){
		if(f1[i] + f2[i+1] > ans ) ans = f1[i] + f2[i+1];
	}
	return ans;
}

