void f(vector<pair<int,int > > &v, ll &ans)
{
  multiset<ll> l1,r1,l2,r2;
  for(int i=0;i<v.size();i++) {l2.insert(v[i].fi);r2.insert(v[i].se);}

  for(int i=0;i<v.size()-1;i++)
  {
