signed main() {
  ios::sync_with_stdio(false); cin.tie(0);
  int n;
  cin >> n;
  vector<pair<int, int>> segs(n);
  for (int i = 0; i < n; i++) {
    cin >> segs[i].first >> segs[i].second;
    segs[i].second++;
  }
  sort(segs.begin(), segs.end());
  SegmentTree<long long> mx(LLMAX, INTMAX_UNITY, n + 10);
  SegmentTree<long long> mi(LLMIN, INTMIN_UNITY, n + 10);
  for (int i = 0; i < n; i++) {
    mx.modify(i, segs[i].first);
    mi.modify(i, segs[i].second);
  }
  int ans = 0;
  for (int i = 0; i < n; i++) {
    int x = segs[i].second - segs[i].first;
    int y = max(0LL, min(mi.get(0, i), mi.get(i + 1, n)) - max(mx.get(0, i), mx.get(i + 1, n)));
    ans = max(ans, x + y);
    int z = max(0LL, mi.get(0, i + 1) - mx.get(0, i + 1));
    int w = max(0LL, mi.get(i + 1, n) - mx.get(i + 1, n));
    ans = max(ans, z + w);
  }
  cout << ans << endl;
  return 0;
}

