void doo( vll & a ) {
    vll b(n,{0ll,0ll}); vll c(n,{0ll,0ll});
    b[0] = a[0];
    c.back() = a.back();
    FOR(i,1,n) {
        b[i] = inter(a[i],b[i-1]);
    }
    FOR(i,n-1,0) c[i] = inter(a[i],c[i+1]);
    FOR(i,0,n-1) {
        ans = max(ans,len(b[i])+len(c[i+1]));
