void solve(){
  inl(N);
  vp v(N); in(v);
  sort(all(v) );
  // 右端をsetで管理
  map<int,int> a , b;
  trc(v);
  each(x , v) b[x.second]++;
  // 切れ目は[0 , i)と[i , N)の間
  ll ans = 0;
  rep1(i , N - 1){
    P cur = v[i - 1];
    // 右端をbからaへ
    if(--(b[cur.se]) == 0) b.erase(cur.se);
    a[cur.se]++;
    each(x,a) trc("a",x);
    each(x,b) trc("b",x);
    ll aa = max(0 , (*a.begin()).fi - v[i - 1].fi + 1);
    ll bb = max(0 , (*b.begin()).fi - v[N - 1].fi + 1);
    amax(ans , aa + bb);
  }
  out(ans);
}

