template<typename T1, typename T2> inline void chmax(T1& a, T2 b) { if (a < b) a = b; }
typedef pair<int, int>P;
const int MOD = 1e9 + 7; const int MAX = 200060;
const double pi = acos(-1); const double EPS = 1e-12;
const ll INF = 1e18;

int dp1[100010];//[0,i)
int dp2[100010];//[i,N)

const int MAX_N = 1 << 18;
int n;
int dat[2 * MAX_N - 1];//セグ木を持つグローバル配列

//初期化
void init(int n_) {
	n = 1;
	//簡単のため、要素数を2のべき乗に
	while (n < n_)n *= 2;
	//gcdに影響を与えない値で初期化する
	for (int i = 0; i < 2 * n - 1; i++)dat[i] = 0;
}

//k番目の値(0-indexed)をaに更新
void update(int k, int a) {
	k += n - 1;//葉の節点
	dat[k] = a;
	//上りながら更新
	while (k > 0) {
		k = (k - 1) / 2;
		dat[k] = max(dat[k * 2 + 1], dat[k * 2 + 2]);
	}
}

//[a,b)のgcdを求める
//そとからは、(a,b,0,0,n)として呼ぶ
int query(int a, int b, int k, int l, int r) {
	//[a,b)と[l,r)が交差していなければ、gcdに影響を与えない値を返す
	//関数定義でgcdの単位元を0としている
	if (r <= a || b <= l)return 0;
	//[a,b)が[l,r)を完全に含んでいれば、この節点の値
	if (a <= l && r <= b)return dat[k];
	//そうでなければ、二つの子のgcd
	else {
		int vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
		int vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
		return max(vl, vr);
	}
}


int n2;
int dat2[2 * MAX_N - 1];//セグ木を持つグローバル配列

					   //初期化
void init2(int n_) {
	n2 = 1;
	//簡単のため、要素数を2のべき乗に
	while (n2 < n_)n2 *= 2;
	//gcdに影響を与えない値で初期化する
	for (int i = 0; i < 2 * n2 - 1; i++)dat2[i] = INF;
}

//k番目の値(0-indexed)をaに更新
void update2(int k, int a) {
	k += n - 1;//葉の節点
	dat2[k] = a;
	//上りながら更新
	while (k > 0) {
		k = (k - 1) / 2;
		dat2[k] = min(dat2[k * 2 + 1], dat2[k * 2 + 2]);
	}
}

//[a,b)のgcdを求める
//そとからは、(a,b,0,0,n)として呼ぶ
int query2(int a, int b, int k, int l, int r) {
	//[a,b)と[l,r)が交差していなければ、gcdに影響を与えない値を返す
	//関数定義でgcdの単位元を0としている
	if (r <= a || b <= l)return INF;
	//[a,b)が[l,r)を完全に含んでいれば、この節点の値
	if (a <= l && r <= b)return dat2[k];
	//そうでなければ、二つの子のgcd
	else {
		int vl = query2(a, b, k * 2 + 1, l, (l + r) / 2);
		int vr = query2(a, b, k * 2 + 2, (l + r) / 2, r);
		return min(vl, vr);
	}
}




void solve() {
	int N; cin >> N;
	vector<P>v;
	int idx = 0, mx = 0;
	init(N); init2(N);
	REP(i, N) {
		int l, r; cin >> l >> r;
		v.push_back({ r, l });
		update(i, l);
		update2(i, r);
	}
	VSORT(v);
	int l = v[0].second, r = v[0].first;
	REP(i, N) {
		l = max(l, v[i].second);
		if (l > r)break;
		dp1[i + 1] = (r - l + 1);
	}
	l = v[N - 1].second, r = v[N - 1].first;
	REPR(i, N) {
		r = min(r, v[i].first);
		l = max(l, v[i].second);
		if (l > r)break;
		dp2[i] = (r - l + 1);
	}
	ll ans = 0;
	REP(i, N) {
		int L = v[i].first - v[i].second + 1;
		int mnR = INF;
		if(i<N)mnR=query2(i + 1, N, 0, 0, n);
		if (i > 0)mnR = query2(0, i, 0, 0, n);
		int mxL = 0;
		if(i>0)mxL=query(0, i, 0, 0, n);
		if(i<N)mxL = max(mxL, query(i + 1, N, 0, 0, n));
		if (mnR >= mxL)L += (mnR - mxL + 1);
		//if (L >= 1e5)print(i);
		ans = max(ans, L);
		ans = max(ans, dp1[i] + dp2[i]);
	}
	print(ans);
}

