    // max_l = max(max_l, l[i]);
    // min_r = min(min_r, r[i]);
  }

  int max_l_ind = 0;
  int min_r_ind = 0;

  for (int i = 1; i < n; ++i) {
    if (l[i] > l[max_l_ind]) max_l_ind = i;
    if (r[i] < r[min_r_ind]) min_r_ind = i;
  }

  if (n == 2) {
    ll ans = max(r[min_r_ind] - l[max_l_ind] + 1L, 0LL);
    printf("%lld\n", ans);
    return 0;
