  // for case that a part of group is singleton
  for (int i = 0; i < n; ++i) {
    if (i == min_r_ind || i == max_l_ind) continue;

    ans = max(ans, max(r[min_r_ind] - l[max_l_ind] + 1, 0LL) + r[i] - l[i] + 1L);
