   multiset<ll,greater<ll>> lefter_left,righter_left;//左側の部分のうち、最も右側にあるものを管理する
    //始めに、0からn-1まですべての「左側」要素lefter_にinputしておく
    rep(i,n){
       lefter_left.insert(l[i]);
    }
    //最低1つはrighterに移す
    itr2 = lefter_left.find(right_sorting[n-1].second);
   lefter_left.erase(itr2);
   righter_left.insert(right_sorting[n-1].second);
   //何枚を左側の山にしておくか？1枚...n-2枚
   //結局、何番目までを右の山に残しておくかn-1,...,0
   for(int i = n - 1;i >= 1;i--){
      ll res=0;
      //右側の山について計算する
      //右側の山の左端部分は、right_sorting[i].second,右端部分はrighter_right.begin
      res +=  right_sorting[i].first - *righter_left.begin() + 1;
      //右側の山は、左端がleft_sorting[n-1].first,右端部分がrighterright.begin
      res +=  right_sorting[0].first - *lefter_left.begin() + 1;
      ll x = right_sorting[i-1].second;//移すもの
      auto itr  = lefter_left.find(x);
      lefter_left.erase(itr);
      righter_left.insert(x);
      maxs(ans,res);
   }
   cout << ans << endl;
