        // problem_i -> day1
        {
            s1 += max(get(r1) - get(l1) + 1, 0ll);
            s1 += max(get(r2) - get(l2) + 1, 0ll);
        }

        // problem_i -> day2
        {
            l1.erase(l1.find(l[i]));
            r1.erase(r1.find(r[i]));
            l2.insert(l[i]);
            r2.insert(r[i]);

            s2 += max(get(r1) - get(l1) + 1, 0ll);
            s2 += max(get(r2) - get(l2) + 1, 0ll);
        }

        if (s1 < s2) {
            ans = s2;
