int n, ans;
pair<int, int> a[100100];

int getAns(int minL, int maxL, int minR, int maxR)
{
  return max(0, maxL - minL + 1) + max(0, maxR - minR + 1);
}

void solve1()
{
  sort(a, a + n);
  vector<int> minPrefix(n), minSuffix(n);
  minPrefix[0] = a[0].second;
  for (int i = 1; i < n; i++)
    minPrefix[i] = min(minPrefix[i - 1], a[i].second);
  minSuffix[n - 1] = a[n - 1].second;
  for (int i = n - 2; i >= 0; i--)
    minSuffix[i] = min(minSuffix[i + 1], a[i].second);

  for (int i = 0; i < n - 1; i++)
    ans = max(ans, getAns(a[i].first, minPrefix[i], a[n - 1].first, minSuffix[i + 1]));
  cout << ans << endl;
}

void solve2(int minL, int maxL, vector<pair<int, int>> l, vector<pair<int, int>> r)
{
  int minR = r.back().first, maxR = r[0].second;
  for (auto u : r)
    maxR = min(maxR, u.second);
  if (minR > maxR)
  {
    cout << ans << endl;
    exit(0);
  }

  vector<pair<int, int>> intersect;
  for (auto u : l)
    if (u.second < minR)
    {
      minL = max(minL, u.first);
      maxL = min(maxL, u.second);
    }
    else intersect.push_back(u);

  if (minL > maxL)
  {
    cout << ans << endl;
    exit(0);
  }

  if (intersect.empty())
  {
    ans = max(ans, getAns(minL, maxL, minR, maxR));
    cout << ans << endl;
    exit(0);
  }

  int m = intersect.size();
  vector<int> minPrefix(m), minSuffix(m);
  minPrefix[0] = intersect[0].second;
  for (int i = 1; i < m; i++)
    minPrefix[i] = min(minPrefix[i - 1], intersect[i].second);
  minSuffix[m - 1] = intersect[m - 1].second;
  for (int i = m - 2; i >= 0; i--)
    minSuffix[i] = min(minSuffix[i + 1], intersect[i].second);

  // put all to left
  ans = max(ans, getAns(max(minL, intersect[m - 1].first), min(maxL, minPrefix[m - 1]), minR, maxR));
  // put all to right
  ans = max(ans, getAns(minL, maxL, minR, min(maxR, minPrefix[m - 1])));
  // split
  for (int i = 0; i < m - 1; i++)
    ans = max(ans, getAns(max(minL, intersect[i].first), min(maxL, minPrefix[i]), minR, min(maxR, minSuffix[i + 1])));
  cout << ans << endl;
}

