            if(pe1<pe2)
            {
                l1=max(l1,l.at(i));
                r1=min(r1,r.at(i));
            }
            else
            {
                l2=max(l2,l.at(i));
                r2=min(r2,r.at(i));
            }
        }
    }
    long long ans = max(r1-l1+1,0)+max(r2-l2+1,0);
    cout<<ans<<endl;
}

