    for(int i=0;i<N;i++){
        ll l,r;
        cin >> l >> r;
        X.push_back({l,r});
    }
    auto solve1 = [&](){
        sort(X.begin(),X.end(),[](Q& a,Q& b){
            if(a.r!=b.r) return a.r<b.r;
            else return a.l<b.l;
        });
        vector<ll> L(N),R(N),Lm(N),Rm(N);
        vector<Q> LQ(N),RQ(N);
        ll l = 0,r = 0;
        for(int i=0;i<N;i++){
            Lm[i] = max((i!=0? Lm[i-1]:0),X[i].r-X[i].l+1);
            if(i==0){
                L[i] = X[i].r-X[i].l+1;
                l = X[i].l;
                r = X[i].r;
            }else if(L[i-1]!=0){
                L[i] = max(0LL,min(X[i].r,r)-max(X[i].l,l)+1);
                l = max(X[i].l,l);
                r = min(X[i].r,r);
            }else{
                l = max(X[i].l,l);
                r = min(X[i].r,r);
                L[i] = 0;
            }
            LQ[i] = {l,r};
        }
        l = 1e9,r = 1e9;
        for(int i=N-1;i>=0;i--){
            Rm[i] = max((i!=N-1? Rm[i+1]:0),X[i].r-X[i].l+1);
            if(i==N-1){
                R[i] = X[i].r-X[i].l+1;
                l = X[i].l,r = X[i].r;
            }else if(R[i+1]!=0){
                R[i] = max(0LL,min(X[i].r,r)-max(X[i].l,l)+1);
                l = max(X[i].l,l);
                r = min(X[i].r,r);
            }else{
                l = max(X[i].l,l);
                r = min(X[i].r,r);
                R[i] = 0;
            }
            RQ[i] = {l,r};
        }
        ll ans = 0;
        for(int i=0;i<N-1;i++){
            ans = max({ans,L[i]+R[i+1],Lm[i],Rm[i+1]});
            if(i!=0){
                if(RQ[i+1].r<RQ[i+1].l) continue;
                if(LQ[i-1].r<LQ[i-1].l) continue;
                ll add = max(0LL,min(RQ[i+1].r,LQ[i-1].r)-max(RQ[i+1].l,LQ[i-1].l));
                ans = max(ans,X[i].r-X[i].l+1+add);
            }
        }
        return ans;
    };
    cout << solve1() << endl;
}

