using pii = pair<int, int>;

pii merge(pii p1, pii p2) {
	int x = max(p1.first, p2.first);
	int y = min(p1.second, p2.second);
	if (x > y) y = x;
	return pii(x, y);
}

int count(pii p) {
	return p.second - p.first;
}

int main() {
	int N; cin >> N;
	vector<pii> LR(N);
	for (int i = 0; i < N; ++i)
		cin >> LR[i].first >> LR[i].second;
	for (int i = 0; i < N; ++i)
		++LR[i].second;
	sort(LR.begin(), LR.end());

	vector<pii> from_front(N + 1), from_back(N + 1);
	from_front[1] = LR[0];
	for (int i = 2; i <= N; ++i)
		from_front[i] = merge(from_front[i - 1], LR[i - 1]);
	from_back[1] = LR[N - 1];
	for (int i = 2; i <= N; ++i)
		from_back[i] = merge(from_back[i - 1], LR[N - i]);

	int res = 0;
	for (int i = 1; i <= N - 1; ++i) {
		// 前からi個出題
		int tmp = count(from_front[i]);
		// 後ろからN-i個出題
		tmp += count(from_back[N - i]);
		res = max(res, tmp);
	}

	for (int i = 0; i < N; ++i) {
		pii others(-1, (1 << 30));
		if (i > 0) others = merge(others, from_front[i]);
		if (i < N - 1) others = merge(others, from_back[N - i - 1]);
		int tmp = count(LR[i]);
		tmp += count(others);
		res = max(res, tmp);
	}

}

