	std::vector<int> a, b;
	for(auto p : ranges) {
		//std::cout << "[" << p.first << ", " << p.second << ")\n";
		a.push_back(p.first);
		b.push_back(-p.second);
	}
	SegmentTree<Node, int> A, B;
	A.init(a);
	B.init(b);
	for(int i = 1; i < n; i++) {
