#include "bits/stdc++.h"
using namespace std;

int main()
{
	int N;
	cin >> N;
	vector<pair<int64_t, int>> R(0);
	vector<int64_t> L(0);
	for (int i = 0; i < N; i++)
	{
		int64_t r, l;
		cin >> l >> r;
		L.push_back(l);
		R.push_back(pair<int64_t, int>(r, i));
	}
	//sort(L.begin(), L.end());
	sort(R.begin(), R.end());

	//ilu[n]はR[n]までを一方に入れたときのありうるLの一番大きい(範囲が狭くなる)値
	vector<int64_t> ilu(N);
	ilu[0] = L[R[0].second];
	for (int i = 1; i < N; i++)
	{
		ilu[i] = max(ilu[i - 1], L[R[i].second]);
	}
	//iln[n]はR[n]までを一方に入れたときの残りのLの一番大きい(範囲が狭くなる)値
	vector<int64_t> iln(N - 2);
	if (N >= 3)
		iln[N - 3] = L[R[N - 1].second];
	for (int i = N - 4; i >= 0; i--)
	{
		iln[i] = max(iln[i + 1], L[R[i + 2].second]);
	}
	//vector<int64_t> fun(N);
	int64_t fun = 0;
	for (int i = 0; i < N - 1; i++)
	{
		int64_t f;
		if (i == N - 2) {
			f = max(R[0].first - ilu[i]+1,0ll) + R[i + 1].first - L[R[i + 1].second]+1;
		}
		else if (ilu[i] >= L[R[i + 1].second])
		{
			f = max(R[0].first - max(iln[i], ilu[i])+1,0ll) + (R[i + 1].first - L[R[i + 1].second]+1);
		}
		else {
			f = max(R[0].first - ilu[i]+1,0ll) + max(R[i + 1].first - max(iln[i], L[R[i + 1].second])+1,0ll);
		}
		fun = max(fun, f );
	}
	cout << fun;
	return 0;
}

