// solve
signed main(){

    cin >> N;
    maxL = -inf;
    minR = inf;
    rep(i, N){
        cin >> L[i] >> R[i];
        if(chmax(maxL, L[i]))posL = i;
        if(chmin(minR, R[i]))posR = i;
    }

    int answer = -inf;
    {
        int ma = -inf;
        rep(i, N)chmax(ma, max(R[i] - L[i] + 1, 0ll));
        chmax(answer, ma + max(minR - maxL + 1, 0ll));
    }

    // 1 に maxL, 2 に minR がある
    int R1 = R[posL], L2 = L[posR];
    int score1 = R1 - maxL + 1, score2 = minR - L2 + 1;
    vector<int> dif1(N, 0), dif2(N, 0);
    rep(i, N){
        if(i == posL || i == posR)continue;
        dif1[i] = score1 - max(min(R1, R[i]) - maxL + 1, 0ll);
        dif2[i] = score2 - max(minR - max(L2, L[i]) + 1, 0ll);
    }

    // int ma1 = -inf, ma2 = -inf;
    // int po1 = -1, po2 = -1;
    // rep(i, N){
    //     if(chmax(ma1, dif1[i]))po1 = i;
    //     if(chmax(ma2, dif2[i]))po2 = i;
    // }

    vector<int> ord(N);
    iota(all(ord), 0);
    sort(all(ord), [&](int i, int j){
        return dif1[i] > dif1[j];
    });

    int minimum = inf * 2, maximum = 0;
    rep(k, N){
        int i = ord[k];
        chmin(minimum, dif1[i] + maximum);
        chmax(maximum, dif2[i]);
    }
    chmin(minimum, maximum);

    chmax(answer, score1 + score2 - minimum);
    cout << answer << '\n';

}

