using Left = map<ll, ll, greater<ll>>;
using Right = map<ll, ll>;

int main() {
    ll N;
    cin >> N;
    V<PLL> LR(N);
    for(ll i = 0; i < N; i++) {
        ll l, r;
        cin >> l >> r;
        LR[i] = PLL(l - 1, r);
    }

    ll ans = 0;

    auto calc_range = [](Left &left, Right &right) {
        return max<ll>(0, right.begin()->first - left.begin()->first);
    };

    {
        Left left;
        Right right;
        for(auto &&ele : LR) {
            ll l, r;
            tie(l, r) = ele;
            update(left, l, true);
            update(right, r, true);
        }
        for(ll i = 0; i < N; i++) {
            ll l, r;
            tie(l, r) = LR[i];
            update(left, l, false);
            update(right, r, false);
            chmax(ans, (r - l) + calc_range(left, right));
            update(left, l, true);
            update(right, r, true);
        }
    }

    sort(ALL(LR), 
         [](PLL a, PLL b) {
             if(a.first != b.first) return b < a;
             else return a < b;
         });

    {
        Left left_a, left_b;
        Right right_a, right_b;
        for(auto &&ele : LR) {
            ll l, r;
            tie(l, r) = ele;
            update(left_b, l, true);
            update(right_b, r, true);
        }

        for(ll i = 0; i < N - 1; i++) {
            ll l, r;
            tie(l, r) = LR[i];
            update(left_a, l, true);
            update(right_a, r, true);
            update(left_b, l, false);
            update(right_b, r, false);
            chmax(ans, calc_range(left_a, right_a) + calc_range(left_b, right_b));
        }
    }

    cout << ans << endl;
    return 0;
}

