ll a[maxn][18],b[maxn][18];
bool comp(node a,node b){
	if(a.l == b.l) return a.r > b.r;
	return a.l > b.l;
}

inline ll maxq(int l,int r){
	int k = (int)(log(double(r-l+1))/log((double)2));
	return max(a[l][k],a[r-(1<<k)+1][k]);
}

inline ll minq(int l,int r){
	int k = (int)(log(double(r-l+1))/log((double)2));
	return min(b[l][k],b[r-(1<<k)+1][k]);
}

int main(){
	int n;
	scanf("%d",&n);
	for(int i = 1;i <= n;++i) scanf("%lld%lld",&s[i].l,&s[i].r);
	sort(s+1,s+n+1,comp);

	for(int i = 1;i <= n;++i) a[i][0] = s[i].l,b[i][0] = s[i].r;

	for(int i = 1;(1 << i) <= n;++i){
		for(int j = 1;j+(1 << i)-1 <= n;++j){
			a[j][i] = max(a[j][i-1],a[j+(1 << (i-1))][i-1]);
			b[j][i] = min(b[j][i-1],b[j+(1 << (i-1))][i-1]);
		}
	}

	ll ans = 0;
	for(int i = 1;i <= n-1;++i) ans = max(ans,(minq(1,i)-maxq(1,i))+(minq(i+1,n)-maxq(i+1,n))+2);
