/* constant */

const int MAX_N = 100000;

/* typedef */

typedef pair<int,int> pii;

/* global variables */

pii ps[MAX_N];
int lrms[MAX_N], rrms[MAX_N];

/* subroutines */

bool cmplr(const pii &a, const pii &b) {
  return a.first < b.first || (a.first == b.first && a.second > b.second);
}

/* main */

int main() {
  int n;
  scanf("%d", &n);

  for (int i = 0; i < n; i++)
    scanf("%d%d", &ps[i].first, &ps[i].second), ps[i].first--;
  sort(ps, ps + n, cmplr);

  lrms[0] = ps[0].second;
  for (int i = 1; i < n; i++)
    lrms[i] = min(lrms[i - 1], ps[i].second);

  rrms[n - 1] = ps[n - 1].second;
  for (int i = n - 2; i >= 0; i--)
    rrms[i] = min(rrms[i + 1], ps[i].second);

  int maxe = 0;
  for (int k = 1; k < n; k++) {
    int l0 = ps[k - 1].first, r0 = lrms[k - 1];
    int l1 = ps[n - 1].first, r1 = rrms[k];
    int e = max(r0 - l0, 0) + max(r1 - l1, 0);
    if (maxe < e) maxe = e;
  }

  int mine = max(lrms[n - 1] - ps[n - 1].first, 0);
  for (int i = 0; i < n; i++) {
    int e = mine + (ps[i].second - ps[i].first);
    if (maxe < e) maxe = e;
  }

  printf("%d\n", maxe);
  return 0;
}

