const int dx[4] = {-1, 0, 1, 0};
const int dy[4] = {0, -1, 0, 1};


struct SegmentTreeMIN{
  ll n;
  vll tree;

  SegmentTreeMIN(ll len){
    n=1;
    while(len>n)
      n*=2;

    tree.assign(2*n-1, LLINF);
  }

  void update(ll index, ll value){
    index += n-1;
    tree[index] = value;

    while(index>0){
      index=(index-1)/2;
      tree[index] = min(tree[index*2+1], tree[index*2+2]);
    }
  }


  //[a, b)
  ll query(ll a, ll b){
    return query(a,b,0,0,n);
  }

  ll query(ll a, ll b, ll index, ll l, ll r){
    if(b<=l || r<=a)
      return LLINF;

    if(a<=l && r<=b)
      return tree[index];

    ll value_l = query(a,b,2*index+1,l,(l+r)/2);
    ll value_r = query(a,b,2*index+2,(l+r)/2,r);
    return min(value_l, value_r);
  }
};


int main(){
  ios_base::sync_with_stdio(false);
  cin.tie(NULL);

  ll n;
  cin>>n;
  vll l(n),r(n);
  REP(i,n)cin>>l[i]>>r[i];

  ll p=-LLINF,q=LLINF;
  REP(i,n){
    p=max(p,l[i]);
    q=min(q,r[i]);
  }

  ll ans=0;
  //p,qが同一グループ
  REP(i,n)ans=max(ans,r[i]-l[i]+1);
  ans+=max(0LL,q-p+1);

  //p,qが別グループ
  vpl t(n);
  REP(i,n){
    t[i].FI=max(r[i]-p+1,0LL);
    t[i].SE=max(q-l[i]+1,0LL);
  }
  auto ord=[](pll a, pll b){
    if(a.FI<b.FI)
      return true;
    if(a.FI>b.FI)
      return false;

    if(a.SE<b.SE)
      return false;
    if(a.SE>=b.SE)
      return true;
    return true;
  };

  sort(ALL(t),ord);

  SegmentTreeMIN seg(n);
  REP(i,n)seg.update(i,t[i].SE);
  REP(i,n){
    if(i==0)
      continue;
    ll now=t[i].FI+seg.query(0,i);
    ans=max(ans,now);
  }


  cout<<ans<<endl;
}

