		pref[i + 1] = max(0LL, min_end - inv[i].ST + 1);
	}

	min_end = 1e9 + 1;
	for(int i = n - 1; i >= 1; i--) {
		min_end = min(min_end, inv[i].ND);
		LL suff = max(0LL, min_end - inv[n - 1].ST + 1);
		ans = max(ans, pref[i] + suff);
	}

	cout << ans << "\n";
}

