int N;
int solve(vector<pair<int, int>> prs) {
    int ret = 0;
    sort(all(prs));

    vector<int> v1, v2;
    vector<pair<int, int>> prs1, prs2;
    int low = 0;
    int high = INT_MAX;
    for (auto it = prs.begin(); it != prs.end(); it++) {
        low = max(low, it->first);
        high = min(high, it->second);
        v1.push_back(high - low + 1);
        prs1.push_back(mp(low, high));
    }

    low = 0;
    high = INT_MAX;
    for (auto it = prs.rbegin(); it != prs.rend(); it++) {
        low = max(low, it->first);
        high = min(high, it->second);
        v2.push_back(high - low + 1);
        prs2.push_back(mp(low, high));
    }
    reverse(all(v2));

    rep(i, N - 1) {
        ret = max(ret, v1[i] + v2[i + 1]);
    }

    low = 0;
    high = INT_MAX;

    REP(i, 1, N - 2) {
        low = max(low, prs[i - 1].first);
        high = min(high, prs[i - 1].second);

        int mlow = prs[i].first;
        int mhigh = prs[i].second;

        int bestVal = 0;
        for (int j = i; j < N; j++) {
            mlow = max(mlow, prs[j].first);
            mhigh = min(mhigh, prs[j].second);
            int tmplow = max(low, prs2[j + 1].first);
            int tmphigh = min(high, prs[j + 1].second);

            int val = max(0LL, mhigh - mlow + 1) + max(0LL, tmphigh - tmplow + 1);
            if (val > bestVal) {
                bestVal = val;
            } else break;
        }
        ret = max(ret, bestVal);
    }

    return ret;
}

int solve2(vector<pair<int, int>> prs1) {
    auto prs2 = prs1;

    int idx1 = 0;
    int idx2 = 0;
    sort(all(prs1));
    sort(all(prs2), [](pair<int, int> &p1, pair<int, int> &p2) {
        if (p1.second != p2.second) return p1.second < p2.second;
        return p1.first < p2.first;
    });

    set<int> divs;
    multiset<int> low1, low2, high1, high2;
    for (auto &pr : prs1) {
        divs.insert(pr.first);
        divs.insert(pr.second);
        low1.insert(pr.first);
        high1.insert(pr.second);
    }

    int ret = 0;
    for (auto num : divs) {
        while (idx1 < N && prs1[idx1].first == num) {
            low2.insert(prs1[idx1].first);
            high2.insert(prs1[idx1].second);
            low1.erase(low1.find(prs1[idx1].first));
            high1.erase(high1.find(prs1[idx1].second));
            idx1++;
        }

        if (!low1.empty() && !low2.empty()) {
            auto it1 = low1.end();
            auto it2 = low2.end();
            it1--;
            it2--;

            int val = max(0LL, *high1.begin() - *it1 + 1) + max(0LL, *high2.begin() - *it2 + 1);
            ret = max(ret, val);
        }

        while (idx2 < N && prs2[idx2].second == num) {
            low2.erase(low2.find(prs2[idx2].first));
            high2.erase(high2.find(prs2[idx2].second));
            low1.insert(prs2[idx2].first);
            high1.insert(prs2[idx2].second);
            idx2++;
        }
    }

    return ret;
}

