    vector<pair<int, int>> prs(N);
    rep(i, N) {
        cin >> prs[i].first >> prs[i].second;
    }

    int ret = 0;
    ret = solve(prs);

    ret = max(ret, solve2(prs));

    cout << ret << endl;

    return 0;
}

