            lb = t1;
        }
        else {
            if(ub == t2) { break; }
            ub = t2;
        }
#endif
    }

    ll ret = -LLINF;
    for(ll i = lb; i <= ub; ++i) {
        ll cand = GetFun(l_min, R[i]);
        ret = max(ret, GetFun(l_min, R[i]));
    }
    return ret;
}


ll fromLeft(ll r_max) {
    ll lb = 0, ub = L.size() - 1;
    while(ub - lb > 2000) {
        // 1000 分探索
        ll sub = (ub - lb) / 1000;
        ll next_val = -LLINF;
        ll next_ind = -1;
        for(int i = lb; i <= ub; i += sub) {
            ll cand_val = GetFun(L[i], r_max);
            if(next_val < cand_val) {
