#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int getValue(int first, int last, vector<pair<pair<int, int>, int>>& lrv)
{
	int n = lrv.size() - 1;
	int l = lrv[last].first.first;
	int r = lrv[last].first.second;
	for (int i = first; i < last; ++i)
	{
		if (l < lrv[i].first.first) {
			l = lrv[i].first.first;
		}
		if (lrv[i].first.second < r) {
			r = lrv[i].first.second;
		}
		if (r < l) {
			return 0;
		}
	}

	int ret = r - l + 1;
	if (ret < 0) {
		return 0;
	}
	else {
		return ret;
	}
}

int main()
{
	int n;
	cin >> n;


	vector<pair<pair<int, int>, int>> lrv(n);
	for (int i = 0; i < n; ++i) {
		cin >> lrv[i].first.first >> lrv[i].first.second;
		lrv[i].second = lrv[i].first.second - lrv[i].first.first + 1;
	}

	sort(lrv.begin(), lrv.end(), [](const pair<pair<int, int>, int>& a, const pair<pair<int, int>, int>& b)
	{
		return a.second > b.second;
	});

	// デバッグ
	//for (auto& i : lrv) {
	//	cout << i.first.first << " " << i.first.second << " " << i.second << endl;
	//}
	//system("pause");
	//return 0;

	// T1 + L1 をもとめる
	int last = n - 1;
	int ret = lrv[0].second + getValue(1, last, lrv);

	int count = 0;
	int roopCount = 1;
	int temp = 0;
	while ( (count + roopCount <= last) && (lrv[0].second == lrv[roopCount].second) ) {
		swap(lrv[0], lrv[roopCount]);
		temp = lrv[0].second + getValue(1, last, lrv);
		if (ret < temp) {
			ret = temp;
		}
		else {
			swap(lrv[0], lrv[roopCount]);
		}
		++roopCount;
	}

	++count;
	while (count < last) {
		// T2 + L1
		// T3 + L1
		// T1 + L1を超える可能性がある所まで繰り返す
		temp = lrv[count].second + lrv[last].second;
		if (ret < temp) {
			temp = getValue(0, count, lrv) + getValue(count + 1, last, lrv);
			if (ret < temp) {
				ret = temp;
			}
			roopCount = 1;
			while ((count + roopCount <= last) && (lrv[count].second == lrv[count + roopCount].second)) {
				swap(lrv[count], lrv[count+roopCount]);
				temp = getValue(0, count, lrv) + getValue(count + 1, last, lrv);
				if (ret < temp) {
					ret = temp;
				}
				else {
					swap(lrv[count], lrv[count + roopCount]);
				}
				++roopCount;
			}

			++count;
		}
		else {
			break;
		}
	}

	cout << ret << endl;

	return 0;
}

