            tie(l, r) = ele;
            update(left_b, l, true);
            update(right_b, r, true);
        }

        for(ll i = 0; i < N - 1; i++) {
            ll l, r;
            tie(l, r) = LR[i];
            update(left_a, l, true);
            update(right_a, r, true);
            update(left_b, l, false);
            update(right_b, r, false);
            chmax(ans, (right_b.begin()->first - left_b.begin()->first) + 
                       (right_a.begin()->first - left_a.begin()->first));
        }
    }

    cout << ans << endl;
    return 0;
}

