pair<int , int> per(pair<int , int> a , pair<int , int> b)
{
	return {max(a.x , b.x) , min(a.y , b.y)};
}
int f(vector<pair<int , int> > v)
{
	vector<pair<int , int> > pp(n) , ps(n);
	pp[0] = v[0];
	for(int i = 1; i < n; i++)
		pp[i] = per(v[i] , pp[i - 1]);
	ps[sz(v) - 1] = v[sz(v) - 1];
	for(int i = n - 2; i >= 0; i--)
		ps[i] = per(v[i] , ps[i + 1]);
	int res = 0;
	for(int i = 0; i < n - 1; i++)
		res = max(res , pp[i].y - pp[i].x + 1 + ps[i + 1].y - ps[i + 1].x + 1);
	for(int i = 1; i < n - 1; i++)
	{
		auto z = per(pp[i - 1] , ps[i + 1]);
		res = max(res , z.y - z.x + 1 + v[i].y - v[i].x + 1);
	}
	return res;
}
bool cmp(pair<int , int> a , pair<int , int> b)
{
	if(a.y != b.y)
	{
		return a.y < b.y;
	}
	return a.x < b.x;
}
