        int id = ord[i];

        while (r.back() > R[id]) {
            r.pop_back();
            idx.pop_back();
        }
        r.push_back(R[id]);
        idx.push_back(id);
    }

    int m = idx.size();
    for (int i = 0; i+1 < m; ++i) {
        chmax(ans, (R[idx[0]] - L[idx[i]] + 1) +
                   (R[idx[i+1]] - L[idx[m-1]] + 1));
    }

    cout << ans << endl;

    return 0;
}

