struct Line {
    Line(ll l, ll r, ll id) : l(l), r(r), id(id) {}
    Line() : Line(0, 0, -1) {}
    ll l, r, id;
    ll len() { assert(r >= l); return r - l; }
    bool contains(ll x) { return x >= l && x < r; }
    Line intersect(const Line& other) {
        Line res;
