        ll right_r = right.r;
        if (!right_ends.empty()) right_r = min(right_r, *right_ends.begin());
        ll right_len = max(0LL, (right_r - right.l));
        upd(ans, left_len + right_len);
    };

    kek();
    ll big_size = sz(big);
    for (ll i = 0; i < big_size; ++i) {
        left = left.intersect(big[i]);
        right_ends.erase(right_ends.find(big[i].r));
        kek();
    }

    cout << ans << endl;
    print_time();
    return 0;
}

