int x,y;

int32_t main(){
	fast;

	cin>>N;

	FOR(i,0,N-1) cin>>A[i].f>>A[i].s;

	if (N == 2){
		cout<<max((int)0,A[0].s - A[0].f + 1) + max((int)0,A[1].s - A[1].f + 1);
		return 0;
	}
	sort(A,A+N);
	stmn[N-1] = A[N-1].s;

	DEC(i,N-2,0) stmn[i] = min(stmn[i+1],A[i].s);

	multiset <int> st;
	if (N > 2) st.insert(A[0].s), st.insert(A[1].s);

	int ans = 0;

	FOR(i,2,N-2){
		//When 1st && 2nd >= 0

		auto it = st.upper_bound(stmn[i+1]);

		if (it != st.end()){
			y = *it;

			if (it == st.begin()) x = *(++st.begin());
			else x = *st.begin();

			ans = max(ans,max(x - A[i].f + 1,(ll)0) + max(y - A[N-1].f + 1,(ll)0));
		}

		if (it != st.begin()){
			it--;
			y = *it;

			if (it == st.begin()) x = *(++st.begin());
			else x = *st.begin();

			ans = max(ans,max(x - A[i].f + 1,(ll)0) + max(y - A[N-1].f + 1,(ll)0));
		}

		//When x is the min

		x = *st.begin();
		y = min(*(--st.end()),stmn[i+1]);

		ans = max(ans,max(x - A[i].f + 1,(ll)0) + max(y - A[N-1].f + 1,(ll)0));

		//When y is the min

		y = min(*st.begin(),stmn[i+1]);
		x = *(--st.end());

		ans = max(ans,max(x - A[i].f + 1,(ll)0) + max(y - A[N-1].f + 1,(ll)0));

		y = *st.begin();
		x = *(++st.begin());

		ans = max(ans,max(x - A[i].f + 1, (ll)0) + max(y - A[N-1].f + 1, (ll) 0));

		x = *st.begin();
		y = *(++st.begin());

		ans = max(ans,max(x-A[i].f+1,(ll)0) + max(y - A[N-1].f + 1, (ll)0));

		y = *st.begin();
		x = *(--st.end());

		ans = max(ans,max(x-A[i].f+1,(ll)0) + max(y - A[N-1].f + 1, (ll)0));

		swap(x,y);
		ans = max(ans,max(x-A[i].f+1,(ll)0) + max(y - A[N-1].f + 1, (ll)0));



		//When 1st < 0 && 2nd >= 0

		y = min(*(--st.end()),stmn[i+1]);
		ans = max(ans,y-A[N-1].f + 1);

		//When 1st >= 0 && 2nd < 0

		x = *(--st.end());
		ans = max(ans,x - A[i].f + 1);

		//~ if (ans == 1684659760){
			//~ cout<<'d';
			//~ return 0;
		//~ }


		st.insert(A[i].s);
	}

	pi pre[maxn],suff[maxn];

	pre[0] = A[0];
	suff[N-1] = A[N-1];
	FOR(i,1,N-1) pre[i] = pi(max(pre[i-1].f,A[i].f),min(pre[i-1].s,A[i].s));
	DEC(i,N-2,0) suff[i] = pi(max(suff[i+1].f,A[i].f),min(suff[i+1].s,A[i].s));

	//If take 1st 2
	if (N >= 2){
		if (N > 2) ans = max(ans,max((int)0,suff[2].s - suff[2].f + 1) + max((int)0,pre[1].s - pre[1].f + 1));
		else ans = max(ans,max((int)0,pre[1].s - pre[1].f + 1));

		//~ if (ans == 1684659760){
			//~ cout<<'e';
			//~ return 0;
		//~ }

	}

	FOR(i,0,N-1){
		pi range;
		if (i == 0) range = suff[i+1];
		else if (i == N-1) range = pre[i-1];
		else range = pi(max(pre[i-1].f,suff[i+1].f),min(pre[i-1].s,suff[i+1].s));

		ans = max(ans, max(A[i].s - A[i].f + 1, (int)0) + max(range.s - range.f + 1,(int)0));
	}
	cout<<ans;



}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef pair<int, int> pii;
typedef pair<ll, ll> pll;

const int MAXN = 1e5;

struct Line { int L, R; };

int N;
Line A[MAXN+10];
int ans, val[MAXN+10];

int main()
{
    int i, j;

    scanf("%d", &N);
    for(i=1; i<=N; i++) scanf("%d%d", &A[i].L, &A[i].R);

    if(N==2)
    {
        printf("%d", A[1].R-A[1].L+A[2].R-A[2].L+2);
        return 0;
    }

    int l=-1, r=1e9+1;
    for(i=1; i<=N; i++) l=max(l, A[i].L), r=min(r, A[i].R);

    pii pl={-1, 0}, pr={1e9+1, 0};
    int nl, nr;
    for(i=1; i<=N; i++)
    {
        if(A[i].R==r) pl=max(pl, pii(A[i].L, i));
        if(A[i].L==l) pr=min(pr, pii(A[i].R, i));
    }
    nl=pl.second; nr=pr.second;

    int flag=-1;
    for(i=1; i<=N; i++) if(A[i].L==l && A[i].R==r) flag=i;
    if(flag!=-1) for(i=1; i<=N; i++) if(i!=flag) ans=max(ans, A[i].R-A[i].L+r-l);

    vector<Line> V;
    for(i=1; i<=N; i++) if(i!=nr) V.push_back(A[i]);

    sort(V.begin(), V.end(), [&](const Line &p, const Line &q) { return p.R>q.R; });

    int ql=-1, qr=1e9+1;
    for(i=V.size()-1; i>=0; i--)
    {
        ql=max(ql, V[i].L);
        qr=min(qr, V[i].R);
        val[i]=qr-ql;
    }
    ql=A[nr].L, qr=A[nr].R;
    for(i=0; i<V.size(); i++)
    {
        ans=max(ans, qr-ql+val[i]);
        ql=max(ql, V[i].L);
        qr=min(qr, V[i].R);
    }

    ans+=2;
    printf("%d", ans);
}

