    if(K[i+1].first-K[i].second<K[i].first+mnq){
      chmax(ans,K[i].first+mnq);
      break;
    }
    else{
      chmin(mnq,-K[i].second);
    }
    if(i==N-3) chmax(ans,P[0]+mnq);
  }

  co(ans);
  return 0;
}

