ll L[SIZE], R[SIZE];

void solve(){
	int N; cin >> N;
	ll mxL = 0, mnR = 1e9 + 10;
	for(int i = 0; i < N; i++){
		cin >> L[i] >> R[i];
		mxL = max(mxL, L[i]);
		mnR = min(mnR, R[i]);
	}
	Rpref[0] = Lpref[N + 1] = 1e9 + 10;
	Lpref[0] = Lsuff[N + 1] = -(1e9 + 10);
	for(int i = 0; i < N; i++){
		Lpref[i + 1] = max(Lpref[i], L[i]);
		Rpref[i + 1] = min(Rpref[i], R[i]); 
	}
	for(int i = N; i > 0; i--){
		Lsuff[i] = max(Lsuff[i + 1], L[i - 1]); 
		Rsuff[i] = min(Rsuff[i + 1], R[i - 1]);
	}
	ll ans = 0;
	for(int i = 1; i <= N; i++){
		ll cur = (R[i - 1] - L[i - 1] + 1) + max(0LL, min(Rpref[i - 1], Rsuff[i + 1]) - max(Lpref[i - 1], Lsuff[i + 1]) + 1);
		ans = max(cur, ans);
	}
	vector<pair<ll,ll>> ev;
	for(int i = 0; i < N; i++){
		ev.push_back(mp(L[i], R[i]));
	}
	sort(all(ev));
	for(int i = N - 1; i > 0; i--){
		ev[i - 1].second = min(ev[i].second, ev[i - 1].second);
	}

	for(int i = 0; i + 1 < N; i++){
		ll cur = max(0LL, (mnR - ev[i].first + 1)) + max(0LL, (ev[i + 1].second - mxL + 1));
		ans = max(ans, cur);
	}
	cout << ans << endl;
}

