template <class Monoid, class Function>
class SegmentTree {
 public:
  SegmentTree(const std::vector<Monoid>& data, Monoid identity_element,
              Function function)
      : identity_element_(identity_element), data_(data), function_(function) {
    build();
  }

  void update(int pos, Monoid new_value) {
    assert(0 <= pos && pos < n_);
    pos += n_;
    node_[pos] = new_value;
    while (pos > 0) {
      pos >>= 1;
      node_[pos] = function_(node_[2 * pos], node_[2 * pos + 1]);
    }
  }

  // return function_[l, r)
  // if l >= r, return identity_element_
  Monoid query(int l, int r) {
    assert(0 <= l && l < n_ && 0 <= r && r < n_ + 1);
    Monoid vl = identity_element_, vr = identity_element_;
    for (l += n_, r += n_; l < r; l >>= 1, r >>= 1) {
      if (l & 1) vl = function_(vl, node_[l++]);
      if (r & 1) vr = function_(node_[--r], vr);
    }
    return function_(vl, vr);
  }

  Monoid operator[](int pos) const {
    assert(0 <= pos && pos < n_);
    return node_[n_ + pos];
  }

 private:
  int n_;
  Monoid identity_element_;
  std::vector<Monoid> data_;
  std::vector<Monoid> node_;
  Function function_;

  void build() {
    int SIZE = data_.size();
    n_ = 1;
    while (n_ < SIZE) {
      n_ <<= 1;
    }
    node_.assign(2 * n_, identity_element_);
    for (int i = 0; i < SIZE; ++i) {
      node_[i + n_] = data_[i];
    }
    for (int i = n_ - 1; i > 0; --i) {
      node_[i] = function_(node_[2 * i], node_[2 * i + 1]);
    }
  }
};


int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  int n; cin >> n;
  vector<pii> v;
  for (int i = 0; i < n; ++i) {
    int l, r; cin >> l >> r;
    v.emplace_back(l, r);
  }

  int ans = 0;

  sort(all(v));

  auto f = [](pii x, pii y) {
    if (max(x.first, y.first) > min(x.second, y.second)) {
      return (pii){-1, -1};
    } else {
      return (pii){max(x.first, y.first), min(x.second, y.second)};
    }
  };

  constexpr int inf = (int)1e9 + 5;

  SegmentTree<pii, decltype(f)> seg(v, (pii){-inf, inf}, f);

  auto cnt = [](pii p) -> int {
    if (p == (pii){-1, -1}) {
      return 0;
    } else {
      return p.second - p.first + 1;
    }
  };

  for (int i = 1; i < n; ++i) {
    ans = max(ans, cnt(seg.query(0, i)) + cnt(seg.query(i, n)));
  }

  for (int i = 1; i < n - 1; ++i) {
    ans = max(ans, cnt(seg[i]) + cnt(f(seg.query(0, i), seg.query(i + 1, n))));
  }

  cout << ans << endl;

  return 0;
}

