#define ALL(x) x.begin(), x.end()

const llong inf = 1'000'000'000'000'007ll;
const llong mod = 1e9+7;

struct data {
	llong L;
	llong R;

	data() = default;
	data(llong L, llong R) :
		L(L),
		R(R)
	{}

	bool operator<(const data &ri) const {
		// return R - L < ri.R - ri.L;
		return R == ri.R ?
			L < ri.L :
			R < ri.R;
	}
	bool operator==(const data &an) const {
		return L == an.L && R == an.R;
	}
};

llong N;
vector<data> tasks;

llong score(data d) {
	if (d.R == inf || d.L == -inf || d.L > d.R) return -inf;

	return d.R - d.L + 1;
}

int main() {
	cin >> N;
	tasks.resize(N);
	for (auto &task: tasks) {
		cin >> task.L >> task.R;
	}
	sort(ALL(tasks));

	vector<data> left, right;
	left.push_back(data(-inf, inf));
	right.push_back(data(-inf, inf));
	for (int i = 0; i < N; ++i) {
		left.push_back(data(max(left.back().L, tasks[i].L), min(left.back().R, tasks[i].R)));
		right.push_back(data(max(right.back().L, tasks[N-i-1].L), min(right.back().R, tasks[N-i-1].R)));
	}

	llong ret = 0;
	for (int i = 1; i < N; ++i) {
		data d(max(left[i-1].L, right[N-i+1].L), min(left[i-1].R, right[N-i+1].R));

		ret = max({ret, score(left[i]) + score(right[N-i]), score(tasks[i-1]) + score(d)});
	}

	cout << ret << endl;

	return 0;
}


