long long bruteforce(int n) {
	long long ret = 0;
	for(int mask=0; mask<(1<<n); mask++) {
		long long l1=0, r1=1e9, l2=0, r2=1e9;
		for(int j=0;j<n;j++) {
			if((mask>>j)&1) {
				l1=max(l1,a[j].first);
				r1=min(r1, a[j].second);
			}
			else {
				l2=max(l2,a[j].first);
				r2=min(r2, a[j].second);
			}
		}
		if(r1==1e9 || r2==1e9) continue;
		long long way1 = max(0LL, r2-l2+1);
		long long way2 = max(0LL, r1-l1+1);
		ret=max(ret, way1+way2);
	}
	return ret;
}

