	while(c<'0' || c>'9'){
		if(c=='-') f=-1; c=getchar();
	}
	while(c>='0' && c<='9'){
		x=(x<<3ll)+(x<<1ll)+c-'0'; c=getchar();
	}return x*f;
}
void Chkmin(LL &x,LL y){
	if(y<x) x=y;
}
void Chkmax(LL &x,LL y){
	if(y>x) x=y;
}
LL add(LL x,LL y){
	return x+=y,x>=mod?x-mod:x;
}
LL dec(LL x,LL y){
	return x-=y,x<0?x+mod:x;
}
LL mul(LL x,LL y){
	return 1ll*x*y%mod;
}
struct node{
	LL l, r;
}a[maxn],b[maxn],c[maxn];
LL n,ans;
LL vis[maxn],pre[maxn],nxt[maxn];
bool cmp1(node A,node B){
	return A.l<B.l || (A.l==B.l && A.r<B.r);
}
int main(){
    n=Read();
    for(LL i=1;i<=n;++i){
    	LL l(Read()),r(Read());
    	a[i]=(node){l,r};
    	ans=std::max(ans,r-l+1);
	}
	std::sort(a+1,a+1+n,cmp1);
	for(LL i=1;i<=n;++i){
		if(i==1){
			b[i]=a[i];
		}else{
			b[i]=b[i-1];
			b[i].l=a[i].l;
			Chkmin(b[i].r,a[i].r);
		}
	}
	for(LL i=n;i>=1;--i){
		if(i==n){
			c[i]=a[i];
		}else{
			c[i]=c[i+1];
			Chkmax(c[i].l,a[i].l);
			Chkmin(c[i].r,a[i].r);
		}
	}
	/*for(LL i=1;i<=n;++i){
		printf("(%d,%d)",a[i].l,a[i].r);
	}puts("");*/
	for(LL i=1;i<=n;++i){
