		else if(i==n) Tmp=b[i-1];
		else{
			Tmp=b[i-1];
		    Chkmax(Tmp.l,c[i+1].l);
		    Chkmin(Tmp.r,c[i+1].r);
		}
		//printf("%d,%d\n",Tmp.l,Tmp.r);
		if(Tmp.l<=Tmp.r) Chkmax(ans,a[i].r-a[i].l+1+(Tmp.r-Tmp.l+1));
	}
	//printf("%d\n",ans);
	LL mi(inf);
	for(LL i=n;i>=1;--i){
		if(mi<=a[i].r) vis[i]=1;
		Chkmin(mi,a[i].r);
	}
	LL tot(0);
