		if(!vis[i]){
			a[++tot]=a[i];
		}
	}
	//printf("%d\n",tot);
	mi=inf;
	for(LL i=1;i<=tot;++i){
		Chkmin(mi,a[i].r);
		if(mi>=a[i].l) pre[i]=mi-a[i].l+1;
	}
	mi=a[tot].l;
	for(LL i=tot;i>=1;--i){
		if(mi<=a[i].r) nxt[i]=a[i].r-mi+1;
	}
	for(LL i=1;i<=tot;++i){
		Chkmax(ans,pre[i]); Chkmax(ans,nxt[i]);
		Chkmax(ans,pre[i]+nxt[i+1]);
	}
	printf("%d\n",ans);
	return 0;
}

