int main(){
    int N;
    cin >> N;

    vector<P> V(N);
    rep(i, N) {
        int l, r;
        cin >> l >> r;
        V[i] = P(l, r + 1);
    }

    int maxL = 0, minR = INF;
    rep (i, N) {
        maxL = max(maxL, V[i].first);
        minR = min(minR, V[i].second);
    }

    // maxLの区間とminRの区間を同じ集合の要素とする場合
    ll ans = 0;
    rep(i, N) {
        ans = max(ans, (ll)max(0, minR - maxL) + (V[i].second - V[i].first));
    }

    vector<P> ab(N);
    rep(i, N) {
        int a = max(0, V[i].second - maxL);
        int b = max(0, minR - V[i].first);
        ab[i] = P(a, b);
    }

    sort(ab.begin(), ab.end(), [](P a, P b){
        return a.first < b.first || (a.first == b.first && a.second > b.second);
    });

    rep(i, N - 1) {
        ans = max(ans, (ll)ab[i].second + ab[i + 1].first);
    }

    cout << ans << endl;
}

