int main(){
  int N;cin>>N;
  vector<int> L(N);vector<int> R(N);
  for(int i=0;i<N;i++){cin>>L[i];cin>>R[i];}

  pair<int,int> contests[N];
  for(int i=0;i<N;i++)contests[i]=pair<int,int>(L[i],R[i]);
  sort(contests,contests+N);

  //i番目までの, Rの最小値
  vector<int> R_min(N);
  for(int i=0;i<N;i++){
    if(i==0)R_min[i]=contests[i].second;
    else R_min[i]=min(R_min[i-1],contests[i].second);
  }
  //逆方向から見たときにi番目までの最小値
  vector<int> R_min_inv(N);
  for(int i=N-1;i>=0;i--){
    if(i==N-1)R_min_inv[i]=contests[i].second;
    else R_min_inv[i]=min(R_min_inv[i+1],contests[i].second);
  }

  int ans=0;
  //切る場所でループ
  for(int i=0;i<N-1;i++){
    ans=max(ans,(R_min[i]-contests[i].first+1)+
            (R_min_inv[i+1]-contests[N-1].first+1));
  }

  cout<<ans<<endl;

}
