#include <iostream>
#include <utility>
#include <algorithm>
#define MAXN 100005
#define MAXVAL 1000000001
#define MINVAL 0

using namespace std;

pair<int, int> ranges[MAXN];
int max_start_from_end[MAXN];

bool cmp(pair<int, int> a, pair<int, int> b) {
	if (a.second != b.second) {
		return a.second < b.second;
	}
	return a.first > b.first;
}

int getrangelength(int max_start, int min_end) {
	if (max_start <= min_end) {
		return min_end - max_start + 1;
	}
	return 0;
}

int main() {
	int n;
	cin >> n;
	int min_end(MAXVAL);
	int max_start(MINVAL);
	int max_length(0);
	for (int i = 0; i < n; ++i) {
		int l, r;
		cin >> l >> r;
		ranges[i].first = l;
		ranges[i].second = r;
		min_end = min(min_end, ranges[i].second);
		max_start = max(max_start, ranges[i].first);
		max_length = max(max_length, ranges[i].second - ranges[i].first + 1);
	}
	sort(ranges, ranges + n, cmp);
	for (int i = n - 1; i >= 0; --i) {
		if (i == n - 1) {
			max_start_from_end[i] = ranges[i].first;
		} else {
			max_start_from_end[i] = max(max_start_from_end[i + 1], ranges[i].first);
		}
	}
	int max_start_from_start(MINVAL);
	int ans(max_length);
	for (int i = 0; i < n - 1; ++i) {
		if (i == 0) {
			max_start_from_start = ranges[i].first;
		} else {
			max_start_from_start = max(max_start_from_start, ranges[i].first);
		}
		ans = max(ans,
			  getrangelength(max_start_from_start, ranges[0].second) +
			  getrangelength(max_start_from_end[i + 1], ranges[i + 1].second));
	}
	cout << ans << endl;
	return 0;
}

