    pair<int,int> largest_interval;
    REP(i,N) {
        int l ,r; cin >> l >> r;
        if(r-l+1>max_length) {
            max_length = r - l + 1;
            largest_interval = make_pair(l,r);
        }
        intervals.push_back(make_pair(l,r));
    }
    sort(all(intervals),greater<pair<int,int>>());
    int now = 1000000001;
    vector<pair<int,int>> kyokushou;
    REP(i,N) {
        if(intervals[i].second<now){
            now = intervals[i].second;
            kyokushou.push_back(intervals[i]);
        }
    }
    if(kyokushou.size()==1) {
        int l = kyokushou[0].first;
        int r = kyokushou[0].second;
        cout << max_length + r - l + 1 << endl; 
