            int tmp3 = max_length + max(0,min(lr[i],rr[i+1])-max(ll[i],rl[i+1]+1));
            ans = max(ans,max(tmp1,max(tmp2,tmp3)));
        }
        cout << ans << endl;
    }
    return 0;
}

