i64 range_width(const pair<i64,i64>& rg) {
    i64 l,r; tie(l,r) = rg;
    return r - l;
}

void solve() {
    i64 N = RD();
    auto A = RD_VEC<pair<i64,i64>>(N);
    // [l,r)
    for(auto& a : A)
        ++a.second;
    //DBG(A);

    // N == 2 は自明(後の例外処理を避ける)
    if(N == 2) {
        i64 ans = range_width(A[0]) + range_width(A[1]);
        PRINTLN(ans);
        return;
    }

    i64 pi = ALL(max_element, A, LT_ON(LIFT(get<0>))) - begin(A);
    i64 qi = ALL(min_element, A, LT_ON(LIFT(get<1>))) - begin(A);
    //DBG(pi,qi);

    // p, q が一致する場合
    if(pi == qi) {
        auto p = A[pi];
        A.erase(begin(A)+pi);
        auto t = *ALL(max_element, A, LT_ON(range_width));
        i64 ans = range_width(p) + range_width(t);
        PRINTLN(ans);
        return;
    }

    i64 ans = 0;
    auto p = A[pi];
    auto q = A[qi];

    // p, q を同じ集合に入れる場合
    {
        i64 l = max(p.first, q.first);
        i64 r = min(p.second, q.second);
        auto t = *ALL(max_element, A, LT_ON(range_width));
        i64 cur = max<i64>(0, r-l) + range_width(t);
        chmax(ans, cur);
    }

    // p, q を別の集合に入れる場合
    {
        A[pi].first = -1;
        A[qi].first = -1;
        A.erase(ALL(remove_if,A,[](const auto& rg){return rg.first==-1;}), end(A));
        ASSERT(SIZE(A) == N-2);

        ALL(sort, A);
        auto que = make_fold_queue<pair<i64,i64>>({INF,INF}, [](const auto& lhs, const auto& rhs) {
            return min(lhs, rhs, LT_ON(LIFT(get<1>)));
        });
        for(const auto& rg : A)
            que.emplace(rg);

        i64 cur = range_width(q) + max<i64>(0, que.fold().second-p.first);
        i64 lmax = -INF;
        while(!que.empty()) {
            chmax(lmax, POP(que).first);
            i64 rmin = min(p.second, que.fold().second);
            chmax(cur, max<i64>(0,q.second-lmax) + max<i64>(0,rmin-p.first));
        }

        chmax(ans, cur);
    }

    PRINTLN(ans);
}

signed main() {


    solve();

    return 0;
}

