pll meet(pll &a, pll &b){
	pll x, y;
	x.first = a.first;
	x.second = a.second;
	y.first = b.first;
	y.second = b.second;

	pll res;

	if(x.first>y.first) swap(x, y);

	if(x.first == -1 || y.first == -1){
		res = {-1, -2};
	}else if(y.first<=x.second){
		res = {y.first, min(x.second, y.second)};
	}else{
		res = {-1, -2};
	}

	return res;
}

vector<pll> left(vector<pll> &seg){
	ll n = seg.size();
	vector<pll> res(n);
	res[0] = seg[0];
	REP(i, n){
		if(i==0) continue;
		res[i] = meet(res[i-1], seg[i]);
	}
	return res;
}

vector<pll> right(vector<pll> &seg){
	ll n = seg.size();
	vector<pll> res(n);
	res[n-1] = seg[n-1];
	REP(i, n){
		if(i==0) continue;
		res[n-i-1] = meet(res[n-i], seg[n-i-1]);
	}
	return res;
}


