struct problem {
    ll L, R, range;

    problem(ll inL, ll inR, ll inRange)
    {
        L = inL;
        R = inR;
        range = inRange;
    }
    bool operator<(const problem &another) const
    {
        return range == another.range ? R < another.R : range < another.range;
    };
};

int main() {
    int N;
    cin >> N;
    vector<ll> L(N), R(N);
    vector<problem> P;
    REP(i, N){
        cin >> L[i] >> R[i];
        P.push_back(problem(L[i], R[i], R[i] - L[i] + 1ll));
    }
