    bounds[0][1] = P[0].R;
    bounds[1][0] = P[N-1].L;
    bounds[1][1] = P[N-1].R;

    ll score1 = P[0].range, score2 = P[N-1].range;

    FORR(i, N-2, 1) {
        // 1に入れる時のコンテスト1のスコア
        ll score1_tmp = max(min(bounds[0][1], P[i].R) - max(bounds[0][0], P[i].L)+1ll, 0ll);

