            // cerr << score1_tmp << endl;
            bounds[0][0] = max(P[i].L, bounds[0][0]);
            bounds[0][1] = min(P[i].R, bounds[0][1]);
        }
    }
    // cerr << "score1 = " << score1 << " score2 = " << score2 << endl;
    cout << score1 + score2 << endl;

    return 0;
}

