#include<algorithm>
using namespace std;
typedef long long ll;

struct node {
  int l,r;
  int ll,lr;
  int rl,rr;
};

bool cmp(const node &a, const node &b) {
  if (a.l == b.l) {
    return (a.r > b.r);
  }
  return (a.l < b.l);
}


void printIt(vector<node> ranges) {
  for(int i=0; i<ranges.size(); ++i) {
    cout<< "L : " << ranges[i].l << " , " << " R : " <<  ranges[i].r << "\t";
    cout<< "Left L : " << ranges[i].ll << " , " << " Left R : " <<  ranges[i].lr << "\t";
    cout<< "Right L : " << ranges[i].rl << " , " << " Right R : " <<  ranges[i].rr << endl;
  }
}


void updateLeftToRight(vector<node> &ranges) {
  if (ranges.size() == 0 ) {
    return;
  }
  ranges[0].ll = ranges[0].l;
  ranges[0].lr = ranges[0].r;
  for (int i=1; i<ranges.size(); ++i) {
    ranges[i].ll = ranges[i].l;
    ranges[i].lr = min(ranges[i].r,ranges[i-1].lr);
  }
}

void updateRightToLeft(vector<node> &ranges) {
  if (ranges.size() == 0 ) {
    return;
  }
  int n = ranges.size();
  ranges[n-1].rl = ranges[n-1].l;
  ranges[n-1].rr = ranges[n-1].r;
  for (int i=n-2; i>=0; --i) {
    ranges[i].rl = ranges[i+1].rl;
    ranges[i].rr = min(ranges[i].r,ranges[i+1].rr);
  }
}

int getAns(vector<node> &ranges) {
  int ans = 0;
  for(int i=0; i<ranges.size(); ++i) {
    if (i > 0) {
        ans = max(ans,max(0,ranges[i-1].lr -ranges[i-1].ll + 1) + max(0,ranges[i].rr -ranges[i].rl + 1));
    }
  }
  for(int i=0; i<ranges.size(); ++i) {
    if (i < ranges.size() - 1) {
        ans = max(ans,max(0,ranges[i].lr -ranges[i].ll + 1) + max(0,ranges[i+1].rr -ranges[i+1].rl + 1));
    }
  }
  int tmpl,tmpr;
  for(int i=0; i<ranges.size(); ++i) {
    if (i>0) {
      tmpl = ranges[i-1].ll;
      tmpr = ranges[i-1].lr;
    }
    if (i+1 < ranges.size()) {
      if (i==0) {
        tmpl = ranges[i+1].rl;
        tmpr = ranges[i+1].rr;
      } else {
        tmpl = max(tmpl, ranges[i+1].rl);
        tmpr = min(tmpr, ranges[i+1].rr);
      }
    }
    ans = max(ans,max(0,ranges[i].r -ranges[i].l + 1) + max(0,tmpr - tmpl + 1));
  }
  return ans;
}

int main() {
  int n;
  cin>>n;
  vector<node> ranges;
  int l,r;
  for(int i=0; i<n; ++i) {
    cin>>l>>r;
    node curr;
    curr.l  = l;
    curr.r = r;
    ranges.push_back(curr);
  }
  sort(ranges.begin(),ranges.end(),cmp);


  updateLeftToRight(ranges);
  updateRightToLeft(ranges);

  // printIt(ranges);
  cout << getAns(ranges) << endl;

  return 0;
}

