        int a, b;
        cin >> a >> b;
        as.emplace_back(a, b);
    }
    sort(as.begin(), as.end());
    SegmentTree seg(n);
    for (int i = 0; i < n; i++) {
        seg.update(i, as[i].second);
    }

    int ans = 0;
    for (int i = 1; i < n; i++) {
        int ll = as[i - 1].first;
        int lr = seg.query(0, i);
        int L = max(lr - ll + 1, 0);
        int rl = as[n - 1].first;
        int rr = seg.query(i, n);
        int R = max(rr - rl + 1, 0);
        ans = max(ans, L + R);
    }

    sort(as.rbegin(), as.rend(), [](auto& a, auto& b) { return a.second - a.first < b.second - b.first; });
    int L = 0, R = 1e9;
