        pii t1 = merge(a,vec[i]);
        pii t2 = merge(b,vec[i]);
        int d1 = (a.second-a.first+1)-(t1.second-t1.first+1);
        int d2 = (b.second-b.first+1)-(t2.second-t2.first+1);
        if(d1 < d2){
            a = t1;
            ans -= d1;
        }else if(d1 > d2){
            b = t2;
            ans -= d2;
        }else{
            mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());
            int v = rng()%2;
            if(v == 0){
                b = t2;
                ans -= d2;
            }else{
                a = t1;
                ans -= d1;
            }
        }
    }
    cout << ans << endl;
}

