                next_ind = i;
            }
        }
        lb = max(0LL, next_ind - sub);
        ub = min(static_cast<ll>(L.size()) - 1LL, next_ind + sub);
    }

    ll ret = -LLINF;
    ll ret_ind = -1;
    for(ll i = lb; i <= ub; ++i) {
        ll cand = GetFun(L[i], r_max);
        if(ret < cand) {
            ret = cand;
