        }
    }

    lb = 0, ub = R.size() - 1;
    while(ub - lb > 2000) {
        // 1000 分探索
        ll sub = (ub - lb) / 1000;
        ll next_val = -LLINF;
        ll next_ind = -1;
        for(int i = lb; i <= ub; i += sub) {
            if(L[ret_ind] > R[i]) { break; }
            ll cand_val = GetFun(L[ret_ind], R[i]);
            if(next_val < cand_val) {
                next_val = cand_val;
                next_ind = i;
            }
        }
        lb = max(0LL, next_ind - sub);
        ub = min(static_cast<ll>(R.size()) - 1LL, next_ind + sub);
    }
    for(ll i = lb; i <= ub; ++i) {
        ret = max(ret, GetFun(L[ret_ind], R[i]));
    }

    return ret;
}

