template<class T> bool chmin(T &a, const T &b) { if (a>b) { a=b; return 1; } return 0; }

bool cmp(const pair<int,int> &a, const pair<int,int> &b){
    return (ll)a.first*(ll)1e10-a.second < (ll)b.first*(ll)1e10-b.second;

}

int main() {
    int N; cin>>N;
    vector<pair<int,int>> q(N);
    int l,r;
    int lmax=-MOD,rmin=MOD;
    for (int i = 0; i < N; ++i) {
        cin>>l>>r;
        chmax(lmax,l);
        chmin(rmin,r);
        q[i]=make_pair(l,r);
    }

    sort(q.begin(),q.end(),cmp);
    int ans=-1;
    for(auto a:q){
        //cout<<a.first<<" "<<a.second<<endl;
        chmax(ans,max(0,rmin-lmax+1)+a.second-a.first+1);
