    int llmax=q[0].first,lrmin=q[0].second;
    left[0]=lrmin-llmax+1;
    for (int i = 1; i < N-1; ++i) {
        chmax(llmax,q[i].first);
        chmin(lrmin,q[i].second);
        left[i]=lrmin-llmax+1;
    }

    //right set
    llmax=q[N-1].first,lrmin=q[N-1].second;
