bool compareLR(struct LR a, struct LR b)
{
	if (a.l < b.l)
		return true;
	else if (a.l > b.l)
		return false;
	else
	{
		if (a.r <= b.r)
			return true;
		else
			return false;
	}
}

bool compareLR_R(struct LR a, struct LR b)
{
	if (a.l < b.l)
		return false;
	else if (a.l > b.l)
		return true;
	else
	{
		if (a.r <= b.r)
			return false;
		else
			return true;
	}
}

long long Caculate(struct LR a, struct LR b)
{
	long long maxL = 0;
	long long minR = 1999999999;

	maxL = a.l >= b.l ? a.l : b.l;
	minR = a.r <= b.r ? a.r : b.r;

	return (long long)(minR - maxL + 1);

}


