    sort(ind + 1, ind + n + 1, cmp);
    sort(rev + 1, rev + n + 1, cmp2);
    int L = 0, R = inf;
    for (int i = 1; i <= n; i++) {
        int cur = rev[i];
        if (L > 0 && R < inf) {
            f[i] = max(0LL, R - L + 1);
        }   else {
            f[i] = 0;
        }
        L = max(L, l[cur]);
        R = min(R, r[cur]);
    }
    L = 0, R = inf;
    for (int i = n; i >= 1; i--) {
        int cur = ind[i];
        if (L > 0 && R < inf) {
            g[i] = max(0LL, R - L + 1);
        }   else {
            g[i] = -inf;
        }
        L = max(L, l[cur]);
        R = min(R, r[cur]);
    }
    multiset <int> st;
    for (int i = 1; i <= n; i++) {
        st.insert(r[rev[i]] + f[i]);
    }
    int j = 0;
    for (int i = 1; i <= n; i++) {
        int cur = ind[i];
        while (j + 1 <= n) {
            int k = rev[j + 1];
            if (r[k] < l[cur]) {
                L = max(L, l[k]);
                R = min(R, r[k]);
                st.erase(st.find(r[k] + f[j + 1]));
                j++;
            }   else {
                break;
            }
        }
        if (g[i] > -inf) {
            if (r[rev[1]] >= l[cur]) {
                ans = max(ans, r[rev[1]] - l[cur] + 1 + g[i]);
            }
        }   else {
            if (!st.empty()) {
                ans = max(ans, - l[cur] + 1 + *(--st.end()));
            }
        }
    }
    cout << ans;
}

