decltype(auto) sortKey(const pair<int, int>& p){
  return pair<int, int>(p.first, -p.second);
}

void sortC() {
  sort(C, C+N, [](auto l, auto r){ return sortKey(l) < sortKey(r); });
}


I solve() {
  SegmentTree<I> segmin(N);
  SegmentTree<I> segmax(N);
  repeat(i, N) segmin.setValue(i, -C[i].second);
  repeat(i, N) segmax.setValue(i, C[i].first);

  I best = 0;
  repeat(i, N) chmax<I>(best, C[i].second - C[i].first);
  I low = C[0].first;
  I high = C[0].second;
  repeat(i, N-1) {
    chmax<I>(low, C[i].first);
    chmin<I>(high, C[i].second);

    I low2 = segmax.getMaxRange(i+1, N).value;
    I high2 = -segmin.getMaxRange(i+1, N).value;
    if (low < high && low2 < high2)
      chmax(best, (high-low)+(high2-low2));
    else
      chmax(best, max(high-low, high2-low2));
    // cout << low << ' ' << high << ' ' << low2 << ' ' << high2 << endl;
    // cout << best << endl;
  }
  return best;
}


I guchoku() {
  int best = 0;
  iterate(b, 1, (1 << N) -2) {
    int l1 = 0, h1 = 2e9;
    int l2 = 0, h2 = 2e9;
    repeat(i, N) {
      if (b & (1 << i)) {
        chmax(l1, C[i].first);
        chmin(h1, C[i].second);
      }
      else {
        chmax(l2, C[i].first);
        chmin(h2, C[i].second);
      }
    }
    if (l1 < h1 && l2 < h2)
      chmax(best, (h1-l1)+(h2-l2));
    else
      chmax(best, max(h1-l1, h2-l2));
  }
  return best;
}


