template<typename T>
struct SegmentTree{
private:
    int n;
    T E;
    vector<T> node;
    inline void updatef(T& x,T& y){
        x = y;
    }
    inline T queryf(T& x,T& y){
        return make_pair(max(x.fr,y.fr), min(x.sc, y.sc));
    }

public:
    SegmentTree() {}

    void init(int sz, T E_) {
        E = E_;
        n=1;
        while(n<sz)n<<=1;
        node.resize(2*n-1,E);
    }

    SegmentTree(int sz,T E_):E(E_){
        n=1;
        while(n<sz)n<<=1;
        node.resize(2*n-1,E);
    }

    SegmentTree(vector<T>& A,T E_):E(E_){
        int sz=A.size();
        n=1;
        while(n<sz)n<<=1;
        node.resize(2*n-1,E);
        rep(i,sz)node[i+n-1]=A[i];
        for(int i=n-2;i>=0;--i){
            node[i]=queryf(node[2*i+1], node[2*i+2]);
        }
    }

    void update(int k,T x){
        k+=n-1;
        updatef(node[k],x);
        while(k>0){
            k=(k-1)/2;
            node[k]=queryf(node[2*k+1], node[2*k+2]);
        }
    }
       //[a,b)での値を返す
    T get(int a,int b,int k=0,int l=0,int r=-1){
        if(r<0)r=n;
        if(r<=a||b<=l)return E;
        if(a<=l&&r<=b)return node[k];
        T xl=get(a,b,2*k+1,l,(l+r)/2);
        T xr=get(a,b,2*k+2,(l+r)/2,r);
        return queryf(xl, xr);
    }
};

void solve() {
	int n; cin >> n;
    vector<int> a(n), b(n);
    vector<P> ps(n);
    rep(i, n) {
        cin >> a[i] >> b[i];
        --a[i];
        ps[i] = make_pair(a[i], b[i]);
    }
    sort(all(a)); sort(all(b));
    int A = a[n - 1], B = b[0];
    int C = 0, j = 0;
    sort(all(ps));
    int res = 0;
    rep(i, n) {
        if(ps[i].fr != A && ps[i].sc != B) {
            chmax(res, ps[i].sc - ps[i].fr);
        }
        if(ps[i].sc == B) {
            if(chmin(C, ps[i].fr)) j = i;
        }
    }
    cerr << A <<  " " << B << endl;
    int ans = res + max(0, B - A);
    cerr << ans << endl;
    SegmentTree<P> sg(ps, make_pair(-inf, inf));
    int rec = B - C + max(0, sg.get(j + 1, n).sc - A);
    cerr << rec << endl;
    chmax(ans, rec);
    rep(i, n - 1) {
        if(ps[i].fr <= C) continue;
        int hoge = max(0, B - ps[i].fr) + max(0, sg.get(i + 1, n).sc - A);
        cerr << hoge << endl;
        chmax(ans, hoge);
    }
    cout << ans << endl;
}

