// pick L O(N),
//          if(L > R) ans = max(len single)
//          if(L <= L(R)) 必选
//          if(L(R)<=L <= R) , L 从大到小， 另一个逐个 变小


ll n;
vector<pair<ll,ll>> lr;

int main(){
  cin>>n;
  rep(i,0,n){
    ll l,r;
    scanf("%lld %lld",&l,&r);
    lr.pb({l,r});
  }
  sort(lr.begin(),lr.end());
  ll maxsingle = 0;
  ll minr = lr[0].second;
  rep(i,0,n){
    maxsingle=max(maxsingle,lr[i].second-lr[i].first+1);
    minr = min(minr,lr[i].second);
  }
  ll minrl = 1'000'000'001;
  rep(i,0,n){ // 最小左端点 [minrl,minr]
    if(lr[i].second == minr){
      minrl = min(minrl,lr[i].first);
    }
  }
  pair<ll,ll>right = {0,1'000'000'001};
  ll ans = maxsingle;
  int maxsinglel = 0,maxsingler = 0;
  rep(i,0,n){
    if(lr[i].second-lr[i].first+1 == maxsingle){
      maxsinglel = lr[i].first;
      maxsingler = lr[i].first;
    }
  }
  rep(i,0,n){
    if(lr[i].first == maxsinglel && lr[i].second == maxsingler)continue;
    right.first = max(right.first,lr[i].first);
    right.second = min(right.second,lr[i].second);
  }
  if(right.first <= right.second){
    ans=max(ans,maxsingle+(right.second-right.first+1));
  }

  right = {0,1'000'000'000};

  per(i,1,n){ // 最左边的一定包裹
    if(lr[i].first == minrl)break; // 剩余的全是包裹[minrl,minr]的
    // 第i个移动到右侧
    right.first = max(right.first,lr[i].first);
    right.second = min(right.second,lr[i].second);
    if(right.second < right.first)break; // 右侧为0
    if(lr[i-1].first > minr)continue; // 左侧为0
    ans = max(ans,(minr-lr[i-1].first+1)+(right.second-right.first+1));
  }
  if(right.first == 0){ // 全部包裹了最小段
    cout<<max(ans,maxsingle+(minr-minrl+1))<<endl;
    return 0;
  }
  cout<<ans<<endl;
  // [              ]
  //   [     ]
  //     [     ]
  //-----------------------
  //    [              ]
  //   [     ]
  //     [     ]
  return 0;
}

