    sort(ALL(LR));
    ll ans = 0;
    SegTree<ll, 1 << 17> st;
    for (int i = 0; i < n; i++)
    {
        st.update(i, LR[i].second);
    }
    for (int i = 0; i < n - 1; i++)
    {
        ll temp = st.get(0, i + 1) - LR[i].first;
        if (temp < 0)
        {
            temp = 0;
        }
        ll sum = temp;
        temp = st.get(i + 1, n) - LR[n - 1].first;
        if (temp < 0)
        {
            temp = 0;
        }
        sum += temp;
        chmax(ans, sum);
        temp = min(st.get(0, i), st.get(i + 1, n)) - LR[n - 1].first;
        sum = max(ll(0), temp);
        sum += LR[i].second - LR[i].first;
        chmax(ans, sum);
    }
    cout << ans << "\n";
}

