  multiset<ll>str;
  rep(i,0,n){
    if(i==mindex)continue;
    stl.insert(l[i]);
    str.insert(r[i]);
  }
  ll maxl=l[mindex];
  ll idx=0;
  while(!stl.empty()){
    //cout<<minr spa maxl spa *str.begin() spa *stl.begin()<<endl;
    chmax(res,max(0LL,minr-maxl+1)+max(0LL,*str.begin()-*stl.begin()+1));
    chmax(maxl,p[idx].fi);
    ll maxlen=0;
    while(idx<n-1&&maxl>=p[idx].fi){
      chmax(maxlen,r[p[idx].se]-p[idx].fi+1);
      stl.erase(stl.find(p[idx].fi));
      str.erase(str.find(r[p[idx].se]));
      idx++;
    }
    //cout<<idx<<endl;
    if(idx==n-1){
      //cout<<maxl spa minr spa maxlen<<endl;
      chmax(res,max(0LL,minr-maxl+1)+maxlen);
      break;
    }
  }
  cout<<res<<endl;
  return 0;
}

