		else range = pi(max(pre[i-1].f,suff[i+1].f),min(pre[i-1].s,suff[i+1].s));

		ans = max(ans, max(A[i].s - A[i].f + 1, (int)0) + max(range.s - range.f + 1,(int)0));
	}
	cout<<ans;



}

