constexpr auto MAX_N { 100005 };

vector<ll> a(MAX_N);

lld f(lld l, lld r)
{
    return max(r - l + 1, 0LL);
}

int main()
{
    ios::sync_with_stdio(false);

    int n;
    cin >> n;
    for (int i = 1; i <= n; ++i)
    {
        cin >> a[i].first >> a[i].second;
    }

    sort(begin(a) + 1, begin(a) + n + 1, [](ll a, ll b) -> bool
    {
        return a.second == b.second ? a.first > b.first : a.second < b.second;        
    });

    lld max_l = 0, min_r = 1LL << 40, idx_max_l = 1, idx_min_r = 1;
    for (int i = 1; i <= n; ++i)
    {    
        if (max_l < a[i].first)
        {
            max_l = a[i].first;
            idx_max_l = i;
        }

        if (min_r > a[i].second)
        {
            min_r = a[i].second;
            idx_min_r = i;
        }
    }

    lld max_length = 0, idx_max_length = 1;
    for (int i = 1; i <= n; ++i)
    {
        if (idx_max_l == i || idx_min_r == i)
        {
            continue;
        }

        lld length = f(a[i].first, a[i].second);
