struct custom_compare
{
	inline bool operator() (const P& p1, const P& p2)
	{
		if (p1.first == p2.first) {
			return p1.second < p2.second;
		}
		return p1.first < p2.first;
	}
};

int main(void)
{
	const ll LARGE = (ll)1e15;
	int n;
	cin >> n;
	vector<P> range;
	ll value = 0;
	rep(i, n) {
		ll l, r;
		cin >> l >> r;
		range.emplace_back(l, r);
	}
	sort(range.begin(), range.end(), custom_compare());
	vector<ll> lefts(n);
	ll m = LARGE;
	rep(i, n) {
		m = min(m, range[i].second);
		lefts[i] = m;
	}
	m = LARGE;
	vector<ll> rights(n);
	for (int i = n - 1; i >= 0; i--) {
		m = min(m, range[i].second);
		rights[i] = m;
	}
	rep(i, n - 1) {
		ll l1 = range[i].first;
		ll r1 = lefts[i];
		ll l2 = range[n - 1].first;
		ll r2 = rights[i + 1];
		ll la = max(0LL, r1 - l1 + 1);
		ll ra = max(0LL, r2 - l2 + 1);
		value = max(value, la + ra);
	}
	for (int i = 1; i < n - 1;i++) {
		ll l1 = range[i].first;
		ll r1 = range[i].second;
		ll l2 = range[n-1].first;
		ll r2 = min(rights[i + 1], lefts[i - 1]);
		ll la = max(0LL, r1 - l1 + 1);
		ll ra = max(0LL, r2 - l2 + 1);
		value = max(value, la + ra);
	}
	cout << value << endl;
	return 0;
}

