ULL gcd(ULL a, ULL b) { if (b == 0) return a; return gcd(b, a%b); }

void solve() {
	int n; cin >> n;
	int l[100000], r[100000]; rep(i, n) { cin >> l[i] >> r[i]; }
	pair<int, int> lr[100000], rl[100000];
	rep(i, n) { lr[i] = { l[i],r[i] }; rl[i] = { r[i],l[i] }; }
	sort(lr, lr + n);
	sort(rl, rl + n);

	int ans = 0;
	{
		int v[100000] = {};
		int lM = 0, rm = 2000000000;
		for(int i = 0; i < n - 1; i++) {
			lM = max(lM, lr[i].first);
			rm = min(rm, lr[i].second);
			v[i] += max(rm - lM + 1, 0);
		}
		lM = 0, rm = 2000000000;
		for (int i = 1; i < n; i++) {
			lM = max(lM, lr[n - i].first);
			rm = min(rm, lr[n - i].second);
			v[n - i - 1] += max(rm - lM + 1, 0);
		}
		rep(i, n - 1){
          ans = max(ans, v[i]);
        }
	}

	cout << ans << endl;
}

int main() {

	solve();

	return 0;
}

