  ll l = 0,r=1e9+7;
  FOR(i,0,N){
    ans = max(ans,LR[i].second-LR[i].first+1);
    l = max(l,LR[i].first);
    r = min(r,LR[i].second);
    if( r-l+1 <= 0 )continue;
    fun_big[i+1] = r-l+1;
  }

  l = 0,r=1e9+7;
  FORR(i,0,N){
    l = max(l,LR[i].first);
    r = min(r,LR[i].second);
    if( r-l+1 <= 0 )continue;
    fun_end[N-i] = r-l+1;
  }

  FOR(i,1,N){
    ans = max( ans , fun_big[i] + fun_end[N-i]);
  }

  Seg_Tree< pair<ll,ll> > sg(N,make_pair(0,1000000009),make_pair(1,1));

  FOR(i,0,N){
    sg.update(i,LR[i]);
  }

  FOR(i,0,N){
    ans = max(ans,len(LR[i])+len(sg.ex(i)));
  }


  cout << ans << endl;

}

