        lb[i] = max(lb[i+1], p[i].first), rb[i] = min(rb[i+1], p[i].second);
    }

    for (int i = 0; i < n-1; i++) {
        ans = max(ans, max(0ll, rf[i] - lf[i] + 1) + max(0ll, rb[i+1] - lb[i+1] + 1));
    }
    cout << ans << endl;
    return 0;
}

