const int N = 1e5 + 123, inf = 1e9 + 123;
int n, l[N], r[N], pl[N], pr[N], sl[N], sr[N];
int f[N], g[N], ind[N], rev[N];

bool cmp(const int & x, const int & y) {
    if (l[x] == l[y]) {
        return r[x] < r[y];
    }
    return l[x] < l[y];
}

bool cmp2(const int & x, const int & y) {
    if (r[x] == r[y]) {
        return l[x] < l[y];
    }
    return r[x] < r[y];
}

int main() {
    ios_base::sync_with_stdio(false), cin.tie(NULL);
    #ifdef LOCAL
        freopen("input.txt", "r", stdin);
    #endif

    cin >> n;
    pl[0] = sl[n + 1] = 0, pr[0] = sr[n + 1] = inf;
    for (int i = 1; i <= n; i++) {
        cin >> l[i] >> r[i];
        pl[i] = max(pl[i - 1], l[i]);
        pr[i] = min(pr[i - 1], r[i]);
    }
    for (int i = n; i >= 1; i--) {
        sl[i] = max(sl[i + 1], l[i]);
        sr[i] = min(sr[i + 1], r[i]);
    }
    int ans = 0;
    for (int i = 1; i <= n; i++) {
        ans = max(ans, min(pr[i - 1], sr[i + 1]) - max(pl[i - 1], sl[i + 1]) + 1
        + r[i] - l[i] + 1);
        ind[i] = rev[i] = i;
    }
    sort(ind + 1, ind + n + 1, cmp);
    sort(rev + 1, rev + n + 1, cmp2);
    int L = 0, R = inf;
    for (int i = 1; i <= n; i++) {
        int cur = rev[i];
        if (L > 0 && R < inf) {
            f[i] = max(0, R - L + 1);
        }
        L = max(L, l[cur]);
        R = min(R, r[cur]);
    }
    L = 0, R = inf;
    for (int i = n; i >= 1; i--) {
        int cur = ind[i];
        if (L > 0 && R < inf) {
            g[i] = max(0, R - L + 1);
        }
        L = max(L, l[cur]);
        R = min(R, r[cur]);
    }
    multiset <int> st;
    for (int i = 1; i <= n; i++) {
        st.insert(r[rev[i]] + f[i]);
    }
    int j = 0;
    for (int i = 1; i <= n; i++) {
        int cur = ind[i];
        while (j + 1 <= n) {
            int k = rev[j + 1];
            if (r[k] < l[cur]) {
                L = max(L, l[k]);
                R = min(R, r[k]);
                st.erase(st.find(r[k] + f[j + 1]));
                j++;
            }   else {
                break;
            }
        }
        if (g[i] > 0) {
            if (r[rev[1]] >= l[i]) {
                ans = max(ans, r[rev[1]] - l[cur] + 1 + g[i]);
            }
        }   else {
            if (!st.empty()) {
                ans = max(ans, -l[cur] + 1 + *(--st.end()));
            }
        }
    }
    cout << ans;
}

