	ll ma = 0, mir = 1e9, mal = 0;
	for(int i = 0; i < n; i++){
		ii x;
		scanf("%d %d", &x.ff, &x.ss);
		v.pb(x);
		mal = max(mal, (ll)x.ff);
		mir = min(mir, (ll)x.ss);
		ma = max(ma, (ll)x.ss - x.ff);
	}
	ll ans = ma + max(0ll, mir - mal+1) + 1;
	ans = 0;
	sort(v.begin(), v.end(), cmp);
	ii g1 = v.back();
	v.pop_back();
	reverse(v.begin(), v.end());
	set<ii> lef, rig;
	for(int i = 0; i < (int)v.size(); i++){
		lef.insert({v[i].ff, i});
		rig.insert({v[i].ss, i});
	}
	ans = max(ans, (ll)g1.ss - g1.ff + 1 + max(0, -lef.rbegin()->ff + rig.begin()->ff + 1));
