                LA[i+1][na][nb]=pa;
                RA[i+1][na][nb]=qa;
                LB[i+1][na][nb]=pb;
                RB[i+1][na][nb]=qb;
                //cout << "new dp= " << dp[i+1][na][nb] << endl;              
