                //cout << "i+1 na nb  " << i+1 << " " << na << " " << nb << endl;
                //cout << "ra sa rb sb  " << ra << " " << sa << " " << rb << " " << sb << endl;
                dp[i+1][na][nb]=dpa2+dpb2;
                LA[i+1][na][nb]=ra;
