		return true;
	if(a.se > b.se)
		return true;
	return false;
}
bool cmp2(pii a , pii b){
	if(a.se < b.se)
		return true;
	if(a.se == b.se)
		return a.fi < b.fi;
	return false;
}
bool cmp3(pii a , pii b){
	if(a.se > b.se)
		return true;
	if(a.se == b.se)
		return a.fi < b.fi;
	return false;
}
