pll meet(pll &a, pll &b){
	pll x, y;
	x.first = a.first;
	x.second = a.second;
	y.first = b.first;
	y.second = b.second;

	pll res;

	if(x.first>y.first) swap(x, y);

	if(x.first == -1 || y.first == -1){
		res = {-1, -2};
	}else if(y.first<=x.second){
		res = {y.first, min(x.second, y.second)};
	}else{
		res = {-1, -2};
	}

	return res;
}

vector<pll> left(vector<pll> &seg){
	ll n = seg.size();
	vector<pll> res(n);
	res[0] = seg[0];
	REP(i, n){
		if(i==0) continue;
		res[i] = meet(res[i-1], seg[i]);
	}
	return res;
}

vector<pll> right(vector<pll> &seg){
	ll n = seg.size();
	vector<pll> res(n);
	res[n-1] = seg[n-1];
	REP(i, n){
		if(i==0) continue;
		res[n-i-1] = meet(res[n-i], seg[n-i-1]);
	}
	return res;
}

ll solve(vector<pll> &seg){
	ll res = -1;
	ll N = seg.size();

    if(N==1){
        return seg[0].second - seg[0].first + 1;
    }

	sort(seg.begin(), seg.end());
	auto LL = left(seg);
    auto RR = right(seg);

    REP(i, N-1){
    	ll lenL = LL[i].second - LL[i].first + 1;
    	ll lenR = RR[i+1].second - RR[i+1].first + 1;
    	res = max(res, lenL+lenR);
    }

    const ll UP = 1000000000+1;
    vector<pll> seg2(N);
    REP(i, N){
    	seg2[i].first = UP - seg[i].second;
    	seg2[i].second = UP - seg[i].first;
    }

    auto LLr = left(seg2);
    auto RRr = right(seg2);

    REP(i, N-1){
    	ll lenL = LLr[i].second - LLr[i].first + 1;
    	ll lenR = RRr[i+1].second - RRr[i+1].first + 1;
    	//dump(lenL+lenR)
    	res = max(res, lenL+lenR);
    }
    return res;
}


