int main() {
    ll n, m, i, j, k;
    cin >> n;
    vector<pair<ll,ll>> v(n);
    ll l=0,r=INF,maxl_r=0,minr_l=0;
    for(i=0;i<n;i++){
        cin >> v[i].second >> v[i].first;
        l = max(l,v[i].second);
        r = min(v[i].first,r);
    }
    if(n==2){
        cout << v[0].first-v[0].second+1 +v[1].first-v[1].second+1 << endl;
        return 0;
    }
    ll ret = 0;
    for(i=0;i<n;i++){
        // Lの最大を持つ区間とRの最小を持つ区間が同じ集合なら
        // 少なくともこの点数はとれる
        // 最大のL(最小のR)を持つものが両方に表れる時もあるが,
        // その時は最大のLを持つ区間と最小のRを持つ区間を別の集合にしたときの
        // 最善の選択よりも必ず悪くなる.
        // (例:単純に最大のL(最小のR)だけの集合とそれ以外に分ければ両方に含まれる時よりも悪くならない)
        ret = max(ret,max(0LL,r-l+1)+v[i].first-v[i].second+1);
    }

    // Lの最大を持つ区間とRの最小を持つ区間が違う集合にある場合
    sort(v.begin(),v.end());
    vector<ll> l1(n+1,-INF),l2(n+2,-INF),r1(n+1,INF),r2(n+2,INF);
    for(i=0;i<n;i++){
        l1[i+1] = max(l1[i],v[i].second);
        r1[i+1] = min(r1[i],v[i].first); 
    }
    for(i=n;i>0;i--){
        l2[i] = max(l2[i+1],v[i-1].second);
        r2[i] = min(r2[i+1],v[i-1].first);
    }
    for(i=1;i<n;i++){
        ret = max(max(r1[i]-l1[i]+1,0LL)+max(0LL,r2[i+1]-l2[i+1]+1),ret);
    }
    cout << ret << endl;
    return 0;
}

