        bool r = 0,l = 0;
        REP(i,N){
            if(!l && A[i].first == L.first && A[i].second == L.second){l = 1;continue;}
            if(!r && A[i].first == R.first && A[i].second == L.second){r = 1;continue;}
            maxv = max(maxv,A[i].second - A[i].first);
        }
    }
    else if(L.first == R.first && L.second == R.second){
        //左端と右端が同じ直線であった時
        ans += B[0].first - A[0].first;
        cout << ans << endl;
        return 0;
    }
    else ans = 0;//すれ違わない時

    REPP(i,1,A.size()){
