struct Conj{
	ll l, r;
	bool empty;
	void build(){
		empty=1;
	}
	ll check(ll _l,ll _r){
		if( empty) return _r-_l+1;
		return min(r,_r) - max(l,_l) +1;
	}
	void add(ll _l, ll _r){
		if(empty){
			empty=0;
			l=_l;
			r=_r;
		}else{
			l = max(l,_l);
			r = min(r, _r);
		}
	}
	ll tam(){
		if(empty) return -INF;
		return r-l+1;
	}
} dp[2][2];

ii A[N];

bool comp(ii x, ii y){
	return (x.ss-x.ff)>(y.ss-y.ff);
}

int main(){
	fastio;
	int n; cin>>n;
	For(i,0,n) cin>>A[i].ff>>A[i].ss;
	For(i,0,2) For(j,0,2) dp[i][j].build();
	dp[0][0].add(A[0].ff, A[0].ss);
	dp[1][0].add(A[0].ff, A[0].ss);
	Conj temp[2][2];
	Conj ans[2][2];
	sort(A, A+n, comp);
	For(i,1,n){
		For(j,0,2){
			For(k,0,2){
				temp[k][0]=dp[k][0];
				temp[k][1]=dp[k][1];
				temp[k][j].add(A[i].ff,A[i].ss);
			}
			if((temp[0][0].tam()+temp[0][1].tam())>(temp[1][0].tam()+temp[1][1].tam())){
				ans[j][0]=temp[0][0];
				ans[j][1]=temp[0][1];
			}else{
				ans[j][0]=temp[1][0];
				ans[j][1]=temp[1][1];
			}
		}
		For(j,0,2) For(k,0,2) dp[j][k]=ans[j][k];
	}
	cout << max(dp[0][0].tam() + dp[0][1].tam(), dp[1][0].tam()+dp[1][1].tam()) << endl;
	return 0;
}

