	ll res = 0;
	ll lma = -big;
	ll rmi = big;
	rep(i, n) {
		if (i == p)
			continue;
		lma = max(lma,l[i]);
		rmi = min(rmi, r[i]);
	}
	res = ma + max(0LL, rmi - lma);

	ll g1l = -big;
	ll g1r = big;
	ll g2l = mal;
	ll g2r = big;
	bool use[100010]; all0(use);

	rep2(i, 0, n - 1) {
		auto p = lr[i];

		// 左、index
		ll tl = get<0>(p);
		ll tr = get<1>(p);

		use[get<2>(p)] = true;
		g1l = max(g1l, tl);
		g1r = min(g1r, tr);
		while (!rmq.empty())
		{
			auto f = rmq.top();

			if (use[f.second]) {
				rmq.pop();
				continue;
			}
			g2r = rmq.top().first;
			break;
		}
		res = max(res, max(g1r - g1l + 1, 0LL) + max(g2r - g2l + 1, 0LL));
	}

