		arbreMin[ TMAX+i ]=intervalles[i].first;

	}

	for(int id=TMAX-1; id>0 ;id--){
		arbreMax[ id ]=max( arbreMax[ 2*id+1 ] , arbreMax[ 2*id ] );
		arbreMin[ id ]=min( arbreMin[ 2*id+1 ], arbreMin[ 2*id ] );
	}

	int best=0,joyful;
	for(int i=1 ; i<n ; i++){ // i est la position de coupure

		joyful= joyfulness(0,i-1) + joyfulness(i,n-1);

		best=max( best, joyful );
	}

