    FOR0(i, n-1)
    {
        ans = MAX2(ans, pre[i] + pos[i+1]);
    }
    cout<<ans<<endl;
    cerr <<endl<< "Time elapsed : " << clock() * 1000.0 / CLOCKS_PER_SEC << " ms" << '\n';
}

