      left_hoge = LR[i].first;
      left_idx = i;
    }
  }

  LL right_min = 0;
  LL right_hoge = INF;
  LL right_idx = -1;
  REP(i,N){
    if(LR[i].first > right_min){
      right_min = LR[i].first;
      right_idx = i;
    }else
    if(LR[i].first == right_min&&
      LR[i].second < right_hoge){
      right_hoge = LR[i].second;
      right_idx = i;
    }
  }

  if(left_idx==right_idx){
    LL ans_max = 0;
    REP(i,N){
      if(i==left_idx){
        continue;
      }
      LL score = LR[i].second - LR[i].first + 1;
      if(score>ans_max){
