void Solve(){
  ll n;
    cin>>n;
  vll A(n);
  vll B(n);
  ll l=0;
  ll r=10000000000;
  vpll lr(n);

  FOR(i,0,n){
    cin>>lr[i].fi>>lr[i].se;
  }
  SORT(lr);

  FOR(i,0,n-1){
    chmax(l,lr[i].fi);
    chmin(r,lr[i].se);
    A[i]=r-l+1;
  }

  l=0;
  r=10000000000;
  for(int i=n-1;i>0;i--){
    chmax(l,lr[i].fi);
    chmin(r,lr[i].se);
    B[i]=r-l+1;
  }

  ll ans=0;
  FOR(i,1,n){
    ll a=A[i-1]+B[i];
    chmax(ans,a);
  }

  //ここから逆パターン
  FOR(i,0,n){
    ll a=lr[i].fi;
    lr[i].fi=lr[i].se;
    lr[i].se=a;
  }
  SORT(lr);
  REV(lr);
  //.seがl,.fiがrになっている
  l=0;
  r=10000000000;
  FOR(i,0,n-1){
    chmax(l,lr[i].se);
    chmin(r,lr[i].fi);
    A[i]=r-l+1;
  }

  l=0;
  r=10000000000;
  for(int i=n-1;i>0;i--){
    chmax(l,lr[i].se);
    chmin(r,lr[i].fi);
    B[i]=r-l+1;
  }

  FOR(i,1,n){
    ll a=A[i-1]+B[i];
    chmax(ans,a);
  }
  cout<<ans<<endl;
}

