#include <bits/stdc++.h>
using namespace std;
struct SegTree {
    int N;
    vector<int> A;
    function<int(int, int)> F;
    int U;
    SegTree(const vector<int> &B, function<int(int, int)> f, int unit) {
        N = 1; while (N < B.size()) N *= 2;
        A.resize(N * 2, unit);
        F = f;
        U = unit;
        for (int i = 0; i < B.size(); i++) {
            A[N + i] = B[i];
        }
        for (int i = N - 1; i > 0; i--) {
            A[i] = F(A[2*i+0], A[2*i+1]);
        }
    }
    int query(int L, int R) {
        int ans = U;
        L += N, R += N;
        while (L < R) {
            if (L & 1) ans = F(ans, A[L++]);
            if (R & 1) ans = F(ans, A[--R]);
            L /= 2, R /= 2;
        }
        return ans;
    }
};
int main() {
    int N; cin >> N;
    vector<pair<int, int>> A(N);
    for (int i = 0; i < N; i++) cin >> A[i].first >> A[i].second;
    int ans = 0;
    auto f = [&]() {
        vector<int> L(N), R(N);
        for (int i = 0; i < N; i++) {
            L[i] = A[i].first;
            R[i] = A[i].second;
        }
        SegTree Lmax(L, [](int x, int y) { return max(x, y); }, -1e9);
        SegTree Rmin(R, [](int x, int y) { return min(x, y); }, 1e9);
        for (int i = 0; i < N; i++) {
            int t = R[i] - L[i] + 1;
            t += max(0, min(Rmin.query(0, i), Rmin.query(i + 1, N)) - max(Lmax.query(0, i), Lmax.query(i + 1, N)) + 1);
            ans = max(ans, t);
        }
        for (int i = 1; i < N; i++) {
            int t = max(0, Rmin.query(0, i) - Lmax.query(0, i) + 1) + max(0, Rmin.query(i, N) - Lmax.query(i, N) + 1);
            ans = max(ans, t);
        }
    };
    sort(begin(A), end(A));
    f();
    sort(begin(A), end(A), [](auto &p, auto &q) { return make_pair(p.second, -p.first) < make_pair(q.second, -q.first); });
    f();
    cout << ans << endl;
    return 0;
}

