			chmax(ans, max(rR_f[i] - rL_f[i] + 1, 0LL) + max(rR_b[i] - rL_b[i] + 1, 0LL));
			DMP(rR_f[i] - rL_f[i] + 1, rR_b[i] - rL_b[i] + 1);
		}

		return ans;

	};

	lint ans = 0;

	sort(LR.begin(), LR.end());
	DMP(LR);
	chmax(ans, solve(LR));
	sort(LR.begin(), LR.end(), [](auto l, auto r) {return l.first < r.first || (l.first == r.first) && l.second > r.second; });
	DMP(LR);
	chmax(ans, solve(LR));
	sort(LR.begin(), LR.end(),greater<pair<int,int>>());
	chmax(ans, solve(LR));

