void solve(istream& input, ostream& output) {
	int N; cin >> N;
	vector<pair<int, int>> A, B;
	int res = 0;
	rep(i, N) {
		int l, r; cin >> l >> r;
		A.emplace_back(l, r);
		chmax(res, r-l+1);
	}
	B = A;
	sort(all(A));
	sort(all(B), [](auto a, auto b) {
		return a.second != b.second ? a.second < b.second : b.first < a.first;
	});
	pair<int, int> b = B[0];
	map<int, int> m;
	rep(i, N) {
		if (A[i].first <= b.first) continue;
		if (m[A[i].first] == 0) {
			m[A[i].first] = A[i].second;
		} else {
			m[A[i].first] = min(m[A[i].first], A[i].second);
		}
	}
	int l = 0;
	int r = 1e9+10;
	map<int, int> dp;
	for (auto i = m.rbegin(); i != m.rend(); i++) {
		chmax(l, i->first);
		chmin(r, i->second);
		dp[i->first] = max(0LL, r - l + 1);
	}
	l = b.first;
	for (auto d : dp) {
		chmax(res, max(0LL, b.second - l + 1) + d.second);
		// cout << b.second - l + 1 + d.second << endl;
		l = d.first;
	}
	if (dp.size()) cout << res << endl;
	else cout << res + b.second - b.first + 1 << endl;
}

