    v.push_back({l,r+1});
  }

  ll p = 0, q = 0;
  rep(i,N){
    if (v[i].l > v[p].l)
      p = i;
    if (v[i].r < v[q].r)
      q = i;
  }

  // printf("p=%d q=%d\n", p, q);

  if (p == q) {
    ll lenA = v[p].r - v[p].l, lenB = -1;
    rep(id,N)
      if (id != p)
        chmax(lenB, v[id].r - v[id].l);
    cout << lenA + lenB << endl;
    return 0;
  }

  ll ans = -1;

  // 戦略1
  {
    ll lenA = v[q].r - v[p].l, lenB = -1;
    rep(id,N)
      if (id != p && id != q)
        chmax(lenB, v[id].r - v[id].l);
    chmax(ans, lenA + lenB);
    // printf("strategy1 ans=%d\n", lenA + lenB);
  }

  // 戦略2
  {
    struct T { ll a,b; };
    vector<T> sec;
    rep(id, N) {
      if (id != p && id != q)
        sec.push_back({max(v[id].r - v[p].l, (ll)0), max(v[q].r - v[id].l, (ll)0)});
    }
    sort(begin(sec), end(sec), [](const T &lhs, const T &rhs){
        if (lhs.a == rhs.a)
          return lhs.b < rhs.b;
        else
          return lhs.a > rhs.a;
        });

    ll lenP = v[p].r - v[p].l;
    ll lenQ = v[q].r - v[q].l;
    SegTree<ll> \
      az(N, lenP, [](const ll &x, const ll &y) { return min(x,y); }), \
      bz(N, lenQ, [](const ll &x, const ll &y) { return min(x,y); });

    // まずは、N-2個すべてをBに追加しておく
    rep(i,sec.size()) {
      bz.update(i, sec[i].b);
    }
    chmax(ans, az.query(0, N) + bz.query(0, N));
    // printf("strategy2 #items=%d, ans=%d\n", 0, az.query(0, N) + bz.query(0, N));

    rep(i,sec.size()) {
      bz.update(i, lenQ);
      az.update(i, sec[i].a);
      chmax(ans, az.query(0, N) + bz.query(0, N));
      // printf("strategy2 #items=%d, ans=%d\n", i+1, az.query(0, N) + bz.query(0, N));
    }
  }

  cout << ans << endl;
  return 0;
}

