bool compare(PL a, PL b) {
  if (a.first == b.first) return a.second > b.second;
  return a < b;
}

void solve() {
  ll N;
  cin >> N;
  VPL ps(N);
  rep(i, N) {
    ll l, r;
    cin >> l >> r;
    // [l, r)
    r++;
    ps[i] = {l, r};
  }

  sort(ps.begin(), ps.end(), compare);

  // a, b の 2 グループに分ける際の b グループにおける r の集合
  multiset<ll> b_rights;
  for (auto p : ps) b_rights.insert(p.second);

  ll a_l = 0;
  ll a_r = 1e9 + 1;

  ll res = 0;

  rep(i, N - 1) {
    PL new_a = ps[i];

    chmax(a_l, new_a.first);
    chmin(a_r, new_a.second);

    b_rights.erase(new_a.second);
    ll b_l = ps[N - 1].first;
    ll b_r = *b_rights.begin();

    chmax(res, b_r - b_l + a_r - a_l);
  }

  cout << res << endl;
}

