    for(int j = 0; j < n; j++)
        if(mx <= (v[j].S - v[j].F + 1)) mx = v[j].S - v[j].F + 1, mx_ind = j;

    int l = -1, r = 1e9+7;
    for(int j = 0; j < n; j++)
        if(j != mx_ind) l = max(l, v[j].F), r = min(r, v[j].S);
    int ans = mx+1 + max(0, r-l+1);

