    l = -1, r = 1e9+7;
    for(int j = 0; j < n; j++){
        l = max(l, v[j].F);
        r = min(r, v[j].S);
        pre[j] = max(0, r - l + 1);
    }
    for(int j = n-1;  j >= 0; j--){
