    {
        return range == another.range ? R < another.R : range < another.range;
    };
};

bool asc1( const problem& left, const problem& right ) {
    return left.L < right.L;
}

bool asc2( const problem& left, const problem& right ) {
    return left.R < right.R;
}

int main() {
    int N;
    cin >> N;
    vector<ll> L(N), R(N);
    vector<problem> P;
    REP(i, N){
        cin >> L[i] >> R[i];
        P.push_back(problem(L[i], R[i], R[i] - L[i] + 1));
    }
    sort(P.rbegin(), P.rend());

    // REP(i, N) {
    //     cerr << P[i].R << " ";
    // }
    // cerr << endl;

    ll score = P[0].range;
    vector<vector<ll>> bounds(2, vector<ll>(2));
    bounds[0][0] = P[0].L;
    bounds[0][1] = P[0].R;
    bounds[1][0] = P[N-1].L;
    bounds[1][1] = P[N-1].R;

    ll score1 = P[0].range, score2 = P[N-1].range;

    FORR(i, N-2, 1) {
        // 1に入れる時のコンテスト1のスコア
        ll score1_tmp = max(min(bounds[0][1], P[i].R) - max(bounds[0][0], P[i].L)+1, 0ll);

        // 2に入れる時のコンテスト2のスコア
        ll score2_tmp = max(min(bounds[1][1], P[i].R) - max(bounds[1][0], P[i].L)+1, 0ll);

        if(score1 + score2_tmp > score1_tmp + score2) {
            // cerr << "insert (" << P[i].L << ", " << P[i].R << ") to contest2" << endl;
            score2 = score2_tmp;
            // cerr << score2_tmp << endl;
            bounds[1][0] = max(P[i].L, bounds[1][0]);
            bounds[1][1] = min(P[i].R, bounds[1][1]);
        } else {
            // cerr << "insert to contest1" << endl;
            score1 = score1_tmp;
            // cerr << score1_tmp << endl;
            bounds[0][0] = max(P[i].L, bounds[0][0]);
            bounds[0][1] = min(P[i].R, bounds[0][1]);
        }
    }
    // cerr << "score1 = " << score1 << " score2 = " << score2 << endl;
    cout << score1 + score2 << endl;

    return 0;
}

