            cout << a[i].r - a[i].l + 1 + w << endl;
            return 0;
        }
    }
    vi idx(n);
    iota(all(idx), 0);
    int mai = -1, mii = -1;
    sort(all(idx), [&](int x, int y){
        if(a[x].l == a[y].l){
            return a[x].r > a[y].r;
        }
        return a[x].l > a[y].l;
    });
    mai = idx[0];
    sort(all(idx), [&](int x, int y){
        if(a[x].r == a[y].r){
            return a[x].l < a[y].l;
        }
        return a[x].r < a[y].r;
    });
    mii = idx[0];
    ll ans = 0;
    rep(i, n){
        if(i != mai && i != mii) ans = max(ans, a[mii].r - a[mai].l + 1 + a[i].r - a[i].l + 1);
    }
    vector<ku> b;
    rep(i, n){
        if(i != mai && i != mii && a[i].r < a[mai].r) b.push_back(a[i]);
    }
    n = b.size();
    if(n == 0){
        cout << a[mai].r - a[mai].l + 1 + a[mii].r - a[mii].l + 1 << endl;
        return 0;
    }
    sort(all(b), [&](ku &x, ku &y){
        return x.r > y.r;
    });
    b.push_back({0, -1});
    priority_queue<pair<ll, int>> q;
    rep(i, n + 1) q.push({b[i].l, i});
    vi used(n + 1, false);
    int now = 0;
    ll r = -1;
    ans = max(ans, a[mai].r - a[mai].l + 1 + a[mii].r - max(a[mii].l, q.top().first) + 1);
    while(now < n){
        r = b[now].r;
        while(1){
            if(b[now].r != r) break;
            used[now] = true;
            now++;
        }
        while(!q.empty()){
            if(!used[q.top().second]) break;
            q.pop();
        }
        if(q.empty()){
            ans = max(ans, r - a[mai].l + 1 + a[mii].r - a[mii].l + 1);
        }else{
            ans = max(ans, r - a[mai].l + 1 + a[mii].r - max(a[mii].l, q.top().first) + 1);
        }
    }
    cout << ans << endl;
    return 0;
}

