void to_bin (vector<bool>& conb, int deci){
  for(size_t i=0; i<conb.size(); ++i){
    if(deci%2==0) conb[i] = 0;
    else conb[i] = 1;
    deci /= 2;
  }
}

int main(){
  int i, j;
  int N;
  cin >> N;
  V<int> l(N);
  V<int> r(N);
  int upper = 0;
  int lower = INT_MAX;
  for(i=0; i<l.size(); i++) cin >> l[i] >> r[i];
  long max_funny = 0;
  long deci = 0;
  vector<bool> conb(N);
  for(long i=0; i<N*N; ++i){
    to_bin(conb, deci);
    deci++;
//    debug(conb);
    upper = 0;
    lower = INT_MAX;
    for(long i=0; i<conb.size(); ++i){
      if(conb[i]){
        upper = max(upper, l[i]);
        lower = min(lower, r[i]);
      }
    }
    if(upper==0 && lower==INT_MAX) continue;
    long funny_temp = 0;
    if(lower>upper) funny_temp = lower - upper + 1;
    upper = 0;
    lower = INT_MAX;
    for(int i=0; i<conb.size(); ++i){
      if(!conb[i]){
        upper = max(upper, l[i]);
        lower = min(lower, r[i]);
      }
    }
    if(upper==0 && lower==INT_MAX) continue;
    if(lower>upper) funny_temp += lower - upper + 1;
    max_funny = max(max_funny, funny_temp);
  }
  cout << max_funny << endl;
  return 0;
}

