// {{{ Segment Tree

// T : 要素
template <typename T>
struct SegmentTree{

    int leng;
    using F = function<T(T,T)>;
    F f;  // T*T -> T
    T ti; // (T,f) の 単位元
    vector<T> data; // 1-indexed

    SegmentTree( F f, T ti ) :
        f(f),ti(ti){}

    void init( int n ){
        leng = 1;
        while( leng < n ) leng += leng;
        data.assign(leng*2,ti);
    }

    void build( vector<T> &v ){
        int n = v.size();
        init( n );
        for (int i = 0; i < n; i++) data[leng+i] = v[i];
        for (int i = leng-1; i > 0 ; i--)
            data[i] = f(data[i<<1],data[(i<<1)|1] );
    }

    // data[a] を x で 変更
    void upda( int a, T x ){

        a += leng;

        data[a] = x;

        while( a >>= 1 ){
            data[a] = f( data[a<<1] , data[(a<<1)|1] );
        }

    }

    // [a,b)の f(演算結果) を求める
    T query(int a, int b, int k = 1, int l = 0, int r = -1 ){

        if( r == -1 ) return query(a,b,k,l,leng);

        //今探すkでの範囲がオーバーしたら単位元をを返す
        if( a>=r || b<=l ) return ti;

        //範囲内ならそのまま返す
        else if( a<=l && b>=r ){
            return data[k];
        //そうでもないなら子へ
        }else{
            T ld = query(a,b,k<<1,l,(l+r)/2);
            T rd = query(a,b,(k<<1)|1,(l+r)/2,r);
            return f(ld,rd);
        }

    }

    void dump(){
        for( int i = 1; i < leng*2; i++ ){
            cerr << "d[" << i << "]=" << data[i] << endl;
        }
    }

};

// }}}

int main() {

    int N;
    Scd(N);

    vii a(N);
    int l,r;
    Rep(i,N){
        Scd2(l,r);
        a[i] = {l,r};
    }

    sort(a.begin(), a.end());

    vi la(N), ra(N);
    Rep(i,N) la[i] = a[i].first, ra[i] = a[i].second;

    SegmentTree<int> lst([](int x, int y){ return max(x,y); }, -1 );
    lst.build(la);
    SegmentTree<int> rst([](int x, int y){ return min(x,y); }, INF );
    rst.build(ra);

    int ans = 0;
    Repe(i,N,1){
        int t1 = rst.query(0,i) - lst.query(0,i) + 1;
        int t2 = rst.query(i,N) - lst.query(i,N) + 1;
        if( t1 < 0 ) t1 = 0;
        if( t2 < 0 ) t2 = 0;
        ans = max( ans, t1+t2 );
    }

    printf ("%d\n", ans );

    return 0;
}

