      tmp.emplace_back(lr[st]);
      st = i + 1;
    }
  }
  int n2 = tmp.size();
  priority_queue<pair<int, int>> q;
  for (int i = 0; i < n2; ++i) {
    while (!q.empty() && q.top().first >= tmp[i].second) {
      q.pop();
    }
    q.emplace(tmp[i].second, tmp[i].first);
  }
  vector<pair<int, int>> tmp2;
  while (!q.empty()) {
    tmp2.emplace_back(q.top().second, q.top().first);
    q.pop();
  }
  sort(tmp2.begin(), tmp2.end());
  int best = 0;
  if (tmp2.size() != 1) {
    int n3 = tmp2.size();
    for (int i = 1; i < n3; ++i) {
      int r1 = tmp2[0].second, l1 = tmp2[i - 1].first, r2 = tmp2[i].second, l2 = tmp2.back().first;
      best = max(best, r1 - l1 + r2 - l2 + 2);
