#define ALL(x) x.begin(), x.end()

const llong inf = 1'000'000'000'000'007ll;
const llong mod = 1e9+7;

struct data {
	llong L;
	llong R;

	data() = default;
	data(llong L, llong R) :
		L(L),
		R(R)
	{}

	bool operator<(const data &ri) const {
		// return R - L < ri.R - ri.L;
		return R == ri.R ?
			L < ri.L :
			R < ri.R;
	}
};

llong N;
vector<data> tasks;

llong score(llong mid) {
	data d1(-inf, inf), d2(-inf, inf);

	for (auto &task: tasks) {
		if (task.R < mid) {
			d1.L = max(d1.L, task.L);
			d1.R = min(d1.R, task.R);
		} else {
			d2.L = max(d2.L, task.L);
			d2.R = min(d2.R, task.R);
		}
	}

	if (d1.R == inf || d2.R == inf) return -1;
	return max(0ll, d1.R - d1.L + 1) + max(0ll, d2.R - d2.L + 1);
}

int main() {
	vector<llong> pos;

	cin >> N;
	tasks.resize(N);
	for (auto &task: tasks) {
		cin >> task.L >> task.R;
		pos.push_back(task.R);
	}
	pos.push_back(0);
	pos.push_back(inf);

	sort(ALL(tasks));
	sort(ALL(pos));

	llong left = 0, right = pos.size()-1;
	llong lmid, rmid;
	while (lmid = (left * 2 + right) / 3, rmid = (left + right * 2) / 3, right - left > 1000) {
// cerr << left << " " << right << endl;
		llong lscore = score(pos[lmid]);
		llong rscore = score(pos[rmid]);

		if (lmid > rmid) {
			right = rmid;
		} else {
			left = lmid;
		}
	}

	llong ret = 0;
	for (llong i = max(0ll, left - 1000); i <= min((llong)(pos.size()-1), right + 1000); ++i) {
		ret = max(ret, score(pos[i]));
	}
	for (auto &task: tasks) {
		ret = max(ret, task.R - task.L + 1);
	}

	cout << ret << endl;

	return 0;
}


