bool compare(const pair<int, int> &a, const pair<int, int> &b) {
	if(a.first == b.first) {
		return a.second > b.second;
	} else {
		return a.first < b.first;
	}
}

int main() {
	uint N;
	cin >> N;

	vector<pair<int, int>> LR(N);
	int l, r;
	for(int i=0; i<N; i++) {
		cin >> l >> r;
		LR[i] = make_pair(l, r);
	}

	sort(LR.begin(), LR.end(), compare);
	vector<int> L(N), R(N);
	for(int i=0; i<N; i++) {
		L[i] = LR[i].first;
		R[i] = LR[i].second;
	}

	vector<int> minR(N, R.back());
	for(int i=N-2; i>=0; i--) {
		minR[i] = min(minR[i-1], R[i]);
	}

	long long ans = 0;
	int c1_r = R[0];

	for(int i=1; i<N; i++) {
		c1_r = min(c1_r, R[i-1]);

		long long c1_p = max(0, c1_r - L[i-1] + 1);
		long long c2_p = max(0, minR[i] - L.back() + 1);

		ans = max(ans, c1_p + c2_p);
	}

	cout << ans << endl;
}

