mt19937 rng; //use it by rng() % mod, shuffle(all(vec), rng)
///////////////////////////////////////////////////////////////////////////////////////////////////

int N;
ll L[MAX_N], R[MAX_N];

void solve() {
	cin >> N;
	ll maxl = -inf, minr = inf;
	rep(i, 0, N) {
		cin >> L[i] >> R[i];
		MAX(maxl, L[i]);
		MIN(minr, R[i]);
	}
	int at = -1;
	rep(i, 0, N) {
		if(L[i] == maxl && R[i] == minr) {
			at = i; break;
		}
	}
	if(at != -1) {
		ll ans = R[at] - L[at] + 1;
		ll tmp = -inf;
		rep(i, 0, N) {
			if(at == i) continue;
			MAX(tmp, R[i] - L[i] + 1);
		}
		ans += tmp;
		cout << ans << "\n";
	}
	else {
		int lat = -1, rat = -1;
		rep(i, 0, N) {
			if(L[i] == maxl) lat = i;
			if(R[i] == minr) rat = i;
		}
		assert(lat != -1 && rat != -1 && lat != rat);
		// debug(L[rat], R[rat], L[lat], R[lat], maxl, minr);
		vector<pl> vec;

		ll tmp = -linf;
		rep(i, 0, N) {
			if(lat == i || rat == i) continue;
			vec.pb(pl(L[i], R[i]));
			MAX(tmp, R[i] - L[i] + 1);
		}
		sort(all(vec));
		multiset<ll> L1, R1, L2, R2;
		L1.insert(-linf); R1.insert(linf);
		L2.insert(-linf); R2.insert(linf);

		rep(i, 0, sz(vec)) {
			L2.insert(vec[i].fst);
			R2.insert(vec[i].sec);
		}
		ll ans = tmp + max(min(R[lat], R[rat]) - max(L[rat], L[lat]) + 1, 0ll);
		// debug(ans);
		rep(i, 0, sz(vec) + 1) {
			ll l1 = max(L[rat], *(--L1.end()));
			ll r1 = min(R[rat], *(R1.begin()));
			ll l2 = max(L[lat], *(--L2.end()));
			ll r2 = min(R[lat], *(R2.begin()));
			MAX(ans, max(r1 - l1 + 1, 0ll) + max(r2 - l2 + 1, 0ll));
			if(i == sz(vec)) break;
			L2.erase(L2.lower_bound(vec[i].fst));
			R2.erase(R2.lower_bound(vec[i].sec));
			L1.insert(vec[i].fst);
			R1.insert(vec[i].sec);
		}
		cout << ans << "\n";
	}
}

