typedef pair < int, int > pii;

const int N = 1e5 + 7;

pair < pii, pii > dp[N];
pii v[N];
int n;

int baga() {
    dp[2] = {v[1], v[2]};
    for (int i = 3; i <= n; ++i) {
        auto &sg0 = dp[i - 1].first;
        auto &sg1 = dp[i - 1].second;
        pii new0 = {max(sg0.first, v[i].first), max(min(sg0.second, v[i].second), max(sg0.first, v[i].first))};
        pii new1 = {max(sg1.first, v[i].first), max(min(sg1.second, v[i].second), max(sg1.first, v[i].first))};
        if (sg0.second - sg0.first - new0.second + new0.first < sg1.second - new1.second - sg1.first + new1.first)
            dp[i] = {new0, sg1};
        else
            dp[i] = {sg0, new1};
    }
    return (dp[n].second.second + dp[n].first.second - dp[n].second.first - dp[n].first.first + 2);
}

int main()
{
    ios_base::sync_with_stdio(NULL);
    cin.tie(0);
    cout.tie(0);
    auto Stime = clock();
    cin >> n;
    for (int i = 1; i <= n; ++i)
        cin >> v[i].first >> v[i].second;
    sort(v, v + n, [](pii a, pii b) {
            return ((a.second - a.first) < (b.second - b.first));
         });
    int ans(baga());
    reverse(v, v + n);
    ans = max(ans, baga());
    sort(v, v + n, [](pii a, pii b) {
            return a.first < b.first;
         });
    ans = max(ans, baga());
    while ((double)(clock() - Stime) / CLOCKS_PER_SEC < 1.8) {
        random_shuffle(v, v + n);
        ans = max(ans, baga());
    }
    cout << ans;
    return 0;
}

