int const INF = 1 << 30;

struct SegmentTree {
  private:
    int n;
    vector<int> node;

  public:
    SegmentTree(vector<ll> v) {
        int sz = v.size();
        n = 1;
        while(n < sz)
            n *= 2;
        node.resize(2 * n - 1, INF);
        for(int i = 0; i < sz; i++)
            node[i + n - 1] = v[i];
        for(int i = n - 2; i >= 0; i--)
            node[i] = min(node[2 * i + 1], node[2 * i + 2]);
    }

    void update(int x, int val) {
        x += (n - 1);
        node[x] = val;
        while(x > 0) {
            x = (x - 1) / 2;
            node[x] = min(node[2 * x + 1], node[2 * x + 2]);
        }
    }

    int getmin(int a, int b, int k = 0, int l = 0, int r = -1) {
        if(r < 0)
            r = n;
        if(r <= a || b <= l)
            return INF;
        if(a <= l && r <= b)
            return node[k];

        int vl = getmin(a, b, 2 * k + 1, l, (l + r) / 2);
        int vr = getmin(a, b, 2 * k + 2, (l + r) / 2, r);
        return min(vl, vr);
    }
};

int main() {
    int N;
    cin >> N;
    vector<pll> A(N);
    rep(i, N) {
        ll l, r;
        cin >> l >> r;
        A[i] = make_pair(l, r);
    }
    sort(All(A));
    ll res = 0;
    vector<ll> mal(N + 1);
    vector<ll> v(N);
    SegmentTree st(v);
    rep(i, N) st.update(i, A[i].second);
    for(int i = 1; i < N; i++) {
        res = max(res, max(st.getmin(0, i) - A[i - 1].first + 1, 0LL) +
                           max(st.getmin(i, N) - A[N - 1].first + 1, 0LL));
    }
    // cout << st.getmin(0, 1) << endl;
    cout << res << endl;
    return 0;
}

