template< typename Monoid >
struct SegmentTree {
  using F = function< Monoid(Monoid, Monoid) >;

  int sz;
  vector< Monoid > seg;

  const F f;
  const Monoid M1;

  SegmentTree(int n, const F f, const Monoid &M1) : f(f), M1(M1) {
    sz = 1;
    while(sz < n) sz <<= 1;
    seg.assign(2 * sz, M1);
  }

  void set(int k, const Monoid &x) {
    seg[k + sz] = x;
  }

  void build() {
    for(int k = sz - 1; k > 0; k--) {
      seg[k] = f(seg[2 * k + 0], seg[2 * k + 1]);
    }
  }

  void update(int k, const Monoid &x) {
    k += sz;
    seg[k] = x;
    while(k >>= 1) {
      seg[k] = f(seg[2 * k + 0], seg[2 * k + 1]);
    }
  }

  Monoid query(int a, int b) {
    Monoid L = M1, R = M1;
    for(a += sz, b += sz; a < b; a >>= 1, b >>= 1) {
      if(a & 1) L = f(L, seg[a++]);
      if(b & 1) R = f(seg[--b], R);
    }
    return f(L, R);
  }

  Monoid operator[](const int &k) const {
    return seg[k + sz];
  }

  template< typename C >
  int find_subtree(int a, const C &check, Monoid &M, bool type) {
    while(a < sz) {
      Monoid nxt = type ? f(seg[2 * a + type], M) : f(M, seg[2 * a + type]);
      if(check(nxt)) a = 2 * a + type;
      else M = nxt, a = 2 * a + 1 - type;
    }
    return a - sz;
  }


  template< typename C >
  int find_first(int a, const C &check) {
    Monoid L = M1;
    if(a <= 0) {
      if(check(f(L, seg[1]))) return find_subtree(1, check, L, false);
      return -1;
    }
    int b = sz;
    for(a += sz, b += sz; a < b; a >>= 1, b >>= 1) {
      if(a & 1) {
        Monoid nxt = f(L, seg[a]);
        if(check(nxt)) return find_subtree(a, check, L, false);
        L = nxt;
        ++a;
      }
    }
    return -1;
  }

  template< typename C >
  int find_last(int b, const C &check) {
    Monoid R = M1;
    if(b >= sz) {
      if(check(f(seg[1], R))) return find_subtree(1, check, R, true);
      return -1;
    }
    int a = sz;
    for(b += sz; a < b; a >>= 1, b >>= 1) {
      if(b & 1) {
        Monoid nxt = f(seg[--b], R);
        if(check(nxt)) return find_subtree(b, check, R, true);
        R = nxt;
      }
    }
    return -1;
  }
};

bool solve(){
  ll n;cin>>n;
  vector<pair<ll,ll>>v;
  vector<ll>L(n),R(n);
  ll p=0,q=0;//leftのmax,rightのmin
  rep(i,n)cin>>L[i]>>R[i];
  rep(i,n)R[i]++;

  rep(i,n){
    if(L[p]<L[i])p=i;
    if(R[q]>R[i])q=i;
  }

  rep(i,n){
    if(i!=p and i!=q)v.emplace_back(L[i],R[i]);
  }

  sort(all(v));
  n=v.size();
  SegmentTree<ll>seg1(n,[](ll a,ll b){return max(a,b);},-INF);
  SegmentTree<ll>seg2(n,[](ll a,ll b){return min(a,b);},INF);
  rep(i,n)seg1.set(i,v[i].first);
  rep(i,n)seg2.set(i,v[i].second);
  seg1.build();
  seg2.build();

  ll ans=0;

  //同じ集合に入れる
  if(R[q]-L[p]>=0){
    rep(i,n)chmax(ans,R[i]-L[i]);
    ans+=R[q]-L[p]; 
  }

  rep(i,n+1){
    //[0,i]を左に入れる
    ll l1=max(L[q],seg1.query(0,i));
    ll r1=min(R[q],seg2.query(0,i));

    ll l2=max(L[p],seg1.query(i,n));
    ll r2=min(R[p],seg2.query(i,n));
    // cout<<r1-l1 + r2-l2<<endl;
    chmax(ans,r1-l1 + r2-l2);
  }

  cout<<ans<<endl;

  return false;
}

signed main(){
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  cout<<fixed<<setprecision(30);
  return solve();
}

