    SegTree<ll> lseg(N, 0, [](ll a, ll b){return max(a, b);}, [](ll a, ll b){return b;});
    SegTree<ll> rseg(N, INF, [](ll a, ll b){return min(a, b);}, [](ll a, ll b){return b;});
    vector<P> interval(N);
    rep(i, 0, N) {
        interval[i].first = L[i];
        interval[i].second = R[i];
    }
    sort(all(interval));
    rep(i, 0, N) {
        lseg.change(i, interval[i].first);
        rseg.change(i, interval[i].second);
    }
    ll ans = 0;
    rep(i, 0, N) {
        ll other = 0;
        if (i > 0 && i + 1 < N) {
            other = max(min(rseg.query(0, i), rseg.query(i + 1, N)) - max(lseg.query(i + 1, N), lseg.query(0, i)) + 1, 0LL);
        }
        ans = max(ans, interval[i].second - interval[i].first + 1 + other);
    }
    rep(i, 1, N) {
        ll lmax1 = lseg.query(0, i), rmin1 = rseg.query(0, i);
        ll lmax2 = lseg.query(i, N), rmin2 = rseg.query(i, N);
        ans = max(ans, max(rmin1 - lmax1 + 1, 0LL) + max(rmin2 - lmax2 + 1, 0LL));
    }
    cout << ans << endl;
    return 0;
}

