    ll l_min = LLINF;   // L の中で最小のもの
    ll r_max = -LLINF;  // R の中で最大のもの

    ll ans = -LLINF;

    ll longest_ind = -1;
    ll longest_val = -LLINF;
    REP(i, N) {
        ll l, r;
