	rep(i,n){
		ll l,r;
		cin>>l>>r;
		v[i]=mp(l,r);
	}
	Sort(v);
	vector<pair<ll,ll> > up(n),down(n);
	up[0]=v[0];
	for(int i=1;i<n;i++){
		up[i]=insec(v[i],up[i-1]);
	}
	down[n-1]=v[n-1];
	for(int i=n-2;i>=0;i--){
		down[i]=insec(v[i],down[i+1]);
	}
	ll ans=0;
	for(int i=0;i<n-1;i++){
		ans=max(ans,calc(up[i],down[i+1]));
	}

	fin(ans);

}

