        update_ans();
        lr.erase(ite);
    }

    sort(ALL(lr),
         [](PLL p, PLL q) {
             ll lp, rp, lq, rq;
             tie(lp, rp) = p;
             tie(lq, rq) = q;
             if(lp != lq) return lp > lq;
             else return rp < rq;
         });

    queue<PLL> lr_q;
    for(auto &&ele : lr) lr_q.push(ele);

    while(1 < lr_q.size()) {
        ll l, r;
        tie(l, r) = lr_q.front();
        chmax(l1, l);
        chmin(r1, r);
        del_l(l);
        del_r(r);
        lr_q.pop();
        update_ans();
    }

    cout << ans << endl;
    return 0;
}

