class sparse_tableMAX {
	vector<vector<int>> dat;
	vector<int> logTable;
	int n;

	int zero_element() const {
		return numeric_limits<int>::min();
	}
	int prop(int a, int b) const {
		return max(a, b);
	}

public:
	sparse_tableMAX(vector<int>& a) {
		n = sz(a);
		logTable.resize(n + 1);
		logTable[0] = logTable[1] = 0;
		for (int i = 2; i <= n; i++) logTable[i] = logTable[i >> 1] + 1;

		int logN = logTable[n];
		dat.resize(logN + 1, vector<int>(n, zero_element()));
		FOR(i, n) dat[0][i] = a[i];
		for (int i = 1; i <= logN; i++) {
			int l = 1 << i;
			for (int j = 0; j + l <= n; j++) {
				dat[i][j] = prop(dat[i - 1][j], dat[i - 1][j + l / 2]);
			}
		}
	}

	int query(int l, int r) {
		if (l >= r) {
			return zero_element();
		}
		int k = logTable[r - l];
		return prop(dat[k][l], dat[k][r - (1 << k)]);
	}

};

class sparse_tableMIN {
	vector<vector<int>> dat;
	vector<int> logTable;
	int n;

	int zero_element() const {
		return numeric_limits<int>::max();
	}
	int prop(int a, int b) const {
		return min(a, b);
	}

public:
	sparse_tableMIN(vector<int>& a) {
		n = sz(a);
		logTable.resize(n + 1);
		logTable[0] = logTable[1] = 0;
		for (int i = 2; i <= n; i++) logTable[i] = logTable[i >> 1] + 1;

		int logN = logTable[n];
		dat.resize(logN + 1, vector<int>(n, zero_element()));
		FOR(i, n) dat[0][i] = a[i];
		for (int i = 1; i <= logN; i++) {
			int l = 1 << i;
			for (int j = 0; j + l <= n; j++) {
				dat[i][j] = prop(dat[i - 1][j], dat[i - 1][j + l / 2]);
			}
		}
	}

	int query(int l, int r) {
		if (l >= r) return zero_element();
		int k = logTable[r - l];
		return prop(dat[k][l], dat[k][r - (1 << k)]);
	}

};


int main() {
	int n; reader(n);
	vector<Pii> lr(n);
	FOR(i, n) reader(lr[i].first, lr[i].second);
	map<int, int> mpx, mpy;
	for (auto& xy : lr) {
		int x, y; tie(x, y) = xy;
		if (mpx.count(x) == 0) mpx[x] = y;
		else chmax(mpx[x], y);
		if (mpy.count(y) == 0) mpy[y] = x;
		else chmin(mpy[y], x);
	}

	vector<int> smx, smn;
	FOR(i, n) smx.push_back(lr[i].first);
	FOR(i, n) smn.push_back(lr[i].second);

	sparse_tableMAX smax(smx);
	sparse_tableMIN smin(smn);

	int ans = 0;
	FOR(i, n) {
		int len1 = lr[i].second - lr[i].first + 1;
		int l2 = max(smax.query(0, i), smax.query(i + 1, n));
		int r2 = min(smin.query(0, i), smin.query(i + 1, n));
		int len2 = r2 - l2 + 1;
		ans = max(ans, len1 + max(len2, 0));
	}

	int xmx = ten(9) + 20;
	for (auto it = mpx.rbegin(); it != mpx.rend(); ++it) {
		chmin(xmx, it->second);
		it->second = xmx;
	}
	int ymn = -2;
	for (auto it = mpy.begin(); it != mpy.end(); ++it) {
		chmax(ymn, it->second);
		it->second = ymn;
	}

	FOR(i, n) {
		if (i == 0) continue;
		int l1 = max(lr[0].first, lr[i].first);
		int r1 = min(lr[0].second, lr[i].second);
		int len1 = r1 - l1 + 1;
		if (len1 <= 0) continue;

		int l2 = max(smax.query(1, i), smax.query(i + 1, n));
		int r2 = min(smin.query(1, i), smin.query(i + 1, n));

		auto it1 = mpx.lower_bound(l1 + 1);
		auto it2 = mpy.lower_bound(r1);
		it2--;
		int len2 = 0;
		if (it1 == mpx.end() && it2 == mpy.end()) {
			continue;
		} else if (it1 != mpx.end() && it2 != mpy.end()) {
			len2 = r2 - l2 + 1;
		} else if (it1 != mpx.end()) {
			len2 = it1->second - l2 + 1;
		} else {
			len2 = r2 - it2->second + 1;
		}

		len1 = max(len1, 0);
		len2 = max(len2, 0);

		ans = max(ans, len1 + len2);
	}
	writerLn(ans);

	return 0;
}

