int main(){
    int n;
    cin >> n;
    vector<ll> l(n),r(n);
    vector<P> p(n);
    REP(i,n){
        cin >> l[i] >> r[i];
        p[i].first = -l[i];
        p[i].second = r[i];
    }
    auto ml = max_element(all(l))-l.begin(),mr = min_element(all(r))-r.begin();
