#define INF (__INT32_MAX__ / 2)
#define EPS 10e-8
#define MAX_N 100000

using namespace std;
typedef pair<llong, llong> ipair;
llong modulo(llong left, llong right) { return (left % right + right) % right; }

llong N;
list<ipair> LR, LRorig;

llong solve1() {
    llong mmax = -INF;
    llong mmin = INF;
    for(ipair pr : LRorig) {
        mmax = max(mmax, pr.second - pr.first + 1);
        mmin = min(mmin, pr.second - pr.first + 1);
    }
    return mmax + mmin;
}

llong lmax[MAX_N], rmin[MAX_N], lmax_rev[MAX_N], rmin_rev[MAX_N];
llong solve() {
    /*
    for(ipair pr : LR)
        cout << pr.first << ", " << pr.second << endl;
        */

    N = LR.size();

    lmax[0] = -LR.begin()->first;
    rmin[0] = LR.begin()->second;
    lmax_rev[N - 1] = -INF;
    rmin_rev[N - 1] = INF;

    auto it = next(LR.begin());
    int i = 0;
    for(; it != LR.end(); ++it) {
        ++i;
        lmax[i] = max(lmax[i - 1], -it->first);
        rmin[i] = min(rmin[i - 1], it->second);
    }
    it = prev(LR.end());
    i = N - 1;
    for(; it != LR.begin(); --it) {
        i--;
        lmax_rev[i] = max(lmax_rev[i + 1], -it->first);
        rmin_rev[i] = min(rmin_rev[i + 1], it->second);
    }

    llong res = 0;
    for(int i = 0; i <= N - 2; ++i) {

        //cout << "(" << lmax[i] << ", " << rmin[i] << "), ";
        //cout << "(" << lmax_rev[i] << ", " << rmin_rev[i] << "), " << endl;

        res = max(res, 
            max(0ll, rmin[i] - lmax[i] + 1) + max(0ll, rmin_rev[i] - lmax_rev[i] + 1)
        );
    }
    return res;
}

int main(int argc, char **argv) {
    cin >> N;
    for(int i = 0; i < N; ++i) {
        llong L, R;
        cin >> L >> R;
        LR.push_back(make_pair(-L, R));
        LRorig.push_back(make_pair(L, R));
    }

    LR.sort();

    vector<list<ipair>::iterator> del;
    llong rmin = INF;
    for(auto it = LR.begin(); it != LR.end(); ++it) {

        if((it == LR.begin() || prev(it)->first != it->first) && it->second < rmin)
            rmin = min(rmin, it->second);
        else
            del.push_back(it);

    }

    for(auto it : del)
        LR.erase(it);

    llong res;
    if(LR.size() == 1)
        res = solve1();
    else
        res = solve();

    cout << res << endl;
}

