	}
}out;

struct Range {
	int x, y; //[x, y]
	Range() :x(0), y(0) {}
	Range(int _x, int _y) :x(_x), y(_y) {}
	Range(pair<int, int> xy) :x(xy.first), y(xy.second) {}
	operator bool() { return x <= y; }
	bool operator==(Range r) { return *this && x == r.x && y == r.y; }
	bool operator!=(Range r) { return !*this || x != r.x || y != r.y; }
	Range operator|(Range r) { return intersects(r) ? Range(min(x, r.x), max(y, r.y)) : Range(0, -1); }
	Range operator&(Range r) { return { max(x, r.x),min(y, r.y) }; }
	Range operator*(int n) { return { x * n,y * n }; }
	Range operator<<(int n) { return { x - n,y - n }; }
	Range operator>>(int n) { return { x + n,y + n }; }
	Range& operator*=(int n) { x *= n; y *= n; return *this; }
	Range& operator<<=(int n) { x -= n; y -= n; return *this; }
	Range& operator>>=(int n) { x += n; y += n; return *this; }
	int size() { return max(0, y - x + 1); }
	bool include(int v) { return x <= v && v <= y; }
	bool intersects(Range r) { return max(x, r.x) <= min(y, r.y); }
	bool contains(Range r) { return x <= r.x && r.y <= y; }
};

