void solve() {
    sort(a,a+n);
    int ans = 0;
    int l = 1, r = 1e9;
    multiset<int> st;
    for (int i = 0; i < n; i++) {
        l = max(l,a[i].fi);
        r = min(r,a[i].se);
        st.insert(a[i].se);
    }
    for (int i = 0; i < n; i++) {
        ans = max(ans, max(0,r-l+1) + a[i].se - a[i].fi + 1);
    }
    for (int i = 0; i < n - 1; i++) {
        st.erase(st.find(a[i].se));
        ans = max(ans, max(0,r - a[i].fi + 1) + max(0,*st.begin() - l + 1));
    }
    cout << ans << endl;
}

