typedef pair<ll,ll> P;
int main(){
    int n; cin >> n;
    vector<pair<ll,ll>> v;
    ll one = 0;
    rep(i,n){
        ll l,r;
        cin >> l >> r;
        v.push_back(P(l,r));
    }
    sort(v.begin(),v.end());
    ll lp =v[0].se;
    rep(i,n){
        //iのみとかせる
        if(i>0 && i+1<n){
            lp = min(lp,v[i+1].se);
            ll res = v[i].se-v[i].fi+1;
            ll re=lp-v[i+1].fi+1;
            if(re<0) re=0;
            one=max(one,res+re);
        }
    }
    ll b[n];
    rep(i,n) b[i]=0;
    ll li = v[n-1].fi;
    ll ri = v[n-1].se;
    ll k = n-1;
    while(li<=min(v[k].se,ri)){
        ri = min(ri,v[k].se);
        b[k]=ri-li+1;
        k--;
    }
    //v[0]を一回目に使うとして良い
    ll last = v[0].se;
    ll ans = 0;
    rep(i,n){
        ll res = 0;
        if(v[i].fi<=last){
            res += last-v[i].fi+1;
        }
        if(i+1<n) res+=b[i+1];
        ans=max(ans,res);
    }
    cout << max(ans,one) << endl;
}

