        l = max(l, v[j].F);
        r = min(r, v[j].S);
        pre[j] = max(0, r - l + 1);
    }
    for(int j = n-1;  j >= 0; j--){
        l = max(l, v[j].F);
        r = min(r, v[j].S);
        suf[j] = max(0, r - l + 1);
    }
    for(int j = 0; j < n; j++){
        int pos = lower_bound(v.begin(), v.end(), mp(v[j].S+1, -1)) - v.begin();
        if(pos == n) continue;

        ans = max(ans, pre[pos-1] + suf[pos]);
    }
