template <class T> void chmin(T& a, T b) { a = min(a, b);}
template <class T> void chmax(T& a, T b) { a = max(a, b);}

constexpr int INF = 1 << 30;
constexpr ll INFL = 1LL << 60;
constexpr ll MOD = 1000000007;
constexpr ld EPS = 1e-12;
ld PI = acos(-1.0);

void solve() {
    ll n;
    cin >> n;
    vpll p;
    rep(i, n) {
        ll l, r;
        cin >> l >> r;
        p.push_back(make_pair(l, r));
    }
    sort(p.begin(), p.end());
    vll f(n), b(n);
    ll l_max = -INFL, r_min = INFL;
    for(ll i = 0; i < n; i++) {
        chmax(l_max, p[i].first);
        chmin(r_min, p[i].second);
        f[i] = max(r_min - l_max + 1, 0ll);
    }
    l_max = -INFL, r_min = INFL;
    for(ll i = n - 1; i >= 0; i--) {
        chmax(l_max, p[i].first);
        chmin(r_min, p[i].second);
        b[i] = max(r_min - l_max + 1, 0ll);
    }
    ll ans = 0;
    for(ll i = 0; i < n - 1; i++) {
        chmax(ans, f[i] + b[i + 1]);
    }
    cout << ans << endl;
    return;
}

int main() {
