			right1=r1;
			left1=l1;
			if(left1>=right1){
				can1=false;
				left1=right1;
			}
		}
	}
	ans1=(can?(Right-Left+1):0)+(can1?(right1-left1+1):0);
	ans=max(ans,ans1);
	for(int j=1000;j<min(10000,n);j++){
		ans1=0;
		Left=v[j].second.first,Right=v[j].second.second;
		left1=v[0].second.first,right1=v[0].second.second;
	    can=true,can1=true;
		for(int i=j+1;i<n-2;i++){
			if(i==j)continue;
			ll l,r,l1,r1;
			l=max(Left,v[i].second.first);
			r=min(Right,v[i].second.second);
			l1=max(left1,v[i].second.first);
			r1=min(right1,v[i].second.second);
			if((right1-left1)-max(0LL,r1-l1)>=(Right-Left)-max(0LL,r-l)){
				Right=r;
				Left=l;
				if(Left>Right){
					can=false;
					Left=Right;
				}
			}
			else{
				right1=r1;
				left1=l1;
				if(left1>=right1){
					can1=false;
					left1=right1;
				}
			}
		}
		ans1=(can?(Right-Left+1):0)+(can1?(right1-left1+1):0);
		ans=max(ans,ans1);
	}
	cout << ans << endl;
}

