int alp_salganda_newe(pair<int,int> x) {
	s1.erase(s1.find(x.S));
    auto nxt = s1.end();
    int res = 0;
	if (nxt != s1.begin()) {
        nxt--;
        res = max(1ll * min(1ll * x.S, 1ll * (*nxt)) - x.F + 1, 0ll) +
                      max(1ll * min((s1.size() > 0 ? *s1.begin() : (int)MOD), min_R_2) - a[n].F + 1, 0ll);
	}
	s1.insert(x.S);
	return res;
}


