template<class T>
T &remax(T &x, const T &y)
{
	return x = max(x, y);
}


void solve(istream &cin = std::cin, ostream &cout = std::cout)
{
	int n;

	cin >> n;

	vector<pair<int, int>> arr(n);

	int ans = 0;

	for (auto &it : arr)
	{
		cin >> it.first >> it.second;
		it.first--;

		remax(ans, it.second - it.first);
	}

	cerr << ans << endl;

	sort(arr.begin(), arr.end());

	int l = 0, r = 0;

	for (int i = 0; i < arr.size(); i++)
	{
		if (arr[i].second < arr[l].second)
			l = i;
		if (arr[i].first > arr[r].first)
			r = i;
	}

	for (int i = 0; i < arr.size(); i++)
		if (i != l && i != r)
			remax(ans, arr[i].second - arr[i].first + max(0, arr[l].second - arr[r].first));

	cerr << ans << endl;

	vector<int> rb(arr.size() + 1);

	rb.back() = arr[r].second;

	for (int i = (int) arr.size() - 1; i >= 0; i--)
		rb[i] = min(rb[i + 1], arr[i].second);

	for (int i = 0; i <= arr.size(); i++)
	{
		int lb = arr[l].first;

		if (i != 0)
			remax(lb, arr[i - 1].first);

		remax(ans, max(0, arr[l].second - lb) + max(0, rb[i] - arr[r].first));
	}

	cout << ans << endl;
}


