using namespace std;

using lli = long long int;

lli calc(vector<pair<lli, lli>> &a) {
  lli mi = 1e18;
  lli ma = 0;
  for (auto &s : a) {
    mi = min(s.second, mi);
    ma = max(s.first, ma);
  }
  return mi - ma + 1 < 0 ? 0 : mi - ma + 1;
}
lli calc_piv(vector<pair<lli, lli>> &a, int start, int last) {
  vector<pair<lli, lli>> b;
  for (int i = start; i < last; i++) {
    b.push_back(a[i]);
  }
  return calc(b);
}
lli piv(vector<pair<lli, lli>> &a, int m1) {

  return calc_piv(a, 0, m1) + calc_piv(a, m1, a.size());
}
lli bin(vector<pair<lli, lli>> &a) {
  lli l = 1;
  lli u = a.size() - 1;
  while (l + 1 < u) {
  //  cerr << l << " " << u << endl;
    lli m1 = (2 * l + u) / 3;
    lli m2 = (l + 2 * u) / 3;
    if (piv(a, m1) > piv(a, m2)) {
      u = m1;
    } else {
      l = m2;
    }
  }
  // for (int i = 1; i < a.size() - 1; i++) {
  //   cerr << "piv: " << i << " " << piv(a, i) << endl;
  // }
  return max({piv(a, u), piv(a, l + 1), piv(a, l)});
}
void solve(long long n, std::vector<long long> l, std::vector<long long> r) {
  if(n==2){
    cout << r[0]-l[0] + r[1]-l[1] + 2 << endl;
    return;
  }
  vector<pair<lli, lli>> a(n);
  rep(i, n) a[i] = make_pair(l[i], r[i]);
  sort(a.begin(), a.end());
  lli ans = bin(a);
  rep(i,n) ans = max(a[i].second - a[i].first + 1, ans);

  sort(a.begin(), a.end(), [](pair<lli, lli> l, pair<lli, lli> r) -> bool {
    return l.second == r.second ? l.first > r.first : l.second > r.second;
  });
  cout << max(ans, bin(a)) << endl;
}

int main() {
  int a;
  long long N;
  scanf("%lld", &N);
  std::vector<long long> L(N);
  std::vector<long long> R(N);
  for (int i = 0; i < N; i++) {
    scanf("%lld", &L[i]);
    scanf("%lld", &R[i]);
  }
  solve(N, std::move(L), std::move(R));
  return 0;
}

