ll l_max = 0, r_min = 1e9+5;

struct problem {
    ll l;
    ll r;
    ll a;
    ll b;

    bool operator<(const problem& other) const {
        if (a < other.a ) return true;
        else if(a > other.a ) return false;
        else return b > other.b;
    }
};

int main() {
    int N, l_arg, r_arg;
    cin >> N;

    vector<ll> L(N), R(N);
    vector<problem> problems(N);
    REP(i, N) {
        ll l, r;
        cin >> l >> r;
        L[i] = l;
        R[i] = r+1;
        if(l_max < l) {
            l_max = l;
            l_arg = i;
        }
        if(r_min > r + 1) {
            r_min = r + 1;
            r_arg = i;
        }
    }

    ll length_max = 0;
    REP(i, N) {
        problems[i].l = L[i];
        problems[i].r = R[i];
        problems[i].a = max(R[i] - l_max, ll(0));
        problems[i].b = max(r_min - L[i], ll(0));
        if(R[i] - L[i] > length_max) length_max = R[i] - L[i];
    }

    sort(ALL(problems));

    set<ll> tset;
    ll ans = 0, min1, min2;
    min1 = problems[0].a;
    min2 = 0;
    ans = min1 + min2;

    FOR(i, 1, N-1) {
        min1 = problems[i].a;
        tset.insert(problems[i-1].b);
        min2 = *tset.begin();
        if(ans < min1 + min2) ans = min1 + min2;
    }

    tset.insert(problems[N-1].b);
    if(ans < *tset.begin()) {
        ans = *tset.begin();
    }

    if(ans < length_max + max(min(R[l_arg], R[r_arg]) - max(L[l_arg], L[r_arg]), ll(0)))
        ans = length_max + max(min(R[l_arg], R[r_arg]) - max(L[l_arg], L[r_arg]), ll(0));

    cout << ans << endl;
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

const int MX = 100000;

int l[MX], r[MX], pL[MX], pR[MX], sL[MX], sR[MX];

int main() {
	int n;
	ignore = scanf("%d", &n);
	for (int i = 0; i < n; i++) ignore = scanf("%d %d", l + i, r + i);

	pL[0] = l[0];
	pR[0] = r[0];
	for (int i = 1; i < n; i++) {
		pL[i] = max(pL[i - 1], l[i]);
		pR[i] = min(pR[i - 1], r[i]);
	}

	sL[n - 1] = l[n - 1];
	sR[n - 1] = r[n - 1];
	for (int i = n - 2; i >= 0; i--) {
		sL[i] = max(sL[i + 1], l[i]);
		sR[i] = min(sR[i + 1], r[i]);
	}

	int ans = 0;
	for (int i = 0; i < n; i++) {
		int ll = -1, rr = 2e9;
		if (i > 0) {
			ll = max(pL[i - 1], ll);
			rr = min(pR[i - 1], rr);
		}
		if (i + 1 < n) {
			ll = max(sL[i + 1], ll);
			rr = min(sR[i + 1], rr);
		}

		ans = max(r[i] - l[i] + 1 + max(rr - ll + 1, 0), ans);
	}

	int k = min_element(r, r + n) - r;
	int L = l[k], R = r[k];

	vector<pair<int, int>> vec;
	for (int i = 0; i < n; i++) {
		if (i != k) vec.emplace_back(l[i], r[i]);
	}

	sort(vec.begin(), vec.end());

	l[n - 2] = vec.back().first;
	r[n - 2] = vec.back().second;
	for (int i = n - 3; i >= 0; i--) {
		l[i] = max(l[i + 1], vec[i].first);
		r[i] = min(r[i + 1], vec[i].second);
	}

	for (int i = 0; i < n - 1; i++) {
		ans = max(ans, max(R - L + 1, 0) + max(r[i] - l[i] + 1, 0));
		L = max(vec[i].first, L);
	}

	printf("%d\n", ans);

	return 0;
}

