    for (int i = 0; i < n; i++) {
        if (L[maxL_idx] < L[i] || (L[i] == L[maxL_idx] && R[i] < R[maxL_idx])) {
            maxL_idx = i;
        }

        if (R[minR_idx] > R[i] || (R[i] == R[minR_idx] && L[i] > L[minR_idx])) {
            minR_idx = i;
        }
    }

    ll ans = max(R[minR_idx] - L[maxL_idx] + 1, 0LL);
    {
        ll tmp = 0;
        for (int i = 0; i < n; i++) {
            if (i == minR_idx || i == maxL_idx) continue;
            tmp = max(tmp, R[i] - L[i] + 1);
        }
        ans += tmp;
    }

    if (minR_idx == maxL_idx) {
        cout << ans << "\n";
        return 0;
    }

    ll L1 = L[minR_idx], R1 = R[minR_idx], L2 = L[maxL_idx], R2 = R[maxL_idx];
    vector<ll> d1(n), d2(n);
    vector<int> ids(n);
    for (int i = 0; i < n; i++) {
        ids[i] = i;
        ll nex_L1 = max(L1, L[i]);
        ll nex_R1 = min(R1, R[i]);
        d1[i] = max(R1 - L1 + 1, 0LL) - max(nex_R1 - nex_L1 + 1, 0LL);

        ll nex_L2 = max(L2, L[i]);
        ll nex_R2 = min(R2, R[i]);
        d2[i] = max(R2 - L2 + 1, 0LL) - max(nex_R2 - nex_L2 + 1, 0LL);
    }
    sort(ids.begin(), ids.end(), [&](const int i1, const int i2){
        if (d1[i1] != d1[i2]) return d1[i1] < d1[i2];
        return d2[i1] > d2[i2];
    });

    vector<ll> dd1(n, 0), dd2(n, 0);
    for (int ii = 0; ii < n; ii++) {
        int i = ids[ii];
        dd1[ii] = d1[i];
        if (ii > 0) dd1[ii] = max(dd1[ii], dd1[ii-1]);
    }

    for (int ii = n - 1; ii >= 0; ii--) {
        int i = ids[ii];
        dd2[ii] = d2[i];
        if (ii < n - 1) dd2[ii] = max(dd2[ii], dd2[ii + 1]);
    }

    ll sum = max(R1 - L1 + 1, 0LL) + max(R2 - L2 + 1, 0LL);
    ll ans2 = max(sum - dd1[n-1], sum - dd2[0]);
    for (int i = 0; i < n - 1; i++) {
        ans2 = max(ans2, sum - dd1[i] - dd2[i + 1]);
    }
    ans = max(ans, ans2);
    cout << ans << "\n";
    return 0;
}

