#define P(x, y) make_pair(x, y)
#define mx 100005

struct st {
    int front = 0;
    vector<pair<int, int>> Q;
	st() : front(0) {}

    void insert(pair<int, int> x) {
		while (front < (int)Q.size() && x >= Q.back())
            Q.pop_back();
        Q.push_back(x);
	}

    void del(int x) {
        while (front < (int)Q.size() && Q[front].second <= x) {
            front += 1;
        }
	}

	int get() {
        if (front < (int)Q.size()) 
            return Q[front].first;
        else 
            return -(1 << 30);
	}
};

vector<pair<int, int > > A;
int B[mx], ns=1 ;
pair<int, int> ar[mx];
long long dp[2][mx];
long long ans = 0;
long long sum[mx];
bool flagged[mx];
void process() {
	sort(B+1, B +1+ ns);
	for (int i = 1;i < ns;++i) {
		sum[i] = sum[i - 1] - B[i];
	}	
}
int N, k;
void calc_dp(int co) {
	st dq;
	bool flip = (co) % 2;
	int n = A.size();
	for (int i = 0;i < n;++i) {
		dq.insert(P(dp[!flip][i] + A[i].second, A[i].second));
		dq.del(A[i].first - 1);
		dp[flip][i + 1] = dq.get() - A[i].first;
	}
	ans = max(ans, dp[flip][n] + sum[k - co]);
}
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(nullptr);

	cin >> N; k = 2;
	for (int i = 0;i < N;++i) {
		cin >> ar[i].first >> ar[i].second;
		++ar[i].second;
	}

	for (int i = 0; i <= N;++i)
		dp[0][i] = -(1 << 30);
	dp[0][0] = 0;
	for (int i = 0;i < N;++i)
		for (int j = i + 1;j < N;++j) {
			if (ar[i].first <= ar[j].first && ar[j].second <= ar[i].second && !flagged[i]) {
				flagged[i] = 1;
				B[ns++] = -(ar[i].second - ar[i].first);
			}
			else if (ar[i].first >= ar[j].first && ar[j].second >= ar[i].second &&!flagged[j]) {
				flagged[j] = 1;
				B[ns++] = -(ar[j].second - ar[j].first);
			}
		}

	for (int i = 0;i < N;++i)
		if (!flagged[i])
			A.push_back(ar[i]);
	process();	sort(A.begin(), A.end());
	int  sz = A.size();
	for (int i = 1;i <= min(k, sz);++i)
		calc_dp(i);

    vector<int> sizes;
    for(int i = 0; i < N; i += 1) {
        sizes.push_back(ar[i].second - ar[i].first);
    }

    sort(sizes.begin(), sizes.end());
    reverse(sizes.begin(), sizes.end());

    long long sum = 0;
    for (int i = 0; i + 1 < k; i += 1) {
        sum += sizes[i];
    }

	cout << max(ans, sum) << endl;
}

