int find_ans(vector< pair<int,int> >c,int x2,int y2)
{
    c.pb({inf,inf});
    sort(all(c));
    int n=c.size();
    reverse(all(c));
    c.pb({0,0});
    reverse(all(c));
    int pref[n+2];
    int suf[n+2];
    for (int i=0;i<=n+1;++i){
        pref[i]=inf;
        suf[i]=inf;
    }
    for (int i=1;i<=n;++i){
        pref[i]=min(pref[i-1],c[i].ss);
    }
    for (int i=n;i>=1;--i){
        suf[i]=min(suf[i+1],c[i].ff);
    }
    int ans=max(x2,y2);
    for (int i=n+1;i>=1;--i){
        int f=min(x2,suf[i])+min(pref[i-1],y2);
        ans=max(ans,f);
    }
    return ans;
}

void upd(int& l,int& r,int l1,int r1)
{
    l=max(l,l1);
    r=min(r,r1);
}

int cost(int l,int r)
{
    if (l<=r)return r-l+1;
    return 0;
}

int per(int l,int r,int l1,int r1)
{
    l=max(l,l1);
    r=min(r,r1);
    return cost(l,r);
}

