bool update()
{
    bool cc=false;
    while(true){
        bool f=false;
        iter it=setik1.lower_bound({r1+1,0});
        if (it!=setik1.end()){
            pair<int,int>a=*it;
            setik1.erase({a.ff,a.ss});
            setik2.erase({a.ss,a.ff});
            upd(l2,r2,a.ff,a.ss);
            cc=true;
            f=true;
        }
        if (!f)break;
    }
    while(true){
        bool f=false;
        iter it=setik2.lower_bound({l1,0});
        if (it!=setik2.begin()){
            --it;
            pair<int,int>a=*it;
            swap(a.ff,a.ss);
            setik2.erase({a.ss,a.ff});
            setik1.erase({a.ff,a.ss});
            upd(l2,r2,a.ff,a.ss);
            cc=true;
            f=true;
        }
        if (!f)break;
    }
    while(true){
        bool f=false;
        iter it=setik1.lower_bound({r2+1,0});
        if (it!=setik1.end()){
            pair<int,int>a=*it;
            setik1.erase({a.ff,a.ss});
            setik2.erase({a.ss,a.ff});
            upd(l1,r1,a.ff,a.ss);
            cc=true;
            f=true;
        }
        if (!f)break;
    }
    while(true){
        bool f=false;
        iter it=setik2.lower_bound({l2,0});
        if (it!=setik2.begin()){
            --it;
            pair<int,int>a=*it;
            swap(a.ff,a.ss);
            setik2.erase({a.ss,a.ff});
            setik1.erase({a.ff,a.ss});
            upd(l1,r1,a.ff,a.ss);
            cc=true;
            f=true;
        }
        if (!f)break;
    }
    return cc;
}

