using namespace std;

int n, ans;
pair<int, int> a[100100];

int getAns(int minL, int maxL, int minR, int maxR)
{
  return max(0, maxL - minL + 1) + max(0, maxR - minR + 1);
}

void solve1()
{
  sort(a, a + n);
  vector<int> minPrefix(n), minSuffix(n);
  minPrefix[0] = a[0].second;
  for (int i = 1; i < n; i++)
    minPrefix[i] = min(minPrefix[i - 1], a[i].second);
  minSuffix[n - 1] = a[n - 1].second;
  for (int i = n - 2; i >= 0; i--)
    minSuffix[i] = min(minSuffix[i + 1], a[i].second);

  for (int i = 0; i < n - 1; i++)
    ans = max(ans, getAns(a[i].first, minPrefix[i], a[n - 1].first, minSuffix[i + 1]));
  cout << ans << endl;
}

void solve2(int minL, int maxL, vector<pair<int, int>> l, vector<pair<int, int>> r)
{
  int minR = r[0].first, maxR = r[0].second;
  for (auto u : r)
  {
    minR = max(minR, u.first);
    maxR = min(maxR, u.second);
  }
  if (minR > maxR)
  {
    cout << ans << endl;
    exit(0);
  }

  if (l.empty())
  {
    ans = max(ans, getAns(minL, maxL, minR, maxR));
    cout << ans << endl;
    exit(0);
  }

  int m = l.size();
  vector<int> minPrefix(m), minSuffix(m);
  minPrefix[0] = l[0].second;
  for (int i = 1; i < m; i++)
    minPrefix[i] = min(minPrefix[i - 1], l[i].second);
  minSuffix[m - 1] = l[m - 1].second;
  for (int i = m - 2; i >= 0; i--)
    minSuffix[i] = min(minSuffix[i + 1], l[i].second);

  // put all to left
  ans = max(ans, getAns(max(minL, l[m - 1].first), min(maxL, minPrefix[m - 1]), minR, maxR));
  // put all to right
  ans = max(ans, getAns(minL, maxL, minR, min(maxR, minPrefix[m - 1])));
  // split
  for (int i = 0; i < m - 1; i++)
    ans = max(ans, getAns(max(minL, l[i].first), min(maxL, minPrefix[i]), minR, min(maxR, minSuffix[i + 1])));
  cout << ans << endl;
}

int main()
{
  ios_base::sync_with_stdio(0);
  cin.tie(0);

  cin >> n;
  for (int i = 0; i < n; i++)
  {
    cin >> a[i].first >> a[i].second;
    ans = max(ans, a[i].second - a[i].first + 1);
  }

  int minRId = 0;
  for (int i = 1; i < n; i++)
    if (a[i].second < a[minRId].second)
      minRId = i;

  vector<pair<int, int>> l, r;
  for (int i = 0; i < n; i++)
    if (i != minRId)
    {
      if (a[i].first > a[minRId].second) r.push_back(a[i]);
      else l.push_back(a[i]);
    }

  sort(l.begin(), l.end());
  sort(r.begin(), r.end());

  if (r.empty()) solve1();
  else solve2(a[minRId].first, a[minRId].second, l, r);
}

