      if (l <= r) {
        return r - l + 1;
      } else {
        return 0;
      }
    }

    it_t operator+(const it_t &x) const {
      return it_t({std::max(l, x.l), std::min(r, x.r)});
    }
  };
  std::vector<it_t> it(n);
  u32 ans = 0;
  for (auto &e : it) {
    std::cin >> e.l >> e.r;
  }
  {
    std::vector<it_t> suf(n), pre(n);
    pre.front() = {0, Inf};
    for (const usize i : rep(0, n - 1)) {
      pre[i + 1] = pre[i] + it[i];
    }
    suf.back() = {0, Inf};
    for (const usize i : revrep(1, n)) {
      suf[i - 1] = suf[i] + it[i];
    }
    for (const usize i : rep(0, n)) {
      chmax(ans, it[i].len() + (pre[i] + suf[i]).len());
    }
  }
  std::sort(it.begin(), it.end(), [&](auto &x, auto &y) {
