bool cmp1(const pii &lhs, const pii &rhs) {
    return (lhs.first == rhs.first) ? lhs.second > rhs.second : lhs.first < rhs.first;
}

bool cmp2(const pii &lhs, const pii &rhs) {
    return (lhs.second == rhs.second) ? lhs.first < rhs.first : lhs.second > rhs.second;
}

inline int calc_cost(const pair<pii, pii> &asc) {
    return max(0, asc.first.second - asc.first.first + 1) + max(0, asc.second.second - asc.second.first + 1);
}

inline pii intersect(const pii &x, const pii &y) {
    return make_pair(max(x.first, y.first), min(x.second, y.second));
}

int main() {
    int n;
    cin >> n;
    vpii sec(n);
    REP(i, n) {
        cin >> sec[i].first >> sec[i].second;
    }
    pair<pii, pii> asc;
    sort(ALL(sec), cmp1);
    asc.first = sec[0];
    sec.erase(sec.begin());
    sort(ALL(sec), cmp2);
    asc.second = sec[0];
    sec.erase(sec.begin());
    REP(i, n - 2) {
        auto cnd1 = asc;
        auto cnd2 = asc;
        cnd1.first = intersect(cnd1.first, sec[i]);
        cnd2.second = intersect(cnd2.second, sec[i]);
        if(calc_cost(cnd1) > calc_cost(cnd2)) asc = cnd1;
        else asc = cnd2;
    }

    cout << calc_cost(asc) << "\n";

    return 0;
}

