constexpr int MAX = 1'000'000'000;

int main() {
    int n;
    cin >> n;
    vector<pair<int, int>> a(n);
    for (auto &e : a) {
        cin >> e.first >> e.second;
    }

    auto solve = [&] () -> int {
        vector<int> s(n), t(n);
        int l = 1, r = MAX;
        for (int i = 0; i < n; i++) {
            const auto &e = a[i];
            chval(l, <, e.first);
            chval(r, >, e.second);
            s[i] = max(0, r - l + 1);
        }
        l = 1; r = MAX;
        for (int i = n; i --> 0;) {
            const auto &e = a[i];
            chval(l, <, e.first);
            chval(r, >, e.second);
            t[i] = max(0, r - l + 1);
        }
        int res = 0;
        for (int i = 0; i + 1 < n; i++) {
            chval(res, <, s[i] + t[i + 1]);
        }
        return res;
    };

    using P = pair<int, int>;
    auto f = [](const P &l, const P &r) -> bool {
        if (l.first == r.first) return (l.second > r.second);
        return (l.first < r.first);
    };

    sort(a.begin(), a.end(), f);

    cout << solve() << '\n';
    return 0;
}

