  al=a[ap].scd.fst;ar=a[ap].scd.scd;
  flag[ap]=1;
  bl=a[n-1].scd.fst;br=a[n-1].scd.scd;
  rep(i,n){
    if(flag[i]==1) continue;
    int aal=al,aar=ar,bbl=bl,bbr=br;
    int aap=aar-aal+1,bbp=bbr-bbl+1;
    int acnt=0,bcnt=0;
    aal=max(a[i].scd.fst,aal);
    aar=min(a[i].scd.scd,aar);
    bbl=max(a[i].scd.fst,bbl);
    bbr=min(a[i].scd.scd,bbr);
    //cout<<" "<<aal<<" "<<aar<<" "<<bbl<<" "<<bbr<<endl;
    acnt=max((int)0,aar-aal+1);
    bcnt=max((int)0,bbr-bbl+1);
    if(aap-acnt<=bbp-bcnt){
      al=aal;
      ar=aar;
    }else{
      bl=bbl;
      br=bbr;
    }
    //cout<<al<<" "<<ar<<" "<<bl<<" "<<br<<endl;
  }
  ans=max(max((int)0,ar-al+1)+max((int)0,br-bl+1),ans);
  cout<<ans<<endl;


  return 0;
}

