        if(chmin(rmin,r))rmidx=i;
        //cout <<lh[i]<< " "<<rh[i]<<endl;
    }

    //ｌの最大値とrの最小値を同じグループに含まない場合
    //その2組以外をlの昇順で並び替える
    int ans=0;
    v.push_back(make_pair(0,0));
    for(int i=0;i<n;i++){
        if(i==lmidx||i==rmidx)continue;
        chmax(maxLen,rh[i]-lh[i]+1);
        v.push_back(make_pair(lh[i],rh[i]));
    }
    v.push_back(make_pair(lh[lmidx],rh[lmidx]));
    sort(v.begin(),v.end(), sortP);
