bool comp(pii a, pii b) {
    if (a.F != b.F) return a.F < b.F;
    return a.S > b.S;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);


    int n;
    cin >> n;
    vector<pii> v(n);
    rep(i, n) cin >> v[i].F >> v[i].S;

    vector<pii> l(n), r(n);
    rep(i, n) { l[i].F = v[i].F; l[i].S = i; }
    rep(i, n) { r[i].F = v[i].S; r[i].S = i; }
    sort(all(l), comp);
    sort(all(r));
    // cout << endl; rep(i, n) cout << l[i].F << " " << l[i].S << endl;
    // cout << endl; rep(i, n) cout << r[i].F << " " << r[i].S << endl;

    // 右端が一番左, 左端が一番右のものに注目
    // 考えやすい

    // 右端が一番左で左端が一番右のが同じものの場合
    if (l[n - 1].S == r[0].S) {
        ll ans = 0;
        rep(i, n) {
            if (i == l[n - 1].S) continue;
            chmax(ans, v[i].S - v[i].F + 1);
        }
        ans += r[0].F - l[n - 1].F + 1;
        cout << ans << endl;
        return 0;
    }

    // 右端が一番左で左端が一番右のが違うものの場合
    // その2つを同じグループにする場合
    ll ans = 0;
    rep(i, n) {
        if (i == l[n - 1].S || i == r[0].S) continue;
        chmax(ans, v[i].S - v[i].F + 1);
    }

    // その2つを違うグループにする場合
    // 左側のグループの右端で全探索
    vector<int> rmin(n, inf);
    for (int i = n - 1; i >= 0; --i) {
        chmin(rmin[i], v[l[i].S].S);
    }
    // rep(i, n) cout << rmin[i] << " "; cout << endl;
    int l1 = v[r[0].S].F, r1 = r[0].F, l2 = l[n - 1].F, r2 = v[l[n - 1].S].S;

    rep(i, n - 1) { // 左端に関して左からどこまで左のグループに入れるか
        if (i == l[n - 1].S || i == r[0].S) continue;
        chmax(l1, l[i].F);
        // 残りはすべて右のグループ
        chmin(r2, rmin[i + 1]);
        chmax(ans, r1 - l1 + 1 + r2 - l2 + 1);
        // cout << l1 << " " << r1 << " " << l2 << " " << r2 << endl;
    }
    cout << ans << endl;
}

