vector<pair<char,ll>> runlength(string s){
	ll i = 0;
	ll n = s.size();
	vector<pair<char, ll>> run;
	while (i < n) {
		char t = s[i];
		int k = 0;
		while (i + k < n && s[i + k] == t) k++;
		run.push_back(pair<char, ll>(t, k));
		i += k;
	}
	return run;
}

