int maxl = -1, minr = 1001001001;

class Range {
public:
  int l, r;
  Range() {}
  Range(int l, int r) : l(l), r(r) {}
};

bool cmp(const Range &a, const Range &b)
{
  int l = a.r;
  int r = b.r;
  if (l == r) return a.l > b.l;
  return l < r;
}

vector<Range> ranges;

int lmax[100010];
int rmin[100010];

int main() {
  int n;
  cin >> n;
  for (int i = 0; i < n; ++i) {
    int l, r;
    cin >> l >> r;
    ++r;
    ranges.emplace_back(l, r);
  }
  sort(ranges.begin(), ranges.end(), cmp);
  int p, q;
  for (int i = 0; i < n; ++i) {
    Range &range = ranges[i];
    if (maxl < range.l) { 
      p = i;
      maxl = range.l;
    }
    if (minr > range.r) {
      q = i;
      minr = range.r;
    }
  }
  int ans = 0;
  for (int i = 0; i < n; ++i) {
    if (i == p || i == q) continue;
    Range &range = ranges[i];
    ans = max(ans, range.r-range.l);
  }
  ans += minr-maxl;

  lmax[0] = ranges[0].l;
  rmin[n-1] = ranges[n-1].r;
  for (int i = 1; i < n; ++i) {
    lmax[i] = max(lmax[i-1], ranges[i].l);
    rmin[n-i-1] = min(rmin[n-i], ranges[n-i-1].r);
  }
  for (int i = 0; i < n-1; ++i) {
    ans = max(ans, (rmin[i+1]-maxl)+(minr-lmax[i]));
  }
  cout << ans << endl;
}

