#define REP(i, n) for(int i=0; i<n; i++)
#define REPi(i, a, b) for(int i=int(a); i<int(b); i++)
#define MEMS(a,b) memset(a,b,sizeof(a))
#define mp make_pair
template<class T>bool chmax(T &a, const T &b) { if (a<b) { a=b; return 1; } return 0; }
template<class T>bool chmin(T &a, const T &b) { if (b<a) { a=b; return 1; } return 0; }
const ll MOD = 1e9+7;

int main(){
    ll N;
    cin >> N;
    vector<pair<ll, ll>> LR(N);
    priority_queue<ll, vector<ll>, greater<ll>> queR;
    priority_queue<ll> queL;
    REP(i,N){
        ll l, r;
        scanf("%lld %lld", &l, &r);
        LR[i] = mp(l, -r);
        queL.push(l);
        queR.push(r);
    }

    sort(LR.begin(), LR.end());

    ll maxl1 = -1;
    ll minr1 = 1e10;
    ll ans = 0;
    map<ll, ll> getL;
    map<ll, ll> getR;
    REP(i,N-1){
        ll tmp = 0;
        auto p = LR[i];
        chmax(maxl1, p.first);
        chmin(minr1, -p.second);

        getL[p.first]++;
        getR[-p.second]++;

        ll maxl2, minr2;
        while(1){
            maxl2 = queL.top();
            if(getL[maxl2] > 0){
                getL[maxl2]--;
                queL.pop();
            }
            else
                break;
        }
        while(1){
            minr2 = queR.top();
            if(getR[minr2] > 0){
                getR[minr2]--;
                queR.pop();
            }
            else
                break;
        }
        //printf("%lld, %lld\n", maxl2, minr2);

        //tmp = (minr1 + minr2) - (maxl1 + maxl2) + 2;
        tmp = max(0LL, minr1-maxl1+1) + max(0LL, minr2-maxl2+1);
        chmax(ans, tmp);
    }

    cout << ans << endl;
    return 0;
}

