using LL = long long;

namespace _buff {

const size_t BUFF = 1 << 19;
char ibuf[BUFF], *ib = ibuf, *ie = ibuf;
char getc() {
    if (ib == ie) {
        ib = ibuf;
        ie = ibuf + fread(ibuf, 1, BUFF, stdin);
    }
    return ib == ie ? -1 : *ib++;
}

}

LL read() {
    using namespace _buff;
    LL ret = 0;
    bool pos = true;
    char c = getc();
    for (; (c < '0' || c > '9') && c != '-'; c = getc()) {
        assert(~c);
    }
    if (c == '-') {
        pos = false;
        c = getc();
    }
    for (; c >= '0' && c <= '9'; c = getc()) {
        ret = (ret << 3) + (ret << 1) + (c ^ 48);
    }
    return pos ? ret : -ret;
}

int main() {
    int n = read();
    vector<pair<int, int> > seg(n);
    generate_n(seg.begin(), n, []() -> pair<int, int> {
        return {read(), read()};
    });
    sort(seg.begin(), seg.end());

    set<int> sr1, sr2;
    for (int i = 0; i < n - 1; ++i) {
        sr1.emplace(seg[i].second);
    }
    sr2.emplace(seg.back().second);

    int ans = 0;
    for (int i = n - 2; i >= 0; --i) {
        int l1 = seg[i].first;
        int l2 = seg.back().first;
        int r1 = seg[i].second;
        int r2 = *sr2.begin();
        int rr1 = sr1.empty() ? INT_MAX : *sr1.begin();
        int rr2 = INT_MAX;

        ans = max(ans, max(min(rr1, r1) - l1 + 1, 0) + max(min(rr2, r2) - l2 + 1, 0));
        swap(rr1, rr2);
        ans = max(ans, max(min(rr1, r1) - l1 + 1, 0) + max(min(rr2, r2) - l2 + 1, 0));

        sr1.erase(seg[i].second);
        sr2.emplace(seg[i].second);
    }

    cout << ans;
    return 0;
}

