coord b[MAX_N + 1];

int s[MAX_N + 1];
int d[MAX_N + 1];

int rez;

void inter(int &st, int &dr, int a, int b)
{
    if(a > dr || b < st)
    {
        st = dr = 0;
    }

    else
    {
        st = max(st, a);
        dr = min(dr, b);
    }
}

int k;
int diff[MAX_N * 2 + 1];

int dx[MAX_N * 2 + 1];

void getD()
{
    k = 0;
    dx[++ k] = diff[1];

    for(int i = 2; i <= 2*n; i ++)
    {
        if(diff[i] != diff[i - 1])
            dx[++ k] = diff[i];
    }
}

void doCalc(coord a[])
{
    int st = 1;
    int dr = (int)(1e9);
    for(int i = 1; i <= n; i ++)
