  rR = RL[0].first;
  rL = RL[0].second;
  rep(i,N) {
    if(RL[i].first >= rL) {
      rR = RL[i].first;
      rL = max(rL,(ll)RL[i].second);
      rm[i+1] = rR - rL + 1; 
    } else {
      break;
    }
  }
  lL = RL[N-1].second;
  lR = RL[N-1].first;
  drep(i,N) {
    if(RL[i].second <= lR) {
      lL = max(lL,(ll)RL[i].second);
      lm[N-i] = lR - lL + 1;
    } else {
      break;
    }
  }
  ll ans2 = 0;
  srep(i,1,N) {
    ans2 = max(ans2,lm[i]+rm[N-i]);
  }
  cout << max(ans,ans2) << endl;
  return 0;
}

