void solve() {
	int n;
	cin >> n;
	vector<pii> arr;
	for (int i = 0; i < n; ++i) {
		int l, r;
		cin >> l >> r;
		--l;
		arr.push_back({l, r});
	}
	sort(arr.begin(), arr.end());
	vector<pii> pref = {{-INF, INF}}, suff = {{-INF, INF}};

	for (int i = 0; i < n; ++i) {
		pref.push_back(comb(pref.back(), arr[i]));
		suff.push_back(comb(suff.back(), arr[n - 1 - i]));
	}

	int ans = 0;
	for (int i = 1; i < n; ++i) {
		ans = max(ans, max(0, pref[i].ss - pref[i].ff) + max(0, suff[n - i].ss - suff[n - i].ff));
	}

	for (int i = 0; i < n; ++i) {
		auto tmp = comb(pref[i], suff[n - 1 - i]);
		ans = max(ans, arr[i].ss - arr[i].ff + max(0, tmp.ss - tmp.ff));
	}

	sort(arr.begin(), arr.end(), [&](auto& a, auto& b) {
		return a.ss < b.ss;
	});

	pref = {{-INF, INF}}, suff = {{-INF, INF}};

	for (int i = 0; i < n; ++i) {
		pref.push_back(comb(pref.back(), arr[i]));
		suff.push_back(comb(suff.back(), arr[n - 1 - i]));
	}

	for (int i = 1; i < n; ++i) {
		ans = max(ans, max(0, pref[i].ss - pref[i].ff) + max(0, suff[n - i].ss - suff[n - i].ff));
	}

	cout << ans << "\n";
}


