struct seg {
	int l, r;
	bool operator< (const seg& b) const {
		return r < b.r;
	}

	seg operator* (const seg& b) const {
		return {max(l, b.l), min(r, b.r)};
	}

	int len() const {
		return max(0, r-l+1);
	}
};

