#include <stack>
#include <functional>
#include <utility>
template<typename T>
class SWAG {
    using P = pair<T, T>;  // raw_data, fold_all
    using Func = function<T(T, T)>;
    stack<P> front_stack, back_stack;
    Func func;

public:
    SWAG(Func _func)
        : func(_func) {}
    void push(T ele) {
        if (back_stack.empty()) {
            back_stack.emplace(ele, ele);
        } else {
            T lst = back_stack.top().second;
            back_stack.emplace(ele, func(lst, ele));
        }
    }
    void pop() {
        if (front_stack.empty()) {
            T fold = back_stack.top().first;
            front_stack.emplace(fold, fold);
            back_stack.pop();
            while (back_stack.size()) {
                T ele = back_stack.top().first;
                front_stack.emplace(ele, fold = func(ele, fold));
                back_stack.pop();
            }
        }
        front_stack.pop();
    }
    T fold_all() {
        if (front_stack.empty()) {
            return back_stack.top().second;
        } else if (back_stack.empty()) {
            return front_stack.top().second;
        } else {
            return func(front_stack.top().second, back_stack.top().second);
        }
    }
};

