        else{
            ans=max(ans,R-(getMax(lst)+max(getMax(rst),ma)-2));
            if(r-l+1==1) {}
            else{
                ans=max(ans,R-gao(getMax(lst),getMax(rst),mi,ma));
            }
        }
        for(int i=l;i<=r;i++) lst.insert(dat[i].first);
    }
    printf("%d\n",ans);
}

