	for(int i=2;i<=n;i++)
	{
		lx[i]=max(lx[i-1],d[i].l);
		rx[i]=min(rx[i-1],d[i].r);
	}
	ly[n]=d[n].l; ry[n]=d[n].r;
	for(int i=n-1;i>=1;i--)
	{
		ly[i]=max(ly[i+1],d[i].l);
		ry[i]=min(ry[i+1],d[i].r);
	}
	for(int i=1;i<n;i++)
		ans=max(ans,max(0,rx[i]-lx[i]+1)+max(0,ry[i+1]-ly[i+1]+1));
	printf("%d\n",ans);
	return 0;
}

