ll len(ll L, ll R) {
    return max(R - L + 1, 0);
}

ll solve(ll N, vector<pl> v) {
    sort(ALL(v));
    auto f = [](pl p1, pl p2) { return make_pair(max(p1.first, p2.first), min(p1.second, p2.second)); };
    auto e = make_pair(numeric_limits<ll>::min(), numeric_limits<ll>::max());
    SegmentTree<pl> st(v, f, e);
    ll ans = numeric_limits<ll>::min();
    for (size_t i = 0; i < N - 1; i++) {
        ll L = st[i].first;
        ll R = st[i].second;
        ll left_R = st.query(0, i).second;
        pl right = st.query(i + 1, N);
        ll tmp1 = len(L, min(left_R, R)) + len(right.first, right.second);
        ll tmp2 = len(L, R) + len(right.first, min(left_R, right.second));
        ans = max({ans, tmp1, tmp2});
    }
    return ans;
}

vector<vector<long long>> base(long long n, long long N) {
    long long SIZE = 1;
    for (long long i = 0; i < N; i++) SIZE *= n;
    vector<vector<long long>> ans(SIZE, vector<long long>());
    for (long long rep = 0; rep < N; rep++) {
        SIZE /= n;
        for (long long i = 0; i < ans.size(); i++) {
            ans[i].push_back((i / SIZE) % n);
        }
    }
    return ans;
}

ll guchoku(ll N, vector<pl> v) {
    ll ans = 0;
    auto e = base(2, N);
    auto f = [](pl p1, pl p2) { return make_pair(max(p1.first, p2.first), min(p1.second, p2.second)); };
    auto e_ = make_pair(numeric_limits<ll>::min(), numeric_limits<ll>::max());
    for (size_t i = 0; i < e.size(); i++) {
        map<ll, ll> m;
        for (auto x : e[i]) m[x]++;
        if (!m[0] || !m[1]) {
            continue;
        }
        pl p1 = e_, p2 = e_;
        for (size_t j = 0; j < e[i].size(); j++) {
            if (e[i][j]) {
                p1 = f(p1, v[j]);
            } else {
                p2 = f(p2, v[j]);
            }
        }
        ans = max(ans, len(p1.first, p1.second) + len(p2.first, p2.second));
    }
    return ans;
}

