      L2[i] = L2[i+1];
      R2[i] = R2[i+1];
    }
    chmax(L2[i], LR[i].first);
    chmin(R2[i], LR[i].second);
  }
  dump(L2);
  dump(R2);

  int res = M;
  rep(i, 0, n-1){
    int ans = max(R1[i]-L1[i]+1,0LL) + max(R2[i+1]-L2[i+1]+1, 0LL);
    dump(i, max(R1[i]-L1[i]+1,0LL), max(R2[i+1]-L2[i+1]+1, 0LL), ans);
    chmax(res, ans);
  }

  rep(i, 1, n-1){
    int ans = 0;
    ans += R[i]-L[i]+1;
    ans += max(R1[i-1]-L1[i-1]+1,0LL);
    ans += max(R2[i+1]-L2[i+1]+1,0LL);
    chmax(res, ans);
  }

  cout << res << endl;

  return 0;
}

