int main() {
    lint n;
    cin >> n;

    vector<P> lr(n);
    for(auto& elem : lr) cin >> elem.first >> elem.second;

    P rmin = {1e18, 1e18};
    for(auto& elem : lr) {
        if(elem.second < rmin.second) rmin = elem;
    }
    auto it = find(lr.begin(), lr.end(), rmin);
    lr.erase(it);
    n = lr.size();

    sort(lr.begin(), lr.end());

    vector<P> dp1(n+1, {-1e18, 1e18}), dp2(n+1, {-1e18, 1e18});
    dp1[0] = rmin;
    for(lint i=0; i<n; i++) {
        chmax(dp1[i+1].first, dp1[i].first);
        chmin(dp1[i+1].second, dp1[i].second);

        chmax(dp1[i+1].first, lr[i].first);
        chmin(dp1[i+1].second, lr[i].second);
    }

    dp2[0] = {-1e18, 1e18};
    for(lint i=0; i<n; i++) {
        chmax(dp2[i+1].first, dp2[i].first);
        chmin(dp2[i+1].second, dp2[i].second);

        chmax(dp2[i+1].first, lr[n-i-1].first);
        chmin(dp2[i+1].second, lr[n-i-1].second);
    }

    lint ans = -1e18;

    // [0, i) と [i, n) で分割する場合
    for(lint i=0; i<n; i++) {
        lint s1 = max(-1LL, dp1[i].second - dp1[i].first);
        lint s2 = max(-1LL, dp2[n-i].second - dp2[n-i].first);
        chmax(ans, s1+s2+2);
    }

    // i番目を除く場合
    for(lint i=0; i<n; i++) {
        auto left = dp1[i];
        auto right = dp2[n-i-1];
        lint l = max(left.first, right.first);
        lint r = min(left.second, right.second);
        lint s1 = max(-1LL, r-l);
        lint s2 = max(-1LL, lr[i].second - lr[i].first);
        chmax(ans, s1+s2+2);
    }

    cout << ans << endl;
}

