    if(st.empty()){
        printf("%lld\n",max(0LL,s_r-s_l+1)+max(0LL,last_r-last_l+1));
        return 0;
    }
    vector<int> nw;
    rep(i,0,n)if(!ban[i])nw.push_back(l[i]);
    swap(nw,l); nw.clear();
    rep(i,0,n)if(!ban[i])nw.push_back(r[i]);
    swap(nw,r);
    int rmin=inf,idx=0,lmax=0,idx2=0;
    rep(i,0,n)if(chmin(rmin,r[i]))idx=i;
    rep(i,0,n)if(chmax(lmax,l[i]))idx2=i;
    int sub=inf;
    if(idx==idx2){
        rep(i,0,n)if(i!=idx)chmin(sub,max(0,r[i]-l[i]+1));
    }
    vector<P> rem; 
    int l_0=l[idx],r_0=r[idx2];
    rep(i,0,n){
        if(l_0<=l[i]&&r[i]<=r_0&&i!=idx&&i!=idx2)rem.push_back({l[i],r[i]});
    }
    if(rem.empty()){
        cerr<<rmin<<lmax<<l_0<<r_0<<endl;
        printf("%d\n",max(0,r_0-lmax+1)+max(0,rmin-l_0+1));
        return 0;
    }
    sort(ALL(rem),cmp);
    SegmentTree<int> maxx(n,
    [](int a,int b){return max(a,b);},[](int a,int b){return b;},0);
    rep(i,0,rem.size())maxx.update(i,rem[i].first);
    int ans=0;
    rep(i,0,rem.size()+1){
        int lmax2=l_0,rmin2=r_0;
        if(i==0){
            rmin2=rem[0].second;
        }
        else if(i==rem.size()){
            lmax2=maxx.query(0,rem.size());
        }
        else{
            lmax2=maxx.query(0,i); rmin2=rem[i].second;
        }
        chmax(ans,max(0,rmin2-lmax+1)+max(0,rmin-lmax2+1));
    }
    printf("%d\n",ans);
    return 0;
}

