    else return x / y + 1;
}

long long extGCD(long long a, long long b, long long &x, long long &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    long long d = extGCD(b, a % b, y, x);
    y -= a / b * x;
    return d;
}

bool cmp(pair<int, int> a, pair<int, int> b) {
    if (a.second == b.second) return a.first < b.first;
    return a.second < b.second;
}

void solve() {
    int n; cin >> n;
    vector<pair<int, int>> lr(n); rep (i, n) cin >> lr[i].first >> lr[i].second;
    sort(all(lr), cmp);

    vector<pair<int, int>> day1(n - 1), day2(n - 1);
    day1[0] = lr[0];
    FOR (i, 1, n - 1) {
        day1[i].first = lr[i].first;
        day1[i].second = min(lr[i].second, day1[i - 1].second);
    }
    day2[n - 2] = lr[n - 1];
    for (int i = n - 3; i >= 0; i--) {
        day2[i].first = day2[i + 1].first;
        day2[i].second = min(lr[i + 1].second, day2[i + 1].second);
    }

    int ans = 0;

    rep (i, n - 1) {
        int one = max(0ll, day1[i].second - day1[i].first + 1);
        int two = max(0ll, day2[i].second - day2[i].first + 1);
        chmax(ans, one + two);
    }

    FOR (i, 1, n - 2) {
        int L = day2[i].first;
        int R = min(day1[i - 1].second, day2[i].second);
        chmax(ans, max(0ll, R - L + 1) + max(0ll, lr[i].second - lr[i].first + 1));
    }

    cout << ans << endl;
    return;
}

signed main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    solve();
}

