int main() {
  int N; cin >> N;
  priority_queue<P, vector<P>, greater<P> > que;
  ll maxlr = 0LL;
  rep(i, N) {
    int l, r; cin >> l >> r;
    que.push(P(l, r));
    maxlr = max(maxlr, (ll)(l-r+1));
  }

  vector<vector<P> > x(2);
  P tmp = que.top(); que.pop();
  int maxr = tmp.second;
  int cnt = 0;
  x[cnt].push_back(tmp);

  while (!que.empty()) {
    P p = que.top(); que.pop();
    if (p.first > maxr) {
      cnt++;
      maxr = p.second;
    } else {
      maxr = max(maxr, p.second);
    }

    if (cnt >= 2) break;

    x[cnt].push_back(p);
  }


  ll ans = 0LL;
  if (cnt == 2) {
    ans = maxlr;
  } else if (cnt == 1) {
    ans = max(maxlr, get_sum(x[0])+get_sum(x[1]));
