      fromR[i] = max(0, (minr-maxl+1));
    }
    ll ans_cand = 0LL;
    rep(i, N-1) ans_cand = max(ans_cand, (ll)(fromL[i]+fromR[i+1]));

    ans = ans_cand;

  }

  cout << ans << endl;


  return 0;
}

