bool compareLR(struct LR a, struct LR b)
{
	if (a.l < b.l)
		return true;
	else if (a.l > b.l)
		return false;
	else
	{
		if (a.r <= b.r)
			return true;
		else
			return false;
	}
}

bool compareLR_R(struct LR a, struct LR b)
{
	if (a.l < b.l)
		return false;
	else if (a.l > b.l)
		return true;
	else
	{
		if (a.r <= b.r)
			return false;
		else
			return true;
	}
}



long long Caculate(struct LR a, struct LR b)
{
	long long maxL = 0;
	long long minR = 1999999999;

	maxL = a.l >= b.l ? a.l : b.l;
	minR = a.r <= b.r ? a.r : b.r;

	long long result = minR - maxL + 1;
	result = result < 0 ? 0 : result;

	return result;

}

bool compareLR_S(struct LR a, struct LR b)
{
	long long tmpA = Caculate(a, a);
	long long tmpB = Caculate(b, b);

	if (tmpA < tmpB)
		return true;
	else
		return false;
}

