		tan = std::min(tan, y);

		if(!(kiri < tan)) break;

		while(qu.size() > 1 and (qu.top().second != i and qu.top().first <= kiri)) {
	//		cout << i << " " << qu.top().first << endl;
			qu.pop();
		}
		int r = Y[i + 1].first, l = qu.top().first;
		if(!(l < r)) continue;

