void solve() {
	int n;
	cin >> n;
	vector<pair<int, int>> a(n), inter(n);
	int ans = 0;
	for (int i = 0; i < n; i++)
	{
		cin >> a[i].first >> a[i].second;
		ans = max(ans, a[i].second - a[i].first + 1);
	}
	for (int qwe = 0; qwe < 2; qwe++)
	{
		sort(all(a));
		inter[n - 1] = a[n - 1];
		for (int i = n - 2; i >= 0; i--)
		{
			inter[i].first = max(inter[i + 1].first, a[i].first);
			inter[i].second = min(inter[i + 1].second, a[i].second);
		}
		int le = a[0].first, ri = a[0].second;
		for (int i = 0; i + 1 < n; i++)
		{
			le = max(le, a[i].first);
			ri = min(ri, a[i].second);
			ans = max(ans, max(0, ri - le + 1) + max(0, inter[i + 1].second - inter[i + 1].first + 1));
		}
		for (int i = 0; i < n; i++)
		{
			a[i].first *= -1;
			a[i].second *= -1;
			swap(a[i].first, a[i].second);
		}
	}
	cout << ans << endl;
}


