LL len(const PII& p) {
	return max(0ll, p.R - p.L + 1);
}
PII merge(const PII& a, const PII& b) {
	return make_pair(max(a.L, b.L), min(a.R, b.R));
}

const LL MAX = 1e9;
void brute(vector<PII> range, LL ans) {
	LL best = 0;
	int n = range.size();
	for (int mask = 1; mask < (1 << n) - 1; mask++) {
		PII lt(1, MAX), rt(1, MAX);
		for (int i = 0; i < n; i++) {
			if (mask & (1 << i)) {
				lt = merge(lt, range[i]);
			} else {
				rt = merge(rt, range[i]);
			}
		}
		best = max(best, len(lt) + len(rt));
	}
	if (best != ans) {
		trace(best, ans);
		assert(false);
	}
}

