void getP2X()
{
    p2x[1] = 0;
    for(int i = 2; i <= MAX_N * 2; i ++)
        p2x[i] = p2x[i >> 1] + 1;
}

int z;

void getRmq()
{
    for(int i = 1; i <= z; i ++)
    inte[0][i] = {org[v[i].i].x, org[v[i].i].y};

    for(int j = 1; (1 << j) <= z; j ++)
    {
        int p = (1 << j);
        int p2 = (p >> 1);
        for(int i = 1; i + p - 1 <= z; i ++)
        {
            //cout << "FACEM " << j << " " << i << "\n";
            getInter(inte[j][i], inte[j - 1][i], inte[j - 1][i + p2]);
        }
    }
}

coord getMax(int st, int dr)
{
    if(st > dr)
        return {0, 0};

    int len = dr - st + 1;
    int p2 = p2x[len];
    int diff = len - (1 << p2);

    coord a;
    getInter(a, inte[p2][st], inte[p2][st + diff]);

    return {a.x, a.y};
}

bool pos(int len)
{
    int cr = 0;
    int dr = 1;
    for(int i = 1; i <= z; i ++)
    {
        while(dr <= z && v[dr].p <= v[i].p + len - 1)
            dr ++;

        if(org[v[i].i].y - org[v[i].i].x + 1 >= len)
        if(v[dr - 1].p >= v[i].p + len - 1)
        {
            int l = 0;
            if(i + 1 <= dr - 1)
            {
                //cout << i << " " << dr << "  PENTR " << len << "\n";
                //cout << "AVEM " << v[i + 1].p << " " << " LA " << v[dr - 1].p <<"\n";

                coord a = getMax(1, i - 1);
                coord rez = getMax(i + 1, dr - 1);
                coord c = getMax(dr + 1, z);

                if(i - 1 >= 1)
                    getInter(rez, rez, a);

                if(dr + 1 <= z)
                    getInter(rez, rez, c);

                l = len + rez.y - rez.x + 1;

               // cout << " DA " << l << "\n";
            }

            cr = max(cr, l);
        }
    }


    rez = max(rez, cr);
    return (cr >= len);
}

