signed main() {
	INIT;

	VAR(int, n);
	VEC_ROW(int, n, L, R);

	int ans = 0;
	{ // 片方のコンテストを最長1つのみにする
		std::priority_queue<PAIR> mL;
		std::priority_queue<PAIR, V<PAIR>, std::greater<PAIR>> mR;

		REP(i, n) {
			mL.emplace(L[i], i);
			mR.emplace(R[i], i);
		}
		REP(i, n) {
			auto pL = mL.top();
			if (pL.second == i) {
				mL.pop();
				pL = mL.top();
			}
			auto pR = mR.top();
			if (pR.second == i) {
				mR.pop();
				pR = mR.top();
			}

			CHMAX(ans, R[i] - L[i] + 1 + std::max(0ll, pR.first - pL.first + 1));

			if (mL.size() < n) mL.emplace(L[i], i);
			if (mR.size() < n) mR.emplace(R[i], i);
		}
	}
	if (n <= 2) {
		OUT(ans)BR;
		return 0;
	}

	int L1, R1, L2, R2;
	{
		PAIR mi(INFINT, INFINT);
		int mii = -1;
		REP(i, n) {
			if (mi > PAIR(R[i], L[i])) {
				mi = PAIR(R[i], L[i]);
				mii = i;
			}
		}
		L1 = L[mii];
		R1 = R[mii];
		std::swap(L[mii], L[n - 1]); L.resize(n - 1);
		std::swap(R[mii], R[n - 1]); R.resize(n - 1);
		--n;
	}
	{
		PAIR ma(-INFINT, -INFINT);
		int mai = -1;
		REP(i, n) {
			if (ma < PAIR(L[i], R[i])) {
				ma = PAIR(L[i], R[i]);
				mai = i;
			}
		}
		L2 = L[mai];
		R2 = R[mai];
		std::swap(L[mai], L[n - 1]); L.resize(n - 1);
		std::swap(R[mai], R[n - 1]); R.resize(n - 1);
		--n;
	}

	V<int> o(n);
	std::iota(ALL(o), 0);
	std::sort(ALL(o), [&](int l, int r) {
		return PAIR(L[l], R[l]) > PAIR(L[r], R[r]);
		});

	std::priority_queue<int, V<int>, std::greater<int>> pq;
	pq.emplace(R2);
	CHMAX(ans, std::max(0ll, R1 - L[o[0]] + 1) + R2 - L2 + 1);
	int miL = L[o[0]];
	REP(i_, n) {
		int i = o[i_];

		pq.emplace(R[i]);
		if(i_ + 1 < n) CHMIN(miL, L[o[i_ + 1]]);
		CHMAX(miL, L1);
		CHMAX(ans, std::max(0ll, R1 - miL + 1) + std::max(0ll, pq.top() - L2 + 1));
	}
	OUT(ans)BR;

	return 0;
}

