    rep(i, n) seg.update(i, a[i].second);

    LL ans = 0;
    rep(i, n){
        chmax(ans, a[i].second-a[i].first+1);
    }
    rep1(i, n){
        // cout << seg.query(0,i) << ":"<< a[i-1].first << " " << seg.query(i,n) <<":"<<a[n-1].first << endl;
        chmax(ans, max(0LL, seg.query(0,i)-a[i-1].first+1)+max(0LL, seg.query(i,n)-a[n-1].first+1));
    }
    cout << ans << endl;


}

