        chmax(mi, vec[i].first);
        chmin(ma, vec[i].second);
        v2[i] = max(ma-mi+1, 0LL);
      }
      ll ans = 0;
      rep(i, n-1) {
        chmax(ans, v1[i]+v2[i+1]);
      }

      multiset<int, greater<>> left;
      multiset<int> right;
      rep(i, n) {
        left.insert(vec[i].first);
        right.insert(vec[i].second);
      }

      rep(i, n) {
        auto it = left.find(vec[i].first);
        left.erase(it);
        it = right.find(vec[i].second);
        right.erase(it);

        debug(*right.begin(), *left.begin());

        ll tmp = max(0, (*right.begin())-(*left.begin())+1);
        ll tmp2 = max(0LL, vec[i].second-vec[i].first+1);
        chmax(ans, tmp + tmp2);

        left.insert(vec[i].first);
        right.insert(vec[i].second);
      }

      cout << ans << endl;

    }
};

