int N;
typedef pair<ll, ll> pll;
vector<pll> lines;

int intersect(int l, int r, int newL, int newR) {
  assert(l<r);
  assert(newL < newR);

  if (r < newL || newR < l) return 0;

  if (l <= newL && newL <= r) {
    return min({r, newR}) - newL;
  }

  return min({r, newR}) - l;
}

pll intersect(pll c, pll newC) {
  if (c.first < 0) {
    return c;
  }

  assert(c.first<=c.second);
  assert(newC.first <= newC.second);

  if (c.second < newC.first || newC.second < c.first) {
    return make_pair(-1, -1);
  }

  if (c.first <= newC.first && newC.first <= c.second) {
    return make_pair(newC.first, min({c.second, newC.second}));
  }

  return make_pair(c.first, min({c.second, newC.second}));
}

ll len(pll p) {
  if (p.first < 0) {
    return 0;
  }
  return p.second - p.first + 1;
}

