            if(i==0){
                L[i] = X[i].r-X[i].l+1;
                l = X[i].l;
                r = X[i].r;
            }else if(L[i-1]!=0){
                L[i] = max(0LL,min(X[i].r,r)-max(X[i].l,l)+1);
                l = max(X[i].l,l);
                r = min(X[i].r,r);
                if(l>r){
                    l = -1; r = -1;
                }
            }else{
                L[i] = 0;
            }
            LQ[i] = {l,r};
        }
        l = 1e9,r = 1e9;
        for(int i=N-1;i>=0;i--){
            Rm[i] = max((i!=N-1? Rm[i+1]:0),X[i].r-X[i].l+1);
            if(i==N-1){
                R[i] = X[i].r-X[i].l+1;
