int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    rande.seed(chrono::steady_clock::now().time_since_epoch().count());

    int n;
    while (read(n)) {
        vec<iip> lr(n);
        forn(i, n) {
            read(lr[i].first, lr[i].second);
        }

        auto mp = max_element(lr.begin(), lr.end()) - lr.begin();

        vec<iip> ps;
        iip mx = lr[mp];
        forn(i, n) if (i != mp) {
            ps.emplace_back(lr[i].second, lr[i].first);
        }

        sort(ps.begin(), ps.end());
        logvp(ps);
        logss(mx.first, mx.second);
        // i64 ans = mx.second - mx.first + 1 + mxl;
        i64 ans = 0;
        iip c2{0, INF};
        forn(i, ps.size()) {
            iip pp = mx;
            uin(pp.second, ps[i].first);
            i64 cans = max(0, pp.second - pp.first + 1);
            if (c2.first != 0) {
                cans += max(0, c2.second - c2.first + 1);
            } else {
                if (mx.second <= ps[i].first) {
                    int mxl = 0;
                    forn(i, ps.size()) {
                        uax(mxl, ps[i].first - ps[i].second + 1);
                    }
                    cans += mxl;
                } else {
                    int mxl = 0;
                    forr(i, 1, ps.size()) {
                        uax(mxl, ps[i].first - ps[i].second + 1);
                    }
                    cans += mxl;
                }
            }
            uax(ans, cans);
            uin(c2.second, ps[i].first);
            uax(c2.first, ps[i].second);
        }

        i64 cans = mx.second - mx.first + 1;
        if (c2.first != 0) {
            cans += max(0, c2.second - c2.first + 1);
        }

        uax(ans, cans);
        cout << ans << endl;
    }
}

