    sort(v, v + n, [](pii a, pii b) {
            return ((a.second - a.first) < (b.second - b.first));
         });
    int ans(baga());
    reverse(v, v + n);
    ans = max(ans, baga());
    sort(v, v + n, [](pii a, pii b) {
            return a.first < b.first;
         });
    ans = max(ans, baga());
    while ((double)(clock() - Stime) / CLOCKS_PER_SEC < 1.9) {
        random_shuffle(v, v + n);
        ans = max(ans, baga());
    }
    cout << ans;
    return 0;
}

