	for (auto& seg : segs) {
		cin >> seg.start >> seg.last;
	}
	vector<Seg> segs2 = segs;

	int ans = 0;
	{
		sort(segs.begin(), segs.end(), [](const auto & lhs, const auto & rhs) {
			if (lhs.start != rhs.start) return (lhs.start < rhs.start);
			return lhs.last < rhs.last;
		});

		vector<int> fh(n);
