		{
			Seg cs = segs[n - 1];
			FOR_DW(i, n - 1, 0) {
				cs.start = max(segs[i].start, cs.start);
				cs.last = min(segs[i].last, cs.last);
				fb[i] = max(0, cs.last - cs.start + 1);
			}
		}

		FOR_LT(i, 0, n - 1) {
			ans = max(ans, fh[i] + fb[i + 1]);
		}
	}

