    vector<pair<ll,ll>> v;
    ll one = 0;
    rep(i,n){
        ll l,r;
        cin >> l >> r;
        v.push_back(P(l,r));
    }
    sort(v.begin(),v.end());

    rep(i,n){
        if(i+1<n && i>0){
            ll re=v[0].se-v[i+1].fi+1;
            if(re<0) re=0;
            one = max(one,v[i].se-v[i].fi+1+re);
        }
