    rep(i,n){
        ll res = 0;
        if(v[i].fi<=last){
            res += last-v[i].fi+1;
        }
        if(i+1<n) res+=b[i+1];
        ans=max(ans,res);
    }
    cout << max(ans,one) << endl;
}

