		int beforeA = max(0, (*aright.begin()) - (*aleft.rbegin()) + 1);
		int beforeB = max(0, (*bright.begin()) - (*bleft.rbegin()) + 1);

		aleft.insert(vleft[i]);
		aright.insert(vright[i]);
		bleft.erase(bleft.find(vleft[i]));
		bright.erase(bright.find(vright[i]));

		int afterA = max(0, (*aright.begin()) - (*aleft.rbegin()) + 1);
		int afterB = max(0, (*bright.begin()) - (*bleft.rbegin()) + 1);

		if(beforeA - afterA < afterB - beforeB) {
			inA[i] = 1;
			continue;
		}

		bleft.insert(vleft[i]);
		bright.insert(vright[i]);
		aleft.erase(aleft.find(vleft[i]));
		aright.erase(aright.find(vright[i]));
	}

	int A = max(0, (*aright.begin()) - (*aleft.rbegin()) + 1);
	int B = max(0, (*bright.begin()) - (*bleft.rbegin()) + 1);

	cout << A + B << endl;
	return 0;
}

