struct data {
	llong L;
	llong R;

	data() = default;
	data(llong L, llong R) :
		L(L),
		R(R)
	{}

	bool operator<(const data &ri) const {
		// return R - L < ri.R - ri.L;
		return R == ri.R ?
			L < ri.L :
			R < ri.R;
	}
};

llong N;
vector<data> tasks;

llong score(llong mid) {
	data d1(-inf, inf), d2(-inf, inf);

	for (auto &task: tasks) {
		if (task.R < mid) {
			d1.L = max(d1.L, task.L);
			d1.R = min(d1.R, task.R);
		} else {
			d2.L = max(d2.L, task.L);
			d2.R = min(d2.R, task.R);
		}
	}

	if (d1.R == inf || d2.R == inf) return -1;
	return max(0ll, d1.R - d1.L + 1) + max(0ll, d2.R - d2.L + 1);
}

