  ll Lmx = 0, Rmn = LINF;
  rep(i, N) {
    chmax(Lmx, LR[i].fi);
    chmin(Rmn, LR[i].se);
    mxL[i] = Lmx;
    mnL[i] = Rmn;
    numL[i] = max(0LL, Rmn - Lmx);
  }

  vector<ll> numR(N), mxR(N), mnR(N);
