    mxR[i] = Lmx;
    mnR[i] = Rmn;
    numR[i] = max(0LL, Rmn - Lmx);
  }

  rep(i, N - 1) {
    ll temp = numL[i] + numR[i + 1];
    chmax(ans, temp);
  }

  rep(i, N) {
    ll temp = LR[i].se - LR[i].fi;
    if (i == 0) {
      temp += numR[1];
