      temp += numL[N - 2];
    } else {
      temp +=
          max(0LL, min(mnL[i - 1], mnR[i - 1]) - max(mxR[i + 1], mxL[i + 1]));
    }
    chmax(ans, temp);
  }

  cout << ans << endl;
}

