#define rirep(i, n) for (int64_t i = n; i >= 0; i--)

using P = tuple<int, int>;
bool cmp(const P& lh, const P& rh)
{
    int lhl, lhr, rhl, rhr;
    tie(lhl, lhr) = lh;
    tie(rhl, rhr) = rh;

    if (lhr < rhr) {
        return true;
    } else if (lhr > rhr) {
        return false;
    } else {
        return lhl < rhl;
    }
}

int main()
{
    int n;
    cin >> n;

    vector<P> p;
    int lm = 0, rm;
    rep(i, n)
    {
        int l, r;
        cin >> l >> r;
        p.push_back(P(l, r));

        if (lm < l) {
            lm = l;
            rm = r;
        }
    }
    p.erase(find(p.begin(), p.end(), P(lm, rm)));
    sort(p.begin(), p.end(), cmp);

    n = p.size();
    vector<P> q(n + 1), q2(n + 1);
    irep(i, n)
    {
        if (i == 0) {
            q[i] = P(1, 1e9);
            q2[n - i] = P(1, 1e9);
        } else {
            int lprev, rprev;
            tie(lprev, rprev) = q[i - 1];
            int lp, rp;
            tie(lp, rp) = p[i - 1];

            //cout << "(" << lprev << ", " << rprev << ") (" << lp << ", " << rp << ")" << endl;
            q[i] = P(max(lp, lprev), min(rp, rprev));

            int lprev2, rprev2;
            tie(lprev2, rprev2) = q2[n - (i - 1)];
            int lp2, rp2;
            tie(lp2, rp2) = p[n - 1 - (i - 1)];

            q2[n - i] = P(max(lp2, lprev2), min(rp2, rprev2));
        }
    }

    irep(i, n)
    {
        int l, r;
        tie(l, r) = q2[i];
        //cout << "l=" << l << " r=" << r << endl;
    }

    int result = 0;
    rep(i, n)
    {
        int l1, r1;
        tie(l1, r1) = q[n - i];
        int l2, r2;
        tie(l2, r2) = q2[n - i];
        int l0 = max(l2, lm), r0 = min(r2, rm);

        int score1 = max(r1 - l1 + 1, 0);
        int score2 = max(r0 - l0 + 1, 0);

        //cout << "i=" << i << " score=" << score1 + score2 << "\t" << l0 << " " << r0 << endl;

        result = max(result, score1 + score2);
    }

    rep(i, n)
    {
        int l1, r1;
        tie(l1, r1) = q[i];
        int l2, r2;
        tie(l2, r2) = q2[i + 1];
        int l3, r3;
        tie(l3, r3) = p[i];

        int l0 = max(lm, max(l1, l2)), r0 = min(rm, min(r1, r2));
        int score1 = max(0, r0 - l0 + 1);
        int score2 = max(0, r3 - l3 + 1);

        result = max(result, score1 + score2);
    }

    cout << result << endl;
    return 0;
}

