int main()
{
    int n; cin >> n;
    vector<LL> L(n), R(n);
    for (int i = 0; i < n; ++i) {
        cin >> L[i] >> R[i];
    }

    vector<int> ord(n);
    iota(ord.begin(), ord.end(), 0);

    sort(ord.begin(), ord.end(), [&](int i, int j) {
            return L[i] < L[j];
            });

    vector<LL> Lmaxl(n+1), Lmaxr(n+1), Rminl(n+1), Rminr(n+1);
    Lmaxl[0] = Lmaxr[n] = 0;
    Rminl[0] = Rminr[n] = 1e9+1;
    for (int i = 0; i < n; ++i) {
        Lmaxl[i+1] = max(Lmaxl[i], L[i]);
        Rminl[i+1] = min(Rminl[i], R[i]);
    }
    for (int i = n-1; i >= 0; --i) {
        Lmaxr[i] = max(Lmaxr[i+1], L[i]);
        Rminr[i] = min(Rminr[i+1], R[i]);
    }

    LL ans = 0;
    for (int i = 0; i < n; ++i) {
        LL lmax = max(Lmaxl[i], Lmaxr[i+1]);
        LL rmin = min(Rminl[i], Rminr[i+1]);
        chmax(ans, R[i] - L[i] + 1 + max(rmin - lmax + 1, 0LL));
    }

    vector<int> idx;
    int prev = -1;
    for (int i = 0; i < n; ++i) {
        int id = ord[i];
        if (prev < R[id]) {
            idx.push_back(id);
        }
        prev = R[id];
    }

    int m = idx.size();
    for (int i = 0; i+1 < m; ++i) {
        chmax(ans, (R[idx[0]] - L[idx[i]] + 1) +
                   (R[idx[i+1]] - L[idx[m-1]] + 1));
    }

    cout << ans << endl;

    return 0;
}

