	}
	ll ans = 0;
	{
		SORT(v);

		auto tree = SegmentTree<PAIR>(n);
		REP(i, n) {
			tree.add(i, v[i]);
		}

		REP(i, n - 1) {
			auto q1 = tree.query(0LL, i);;
			ll r1 = q1.second - q1.first + 1;
			if (r1 > 1e9) { r1 = 0; }MAX(r1, 0LL);

			auto q2 = tree.query(i + 1, n);
			ll r2 = q2.second - q2.first + 1;
			if (r2 > 1e9) { r2 = 0; }MAX(r2, 0LL);
			MAX(ans, r1 + r2);
