void flex(){
	int MxL = 0 , MnR = 2e9 , lim = n;
	for(int i = n; i >= 1 ; i--){
		MxL = max(p[i].fi , MxL);
		MnR = min(p[i].se , MnR);
		if(MxL > MnR)
			break;
		lim = i;
		sf[i] = max(MnR - MxL + 1 , 0ll);
	}
	int MinR = 2e9 , MaxL = 0;

	for(int i = 1; i <= n; i++){
		MinR = min(MinR , p[i].se);
		MaxL = max(MaxL , p[i].fi);
		int cur = MinR - MaxL + 1;
		if(cur <= 0)break;
		cur += sf[i + 1];
		ans = max(ans , cur);
	}
	for(int i = n; i >= lim ; i--)
		sf[i] = 0;
}
