void plex(){
	int MxL = 0 , MnR = 2e9 , lim = n;
	for(int i = n; i >= 1 ; i--){
		MxL = max(p[v[i - 1]].fi , MxL);
		MnR = min(p[v[i - 1]].se , MnR);
		if(MxL > MnR)
			break;
		lim = i;
		sf[i] = max(MnR - MxL + 1 , 0ll);
	}
	int MinR = 2e9 , MaxL = 0;
	for(int i = 1; i <= n; i++){
		MinR = min(MinR , p[v[i - 1]].se);
		MaxL = max(MaxL , p[v[i - 1]].fi);
