}	
void rev(){
	for(int i = 1 ; i <= n; i++){
		p[i].fi = 1e9 - p[i].fi + 1;
		p[i].se = 1e9 - p[i].se + 1;
		swap(p[i].fi,p[i].se);
	}
}
bool cmp1(pii a , pii b){
	if(a.fi < b.fi)
		return true;
	if(a.fi == b.fi and a.se > b.se)
		return true;
	return false;
}
bool cmp2(pii a , pii b){
	if(a.se < b.se)
		return true;
	if(a.se == b.se)
		return a.fi < b.fi;
	return false;
}
bool cmp3(pii a , pii b){
	if(a.se > b.se)
		return true;
	if(a.se == b.se)
		return a.fi < b.fi;
	return false;
}
