int solve(const int& n,const vector<pi>& prob){
  vector<pi> mei(n,prob[0]),med(n,prob[n-1]);
  for(int i=1;i<n-1;++i){
    mei[i].l=max(prob[i].l,mei[i-1].l);
    mei[i].r=min(prob[i].r,mei[i-1].r);
  }
  for(int i=n-2;i>0;--i){
    med[i].l=max(prob[i].l,med[i+1].l);
    med[i].r=min(prob[i].r,med[i+1].r);
  }
  int res=0;
  for(int i=0;i<n-1;++i){
    res=max(res,diff(mei[i])+diff(med[i+1]));
  }
  return res;
}
