void flex(){
	int MxL = 0 , MnR = 2e9;
	for(int i = n; i >= 1 ; i--){
		MxL = max(p[i].fi , MxL);
		MnR = min(p[i].se , MnR);
		sf[i] = max(MnR - MxL + 1 , 0ll);
