        ret = imax(ret, R[i] - L[i] + 1);
    }
    if (Lmax <= Rmin) {
        ret += Rmin - Lmax + 1;
    }

    std::sort(vec.begin(), vec.end(), [&](Closed_Section& a, Closed_Section& b){
        return a.begin < b.begin;
    });
    ret = imax(ret, calc(vec));

    std::cout << ret << std::endl;

    return 0;
}

