using namespace std;

struct Interval {
    int i, j;
    Interval(): i(0), j(1000000010) {}
    Interval(int i, int j): i(i), j(j) {}
    Interval operator&(const Interval& o) const {
        int new_i = max(i, o.i);
        int new_j = min(j, o.j);
        return Interval(new_i, new_j);
    }
    int size() {
        return max(0, j - i);
    }
    bool operator<(const Interval& o) const {
        return j < o.j;
    }
    friend istream& operator>>(istream& in, Interval& interval) {
        in >> interval.i >> interval.j;
        ++interval.j;
        return in;
    }
};

template <typename T>
struct AndHeap {
    int n;
    vector<T> heap;
    AndHeap(vector<T>& xs) {
        int orgN = (int) xs.size();
        n = 1;
        while (n < orgN) {
            n *= 2;
        }
        heap = vector<T>(2*n-1);
        for (int i = 0; i < orgN; ++i) {
            heap[n-1+i] = xs[i];
        }
        for (int i = n-2; i >= 0; --i) {
            heap[i] = xs[2*i+1] & xs[2*i+2];
        }
    }
    T _partial_and(int pos, int left, int right, int from, int to) {
        // assert ((Interval(left, right) & Interval(from, to)).size() > 0);
        left = max(left, from);
        right = min(right, to);
        if (left >= right) {
            return T();
        }
        if (pos >= n-1) {
            return heap[pos];
        }
        assert( (from-to) % 2 == 0);
        T left_t = _partial_and(2*pos+1, left, right, from, (from + to)/2);
        T right_t = _partial_and(2*pos+2, left, right, (from + to)/2, to);
        return left_t & right_t;
    }
    T partial_and(int from, int to) {
        return _partial_and(0, from, to, 0, n);
        // Interval interval;
        // for (int i = from; i < to; ++i) {
            // interval = interval & heap[n-1 + i];
        // }
        // return interval;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n;
    cin >> n;
    vector<Interval> intervals(n);
    for (auto& interval : intervals) {
        cin >> interval;
    }
    sort(intervals.begin(), intervals.end());
    AndHeap<Interval> fast_and(intervals);
    int best = 0;

    // all but one:
    for (int i = 0; i < n; ++i) {
        auto left = fast_and.partial_and(0, i);
        auto right = fast_and.partial_and(i+1, n);
        int total_size = (left & right).size() + intervals[i].size();
        best = max(best, total_size);
    }

    // first i
    for (int i = 1; i < n; ++i) {
        auto left = fast_and.partial_and(0, i);
        auto right = fast_and.partial_and(i, n);
        int total_size = left.size() + right.size();
        best = max(best, total_size);
    }

    cout << best << endl;

    return 0;
}

