ll fast_pow(ll a, ll b){
    ll ans = 1;
    a %= mod;
    while(b){
        if(b&1) ans = (ans * a) % mod;
        a = (a * a) % mod;
        b /= 2;
    }
    return ans;
}

vector<pii> v;
int mx;

int check(int cnt){
    int l1 = v[0].F, r1 = v[0].S, l2 = -1, r2 = 1e9+7;
    for(int j = 1; j < (int)v.size(); j++){
        if(cnt == 0 && j == mx){
            l2 = v[j].F, r2 = v[j].S;
            continue;
        }
        int l_ = max(l1, v[j].F), r_ = min(r1, v[j].S);
        int new_cnt = r_ - l_ + 1;
        if(new_cnt >= cnt) l1 = l_, r1 = r_;
        else l2 = max(l2, v[j].F), r2 = min(r2, v[j].S);
    }
    return (max(0, r1-l1+1) + max(0, r2-l2+1));
}

int foo(int l, int r){
    if(l == r) return check(l);
    int m = (l+r) >> 1;
    int x1 = check(m), x2 = check(m+1);
    if(x1 <= x2) return foo(m+1, r);
    return foo(l, m);
}

