signed main()
{
  IOS; /* making cin faster */
  const int M = 1e9;
  int N;
  SCAND(N);
  vector<pair<lli,lli> > P(N);
  REP(i,N)
    {
      SCANLLD2(P[i].first,P[i].second);
    }
  sort(ALL(P),[](pair<lli,lli> a, pair<lli,lli> b)
       {
	 return a.second - a.first < b.second - b.first;
       });

  vector<lli> numl(N);
  lli rl = 1;
  lli rr = M;

  REP(i,N)
    {
      rl = max(rl,P[i].first);
      rr = min(rr,P[i].second);

      numl[i] = max(rr-rl+1,0LL);
    }

  vector<lli> numr(N);
  rl = 1;
  rr = M;

  REP_R(i,N)
    {
      rl = max(rl,P[i].first);
      rr = min(rr,P[i].second);

      numr[i] = max(rr-rl+1,0LL);
    }

  lli ans = 0;
  REP(i,N-1)
    {
      ans = max(ans,numl[i]+numr[i+1]);
    }

  vector<pair<lli,lli> > psl(N,make_pair(1,M));
  vector<pair<lli,lli> > psr(N,make_pair(1,M));

  FOR(i,1,N)
    {
      psl[i].first = max(psl[i-1].first,P[i-1].first);
      psl[i].second = min(psl[i-1].second,P[i-1].second);
    }

  REP_R(i,N-1)
    {
      psr[i].first = max(psr[i+1].first,P[i+1].first);
      psr[i].second = min(psr[i+1].second,P[i+1].second);
    }

  REP(i,N)
    {
      lli rrl = max(psl[i].first,psr[i].first);
      lli rrr = min(psl[i].second,psr[i].second);

      lli ad = max(0LL,rrr-rrl+1);
      ans = max(ans,P[i].second-P[i].first+1+ad);
    }
  PRINTLLD(ans);





}

