	int n;
	scanf("%d", &n);
	for (int i=0 ; i<n ; i++) {
		int x, y;
		scanf("%d%d", &x, &y);
		v.pb(mp(x,y));
	}
	int sol = -2;
	//pref c1
	sort(v.begin(), v.end());
	for (int i=n-1 ; i>=0 ; i--) {
		if (i == n-1) suff[i] = mp(v[i].x, v[i].y);
		else {
			suff[i].x = max(suff[i+1].x, v[i].x);
			suff[i].y = min(suff[i+1].y, v[i].y);
		}
	}
	int l=0, r=1e9;
	for (int i=0 ; i<n-1 ; i++) {
		l = max(l, v[i].x);
		r = min(r, v[i].y);
		int c1 = max(0, r-l+1);
		int c2 = max(0, suff[i+1].y - suff[i+1].x + 1);
		sol = max(sol, c1+c2);
	}
	//suff c2
	sort(v.begin(), v.end(), cmp);
	for (int i=0 ; i<n ; i++) {
		if (!i) pref[i] = mp(v[i].x, v[i].y);
		else {
			pref[i].x = max(pref[i-1].x, v[i].x);
			pref[i].y = min(pref[i-1].y, v[i].y);
		}
	}
	l=0, r=1e9;
	for (int i=n-1 ; i ; i--) {
		l = max(l, v[i].x);
		r = min(r, v[i].y);
		int c1 = max(0, r-l+1);
		int c2 = max(0, pref[i-1].y - pref[i-1].x + 1);
		sol = max(sol, c1+c2);
	}
	//best c1
	for (int i=0 ; i<v.size() ; i++) {
		sol = max(sol, v[i].y - v[i].x + 1);
	}

	printf("%d\n", sol);
	return 0;
}

