#include <algorithm>
#include <iostream>
#include <vector>
#define rep(i, n) for(long i = 0; i < (n); i++)

using namespace std;

void solve() {
  long N;
  cin >> N;
  vector<pair<long, long>> LR(N);
  vector<long> L;
  vector<long> R;

  rep (i, N) {
    long l, r;
    cin >> l >> r;
    LR[i] = make_pair(l, r);
    L.push_back(l);
    R.push_back(r);
  }

  // 1問とその他に分けるケースのカバー
  long one_and_others = 0;
  {
    sort(L.begin(), L.end());
    reverse(L.begin(), L.end());
    sort(R.begin(), R.end());
    for (auto it: LR) {
      long first_L = it.first;
      long first_R = it.second;
      long first_score = first_R - first_L + 1;
      long second_L = L[0];
      long second_R = R[0];
      if (second_L == first_L) second_L = L[1];
      if (second_R == first_R) second_R = R[1];
      long second_score = second_R - second_L + 1;
      if (second_score < 0) second_score = 0;
      one_and_others = max(one_and_others, first_score + second_score);
    }
  }

  // LRを昇順に並べ、どこかで前と後ろの2つに分ける
  sort(LR.begin(), LR.end());

  vector<long> minRmemo(N); // 先頭〜N番目までのRの最小値
  vector<long> minRmemoRev(N); // N番目〜末尾までのRの最小値
  minRmemo[0] = LR[0].second;
  for (long i = 1; i < N; i++) {
    minRmemo[i] = min(minRmemo[i-1], LR[i].second);
  }
  minRmemoRev[N-1] = LR[N-1].second;
  for (long i = N - 2; i >= 0; i--) {
    minRmemoRev[i] = min(minRmemoRev[i+1], LR[i].second);
  }

  long split_ans = 0;
  for (long i = 0; i < N - 1; i++) {
    long first_score = minRmemo[i] - LR[i].first + 1;
    if (first_score < 0) first_score = 0;

    long second_score = minRmemoRev[i+1] - LR[N-1].first + 1;
    if (second_score < 0) second_score = 0;

    split_ans = max(split_ans, first_score + second_score);
  }

  // 「1問+その他」パターンと、「昇順ちょんぎりパターン」のうち、大きい方を答えとする
  long ans = max(one_and_others, split_ans);
  cout << ans << endl;
}

int main(void) {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout.precision(12);
  solve();
  return 0;
}

