class Range {
public:
  int l, r;
  Range() {}
  Range(int l, int r) : l(l), r(r) {}
};

bool cmp(const Range &a, const Range &b)
{
  int l = a.r;
  int r = b.r;
  if (l == r) return a.l > b.l;
  return l < r;
}

vector<Range> ranges;

int ll[100010];
int lr[100010];
int rl[100010];
int rr[100010];

int common2(int i, int j) { 
  int l = max(ranges[i].l, ranges[j].l);
  int r = min(ranges[i].r, ranges[j].r);
  // cerr <<  i << " " << j << " " << l  << " " << r << endl;
  return max(r-l+1, 0);
}

int common(int i, int j, int ignore=-1) { 
  int r = -1;
  int l = -1;
  for (int k = i; k <= j; ++k) {
    if (k == ignore) continue;
    Range &range = ranges[k];
    if (r == -1 || r > range.r) {
      r = range.r;
    }
    if (l == -1 || l < range.l) {
      l = range.l;
    }
  }
  return r-l+1;
}

int main() {
  int n;
  cin >> n;
  for (int i = 0; i < n; ++i) {
    int l, r;
    cin >> l >> r;
    ranges.emplace_back(l, r);
  }
  sort(ranges.begin(), ranges.end(), cmp);
  int ans = 0;
  for (int i = 0; i < n; ++i) { 
    if (i == 0) {
      ll[i] = ranges[i].l;
      lr[i] = ranges[i].r;
    }
    else {
      ll[i] = max(ll[i-1], ranges[i].l);
      lr[i] = min(lr[i-1], ranges[i].r);
    }
  }
  for (int i = n-1; i >= 0; --i) { 
    if (i == n-1) {
      rl[i] = ranges[i].l;
      rr[i] = ranges[i].r;
    }
    else {
      rl[i] = max(rl[i+1], ranges[i].l);
      rr[i] = min(rr[i+1], ranges[i].r);
    }
  }
  for (int i = 0; i < n; ++i) { 
    if (i == 0) {
      // ans = max(ans, common2(0, 0)+common2(1, n-1));
      ans = max(ans, common2(0, 0)+common2(1, n-1));
    }
    else if (i == n-1) {
      ans = max(ans, common2(n-1, n-1)+common2(0, n-2));
    }
    else {
      ans = max(ans, common2(i, i)+common2(0, n-1));
    }
  }
  for (int i = 0; i < n-1; ++i) { 
    ans = max(ans, lr[i]-ll[i]+1+rr[i+1]-rl[i+1]+1);
  }
  // cerr << common2(0, 1) << " " << common2(2, 3) << endl;
  // for (Range &r: ranges) {
