const int max_N = 100000 + 1;

class max_seg_tree {
private:

    vector<ll> dat;
    int n;
public:
    max_seg_tree(int _n) : dat(2 * max_N - 1) {
        n = 1;
        while (n < _n) n *= 2;
    }
    int get_n() {
        return n;
    }
    void init_fill(ll v) {
        for (int i = 0; i < 2 * n - 1; i++) {
            dat[i] = v;
        }
    }
    void updata(int k, ll a) {
        k += n - 1;
        dat[k] = a;
        while (k > 0) {
            k = (k - 1) / 2;
            dat[k] = max(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }
    ll query(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l) return 0;
        if (a <= l && r <= b) return dat[k];
        else {
            ll vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
            ll vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
            return max(vl, vr);
        }
    }
};

class min_seg_tree {
private:

    vector<ll> dat;
    int n;
public:
    min_seg_tree(int _n) : dat(2 * max_N - 1) {
        n = 1;
        while (n < _n) n *= 2;
    }
    int get_n() {
        return n;
    }
    void init_fill(ll v) {
        for (int i = 0; i < 2 * n - 1; i++) {
            dat[i] = v;
        }
    }
    void updata(int k, ll a) {
        k += n - 1;
        dat[k] = a;
        while (k > 0) {
            k = (k - 1) / 2;
            dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }
    ll query(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l) return LINF;
        if (a <= l && r <= b) return dat[k];
        else {
            ll vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
            ll vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
            return min(vl, vr);
        }
    }
};
