vector<pair<int, int> > V;

bool comp(pair<int, int> p1, pair<int, int> p2)
{
    if(p1.second < p2.second) return true;
    else if(p1.second == p2.second){
        return p1.first > p2.first;
    }
    return false;
}

set<pair<int, int> > x;
set<pair<int, int> > y;

int l1, r1;

void dlt(int l, int r)
{
    x.erase(x.lower_bound(make_pair(l, -1)));
    y.erase(y.lower_bound(make_pair(r, -1)));
}

int query()
{
    //cout << x.size() << " " << y.size() << endl;
    set<pair<int, int> > ::iterator it1 = x.end();
    it1--;
    pair<int, int> p1 = *it1;
    set<pair<int, int> > ::iterator it2 = y.begin();
    pair<int, int> p2 = *it2;

    int l2 = p1.first, r2 = p2.first;
    int ans = 0;
    if(r1 >= l1) ans += (r1-l1+1);
    if(r2 >= l2) ans += (r2-l2+1);
    return ans;
}

