{
    int n;
    scanf("%d", &n);
    for(int i=0; i<n; i++){
        int l, r;
        scanf("%d %d", &l, &r);
        V.push_back(make_pair(l, r));
    }
    sort(V.begin(), V.end(), comp);
    int ans = 0;
    l1 = V[0].first, r1 = V[0].second;
    for(int i=1; i<V.size(); i++){
        int l = V[i].first, r = V[i].second;
        x.insert(make_pair(l, i));
        y.insert(make_pair(r, i));
        ans = max(ans, r-l+1);
    }
    ans = max(ans, query());
    for(int i=1; i<n-1; i++){
        int l = V[i].first, r = V[i].second;
        l1 = max(l1, l);
        r1 = min(r1, r);
        dlt(l, r);
        int cur = query();
        ans = max(ans, cur);
    }
    cout << ans;
}

