struct Segment_tree_min {
	using T = ll;

	ll n;
	vector<T> data;
	const T out = 1e9 + 5;

	inline T vmerge(T l, T r) { return min(l, r); }

	Segment_tree_min(ll n) :n(n) { data.assign(2 * n, out); }

	void update(ll p, T x) {  // set value at position p
		for (data[p += n] = x; p > 1; p >>= 1) {
			data[p >> 1] = vmerge(data[p], data[p ^ 1]);
		}
	}

	T query(ll l, ll r) {  // sum on llerval [l, r)
		T resl = out, resr = out;
		for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
			if (l & 1) resl = vmerge(data[l++], resl);
			if (r & 1) resr = vmerge(resr, data[--r]);
		}
		return vmerge(resl, resr);
	}
};

struct Segment_tree_max {
	using T = ll;

	ll n;
	vector<T> data;
	const T out = 0;

	inline T vmerge(T l, T r) { return max(l, r); }

	Segment_tree_max(ll n) :n(n) { data.assign(2 * n, out); }

	void update(ll p, T x) {  // set value at position p
		for (data[p += n] = x; p > 1; p >>= 1) {
			data[p >> 1] = vmerge(data[p], data[p ^ 1]);
		}
	}

	T query(ll l, ll r) {  // sum on llerval [l, r)
		T resl = out, resr = out;
		for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
			if (l & 1) resl = vmerge(data[l++], resl);
			if (r & 1) resr = vmerge(resr, data[--r]);
		}
		return vmerge(resl, resr);
	}
};


