    for(int i = n; i; i--){
        mn = min(mn, a[i].se);
        suf[i] = max(0, mn - tmp + 1);
    }
    int res = 0;
    for(int i = 0; i <= n; i++){
        res = max(res, pre[i] + suf[i + 1]);
    }
    cout << res << '\n';
    return 0;
}

