int process(vector<pair<int, int> > v) {
	int n = v.size();
	int ans = 0;
	vector<pair<int, int> > pref(n+1), suff(n+1);
	pref[0] = {-1e9, 1e9};
	for (int i=0;i<n;++i){
		pref[i+1] = {max(pref[i].first, v[i].first), min(pref[i].second, v[i].second)};
	}
	suff[n] = {-1e9, 1e9};
	for (int i=n-1; i >= 0; i--){
		pref[i] = {max(pref[i+1].first, v[i].first), min(pref[i+1].second, v[i].second)};
	}

	for (int i=0;i<n;++i){
		int L = max(pref[i].first, suff[i+1].first);
		int R = min(pref[i].second, suff[i+1].second);
		ans = max(ans, max(R-L+1, 0) + v[i].second-v[i].first + 1);
	}

	return ans;

}

