struct Segment_tree_min {
	using T = ll;

	ll n;
	vector<T> data;
	const T out = 1e9 + 5;

	inline T vmerge(T l, T r) { return min(l, r); }

	Segment_tree_min(ll n) :n(n) { data.assign(2 * n, out); }

	void update(ll p, T x) {  // set value at position p
		for (data[p += n] = x; p > 1; p >>= 1) {
			data[p >> 1] = vmerge(data[p], data[p ^ 1]);
		}
	}

	T query(ll l, ll r) {  // sum on llerval [l, r)
		T resl = out, resr = out;
		for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
			if (l & 1) resl = vmerge(data[l++], resl);
			if (r & 1) resr = vmerge(resr, data[--r]);
		}
		return vmerge(resl, resr);
	}
};

struct Segment_tree_max {
	using T = ll;

	ll n;
	vector<T> data;
	const T out = 0;

	inline T vmerge(T l, T r) { return max(l, r); }

	Segment_tree_max(ll n) :n(n) { data.assign(2 * n, out); }

	void update(ll p, T x) {  // set value at position p
		for (data[p += n] = x; p > 1; p >>= 1) {
			data[p >> 1] = vmerge(data[p], data[p ^ 1]);
		}
	}

	T query(ll l, ll r) {  // sum on llerval [l, r)
		T resl = out, resr = out;
		for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
			if (l & 1) resl = vmerge(data[l++], resl);
			if (r & 1) resr = vmerge(resr, data[--r]);
		}
		return vmerge(resl, resr);
	}
};


int main() {

	ll n;
	cin >> n;
	VP v(n);
	REP(i, n) {
		ll a, b;
		cin >> a >> b;
		v[i] = { b,a };
	}
	sort(ALL(v));

	Segment_tree_min rmq1(n), rmq2(n);
	Segment_tree_max rmq3(n), rmq4(n);

	REP(i, n) {
		rmq1.update(i, v[i].first);
		rmq3.update(i, v[i].second);
	}

	ll ans = 0;

	REP(i, n) {
		ll cnt = v[i].first - v[i].second + 1;
		rmq1.update(i, INF);
		rmq3.update(i, 0);
		ll a = rmq1.query(0, n) - rmq3.query(0, n) + 1;
		a = max(0LL, a);
		ans = max(ans, a + cnt);
		rmq1.update(i, v[i].first);
		rmq3.update(i, v[i].second);
	}
	REP(i, n - 1) {
		rmq1.update(i, INF);
		rmq3.update(i, 0);
		rmq2.update(i, v[i].first);
		rmq4.update(i, v[i].second);
		ll a = rmq1.query(0, n) - rmq3.query(0, n) + 1;
		ll b = rmq2.query(0, n) - rmq4.query(0, n) + 1;
		a = max(a, 0LL);
		b = max(b, 0LL);
		ans = max(ans, a + b);
	}
	cout << ans << endl;
}

