      lidx=i;
    }
    if(r[i]<rmi){
      rmi=r[i];
      ridx=i;
    }
    CHMAX(ma, r[i]-l[i]);
  }
  int ans=rmi-lma+ma;
  vi ord;
  REP(i, n){
    if(i!=lidx && i!=ridx){
      ord.push_back(i);
    }
  }
  sort(ALL(ord), [](int x, int y){
    if(max(0, r[x]-lma)==max(0, r[y]-lma)) return max(0, rmi-l[x])<max(0, rmi-l[y]);
    return max(0, r[x]-lma)>max(0, r[y]-lma);
  });
  ord.push_back(ridx);
  int lb=0;
  FORR(i, 0, n-1){
    CHMAX(lb, l[ord[i]]);
    // 1回目
    int tmp=max(0, r[ridx]-lb);
    // ２回目
    tmp+=max(0, (i>0 ? r[ord[i-1]] : r[lidx])-l[lidx]);
    CHMAX(ans, tmp);
  }
  cout<<ans<<'\n';
  return 0;
}

