int n;

struct coord
{
    int x, y;
};

struct cmpX
{
    bool operator()(const coord &a, const coord &b)
    {
        if(a.x == b.x)
            return a.y < b.y;

        return a.x < b.x;
    }
};

struct cmpY
{
    bool operator()(const coord &a, const coord &b)
    {
        if(a.y == b.y)
            return a.x < b.x;

        return a.y < b.y;
    }
};

coord a[MAX_N + 1];
coord b[MAX_N + 1];

int s[MAX_N + 1];
int d[MAX_N + 1];

int rez;

void inter(int &st, int &dr, int a, int b)
{
    if(a > dr || b < st)
    {
        st = dr = 0;
    }

    else
    {
        st = max(st, a);
        dr = min(dr, b);
    }
}

int k;
int diff[MAX_N * 2 + 1];

int dx[MAX_N * 2 + 1];

void getD()
{
    k = 0;
    dx[++ k] = diff[1];

    for(int i = 2; i <= 2*n; i ++)
    {
        if(diff[i] != diff[i - 1])
            dx[++ k] = diff[i];
    }
}

void doCalc(coord a[])
{
    int st = 1;
    int dr = (int)(1e9);
    for(int i = 1; i <= n; i ++)
    {
        inter(st, dr, a[i].x , a[i].y);

        s[i] = dr - st + 1;
    }


    st = 1;
    dr = (int)(1e9);
    for(int i = n; i >= 1; i --)
    {
        inter(st, dr, a[i].x , a[i].y);

        if(i >= 2)
            rez = max(rez, dr - st + 1 + s[i - 1]);

        d[i] = dr - st + 1;
    }
}

