        diff[++ k] = b[i].x;
        diff[++ k] = b[i].y;

        rez = max(rez, a[i].y - a[i].x);
    }

    sort(diff + 1, diff + k + 1);

    getD();

    sort(a + 1, a + n + 1, cmpX());
    sort(b + 1, b + n + 1, cmpY());

    doCalc(a);
    doCalc(b);

    rez = max(rez, mx + a[n].x - b[1].y);

    cout << rez << "\n";

    return 0;
}

