    int cnt = 0;
    int al,bl,ar,br;
    for(int i = 1;i <= N;i++){
        if(i != locl && i != locr){
            a[++cnt] = max(0,R[i] - mxl + 1);
            b[cnt] = max(0,mnr - L[i] + 1);
            id[cnt] = cnt;
        }
        else if(i == locl){
            al = max(0,R[i] - mxl + 1);
            bl = max(0,mnr - L[i] + 1);
        }
        else{
