#include <bits/stdc++.h>
using namespace std;

typedef long long int ll;
typedef pair<ll, ll> pll;

#define FOR(i, n, m) for (ll(i) = (m); (i) < (n); ++(i))
#define REP(i, n) FOR(i, n, 0)
#define OF64 std::setprecision(10)

const ll MOD = 1000000007;
const ll INF = (ll)1e15;

pll Q[100005];
ll L[100005];
ll R[100005];
ll N;

ll solve()
{
    memset(L, 0, sizeof(L));
    memset(R, 0, sizeof(R));
    {
        ll ml = 0, mr = INF;
        REP(i, N)
        {
            ml = std::max(ml, Q[i].first);
            mr = std::min(mr, Q[i].second);
            L[i] = std::max(0LL, mr - ml + 1);
        }
    }
    {
        ll ml = 0, mr = INF;
        REP(i, N)
        {
            ml = std::max(ml, Q[N - 1 - i].first);
            mr = std::min(mr, Q[N - 1 - i].second);
            R[N - 1 - i] = std::max(0LL, mr - ml + 1);
        }
    }
    ll max = 0;
    REP(i, N - 1)
    {
        max = std::max(max, L[i] + R[i + 1]);
    }
    return max;
}

int main()
{

    cin >> N;
    REP(i, N)
    {
        cin >> Q[i].first >> Q[i].second;
    }
    sort(Q, Q + N, [](pll a, pll b) { return a.first == b.first ? a.second < b.second : a.first < b.first; });
    ll max = solve();
    sort(Q, Q + N, [](pll a, pll b) { return a.second == b.second ? a.first < b.first : a.second < b.second; });
    max = std::max(max, solve());
    cout << max << endl;
    return 0;
