    node[k]=a;
    while(k>0){
      k=(k-1)/2;
      node[k]=min(node[k*2+1], node[k*2+2]);
    }
  }

  // [a, b)の最小値を求める
  // k: 節点の番号、その節点は[l, r)に対応づく
  T query(int a, int b, int k, int l, int r){
    // [a, b)と[l, r)が交差しなければMAX
    if(r<=a || b<=l){
      return MAX;
    }
    // [a, b)と[l, r)が完全に含んでいればこの節点の値
    if(a<=l && r<=b){
      return node[k];
    }
    // そうでなければ2つの子の最小値
    else{
      T v1=query(a, b, k*2+1, l, (l+r)/2), v2=query(a, b, k*2+2, (l+r)/2, r);
