        l = max(l, sections.at(i).first);
        r = min(r, sections.at(i).second);
        l_from_back.at(i) = l;
        r_from_back.at(i) = r;
    }

    long long maxi = 0;
    for (int i = 0; i < n - 1; i++) {
        long long cnt = max(0ll, r_from_front.at(i) - l_from_front.at(i) + 1) + max(0ll, r_from_back.at(i + 1) - l_from_back.at(i + 1) + 1);
        maxi = max(maxi, cnt);

        if (i != 0) {
            long long l = max(l_from_front.at(i - 1), l_from_back.at(i + 1));
            long long r = min(r_from_front.at(i - 1), r_from_back.at(i + 1));
            cnt = max(0ll, r - l + 1) + max(0ll, sections.at(i).second - sections.at(i).first + 1);
            maxi = max(maxi, cnt);
        }
    }
    cout << maxi << endl;
}

