ll N;

ll search(vpll RL){
  vll L(N);
  ll L_max = RL[0].second;

  REP(i,N){
    chmax(L_max, RL[i].second);
    L[i] = max((ll)0, RL[0].first - L_max + 1);
  }

  vll R(N);
  L_max = RL[N-1].second;

  RREP(i,N-1){
    chmax(L_max, RL[i].second);
    R[i] = max((ll)0, RL[i].first - L_max + 1);
  }

  ll ans = 0;
  REP(i,N-1){
    chmax(ans, L[i]+R[i+1]);
  }

  return ans;
}

