template<typename T>
struct SegmentTree {
private:
    using Func = function<T(T, T)>;

    int n;
    vector<T> node;

    T init_v;
    Func func;

public:

    SegmentTree(vector<T> a, Func _func, T _init_v) {
        int sz = a.size();
        n = 1;
        init_v = _init_v;
        func = _func;

        while (n < sz) n *= 2;
        node.resize(2 * n, init_v);
        for (int i = 0; i < sz; i++) node[i + n - 1] = a[i];
        for (int i = n - 2; i >= 0; i--) node[i] = func(node[i * 2 + 1], node[i * 2 + 2]);
    }

    void update(int pos, T v) {
        int k = pos + n - 1;
        node[k] = v;
        while (k > 0) {
            k = (k - 1) / 2;
            node[k] = func(node[k * 2 + 1], node[k * 2 + 2]);
        }
    }

    T get(int pos) {
        int k = pos + n - 1;
        return node[k];
    }

    T query(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0) r = n;
        if (r <= a || b <= l) return init_v;
        if (a <= l && r <= b)return node[k];
        T lv = query(a, b, k * 2 + 1, l, (l + r) / 2);
        T rv = query(a, b, k * 2 + 2, (l + r) / 2, r);
        return func(lv, rv);
    }

};

constexpr LL INF = 1e15;

int main() {

    int N;
    cin >> N;

    vector<pair<LL, LL>> LR(N);
    for (int i = 0; i < N; i++) {
        LL l, r;
        cin >> l >> r;
        r++;
        LR[i] = make_pair(l, r);
    }
    SORT(LR);

    vector<LL> L(N), R(N);
    for (int i = 0; i < N; i++) {
        L[i] = LR[i].first;
        R[i] = LR[i].second;
    }

    SegmentTree<LL> leftTree(L, [](const auto x, const auto y) { return max(x, y); }, -INF);
    SegmentTree<LL> rightTree(R, [](const auto x, const auto y) { return min(x, y); }, INF);

    LL ans = 0;
    for (LL i = 0; i < N; i++) {
        LL x = R[i] - L[i];
        LL l_max = max(leftTree.query(0, i), leftTree.query(i + 1, N));
        LL r_min = min(rightTree.query(0, i), rightTree.query(i + 1, N));
        ans = max(ans, max(0LL, r_min - l_max) + x);
    }

    for (LL i = 1; i < N; i++) {
        LL g1_l_max = leftTree.query(0, i);
        LL g1_r_min = rightTree.query(0, i);
        LL g2_l_max = leftTree.query(i, N);
        LL g2_r_min = rightTree.query(i, N);
        ans = max(ans, max(0LL, g1_r_min - g1_l_max) + max(0LL, g2_r_min - g2_l_max));
    }

    cout << ans << endl;

    return 0;
}

