using namespace std;

class BTwoContests {
public:
	void solve(std::istream& inp, std::ostream& outp) {
        Input in(inp);
        Output out(outp);

        int n = in.readInt();
        vector<pii> segs(n);
        for (int i = 0; i < n; ++i) {
            int l = in.readInt();
            int r = in.readInt();
            segs[i] = make_pair(l, r);
        }
        sort(segs);
        int ml = 0;
        int mr = MAX_INT;
        for (const auto& p : segs) {
            ml = max(ml, p.first);
            mr = min(mr, p.second);
        }
        int add = 0;
        if (mr >= ml) {
            add += mr - ml + 1;
            for (auto& p : segs) {
                p.second -= add;
            }
        }
        int answer = 0;
        for (const auto& p : segs) {
            answer = max(answer, p.second - p.first + 1);
        }
        vi left(n);
        left[0] = segs[0].second - segs[0].first + 1;
        int b = segs[0].second;
        for (int i = 1; i < n; i++) {
            b = min(b, segs[i].second);
            left[i] = b - segs[i].first + 1;
        }
        vi right(n);
        right[n - 1] = segs[n - 1].second - segs[n - 1].first + 1;
        b = segs[n - 1].second;
        for (int i = n - 1; i >= 0; i--) {
            b = min(b, segs[i].second);
            right[i] = b - segs[n - 1].first + 1;
        }
        for (int i = 1; i < n; i++) {
            if (left[i - 1] > 0 && right[i] > 0) {
                answer = max(answer, left[i - 1] + right[i]);
            }
        }
        out.printLine(answer + 2 * add);
	}
};


int main() {
    std::ios::sync_with_stdio(false);
	BTwoContests solver;
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	solver.solve(in, out);
	return 0;
}

