	for (int i = 0; i < N; ++i) {
		scanf("%d %d", &elems[i].first, &elems[i].second);
		maxrange = max(maxrange, elems[i].second - elems[i].first + 1);
		lorder[i] = iii(ii(-elems[i].first, elems[i].second), i);
		rorder[i] = iii(ii(elems[i].second, -elems[i].first), i);
	}
	sort(lorder, lorder + N);
	sort(rorder, rorder + N);
	if (lorder[0].second == rorder[0].second) printf("%d", maxrange + lorder[0].first.second + lorder[0].first.first + 1);
	else {
		int ans = 0, rf = lorder[0].first.second, ls = -rorder[0].first.second;
		priority_queue< ii, vector<ii>, greater<ii> > pq;
		for (int i = 0; i < N; ++i) {
			if (i == lorder[0].second || i == rorder[0].second) continue;
			pq.push(ii(elems[i].second, -elems[i].first));
		}
		pq.push(ii(1000000001, 0));
		ans = max(ans, max(min(rf, pq.top().first) + lorder[0].first.first, -1) + max(rorder[0].first.first - ls, -1) + 2);
		while (pq.size() != 1) {
			ls = max(ls, -pq.top().second);
			pq.pop();
			ans = max(ans, max(min(rf, pq.top().first) + lorder[0].first.first, -1) + max(rorder[0].first.first - ls, -1) + 2);
		}
		printf("%d", ans);
	}
	return 0;
}

