{
    x.erase(x.lower_bound(make_pair(l, -1)));
    y.erase(y.lower_bound(make_pair(r, -1)));
}

int query()
{
    //cout << x.size() << " " << y.size() << endl;
    set<pair<int, int> > ::iterator it1 = x.end();
