template<class T>inline bool chmax(T &a, const T &b) { if (b > a) { a = b; return true; } return false; }
template<class T>inline bool chmin(T &a, const T &b) { if (b < a) { a = b; return true; } return false; }

constexpr int dx[4] = {-1, 0, 0, 1}, dy[4] = {0, -1, 1, 0};
constexpr int INF = 1e9;
constexpr int MOD = 1e9 + 7;
constexpr long long LINF = 1e18;
constexpr double EPS = 1e-10;
constexpr double PI = M_PI;

void solve() {
    int n;
    cin >> n;
    vector<pair<int, int>> pro(n);
    for (int i=0; i<n; ++i) {
        cin >> pro.at(i).first >> pro.at(i).second;
        ++pro.at(i).second;
    }

    int maxl1 = 0, maxl2 = 0, minr1 = INF+1, minr2 = INF+1;
    for (auto p : pro) {
        int l = p.first, r = p.second;
        if (l > maxl1) maxl2 = maxl1, maxl1 = l;
        else if (l > maxl2) maxl2 = l;
        if (r < minr1) minr2 = minr1, minr1 = r;
        else if (r < minr2) minr2 = r;
    }
    int res = 0;
    for (auto p : pro) {
        int l = p.first, r = p.second;
        int maxl = maxl1 == l ? maxl2 : maxl1;
        int minr = minr1 == r ? minr2 : minr1;
        chmax(res, r - l + max(0, minr - maxl));
    }
    sort(pro.begin(), pro.end());
    vector<int> dp(n-1);
    int l = 0, r = INF+1;
    for (int i=0; i<n-1; ++i) {
        chmax(l, pro.at(i).first);
        chmin(r, pro.at(i).second);
        dp.at(i) += max(0, r - l);
    }
    l = 0, r = INF+1;
    for (int i=n-1; i>0; --i) {
        chmax(l, pro.at(i).first);
        chmin(r, pro.at(i).second);
        dp.at(i-1) += max(0, r - l);
    }
    for (auto x : dp) chmax(res, x);
    cout << res << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << fixed << setprecision(20);

    solve();

    return 0;
}

