    ll p1, p2, p3;
    p1 = min(r1, r) - max(l1, l) + 1 + r2 - l2 + 1;
    p2 = min(r2, r) - max(l2, l) + 1 + r1 - l1 + 1;
    p3 = min(r1, r2) - max(l1, l2) + + r - l + 1;
    if (p1 > p2 && p1 > p3) {
      r1 = min(r1, r);
      l1 = max(l1, l);
    } else if (p2 > p1 && p2 > p3) {
      r2 = min(r2, r);
      l2 = max(l2, l);
    } else if (p3 > p1 && p3 > p2) {
      r2 = min(r2, r1);
      l2 = max(l2, l1);
      l1 = l;
      r1 = r;
    }
  }
  ll ans = r1 - l1 + 1 + r2 - l2 + 1;
  cout << ans << endl;
}

