bool compare(const pair<int, int> &a, const pair<int, int> &b) {
	if(a.first == b.first) {
		return a.second > b.second;
	} else {
		return a.first < b.first;
	}
}

int main() {
	uint N;
	cin >> N;

	vector<pair<int, int>> LR(N);
	int l, r;
	for(int i=0; i<N; i++) {
		cin >> l >> r;
		LR[i] = make_pair(l, r);
	}

	sort(LR.begin(), LR.end(), compare);

	pair<int, int> L = LR.front();
	pair<int, int> R = LR.back();

	for(int i=1; i<N-1; i++) {
		int l_f = L.first;
		int l_s = L.second;
		int r_f = R.first;
		int r_s = R.second;

		int l_p = max(0, l_s - l_f);
		int r_p = max(0, r_s - r_f);

		int l_f_n = max(l_f, LR[i].first);
		int l_s_n = min(l_s, LR[i].second);
		int r_f_n = max(r_f, LR[i].first);
		int r_s_n = min(r_s, LR[i].second);

		int l_p_n = max(0, l_s_n - l_f_n);
		int r_p_n = max(0, r_s_n - r_f_n);

		int p_l_n = l_p_n + r_p;
		int p_r_n = l_p + r_p_n;

		if(p_l_n > p_r_n) {
			L.first = l_f_n;
			L.second = l_s_n;
		} else {
			R.first = r_f_n;
			R.second = r_s_n;
		}
	}

	uint l_ans = max(0, L.second - L.first + 1);
	uint r_ans = max(0, R.second - R.first + 1);
	uint ans = l_ans + r_ans;

	cout << ans << endl;
}

