    return a.first < b.first || a.first == b.first && a.second > b.second;
  });

  a[0] = PP(-inf, inf);
  for (int i = 0; i < m; ++i) {
    a[i + 1] = cap(a[i], p[i]);
  }
  b[m] = PP(-inf, inf);
  for (int i = m - 1; i >= 0; --i) {
    b[i] = cap(b[i + 1], p[i]);
  }

  reduce();

  if (m == 1) {
    cout << len(p[0]) + len(p[n - 1]) << endl;
