const int mod = 1000000007;
const int INF = 1e18;

template< typename T, typename E >
struct SegmentTree{
    using F = function< T(T, T) >;
    using G = function< T(T, E) >;
    int sz;
    vector<T> dat;
    F f;
    G g;
    T t1;
    SegmentTree(int n, F f, G g, T t1) : f(f), g(g), t1(t1) {
        sz = 1;
        while(sz < n) sz *= 2;
        dat.clear();
        dat.resize(2 * sz - 1, t1);
    }
    void set(int k, T x) { dat[k + sz - 1] = x; }
    void build() {
        for(int k = sz - 2; k >= 0; k--) {
            dat[k] = f(dat[2 * k + 1], dat[2 * k + 2]);
        }
    }
    void update(int k, E x) {
        k += sz - 1;
        dat[k] = g(dat[k], x);
        while(k > 0) {
            k = (k - 1) / 2;
            dat[k] = f(dat[2 * k + 1], dat[2 * k + 2]);
        }
    }
    T query(int a, int b, int k, int l, int r) {
        if(r <= a || b <= l) return t1;
        if(a <= l && r <= b) return dat[k];
        T vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
        T vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
        return f(vl, vr);
    }
    T query(int a, int b){ return query(a, b, 0, 0, sz); }
    T operator[](int k) { return dat[k + sz - 1]; }
};

signed main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    int n;
    cin >> n;
    vector<P> d(n);
    rep(i, 0, n){
        cin >> d[i].first >> d[i].second;
        d[i].second *= -1;
    }
    sort(d.begin(), d.end());
    rep(i, 0, n) d[i].second *= -1;
    SegmentTree<int, int> seg(n,
        [](int a, int b){ return min(a, b); },
        [](int a, int b){ return b; },
        INF);
    rep(i, 0, n) seg.update(i, d[i].second);
    int ans = 0;
    for(int i = 0; i < n - 1; i++){
        int ll = d[i].first;
        int lr = seg.query(0, i + 1);
        int rl = d[n - 1].first;
        int rr = seg.query(i + 1, n);
        if(ll <= lr && rl <= rr) ans = max(ans, max(0LL, lr - ll + 1) + max(0LL, rr - rl + 1));
    }
    for(int i = 1; i < n - 1; i++){
        int ll = d[i - 1].first;
        int lr = seg.query(0, i);
        int rl = d[n - 1].first;
        int rr = seg.query(i + 1, n);
        int l = max(ll, rl);
        int r = min(lr, rr);
        int tmp = 0;
        if(l <= r) tmp = r - l + 1;
        ans = max(ans, tmp + d[i].second - d[i].first + 1);
    }
    cout << ans << endl;
}

