   cin >> N;
   vector<pair<int, int>> A(N);
   for (int i = 0; i < N; ++i) {
      cin >> A[i].first >> A[i].second;
      A[i].second = -A[i].second;
   }
   int ans = 0;
   sort(A.begin(), A.end());
   vector<pair<int, int>> B;
   vector<pair<int, int>> C;
   for (int i = 0; i < N; ++i) {
      A[i].second = -A[i].second;
      while (B.size() && B.back().second >= A[i].second) {
         C.emplace_back(B.back());
         B.pop_back();
      }
      B.emplace_back(A[i]);
   }
   for (int i = 0; i + 1 < B.size(); ++i) {
      int leftVal = max(0, B[0].second - B[i].first + 1);
      int rightVal = max(0, B[i + 1].second - B.back().first + 1);
      ans = max(ans, leftVal + rightVal);
   }
   int leftVal = max(0, B[0].second - B.back().first + 1);
   int rightVal = 0;
   for (auto p : C) {
      rightVal = max(rightVal, p.second - p.first + 1);
   }
   for (int i = 1; i + 1 < B.size(); ++i) {
      rightVal = max(rightVal, B[i].second - B[i].first + 1);
   }
