pair<ll,ll> insec(pair<ll,ll> a, pair<ll,ll> b) {
	if(a.first>b.first){
		swap(a,b);
	}
	if(a.second>=b.second){
		return b;
	} else{
		return mp(b.first,a.second);
	}
}
ll calc(pair<ll,ll> a, pair<ll,ll> b){
	ll suma=a.second-a.first+1;
	ll sumb=b.second-b.first+1;
	return suma+sumb;
}


