  // for case that a part of group is singleton
  for (int i = 0; i < n; ++i) {
    ans = max(ans, max(r[min_r_ind] - l[max_l_ind] + 1, 0LL) + r[i] - l[i] + 1L);
  }

  vector<pair<ll, ll>> p;

  for (int i = 0; i < n; ++i) {
    if (i == min_r_ind || i == max_l_ind) continue;

    p.push_back(make_pair(0LL, 0LL));

    p[i].first = max(r[min_r_ind] - l[i] + 1L, 0LL);   // first: fixed right
    p[i].second = max(r[i] - l[max_l_ind] + 1L, 0LL);  // second: fixed left
  }

  sort(p.begin(), p.end(), cmp);

  for (int i = 1; i < n; ++i) {
    ans = max(ans, p[0].first + p[i].second);
  }

  ll part = p[0].second;
  for (int i = 1; i < n; ++i) {
    ans = max(ans, part + p[i].first);
    part = min(part, p[i].second);
  }

  printf("%lld\n", ans);

  return 0;
}

