	{
		auto rm = lower_bound(ls, ls + n + 1, r[i]);
		auto lm = lower_bound(rs, rs + n + 1, l[i]);
		if ((*rm != INF) && (lm != rs)) {
			tb = true;
			break;
		}

		if (*rm != INF) {
			left.push_back(i);
			continue;
		}
		if (l[i] >= rs[0]) {
			right.push_back(i);
			continue;
		}
