			ld.second= min(ld.second, r[left[i]]);
		}

		for (size_t i = 0; i < right.size(); i++)
		{
			rd.first = max(rd.first, l[right[i]]);
			rd.second = min(rd.second, r[right[i]]);
		}

		for (size_t i = 0; i < one.size(); i++)
		{
			if (ld.first >= l[one[i]]) {
				continue;
			}
			if (rd.second <= r[one[i]]) {
				continue;
			}
			if (l[one[i]] - ld.first > rd.second - r[one[i]]) {
				rd.second = r[one[i]];
			}
			else {
				ld.first = l[one[i]];
