	int ans = 0;
	{ // same
		int ans1 = 0, ans2 = 0;
		for(int i = 0; i < n; ++i) {
			int l, r;
			tie(l, r) = p[i];
			r = -r;
			if(l == lmax and r == rmin) {
				ans1 = max(0, rmin - lmax);
			} else {
				ans2 = max(ans2, r - l);
			}
		}
		if(ans1 > 0) {
			ans = ans1 + ans2;
		}
	}
	// (lmax, r) (l, rmin)
	{ // diff
		multiset<int> r1, l2;
		int idx = -1;
		for(int i = 0; i < n; ++i) {
			int l, r;
			tie(l, r) = p[i];
			r = -r;
			if(r == rmin) {
				if(idx == -1) {
					l2.insert(l);
					idx = i;
				}
			} else {
				r1.insert(r);
			}
