#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using pii = pair<ll, ll>;
using ppii = pair<pii,pii>;

ll solve() {
    ll N, l, r;
    cin >> N;
    vector<pii> A(N);
    ll xmin = 0;
    int xi;
    for ( int i = 0; i < N; i++ ) {
        cin >> l >> r;
        A[i] = pii(l,r);
    }
    sort(A.begin(), A.end());
    for ( int i = 0; i < N; i++ ) {
        l = A[i].first;
        r = A[i].second;
        if ( xmin < r-l+1 ) {
            xmin = r-l+1;
            xi = i;
        }
    }
    l = 0, r = 10e9+1;
    for ( int i = 0; i < N; i++ ) {
        if ( A[i] == A[xi] ) continue;
        l = max(l, A[i].first);
        r = min(r, A[i].second);
        if ( r < l ) break;
    }
    xmin += l < r ? r-l+1 : 0;

    vector<ppii> c;
    c.push_back(ppii(A[xi], pii(-1,-1)));
    for ( int ii = 0; ii < N; ii++ ) {
        int i = ii % 2 == 0 ? ii/2 : N - 1 - ii/2;
        if ( i == xi ) continue;
        vector<ppii> cn;
        for ( ppii pp : c ) {
            ll l1 = max(pp.first.first, A[i].first);
            ll r1 = min(pp.first.second, A[i].second);
            ll w11 = l1 < r1 ? r1-l1+1 : 0;
            ll w12 = pp.second.first == -1 ? 0 : pp.second.second - pp.second.first + 1;
            if ( pp.second.first == -1 || w11 + w12 >= xmin ) {
                cn.push_back(ppii(pii(l1,r1), pp.second));
            }
            ll l2 = pp.second.first == -1 ? A[i].first : max(pp.second.first, A[i].first);
            ll r2 = pp.second.first == -1 ? A[i].second : min(pp.second.second, A[i].second);
            ll w21 = pp.first.second - pp.first.first + 1;
            ll w22 = l2 < r2 ? r2-l2+1 : 0;
            if ( w21 + w22 >= xmin ) {
                cn.push_back(ppii(pp.first, pii(l2,r2)));
            }
        }
        c.swap(cn);
        if ( c.empty() ) break;
    }


    ll ans = 0;
    for ( ppii pp : c ) {
        ll w31 = pp.first.second - pp.first.first + 1;
        ll w32 = pp.second.first == -1 ? 0 : pp.second.second - pp.second.first + 1;
        ans = max(ans, w31+w32);
    }
    return ans;
}

int main() {
    auto ans = solve();
    cout << ans << "\n";
    return 0;
}

