    ans = CH(max, ans, max(0LL, R_min - l.top().first + 1) + max(0LL, r.top() - L_max + 1));
    REP(i, N)
    {
        r.push(l.top().second);
        l.pop();
        CH(max, ans, max(0LL, R_min - l.top().first + 1) + max(0LL, r.top() - L_max + 1));
    }
    OUT(ans);
}

