    for(i=0;i<n;i++)cin>>l.at(i)>>r.at(i);
    vector<int> len(n);
    for(i=0;i<n;i++)len.at(i)=r.at(i)-l.at(i)+1;
    int l1,r1,l2,r2;
    l1=1e9+1;
    r2=0;
    int c1,c2;
    int rmax=0;
    int lmin=1e9+1;
    for(i=0;i<n;i++)
    {
        if(r.at(i)>rmax)
        {
            l1=l.at(i);
            r1=r.at(i);
            c1=i;
            rmax=r.at(i);
        }
    }
    for(i=0;i<n;i++)
    {
        if(l.at(i)<lmin&&i!=c1)
        {
            l2=l.at(i);
            r2=r.at(i);
            c2=i;
            lmin=l.at(i);
        }
    }
    int len1=len.at(c1);
    int len2=len.at(c2);
    for(i=0;i<n;i++)
    {
        if(i!=c1&&i!=c2)
        {
            long long pe1=(r1-l1)-(min(r1,r.at(i))-max(l1,l.at(i)));
            long long pe2=(r2-l2)-(min(r2,r.at(i))-max(l2,l.at(i)));
            if(pe1<pe2)
            {
                l1=max(l1,l.at(i));
                r1=min(r1,r.at(i));
            }
            else
            {
                l2=max(l2,l.at(i));
                r2=min(r2,r.at(i));
            }
        }
    }
    long long ans = max(r1-l1+1,0)+max(r2-l2+1,0);
    cout<<ans<<endl;
}

#include <bits/stdc++.h>
#define MOD 1000000007LL
using namespace std;
typedef long long ll;
typedef pair<ll,ll> P;

class segtree{
public:
	static const int N=1<<19;
	int dp[1<<20];
	int sz[1<<20];
	int lazy[1<<20];
	segtree(){
		memset(dp,0,sizeof(dp));
	}
	void update(int k,int v){
		k+=N-1;
		sz[k]+=v;
		while(k>0){
			k=(k-1)/2;
			dp[k]=max(dp[k*2+1],dp[k*2+2]);
			sz[k]=sz[k*2+1]+sz[k*2+2];
		}
	}

	void lazy_eval(int k){
		dp[k]+=lazy[k];
		if(k<N-1){
			lazy[k*2+1]+=lazy[k];
			lazy[k*2+2]+=lazy[k];
		}
		lazy[k]=0;
	}

	void lazy_upd(int k){
		dp[k]=max(dp[k*2+1],dp[k*2+2]);
		sz[k]=0;
		if(dp[k]==dp[k*2+1]){
			sz[k]+=sz[k*2+1];
		}
		if(dp[k]==dp[k*2+2]){
			sz[k]+=sz[k*2+2];
		}
	}

	void add(int a,int b,int v,int k=0,int l=0,int r=N){
		lazy_eval(k);
		if(b<=l || r<=a)return;
		if(a<=l && r<=b){
			lazy[k]+=v;
			lazy_eval(k);
			return;
		}
		int mid=(l+r)/2;
		add(a,b,v,k*2+1,l,mid);
		add(a,b,v,k*2+2,mid,r);
		lazy_upd(k);
	}

	P query(int a,int b,int k=0,int l=0,int r=N){
		lazy_eval(k);
		if(b<=l || r<=a)return P(0,0);
		if(a<=l && r<=b)return P(dp[k],sz[k]);
		int mid=(l+r)/2;
		P vl=query(a,b,k*2+1,l,mid);
		P vr=query(a,b,k*2+2,mid,r);
		lazy_upd(k);
		return max(vl,vr);
	}
};

