	}
	sort(vec.begin(),vec.end());
	vec.erase(unique(vec.begin(),vec.end()),vec.end());
	for(int i=0;i<n;i++){
		p[i].first=lower_bound(vec.begin(),vec.end(),p[i].first)-vec.begin();
		p[i].second=lower_bound(vec.begin(),vec.end(),p[i].second)-vec.begin();
	}
	sort(p,p+n);
	int cnt=0;
	int rmin=p[0].second;
	for(int i=1;i<n;i++){
		if(rmin<p[i].first){
			cnt++;
			rmin=p[i].second;
		}else{
			rmin=min(rmin,(int)p[i].second);
		}
	}
	ll ans=0;
	for(int i=0;i<n;i++){
		ans=max(ans,vec[p[i].second]-vec[p[i].first]+1);
	}
	for(int i=0;i+1<vec.size();i++){
		//printf("%lld\n",vec[i+1]-vec[i]);
		seg.update(i,vec[i+1]-vec[i]);
		seg2.update(i,vec[i+1]-vec[i]);
	}
	for(int i=0;i<n;i++){
		//printf("%lld %lld\n",p[i].first,p[i].second+1);
		seg.add(p[i].first,p[i].second+1,1);
	}
	for(int i=0;i+1<n;i++){
		seg.add(p[i].first,p[i].second+1,-1);
		seg2.add(p[i].first,p[i].second+1,1);
		P p1=seg.query(0,seg.N);
		int val=0;
		if(p1.first==(n-i-1)){
			val+=p1.second;
		}
		P p2=seg2.query(0,seg2.N);
		if(p2.first==(i+1)){
			val+=p2.second;
		}
		//printf("%lld %lld %lld %lld\n",p1.first,p1.second,p2.first,p2.second);
		ans=max(ans,(ll)val);
	}
	printf("%lld\n",ans);
	return 0;
}

