struct KMin {
    int col1, col2;
    int val1, val2;

    KMin(){ 
        val1 = val2 = inf;
        col1 = col2 = -1;
    }

    void add(int v, int c) {
        if (v < val1) {
            swap(val1, val2);
            swap(col1, col2);
            swap(col1, c);
            swap(val1, v);
        } else if (v < val2) {
            swap(val2, v);
            swap(col2, c);
        }
    }

    void clear() {
        val1 = val2 = inf;
        col1 = col2 = -1;
    }

    void add(KMin other) {
        if (other.val1 < val1) {
            swap(val1, val2);
            swap(col1, col2);
            swap(val1, other.val1);
            swap(col1, other.col1);
        } else if (other.val1 < val2) {
            swap(val2, other.val1);
            swap(col2, other.col1);
        }
        if (other.val2 < val2) {
            swap(val2, other.val2);
            swap(col2, other.col2);
        }
    }

    int get(int c) {
        return c == col1 ? val2 : val1;
    }
};

int solve(int n, vector<int> l, vector<int> r) {
    int mr = inf;
    int idskip;

    KMin mml, mmr;

    for (int i = 0; i < n; i++) {
        if (upmin(mr, r[i])) {
            idskip = i;
        }

        mmr.add(r[i], i);
        mml.add(-l[i], i);
    }

    int ans = 0;

    for (int i = 0; i < n; i++) {
        int area1 = r[i] - l[i] + 1;
        int area2 = mmr.get(i) + mml.get(i) + 1;
        upmax(ans, area1 + area2);
    }

    vector<pii> evs;
    for (int i = 0; i < n; i++) if (i != idskip) {
        evs.eb(l[i], i);
    }

    sort(all(evs));

    int maxL = l[idskip];

    vector<int> rm(evs.size(), inf);
    for (int i = evs.size() - 1; i >= 0; i--) {
        rm[i] = r[evs[i].second];
        if (i + 1 < evs.size()) {
            upmin(rm[i], rm[i + 1]);
        }
    }

    for (int i = 0; i < evs.size(); i++) {
        // [i, ...]
        int area1 = r[idskip] - maxL + 1;
        int area2 = rm[i] - evs.back().first + 1;
        upmax(maxL, evs[i].first);
        upmax(ans, area1 + area2);
    }
    return ans;
}

int brute(int n, vector<int> l, vector<int> r) {
    int ans = 0;
    for (int mask = 1; mask < (1 << n) - 1; mask++) {
        int l1 = -inf, r1 = inf, l2 = -inf, r2 = inf;
        for (int i = 0; i < n; i++) {
            if (mask & (1 << i)) {
                upmax(l1, l[i]);
                upmin(r1, r[i]);
            } else {
                upmax(l2, l[i]);
                upmin(r2, r[i]);
            }
        }
        upmax(ans, r1 - l1 + 1 + r2 - l2 + 1);
    }
    return ans;
}

