const ll MOD = 1e9 + 7;

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	int n;
	cin >> n;

	// Divide into two piles, maximize sum of lengths of intersections of the piles
	// If there are three pairwise disjoint intervals, it is optimal to pick the longest interval for the other pile.
	// Otherwise, now every interval overlaps with either the interval that ends the earliest or starts the latest
	// The overlap of those two intervals will overlap with all other intervals, so if they are in the same pile,
	// it is optimal to pick the longest remaining interval alone in the other pile. If they are not in the same pile,
	// the result will be the minimum end over intervals in the left pile, plus the maximum start over intervals in the right pile.
	// Sort intervals by their start, and put some prefix into the right pile. Take answer as the maximum offer.

	vector<pair<int, int>> itvs(n);
	for (int i = 0; i < n; ++i) cin >> itvs[i].first >> itvs[i].second;

	// The interval that starts the latest
	for (int i = n-1; i >= 0; --i) {
		if (itvs[i].first > itvs.back().first) swap(itvs[i], itvs.back());
	}
	pair<int, int> x = itvs.back();
	itvs.pop_back();

	// The interval that ends the earliest
	for (int i = n-2; i >= 0; --i) {
		if (itvs[i].second < itvs.back().second) swap(itvs[i], itvs.back());
	}
	pair<int, int> y = itvs.back();

	if (y.second > x.second) {
		// x and y essentially are always in the same pile Put both x and y in the same pile
		ll res = 0;
		for (auto pr : itvs) res = max(res, (ll)pr.second - pr.first + 1);
		res += x.second - x.first + 1;
		cout << res << '\n';
	} else {
		itvs.pop_back();

		// Case 1: Put both x and y in the same pile
		ll res = 0;
		for (auto pr : itvs) res = max(res, (ll)pr.second - pr.first + 1);
		res += max(0, y.second - x.first + 1);

		// Case 2: x and y in different piles
		sort(itvs.begin(), itvs.end());

		int min_end = x.second;
		for (int i = n-3; i >= -1; --i) {
			int max_start = (i >= 0 ? max(y.first, itvs[i].first) : y.first);
			ll offer = max(0, min_end - x.first + 1) + max(0, y.second - max_start + 1);
			res = max(res, offer);

			cerr << x.first << ' ' << min_end << ", " << max_start << ' ' << y.second << ": " << offer << '\n';

			if (i >= 0) min_end = min(min_end, itvs[i].second);
		}

		cout << res << '\n';
	}

}

