		x2=x2%mod;
		if(x1>x2)
		{
			dp[i+1][0].first=p2;
			dp[i+1][0].second=dp[i][1].second;
		}
		else
		{
			dp[i+1][0].first=p1;
			dp[i+1][0].second=dp[i][0].second;
		}
