const long long MOD = 1e9 + 7;
const long long MAXN = 1e6 + 1;
using namespace std;

typedef long long ll;

long long readInt() {
    bool minus1 = false;
    long long result = 0;
    char ch;
    ch = getchar();
    while (true) {
        if (ch == '-') break;
        if (ch >= '0' && ch <= '9') break;
        ch = getchar();
    }
    if (ch == '-') minus1 = true; else result = ch-'0';
    while (true) {
        ch = getchar();
        if (ch < '0' || ch > '9') break;
        result = result*10 + (ch - '0');
    }
    if (minus1)
        return -result;
    else
        return result;
}

pair<int,int> a[MAXN];

int main() {
    int n = readInt();
    for (int i = 1; i <= n; i++) {
        a[i] = {readInt(), readInt()};
    }
    sort(a + 1, a + 1 + n);
    multiset <int> s1;
    multiset <int> s2;
    for (int i = 1; i <= n; i++) {
        s2.insert(a[i].S);
    }
    ll ans = 0;
    for (int i = 1; i < n; i ++) {
        /// min(R) - max(L) + 1
        s2.erase(s2.find(a[i].S));
        s1.insert(a[i].S);
        int min_R_1 = *s1.begin();
        int min_R_2 = *s2.begin();
        ans = max(ans, max(1ll * min_R_1 - a[i].F + 1, 0ll) + max(1ll * min_R_2 - a[n].F + 1, 0ll));

            ///checking for >
            s1.erase(s1.find(a[i].S));
	        auto nxt = s1.end();
	        if(nxt != s1.begin()) {
		        nxt--;
				ans = max(ans, max(1ll * min(1ll * a[i].S, 1ll * (*nxt)) - a[i].F + 1, 0ll) + max(1ll * (*s1.begin()) - a[n].F + 1, 0ll));
            }
            s1.insert(a[i].S);

        if (min_R_1 >= min_R_2) {
        	//correct
          	s1.erase(s1.find(a[i].S));
          	auto nxt = s1.end();
          	if(nxt != s1.begin()) {
        		nxt--;
				ans = max(ans, max(1ll * min(1ll * a[i].S, 1ll * (*nxt)) - a[i].F + 1, 0ll) + max(1ll * min_R_2 - a[n].F + 1, 0ll));
            }
            s1.insert(a[i].S);
        }
        if (a[i].F == a[n].F) assert(0);
    }
    cout << ans;
    return 0;
}

