using namespace std;
#define ll long long int
bool comp(const pair<ll,ll>&i,const pair<ll,ll>&j)
{
    if(i.first==j.first)
        return i.second>j.second;
    else
        return i.first<j.first;
}
int main()
{
    ll t;
    cin>>t;
    ll n=t;
    vector<pair<ll,ll> >v;
    while(t--)
    {
        ll a,b;
        cin>>a>>b;
        v.push_back({a,b});
    }
    sort(v.begin(),v.end(),comp);
    ll uporFirst[n];
    ll uporSecond[n];
    ll nisFirst[n];
    ll nisSecond[n];
    uporFirst[0]=v[0].first;
    uporSecond[0]=v[0].second;
    for(ll i=01; i<v.size(); i++)
    {
        uporFirst[i]=max(v[i].first,uporFirst[i-1]);
        uporSecond[i]=min(v[i].second,uporSecond[i-1]);
    }
    ll si=v.size()-1;
    nisFirst[si]=v[si].first;
    nisSecond[si]=v[si].second;
    for(ll i=si-1; i>=0; i--)
    {
        nisFirst[i]=max(v[i].first,nisFirst[i+1]);
        nisSecond[i]=min(v[i].second,nisSecond[i+1]);
    }
    ll ans=0;
    for(ll i=0; i<si; i++)
    {
        ll dif1=(uporSecond[i]-uporFirst[i]);
        dif1++;
        if(dif1<=0)
            dif1=0;
        ll dif2=(nisSecond[i+1]-nisFirst[i+1]);
        dif2++;
        if(dif2<=0)
            dif2=0;
        ans=max(ans,(dif1+dif2));
    }
    cout<<ans<<endl;
}

