int main(){
	cin.tie(nullptr);
	ios::sync_with_stdio(false);
	int n; cin >> n;
	vector<pair<ll,pair<ll,ll> > > v;
	for(int i=0;i<n;i++){
		ll l,r; cin >> l >> r;
		v.push_back(make_pair(r-l,make_pair(l,r)));
	}
	sort(v.begin(),v.end());
	if(n==2){
		ll ans=(v[0].second.second-v[0].second.first+1)+(v[1].second.second-v[1].second.first+1);
		cout << ans << endl;
		return 0;
	}
	ll ans=0;
	ll Left=v[0].second.first,Right=v[0].second.second;
	ll left1=v[n-1].second.first,right1=v[n-1].second.second;
	bool can=true,can1=true;
	for(int i=1;i<n-1;i++){
		ll l,r,l1,r1;
		l=max(Left,v[i].second.first);
		r=min(Right,v[i].second.second);
		l1=max(left1,v[i].second.first);
		r1=min(right1,v[i].second.second);
		if((right1-left1)-max(0LL,r1-l1)>=(Right-Left)-max(0LL,r-l)){
			Right=r;
			Left=l;
			if(Left>Right){
				can=false;
				Left=Right;
			}
		}
		else{
			right1=r1;
			left1=l1;
			if(left1>right1){
				can1=false;
				left1=right1;
			}
		}
	}
	if(Left>Right)can=false;
	if(left1>right1)can1=false;
	ans=(can?(Right-Left+1):0)+(can1?(right1-left1+1):0);
	ll ans1=0;
	Left=v[1].second.first,Right=v[1].second.second;
	left1=v[n-1].second.first,right1=v[n-1].second.second;
    can=true,can1=true;
    set<ll> s,st,nanao,yuriko;
    map<ll,ll> t,tt,ttt,tttt;
    set<int> fi;
	for(int i=0;i<n-1;i++){
		if(i==1)continue;
		ll l,r,l1,r1;
		l=max(Left,v[i].second.first);
		r=min(Right,v[i].second.second);
		l1=max(left1,v[i].second.first);
		r1=min(right1,v[i].second.second);
		if((right1-left1)-max(0LL,r1-l1)>=(Right-Left)-max(0LL,r-l)){
			fi.insert(i);
			Right=r;
			Left=l;
			s.insert(v[i].second.first);
			t[v[i].second.first]++;
			st.insert(v[i].second.second);
			tt[v[i].second.second];
			if(Left>Right){
				can=false;
				Left=Right;
			}
		}
		else{
			right1=r1;
			left1=l1;
			nanao.insert(v[i].second.first);
			ttt[v[i].second.first]++;
			yuriko.insert(v[i].second.second);
			tttt[v[i].second.second]++;
			if(left1>=right1){
				can1=false;
				left1=right1;
			}
		}
	}
	ans1=(can?(Right-Left+1):0)+(can1?(right1-left1+1):0);
	ans=max(ans,ans1);
	for(int i:fi){
		ll nagayoshi=Left;
		ll subaru=Right;
		if(Left==v[i].second.first&&t[v[i].second.first]==1){
			auto it=lower_bound(s.begin(),s.end(),v[i].second.first);
			if(it==s.begin())continue;
			it--;
			nagayoshi=*it;
		}
		if(Right==v[i].second.second&&t[v[i].second.second]==1){
			auto it=upper_bound(s.begin(),s.end(),v[i].second.second);
			if(it==s.end())continue;
			subaru=*it;
		}
		set<ll> tada,riina;
		tada=nanao;
		riina=yuriko;
		tada.insert(v[i].second.first);
		riina.insert(v[i].second.second);
		ll serika=*tada.begin();
		auto it=riina.end();
		it--;
		ll anna=*it;
		ll sum=max(0LL,subaru- nagayoshi+1)+max(0LL,anna -serika);
		ans=max(sum,ans);
	}
	cout << ans << endl;
}

