using namespace std;

bool chmin (int &a, int b) {
    if (a > b) {
        a = b;
        return true;
    }
    return false;
}

bool chmax (int &a, int b) {
    if (a < b) {
        a = b;
        return true;
    }
    return false;
}

pair<int, int> find_lr (const vector<pair<int, int>> &a) {
    int vl = 0, vr = numeric_limits<int>::max();
    for (const pair<int, int> &p : a) {
        chmax(vl, p.first);
        chmin(vr, p.second);
    }
    return make_pair(vl, vr);
}

int main() {
    int n;
    cin >> n;
    vector<pair<int, int>> dat;
    for (int i = 0; i < n; i++) {
        int l, r;
        cin >> l >> r;
        dat.emplace_back(l, r + 1);
    }

    auto [l, r] = find_lr(dat);

    auto f = [&] (const pair<int, int> &s, const pair<int, int> &t) {
        int al = max(s.second - l, 0), ar = max(t.second - l, 0);
        if (al == ar) return (max(r - s.first, 0) < max(r - t.first, 0));
        return (al < ar);
    };
    sort(dat.begin(), dat.end(), f);

    int vr = dat[0].second, vl = dat[n - 1].first;
    vector<int> s(n), t(n);
    s[0] = dat[0].second - dat[0].first;
    t[n - 1] = dat[n - 1].second - dat[n - 1].first;

    for (int i = 1; i < n; i++) {
        chmin(vr, dat[i].second);
        s[i] = min(s[i - 1], max(vr - dat[i].first, 0));
    }
    for (int i = n - 2; i >= 0; i--) {
        chmax(vl, dat[i].first);
        t[i] = min(t[i + 1], max(dat[i].second - vl, 0));
    }

    int ans = 0;
    for (int i = 0; i + 1 < n; i++) {
        chmax(ans, s[i] + t[i + 1]);
    }

    cout << ans << '\n';

    return 0;
}

