  usize n = scan<usize>();
  struct it_t {
    u32 l, r;

    u32 len() const {
      if (l <= r) {
        return r - l + 1;
      } else {
        return 0;
      }
    }

    it_t operator+(const it_t &x) const {
      return it_t({std::max(l, x.l), std::min(r, x.r)});
    }
  };
  std::vector<it_t> it(n);
  u32 maxw = 0;
  for (auto &e : it) {
    std::cin >> e.l >> e.r;
    chmax(maxw, e.len());
  }
  std::sort(it.begin(), it.end(), [&](auto &x, auto &y) {
    if (x.r != y.r) {
      return x.r < y.r;
    } else {
      return x.l > y.l;
    }
  });
  {
    u32 lmax = 0;
    std::vector<it_t> nex;
    for (const usize i : rep(0, n)) {
      if (lmax < it[i].l) {
        nex.push_back(it[i]);
      }
      chmax(lmax, it[i].l);
    }
    it = std::move(nex);
    n = it.size();
  }
  {
    if (n == 1) {
      std::cout << maxw + it.front().len() << std::endl;
      return;
    }
  }
  u32 ans = 0;
  std::vector<it_t> suf(n);
  suf.back() = it.back();
  for (const usize i : revrep(1, n)) {
    suf[i - 1] = suf[i] + it[i - 1];
  }
  it_t pre = it.front();
  for (const usize i : rep(1, n)) {
    chmax(ans, pre.len() + suf[i].len());
