#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef pair<int,int>pii;

const int N=1e5+10;
const int INF=1e9+10;
pii dat[N];

bool cmp(const pii& rh1, const pii& rh2) {
    return rh1.second < rh2.second;
}

int gao(int a,int b,int c){
    return min(max(a,c)+b, max(b,c)+a)-2;
}

int gao(int a,int b,int c,int d){
    return min(max(a,c)+max(b,d), max(a,d)+max(b,c))-2;
}

int getMax(const multiset<int>& st){
    assert(st.size());
    return *(--st.end());
}

void solve(){
    int n;
    scanf("%d",&n);
    int ans=0;
    for(int i=1;i<=n;i++){
        scanf("%d%d",&dat[i].first,&dat[i].second);
        ans=max(ans,dat[i].second-dat[i].first+1);
    }
    sort(dat+1,dat+n+1,cmp);

    multiset<int>lst,rst;
    for(int i=1;i<=n;i++) rst.insert(dat[i].first);

    for(int l=1,r=1;l<=n;l=r+1,r=l){
        while(r+1<=n && dat[r+1].second==dat[l].second) r++;
        int mi=INF,ma=0;
        for(int i=l;i<=r;i++){
            rst.erase(rst.lower_bound(dat[i].first));
            mi=min(mi,dat[i].first);
            ma=max(ma,dat[i].first);
        }
        int R=dat[1].second+dat[l].second;
        if(l==1 && r==n){
            ans=max(ans,R-(mi+ma-2));
        }
        else if(l==1){
            if(r-l+1==1) {}
            else{
                ans=max(ans,R-(mi+max(ma,getMax(rst))-2));
            }
        }
        else if(r==n){
            ans=max(ans,R-(getMax(lst)+ma-2));
            if(r-l+1==1) {}
            else{
                ans=max(ans,R-(max(getMax(lst),ma)+mi-2));
            }
        }
        else{
            ans=max(ans,R-(getMax(lst)+max(getMax(rst),ma)-2));
            if(r-l+1==1) {}
            else{
                ans=max(ans,R-gao(getMax(lst),getMax(rst),mi,ma));
            }
        }
        for(int i=l;i<=r;i++) lst.insert(dat[i].first);
    }
    printf("%d\n",ans);
}

int main(){

    solve();
    return 0;
}

