	vector<long> L(0);
	for (int i = 0; i < N; i++)
	{
		long r, l;
		cin >> l >> r;
		L.push_back(l);
		R.push_back(pair<long, int>(r, i));
	}
	//sort(L.begin(), L.end());
	sort(R.begin(), R.end());

	//ilu[n]はR[n]までを一方に入れたときのありうるLの一番大きい(範囲が狭くなる)値
	vector<long> ilu(N);
	ilu[0] = L[R[0].second];
	for (int i = 1; i < N; i++)
	{
		ilu[i] = max(ilu[i - 1], L[R[i].second]);
	}
	//iln[n]はR[n]までを一方に入れたときの残りのLの一番大きい(範囲が狭くなる)値
	vector<long> iln(N - 2);
	if (N >= 3)
		iln[N - 3] = L[R[N - 1].second];
	for (int i = N - 4; i >= 0; i--)
	{
		iln[i] = max(iln[i + 1], L[R[i + 2].second]);
	}
	//vector<long> fun(N);
	long fun = 0;
	for (int i = 0; i < N - 1; i++)
	{
		long f;
		if (i == N - 2) {
			f = max(R[0].first - ilu[i]+1,0l) + R[i + 1].first - L[R[i + 1].second]+1;
		}
		else if (ilu[i] >= L[R[i + 1].second])
		{
			f = max(R[0].first - max(iln[i], ilu[i])+1,0l) + (R[i + 1].first - L[R[i + 1].second]+1);
		}
		else {
			f = max(R[0].first - ilu[i]+1,0l) + max(R[i + 1].first - max(iln[i], L[R[i + 1].second])+1,0l);
		}
		fun = max(fun, f );
	}
	cout << fun;
	return 0;
}

