#define ALL(x) x.begin(), x.end()

const llong inf = 1'000'000'000'000'007ll;
const llong mod = 1e9+7;

struct data {
	llong L;
	llong R;

	data() = default;
	data(llong L, llong R) :
		L(L),
		R(R)
	{}

	bool operator<(const data &ri) const {
		// return R - L < ri.R - ri.L;
		return R == ri.R ?
			L < ri.L :
			R < ri.R;
	}
	bool operator==(const data &an) const {
		return L == an.L && R == an.R;
	}
};

llong N;
vector<data> tasks;

llong score(llong mid, llong id) {
	data d1(-inf, inf), d2(-inf, inf);
	data d3 = d1, d4 = d1;

	for (auto &task: tasks) {
		if (task.R < mid) {
			d1.L = max(d1.L, task.L);
			d1.R = min(d1.R, task.R);
		} else {
			d2.L = max(d2.L, task.L);
			d2.R = min(d2.R, task.R);
		}

		if (task == tasks[id]) {
			d3.L = max(d3.L, task.L);
			d3.R = min(d3.R, task.R);
		} else {
			d4.L = max(d4.L, task.L);
			d4.R = min(d4.R, task.R);
		}
	}

	llong a = 0, b = 0;
	if (d1.R != inf && d2.R != inf)
		a = max(0ll, d1.R - d1.L + 1) + max(0ll, d2.R - d2.L + 1);
	if (d3.R != inf && d4.R != inf)
		b = max(0ll, d3.R - d3.L + 1) + max(0ll, d4.R - d4.L + 1);

	return max(a, b);
}

int main() {
	vector<llong> pos;

	cin >> N;
	tasks.resize(N);
	for (auto &task: tasks) {
		cin >> task.L >> task.R;
		pos.push_back(task.R);
	}
	pos.push_back(0);
	pos.push_back(inf);

	sort(ALL(tasks));
	sort(ALL(pos));

	llong left = 0, right = pos.size()-1;
	llong lmid, rmid;
	while (lmid = (left * 2 + right) / 3, rmid = (left + right * 2) / 3, right - left > 5000) {
		llong lscore = score(pos[lmid], lmid);
		llong rscore = score(pos[rmid], rmid);

		if (lmid > rmid) {
			right = rmid;
		} else {
			left = lmid;
		}
	}

	llong ret = 0;
	for (llong i = max(0ll, left - 1000); i <= min((llong)(pos.size()-2), right + 1000); ++i) {
		ret = max(ret, score(pos[i], i));
	}

	cout << ret << endl;

	return 0;
}


