#define ll long long


struct segtree{
    int size;
    vector<int> dat;
    int inf = 1 << 30;

    segtree (int N) {
        size = 1;
        while (size < N) size *= 2;
        dat = vector<int>(2*size-1, inf);
    }

    int op(int a, int b) {
        return min(a, b);
    }

    void update(int i, int x) { 
        i += size-1;
        dat[i] = x;
        while (i > 0) {
            i = (i-1)/2;
            dat[i] = op(dat[2*i+1], dat[2*i+2]);
        }
        return;
    }

    int query(int a, int b) {
        return query(a, b, 0, 0, size);
    }

    int query(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l) return inf;
        if (a <= l && r <= b) return dat[k];

        int lv, rv;
        lv = query(a, b, 2*k+1, l, (l+r)/2);
        rv = query(a, b, 2*k+2, (l+r)/2, r);
        return op(lv, rv);
    }
};

int main(){
    int N;
    cin >> N;
    vector<pair<int, int>> ps(N);
    for (int i = 0; i < N; i++) {
        int l, r;
        cin >> l >> r;
        ps[i] = {l, r};
    }
    sort(ps.begin(), ps.end());
    segtree st(N);
    for (int i = 0; i < N; i++) {
        st.update(i, ps[i].second);
    }
    int ans = 0;
    for (int i = 1; i < N-1; i++) {
        int t = min(st.query(0, i), st.query(i+1, N));
        ans = max(ans, ps[i].second-ps[i].first+1 + max(0, t-ps[N-1].first+1));
    }
    for (int i = 0; i < N-1; i++) {
        int t = max(0, st.query(0, i+1)-ps[i].first+1);
        int u = max(0, st.query(i+1, N)-ps[N-1].first+1);
        ans = max(ans, t+u);
    }
    cout << ans << endl;
    return 0;
}

