vector<i64> crange(i64 cl, i64 cr, i64 xl, i64 xr) {
  vector<i64> res = {0, -1};
  if (xl > cr) {
    // 共通範囲なし
    return res;
  } else if (cr >= xl && cr <= xr) {
    res[0] = xl;
    res[1] = cr;
    return res;
  } else if (cl >= xl && cl <= xr) {
    res[0] = cl;
    res[1] = xr;
    return res;
  } else if (cl <= xl && xr <= cr) {
    res[0] = xl;
    res[1] = xr;
    return res;
  } else if (xl <= cl && cr <= xr) {
    res[0] = cl;
    res[1] = cr;
    return res;
  } else {
    // 共通範囲なし
    return res;
  }
}

