  i64 minid = -1;
  rep(i, n) {
    vector<i64> tmp = crange(L[maxid], R[maxid], L[i], R[i]);
    i64 kaburi = tmp[1] - tmp[0] + 1;
    if (range > kaburi) {
      range = kaburi;
      minid = i;
    }
  }

  vector<i64> c1 = {L[maxid], R[maxid]};
  // vector<i64> c2 = {L[minid], R[minid]};
  vector<i64> c2 = {1LL, 1000000000};
  rep(i, n) {
    if (i == maxid) continue;
    // if (i == minid) continue;
    i64 fun1, fun2;
    vector<i64> tmp1 = crange(c1[0], c1[1], L[i], R[i]);
