    a[i].first = l;
    a[i].second = r;
  }
  pair<long, long> c1, c2;
  c1 = a[0];
  c2 = a[1];
  for (int i=2; i<n; i++) {
    long v1 = get_num(a[i]) + get_num(intersection(c1, c2));
    long v2 = get_num(c1) + get_num(intersection(a[i], c2));
    long v3 = get_num(c2) + get_num(intersection(a[i], c1));
    if (v1 >= v2 && v1 >= v3) {
      c2 = intersection(c1, c2);
      c1 = a[i];
    } else if (v2 >= v3 && v2 >= v1) {
      c2 = intersection(a[i], c2);
    } else {
      auto tmp = c2;
      c2 = intersection(a[i], c1);
      c1 = tmp;
    }
  }
  cout<<get_num(c1) + get_num(c2)<<endl;
