using namespace std;
typedef long long ll;
typedef pair<ll, ll> P;
#define DUMP(x) cout << #x << " = " << (x) << endl;
#define FOR(i, m, n) for (ll i = m; i < n; i++)
#define IFOR(i, m, n) for (ll i = n - 1; i >= m; i--)
#define REP(i, n) FOR(i, 0, n)
#define IREP(i, n) IFOR(i, 0, n)
#define FOREACH(x, a) for (auto&(x) : (a))
#define ALL(v) (v).begin(), (v).end()
#define SZ(x) ll(x.size())

P calc(P p1, P p2) {
  P res = make_pair(min(p1.first, p2.first), max(p1.second, p2.second));
  return res;
}

ll score(P p) { return max(0LL, p.first - p.second + 1); }

int main() {
  ll n;
  cin >> n;
  vector<P> a, b;
  ll ans = 0;
  REP(i, n) {
    ll l, r;
    cin >> l >> r;
    ans = max(ans, r - l + 1);
    a.push_back(make_pair(r, l));
  }
  auto comp = [&](P p, P q) {
    if (p.second == q.second) return p.first > q.first;
    return p.second < q.second;
  };
  sort(ALL(a), comp);
  vector<P> left(n), right(n);
  P cur = make_pair(1e18, 0);
  REP(i, n - 1) {
    cur = calc(cur, a[i]);
    left[i] = cur;
  }
  cur = make_pair(1e18, 0);
  IFOR(i, 1, n) {
    cur = calc(cur, a[i]);
    right[i] = cur;
  }
  REP(i, n - 1) { ans = max(ans, score(left[i]) + score(right[i + 1])); }
  cout << ans << endl;
}

