struct Seg {
    int l, r;
    int len() {
        return std::max(0, r - l + 1);
    }
};

int main() {
    int n;
    std::cin >> n;

    std::vector<Seg> segs(n);
    for (auto& s : segs) {
        std::cin >> s.l >> s.r;
    }

    std::sort(segs.begin(), segs.end(),
              [](const Seg& a, const Seg& b) {
                  return a.r != b.r ? a.r < b.r : a.l < b.l;
              });
    // r最小，l最小を持ってくる
    auto base = segs.front();
    segs.erase(segs.begin());
    --n;

    std::sort(segs.begin(), segs.end(),
              [](const Seg& a, const Seg& b) {
                  return a.l != b.l ? a.l < b.l : a.r < b.r;
              });

    std::vector<int> back(n);
    Seg backs;
    backs.l = 0, backs.r = 1e9;
    back[0] = backs.len();
    for (int i = 1; i <= n; ++i) {
        auto seg = segs[n - i];
        backs.l = std::max(backs.l, seg.l);
        backs.r = std::min(backs.r, seg.r);
        back[i] = backs.len();
    }

    int ans = 0;
    Seg fseg = base;
    for (int i = 0; i < n; ++i) {
        int f = fseg.len();
        int b = back[n - i];
        ans = std::max(ans, f + b);

        fseg.l = std::max(fseg.l, segs[i].l);
        fseg.r = std::min(fseg.r, segs[i].r);
    }

    fseg = base;
    fseg.l = std::max(fseg.l, segs.back().l);
    fseg.r = std::min(fseg.r, segs.back().r);

    for (int i = 0; i < n - 1; ++i) {
        auto seg = segs[i];
        ans = std::max(ans, seg.len() + fseg.len());
    }

    std::cout << ans << std::endl;
    return 0;
}

