bool asc(const P &a, const P &b){
	if(a.fs == b.fs) return a.sc > b.sc;
	else return a.fs < b.fs;
}

void init(){
  rep(i, MAX_N*4) data[i] = LINF;
}

void update(int i, int x){
  i += N-1;
  data[i] = x;
  while(i > 0){
    i = (i-1)/2;
    data[i] = min(data[i*2+1], data[i*2+2]);
  }
}

ll rmq(ll a, ll b, ll k, ll l, ll r){
  if(r <= a || b <= l) return LINF;
  if(a <= l && r <= b) return data[k];
  else{
    ll vl = rmq(a, b, k*2+1, l, (l+r)/2);
    ll vr = rmq(a, b, k*2+2, (l+r)/2, r);
    return min(vl, vr);
  }
}

int main(void){
	int n;
	cin >> n;

	N = 1;
	while(N < n) N <<= 1;
	init();

	vector<P> r(n);
	rep(i, n) cin >> r[i].fs >> r[i].sc;

	sort(all(r));

	rep(i, n) update(i, r[i].sc);

	ll ans = 0;
	repn(i, n-1){
		ans = max(ans, max(ans, max(0LL, rmq(0, i, 0, 0, N)-r[i-1].fs+1)+max(0LL, rmq(i, n, 0, 0, N)-r[n-1].fs+1)));
	}

	vector<int> max_num;
	ll max_r = 0;
	rep(i, n){
		ll range = r[i].sc - r[i].fs+1;
		if(range > max_r){
			max_r = range;
			max_num.clear();
			max_num.pb(i);
		}else if(range == max_r){
			max_num.pb(i);
		}
	}

	rep(i, max_num.size()){
		ll max_l = -1, min_r = LINF;
		rep(j, n){
			if(j != max_num[i]){
				max_l = max(max_l, r[j].fs);
				min_r = min(min_r, r[j].sc);
			}
		}

		ans = max(ans, max_r+min_r-max_l+1);
	}

	co(ans);

	return 0;
}

