template<class T> inline bool chmax(T& a, T b) { if (a < b) { a = b; return true; } return false; }
template<class T> inline bool chmin(T& a, T b) { if (a > b) { a = b; return true; } return false; }

using P = pair<int, int>;

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  int n;
  cin >> n;
  vector<int> l(n), r(n);
  int lmax = 0, rmin = 1e9+10, lidx, ridx;
  rep(i, n) {
    cin >> l[i] >> r[i];
    r[i]++;
    if (chmax(lmax, l[i]))
      lidx = i;
    if (chmin(rmin, r[i]))
      ridx = i;
  }

  int mx = 0;
  rep(i, n) chmax(mx, r[i]-l[i]);
  int ans = mx+max(rmin-lmax, 0);

  if (lidx != ridx) {
    vector<P> rem;
    rep(i, n) {
      if (i == lidx || i == ridx)
        continue;
      rem.push_back({l[i], r[i]});
    }
    sort(rem.rbegin(), rem.rend());
    rem.push_back({l[ridx], r[ridx]});
    int l1 = rem[0].first, r1 = rmin;
    int l2 = lmax, r2 = r[lidx];
    chmax(ans, max(r1-l1, 0)+max(r2-l2, 0));
    rep(i, n-2) {
      l1 = rem[i+1].first;
      chmin(r2, rem[i].second);
      chmax(ans, max(r1-l1, 0)+max(r2-l2, 0));
    }
  }

  cout << ans << endl;
  return 0;
}

