const ll MOD = 1000000007LL;

int main() {
    int N; cin >> N;
    vector< pair<ll, ll> > segs;
    for(int i=0; i<N; i++) {
        ll l, r; scanf("%lld%lld", &l, &r);
        segs.emplace_back(l, r);
    }
    sort(segs.begin(), segs.end());

    vector<ll> max1(N), max2(N);
    vector<ll> min1(N), min2(N);
    max1[0] = segs[0].first, min1[0] = segs[0].second;
    max2[N-1] = segs[N-1].first, min2[N-1] = segs[N-1].second;
    for(int i=1; i<N; i++) {
        max1[i] = max(max1[i-1], segs[i].first);
        min1[i] = min(min1[i-1], segs[i].second);
    }
    for(int i=N-2; i>=0; i--) {
        max2[i] = max(max2[i+1], segs[i].first);
        min2[i] = min(min2[i+1], segs[i].second);
    }

    ll ans = 0;
    for(int i=0; i+1<N; i++) {
        ll l1 = max1[i], r1 = min1[i];
        ll l2 = max2[i+1], r2 = min2[i+1];
        // fprintf(stderr, "[%lld, %lld], [%lld, %lld]\n", l1, r1, l2, r2);
        ll sum = max(0LL, r1 - l1 + 1) + max(0LL, r2 - l2 + 1);
        chmax(ans, sum);
    }
    for(int i=0; i<N; i++) {
        ll l1, r1; tie(l1, r1) = segs[i];
        ll l2 = -LONGINF, r2 = LONGINF;
        if(i > 0) chmax(l2, max1[i-1]), chmin(r2, min1[i-1]);
        if(i + 1 < N) chmax(l2, max2[i+1]), chmin(r2, min2[i+1]);
        ll sum = max(0LL, r1 - l1 + 1) + max(0LL, r2 - l2 + 1);
        chmax(ans, sum);
    }
    cout << ans << endl;
    return 0;
}

