void __solve()
{
    i32 n; cin>>n;
    vector<i32> l(n),r(n);
    for(i32 i=0; i<n; ++i)
    {
        cin>>l[i]>>r[i];
        r[i]++;
    }    
    i32 i2=min_element(all(r))-r.begin();
    i32 i1=max_element(all(l))-l.begin();

    i32 ans=0;

    // in same group
    {
        i32 lenmx=0;
        for(i32 i=0; i<n; ++i)
        {
            if(i!=i1 and i!=i2) 
            {
                sbmax(lenmx,r[i]-l[i]);
            }
        }
        if(lenmx)
        {
            ans=lenmx+max(i32(0),r[i2]-l[i1]);
        }
    }

    // in different group
    if(i1!=i2)
    {
        vector<pii> seg;
        i32 ll=l[i2],rr=r[i1];
        for(i32 i=0; i<n; ++i)
        {
            if(i!=i1 and i!=i2 and l[i]>ll and r[i]<rr) seg.emplace_back(l[i],r[i]);
        }
        sort(all(seg));
        n=seg.size();
        vector<i32> rx(1+n);
        const int inf=2e9;
        {
            i32 now=inf;
            rx[n]=now;
            for(i32 i=n-1; i>=0; --i)
            {
                sbmin(now,seg[i].second);
                rx[i]=now;
            }
        }

        // k probs go G2
        for(i32 k=0; k<=n; ++k)
        {
            sbmax(ans, max((i32)0,r[i2]-ll) + max((i32)0, min(rr,rx[k])-l[i1]));
            if(k<n) sbmax(ll,seg[k].first);
        }
    }

    cout << ans << "\n";
}

