struct P{
    int l, r;
    P(int l, int r) : l(l), r(r){}
    bool operator<(const P &p)const{
        if(l != p.l) return l < p.l;
        return r < p.r;
    }
};

int main(void){
    int n;
    vector<P> p;
    int ans = 0;
    vector<int> v[4];
    cin >> n;
    for(int i=0;i<n;i++){
        int l, r;
        cin >> l >> r;
        p.push_back(P(l, r));
        ans = max(ans, r-l+1);
    }
    sort(p.begin(), p.end());
    for(int i=0;i<4;i++){
        v[i].assign(n, 0);
    }
    v[0][0] = p[0].l;
    v[1][0] = p[0].r;
    for(int i=1;i<n;i++){
        v[0][i] = max(v[0][i-1], p[i].l);
        v[1][i] = min(v[1][i-1], p[i].r);
    }
    v[2][n-1] = p[n-1].l;
    v[3][n-1] = p[n-1].r;
    for(int i=n-2;i>=0;i--){
        v[2][i] = max(v[2][i+1], p[i].l);
        v[3][i] = min(v[3][i+1], p[i].r);
    }
    for(int i=0;i<n-1;i++){
        int res = 0;
        if(v[0][i] <= v[1][i]) res += v[1][i] - v[0][i] + 1;
        if(v[2][i+1] <= v[3][i+1]) res += v[3][i+1] - v[2][i+1] + 1;
        ans = max(ans, res);
        //cout << i << " : " << res << endl;
        //cout << v[0][i] << " " << v[1][i] << " " << v[2][i] << " " << v[3][i] << endl;
    }
    cout << ans << endl;
}

