using namespace std;

int n;
int l[100000], r[100000];
int scoreL[100000];
int scoreR[100000];
int lmaxL[100000], rminL[100000];
int lmaxR[100000], rminR[100000];

signed main() {
	int i, j;

	cin >> n;

	typedef pair<int, int> P;
	static vector<P> pa;
	pa.resize(n);
	rep(i, n) cin >> pa[i].first >> pa[i].second;
	sort(pa.begin(), pa.end());
	pa.erase(unique(pa.begin(), pa.end()), pa.end());

	n = pa.size();
	rep(i, n) { l[i] = pa[i].first; r[i] = pa[i].second; }

	int lmax = l[0], rmin = r[0];
	rep(i, n) {
		lmax = max(lmax, l[i]);
		rmin = min(rmin, r[i]);
		lmaxL[i] = lmax;
		rminL[i] = rmin;
		scoreL[i] = max(rmin - lmax + 1, 0LL);
	}

	lmax = l[n - 1];
	rmin = r[n - 1];
	for (i = n - 1; i >= 0; i--) {
		lmax = max(lmax, l[i]);
		rmin = min(rmin, r[i]);
		lmaxR[i] = lmax;
		rminR[i] = rmin;
		scoreR[i] = max(rmin - lmax + 1, 0LL);
	}

	int ans = 0;

	//oxの形
	for (i = 0; i < n - 1; i++) {
		ans = max(ans, scoreL[i] + scoreR[i + 1]);
	}

	//xoxの形 (oのサイズは小さくて良いと仮定してみる)
	for (i = 1; i < n; i++) {
		rmin = r[i];
		lmax = l[i];
		for (j = i; j + 1 < n && j - i + 1 < 500; j++) {
			rmin = min(rmin, r[j]);
			lmax = max(lmax, l[j]);
			int res = min(rminL[i - 1], rminR[j + 1]) - max(lmaxL[i - 1], lmaxR[j + 1]) + 1;
			if (res < 0) res = 0;
			res += max(rmin - lmax + 1, 0LL);
			ans = max(ans, res);
		}
	}

	cout << ans << endl;
	return 0;
}

