void eS(int idx){
	sL.erase(sL.find(p[idx].x));
	sR.erase(sR.find(p[idx].y));
}

void iS(int idx){
	sL.insert(p[idx].x);
	sR.insert(p[idx].y);
}

void iF(int idx){
	curR.insert(make_pair(p[idx].y,idx));
}

void eF(int idx){
	curR.erase(curR.find(make_pair(p[idx].y,idx)));
}

int ans(int L){
	if(curR.size() == 0)return -2e9;
	if(sL.size() == 0)return -2e9;
	ll fn = max(0ll,1ll*((*curR.begin()).first) - L + 1);
	fn += max(0ll,1ll*(*sR.begin())-(*--sL.end()) + 1);
	return fn;
}

bool removeOne(int L){
	if(curR.size() == 0)return false;
	int f1 = ans(L);
	int idx = (*curR.begin()).second;
	eF(idx);
	iS(idx);
	int f2 = ans(L);
	eS(idx);
	iF(idx);
	return f2 >= f1;
}
