	iii lorder[N], rorder[N];
	for (int i = 0; i < N; ++i) {
		scanf("%lld %lld", &elems[i].first, &elems[i].second);
		maxrange = max(maxrange, elems[i].second - elems[i].first + 1);
		lorder[i] = iii(ii(-elems[i].first, elems[i].second), i);
		rorder[i] = iii(ii(elems[i].second, -elems[i].first), i);
	}
	sort(lorder, lorder + N);
	sort(rorder, rorder + N);
	if (lorder[0].second == rorder[0].second) printf("%lld", maxrange + lorder[0].first.second + lorder[0].first.first + 1);
