ll mod_pow(ll x, ll p, ll M = MOD) {
  ll a = 1;
  while (p) {
    if (p % 2)
      a = a*x%M;
    x = x*x%M;
    p /= 2;
  }
  return a;
}

ll mod_inverse(ll a, ll M = MOD) {
  return mod_pow(a, M - 2, M);
}

void set_fact(ll n, ll M = MOD) {
  fact[0] = fact[1] = rfact[0] = rfact[1] = 1;
  for (ll i = 2; i <= n; i++) {
    fact[i] = i * fact[i - 1] % M;
    // rfact[i] = mod_inverse(fact[i], M);
  }
}

//http://drken1215.hatenablog.com/entry/2018/06/08/210000
//nが大きくfactが計算できないときのほかの計算方法について書いてある
ll nCr(ll n, ll r, ll M = MOD) {
  if (r > n) return 0;
  assert(fact[2] == 2);
  ll ret = fact[n];
  if (rfact[r] == 0) {
    rfact[r] = mod_inverse(fact[r], M);
  }
  ret = (ret*rfact[r]) % M;
  if (rfact[n - r] == 0) {
    rfact[n - r] = mod_inverse(fact[n - r], M);
  }
  ret = (ret*rfact[n - r]) % M;
  return ret;
}

pll merge(pll a, pll b) {
  if (a.first == -1 or b.first == -1) return pll(-1, -1);
  if (a.first > b.first) swap(a, b);
  pll c(b.first, min(a.second, b.second));
  if (c.first >= c.second) c = pll(-1, -1);
  return c;
}

ll solve(int n, vector<pll> lr) {
  ll ans = 0;
  rep (i, n) {
    chmax(ans, lr[i].second - lr[i].first);
  }

  vector<pll> sum(n), rsum(n);
  sum[0] = lr[0];
  rep (i, n - 1) {
    sum[i + 1] = merge(sum[i], lr[i + 1]);
  }
  rsum[n - 1] = lr[n - 1];
  rrep (i, n - 1) {
    rsum[i] = merge(rsum[i + 1], lr[i]);
  }

  //DEBUG_VEC(lr);
  //DEBUG_VEC(sum);
  //DEBUG_VEC(rsum);

  rep (i, n - 1) {
    pll temp = merge(sum[i], rsum[i + 1]);
    chmax(ans, sum[i].second - sum[i].first + rsum[i + 1].second - rsum[i + 1].first);
  }
  return ans;
}

