mi mod_pow(ll a, ll n) {
    mi ret = 1;
    mi tmp = a;
    while(n > 0) {
        if(n % 2) ret *= tmp;
        tmp = tmp * tmp;
        n /= 2;
    }
    return ret;
}

ll calc(vector<P> v) {
    int n = (int)v.size();
    vector<P> mm1(n), mm2(n);
    mm1[0] = v[0];
    mm2[n - 1] = v[n - 1];
    FOR(i, 1, n) {
        mm1[i].first = max(mm1[i - 1].first, v[i].first);
        mm1[i].second = min(mm1[i - 1].second, v[i].second);
    }
    for(int i = n - 2; i >= 0; i--) {
        mm2[i].first = max(mm2[i + 1].first, v[i].first);
        mm2[i].second = min(mm2[i + 1].second, v[i].second);
    }
    ll ret = 0;
    if(n == 1) return v[0].second - v[0].first + 1;
    REP(i, n) {
        ll tmp = v[i].second - v[i].first + 1;
        P mm = {0, inf};
        if(i) {
            mm.first = max(mm.first, mm1[i - 1].first);
            mm.second = min(mm.second, mm1[i - 1].second);
        }
        if(i < n - 1) {
            mm.first = max(mm.first, mm2[i + 1].first);
            mm.second = min(mm.second, mm2[i + 1].second);
        }
        tmp += max(0LL, mm.second - mm.first + 1);
        ret = max(ret, tmp);
    }
    return ret;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n;
    cin >> n;
    vector<P> v(n);
    REP(i, n) {
        cin >> v[i].first >> v[i].second;
    }
    ll ans = calc(v);
    REP(i, n) v[i].second = -v[i].second;
    sort(ALL(v));
    REP(i, n) v[i].second = -v[i].second;
    vector<P> nv;
    ll mn = v[n - 1].second;
    nv.pb(v[n - 1]);
    for(int i = n - 2; i >= 0; i--) {
        if(v[i].second < mn) {
            mn = v[i].second;
            nv.pb(v[i]);
        }
    }
    sort(ALL(nv));
    int nn = (int)nv.size();
    ans = max(ans, calc(nv));
    REP(i, nn - 1) {
        ll tmp1 = nv[0].second - nv[i].first + 1;
        if(tmp1 <= 0) continue;
        ll tmp2 = nv[i + 1].second - nv[nn - 1].first + 1;
        if(tmp2 <= 0) continue;
        ans = max(ans, tmp1 + tmp2);
    }
    cout << ans << endl;
    return 0;
}

