	sort(ques, ques + N);
	P left = ques[0], right = ques[N - 1];
	for (ll i = 1; i < N - 1; i++) {
		ll l = dis(ques[i], left);
		ll r = dis(ques[i], right);

		if (dis(left,left)-l <= dis(right,right)-r) {
			left = renew(left, ques[i]);
		}
		else {
			right = renew(right, ques[i]);
		}
	}
	cout << dis(left, left) + dis(right, right) << endl;


}

