bool cmp(pair<ll, ll> f, pair<ll, ll> s){
    if((f.second-f.first)==(s.second-s.first)) return f.first<s.first;
    return (f.second-f.first)<s.second-s.first;
    if(f.first==s.first) return f.second<s.second;
    else return f.first<s.first;
}
int main() {
