        ll l, r;
        cin>>l>>r;
        arr.push_back({l,r});
    }
    sort(arr.begin(), arr.end(), cmp);
    ll best1=arr[0].first, best2=arr[0].second;
    leftAns[0]=best2-best1+1;
    for(int i=1;i<n;i++){
        best1=max(arr[i].first, best1);
        best2=min(best2, arr[i].second);
        leftAns[i]=max((ll)0, best2-best1+1);
    }
    best1=arr[n-1].first, best2=arr[n-1].second;
    rightAns[n-1]=best2-best1+1;
    for(int i=n-2;i>=0;i--){
        best1=max(arr[i].first, best1);
        best2=min(best2, arr[i].second);
        rightAns[i]=max((ll)0,best2-best1+1);
    }
    ll ans=0;
    for(int i=0;i<n-1;i++){
        ans=max(ans, leftAns[i] + rightAns[i+1]);
    }
