using namespace std;

class Range {
public:
  int l, r;
  Range() {}
  Range(int l, int r) : l(l), r(r) {}
};

bool cmp(const Range &a, const Range &b)
{
  int l = a.l+a.r;
  int r = b.l+b.r;
  if (l == r) return a.l < b.l;
  return l < r;
}

vector<Range> ranges;


int common2(int i, int j) { 
  int l = max(ranges[i].l, ranges[j].l);
  int r = min(ranges[i].r, ranges[j].r);
  // cerr <<  i << " " << j << " " << l  << " " << r << endl;
  return r-l+1;
}

int common(int i, int j) { 
  int min = -1;
  int max = -1;
  for (int k = i; k <= j; ++k) {
    Range &r = ranges[k];
    if (min == -1 || min > r.r) {
      min = r.r;
    }
    if (max == -1 || max < r.l) {
      max = r.l;
    }
  }
  return min-max+1;
}

int main() {
  int n;
  cin >> n;
  for (int i = 0; i < n; ++i) {
    int l, r;
    cin >> l >> r;
    ranges.emplace_back(l, r);
  }
  sort(ranges.begin(), ranges.end(), cmp);
  int ans = 0;
  for (int i = 0; i < n; ++i) { 
    if (i == 0) {
      ans = max(ans, common2(0, 0)+common2(1, n-1));
    }
    else if (i == n-1) {
      ans = max(ans, common2(n-1, n-1)+common2(0, n-2));
    }
    else {
      ans = max(ans, common2(i, i)+common2(0, n-1));
    }
  }
  for (int i = 0; i < n-1; ++i) { 
    ans = max(ans, common2(0, i)+common2(i+1, n-1));
  }
  // cerr << common2(0, 1) << " " << common2(2, 3) << endl;
  // for (Range &r: ranges) {
  //   cerr << r.l << " " << r.r << endl;
  // }
  cout << ans << endl;

}

