int N;
int solve(vector<pair<int, int>> prs) {
    int ret = 0;
    sort(all(prs));

    vector<int> v1, v2;
    vector<pair<int, int>> prs1, prs2;
    int low = 0;
    int high = INT_MAX;
    for (auto it = prs.begin(); it != prs.end(); it++) {
        low = max(low, it->first);
        high = min(high, it->second);
        v1.push_back(high - low + 1);
        prs1.push_back(mp(low, high));
    }

    low = 0;
    high = INT_MAX;
    for (auto it = prs.rbegin(); it != prs.rend(); it++) {
        low = max(low, it->first);
        high = min(high, it->second);
        v2.push_back(high - low + 1);
        prs2.push_back(mp(low, high));
    }
    reverse(all(v2));

    rep(i, N - 1) {
        ret = max(ret, v1[i] + v2[i + 1]);
    }

    low = 0;
    high = INT_MAX;

    REP(i, 1, N - 2) {
        low = max(low, prs[i - 1].first);
        high = min(high, prs[i - 1].second);

        int mlow = prs[i].first;
        int mhigh = prs[i].second;

        int bestVal = 0;
        for (int j = i; j < N; j++) {
            mlow = max(mlow, prs[j].first);
            mhigh = min(mhigh, prs[j].second);
            int tmplow = max(low, prs2[j + 1].first);
            int tmphigh = min(high, prs[j + 1].second);

            int val = max(0LL, mhigh - mlow + 1) + max(0LL, tmphigh - tmplow + 1);
            if (val > bestVal) {
                bestVal = val;
            } else break;
        }
        ret = max(ret, bestVal);
    }

    return ret;
}

