    // sort(ALL(Ridx), [&](int i1, int i2){
    //     return R[i1] < R[i2];
    // });
    vector<int> Lidx(N);
    iota(ALL(Lidx), 0);
    sort(ALL(Lidx), [&](int i1, int i2){
        return L[i1] > L[i2];
    });

    // corner: N=2
    if (N == 2) {
        cout << max(0LL, R[0]-L[0]+1) + max(0LL, R[1]-L[1]+1) << endl;
        return 0;
    }

    // Rminをfirstに入れる -> first's maxは変わらない
    // Lで大きい順にみる。ひとたびfirstに入れたら残りは全部firstに入れてよい 
    // いつfirstに入れるか？
    int RminIdx = min_element(ALL(R)) - R.begin();
    long long firstL = L[RminIdx];
    long long firstR = R[RminIdx];

    // corner: Lmaxをfirstに入れる
    long long score1first = -1;
    long long LRmax = -1;
    for (int i=0; i<N; i++) {
        if (Lidx[i] == RminIdx) continue;
        long long Li = L[Lidx[i]];
        long long Ri = R[Lidx[i]];
        if (score1first == -1){
            long long firstMax = firstR;
            long long firstMin = max(firstL, Li);
            score1first = max(0LL, (firstMax-firstMin + 1));
        }
        else {
            long long lr = max(0LL, (Ri - Li + 1));
            LRmax = max(LRmax, lr);
        }
    }
    long long score1 = score1first + LRmax;
    cerr << "#" << score1 << endl;

    // Lmaxをsecondに入れる -> second's minは変わらない
    long long firstMin = firstL;
    long long firstMax = firstR;
    long long secondMin = -1;
    long long secondMax = -1;
    vector<long long> firstScore;
    vector<long long> secondScore;
    bool isFirst = true;
    for (int i=0; i<N; i++) {
        if (Lidx[i] == RminIdx) continue;
        long long Li = L[Lidx[i]];
        long long Ri = R[Lidx[i]];
        if (secondMin == -1) {
            secondMin = Li;
            secondMax = Ri;
        }
        else {
            // firstのminが増える損失 vs secondのmaxが減る損失
            // firstに入れた最大のL vs secondに入れた最小のR

            if (isFirst) {
                // 1個もいれない
                long long fs = max(0LL, (firstMax - firstMin)+1);
                firstScore.push_back(fs);
                long long ss = max(0LL, (secondMax - secondMin) + 1);
                secondScore.push_back(ss);
            }
            isFirst = false;

            firstMin = max(firstMin, Li);
            secondMax = min(secondMax, Ri);
            long long fs = max(0LL, (firstMax - firstMin)+1);
            firstScore.push_back(fs);
            long long ss = max(0LL, (secondMax - secondMin) + 1);
            secondScore.push_back(ss);
        }
    }
    long long sss = 0;
    for (int i=0; i<firstScore.size(); i++) {
        sss = max(sss, firstScore[i] + secondScore[firstScore.size() - i -1]);
    }
    long long score2 = sss;

    cerr << "#" << score2 << endl;
    cout << max(score1,score2) << endl;
    return 0;
}

