// chmax, chmin
template<class T>
inline bool chmax(T &a, T b) {
    if (a < b) {
        a = b;
        return 1;
    }
    return 0;
}

template<class T>
inline bool chmin(T &a, T b) {
    if (a > b) {
        a = b;
        return 1;
    }
    return 0;
}


struct Line {
    ll l;
    ll r;
    int id;

    ll size() {
        return max(0ll, r - l);
    }

    Line intersect(Line x) {
        return {max(x.l, l), min(x.r, r), -1};
    }

    bool contains(Line x) {
        return l <= x.l && x.r <= r;
    }
};


Line getMin(vector<Line> ps) {
    sort(ps.begin(), ps.end(), [](Line &a, Line &b) {
        if (a.r != b.r) {
            return a.r < b.r;
        }
    });
    return ps[0];
}

Line getMax(vector<Line> ps) {
    sort(ps.begin(), ps.end(), [](Line &a, Line &b) {
        return a.l > b.l;
    });
    return ps[0];
}


/*
 * 1 20
 * 2 19
 * 3 18
 * 4 17
 */
void solve(long long N, std::vector<long long> L, std::vector<long long> R) {
    vector<Line> ps;
    vector<long long> ls;
    for (int i = 0; i < N; i++) {
        ps.push_back({L[i], R[i] + 1, i});
        ls.push_back(L[i]);
    }

    sort(ls.begin(), ls.end());
    ls.erase(unique(ls.begin(), ls.end()), ls.end());

    ll ans = 0;
    for (auto i : ps) ans = max(ans, i.size());

    Line minL = getMin(ps);
    Line maxL = getMax(ps);


    int mindex = lower_bound(ls.begin(), ls.end(), minL.l) - ls.begin();

    for (; mindex < ls.size(); mindex++) {
        ll s = ls[mindex];
        if( s > minL.r) break;

        Line tmp = maxL;
        ll bestSize = -1e18;
        bool used = false;
        for (int i = 0; i < N; i++) {
            if (i == minL.id || ps[i].contains({s, minL.r})) {
                if (i != minL.id) {
                    bestSize = max(bestSize, ps[i].size());
                }
            } else {
                tmp = tmp.intersect(ps[i]);
                used = true;
            }
        }
        if (!used) {
            ans = max(ans, bestSize + Line{s, minL.r}.size());
        } else {
            ans = max(ans, tmp.size() + Line{s, minL.r}.size());
        }


    }
    cout << ans << endl;

}

int main() {
    long long N;
    scanf("%lld", &N);
    std::vector<long long> L(N);
    std::vector<long long> R(N);
    for (int i = 0; i < N; i++) {
        scanf("%lld", &L[i]);
        scanf("%lld", &R[i]);
    }
    solve(N, std::move(L), std::move(R));
    return 0;
}

