    auto del_r = [&](ll r) {
        auto ite = rset.find(r);
        rset.erase(ite);
    };

    ll l1, r1, ans = 0;
    auto update_ans = [&] {
        ll rng1 = max<ll>(0, r1 - l1 + 1);
        ll rng2 = max<ll>(0, (*rset.begin()) - (*lset.begin()) + 1);
        chmax(ans, rng1 + rng2);
    };

    for(auto &&ele : lr) {
        tie(l1, r1) = ele;
        del_l(l1);
        del_r(r1);
        update_ans();
        lset.insert(l1);
        rset.insert(r1);
    }

    {
        auto ite = 
            min_element(ALL(lr),
                        [](PLL p, PLL q) {
                            ll lp, lq, rp, rq;
                            tie(lp, rp) = p;
                            tie(lq, rq) = q;
                            if(lp != lq) return lp > lq;
                            else return rp < rq;
                        });
        tie(l1, r1) = *ite;
        del_l(l1);
        del_r(r1);
        update_ans();
        lr.erase(ite);
    }

    sort(ALL(lr),
         [](PLL p, PLL q) {
             ll lp, rp, lq, rq;
             tie(lp, rp) = p;
             tie(lq, rq) = q;
             if(lp != lq) return lp > lq;
             else return rp < rq;
         });

    queue<PLL> lr_q;
    for(auto &&ele : lr) lr_q.push(ele);

    while(1 < lr_q.size()) {
        ll l, r;
        tie(l, r) = lr_q.front();
        chmax(l1, l);
        chmin(r1, r);
        del_l(l);
        del_r(r);
        lr_q.pop();
        update_ans();
    }

    cout << ans << endl;
    return 0;
}

