pair<int, int> intersection(pair<int, int> x, pair<int, int> y) {
	int l = max(x.first, y.first);
	int r = min(x.second, y.second);
	if (l > r) return {2, 1};
	return {l, r};
}
int len(pair<int, int> p) {
	return p.second - p.first + 1;
}

int main()
{
	int n;
	ignore = scanf("%d", &n);

	vector<pair<int, int>> A;

	for (int i = 0; i < n; i++) {
		int L, R;
		ignore = scanf("%d %d", &L, &R);		
		A.emplace_back(L, R);
	}

	int ans = 0;
	{
		vector<pair<int, int>> B;
		for (int i = 0; i < n; i++) {
			if (i == 0) B.push_back(A[0]);
			else B.push_back(intersection(B.back(), A[i]));
		}
		pair<int, int> x = {1, 1000000000};
		for (int i = n - 1; i >= 0; i--) {
			int tmp = len(A[i]) + len(i == 0 ? x : intersection(x, B[i - 1]));
			ans = max(ans, tmp);
			x = intersection(x, A[i]);
		}
	}

	int j = -1;
	for (int i = 0; i < n; i++) {
		if (j == -1 || A[i].second < A[j].second) j = i;
	}

	pair<int, int> x = {1, 1000000000};
	int cnt = 0;

	vector<pair<int, int>> B;

	for (int i = 0; i < n; i++) {
		if (i == j || A[i].first <= A[j].first) continue;
		if (A[i].first <= A[j].second) B.push_back(A[i]);
		else {
			cnt++;
			x = intersection(x, A[i]);
		}
	}

	sort(B.begin(), B.end());

	while (!B.empty()) {
		if (cnt > 0) ans = max(ans, len(x) + A[j].second - B.back().first + 1);
		cnt++;
		x = intersection(x, B.back());
		B.pop_back();
	}

	if (cnt > 0) ans = max(ans, len(x) + len(A[j]));

	printf("%d\n", ans);
}

