ll dfs(pair<ll, ll> f, pair<ll, ll> s,ll t) {
    if(t==n){
        return max(0LL, f.second - f.first + 1) + max(0LL, s.second - s.first + 1);
    }
    ll x = v[t].first, y = v[t].second;
    ll a1 = max(0LL, min(f.second, y) - max(f.first, x) + 1) + max(0LL, s.second - s.first + 1);
    ll a2 = max(0LL, min(s.second, y) - max(s.first, x) + 1) + max(0LL, f.second - f.first + 1);
    ll a3 = max(0LL, min(f.second, s.second) - max(f.first, s.first) + 1) + y - x + 1;
    ll ma = max({a1, a2, a3});
    ll b=0,c=0,d=0;
    if(ma == a1) {
        f.first = max(f.first, x), f.second = min(f.second, y);
        if(f.first > f.second) f = {10, -10};
        b = dfs(f,s,t+1);
    } else if(ma == a2) {
        s.first = max(s.first, x), s.second = min(s.second, y);
        if(s.first > s.second) s = {10, -10};
        c = dfs(f,s,t+1);
    } else if(ma == a3) {
        f.first = max(f.first, s.first), f.second = min(f.second, s.second);
        if(f.first > f.second) f = {10, -10};
        s = {x, y};
        d = dfs(f,s,t+1);
    }
    return max({b,c,d});
}

