int solve1(){
	int l = P[1].first, r = P[1].second, s = 0;
	for(int i=1; i<=n; i++){
		l = max(l, P[i].first), r = min(r, P[i].second);
		s = max(s, P[i].second - P[i].first+1);
	}
	return max(r-l+1, 0) + s;
