int solve2(){
	sort(P+1, P+n+1, [](pii a, pii b){
		return a.second<b.second || (a.second==b.second && a.first>b.first);
	});
	vector<pii> V;
	for(int i=1, l=0; i<=n; i++){
		int x,y; tie(x,y) = P[i];
		if(l<x) V.push_back(P[i]);
		l = max(l, x);
	}

	int m = V.size(), ans = 0;
	for(int i=0; i<m-1; i++){
		int lf = V[0].second - V[i].first+1;
		int ri = V[i+1].second - V[m-1].first+1;
		ans = max(ans, max(0,lf) + max(0,ri));
	}
	return ans;
}

