    if (i > j) return 0;
    int a = vl, b = vr;
    int ml = st[j].first;
    int mr = st[i].second;
    if (i) {
      a = max(a, st[i - 1].first);
      b = min(b, st[0].second);
    }
    if (j != (int) st.size() - 1) {
      a = max(a, st.back().first);
      b = min(b, st[j + 1].second);
    }
    if (a) {
      return max(0, mr - ml + 1) + max(0, b - a + 1);
    } else {
      return 0;
    }
  };

  void solve(int l, int r, int opt_l, int opt_r) {
    if (l >= r) return;
    if (r - l == 1) {
      for (int i = max(l, opt_l); i <= opt_r; i++)
        ans = max(ans, f(l, i));
    } else {
      int m = (l + r) / 2;
      int opt = -1;
      for (int i = opt_l; i <= opt_r; i++) {
        if (i >= m && (opt == -1 || f(m, i) > f(m, opt))) {
          opt = i;
        }
      }
      ans = max(ans, f(m, opt));
      solve(l, m, opt_l, opt);
      solve(m + 1, r, opt, opt_r);
    }
  }

