//			Int t = 0;
//			ans = max(ans, t = R[i] - L[i] + 1 + Rmin - Lmax + 1);
//		}
//	}

	Int Rmin = INF;
	int Rmin_id = -1;
	for(int i = 0;i < N;i++){
		if(Rmin > R[i]){
			Rmin = R[i];
			Rmin_id = i;
		}
	}
	Int Lmax2 = -INF, Rmin2 = INF;
	for(int i = N - 1;i >= 0;){
		if(p[i].first > Rmin){
			Lmax2 = max(Lmax2, L[i]);
			Rmin2 = min(Rmin2, R[i]);
			i--;
			continue;
		}
		if(i == N - 1){
			Int max_len = -INF;
			for(int j = 0;j < N - 1;j++){
				max_len = max(max_len, R[j] - L[j] + 1);
			}
			ans = max(ans, max_len + Rmin - L[i] + 1);
			Lmax2 = max(Lmax2, L[i]);
			Rmin2 = min(Rmin2, R[i]);
			i--;
			continue;
		}
		int j = i;
		while(j >= 0 and L[j] == L[i]){
			j--;
		}

		if(Lmax2 >= 0 and Rmin2 >= Lmax2)ans = max(ans, Rmin2 - Lmax2 + 1 + Rmin - L[i] + 1);
