    }
    sort(nums.begin(), nums.end());
    vector <ll> L(n);
    vector <ll> R(n);
    for(int i=0; i<n; i++){
        L[i] = nums[i].f;
        R[i] = nums[i].s;
    }
    SegmentTree max_L(L, 0);
    SegmentTree min_R(R, 1);
    ll L1, R1, L2, R2;
    ll ans = 0;
    for(int i=0; i<n-1; i++){
        L1 = max_L.query(0, i);
        R1 = min_R.query(0, i);
        L2 = max_L.query(i+1,n-1);
        R2 = min_R.query(i+1,n-1);
        ans = max(ans, calc(L1,R1)+calc(L2,R2));
    }

    sort(nums.begin(), nums.end(), comp);
    for(int i=0; i<n; i++){
        L[i] = nums[i].f;
        R[i] = nums[i].s;
    }
    SegmentTree max2_L(L, 0);
