    R.erase(unique(R.begin(), R.end()), R.end());
    ll lb = 0, ub = R.size() - 1;
    while(ub - lb > 1000) {
#if 1
        // 1000 分探索
        ll sub = (ub - lb) / 1000;
        ll next_val = -LLINF;
        ll next_ind = -1;
        for(int i = lb; i <= ub; i += sub) {
