pi get(pi a, pi b){
	if(a>b) swap(a, b);
	if(a == mp(0, 0)) return a;
	if(a == mp(-1, -1)) return b;
	if(max(a.f, b.f) > min(a.s, b.s)) return mp(0, 0);
	return mp(max(a.f, b.f), min(a.s, b.s));
}
int val(pi a){
	if(a == mp(0, 0) || a == mp(-1, -1)) return 0;
	return a.s - a.f+1;
}
