typedef pair<ll,ll> P;
bool judge(const P &p1,const P &p2){
  if(p1.first==p2.first) return p1.second>p2.second;
  return p1.first<p2.first;
}
int main(){
  ll n;
  cin>>n;
  ll lm=0,rm=1e9+7;
  ll max_width=0;
  vector<P> vec;
  for(int i=0;i<n;i++){
    ll l,r;
    cin>>l>>r;
    r++;
    lm=max(lm,l);
    rm=min(rm,r);
    max_width=max(max_width,r-l);
    vec.push_back(P(l,r));
  }
  ll ans=max_width+max(rm-lm,(ll)0);
  vector<P> v2;
  for(int i=0;i<n;i++){
    ll x=max(vec[i].second-lm,(ll)0),y=max(rm-vec[i].first,(ll)0);
    v2.push_back(P(x,y));
  }
  sort(v2.begin(),v2.end(),judge);
  ll kmin=1e9+7;
  for(int i=1;i<n;i++){
    kmin=min(v2[i-1].second,kmin);
    ans=max(ans,kmin+v2[i].first);
  }
  cout<<ans<<endl;
}

