bool compare(const pair<int, int> &a, const pair<int, int> &b) {
	if(a.first == b.first) {
		return a.second > b.second;
	} else {
		return a.first < b.first;
	}
}

int main() {
	uint N;
	cin >> N;

	vector<pair<int, int>> LR(N);
	int l, r;
	for(int i=0; i<N; i++) {
		cin >> l >> r;
		LR[i] = make_pair(l, r);
	}

	//sort(LR.begin(), LR.end(), compare);
	sort(LR.begin(), LR.end());

	pair<int, int> c1 = LR.front();
	pair<int, int> c2 = LR.back();

	for(int i=1; i<N-1; i++) {
		// 振り分け前の回答範囲
		int c1_l = c1.first;
		int c1_r = c1.second;
		int c2_l = c2.first;
		int c2_r = c2.second;
		// 振り分け前の楽しさ
		int c1_p = max(0, c1_r - c1_l);
		int c2_p = max(0, c2_r - c2_l);
		// 振り分け後の回答範囲
		int c1_l_n = max(c1_l, LR[i].first);
		int c1_r_n = min(c1_r, LR[i].second);
		int c2_l_n = max(c2_l, LR[i].first);
		int c2_r_n = min(c2_r, LR[i].second);
		// 振り分け後の楽しさ
		int c1_p_n = max(0, c1_r_n - c1_l_n);
		int c2_p_n = max(0, c2_r_n - c2_l_n);
		// 振り分け選択
		if(c1_p_n + c2_p > c1_p + c2_p_n) {
			c1.first = c1_l_n;
			c1.second = c1_r_n;
		} else {
			c2.first = c2_l_n;
			c2.second = c2_r_n;
		}
	}

	uint l_ans = max(0, c1.second - c1.first + 1);
	uint r_ans = max(0, c2.second - c2.first + 1);
	uint ans = l_ans + r_ans;

	cout << ans << endl;
}

