const int maxN = 1e5 + 10, inf = 1e18;

pair < int, int > f(pair < int, int > a, pair < int, int > b) {
    return {max(a.first, b.first), min(a.second, b.second)};
}

int e(pair < int, int > a) {
    return a.second - a.first;
}

int n, ans;
pair < int, int > a[maxN], pref[maxN], suf[maxN], d[maxN];

void solve() {
    cin >> n;
    for (int i = 0; i < n; i++) {
        cin >> a[i].first >> a[i].second;
    }
    sort(a, a + n);
    pref[0] = {a[0].first, a[0].second};
    for (int i = 1; i < n; i++) {
        pref[i] = f(pref[i - 1], a[i]);
    }
    suf[n - 1] = {a[n - 1].first, a[n - 1].second};
    for (int i = n - 2; i >= 0; i--) {
        suf[i] = f(suf[i + 1], a[i]);
    }
    d[1] = {a[0].second, a[1].second};
    for (int i = 2; i < n; i++) {
        if (pref[i - 1].second + a[i].second < d[i - 1].first + d[i - 1].second) {
            d[i] = {pref[i - 1].second, a[i].second};
        } else {
            d[i] = {d[i - 1].first, min(d[i - 1].second, a[i].second)};
        }
    }
    for (int i = 0; i < n - 1; i++) {
        ans = max(ans, e(pref[i]) + e(suf[i + 1]));
        if (i) {
            ans = max(ans, e(f(pref[i - 1], suf[i + 1])) + e(a[i]));
            ans = max(ans, e({a[i].first, d[i].second}) + e({a[n - 1].first, min(d[i].first, suf[i + 1].second)}));
        }
    }
    cout << ans;
}

