    L--; R--;
    lines.emplace_back(L, R);
  }

  sort(begin(lines), end(lines),
       [](const pll& lhs, const pll& rhs) {
         if (lhs.first == rhs.first) {
           return lhs.second > rhs.second;
	 }
         return lhs.first < rhs.first;
       });

  // bottom to top
  vll bt(N);
  pll current;
  REP(i, N) {
    pll p = lines[i];
    if (i==0) {
      bt[i] = len(p);
      current = p;
      continue;
    }

    current = intersect(current, p);
    bt[i] = len(current);
  }

  // top to bottom
  vll tb(N);
  REPR(i, N) {
    pll p = lines[i];
    if (i==N-1) {
      tb[i] = len(p);
      current = p;
      continue;
    }

    current = intersect(current, p);
    tb[i] = len(current);
  }

//dumpContents(bt, "bt");
//dumpContents(tb, "tb");

  ll ret = 0;
  REP(i, N-1) {
    ll score = bt[i] + tb[i+1];
    chmax(ret, score);
  }

  cout << ret << endl;

  return 0;
}

