}

int findMax(set<pair<int, int> > &S)
{
    set<pair<int, int> > ::iterator it = S.end();
    it--;
    pair<int, int> p = *it;
    return p.first;
}

int findMin(set<pair<int, int> > &S)
{
    set<pair<int, int> > ::iterator it = S.begin();
    pair<int, int> p = *it;
    return p.first;
}

int calc()
{
    int ans = 0;
    for(int i=0; i<n; i++){
        int l = V[i].first, r = V[i].second;
        int cur = r-l+1;
        dlt(lft, l);
        dlt(rght, r);
        int maxs = findMax(lft);
        int mins = findMin(rght);
        if(maxs <= mins) cur += mins-maxs+1;
        ans = max(ans, cur);
        lft.insert(make_pair(l, i));
        rght.insert(make_pair(r, i));
    }
    return ans;
}

