using ll = long long;
using vi = vector<int>;
using vl = vector<ll>;
using Graph = vector<vi>;  // vi <=> vl
using vb = vector<bool>;
using boolGraph = vector<vb>;
using P = pair<int, int>;  // int <=> ll
const int MOD = 1e9+7;
const double EPS = 1e-9;

int main() {
  int n; cin >> n;
  Graph G(n, vi(2));
  rep(i,n) rep(j,2) cin >> G[i][j];

  sort(all(G));

  int a = 0, b = -1;
  int a_end = n - 1;
  bool zero = false;

  rep(i,n) {
    if (b == -1) {
      if (G[a][1] < G[i][0]) {
        b = i;
        a_end = i - 1;
      }
      else if (G[i][1] <= G[a][1]) {
        a = i;
      }
    }

    else {
      if (G[i][0] > G[b][1]) {
        zero = true;
        break;
      }
      else if (G[i][1] <= G[b][1]) {
        b = i;
      }
    }
  }

  int ans = 0;
  rep(i,n) ans = max(ans, G[i][1] - G[i][0] + 1);

  if (zero) {
    cout << ans << endl;
    return 0;
  }

  if (b == -1) {
    ans += G[a][1] - G[n-1][0] + 1;
  }

  Graph rest;
  int r = b == -1 ? n-1 : b;
  for (int i=a_end; i>=a; --i) {
    if (G[i][1] <= G[r][1]) rest.push_back(G[i]);
    if (G[i][1] < G[n-1][0]) break;
  }

  int b_right = G[r][1];
  rep(i,rest.size()) {
    ans = max(ans, (G[a][1] - rest[i][0] + 1) + (b_right - G[n-1][0] + 1));
    b_right = min(b_right, rest[i][1]);
  }

  cout << ans << endl;
  return 0;
}

