using namespace std;

void solve() {
  long N;
  cin >> N;
  vector<pair<long, long>> LR(N);

  long max_prob = 0;
  rep (i, N) {
    long l, r;
    cin >> l >> r;
    max_prob = max(max_prob, r - l + 1);
    LR[i] = make_pair(l, r);
  }
  sort(LR.begin(), LR.end());

  vector<long> minRmemo(N);
  vector<long> minRmemoRev(N);
  minRmemo[0] = LR[0].second;
  for (long i = 1; i < N; i++) {
    minRmemo[i] = min(minRmemo[i-1], LR[i].second);
  }
  minRmemoRev[N-1] = LR[N-1].second;
  for (long i = N - 2; i >= 0; i--) {
    minRmemoRev[i] = min(minRmemoRev[i+1], LR[i].second);
  }

  long split_ans = 0;
  for (long i = 0; i < N - 1; i++) {
    long foo = minRmemo[i] - LR[i].first + 1;
    if (foo < 0) foo = 0;

    long bar = minRmemoRev[i+1] - LR[N-1].first + 1;
    if (bar < 0) bar = 0;

    split_ans = max(split_ans, foo + bar);
  }

  long ans = max(max_prob, split_ans);
  // cout << "max_prob: " << max_prob << ", split_ans: " << split_ans << endl;
  cout << ans << endl;
}

int main(void) {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout.precision(12);
  solve();
  return 0;
}

