// doc: https://shibh308.github.io/library/library/lib/classes/segtree.cpp.html
template<typename T>
struct Segtree{
    int n;
    T op;
    vector<T> elm;
    function<T(T, T)> f;

    Segtree(int n, T init, function<T(T, T)> f, T op = T()) :
        n(n),
        op(op),
        elm(2 * n, init),
        f(f)
    {
        for(int i = n - 1; i >= 1; --i)
            elm[i] = f(elm[2 * i], elm[2 * i + 1]);
    }

    Segtree(int n, vector<T> init, function<T(T, T)> f, T op = T()) :
        n(n),
        op(op),
        elm(2 * n),
        f(f)
    {
        for(int i = 0; i < n; ++i)
            elm[i + n] = init[i];
        for(int i = n - 1; i >= 1; --i)
            elm[i] = f(elm[2 * i], elm[2 * i + 1]);
    }

    void set(int x, T val){
        x += n;
        elm[x] = val;
        while(x >>= 1)
            elm[x] = f(elm[2 * x], elm[2 * x + 1]);
    }

    void update(int x, T val){
        x += n;
        elm[x] = f(elm[x], val);
        while(x >>= 1)
            elm[x] = f(elm[2 * x], elm[2 * x + 1]);
    }

    T get(int x, int y) const{
        T l = op, r = op;
        for(x += n, y += n - 1; x <= y; x >>= 1, y >>= 1){
            if(x & 1)
                l = f(l, elm[x++]);
            if(!(y & 1))
                r = f(elm[y--], r);
        }
        return f(l, r);
    }
};


signed main(){
    int n;
    cin >> n;
    vector<i64> l(n), r(n);
    i64 ans = 0;
    vector<pair<int,int>> v;
    for(int i = 0; i < n; ++i){
        cin >> l[i] >> r[i];
        --l[i];
        chmax(ans, r[i] - l[i]);
        v.emplace_back(r[i], l[i]);
    }
    vector<i64> vx, vy;
    sort(v.begin(), v.end());
    for(int i = 0; i < n; ++i){
        vx.emplace_back(v[i].first);
        vy.emplace_back(v[i].second);
    }

    Segtree<i64> seg(n, vy, [](auto x, auto y){return max(x, y);}, -INF);
    Segtree<i64> seg2(n, vy, [](auto x, auto y){return min(x, y);}, INF);

    for(int i = 1; i < n; ++i){
        i64 r0 = v.front().first;
        i64 r1 = v[i].first;
        i64 l0 = seg.get(0, i);
        i64 l1 = seg.get(i, n);
        chmax(ans, r0 + r1 - l0 - l1);
        chmax(ans, r0 + r1 - max(l0, l1) - seg2.get(i, n));
    }
    cout << ans << endl;
}

