      fromR[i] = max(0LL, ((ll)minr-(ll)maxl+1LL));
    }
    ll ans_cand = 0LL;
    rep(i, N-1) ans_cand = max(ans_cand, (fromL[i]+fromR[i+1]));

    ans = ans_cand;

  }

  cout << ans << endl;


  return 0;
}

