int main() {

    ll N;
    cin >> N;

    vector<P> q(N), horyu;
    for (int i = 0; i < N; i++) {
        ll l, r;
        cin >> l >> r;
        q[i] = std::make_pair(l, r);
    }
    std::sort(q.begin(), q.end());
    P p1, p2;
    p1 = q[N-1];
    p2 = q[0];
    ll c1, c2;
    c1 = std::max(p1.second - p1.first + 1, 0LL);
    c2 = std::max(p2.second - p2.first + 1, 0LL);
    ll ans = c1 + c2;
    for (int i = 1; i < N-1; i++) {
        //cerr << "(" << p1.first << ", " << p1.second << ")" << ", " <<  "(" << p2.first << ", " << p2.second << ")" << endl;
        P p = q[i];
        ll scr1 = std::max(std::min(p1.second, p.second) - std::max(p1.first, p.first) + 1, 0LL);
        ll scr2 = std::max(std::min(p2.second, p.second) - std::max(p2.first, p.first) + 1, 0LL);
        if (c1 -scr1 == c2 - scr2) {
            horyu.push_back(p);
        } else if (c1 - scr1 > c2 - scr2) {
            p2.first = std::max(p2.first, p.first);
            p2.second = std::min(p2.second, p.second);
        } else {
            p1.first = std::max(p1.first, p.first);
            p1.second = std::min(p1.second, p.second);
        }
        c1 = std::max(p1.second - p1.first + 1, 0LL);
        c2 = std::max(p2.second - p2.first + 1, 0LL);
        ans = c1 + c2;
    }
    ll cnt = 0;
    while (!horyu.empty()) {
        P p = horyu.back();
        horyu.pop_back();
        ll scr1 = std::max(std::min(p1.second, p.second) - std::max(p1.first, p.first) + 1, 0LL);
        ll scr2 = std::max(std::min(p2.second, p.second) - std::max(p2.first, p.first) + 1, 0LL);
        if (c1 - scr1 > c2 - scr2) {
            p2.first = std::max(p2.first, p.first);
            p2.second = std::min(p2.second, p.second);
            cnt = 0;
        } else {
            p1.first = std::max(p1.first, p.first);
            p1.second = std::min(p1.second, p.second);
            cnt = 0;
        }
        c1 = std::max(p1.second - p1.first + 1, 0LL);
        c2 = std::max(p2.second - p2.first + 1, 0LL);
        ans = c1 + c2;
    }

    cout << ans << endl;

    return 0;
}

