pii pre[MAXN],suf[MAXN];
inline pii inter(pii x, pii y)
{
	if(x.fi>y.fi)
		swap(x,y);
	return x.se>=y.fi?mp(y.fi,min(x.se,y.se)):mp(-inf,-inf-1);
}

