	}
	pre[0] = suf[cnt+1] = mp(-inf,inf);
	for(int i = 1; i<=cnt; i++)
		pre[i] = inter(pre[i-1],c[i]);
	for(int i = cnt; i>=1; i--)
		suf[i] = inter(suf[i+1],c[i]);
	int ans = 0;
	for(int i = 1; i<cnt; i++)
