    dp[0]={{a[0].fi,a[0].se},a[0].se-a[0].fi+1};
    dp[1]={{a[1].fi,a[1].se},a[1].se-a[1].fi+1};
    fs(i,2,n)
    {
        res1=solve(dp[0].fi,a[i]);
        res2=solve(dp[1].fi,a[i]);
        sum1=dp[1].se+res1.se;
        sum2=dp[0].se+res2.se;
        //cout<<i<<" "<<sum1<<" "<<sum2<<endl;
        if(sum1>=sum2)
        {
            dp[0].se=res1.se;
            dp[0].fi=res1.fi;
        }
        else
        {
            dp[1].se=res2.se;
            dp[1].fi=res2.fi;
        }
    }
    cout<<dp[0].se+dp[1].se;
    return 0;
}

