    cout << calc(l_, r_) + 2 * max(minr - maxl, 0ll) << endl;
  }
  LL calc(vector<LL> l, vector<LL> r) {
    LL ret = 0;
    for (int i = 0; i < n; ++i) {
      ret = max(ret, r[i] - l[i]);
    }
    vector<LL> LR;
    for (int i = 0; i < n; ++i) {
      LR.push_back(l[i]);
      LR.push_back(r[i]);
    }
    sort(LR.begin(), LR.end());
    LR.erase(unique(LR.begin(), LR.end()), LR.end());
    for (int i = 0; i < n; ++i) {
      l[i] = distance(LR.begin(), lower_bound(LR.begin(), LR.end(), l[i]));
      r[i] = distance(LR.begin(), lower_bound(LR.begin(), LR.end(), r[i]));
    }
    LL maxlid = distance(l.begin(), max_element(l.begin(), l.end()));
    LL minrid = distance(r.begin(), min_element(r.begin(), r.end()));

    LL ll = l[minrid];
    LL lr = r[minrid];
    LL rl = l[maxlid];
    LL rr = r[maxlid];

    vector<LL> dp(LR.size());
    for (int i = ll; i <= lr; ++i) {
      dp[i] = rr;
    }

    for (int i = 0; i < n; ++i) {
      if (l[i] < r[minrid] && r[i] > l[maxlid]) {
        dp[l[i]] = min(dp[l[i]], r[i]);
      } else if (r[i] <= l[maxlid]) {
        ll = max(ll, l[i]);
        lr = min(lr, r[i]);
      } else {
        rl = max(rl, l[i]);
        rr = min(rr, r[i]);
      }
    }
    for (int i = r[minrid] - 1; i >= l[minrid]; --i) {
      dp[i] = min(dp[i], dp[i + 1]);
    }
    LL ret2 = 0;
    for (int i = l[minrid]; i < r[minrid]; ++i) {
      LL tll = ll;
      LL tlr = lr;
      LL trl = rl;
      LL trr = rr;
      tll = max(tll, (LL)i);
      trr = min(trr, dp[i + 1]);
      LL tmp = LR[trr] - LR[trl] + LR[tlr] - LR[tll];
      ret2 = max(ret2, tmp);
    }
    return max(ret, ret2);
  }
};

