struct Segment {
    int l, r;
    Segment (int _l, int _r) {
        l = _l;
        r = _r;
    }
    int len() {
        return r - l + 1;
    }
    int with(Segment other) {
        int start = max(l, other.l);
        int end = min(r, other.r);
        return max(0, end - start + 1);
    }
    bool operator < (Segment other) {
        return len() > other.len();
//        return l < other.l || (l == other.l && r > other.r);
    }
    Segment merge(Segment other) {
        l = max(l, other.l);
        r = min(r, other.r);
    }
};

