void init() {
    sort(segs.begin(), segs.end());
}

void solve() {
    Segment contest_one = segs[0];
    Segment contest_two = segs[1];
    for (int i = 2; i < n; i++) {
        Segment current_segment = segs[i];
        int merge_into_one = contest_one.with(current_segment) + contest_two.len();
        int merge_into_two = contest_two.with(current_segment) + contest_one.len();
        int merge_two_into_one = contest_one.with(contest_two) + current_segment.len();
        int mx = max(merge_into_one, max(merge_into_two, merge_two_into_one));
        if (merge_into_one == mx) {
            contest_one.merge(current_segment);
        } else {
            if (merge_into_two == mx) {
                contest_two.merge(current_segment);
            } else {
                contest_one.merge(contest_two);
                contest_two = current_segment;
            }
        }
    }
    res = contest_one.len() + contest_two.len();
}

void get_result() {
    cout << res;
}

