#include<bits/stdc++.h>
using namespace std;

int n, ans, tmin[100005<<2];
struct seg {
	int l, r;
} s[100005];

bool cmp(seg a, seg b) { return a.l > b.l; }

int query(int o, int l, int r, int x, int y) {
	int res = 1e9;
	if(x <= l && r <= y) 
		return tmin[o];
	int mid = (l + r)>>1;
	if(mid >= x) res = min(res, query(o<<1, l, mid, x, y));
	if(mid < y) res = min(res, query(o<<1|1, mid + 1, r, x, y));
	return res;
}

void Build(int o, int l, int r) {
	if(l == r) {
		tmin[o] = s[l].r;
		return;
	}
	int mid = (l + r)>>1;
	Build(o<<1, l, mid);
	Build(o<<1|1, mid + 1, r);
	tmin[o] = min(tmin[o<<1], tmin[o<<1|1]);
	return;
}

void update(int o, int l, int r, int x, int val) {
	if(l == r) {
		tmin[o] = val;
		return;
	}
	int mid = (l + r)>>1;
	if(mid >= x) update(o<<1, l, mid, x, val);
	else update(o<<1|1, mid + 1, r, x, val);
	tmin[o] = min(tmin[o<<1], tmin[o<<1|1]);
	return;
}

int main() {
	cin>>n;
	for(int i = 1; i <= n; i++) 
		scanf("%d%d", &s[i].l, &s[i].r);
	sort(s + 1, s + n + 1, cmp);
	int ver = s[1].r;
	Build(1, 1, n);
	for(int i = 1; i < n; i++) {
		ver = min(ver, s[i].r);
		ans = max(ans, max(0, ver - s[1].l + 1) + max(0, query(1, 1, n, i + 1, n) - s[i + 1].l + 1));
	}
	for(int i = 1; i <= n; i++) {
		update(1, 1, n, i, 1e9);
		ans = max(ans, s[i].r - s[i].l + 1 + max(0, query(1, 1, n, 1, n) - ((i == 1) ? s[2].l : s[1].l) + 1));
		update(1, 1, n, i, s[i].r);
	} 
	cout<<ans<<endl;
}

