int main() {
    int N; cin >> N;
    vector<ll> L(N),R(N);
    for(int i = 0;i < N; ++i) cin >> L[i] >> R[i];

	// //一点更新 + 区間最小
	function<ll(ll,ll)> funcMin =  [&](ll a,ll b){return min(a,b);};
	function<ll(ll,ll)> funcMax =  [&](ll a,ll b){return max(a,b);};
	function<ll(ll,ll)> funcMerge = [&](ll a,ll b){return b;};
    SegmentTree<ll> SegL(N,-1,funcMax,funcMerge);
    SegmentTree<ll> SegR(N,LOWINF,funcMin,funcMerge);

    for(int i = 0; i < N; ++i) {
        SegL.update(i,L[i]);
        SegR.update(i,R[i]);
    }

    priority_queue<P<ll,int>> pq,pq2;
    for(int i = 0; i < N; ++i) {
        pq.push({-L[i],i+N});
        pq.push({-R[i],i});
    }

    ll ans = 0;
    for(int i = 0; i < N; ++i) chmax(ans,R[i]-L[i]+1);

    int cnt = N;
    vector<int> live(N,0);
    while(pq.size()){
        auto e = pq.top();
        int i = e.second;
        pq.pop();
        if(i>=N){
            i -= N;
            pq2.push({L[i],i});
            SegL.update(i,-1);
            SegR.update(i,LOWINF);
            cnt--;
            live[i] = 1;
        }
        else{
            if(live[i]==0){
                pq2.push({L[i],i});
                SegL.update(i,-1);
                SegR.update(i,LOWINF);
                cnt--;
                live[i] = 1;
            }
            while(pq2.size() && live[i]){
                auto e2 = pq2.top();
                int j = e2.second;
                pq2.pop();
                ll x = R[i]-L[j]+1;
                ll y = SegR.get(0,N)-SegL.get(0,N)+1;
                if(cnt) chmax(ans,x+y);
                SegL.update(j,L[j]);
                SegR.update(j,R[j]);
                cnt++;
                live[j] = 0;
            }

        }
    }
    cout << ans << endl;

}

