ll N;
ll L[100010], R[100010];
ll maL, miR = INF;
ll li, ri;
std::vector<P> ps;
ll right[100010];

int main()
{
  std::cin >> N;

  rep( i, N )
  {
    std::cin >> L[i] >> R[i];

    if( chmax( maL, L[i] ) )
      li = i;
    if( chmin( miR, R[i] ) )
      ri = i;

    ps.emplace_back( L[i], R[i] );
  }

  ll ans = 0;

  if( miR >= maL )
  {
    rep( i, N ) if( i != li && i != ri )
      chmax( ans, R[i]-L[i]+1 );

    ans += miR-maL+1;
  }

  if( li == ri )
  {
    std::cout << ans << std::endl;

    return 0;
  }

  std::sort( all(ps) );

  right[N] = INF;

  repd( i, N )
  {
    if( ps[i] == P( L[ri], R[ri] ) )
      right[i] = right[i+1];
    else
      right[i] = std::min( right[i+1], ps[i].second );
  }

  ll l = L[ri];
  ll r = R[li];

  rep( i, N )
  {
    chmax( ans, miR-l+1+std::min(right[i],r)-maL+1 );

    if( ps[i] != P( L[li], R[li] ) )
      chmax( l, ps[i].first );
  }

  std::cout << ans << std::endl;

  return 0;
}

