        }
        sort(all(LR));

        map<Int, Int> fL, fR, sL, sR;
        for (int i = 0; i < N; ++i) {
            fL[LR[i].first]++;
            fR[LR[i].second]++;
        }

        Int ans = 0;
        Int lR, lL; // lRは右の最大値(左サイドになる), lLは左の最小値(右サイドになる)
        {
