            ans = max(0ll, itR->first - itL->first);
//            if (ans > 0) {
//                lR = itL->first;
//                lL = itR->first;
//            }
        }
        //区間スケジューリング



        int idx = 0;
        for (auto e : appL) {
            while (idx < LR.size() && LR[idx].first == e) {
                Int l = LR[idx].first;
                Int r = LR[idx].second;
                idx++;
                fL[l]--;
                if (fL[l] == 0) fL.erase(l);
                fR[r]--;
                if (fR[r] == 0) fR.erase(r);

                sL[l]++;
                sR[r]++;


                if (fL.size()) {
                    auto itFL = fL.end();
                    itFL--;
                    auto itFR = fR.begin();

                    auto itSL = sL.end();
                    itSL--;
                    auto itSR = sR.begin();

                    Int fval = max(0ll, itFR->first - itFL->first + 1);
                    Int sval = max(0ll, itSR->first - itSL->first + 1);

                    Int tmp = fval + sval;
//                    cerr << tmp << endl;
                    chmax(ans, tmp);
                }
            }
        }

        map<Int, Int> tL, tR; //のこりもの
        for (int i = 0; i < N; ++i) {
            tL[LR[i].first]++;
            tR[LR[i].second]++;
        }

        for (int i = 0; i < N; ++i) {
            //del
            Int l = LR[i].first;
            Int r = LR[i].second;
            tL[l]--;
            if (tL[l] == 0) tL.erase(l);
            tR[r]--;
            if (tR[r] == 0) tR.erase(r);

            Int ftmp = r - l + 1;

            auto itL = tL.end();
            itL--;
            auto itR = tR.begin();
            Int stmp = max(0ll, itR->first - itL->first + 1);

            Int tmp = ftmp + stmp;
            chmax(ans, tmp);

            tL[l]++;
            tR[r]++;
        }

        cout << ans << endl;


    }

};


