using namespace std;
using ll =  long long;
using ld = long double;

int la = 0, ra = MOD;

bool ch (pair<int, int> p1, pair<int, int> p2) {
	if (max (p1.second - la + 1, 0) != max (p2.second - la + 1, 0)) {
		return max (p1.second - la + 1, 0) < max (p2.second - la + 1, 0);
	}
	return max (ra - p1.first + 1, 0) > max (ra - p2.first + 1, 0);
}

int main () {
	int n;
	cin >> n;
	int mal = 0, mir = 0;
	vector<pair<int, int>> vp;
	int ans = 0;
	for (int i = 0; i < n; i++) {
		int l, r;
		cin >> l >> r;
		la = max (l, la);
		ra = min (r, ra);
		vp.push_back (make_pair (l, r));
		ans = max (ans, r - l + 1);
		if (i && l > vp[i].first) {
			mal = i;
		}
		if (i && r < vp[i].second) {
			mir = i;
		}
	}
	sort (vp.begin (), vp.end (), ch);
	int ar[n] = {}, br[n] = {}, l = 1, r = INF;
	for (int i = 0; i < n; i++) {
		l = max (vp[i].first, l), r = min (vp[i].second, r);
		ar[i] = r - l + 1;
		if (ar[i] <= 0) {
			ar[i] = 0;
			break;
		}
	}
	l = 1, r = INF;
	for (int i = n - 1; i >= 0; i--) {
		l = max (vp[i].first, l), r = min (vp[i].second, r);
		br[i] = r - l + 1;
		if (br[i] <= 0) {
			br[i] = 0;
			break;
		}
	}
	for (int i = 0; i < n - 1; i++) {
		ans = max (ans, ar[i] + br[i + 1]);
	}
	cout << ans << "\n";
}

