    for (int i = 0; i < n; i += 1) {
        cin >> l[i] >> r[i];
        if (r[i] - l[i] + 1 > maxx) {
            maxx = r[i] - l[i] + 1;
        }
        v[i] = make_pair(l[i], r[i]);
    }

    if (n == 1) {
        cout << maxx << "\n";
        return 0;
    }

    int min_r = *min_element(r.begin(), r.end());
    int max_l = *max_element(l.begin(), l.end());

    auto w = v;

    for (int i = 0; i < n; i += 1)
        if(w[i].second - w[i].first + 1 == maxx) {
            w.erase(w.begin() + i);
            break;
        }

    int temp_first = 0, temp_right = numeric_limits<int>::max();

    for (auto temp : w) {
        temp_right = min(temp_right, temp.second);
        temp_first = max(temp_first, temp.first);
    }

    int ans = maxx + max(temp_right - temp_first + 1, 0);

    int who = -1;
    vector<int> taken(n, 0);
    int best_l_for_r = numeric_limits<int>::max(), best_r_for_l = -1;

    for (int i = 0; i < n; i += 1) {
        if (r[i] == min_r and l[i] < best_l_for_r) {
            best_l_for_r = l[i];
            who = i;
        }
    }


    taken[who] = 1;
    who = -1;

    for (int i = 0; i < n; i += 1) {
        if (not taken[i] and l[i] == max_l and r[i] > best_r_for_l) {
            best_r_for_l = r[i];
            who = i;
        }
    }

    if (who == -1) {
        cout << ans << "\n";
        return 0;
    }

    taken[who] = 1;

    vector<int> p(n, 0);
    for (int i = 0; i < n; i += 1)
        p[i] = i;

    sort(p.begin(), p.end(), [&] (int a, int b) {
        return v[a] < v[b];
    });


    int smallest = numeric_limits<int>::max();

    for (int ii = n - 1; ii >= 0; ii -= 1) {
        int i = p[ii];

        if (taken[i])
            continue;

        int left = max(v[i].first, best_l_for_r);
        int right = min(best_r_for_l, smallest);

        ans = max(ans, max(0, (min_r - left + 1)) + max(0, (right - max_l + 1)));
        smallest = min(smallest, v[i].second);
    }

    ans = max(ans, max(0, min_r - best_l_for_r) + max(0, min(best_r_for_l, smallest) - max_l + 1));

    cout << ans << "\n";
