    int n;
    cin>>n;
    int maxi = -1;
    for(int i = 1; i <= n; i++){
        cin>>a[i].first>>a[i].second;
        maxi = max(a[i].second-a[i].first, maxi);
    }
    sort(a+1, a+1+n);
    int L1=a[1].first, R1=a[1].second;
    int L2=a[n].first, R2=a[n].second;
    vec1.emplace_back(a[1]);
    vec2.emplace_back(a[n]);
    for(int i = 2; i <= n-1; i++){
        int x1 = min(R1, a[i].second)-max(L1, a[i].first);
        int x2 = min(R2, a[i].second)-max(L2, a[i].first);
        R1 = min(R1, a[i].second);
        L1 = max(L1, a[i].first);
        R2 = min(R2, a[i].second);
        L2 = max(L2, a[i].first);
        if(x1 > x2){
            vec2.emplace_back(a[i]);
        }else{
            vec1.emplace_back(a[i]);
        }
    }
    int l1 = -1, r1 = inf;
    for(auto it : vec1){
        l1=max(l1, it.first);
        r1=min(r1, it.second);
    }
    int l2 = -1, r2 = inf;
    for(auto it : vec2){
        l2 = max(l2, it.first);
        r2 = min(r2, it.second);
    }
    int ans =  0;
    if(l1 <= r1)ans += r1-l1+1;
    if(l2 <= r2)ans += r2-l2+1;
