ll mmin(ll a, ll b) {
  return a < b ? a : b;
}

int main(void) {
  ll i, j, k, n, ans = 0, t;
  scanf("%lld", &n);
  pair<ll, ll> a[n];
  for(i = 0; i < n; ++i) scanf("%lld%lld", &a[i].first, &a[i].second), a[i].first--;
  sort(a, a + n);
  ll f[n], l[n];
  f[0] = a[0].second, l[n - 1] = a[n - 1].second;
  for(i = 1; i < n; ++i) f[i] = mmin(f[i - 1], a[i].second);
  for(i = n - 1; i; --i) l[i - 1] = mmin(l[i], a[i - 1].second);
  for(i = 1; i < n; ++i) {
    t = -mmin(a[i - 1].first - f[i - 1], 0) - mmin(a[n - 1].first - l[i], 0);
