using namespace std;
typedef long long ll;

struct range {
    ll mi;
    ll ma;

    bool operator<(const range &another) const {
        if (mi != another.mi) return mi < another.mi;
        return ma < another.ma;
    };
};

int main() {
    int n;
    cin >> n;
    vector<range> v(n);
    for (int i = 0; i < n; i++) cin >> v[i].mi >> v[i].ma;
    sort(v.begin(), v.end());

    vector<range> dp1(n + 1, {-1, 1145141919810});
    for (int i = 1; i <= n; i++) {
        dp1[i].mi = max(dp1[i - 1].mi, v[i - 1].mi);
        dp1[i].ma = min(dp1[i - 1].ma, v[i - 1].ma);
    }
    vector<range> dp2(n + 1, {-1, 1145141919810});
    for (int i = n - 1; i >= 0; i--) {
        dp2[i].mi = max(dp2[i + 1].mi, v[i].mi);
        dp2[i].ma = min(dp2[i + 1].ma, v[i].ma);
    }

    ll ret = 0;
    for (int i = 0; i <= n; i++) {
        ll now = 0;
        if (i != 0)now += max((ll) 0, (dp1[i].ma - dp1[i].mi + 1));
        if (i != n)now += max((ll) 0, (dp2[i].ma - dp2[i].mi + 1));
        ret = max(ret, now);
    }
    cout << ret << endl;
    return 0;
}

