void init_io() { std::cin.tie(nullptr); std::ios::sync_with_stdio(false); std::cout << std::fixed << std::setprecision(15); }

using namespace std;
using ll = long long;

int main() { init_io();
  int N; cin >> N;
  vector<pair<int, int>> LR(N);
  rep(i, N) {
    cin >> LR[i].first >> LR[i].second;
  }
  sort(range(LR));
  vector<int> L(N), R(N);
  rep(i, N) {
    L[i] = LR[i].first;
    R[i] = LR[i].second;
  }
  const int INF = 1e9;
  vector<int> prefL(N + 1, -INF);
  vector<int> prefR(N + 1, INF);
  vector<int> suffL(N + 1, -INF);
  vector<int> suffR(N + 1, INF);
  rep(i, N) {
    prefL[i + 1] = max(prefL[i], L[i]);
    prefR[i + 1] = min(prefR[i], R[i]);
  }
  repr(i, N) {
    suffL[i] = max(suffL[i + 1], L[i]);
    suffR[i] = min(suffR[i + 1], R[i]);
  }
  int ans = 0;
  rep(i, N) {
    int cnt = 0;
    cnt += R[i] - L[i] + 1;
    int l = max(prefL[i], suffR[i + 1]);
    int r = min(prefR[i], prefR[i + 1]);
    cnt += max(0, r - l + 1);
    ans = max(ans, cnt);
  }
  repe(i, 1, N) {
    int cnt = 0;
    cnt += max(0, prefR[i] - prefL[i] + 1);
    cnt += max(0, suffR[i] - suffL[i] + 1);
    ans = max(ans, cnt);
  }
  cout << ans << endl;
}

