      mp.erase(val[i].second);
    }
    ri = mp.begin()->first;
    le = val[n-1].first;
    tmp = max((ll)0,ri-le);

    ri = min_r;
    le = val[i].first;
    tmp += max((ll)0,ri-le);
    ans = max(ans,tmp);
  }
  cout << max(ans,max_a)<<endl;
}

