using namespace std;
typedef long long ll;
typedef pair<ll,ll> P;

class segtree{
public:
	static const int N=1<<19;
	int dp[1<<20];
	int sz[1<<20];
	int lazy[1<<20];
	segtree(){
		memset(dp,0,sizeof(dp));
	}
	void update(int k,int v){
		k+=N-1;
		sz[k]+=v;
		while(k>0){
			k=(k-1)/2;
			dp[k]=max(dp[k*2+1],dp[k*2+2]);
			sz[k]=sz[k*2+1]+sz[k*2+2];
		}
	}

	void lazy_eval(int k){
		dp[k]+=lazy[k];
		if(k<N-1){
			lazy[k*2+1]+=lazy[k];
			lazy[k*2+2]+=lazy[k];
		}
		lazy[k]=0;
	}

	void lazy_upd(int k){
		dp[k]=max(dp[k*2+1],dp[k*2+2]);
		sz[k]=0;
		if(dp[k]==dp[k*2+1]){
			sz[k]+=sz[k*2+1];
		}
		if(dp[k]==dp[k*2+2]){
			sz[k]+=sz[k*2+2];
		}
	}

	void add(int a,int b,int v,int k=0,int l=0,int r=N){
		lazy_eval(k);
		if(b<=l || r<=a)return;
		if(a<=l && r<=b){
			lazy[k]+=v;
			lazy_eval(k);
			return;
		}
		int mid=(l+r)/2;
		add(a,b,v,k*2+1,l,mid);
		add(a,b,v,k*2+2,mid,r);
		lazy_upd(k);
	}

	P query(int a,int b,int k=0,int l=0,int r=N){
		lazy_eval(k);
		if(b<=l || r<=a)return P(0,0);
		if(a<=l && r<=b)return P(dp[k],sz[k]);
		int mid=(l+r)/2;
		P vl=query(a,b,k*2+1,l,mid);
		P vr=query(a,b,k*2+2,mid,r);
		lazy_upd(k);
		return max(vl,vr);
	}
};

