typedef pair <int, int> pii;

bool solve() {
  int n;
  if (scanf("%d", &n) != 1) { return false; }

  vector<pii> a(n);
  for (int i = 0; i < n; ++i) {
    scanf("%d%d", &a[i].first, &a[i].second);
  }

  sort(a.begin(), a.end(), [](pii x, pii y) {
    if (x.second != y.second) {
      return x.second < y.second;
    }
    return x.first > y.first;
  });

  vector<pii> pref(n);
  pref[0] = a[0];
  for (int i = 1; i < n; ++i) {
    pref[i].first = max(pref[i - 1].first, a[i].first);
    pref[i].second = min(pref[i - 1].second, a[i].second);
  }

  vector<pii> suff(n);
  suff[n - 1] = a[n - 1];
  for (int i = n - 2; i >= 0; --i) {
    suff[i].first = max(suff[i + 1].first, a[i].first);
    suff[i].second = min(suff[i + 1].second, a[i].second);
  }

  for (int i = 0; i < n; ++i) {
    dbg("%d %d %d %d %d %d\n", a[i].first, a[i].second, pref[i].first, pref[i].second, suff[i].first, suff[i].second);
  }

  int ans = 0;
  for (int i = 0; i < n - 1; ++i) {
    int cur = max(0, pref[i].second - pref[i].first + 1) + max(0, suff[i + 1].second - suff[i + 1].first + 1);
    dbg("i %d cur %d\n", i, cur);
    ans = max(ans, cur);
  }
  printf("%d\n", ans);

  return true;
}

int main() {
  int tt = -1;
  //scanf("%d", &tt);
  while (tt-- && solve());
  return 0;
}

