int binpow(int a, int s) { 
    int res = 1;
    while (s) {
        if (s % 2) {
            res = 1ll * res * a % base;
        }
        a = 1ll * a * a % base;
        s /= 2;
    }
    return res;
}


struct KMin {
    int col1, col2;
    int val1, val2;

    KMin(){ 
        val1 = val2 = inf;
        col1 = col2 = -1;
    }

    void add(int v, int c) {
        if (v < val1) {
            swap(val1, val2);
            swap(col1, col2);
            swap(col1, c);
            swap(val1, v);
        } else if (v < val2) {
            swap(val2, v);
            swap(col2, c);
        }
    }

    void clear() {
        val1 = val2 = inf;
        col1 = col2 = -1;
    }

    void add(KMin other) {
        if (other.val1 < val1) {
            swap(val1, val2);
            swap(col1, col2);
            swap(val1, other.val1);
            swap(col1, other.col1);
        } else if (other.val1 < val2) {
            swap(val2, other.val1);
            swap(col2, other.col1);
        }
        if (other.val2 < val2) {
            swap(val2, other.val2);
            swap(col2, other.col2);
        }
    }

    int get(int c) {
        return c == col1 ? val2 : val1;
    }
};

