const int MAXN=100000;
struct Z { int l,r; };
bool operator<(const Z &a,const Z &b) { return a.l<b.l; }

int n;
Z z[MAXN];

int pref[MAXN+1];
int suff[MAXN+1];

ll solve() {
	ll ret=0;
	REP(i,n) ret=max(ret,(ll)z[i].r-z[i].l+1);
	int rmn=z[0].r; REP(i,n) rmn=min(rmn,z[i].r);
	int lmx=z[0].l; REP(i,n) lmx=max(lmx,z[i].l);
	if(lmx<=rmn) REP(i,n) ret=max(ret,(ll)rmn-lmx+1+z[i].r-z[i].l+1);
	sort(z,z+n);
	pref[0]=INT_MIN; REP(i,n) pref[i+1]=max(pref[i],z[i].l);
	suff[n]=INT_MAX; for(int i=n-1;i>=0;--i) suff[i]=min(suff[i+1],z[i].r);
	FORE(i,1,n-1) if(pref[i]<=rmn&&suff[i]>=lmx) {
		ll cur=(ll)(rmn-pref[i]+1)+(ll)(suff[i]-lmx+1);
		ret=max(ret,cur);
	}
	return ret;
}

