    vector<pair<ll, ll>> section(N);
    Rep (i, N) {
        ll L, R;
        cin >> L >> R;
        L--;
        section[i] = {L, R};
    }

    sort(section.begin(), section.end());

    SegTree<ll> st1(N, -inf, [](ll a, ll b){return max(a, b);}, [](ll a, ll b){return b;});
    SegTree<ll> st2(N, inf, [](ll a, ll b){return min(a, b);}, [](ll a, ll b){return b;});

    Rep (i, N) {
        st1.change(i, section[i].first);
        st2.change(i, section[i].second);
    }

    ll ans = 0;
    Rep (i, N) {
        ll tmp = section[i].second - section[i].first;
        tmp += max<ll>(0, min(st2.query(0, i), st2.query(i+1, N)) - max(st1.query(0, i), st1.query(i+1, N)));
        chmax(ans, tmp);

        if (i < N-1) {
            tmp = max<ll>(0, st2.query(0, i+1) - st1.query(0, i+1));
            tmp += max<ll>(0, st2.query(i+1, N) - st1.query(i+1, N));
            chmax(ans, tmp);
        }
    }

    cout << ans << endl;
}

