			b[i].first = max(b[i + 1].first, p[i].first);
			b[i].second = p[i].second;
		}
	}
	int ans = 0;
	rep(i, n - 1) {
		ans = max(ans, max((int)0, a[i].second - a[i].first + 1) + max((int)0, (b[i + 1].second - b[i + 1].first + 1)));
	}
	rep(i, n) {
		ans = max(ans, max((int)0, p[i].second - p[i].first + 1));
		if (0 < i && i < n - 1) {
			ans = max(ans, max((int)0, p[i].second - p[i].first + 1) + max((int)0, a[i - 1].second - max(a[i - 1].first, b[i + 1].first) + 1));
		}
		if (i == 0)ans = max(ans, max((int)0, p[i].second - p[i].first + 1) + max((int)0, b[i + 1].second - b[i + 1].first + 1));
		if (i == n - 1)ans = max(ans, max((int)0, p[i].second - p[i].first + 1) + max((int)0, a[i - 1].second - a[i - 1].first + 1));
	}
	cout << ans << endl;
	return 0;
}

