void solve()
{
    ll N;
    in(N);
    vpll A(N);
    for1 (i, N) {
        ll l, r, len;
        in(l, r);
        r++;
        A[i] = make_pair(l, r);
    }

    ll loR = INF;
    for1 (i, N) {
        chmin(loR, A[i].second);
    }

    ll hiL = -INF;
    for1 (i, N) {
        chmax(hiL, A[i].first);
    }

    ll hiLen = -INF;
    for1 (i, N) {
        chmax(hiLen, A[i].second - A[i].first);
    }

    ll ans = 0;
    if (hiL < loR) {
        ans = loR - hiL + hiLen;
    }

    sort(all(A));
    vll cR(N + 1);
    cR[N] = INF;
    rfor2 (i, N - 1, -1) {
        cR[i] = min(cR[i + 1], A[i].second);
    }
    dump(hiL, loR);
