    for1 (i, N - 1) {
        // 1つめの左端をA[i].first だとする
        ll a1 = max(loR - A[i].first, 0LL);
        ll a2 = max(cR[i + 1] - hiL, 0LL);
        ll a = a1 + a2;
        dump(i, a, a1, a2);
        chmax(ans, a);
    }
    print(ans);
}

