int main() {
	int n; std::cin >> n;
	std::vector<std::pair<int, int>> segments(n);
	for (auto& p : segments) std::cin >> p.first >> p.second;
	std::sort(segments.begin(), segments.end(), [](const std::pair<int, int> a, const std::pair<int, int> b) {return a.first == b.first ? a.second < b.second : a.first < b.first; });
	const int min_right = std::min_element(segments.begin(), segments.end(), [](const std::pair<int, int> a, const std::pair<int, int> b) {return a.second < b.second; })->second;
	const int max_left = std::max_element(segments.begin(), segments.end(), [](const std::pair<int, int> a, const std::pair<int, int> b) { return a.first < b.first; })->first;
	std::vector<int> right_min; std::transform(std::next(segments.begin()), segments.end(), std::back_inserter(right_min), [](const std::pair<int, int> a) {return a.second; });
	for (auto i = 2; i <= right_min.size(); ++i) right_min[right_min.size() - i] = std::min(right_min[right_min.size() - i], right_min[right_min.size() - i + 1]);
	const auto max_segment = std::max_element(segments.begin(), segments.end(), [](const std::pair<int, int> a, const std::pair<int, int> b) {return a.second - a.first < b.second - b.first; });
	long long int max_score = max_segment->second - max_segment->first + 1 + std::max(min_right - max_left + 1, 0);
	for (auto i = 0; i + 1 < n; ++i) {
		long long int score = std::max(min_right - segments[i].first + 1, 0) + std::max(right_min[i] - max_left + 1, 0);
		max_score = std::max(max_score, score);
	}
	std::cout << max_score << '\n';
}

