const int MAXcomb = 200010;
ll fac[MAXcomb], finv[MAXcomb], inv[MAXcomb];
//facはn!,finvは1/n!
//invは逆元
void COMinit(){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(int i = 2; i < MAXcomb; i++){
        fac[i] = fac[i-1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;
        finv[i] = finv[i-1] * inv[i] % MOD;
    }
}
ll comb(int n, int k){
    if(n < k) return 0;
    if(n < 0 || k < 0) return 0;
    return fac[n] * finv[k] % MOD * finv[n-k] % MOD;
}


ll solve2(vector<pair<ll, ll>> LR){
  ll M = 0, mid = -1;
  rep(i, LR.size()){
    if(M < LR[i].s - LR[i].f + 1){
      M = LR[i].s - LR[i].f + 1;
      mid = i;
    }
  }
  ll left = -INFL, right = INFL;
  rep(i, LR.size()){
    if(i == mid) continue;
    left = max(left, LR[i].f);
    right = min(right, LR[i].s);
  }
  return M + max(0LL, right - left + 1);
}

