#define rep(i,a,b) for(ll i=a;i<b;i++)
#define rrep(i,a,b) for(ll i=a-1;i>=b;i--)

int main() {
	struct Task {
		ll L;
		ll R;
		static Task intersect(Task lhs, Task rhs) {
			return Task{max(lhs.L, rhs.L), min(lhs.R, rhs.R)};
		}
		static Task whole() {
			return Task{0, numeric_limits<ll>::max()};
		}
		ll len() {
			return max((ll)0, R-L);
		}
	};
	ll N;
	cin >> N;
	vector<Task> tasks(N);
	rep(i,0,N) {
		cin >> tasks[i].L;
		cin >> tasks[i].R;
		tasks[i].R++;
	}
	ll ans = 0;
	sort(tasks.begin(), tasks.end(), [](Task lhs, Task rhs){
		return lhs.L < rhs.L;
	});
	vector<Task> int_l(N+1, Task::whole());
	vector<Task> int_r(N+1, Task::whole());
	rep(i,0,N) {
		int_l[i+1] = Task::intersect(int_l[i], tasks[i]);
		int_r[i+1] = Task::intersect(int_r[i], tasks[N-1-i]);
	}
	rep(i,0,N) {
		ans = max(ans, tasks[i].len()
				+ Task::intersect(int_l[i], int_r[N-(i+1)]).len());
	}
	vector<Task> reduced;
	rep(i,0,N) {
		if (reduced.empty() || reduced.back().R < tasks[i].R) {
			reduced.push_back(tasks[i]);
		} else {
			reduced.pop_back();
		}
	}
	ll M = reduced.size();
	vector<Task> int_l_red(M+1, Task::whole());
	vector<Task> int_r_red(M+1, Task::whole());
	rep(i,0,M) {
		int_l_red[i+1] = Task::intersect(int_l_red[i], reduced[i]);
		int_r_red[i+1] = Task::intersect(int_r_red[i], reduced[M-1-i]);
	}
	rep(i,1,M) {
		ans = max(ans, int_l_red[i].len() + int_r_red[M-i].len());
	}
	cout << ans << endl;
}

