    REP(i,1,n) {
        int tmp = 0;
        {
            int l = lru[i-1].first, r = lru[i-1].second;
            tmp += max(0, r - l + 1);
        }
        {
            int l = rru[i].first, r = rru[i].second;
            tmp += max(0, r - l + 1);
        }
        ans = max(ans, tmp);
    }
    return ans;
}

