    int l = L[k], r = R[k];
    int ans = r - l + max(-1,right.begin()->first - left.rbegin()->first) + 2;
    int maxl = 0;
    while (left.size() > 1) {
        int val,num;
        tie(val,num) = *left.begin();
        left.erase(left.begin());
        right.erase({R[num],num});
        chmax(l,val);
        chmax(ans,max(-1,r-l) + max(-1,right.begin()->first - left.rbegin()->first) + 2);
        chmax(maxl,R[num]-L[num]);
    }
    chmax(l,left.begin()->first);
    chmax(ans,max(-1,r-l) + maxl + 2);

    cout << ans << endl;
}

