int main(){

	int N;
	cin>>N;

	vector<pair<int,int>> P(N);

	for(int i=0;i<N;i++){
		cin>>P[i].first>>P[i].second;
	}

	int Rmin = Inf;

	for(int i=0;i<N;i++){
		if(P[i].second<Rmin){
			Rmin=P[i].second;
		}
	}

	int Lmin = Inf;
	int ind = 0;

	for(int i=0;i<N;i++){
		if(P[i].second!=Rmin)continue;
		if(P[i].first<Lmin){
			Lmin=P[i].first;
			ind = i;
		}
	}

	P.erase(P.begin()+ind);
	int Lmax = Lmin;
	sort(P.begin(),P.end());

	vector<int> L(N-1),R(N-1);
	for(int i=0;i<N-1;i++){
		L[i]=P[i].first;
		R[i]=P[i].second;
	}

	segtreemax<int> segmax(L);
	segtreemin<int> segmin(R);

	int ans = 0;

	for(int i=0;i<N-1;i++){
		int a = Rmin - Lmax + 1;
		if(a<0)a=0;
		int b = segmin.query(0,N-1)-segmax.query(0,N-1) + 1;
		if(b<0)b=0;
		ans = max(ans,a+b);
		int l = segmax.query(i,i+1);
		if(l<Lmax)continue;
		Lmax = max(Lmax,segmax.query(i,i+1));
		segmax.update(i,0);
		segmin.update(i,Inf);
	}

	for(int i=0;i<N-1;i++){
		int mini = segmin.query(i,i+1);
		int maxi = segmax.query(i,i+1);
		if(maxi==0)break;

		int a = Rmin-Lmax+1;
		int b = mini-maxi+1;

		ans = max(ans,a+b);
	}

	cout<<ans<<endl;


    return 0;
}

