		} else {
			rest = merge(rest, e);
			empty = false;
		}
	}
	sort(lt.rbegin(), lt.rend(),
		[&](const PII& a, const PII& b) {
			return make_pair(max(first.L, a.L), a.R) < make_pair(max(first.L, b.L), b.R); 
