template<class Type>
Type solve(Type res = Type()){
    int N; cin >> N;
    vector<ll> L(N),R(N);
    for(int i = 0; i < N;i++) cin >> L[i] >> R[i];
    vector<pll> RL(N);
    for(int i = 0; i < N;i++){
        RL[i] = make_pair(R[i],L[i]);
    }
    sort(RL.begin(),RL.end());
    vector<ll> get_cnt(N);
    {
        ll lpos = 1,rpos = 1e9;
        for(int i = N-1; i >= 0; i--){
            ll l,r; tie(r,l) = RL[i];

            lpos = max(lpos,l);
            rpos = min(rpos,r);

            get_cnt[i] = max(0LL,rpos-lpos+1);
        }
    }
    // cout << get_cnt << endl;
    {
        ll lpos = 1,rpos = 1e9;
        for(int i = 0; i < N-1; i++){
            ll l,r; tie(r,l) = RL[i];
            lpos = max(lpos,l);
            rpos = min(rpos,r);
            res = max(res,get_cnt[i+1]+max(0LL,rpos-lpos+1));
        }
    }

    return res;
}
