typedef long long ll;
#define REP(i,n) for (ll i = 0; i < (n); ++i)
#define SETMAX(x, y) x = max(x, (y));

ll width(const pair<ll, ll>& p){
    return p.second - p.first + 1;
}

ll width(ll left, ll right){
    return max(0LL, right - left + 1);
}

int main(){
    ll n;
    cin >> n;
    vector<pair<ll, ll>> p(n);
    REP(i, n){
        cin >> p.at(i).first >> p.at(i).second;
    }

    if(n == 2){
        cout << width(p.at(0)) + width(p.at(1)) << endl;
        return 0;
    }

    ll maxl = 0, maxl_idx = -1;
    ll minr = 1000000001, minr_idx = -1;
    REP(i, n){
        if(maxl < p.at(i).first){
            maxl = p.at(i).first;
            maxl_idx = i;
        }
        if(minr > p.at(i).second){
            minr = p.at(i).second;
            minr_idx = i;
        }
    }

    vector<pair<ll, ll>> p2;
    REP(i, n){
        if(i == maxl_idx || i == minr_idx){
            continue;
        }
        p2.push_back(p.at(i));
    }
    sort(p2.begin(), p2.end());

    ll ans = 0;
    for(auto q : p2){
        SETMAX(ans, width(maxl, minr) + width(q));
    }

    vector<ll> cminr(p2.size());
    cminr.at(p2.size() - 1) = p2.back().second;
    for(ll i = p2.size() - 2; i >= 0; --i){
        cminr.at(i) = min(p2.at(i).second, cminr.at(i + 1));
    }

    for(ll i = -1; i < (ll)p2.size(); ++i){
        if(i == -1){
            SETMAX(
                ans,
                width(p.at(minr_idx)) + 
                width(maxl, min(cminr.at(i + 1), p.at(maxl_idx).second))
            );
        }else if(i < cminr.size() - 1){
            SETMAX(
                ans,
                width(max(p2.at(i).first, p.at(minr_idx).first), minr) + 
                width(maxl, min(cminr.at(i + 1), p.at(maxl_idx).second))
            );
        }else{
            SETMAX(
                ans,
                width(max(p2.at(i).first, p.at(minr_idx).first), minr) +
                width(p.at(maxl_idx))
            );
        }
    }
    cout << ans << endl;
    return 0;
}

