        cin >> l[i] >> r[i];
    }

    VI lMaxPref, lMaxSuff, rMinPref, rMinSuff;

    auto makePrefSuff = [&]() {
        lMaxPref = l, lMaxSuff = l;
        rMinPref = r, rMinSuff = r;

        FOR(i,1,n-1) {
            lMaxPref[i] = max(lMaxPref[i], lMaxPref[i-1]);
            rMinPref[i] = min(rMinPref[i], rMinPref[i-1]);
        }

        FORD(i,n-2,0) {
            lMaxSuff[i] = max(lMaxSuff[i], lMaxSuff[i+1]);
            rMinSuff[i] = min(rMinSuff[i], rMinSuff[i+1]);
        }
    };

    makePrefSuff();

    int ans = 0;

    FOR(i,0,n-1) {
        int here = r[i] - l[i] + 1;

        int lRest = 0;
        if (i > 0) lRest = max(lRest, lMaxPref[i-1]);
        if (i < n-1) lRest = max(lRest, lMaxSuff[i+1]);

        int rRest = 1e9 + 1;
        if (i > 0) rRest = min(rRest, rMinPref[i-1]);
        if (i < n-1) rRest = min(rRest, rMinSuff[i+1]);

        if (lRest <= rRest) {
            here += rRest - lRest + 1;
        }

        ans = max(ans, here);
    }

    VP pairs(n);
    FOR(i,0,n-1) pairs[i] = {l[i], r[i]};

    sort(pairs.begin(), pairs.end(), [&](const pii &a, const pii &b) {
        if (a.nd != b.nd) {
            return a.nd < b.nd;
        } else {
            return a.st > b.st;
        }
    });

    VP rest;

    for (auto &p : pairs) {
        if (rest.empty() || p.st > rest.back().st) {
            rest.push_back(p);
        }
    }

    n = SIZE(rest);

    if (n > 1) {
        l.resize(n);
        r.resize(n);

        FOR(i,0,n-1) {
            l[i] = rest[i].st;
            r[i] = rest[i].nd;
        }

        makePrefSuff();

        FOR(i,0,n-2) {
            int lLeft = lMaxPref[i], rLeft = rMinPref[i];
            int lRight = lMaxSuff[i+1], rRight = rMinSuff[i+1];

            int here = 0;

            if (lLeft <= rLeft) here += rLeft - lLeft + 1;
            if (lRight <= rRight) here += rRight - lRight + 1;

            ans = max(ans, here);
        }
    }

    cout << ans;

    return 0;
}

