template<typename T>
void fin(T const& t){ std::cout << t << std::endl; exit(0); }

struct E {
  int L, R;
  bool operator<(E const& r) const { return L > r.L; }
};

int main() {
  std::cin.tie(0); std::ios::sync_with_stdio(false);
  int N; std::cin >> N;
  std::vector<E> LR(N);
  int ma = 0, maL=0, miR=1e9+1, iL, iR;
  auto len = [](int l, int r)->int64_t { return std::max(0, r-l+1); };
  for(int i = 0; i < N; ++i) {
    std::cin >>  LR[i].L >> LR[i].R;
    ma = std::max(ma, LR[i].R-LR[i].L+1);
    if(LR[i].L > maL) { maL = LR[i].L; iL = i; }
    if(LR[i].R < miR) { miR = LR[i].R; iR = i; }
  }
  int64_t ans = ma + len(maL, miR);
  if(iL == iR) fin(ans);
  int miL = LR[iR].L, maR = LR[iL].R;
  LR.erase(LR.begin() + std::max(iL, iR));
  LR.erase(LR.begin() + std::min(iL, iR));
  std::sort(LR.begin(), LR.end());
  // initial: [all LR.L, miR] + [maL, maR]
  // final:   [miL, miR] + [maL, all LR.R]
  for(int i = 0; i < LR.size(); ++i) {
    int64_t cur = len(std::max(LR[i].L, miL), miR)
                + len(maL, maR);
    ans = std::max(ans, cur);
    maR = std::min(maR, LR[i].R);
  }
  int64_t cur = len(miL, miR) + len(maL, maR);
  ans = std::max(ans, cur);
  fin(ans);
  return 0;
}

