void solve()
{
    ll N;
    in(N);
    vpll A(N);
    for1 (i, N) {
        ll l, r, len;
        in(l, r);
        r++;
        A[i] = make_pair(l, r);
    }

    ll loR = INF;
    ll loRidx = 0;
    for1 (i, N) {
        if (chmin(loR, A[i].second)) {
            loRidx = i;
        }
    }

    ll hiL = -INF;
    ll hiLidx = 0;
    for1 (i, N) {
        if (chmax(hiL, A[i].first)) {
            hiLidx = i;
        }
    }

    ll hiLen = 0;
    for1 (i, N) {
        if (i == hiLidx || i == loRidx) continue;
        chmax(hiLen, A[i].second - A[i].first);
    }

    ll ans = 0;
    ans = max(loR - hiL, 0LL) + hiLen;

    sort(all(A));
    vll cR(N + 1);
    cR[N] = INF;
    rfor2 (i, N - 1, -1) {
        cR[i] = min(cR[i + 1], A[i].second);
    }
