    }

    sort(a+1, a+n+1);
    build();

    for(int i = 1; i <= n; i++){
        update(i, a[i].first, a[i].second);
    }

    for(int i = 2; i <= n; i++){
        ll l1 = query1(1, i-1), r1 = query2(1, i-1);
        ll l2 = query1(i, n), r2 = query2(i, n);
        ans = max(ans, max(0LL, r1-l1+1) + max(0LL, r2-l2+1));
        //print(i, l1, r1, l2, r2);

        if(i == n) continue;
        ll t = a[i].second-a[i].first+1;
        l1 = max(query1(1, i-1), query1(i+1, n));
        r1 = min(query2(1, i-1), query2(i+1, n));
        t += max(0LL, r1-l1+1);
        ans = max(ans, t);
    }

