		rep(i, N) if (LR[i].second < LR[ilR].second) ilR = i;
		swap(LR.back(), LR[ilR]);
		auto lR = LR.back(); LR.pop_back();
		sort(LR.begin(), LR.end());

		vector<pair<UL, UL>> LLR(N);
		LLR[0] = lR;
		rep(i, N - 1) {
			LLR[i + 1].first = max(LLR[i].first, LR[i].first);
			LLR[i + 1].second = min(LLR[i].second, LR[i].second);
		}
		vector<pair<UL, UL>> RLR(N);
		RLR[N - 1] = { 0, 1000000000 };
		rep(ip, N - 1) {
			UL i = (N - 1) - ip - 1;
			RLR[i].first = max(RLR[i + 1].first, LR[i].first);
			RLR[i].second = min(RLR[i + 1].second, LR[i].second);
		}
		/*
		rep(i, N - 1) cout << LR[i].first << " " << LR[i].second << endl;
		rep(i, N) {
			cout << LLR[i].first << " " << LLR[i].second << " "
				<< RLR[i].first << " " << RLR[i].second << endl;
		}*/
		UL ans = 0;
		rep(i, N - 1) {
			if (LLR[i].first >= LLR[i].second) continue;
			if (RLR[i].first >= RLR[i].second) continue;
			UL ansbuf = (LLR[i].second - LLR[i].first) + (RLR[i].second - RLR[i].first);
			ans = max(ans, ansbuf);
		}
		UL ansbuf = 0;
		if(LLR[N - 1].second > LLR[N - 1].first) ansbuf = LLR[N - 1].second - LLR[N - 1].first;
		rep(i, N - 1) { ans = max(ans, LR[i].second - LR[i].first + ansbuf); }
		cout << ans << endl;
	}

	Problem();
};
