        if(bakiL>bakiR or shuru > shesh) cout<<ans, exit(0);
    }
//    cout<<ans<<endl;
//    cout<<shesh<<" "<<shuru<<" "<<bakiL<<" "<<bakiR<<endl;
    bakiL = max(bakiL , 1LL);
    ans = max(ans, shesh-shuru+1 + bakiR-bakiL+1);
    cout<<ans;
}
