using namespace std;

int
main() {
  std::ios::sync_with_stdio(false);

  int n;
  cin>>n;

  ll left, right;
  vector<pair<int, int>> data;
  for (int i=0; i<n; i++) {
    cin>>left>>right;
    data.push_back({left, right});
  }
  sort(data.begin(), data.end());

  vector<int> end(n);
  for (auto p : data) end.push_back(p.second);
  for (int i=n-1; i>=0; i--) end[i] = min(end[i*2], end[i*2+1]);

  ll ans = 0;
  for (int i=0; i<n-1; i++) {
    ll current = 0;
    int bottom = INT_MAX;
    int left = 0, right = i;
    left += n, right += n;
    while (1) {
      if (left > right) break;

      if (right % 2 == 0) {
        bottom = min(bottom, end[right]);
        right--;
      }
      if (left % 2 == 1) {
        bottom = min(bottom, end[left]);
        left++;
      }

      right /= 2;
      left /= 2;
    }
    current += max(0, bottom - data[i].first + 1);

    bottom = INT_MAX;
    left = i+1, right = n-1;
    left += n, right += n;
    while (1) {
      if (left > right) break;

      if (right % 2 == 0) {
        bottom = min(bottom, end[right]);
        right--;
      }
      if (left % 2 == 1) {
        bottom = min(bottom, end[left]);
        left++;
      }

      right /= 2;
      left /= 2;
    }

    current += max(0, bottom - data[n-1].first + 1);
    ans = max(current, ans);
  }

  cout<<ans<<endl;
  return 0;
}

