    SegTree<ll> lseg(N, 0, [](ll a, ll b){return max(a, b);}, [](ll a, ll b){return b;});
    SegTree<ll> rseg(N, INF, [](ll a, ll b){return min(a, b);}, [](ll a, ll b){return b;});
    vector<P> interval(N);
