long get_num(pair<long, long> c) {
  if (c.first == -1) {
    return 0;
  } else {
    return max(c.second - c.first + 1, 0L);
  }
}
pair<long, long> intersection(pair<long, long> c1, pair<long, long> c2) {
  int l1, r1, l2, r2;
  tie(l1, r1) = c1;
  tie(l2, r2) = c2;
  if (l1 == -1 || l2 == -1) {
    return make_pair(-1, -1);
  }
  if (r1 < l2 || r2 < l1) {
    return make_pair(-1, -1);
  }
  return make_pair(max(l1, l2),  min(r1, r2));
}
