void solve2(int minL, int maxL, vector<pair<int, int>> l, vector<pair<int, int>> r)
{
  int minR = r[0].first, maxR = r[0].second;
  for (auto u : r)
  {
    minR = max(minR, u.first);
    maxR = min(maxR, u.second);
  }
  if (minR > maxR)
  {
    cout << ans << endl;
    exit(0);
  }

  if (l.empty())
  {
    ans = max(ans, getAns(minL, maxL, minR, maxR));
    cout << ans << endl;
    exit(0);
  }

  int m = l.size();
  minPrefix[0] = l[0].second;
  for (int i = 1; i < m; i++)
    minPrefix[i] = min(minPrefix[i - 1], l[i].second);
  minSuffix[m - 1] = l[m - 1].second;
  for (int i = m - 2; i >= 0; i--)
    minSuffix[i] = min(minSuffix[i + 1], l[i].second);

  // put all to left
  ans = max(ans, getAns(max(minL, l[m - 1].first), min(maxL, minPrefix[m - 1]), minR, maxR));
  // put all to right
  ans = max(ans, getAns(minL, maxL, minR, min(maxR, minPrefix[m - 1])));
  // split
  for (int i = 0; i < m - 1; i++)
    ans = max(ans, getAns(max(minL, l[i].first), min(maxL, minPrefix[i]), minR, min(maxR, minSuffix[i + 1])));
  cout << ans << endl;
}

