                ans = max(ans, max(1ll * (*nxt) - a[i].F + 1, 0ll) + max(1ll * min_R_2 - a[n].F + 1, 0ll));
            }
            /// checking for =
            if (s1.count(min_R_2) > 1) {
				ans = max(ans, max(1ll * min_R_2 - a[i].F + 1, 0ll) + max(1ll * min_R_2 - a[n].F + 1, 0ll));            		
            }
        ans = max(ans, max(1ll * min_R_1 - a[i].F + 1, 0ll) + max(1ll * min_R_2 - a[n].F + 1, 0ll));
        if (a[i].F == a[n].F) assert(0);
    }
    cout << ans;
    return 0;
}

