using namespace std;

void solve() {
  long N;
  cin >> N;
  vector<pair<long, long>> LR(N);
  vector<long> L;
  vector<long> R;

  long max_prob = 0;
  rep (i, N) {
    long l, r;
    cin >> l >> r;
    max_prob = max(max_prob, r - l + 1);
    LR[i] = make_pair(l, r);
    L.push_back(l);
    R.push_back(r);
  }
  sort(LR.begin(), LR.end());

  {
    // 1問とその他に分けるケースのカバー
    sort(L.begin(), L.end());
    reverse(L.begin(), L.end());
    sort(R.begin(), R.end());
    for (auto it: LR) {
      long f_L = it.first;
      long f_R = it.second;
      long f_score = f_R - f_L + 1;
      long s_L = L[0];
      long s_R = R[0];
      if (s_L == f_L) s_L = L[1];
      if (s_R == f_R) s_R = R[1];
      long s_score = s_R - s_L + 1;
      max_prob = max(max_prob, f_score + s_score);
    }
  }

  // for (auto it: LR) cout << it.first << ", " << it.second << endl;

  vector<long> minRmemo(N);
  vector<long> minRmemoRev(N);
  minRmemo[0] = LR[0].second;
  for (long i = 1; i < N; i++) {
    minRmemo[i] = min(minRmemo[i-1], LR[i].second);
  }
  minRmemoRev[N-1] = LR[N-1].second;
  for (long i = N - 2; i >= 0; i--) {
    minRmemoRev[i] = min(minRmemoRev[i+1], LR[i].second);
  }

  long split_ans = 0;
  for (long i = 0; i < N - 1; i++) {
    long foo = minRmemo[i] - LR[i].first + 1;
    if (foo < 0) foo = 0;

    long bar = minRmemoRev[i+1] - LR[N-1].first + 1;
    if (bar < 0) bar = 0;

    split_ans = max(split_ans, foo + bar);
  }

  long ans = max(max_prob, split_ans);
  // cout << "max_prob: " << max_prob << ", split_ans: " << split_ans << endl;
  cout << ans << endl;
}

int main(void) {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout.precision(12);
  solve();
  return 0;
}

