int ModExp(int x,int y,int m){
    int res = 1;
    x = x % m;
    while (y > 0)
    {
        if (y & 1)
            res = (res*x) % m;

        y = y>>1;
        x = (x*x) % m;
    }
    return res;
}

pii merge(pii a,pii b){
    pii ans;
    ans.first = max(a.first,b.first);
    ans.second = min(a.second,b.second);
    if(ans.second < ans.first){
        ans.second = ans.first;
    }
    return ans;
}

void solve(){
    int n;
    cin >> n;
    vector<pii> vec;
    FOR(i,0,n){
        int l,r;
        cin >> l >> r;
        vec.pb({l,r});
    }
    sort(vec.begin(),vec.end());
    pii a = vec[0];
    pii b = vec[n-1];
    int ans = a.second-a.first+1;
    ans += b.second-b.first+1;
    FOR(i,1,vec.size()-1){
        pii t1 = merge(a,vec[i]);
        pii t2 = merge(b,vec[i]);
        int d1 = (a.second-a.first+1)-(t1.second-t1.first+1);
        int d2 = (b.second-b.first+1)-(t2.second-t2.first+1);
        if(d1 < d2){
            a = t1;
            ans -= d1;
        }else if(d1 > d2){
            b = t2;
            ans -= d2;
        }else{
            if((a.second-a.first+1) > (b.second-b.first+1)){
                b = t2;
                ans -= d2;
            }else{
                a = t1;
                ans -= d1;
            }
        }
    }
    cout << ans << endl;
}

