#define REP(i,n) FOR(i,0,n)

using namespace std;
LL p = 1000000007ll;

struct RMQ {
  using type = int;
  static int id() { return 1023456789; }
  static int op(const int &l, const int &r) {
    return std::min(l, r);
  }
};

// segment tree
template <typename M>
class segment_tree {
  using T = typename M::type;
  const int n;
  vector<T> data;
  int size(int n) {
    int res;
    for (res = 1; res < n; res <<= 1);
    return res;
  }
public:
  segment_tree(int n_) : n(size(n_)), data(n * 2, M::id()) {}
  segment_tree(int n_, T val) : n(size(n_)), data(n * 2, val) {}
  void init(const vector<T>& data_) {
    for (int i = 0; i < static_cast<int>(data_.size()); i++)
      data[i + n] = data_[i];
    for (int i = n - 1; i >= 0; i--)
      data[i] = M::op(data[i * 2], data[i * 2 + 1]);
  }
  void update(int p, T val) {
    p += n;
    data[p] = val;
    while (p >>= 1) data[p] = M::op(data[p * 2], data[p * 2 + 1]);
  }
  void add(int p, T val) {
    p += n;
    data[p] += val;
    while (p >>= 1) data[p] = M::op(data[p * 2], data[p * 2 + 1]);
  }
  T find(int l, int r) {
    l += n; r += n + 1;
    T res1 = M::id(), res2 = M::id();
    while (l < r) {
      if (l & 1) res1 = M::op(res1, data[l++]);
      if (r & 1) res2 = M::op(data[--r], res2);
      l >>= 1; r >>= 1;
    }
    return M::op(res1, res2);
  }
};


int main(void)
{
  int n;
  cin >> n;
  vector<pair<int,int>> vlr(n);
  for(auto &pa:vlr) cin >> pa.first >> pa.second;
  sort(vlr.begin(),vlr.end());
  vector<int> l(n),r(n);
  REP(i,n) l[i] = vlr[i].first;
  REP(i,n) r[i] = vlr[i].second + 1;
  segment_tree<RMQ> rmq(n);
  REP(i,n) rmq.update(i,r[i]);

  int answer = 0;
  REP(i,n) {
    int tmp = r[i] - l[i];
    answer = max(answer,tmp);
    tmp += min(rmq.find(0,i-1), rmq.find(i+1,n-1));
    tmp -= l[n-1];
    answer = max(answer,tmp);
  }

  FOR(i,1,n) {
    int lseg = rmq.find(0,i-1) - l[i-1];
    int rseg = rmq.find(i,n-1) - l[n-1];
    answer = max(answer, lseg+rseg);
  }

  cout << answer << endl;

  return 0;
}

