	int l, r;
};

Contestants c[N + 1];
multiset<int> sl, sr;
int n;

bool comp_r(const Contestants &a, const Contestants &b) {
	if (a.r == b.r) {
		return a.l < b.l;
	}

	return a.r < b.r;
}

bool comp_l(const Contestants &a, const Contestants &b) {
	if (a.l == b.l) {
		return a.r < b.r;
	}

	return a.l < b.l;
}

void init() {
	sl.clear();
	sr.clear();

	for (int i = 1; i <= n; i++) {
		sl.insert(c[i].l);
		sr.insert(c[i].r);
	}
}

int main() {
	int ans, l, r, i;

	scanf("%d", &n);

	for (i = 1; i <= n; i++) {
		scanf("%d%d", &c[i].l, &c[i].r);
	}

	// Biggest.
	init();
	ans = 0;

	for (i = 1; i <= n; i++) {
		sl.erase(sl.find(c[i].l));
		sr.erase(sr.find(c[i].r));
		ans = max(ans, max(0, c[i].r - c[i].l + 1) + max(0, *sr.begin() - *sl.rbegin() + 1));
		sl.insert(c[i].l);
		sr.insert(c[i].r);
	}

	// Left to right.
	init();
	sort(c + 1, c + 1 + n, comp_r);
	l = -INF;
	r = INF;

	for (i = 1; i <= n - 1; i++) {
		sl.erase(sl.find(c[i].l));
		sr.erase(sr.find(c[i].r));
		l = max(l, c[i].l);
		r = min(r, c[i].r);
		ans = max(ans, max(0, r - l + 1) + max(0, *sr.begin() - *sl.rbegin() + 1));
	}

	// Right to left.
	init();
	sort(c + 1, c + 1 + n, comp_l);
	l = -INF;
	r = INF;

	for (i = n; i >= 2; i--) {
		sl.erase(sl.find(c[i].l));
		sr.erase(sr.find(c[i].r));
		l = max(l, c[i].l);
		r = min(r, c[i].r);
		ans = max(ans, max(0, r - l + 1) + max(0, *sr.begin() - *sl.rbegin() + 1));
	}

	printf("%d\n", ans);

	return 0;
}

