using range = pair<lint, lint>;
using answer = pair<range, range>;

range merge(range a, range b){
    if(a.second <= b.first){
        return {a.second, a.second};
    }
    if(b.second <= a.first){
        return {b.second, b.second};
    }
    return {max(a.first, b.first), min(a.second, b.second)};
}

lint len(range a){
    return a.second - a.first;
}

lint score(answer a){
    return len(a.first) + len(a.second);
}

answer good(answer a, answer b){
    if(score(a) < score(b)){
        return b;
    }else{
        return a;
    }
}

