using namespace std;
typedef long long ll;

const ll INF = (1ll << 60) - 1;

struct Segment {
    int n;
    vector<ll> node;

    Segment(int N) {
        n = 1;
        while (n < N) n *= 2;

        // ノード数は ceil(log2(N))^2 * 2 (葉数が2べきとなるよう調整)
        node.assign(2 * n - 1, INF);
    }

    void update(int k, ll a) {  // k番目の値をaに変更
        // k番目の葉 : k+n-1
        k += n - 1;
        node[k] = a;

        // 子 → 親 : (k-1)/2
        // 親 → 子(1,2) : 2*k + (1,2)
        while (k > 0) {
            k = (k - 1) / 2;
            node[k] = min(node[2 * k + 1], node[2 * k + 2]);
        }
    }

    ll find_min(int a, int b, int k = 0, int l = 0, int r = -1) {  // [a,b)の最小値を返す
        if (r < 0) r = n;

        // 含まない
        if (r <= a || b <= l) return INF;
        // 完全に含む
        if (a <= l && r <= b)
            return node[k];
        else {
            ll vl = find_min(a, b, 2 * k + 1, l, (l + r) / 2);
            ll vr = find_min(a, b, 2 * k + 2, (l + r) / 2, r);

            return min(vl, vr);
        }
    }
};

int main() {
    ll n, ans = 0;
    cin >> n;
    vector<pair<ll, ll>> p(n);
    for (int i = 0; i < n; i++) {
        int l, r;
        cin >> l >> r;
        p[i] = make_pair(l, r);
    }
    sort(p.begin(), p.end());
    Segment tree(n);
    for (int i = 0; i < n; i++) {
        tree.update(i, p[i].second);
    }
    for (int k = 0; k < n - 1; k++) {
        ans = max(max(0ll, tree.find_min(0, k + 1) - p[k].first + 1) + max(0ll, tree.find_min(k + 1, n) - p[n - 1].first + 1), ans);
    }
    cout << ans << endl;
    return 0;
}

