      segments.begin(), segments.end(),
      [](const Segment& s1, const Segment& s2) -> bool {
        if (s1.l != s2.l) return s1.l > s2.l;
        return s1.r > s2.r;
      });

  int64 ans = 0;

  // 1 + n - 1
  multiset<int64> l_set, r_set;
  for (const auto& segment : segments) {
    l_set.insert(segment.l);
    r_set.insert(segment.r);
  }

