    int64 r_min = *(r_set.begin());
    int64 l_max_2 = *(l_set_2.rbegin());
    int64 r_min_2 = *(r_set_2.begin());
    UpdateMax(
        ans, max(r_min - l_max + 1, 0LL) + max(r_min_2 - l_max_2 + 1, 0LL));
  }

  cout << ans << endl;
}

