		res = max(res, lr[i].second - lr[i].first + 1);
		lmax = max(lr[i].first, lmax);
		rmin = min(lr[i].second, rmin);
		q2.psp2(lr[i].second, i);
		lr[i].second = -lr[i].second;
		q.push(make_tuple(lr[i].first, lr[i].second, i));
	}
	auto p = q.top();
	q.pop();
	auto p2 = q2.top();

	ll glm = get<0>(p);
	ll grm = -get<1>(p);
	ll i = get<2>(p);
	if (i == p2.second) {
		q2.pop();
	}
	rmin = q2.top().first;

	ll v = max(0LL, (rmin - lmax) + 1);
	v += grm - glm + 1;
	res = max(res, v);
	bool use[100010];
	all0(use);
	while (q.size() > 1)
	{
		p = q.top();
		q.pop();
		glm = max(glm, get<0>(p));
		grm = min(grm, -get<1>(p));
		i = get<2>(p);
		use[i] = true;
		while (!q2.empty())
		{
			if (use[q2.top().second]) {
				q2.pop();
			}
			else {
				break;
			}
		}
		p2 = q2.top();
		rmin = p2.first;

		res = max(res,
			max(0LL, grm - glm + 1) +
			max(0LL, rmin - lmax + 1));
	}

	cout << res << endl;

}


