    int n;
    cin >> n;
    vector<Interval> intervals(n);
    for (auto& interval : intervals) {
        cin >> interval;
    }
    sort(intervals.begin(), intervals.end());
    AndHeap<Interval> fast_and(intervals);
    int best = 0;

    // all but one:
    for (int i = 0; i < n; ++i) {
        auto left = fast_and.partial_and(0, i);
        auto right = fast_and.partial_and(i+1, n);
        int total_size = (left & right).size() + intervals[i].size();
        best = max(best, total_size);
    }

    // first i
    for (int i = 1; i < n; ++i) {
        auto left = fast_and.partial_and(0, i);
        auto right = fast_and.partial_and(i, n);
        int total_size = left.size() + right.size();
        best = max(best, total_size);
    }

    cout << best << endl;

    return 0;
}

