      while (B.size() && B.back().second >= A[i].second) {
         C.emplace_back(B.back());
         B.pop_back();
      }
      B.emplace_back(A[i]);
   }
   for (int i = 0; i + 1 < B.size(); ++i) {
      int leftVal = max(0, B[0].second - B[i].first + 1);
      int rightVal = max(0, B[i + 1].second - B.back().first + 1);
      ans = max(ans, leftVal + rightVal);
   }
   int leftVal = max(0, B[0].second - B.back().first + 1);
   int rightVal = 0;
   for (auto p : C) {
      rightVal = max(rightVal, p.second - p.first + 1);
   }
   ans = max(ans, leftVal + rightVal);
   cout << ans << "\n";
   return 0;
}

