Int calc(Int N, vector<P> A){
  Int ans = 0;
  for(auto p:A) Max<Int>(ans, p.second - p.first + 1);

  multiset<Int> L1, R1;
  multiset<Int> L2, R2;
  for(auto p:A){
    Int l, r; tie(l, r) = p;
    L2.insert(l);
    R2.insert(r);
  }

  for(Int i=0;i<N-1;i++){
    Int l, r; tie(l, r) = A[i];
    L2.erase(L2.find(l));
    R2.erase(R2.find(r));
    L1.insert(l);
    R1.insert(r);

    Int a = *(--L1.end());
    Int b = *R1.begin();
    Int x = *(--L2.end());
    Int y = *R2.begin();
    Int len1 = max<Int>(0, b - a + 1);
    Int len2 = max<Int>(0, y - x + 1);
    Int len = len1 + len2;
    Max(ans, len);
  }
  return ans;
}

Int solve(Int N, vector<P> A){
  sort(A.begin(), A.end(), [&](auto a, auto b){
      if(a.first != b.first) return a.first < b.first;
      return a.second > b.second;
    });
  Int a = calc(N, A);


  reverse(A.begin(), A.end());
  Int b = calc(N, A);

  sort(A.begin(), A.end(), [&](auto a, auto b){
      if(a.second != b.second) return a.second < b.second;
      return a.first > b.first;
    });
  Int c = calc(N, A);

  reverse(A.begin(), A.end());
  Int d = calc(N, A);
  Int ans = max({a, b, c, d});
  return ans;
}

