bool cmp(pair<long long, long long> x, pair<long long, long long> y) {
	if (x.Y != y.Y) return x.Y < y.Y;
	return x.X < y.X;
}

void solve() {
	int n;
	cin >> n;

	long long maxDiff = 0, minDiff = (long long)1E12;
	vector<pair<long long, long long>> plr(n);
	for (int i = 0; i < n; ++i) {
		cin >> plr[i].X >> plr[i].Y;
		maxDiff = max(maxDiff, plr[i].Y - plr[i].X + 1);
		minDiff = min(minDiff, plr[i].Y - plr[i].X + 1);
	}

	sort(ALL(plr));
	for (int i = 1; i < n; ++i) {
		if (plr[i].X == plr[i - 1].X) plr[i].Y = -1;
	}

	sort(ALL(plr), cmp);
	for (int i = 1; i < n; ++i) {
		if (plr[i].Y == plr[i - 1].Y) plr[i].X = -1;
	}

	vector<pair<long long, long long>> plr2;
	for (int i = 0; i < n; ++i) {
		if (plr[i].X != -1 and plr[i].Y != -1) {
			plr2.Push(plr[i]);
		}
	}

	n = plr2.size();

	if (n == 1) {
		cout << maxDiff + minDiff << "\n";
		return;
	}

	sort(ALL(plr2), cmp);

	long long leftRange[n], lMin = 0;
	for (int i = 0; i < n; ++i) {
		lMin = max(lMin, plr2[i].X);
		leftRange[i] = max(0LL, plr2[0].Y - lMin + 1);
		// cout << leftRange[i] << " ";
	}

	long long rightRange[n], rMin = 0, rMax = (long long)1E12;
	for (int i = n-1; i >= 0; --i) {
		rMin = max(rMin, plr2[i].X);
		rMax = min(rMax, plr2[i].Y);
		rightRange[i] = max(0LL, rMax - rMin + 1);
		// cout << rightRange[i] << " ";
	}

	long long maxAns = 0;
	for (int i = 0; i < n-1; ++i) {
		maxAns = max(maxAns, leftRange[i] + rightRange[i + 1]);
	}

	cout << maxAns << "\n";
}

int main() {
	int t = 1;
	// cin >> t;
	while (t--) {
		solve();
	}
	return 0;
}

