ll dfs(pair<ll, ll> f, pair<ll, ll> s,ll t) {
    if(t==n){
        return max(0LL, f.second - f.first + 1) + max(0LL, s.second - s.first + 1);
    }
    ll x = v[t].first, y = v[t].second;
    ll a1 = max(0LL, min(f.second, y) - max(f.first, x) + 1) + max(0LL, s.second - s.first + 1);
    ll a2 = max(0LL, min(s.second, y) - max(s.first, x) + 1) + max(0LL, f.second - f.first + 1);
    ll a3 = max(0LL, min(f.second, s.second) - max(f.first, s.first) + 1) + max(0LL,y - x + 1);
    ll ma = max({a1, a2, a3});
    ll b=0,c=0,d=0;
    if(ma == a1) {
        f.first = max(f.first, x), f.second = min(f.second, y);
        if(f.first > f.second) f = {10, -10};
        b = dfs(f,s,t+1);
    } else if(ma == a2) {
        s.first = max(s.first, x), s.second = min(s.second, y);
        if(s.first > s.second) s = {10, -10};
        c = dfs(f,s,t+1);
    } else if(ma == a3) {
        f.first = max(f.first, s.first), f.second = min(f.second, s.second);
        if(f.first > f.second) f = {10, -10};
        s = {x, y};
        d = dfs(f,s,t+1);
    }
    return max({b,c,d});
}

int main() {
    ll m, i, j, k;
    cin >> n;
    v = vector<pair<ll, ll>>(n);
    for(i = 0; i < n; i++) {
        cin >> v[i].first >> v[i].second;
    }
    sort(v.begin(), v.end(), [](const pair<ll, ll> &x, const pair<ll, ll> &y) {
        if(x.second - x.first != y.second - y.first) {
            return x.second - x.first < y.second - y.first;
        } else {
            return x.first < y.first;
        }
    });
    /*for(i=0;i<n;i++){
        cout << v[i].first << " " << v[i].second << endl;
    }*/
    pair<ll, ll> f = v[0], s = v[1];
    ll x = 2;
    for(i = 2; i < n; i++) {
        ll x = v[i].first, y = v[i].second;
        ll a1 = max(0LL, min(f.second, y) - max(f.first, x) + 1) + max(0LL, s.second - s.first + 1);
        ll a2 = max(0LL, min(s.second, y) - max(s.first, x) + 1) + max(0LL, f.second - f.first + 1);
        ll a3 = max(0LL, min(f.second, s.second) - max(f.first, s.first) + 1) + max(0LL,y - x + 1);
        ll ma = max({a1, a2, a3});
        if(ma == a1) {
            f.first = max(f.first, x), f.second = min(f.second, y);
            if(f.first > f.second) f = {0, -INF};
        } else if(ma == a2) {
            s.first = max(s.first, x), s.second = min(s.second, y);
            if(s.first > s.second) s = {0, -INF};
        } else if(ma == a3) {
            f.first = max(f.first, s.first), f.second = min(f.second, s.second);
            if(f.first > f.second) f = {0, -INF};
            s = {x, y};
        }
    }
    cout << max(0LL, f.second - f.first + 1) + max(0LL, s.second - s.first + 1) << endl;
    return 0;
}

