using namespace std;
using lld = long long int;
using ll = pair<lld, lld>;

constexpr auto MAX_N { 100005 };

vector<ll> a(MAX_N);

lld find_max_joyfulness(int l, int r)
{
    lld max_l = 0, min_r = 1LL << 40;
    for (int i = l; i <= r; ++i)
    {
        max_l = max(max_l, a[i].first);
        min_r = min(min_r, a[i].second);
    }
    return max(min_r - max_l + 1, 0LL);
}

int main()
{
    ios::sync_with_stdio(false);

    int n;
    cin >> n;
    for (int i = 1; i <= n; ++i)
    {
        cin >> a[i].first >> a[i].second;
    }

    sort(begin(a) + 1, begin(a) + n + 1);
    lld l = 1, r = n - 1, ans = find_max_joyfulness(1, n - 1) + find_max_joyfulness(n - 1, n);
    while (l <= r)
    {
        lld m1 = l + (r - l) / 3;
        lld m2 = r - (r - l) / 3;

        lld x1 = find_max_joyfulness(1, m1) + find_max_joyfulness(m1 + 1, n);
        lld x2 = find_max_joyfulness(1, m2) + find_max_joyfulness(m2 + 1, n);

        ans = max(ans, max(x1, x2));

        if (x1 > x2) r = m2 - 1;
        else l = m1 + 1;
    }

    cout << ans << endl;

    return 0;
}

