using namespace std;

int main() {
	const int INF = 1e9 + 10;
	int n; cin >> n;
	pair<int, int> p[n];
	int lmax = 0, rmin = INF;
	for(int i = 0; i < n; ++i) {
		int l, r;
		cin >> l >> r;
		p[i] = {l, r};
		lmax = max(lmax, l);
		rmin = min(rmin, r);
	}
	bool part1 = false;
	int diff = 0;
	for(int i = 0; i < n; ++i) {
		int l, r;
		tie(l, r) = p[i];
		if(l == lmax and r == rmin) {
			part1 = true;
		}
		if(l == lmax or r == rmin) {
			continue;
		}
		diff = max(diff, r - l + 1);
	}
	diff = max(0, (rmin - lmax + 1)) + diff;
	if(part1) {
		cout << diff << endl;
		return 0;
	}
	sort(p, p + n);
	reverse(p, p + n);
	multiset<int> lleft;
	for(int i = 0; i < n; ++i) {
		if(p[i].first != lmax) {
			lleft.insert(p[i].first);
		}
	}
	multiset<int> rright;
	for(int i = 0; i < n; ++i) {
		int l, r;
		tie(l, r) = p[i];
		if(r == rmin) continue;
		if(l != lmax) {
			if(r >= *rright.begin()) {
				rright.insert(r);
			} else {
				// 変更前
				int diff1 = (rmin - *lleft.rbegin()) + (*rright.begin() - lmax);
				// 変更後
				int diff2 = 0;
				lleft.erase(lleft.find(l));
				diff2 += rmin - *lleft.rbegin();
				lleft.insert(l);
				rright.insert(r);
				diff2 += *rright.begin() - lmax;
				rright.erase(rright.find(r));
				if(diff1 < diff2) {
					lleft.erase(lleft.find(l));
					rright.insert(r);
				}
			}
		} else {
			rright.insert(r);
		}
	}
	int diff1 = max(0, rmin - *lleft.rbegin() + 1);
	int diff2 = max(0, *rright.begin() - lmax + 1);
	cout << max(diff, diff1 + diff2) << endl;
	return 0;
}

