#define FOR(i, n) for(int i = 0; i < (n); ++i)
#define REP(i, a, b) for(int i = (a); i < (b); ++i)
#define TRAV(i, n) for(auto &i : n)
#define SZ(x) (int)(x).size()
#define PR std::pair
#define MP std::make_pair
#define X first
#define Y second
typedef long long ll;
typedef std::pair<int, int> PII;
typedef std::vector<int> VI;

const int INF = 1000000666;

int main(){
	std::ios_base::sync_with_stdio(false);
	std::cin.tie(0);

	int n;
	std::cin >> n;
	std::vector<PII> A(n);
	auto lmax = MP(MP(-1, -1), MP(-1, -1));
	auto rmin = MP(MP(INF, -1), MP(INF, -1));
	int ans = 0;
	FOR(i, n){
		std::cin >> A[i].X >> A[i].Y;
		auto a = MP(A[i].X, i);
		auto b = MP(A[i].Y, i);
		if(a >= lmax.X){
			std::swap(lmax.X, lmax.Y);
			lmax.X = a;
		}else if(a >= lmax.Y){
			lmax.Y = a;
		}
		if(b <= rmin.X){
			std::swap(rmin.X, rmin.Y);
			rmin.X = b;
		}else if(b <= rmin.Y){
			rmin.Y = b;
		}
		A[i].Y *= -1;
	}
	std::sort(A.begin(), A.end());
	FOR(i, n) A[i].Y *= -1;
	FOR(i, n){
		int l = lmax.X.X;
		if(lmax.X.Y == i) l = lmax.Y.X;
		int r = rmin.X.X;
		if(rmin.X.Y == i) r = rmin.Y.X;
		ans = std::max(ans, std::max(0, r-l+1)+A[i].Y-A[i].X+1);
	}
	std::vector<PII> B;
	std::vector<PII> ev;
	int ind = 0;
	TRAV(i, A) ev.push_back(MP(i.X, ind+1)), ev.push_back(MP(i.Y, -ind-1)), ind++;
	std::vector<int> state(n);
	std::deque<int> deq;
	std::sort(ev.begin(), ev.end());
	TRAV(e, ev){
		if(e.Y > 0){
			deq.push_front(e.Y-1);
		}else{
			int guy = -e.Y-1;
			if(state[guy]) continue;
			B.push_back(A[guy]);
			while(deq.back() != guy){
				state[deq.back()] = 1;
				deq.pop_back();
			}
			deq.pop_back();
			state[guy] = 1;
		}
	}
	std::sort(B.begin(), B.end());
	if(SZ(B) == 1){
		std::cout << ans << "\n";
		return 0;
	}
	int rl = B.back().X;
	int rr = B[1].Y;
	int llx = B[0].X;
	int lr = B[0].Y;
	ans = std::max(ans, std::max(0, rr-rl+1)+std::max(0, lr-llx+1));
	REP(i, 1, SZ(B)-1){
		llx = B[i].X;
		rr = B[i+1].Y;
		ans = std::max(ans, std::max(0, rr-rl+1)+std::max(0, lr-llx+1));
	}
	std::cout << ans << "\n";
	return 0;
}

