const int N = 1e6 + 5;

int n;
int ans = 0;
int a[N], b[N];
set<pair<int, int>> L[2], R[2];
vector<pair<int, int>> start;
vector<pair<int, int>> finish;

int get(int t) {
    if (L[t].empty()) return 0;
    return max(0, R[t].begin()->x - L[t].rbegin()->x);
}

int main() {
    ios::sync_with_stdio(0);
    srand(time(0));
#ifdef ONPC
    freopen("input", "r", stdin);
#endif
    cin >> n;
    for (int i = 0; i < n; ++i) {
        cin >> a[i] >> b[i];
        --a[i];
        start.emplace_back(a[i], i);
        finish.emplace_back(b[i], i);
        L[1].insert({a[i], i});
        R[1].insert({b[i], i});
    }
    sort(start.begin(), start.end());
    sort(finish.begin(), finish.end());
    chkmax(ans, get(1) * 2);
    int cur_ans = -1;
    while (cur_ans != ans) {
        cur_ans = ans;
        int w = (ans + 1) >> 1;
        int its = 0, itf = 0;
        while (its < n || itf < n) {
            int coor = 2e9;
            if (its < n) chkmin(coor, start[its].x);
            if (itf < n) chkmin(coor, finish[itf].x - w);
            while (its < n && start[its].x == coor) {
                int id = start[its].y;
                L[0].insert({a[id], id});
                L[1].erase({a[id], id});
                R[0].insert({b[id], id});
                R[1].erase({b[id], id});
                ++its;
            }
            while (itf < n && finish[itf].x - w == coor) {
                int id = finish[itf].y;
                L[1].insert({a[id], id});
                L[0].erase({a[id], id});
                R[1].insert({b[id], id});
                R[0].erase({b[id], id});
                ++itf;
            }
            int val1 = get(0), val2 = get(1);
            if (L[0].empty()) val1 = val2;
            if (L[1].empty()) val2 = val1;
            chkmax(ans, val1 + val2);
        }
    }
    cout << ans << '\n';
}

