#include <bits/stdc++.h>
using namespace std;
#define int         long long
#define endl        "\n"
#define P           pair<int, int>
#define dint        long double

const int mod = 1e9+7;

inline int add(int a, int b) { int res = a + b; if(res >= mod) res -= mod;  return res; }
inline int sub(int a, int b) { int res = a - b; if(res < 0) res += mod; return res;}
inline int mul(int a, int b) { return (a * b)%mod; }

int modpow(int a, int b) {
    int ans = 1;
    while(b) {
        if(b%2) ans = mul(ans, a);    
        b /= 2; a = mul(a, a);
    }   return ans;
}

bool cmp(P a, P b) {
    if(a.first == b.first) {
        return a.second > b.second;
    } 
    return a.first < b.first;
}

void solve() {
    int n; cin >> n;
    P a[n];
    for(int i=0; i<n; i++) cin >> a[i].first >> a[i].second;
    sort(a, a+n, cmp);
    int f[n]; memset(f, 0, sizeof f);
    int L = a[n-1].first, R = a[n-1].second;
    for(int i=n-1; i>=0; i--) {
        L = max(a[i].first, L);
        R = min(a[i].second, R);
        f[i] = R - L + 1;
    }
    int ans = f[1] + (a[0].second - a[0].first + 1);
    L = a[0].first, R = a[0].second;
    for(int i=1; i<n-1; i++) {
        L = max(L, a[i].first);
        R = min(R, a[i].second);
        ans = max(ans, R - L + 1 + f[i+1]);
    }
    cout << ans << endl;
}

