long long myMax(long long t1,long long t2){
    if(t1>t2) return t1;
    else return t2;
}
long long myMin(long long t1,long long t2){
    if(t1<t2) return t1;
    else return t2;
}
long long score(long long l1,long long r1,long long l2,long long r2){
    long long ret = myMin(r1,r2)-myMax(l1,l2)+1;
    if(ret>0) return ret;
    else return 0;
}


int main(){
    int n; cin>>n;
    long long oneL,oneR,twoL,twoR;
    vector<vector<long long> > ngo(n,{0,0});
    long long mini = 1000000001;
    int miniIndex = -1;
    for(int i=0;i<n;++i){
        cin>>ngo[i][0];
        cin>>ngo[i][1];
        if(i>0){
            if(score(ngo[0][0],ngo[0][1],ngo[i][0],ngo[i][1]) < mini){
                mini = score(ngo[0][0],ngo[0][1],ngo[i][0],ngo[i][1]);
                miniIndex = i;
            }
        }
    }
    oneL = ngo[0][0];
    oneR = ngo[0][1];
    twoL = ngo[miniIndex][0];
    twoR = ngo[miniIndex][1];
    for(int i=1;i<n;++i){
        if(i == miniIndex) continue;
        long long score1 = score(oneL,oneR,ngo[i][0],ngo[i][1]) + score(twoL,twoR,twoL,twoR);
        long long score2 = score(twoL,twoR,ngo[i][0],ngo[i][1]) + score(oneL,oneR,oneL,oneR);
        if(score1>score2){
            oneL = myMax(oneL,ngo[i][0]);
            oneR = myMin(oneR,ngo[i][1]);
        }else{
            twoL = myMax(twoL,ngo[i][0]);
            twoR = myMin(twoR,ngo[i][1]);
        }
    }cout<<score(oneL,oneR,oneL,oneR)+score(twoL,twoR,twoL,twoR)<<endl;
}

