const int maxn = (int) 1e5 + 5;
int n;
int ls[maxn], rs[maxn];

bool read() {
  if (scanf("%d", &n) < 1) {
    return false;
  }
  for (int i = 0; i < n; i++) {
    scanf("%d%d", &ls[i], &rs[i]);
    ls[i]--;
  }
  return true;
}

pair<int, int> ps[maxn];

void solve() {
  int rr = inf, ll = 0;
  for (int i = 0; i < n; i++) {
    rr = min(rr, rs[i]);
    ll = max(ll, ls[i]);
  }
  for (int i = 0; i < n; i++) {
    ps[i] = make_pair(max(0, rr - ls[i]), max(0, rs[i] - ll));
  }
  sort(ps, ps + n);
  int mn = inf;
  int res = 0;
  for (int i = 0; i + 1 < n; i++) {
    mn = min(mn, ps[i].second);
    res = max(res, ps[i + 1].first + mn);
  }
  for (int i = 0; i < n; i++) {
    res = max(res, ps[0].first + ps[i].second);
  }
  for (int i = 0; i < n; i++) {
    res = max(res, (rs[i] - ls[i]) + max(0, rr - ll));
  }
