			lmn[n] = -1;

			rmx[0] = v[0].first;
			RFOR(i, 1, n) { rmx[i] = std::max(v[i].second, rmx[i - 1]); }

			unordered_map<ll, ll> toI;
			REP(i, n) {
				toI[v[i].first] = i;
			}
			FOR(i, 1, n) {
				ll ok = toI[v[i].first];
				ll val = v[i].second - v[i].first + 1;
				ll lr = lmn[ok + 1] - rmx[i - 1] + 1;
				MAX(lr, 0LL);
				val += lr;

				MAX(ans, val);
			}
		}
		dump(ans);
	}
