int main(){
  int N;
  std::cin>>N;
  std::vector<std::pair<int,std::pair<int,int>> > V(N);
  std::vector<int> L(N),R(N);
  int ans=0,maxL_ind=0,minR_ind=0;
  std::priority_queue<std::pair<int,int> > minR_in_S;
  for(int i=0;i<N;i++){
    std::cin>>L[i]>>R[i];
    R[i]++;
    V[i]={L[i],{-R[i],i}};
    ans=std::max(ans,R[i]-L[i]);
    if(L[maxL_ind]<L[i]){
      maxL_ind=i;
    }
    if(R[minR_ind]>R[i]){
      minR_ind=i;
    }
    minR_in_S.push({-R[i],i});
  }
  ans=std::max(ans,ans+std::max(0,R[minR_ind]-L[maxL_ind]));
  std::sort(V.begin(),V.end());
  bool is_T[N]={};
  is_T[minR_ind]=is_T[maxL_ind]=true;
  for(int i=0;i<N;i++){
    int ind=V[i].second.second;
    if(ind==minR_ind||ind==maxL_ind) continue;
    is_T[ind]=true;
    std::pair<int,int> p=minR_in_S.top();
    while((is_T[p.second]==true)&&minR_in_S.size()){
      minR_in_S.pop();
      p=minR_in_S.top();
    }
    ans=std::max(ans,std::max(0,R[p.second]-L[maxL_ind])
                      +std::max(0,R[minR_ind]-L[ind]));
  }
  std::cout<<ans<<std::endl;
  return 0;
}

