const int MAXN = 1e5+5;
#define L first
#define R second

int n;
ii LR[MAXN];
bool on1[MAXN];

set<ii> Ls, Rs;

void ADD(int i){
	Ls.insert({LR[i].L, i});
	Rs.insert({LR[i].R, i});
}
void ERASE(int i){
	auto it = Ls.find({LR[i].L, i});
	Ls.erase(it);
	it = Rs.find({LR[i].R, i});
	Rs.erase(it);
}
int CURR(){
	assert((int) Ls.size());
	auto l = Ls.end(); l--;
	auto r = Rs.begin();
	return max(0, (r->first) - (l->first) + 1);
}

int easysolve(){
	int ans = LR[0].R-LR[0].L+1;
	int ans2 = LR[1].R-LR[1].L+1;
	for(int i=2; i<(int)n; i++) mxze(ans2, LR[i].R-LR[i].L+1);
	return ans+ans2;
}

int main(){
	scan(n);
	for(int i=0; i<(int)n; i++)
		scan(LR[i].L, LR[i].R);


	for(int i=1; i<(int)n; i++){
		if(LR[i].R < LR[0].R || (LR[i].R == LR[0].R && LR[i].L > LR[0].L))
			swap(LR[i], LR[0]);
	}
	for(int i=0; i<(int)n; i++) if(LR[i].L <= LR[0].L) on1[i] = true;
	for(int i=0; i<(int)n; i++) if(!on1[i]) ADD(i);

	int ans = 0;
	if(Rs.size() == 0){
		printf("%d\n",easysolve());
		return 0;
	}
	mxze(ans, LR[0].R-LR[0].L+1 + CURR());
	vector<ii> ch;
	for(int i=1; i<(int)n; i++){
		if(LR[0].L < LR[i].L && LR[i].L <= LR[0].R){
			ch.pb({LR[i].L, i});
		}
	}
	sort(all(ch));
	for(int i=0; i<(int)ch.size(); i++){
		int j = ch[i].second, nl = ch[i].first;
		ERASE(j);
		if(Ls.size()){
			mxze(ans, LR[0].R-nl+1 + CURR());
		}
	}
	printf("%d\n",ans);
}

