using namespace std;
using ll =  long long;
using ld = long double;

ll solve (vector<pair<ll, ll>> &vv) {
	int n = vv.size ();
	sort (vv.begin (), vv.end ());
	ll ar[n] = {}, br[n] = {};
	ll st = 1, en = INF, ma = 0;
	for (ll i = 0; i < n; i++) {
		st = vv[i].first, en = min (en, vv[i].second);
		if (st > en) {
			break;
		}
		ar[i] = en - st + 1;
	}
	st = 1, en = INF;
	for (ll i = n - 1; i >= 0; i--) {
		st = max (vv[i].first, st), en = min (vv[i].second, en);
		if (st > en) {
			break;
		}
		br[i] = en - st + 1;
	}
	for (ll i = 0; i < n - 1; i++) {
		ma = max (ar[i] + br[i + 1], ma);
	}
	return ma;
}

int main () {
	ll n;
	cin >> n;
	ll ma = 0;
	vector<pair<ll, ll>> vp, vv;
	for (ll i = 0; i < n; i++) {
		ll l, r;
		cin >> l >> r;
		ma = max (ma , r - l + 1);
		vv.push_back (make_pair (l, r));
		vp.push_back (make_pair (INF - r + 1, INF - l + 1));
	}
	ma = max (solve (vv), ma);
	ma = max (solve (vp), ma);
	cout << ma << "\n";
}

