const ll INF = 1e17;

struct SegmentTree {
  private:
    int n;
    vector<ll> node;

  public:
    SegmentTree(vector<ll> v) {
        int sz = v.size();
        n = 1;
        while(n < sz)
            n *= 2;
        node.resize(2 * n - 1, INF);
        for(int i = 0; i < sz; i++)
            node[i + n - 1] = v[i];
        for(int i = n - 2; i >= 0; i--)
            node[i] = min(node[2 * i + 1], node[2 * i + 2]);
    }

    void update(int x, ll val) {
        x += (n - 1);
        node[x] = val;
        while(x > 0) {
            x = (x - 1) / 2;
            node[x] = min(node[2 * x + 1], node[2 * x + 2]);
        }
    }

    ll getmin(int a, int b, int k = 0, ll l = 0, ll r = -1) {
        if(r < 0)
            r = n;
        if(r <= a || b <= l)
            return INF;
        if(a <= l && r <= b)
            return node[k];

        ll vl = getmin(a, b, 2 * k + 1, l, (l + r) / 2);
        ll vr = getmin(a, b, 2 * k + 2, (l + r) / 2, r);
        return min(vl, vr);
    }
};

int main() {
    ll N;
    cin >> N;
    vector<pll> A(N);
    rep(i, N) {
        ll l, r;
        cin >> l >> r;
        A[i] = make_pair(l, r);
    }
    sort(All(A));
    ll res = 0;
    vector<ll> v(N);
    SegmentTree st(v);
    rep(i, N) st.update(i, A[i].second);
    for(int i = 1; i < N; i++) {
        ll a1 = 0, a2 = 0;
        if(st.getmin(0, i) - A[i - 1].first >= 0)
            a1 = max(st.getmin(0, i) - A[i - 1].first + 1LL, 0LL);
        if(st.getmin(i, N) - A[N - 1].first >= 0)
            a2 = max(st.getmin(i, N) - A[N - 1].first + 1LL, 0LL);
        res = max(res, a1 + a2);
    }
    for(int i = 0; i < N; i++) {
        ll a1 = 0, a2 = 0;
        a1 = A[i].second - A[i].first + 1;
        a2 = max(min(st.getmin(i + 1, N), st.getmin(0, i)) - A[N - 1].first +
                     1LL,
                 0LL);
        res = max(res, a1 + a2);
    }
    cout << res << endl;
    return 0;
}

