const ll UP = 1000000000+1;

pll meet(pll &a, pll &b){
	pll x, y;
	x.first = a.first;
	x.second = a.second;
	y.first = b.first;
	y.second = b.second;

	pll res;

	if(x.first>y.first) swap(x, y);

	if(x.first == -1 || y.first == -1){
		res = {-1, -2};
	}else if(y.first<=x.second){
		res = {y.first, min(x.second, y.second)};
	}else{
		res = {-1, -2};
	}

	return res;
}

