using P = pair<long long, long long>;

long long n;
vector<P> v, l, r;

long long solve();

int main() {
  cin >> n;
  v.resize(n);
  for(int i = 0; i < n; ++i) cin >> v[i].se >> v[i].fi;
  cout << solve() << endl;
  return 0;
}

long long solve() {
  sort(v.begin(), v.end());
  l.assign(n, {0, 0});
  r.assign(n, {0, 0});
  for(int i = 0; i < n; ++i) {
    l[i].se = v[0].fi;
    if(i == 0)
      l[i].fi = v[0].se;
    else
      l[i].fi = max(l[i - 1].fi, v[i].se);
  }
  for(int i = n - 1; i >= 0; --i) {
    r[i].se = v[i].fi;
    if(i == n - 1)
      r[i].fi = v[i].se;
    else
      r[i].fi = max(r[i + 1].fi, v[i].se);
  }
  long long ans = 0;
  for(int i = 0; i < n; ++i) {
    long long now = v[i].fi - v[i].se + 1;
    now += max(0LL, v[0].fi - max(l[i].fi, r[i].fi) + 1);
    ans = max(ans, now);
  }
  for(int i = 0; i < n - 1; ++i) {
    long long now = 0;
    now = max(0LL, l[i].se - l[i].fi + 1);
    now += max(0LL, r[i + 1].se - r[i + 1].fi + 1);
    ans = max(ans, now);
  }
  return ans;
}

