using namespace std;

struct interval{
	int a,b;
};

int solve0(const vector<interval>& I){
	int n=I.size();
	multiset<int> L,R;
	rep(i,n){
		L.emplace(I[i].a);
		R.emplace(I[i].b);
	}

	int res=0;
	rep(i,n){
		int l=I[i].a,r=I[i].b;
		L.erase(L.find(l));
		R.erase(R.find(r));
		int l2=*L.rbegin();
		int r2=*R.begin();
		res=max(res,max(r-l+1,0)+max(r2-l2+1,0));
		L.emplace(l);
		R.emplace(r);
	}
	return res;
}

int solve(const vector<interval>& I){
	int n=I.size();
	multiset<int> L,R;
	rep(i,n-1){
		L.emplace(I[i+1].a);
		R.emplace(I[i+1].b);
	}

	int res=0;
	int l=I[0].a,r=I[0].b;
	rep(i,n-1){
		int l2=*L.rbegin();
		int r2=*R.begin();
		res=max(res,max(r-l+1,0)+max(r2-l2+1,0));
		l=max(l,I[i+1].a);
		r=min(r,I[i+1].b);
		L.erase(L.find(I[i+1].a));
		R.erase(R.find(I[i+1].b));
	}
	return res;
}

int main(){
int q; cin>>q;
rep(_,q){
	int n; cin>>n;
	vector<interval> I(n);
	rep(i,n) cin>>I[i].a>>I[i].b;

	int ans=solve0(I);
	sort(I.begin(),I.end(),[](const interval& I,const interval& J){ return tie(I.a,I.b)<tie(J.a,J.b); });
	ans=max(ans,solve(I));
	sort(I.begin(),I.end(),[](const interval& I,const interval& J){ return tie(I.b,I.a)<tie(J.b,J.a); });
	ans=max(ans,solve(I));
	sort(I.begin(),I.end(),[](const interval& I,const interval& J){ return tie(I.a,J.b)<tie(J.a,I.b); });
	ans=max(ans,solve(I));
	sort(I.begin(),I.end(),[](const interval& I,const interval& J){ return tie(I.b,J.a)<tie(J.b,I.a); });
	ans=max(ans,solve(I));
	cout<<ans<<endl;
}
	return 0;
}

