#define N_MAX (1<<17)
#define INF 1000000000000000000LL

struct segmn{
  long long nn;
  long long dat[(2 * N_MAX) - 1];

  void init(long long n1){
    nn = 1;

    while(nn < n1)nn *= 2;

    for(long long i = 0; i < 2 * nn - 1; i++){
      dat[i] = INF;
    }
  }

  void update(long long k, long long a){
    k += nn - 1;
    dat[k] = a;
    while(k > 0){
      k = (k - 1) / 2;
      dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
    }
  }

  long long query(long long a, long long b, long long k, long long l, long long r){
    if(r <= a || b <= l)return INF;

    if(a <= l && r <= b){
      return dat[k];
    }
    else{
      long long vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
      long long vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
      return min(vl, vr);
    }
  }

  long long query(long long a, long long b){
    return query(a,b,0,0,nn);
  }
}segmn1,segmn2;

struct segmx{
  long long nn;
  long long dat[(2 * N_MAX) - 1];

  void init(long long n1){
    nn = 1;

    while(nn < n1)nn *= 2;

    for(long long i = 0; i < 2 * nn - 1; i++){
      dat[i] = -INF;
    }
  }

  void update(long long k, long long a){
    k += nn - 1;
    dat[k] = a;
    while(k > 0){
      k = (k - 1) / 2;
      dat[k] = max(dat[k * 2 + 1], dat[k * 2 + 2]);
    }
  }

  long long query(long long a, long long b, long long k, long long l, long long r){
    if(r <= a || b <= l)return -INF;

    if(a <= l && r <= b){
      return dat[k];
    }
    else{
      long long vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
      long long vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
      return max(vl, vr);
    }
  }

  long long query(long long a, long long b){
    return query(a,b,0,0,nn);
  }
}segmx2;

