void solve(){
	int n;
	cin>>n;

	vector<pa> ve;
	for(int i=0;i<n;i++){
		int y,yy;
		cin>>y>>yy;
		yy++;
		ve.pb(mp(y,yy));
	}
	sort(ve.begin(),ve.end());
	int ans=-1;
	Segmin mi;
	Segmax ma;
	mi.shoki1();
	ma.shoki1();
	for(int i=0;i<n;i++){
		ma.vec[ma.cor+i].first=ve[i].first;
		mi.vec[mi.cor+i].first=ve[i].second;

	}
	mi.shoki2();
	ma.shoki2();

	for(int i=0;i<n;i++){
		int t,s;
		if(i==0){
			 t=mi.segmin(i+1,n).first;
			 s=ma.segmax(i+1,n).first;
		}
		else if(i==n-1){
			 t=mi.segmin(0,i).first;
			 s=ma.segmax(0,i).first;	
		}
		else{
			 t=min(mi.segmin(0,i).first,mi.segmin(i+1,n).first);
			 s=max(ma.segmax(0,i).first,ma.segmax(i+1,n).first);		
		}
			ans=max(ans,ve[i].second-ve[i].first+max(0ll,t-s));

	}
	for(int i=0;i<n-1;i++){
			int t=mi.segmin(0,i+1).first;
			int s=ma.segmax(0,i+1).first;	

			int tt=mi.segmin(i+1,n).first;
			int ss=ma.segmax(i+1,n).first;	
		ans=max(ans,max(0ll,t-s)+max(0ll,tt-ss));


	}
	cout<<ans<<endl;

}
