typedef class Segment {
public:
    int l, r;

    Segment() { }
    Segment(int l, int r) : l(l), r(r) {    }

    Segment operator & (Segment b) const {
        return Segment(max(l, b.l), min(r, b.r));
    }
    int length() {
        return max(r - l + 1, 0);
    }
    boolean operator < (Segment b) const {
        return r < b.r;
    }
} Segment;

