typedef pair<Long, Long> pll;


pll intersect(pll a, pll b) {
    if (a.Y < b.X || b.Y < a.X)
        return {0,0};

    return {
        max(a.X, b.X),
        min(a.Y, b.Y)
    };
}


set<pll> vx;
set<pll, greater<> > vy;

void erase(pll p) {
    vx.erase(p);
    vy.erase({p.Y, p.X});
}


pll findo(pll a) {
    if (!vx.empty()) {
        auto it = vx.upper_bound({a.Y+1, 0});
        if (it != vx.end())
            return *it;
    }

    if (!vy.empty()) {
        auto it = vy.upper_bound({a.X - 1, 1e10});
        if (it != vy.end())
            return {it->second, it->first};
    }
    return {0,0};
}


Long sss(pll p) {
    if (p.X == 0)
        return 0;
    return p.Y - p.X + 1;
}

class BTwoContests {
public:
    void solve(std::istream& in, std::ostream& out) {
        fastIO();
        int n;
        in >> n;
        vector<pll> v(n);
        in >> v;

        Long ans = 0;
        Long miny = 1e12;
        Long maxx = 0;

        vx.clear();
        vy.clear();

        for(auto p: v) {
            ans = max(ans, sss(p));
            maxx = max(maxx, p.X);
            miny = min(miny, p.Y);

            vx.insert(p);
            vy.insert({p.Y, p.X});
        }

        sort(ALL(v));
        if (vx.size() <= 2) {
            out << sss(v[0]) + sss(v.back()) << endl;
            return;
        }

        // two distinct
        if (maxx > miny) {
            pll a, b;
            for(auto p: v) {
                if (p.X == maxx)
                    a = p;
                if (p.Y == miny)
                    b = p;
            }

            erase(a);
            erase(b);

            bool changed = true;

            while (changed) {
                changed = false;
                auto oa = findo(a);
                if (oa.X != 0) {
                    b = intersect(oa, b);
                    erase(oa);
                    changed = true;
                }

                auto ob = findo(b);
                if (ob.X != 0) {
                    a = intersect(a, ob);
                    erase(ob);
                    changed = true;
                }

            }

            if (sss(a) == 0 || sss(b) == 0) {
                out << ans << endl;
                return;
            }

            vector<pll> v;

            v.pb({sss(a), 0});
            v.pb({0, -sss(b)});
            for(auto p: vx) {
                v.pb({
                    sss(intersect(p, a)),
                    -sss(intersect(p, b))
                });
            }

            Long best = 0;

            sort(ALL(v));

            Long mn = -v[0].Y;
            FOR(i, 1, v.size()) {
                best = max(best, mn+v[i].X);
                mn = min(mn, -v[i].Y);
            }

            ans = max(ans, best);
            out << ans << endl;
            return;
        }

        if (vx.count({maxx, miny})) {
            out << ans + sss({maxx, miny}) << endl;
            return;
        }


        auto firstl = *vy.rbegin();
        firstl = {
            firstl.Y, firstl.X
        };

        erase(firstl);

        vector<pll> tod;
        for(auto p: vx) {
            if (intersect(p, firstl) == firstl)
                tod.pb(p);
        }

        Long mxsize = 0;

        for (auto p: tod) {
            erase(p);
            mxsize = max(mxsize, sss(p));
        }


        auto d2 = *vx.rbegin();

        erase(d2);
        for(auto p: vx) {
            mxsize = max(mxsize, sss(p));
        }

        ans = max(mxsize + sss(intersect(d2, firstl)), ans);

        while (!vx.empty()) {
            auto cand = *vx.rbegin();
            ans = max(ans, sss(d2) + sss(intersect(firstl, cand)));
            d2 = intersect(d2, cand);
            erase(cand);
        }

        ans = max(ans, sss(d2) + sss(firstl));

        out << ans << endl;

    }
};


int main() {
	BTwoContests solver;
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	solver.solve(in, out);
	return 0;
}

