bool compare(const pair<int, int> &a, const pair<int, int> &b) {
	if(a.first == b.first) {
		return a.second > b.second;
	} else {
		return a.first < b.first;
	}
}

int main() {
	uint N;
	cin >> N;

	vector<pair<int, int>> LR(N);
	int l, r;
	for(int i=0; i<N; i++) {
		cin >> l >> r;
		LR[i] = make_pair(l, r);
	}

	sort(LR.begin(), LR.end(), compare);
	vector<int> L(N), R(N);
	for(int i=0; i<N; i++) {
		L[i] = LR[i].first;
		R[i] = LR[i].second;
	}

	int ans = 0;
	for(int i=1; i<N; i++) {
		int c1_l = L[i-1];
		int c1_r = *min_element(R.begin(), R.begin() + i);
		int c1_p = max(0, c1_r - c1_l + 1);

		int c2_l = L.back();
		int c2_r = *min_element(R.begin() + i, R.end());
		int c2_p = max(0, c2_r - c2_l + 1);

		ans = max(ans, c1_p + c2_p);
	}

	cout << ans << endl;
}

