int main(){

  lint n; cin >> n;
  vector<lint> l(n);
  vector<lint> r(n);
  for(int i = 0; i < n; i++) cin >> l[i] >> r[i];

  vector<pair<lint, lint>> p(n);
  for(int i = 0; i < n; i++) {
    p[i] = {r[i], i};
  } 

  sort(ALL(p));

  lint l1 = l[p[0].second];
  lint r1 = r[p[0].second];

  vector<pair<lint, lint>> rest(n - 1);
  for(int i = 0; i < n - 1; i++) {
    rest[i] = {l[p[i + 1].second], r[p[i + 1].second]};
  }

  sort(ALL(rest));
  vector<lint> min_r(n - 1, INF);
  min_r[n - 2] = rest[n - 2].second;
  for(int i = n - 3; i >= 0; i--) min_r[i] = min(min_r[i + 1], rest[i].second);
  lint ans = 0;
  for(int i = 0; i < n - 2; i++) {
    lint tmp = r1 - rest[i].first + min_r[i + 1] - rest[n - 2].first;
    // cerr << r1 << " " << rest[i].first << " " << min_r[i + 1] << " " << rest[n - 2].first << endl;
    ans = max(ans, tmp);
  }


  cout << ans + 2 << endl;
  return 0;
}

