int main() {
	cin >> N;
	ll ans = 0;
	vector< range > R(N);
	rep(i, N) cin >> R[i].l >> R[i].r;
	sort(R.begin(), R.end());
	vector< int > l(N), r(N);
	rep(i, N) {
		l[i] = R[i].l;
		r[i] = R[i].r;
		chmax(ans, (ll)(r[i] - l[i] + 1));
	}
	SegT1 rmin(r);
	SegT2 lmax(l);
	ans += max(rmin.get(0, N) - lmax.get(0, N) + 1, 0LL);
	ll ansl = 0, ansr = INT_MAX / 2;
	rep(i, N - 1) {
		range tmp = R[i];
