		L.push_back(l);
		R.push_back(pair<int64_t, int>(r, i));
		length.push_back(r - l + 1);
	}
	sort(length.begin(), length.end());
	sort(R.begin(), R.end());

	//ilu[n]はR[n]までを一方に入れたときのありうるLの一番大きい(範囲が狭くなる)値
	vector<int64_t> ilu(N);
	int64_t M = L[0];
	ilu[0] = L[R[0].second];
	for (int i = 1; i < N; i++)
	{
		M = min(M, L[i]);
		ilu[i] = max(ilu[i - 1], L[R[i].second]);
	}
	//iln[n]はR[n]までを一方に入れたときの残りのLの一番大きい(範囲が狭くなる)値
	vector<int64_t> iln(N - 2);
	if (N >= 3)
		iln[N - 3] = L[R[N - 1].second];
	for (int i = N - 4; i >= 0; i--)
	{
		iln[i] = max(iln[i + 1], L[R[i + 2].second]);
	}
	//vector<int64_t> fun(N);
	int64_t fun = 0;
	for (int i = 0; i < N - 1; i++)
	{
