			break;
		}

		long damage = max(R[0].first - iln[i], (int64_t)0) - max(R[0].first - ilu[i], (int64_t)0);
		long damage2 = max(R[i + 1].first - iln[i], (int64_t)0) - max(R[i + 1].first - L[R[i + 1].second], (int64_t)0);
		if (damage > damage2)
