class Contest {
    multiset<ll> start, end;
public:
    void push(ll l, ll r) {
        start.insert(l);
        end.insert(r);
    }

    void pop(ll l, ll r) {
        start.erase(start.find(l));
        end.erase(end.find(r));
    }

    ll count() {
        ll l = *start.rbegin();
        ll r = *end.begin();
        if (r < l) return 0;
        ll now = r - l + 1;

        return now;
    }

};

