ll intersection(pll a, pll b) {
    return max(min(a.y, b.y) - max(a.x, b.x) + 1, 0LL);
}
ll best(pll st, pll en, vector <pll> &ranges) {
    if(st.y > en.x) {
        swap(st, en);
    }
    if(st == en) {
        if(count(all(ranges), st) == 1) {
            return 0;
        }
    }
    pll lef = st;
    pll rig = en;
    vector <pll> yo;
    for(auto u : ranges) {
        yo.push_back({intersection(u, lef), intersection(u, rig)});
    }
    ll ans = 0;
    sort(all(yo));
    set <ll> mn;
    mn.insert(intersection(rig, rig));
    for(int i = 0; i < yo.size(); i++) {
        ans = max(ans, *mn.begin() + yo[i].first);
        mn.insert(yo[i].second);
    }
    return ans;
}
