template<class T> struct MinSeg { 
	const T ID = LLONG_MAX; // comb(ID,b) must equal b
	T combine(T a, T b) { return min(a, b);} 
	int n; vector<T> seg;
	void init(int _n) { n = _n; seg.assign(2*n,ID);}

	void update(int p, T value) {	// set value at position p
		seg[p += n] = value;
		for (p /= 2; p; p /= 2) seg[p] = combine(seg[2*p], seg[2*p+1]);
	}

	T query(int l, int r) {	 // sum on interval [l, r]
		T ra = ID, rb = ID; 
		for (l += n, r += n+1; l < r; l /= 2, r /= 2) {
			if (l&1) ra = combine(ra,seg[l++]);
			if (r&1) rb = combine(seg[--r],rb);
		}
		return combine(ra,rb);
	}
};

MinSeg<ll> minSeg;

int solve1(vector<pii> probs) {
	// Assume min(R) and max(R) are in same set
	auto minR = min_element(probs.begin(), probs.end(), [] (const pii lhs, const pii rhs) {
		return lhs.second < rhs.second || (lhs.second == rhs.second && lhs.first > rhs.first);
	});

	auto maxL = max_element(probs.begin(), probs.end(), [] (const pii lhs, const pii rhs) {
		return lhs.first < rhs.first || (lhs.first == rhs.first && lhs.second < rhs.second);
	});

	int largest = 0;
	for (auto it = probs.begin(); it != probs.end(); ++it) {
		if (it != minR && it != maxL) largest = max(largest, (*it).second - (*it).first);
	}
	return largest + max((*minR).second - (*maxL).first, 0);
}

pii minRP;
pii maxLP;
int solve2(vector<pii> probs) {
	// Assume min(R) and max(R) are in different sets

	auto minR = min_element(probs.begin(), probs.end(), [] (const pii lhs, const pii rhs) {
		return lhs.second < rhs.second || (lhs.second == rhs.second && lhs.first > rhs.first);
	});
	minRP = *minR;
	probs.erase(minR);

	auto maxL = max_element(probs.begin(), probs.end(), [] (const pii lhs, const pii rhs) {
		return lhs.first < rhs.first || (lhs.first == rhs.first && lhs.second < rhs.second);
	});
	maxLP = *maxL;
	probs.erase(maxL);

	auto it = probs.begin();
	while (it != probs.end()) {
		pii range = *it;
		if (range.first <= minRP.first || range.second >= maxLP.second) {
			it = probs.erase(it);
		} else {
			++it;
		}
	}

	sort(probs.begin(), probs.end());
	minSeg.init(probs.size());
	F0R(i, probs.size()) minSeg.update(i, probs[i].second);

	int best = max(minRP.second - minRP.first, 0) + max((int)minSeg.query(0, probs.size()-1) - maxLP.first, 0);
	F0R(i, probs.size()) {
		int r = (i != probs.size() - 1) ? minSeg.query(i+1, probs.size()-1) : maxLP.second;
		best = max(best, max(minRP.second - probs[i].first, 0) + max((int)r - maxLP.first, 0));
	}
	if (probs.size() == 0) best = max(minRP.second - minRP.first, 0) + max(maxLP.second - maxLP.first, 0);
	return best;
}
int main() {
    ios::sync_with_stdio(0), cin.tie(0), cout.tie(0);

	int N; cin >> N;

	vector<pii> probs (N);
	F0R(i, N) {
		int L, R; cin >> L >> R; R++;
		probs[i] = {L, R};
	}

	print(max(solve1(probs),solve2(probs)));

}

