using namespace std;
typedef long long ll;
typedef pair<int, int> P;
const ll MOD = 1e9 + 7;
P intersect(P a, P b) {
	int l = max(a.first, b.first);
	int r = min(a.second, b.second);
	if (l >= r) return P(0, 0);
	return P(l, r);
}
int length(P a) {
	return a.second - a.first;
}
P fromL[100001], fromR[100001];
int main() {
	int N;
	cin >> N;
	vector<P> vec;
	int ans = 0;
	for (int i = 0; i < N; i++) {
		int L, R;
		cin >> L >> R;
		R++;
		vec.emplace_back(L, R);
		ans = max(ans, R - L);
	}
	sort(vec.begin(), vec.end());
	vector<P> vec2;
	P p(0, 1 << 30);
	for (int i = 1; i < N; i++) {
		if (vec[i].first < vec[0].second) {
			vec2.emplace_back(vec[i].second, vec[i].first);
		}
		else {
			p = intersect(p, vec[i]);
		}
	}
	sort(vec2.begin(), vec2.end());
	for (int i = 0; i < vec2.size(); i++) swap(vec2[i].first, vec2[i].second);
	fromL[0] = P(0, 1 << 30);
	fromR[vec2.size()] = P(0, 1 << 30);
	for (int i = 0; i < vec2.size(); i++) {
		fromL[i + 1] = intersect(fromL[i], vec2[i]);
	}
	for (int i = (int)vec2.size() - 1; i >= 0; i--) {
		fromR[i] = intersect(fromR[i + 1], vec2[i]);
	}
	for (int i = 0; i <= vec2.size(); i++) {
		P p1 = intersect(vec[0], fromL[i]);
		P p2 = intersect(p, fromR[i]);
		if (p2 == P(0, 1 << 30)) continue;
		ans = max(ans, length(p1) + length(p2));
	}
	cout << ans << endl;
}

