bool cmpByL(ls a, ls b) {
  if (a.l != b.l) return a.l < b.l;
  if (a.r != b.r) return a.r > b.r;
  return a.i < b.i;
}

bool cmpByR(ls a, ls b) {
  if (a.r != b.r) return a.r < b.r;
  if (a.l != b.l) return a.l < b.l;
  return a.i < b.i;
}

bool cmpBySize(ls a, ls b) {
  return a.r - a.l < b.r - b.l;
}

ls s1[100001] = {};
ls s2[100001] = {};
ls s3[100001] = {};
bool used[100001] = {};

int main(){
  int N; cin>>N;
  for (int i=1;i<=N;i++) {
    cin>>s1[i].l>>s1[i].r;
    s1[i].i = i;
    s2[i] = s1[i];
    s3[i] = s1[i];
  }
  sort(s1+1, s1+N+1, cmpByL);
  sort(s2+1, s2+N+1, cmpByR);
  sort(s3+1, s3+N+1, cmpBySize);

  ll final_ans = 0;
  // minR+maxL in a group
  {
    ll ans = 0;
    used[s3[N].i] = 1; ans += s3[N].r - s3[N].l;

    int i=N;
    while (used[s1[i].i]) i--; ans -= s1[i].l;

    i=1;
    while (used[s2[i].i]) i++; ans += s2[i].r;

    ans+=2;
    final_ans = max(final_ans, ans);
  }

  memset(used, 0, sizeof(used));

  // maxL in a group, then minR in a group
  {
    ll this_ans = 0;
    ll ans = 0;
    used[s1[N].i] = 1; ans -= s1[N].l;

    int i=1;
    while (used[s2[i].i]) i++;
    used[s2[i].i] = 1; ans += s2[i].r;

    int j=N-1;
    for (int k=N;k>=1;k--) {
      if (used[s2[k].i]) continue;
      used[s2[k].i] = 1;
      while (used[s1[j].i]) j--;
      this_ans = max(this_ans, ans + min(s2[k].r, s1[N].r) - max(s1[j].l, s2[i].l));
    }
    this_ans+=2;
    final_ans = max(final_ans, this_ans);
  }

  memset(used, 0, sizeof(used));

  // minR in a group, then maxL in a group
  {
    ll this_ans = 0;
    ll ans = 0;
    used[s2[1].i] = 1; ans += s2[1].r;

    int i= N;
    while (used[s1[N].i]) i--;
    used[s1[i].i] = 1; ans -= s1[i].l;

    int j=N-1;
    for (int k=N;k>=1;k--) {
      if (used[s2[k].i]) continue;
      used[s2[k].i] = 1;
      while (used[s1[j].i]) j--;
      this_ans = max(this_ans, ans + min(s2[k].r, s1[i].r) - max(s1[j].l, s2[1].l));
    }
    this_ans+=2;
    final_ans = max(final_ans, this_ans);
  }
  cout << final_ans << endl;


  return 0;
}

