	sort(ALL(v));

	LL rmi = 2e9;
	vector<int> w;
	dec(i, n) {
		if(setmin(rmi, v[i].SE)) {
			if(SI(w) > 0 && v[w.back()].FI == v[i].FI) { w.pop_back(); }
			w.PB(i);
		}
	}
	reverse(ALL(w));

	LL ans = 0;
	inc(i, n) { setmax(ans, v[i].SE - v[i].FI + 1); }

	if(SI(w) == 1) {
		ans += v[w[0]].SE - v[w[0]].FI + 1;
	} else {
		LL R1 = v[w.front()].SE;
		LL L2 = v[w.back() ].FI;

		inc(i, SI(w) - 1) {
			LL L1 = v[w[i    ]].FI;
			LL R2 = v[w[i + 1]].SE;
			setmax(ans, (R1 - L1 + 1) + (R2 - L2 + 1));
		}
	}

	cout << ans << endl;

	return 0;
}

