int solve() {

    SS(int, N);
    vector<pair<int, int>> seg;
    REP(i, N) {
        SS(int, L, R);
        seg.emplace_back(L, R);
    }
    SORT(seg);

    vector<int> v_l, v_r;
    for (auto& [l, r]: seg) {
        v_l.emplace_back(l);
        v_r.emplace_back(r);
    }

    SparseTable<int> st_l(v_l, [](int a, int b){ return max(a, b);  });
    SparseTable<int> st_r(v_r, [](int a, int b){ return min(a, b);  });

    ll res = -INFF;
    REP(i, 1, N) {
        ll tmp = 0;
        {
            ll l = st_l.query(0, i);
            ll r = st_r.query(0, i);
            if (l <= r) tmp += r - l + 1;
        }
        {
            ll l = st_l.query(i, N);
            ll r = st_r.query(i, N);
            if (l <= r) tmp += r - l + 1;
        }
        chmax(res, tmp);
    }
    print(res);

    return 0;

}

