struct DJset {
	vi parent, rank, size;

	DJset(int n) : parent(n), rank(n, 1), size(n, 1) {
		rep(i,0,n) {
			parent[i] = i;
		}
	}

	int find(int i) {
		if(i == parent[i]) return i;
		return parent[i] = find(parent[i]);
	}

	void merge(int u, int v) {
		u = find(u); v = find(v);
		if(u == v) return;
		if(rank[u] > rank[v]) swap(u, v);
		parent[u] = v;
		if(rank[u] == rank[v]) ++rank[v];
		size[v] += size[u];
	}
};

