map< int, int, greater< int > > M1, M3;
map< int, int > M2, M4;

bool cmp(pair<int, int> a, pair<int, int> b)
{
    int x = (a.second == -1 ? L[a.first] : R[a.first]);
    int y = (b.second == -1 ? L[b.first] : R[b.first]);

    if(x == y)
        return a.second < b.second;

    return x < y;
}

void removex(int x, int f)
{
    if(f == 1)
        M1[x] == 1 ? M1.erase(x) : M1[x]--;
    else if(f == 2)
        M2[x] == 1 ? M2.erase(x) : M2[x]--;
    else if(f == 3)
        M3[x] == 1 ? M3.erase(x) : M3[x]--;
    else
        M4[x] == 1 ? M4.erase(x) : M4[x]--;
}

int query()
{
    if(M1.empty() || M3.empty())
        return 0;

    int x = M2.begin()->first - M1.begin()->first + 1;
    int y = M4.begin()->first - M3.begin()->first + 1;

    return max(0, x) + max(0, y);
}

