    for(int i=1; i<=N; i++)
    {
        cin >> L[i] >> R[i];
        X.push_back({i, -1});
        X.push_back({i, 1});

        M3[ L[i] ]++, M4[ R[i] ]++;
    }

    int ans = 0;
    sort(X.begin(), X.end(), cmp);

    for(auto x : X)
    {
        int indx = x.first, f = x.second;

        if(f == -1)
        {
            M1[ L[indx] ]++, M2[ R[indx] ]++;
            removex(L[indx], 3);
            removex(R[indx], 4);
        }
        else
        {
            M3[ L[indx] ]++, M4[ R[indx] ]++;
            removex(L[indx], 1);
            removex(R[indx], 2);
        }

        ans = max(ans, query());
    }

    cout << ans << "\n";
    return 0;
}

