        ans = max(ans, f(l, i));
    } else {
      int m = (l + r) / 2;
      int opt = -1;
      for (int i = opt_l; i <= opt_r; i++) {
        if (i >= m && (opt == -1 || f(m, i) > f(m, opt))) {
          opt = i;
        }
      }
      ans = max(ans, f(m, opt));
      solve(l, m, opt_l, opt);
      solve(m + 1, r, opt, opt_r);
    }
  }

