  int a = 0, b = -1;
  int a_end;
  bool zero = false;

  for (int i=1; i<n; ++i) {
    if (b == -1) {
      if (G[i][0] > G[a][1]) {
        b = i;
        a_end = i - 1;
      }
      else if (G[i][1] <= G[a][1]) {
        a = i;
      }
    }

    else {
      if (G[i][0] > G[b][1]) {
        zero = true;
        break;
      }
      else if (G[i][1] <= G[b][1]) {
        b = i;
      }
    }
  }

