  int last = b == -1 ? n-1 : a_end;
  int r = b == -1 ? n-1 : b;
  for (int i=a+1; i<=last; ++i) {
    if (b != -1 && G[i][1] < G[r][0]) a_end = i;
    else if (G[i][1] <= G[r][1]) rest.push_back(G[i]);
  }

  Graph right(rest.size(), vi(2));
  rep(i,rest.size()) {
    right[i][0] = rest[i][1];
    right[i][1] = i;
  }
