long long solve(int N, vector<int> L, vector<int> R)
{
    vector<pair<int,int>> tmp;
    for (int i=0; i<N; i++)
        tmp.push_back(make_pair(R[i], -L[i]));
    sort(tmp.begin(), tmp.end());
    for (int i=0; i<N; i++)
        R[i] = tmp[i].first,
        L[i] = -tmp[i].second;

    vector<int> L2, R2;
    L2.push_back(L[0]);
    R2.push_back(R[0]);
    int maxL = L[0];
    for (int i=1; i<N; i++)
    {
        if (L[i] > maxL)
        {
            L2.push_back(L[i]);
            R2.push_back(R[i]);
            maxL = L[i];
        }
    }
    int N2 = (int)L2.size();

    long long ans = 0;
    if (N2==1)
    {
        ans = R[0]-L[0]+1LL + R[N-1]-L[N-1]+1LL;
    }
    else
    {
        for (int i=0; i<N2-1; i++)
            ans = max(ans,
                max(0LL, R2[0]-L2[i]+1LL) +
                max(0LL, R2[i+1]-L2[N2-1]+1LL));
    }

    for (int i=0; i<N; i++)
        ans = max(ans, R[i]-L[i]+1LL);

    multiset<int> LS, RS;
    for (int i=0; i<N; i++)
    {
        LS.insert(L[i]);
        RS.insert(R[i]);
    }
    for (int i=0; i<N; i++)
    {
        LS.erase(LS.find(L[i]));
        RS.erase(RS.find(R[i]));

        ans = max(ans,
            max(0LL, R[i]-L[i]+1LL)+
            max(0LL, *RS.begin()-*LS.rbegin()+1LL));

        LS.insert(L[i]);
        RS.insert(R[i]);
    }

    return ans;
}

