// {{{ Segment Tree

// T : 要素
template <typename T>
struct SegmentTree{

    int leng;
    using F = function<T(T,T)>;
    F f;  // T*T -> T
    T ti; // (T,f) の 単位元
    vector<T> data; // 1-indexed

    SegmentTree( F f, T ti ) :
        f(f),ti(ti){}

    void init( int n ){
        leng = 1;
        while( leng < n ) leng += leng;
        data.assign(leng*2,ti);
    }

    void build( vector<T> &v ){
        int n = v.size();
        init( n );
        for (int i = 0; i < n; i++) data[leng+i] = v[i];
        for (int i = leng-1; i > 0 ; i--)
            data[i] = f(data[i<<1],data[(i<<1)|1] );
    }

    // data[a] を x で 変更
    void upda( int a, T x ){

        a += leng;

        data[a] = x;

        while( a >>= 1 ){
            data[a] = f( data[a<<1] , data[(a<<1)|1] );
        }

    }

    // [a,b)の f(演算結果) を求める
    T query(int a, int b, int k = 1, int l = 0, int r = -1 ){

        if( r == -1 ) return query(a,b,k,l,leng);

        //今探すkでの範囲がオーバーしたら単位元をを返す
        if( a>=r || b<=l ) return ti;

        //範囲内ならそのまま返す
        else if( a<=l && b>=r ){
            return data[k];
        //そうでもないなら子へ
        }else{
            T ld = query(a,b,k<<1,l,(l+r)/2);
            T rd = query(a,b,(k<<1)|1,(l+r)/2,r);
            return f(ld,rd);
        }

    }

    void dump(){
        for( int i = 1; i < leng*2; i++ ){
            cerr << "d[" << i << "]=" << data[i] << endl;
        }
    }

};

// }}}

int main() {

    int N;
    Scd(N);

    vii a(N);
    int l,r;
    int ans = 0;
    int lax = 0;
    int rin = INF;
    Rep(i,N){
        Scd2(l,r);
        r++;
        a[i] = {l,r};
        ans = max( ans, r-l );
        lax = max( lax, l );
        rin = min( rin, r );
    }

    ans = ans+max(0,rin-lax);

    vii b(N);
    Rep(i,N) b[i] = { max(0,a[i].second-lax), min(0,a[i].first-rin) };

    sort( b.begin(), b.end() );

    int sax = b[0].second;
    Repe(i,N,1){
        ans = max( ans, b[i].first - sax );
        // printf ("%d %d\n", b[i].first, b[i].second );
        sax = max( sax, b[i].second );
    }

    printf ("%d\n", ans );

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef pair<int, int> pii;
typedef pair<ll, ll> pll;

const int MAXN = 1e5;

struct Line { int L, R; };

int N;
Line A[MAXN+10];
int ans, val1[MAXN+10], val2[MAXN+10];

int main()
{
    int i, j;

    scanf("%d", &N);
    for(i=1; i<=N; i++) scanf("%d%d", &A[i].L, &A[i].R);

    int l=-1, r=1e9+1;
    for(i=1; i<=N; i++) l=max(l, A[i].L), r=min(r, A[i].R);

    if(l<=r)
    {
        int flag=-1;
        for(i=1; i<=N; i++) if(A[i].L==l && A[i].R==r) flag=i;
        if(flag!=-1) for(i=1; i<=N; i++) if(i!=flag) ans=max(ans, A[i].R-A[i].L+r-l+2);
        else
        {
            pii pl={-1, 0}, pr={1e9+1, 0};
            for(i=1; i<=N; i++)
            {
                if(A[i].R==r) pl=max(pl, pii(A[i].L, i));
                if(A[i].L==l) pr=min(pr, pii(A[i].R, i));
            }
            for(i=1; i<=N; i++)
            {
                if(i==pl.second || i==pr.second) continue;
                ans=max(ans, A[i].R-A[i].L+r-l+2);
            }
        }
    }

    sort(A+1, A+N+1, [&](const Line &p, const Line &q)
         {
             if(p.R==q.R) return p.L<q.L;
             return p.R>q.R;
         });

    int nl=-1, nr=1e9+1;
    for(i=1; i<=N; i++)
    {
        nl=max(nl, A[i].L);
        nr=min(nr, A[i].R);
        val1[i]=max(0, nr-nl+1);
    }

    nl=-1, nr=1e9+1;
    for(i=N; i>=1; i--)
    {
        nl=max(nl, A[i].L);
        nr=min(nr, A[i].R);
        val2[i]=max(0, nr-nl+1);
    }

    for(i=1; i<N; i++) ans=max(ans, val1[i]+val2[i+1]);
    printf("%d", ans);
}

