    val[i].second = r[i]+1;
  }
  sort(val,val+n,[&](const P x,const P y){
      ll xa,xb,ya,yb;
      xa = max(x.second-max_l,(ll)0);
      xb = max(x.first-min_r,(ll)0);
      ya = max(y.second-max_l,(ll)0);
      yb = max(y.first-min_r,(ll)0);
      if(xa<ya){
      return true;
      }else if(xa==ya&&xb>yb){
      return true;
      }else{
      return false;
      }
      });
  for(int i=0;i<n;i++){
    mp0[val[i].first]++;
    mp1[val[i].second]++;
  }
  for(int i=0;i<n-1;i++){
    min_r = min(min_r,val[i].second);
    mp0[val[i].first]--;
    if(mp0[val[i].first]==0){
      mp0.erase(val[i].first);
    }
    mp1[val[i].second]--;
    if(mp1[val[i].second]==0){
      mp1.erase(val[i].second);
    }
    ri = mp1.begin()->first;
    le = mp0.rbegin()->first;
    tmp = max((ll)0,ri-le);
    mp2[val[i].first]++;
