struct RangeSet {
    multiset<int> ls, rs;

    void insert(int l, int r) {
        ls.insert(l);
        rs.insert(r);
    }

    void insert(pii x) { insert(x.first, x.second); }

    void erase(int l, int r) {
        ls.erase(l);
        rs.erase(r);
    }

    void erase(pii x) { erase(x.first, x.second); }

    i64 intersectLength() const {
        return max<i64>(0, i64(*rs.begin()) - i64(*ls.rbegin()) + 1);
    }
};

i64 solve(const vector<pii> &a)
{
    RangeSet A, B;
    for (const pii e : a) A.insert(e);

    i64 ans = A.intersectLength();

    rep(i, a.size() - 1) {
        const auto e = a[i];
        A.erase(e);
        B.insert(e);
        chmax(ans, A.intersectLength() + B.intersectLength());
    }

    return ans;
}

