struct Info {
    int len;
    int l;
    int r;
};

bool operator>(const Info& lhs, const Info& rhs) {
    if (lhs.len != rhs.len) return lhs.len > rhs.len;
    if (lhs.l != rhs.l) return lhs.l < rhs.l;
    return lhs.r > rhs.r;
}

signed main() {
    cin.tie(0), cout.tie(0), ios::sync_with_stdio(false);
    int n;
    cin >> n;
    vector<Info> v;
    int l, r;
    rep (i, n) {
        cin >> l >> r;
        v.pb(Info{r - l + 1, l, r});
    }
    sort(all(v), greater<Info>());

    Info fi = v[0];

    Info se = v[n - 1];

    For(i, 1, n - 2) {
        Info tmp = v[i];
        int one = min(fi.r, tmp.r) - max(fi.l, tmp.l) + 1;
        int two = min(se.r, tmp.r) - max(se.l, tmp.l) + 1;
        chmax(one, 0LL);
        chmax(two, 0LL);

        if (fi.len - one > se.len - two) {
            int newl = max(se.l, tmp.l);
            int newr = min(se.r, tmp.r);
            int newlen = max(0LL, newr - newl + 1);
            se = Info{newlen, newl, newr};
        } else {
            int newl = max(fi.l, tmp.l);
            int newr = min(fi.r, tmp.r);
            int newlen = max(0LL, newr - newl + 1);
            fi = Info{newlen, newl, newr};
        }
    }
    print(fi.len + se.len);

    return 0;
}

