const int maxn = (int)4e5 + 10;
int l[maxn], r[maxn];

int t[4 * maxn];
int st[4 * maxn];

void sets(int it, int x) {
	t[it] += x;
	st[it] += x;
}

void push(int it) {
	if (st[it] != 0) {
		sets(2 * it, st[it]);
		sets(2 * it + 1, st[it]);
		st[it] = 0;
	}
}

void change(int it, int l, int r, int lm, int rm, int x) {
	if (l == lm && r == rm) {
		sets(it, x);
	}
	else {
		push(it);
		int m = (l + r) >> 1;

		if (rm <= m) {
			change(2 * it, l, m, lm, rm, x);
		}
		else if (lm > m) {
			change(2 * it + 1, m + 1, r, lm, rm, x);
		}
		else {
			change(2 * it, l, m, lm, m, x);
			change(2 * it + 1, m + 1, r, m + 1, rm, x);
		}

		t[it] = max(t[2 * it], t[2 * it + 1]);
	}
}

bool cmp(pii a, pii b) {
	if (a.first != b.first) {
		return a.first < b.first;
	}

	return a.second > b.second;
}

ll inter(pii a, pii b) {
	a.first = max(a.first, b.first);
	a.second = min(a.second, b.second);
	return max(0, a.second - a.first + 1);
}

