	if (n != 1)
		for (int i = 0; i < n; i++) {
			lm.erase(lm.find(l[i]));
			rm.erase(rm.find(r[i]));

			ans = max(ans, (ll)r[i] - l[i] + 1 + max(0, (*rm.begin()) - (*lm.rbegin()) + 1));

