		[](const PII& a, const PII& b) { 
			return make_pair(a.R, a.L) < make_pair(b.R, b.L); 
		});

	LL best = 0; PII tot(1, MAX);
	for (auto& e: range) {
		best = max(best, len(e));
		tot = merge(tot, e);
	}
	LL ans = len(tot) + best;

	auto first = range[0];
	LL rmin = range[0].R;
	range.erase(range.begin());
	// sort(range.begin(), range.end());
	vector<PII> lt;
	PII rest(1, MAX);
	bool empty = true;
	for (auto& e: range) {
		if (e.L <= rmin) {
			lt.push_back(e);
		} else {
			rest = merge(rest, e);
			empty = false;
		}
	}
	sort(lt.rbegin(), lt.rend(),
		[&](const PII& a, const PII& b) {
			return make_pair(max(first.L, a.L), a.R) < make_pair(max(first.L, b.L), b.R); 
		});
	for (auto& e: lt) {
		if (!empty) ans = max(ans, len(rest) + len(merge(e, first)));
		rest = merge(rest, e);
		empty = false;
	}
	ans = max(ans, len(rest) + len(first));

	cout << ans << endl;

#ifdef LOCAL_EXEC
	range.push_back(first);
	brute(range, ans);
#endif

	return 0;
}

