typedef long long LL;

const int N=100000,INF=(1<<30)-1;

int n,mn;
struct seg{
  int l,r;
  seg(int L=0,int R=0){l=L;r=R;}
}a[N+9];

bool cmp(const seg &a,const seg &b){return a.l<b.l;}

int ans;

void into(){
  scanf("%d",&n);
  mn=INF;
  int l=1,r=INF;
  for (int i=1;i<=n;++i){
	scanf("%d%d",&a[i].l,&a[i].r);
	mn=min(mn,a[i].r);
	ans=max(ans,a[i].r-a[i].l+1);
	l=max(l,a[i].l);
	r=min(r,a[i].r);
  }
  ans+=max(r-l+1,0);
}

void Get_ans(){
  sort(a+1,a+n+1,cmp);
  int l=1,r=INF;
  for (int i=n;i>1;--i){
	if (a[i].r==mn) return;
	l=max(l,a[i].l);
	r=min(r,a[i].r);
	ans=max(ans,max(r-l+1,0)+max(mn-a[i-1].l+1,0));
  }
}

void work(){
  Get_ans();
}

void outo(){
  printf("%d\n",ans);
}

