int solve(vpii&lr)
{
	int n=lr.size();
	int ans=0;
	vi l(n), r(n), w(n);

	sort(lr.begin(), lr.end());

	for(int i=0;i<n;i++)
	{
		l[i]=lr[i].first;
		r[i]=-lr[i].second;
		w[i]=r[i]-l[i]+1;
		max_u(ans, w[i]);
	}

	vi lminr(n), rminr(n), rmaxl(n);

	lminr[0]=r[0];
	for(int i=1;i<n;i++)
	{
		lminr[i]=min(lminr[i-1], r[i]);
	}

	rminr[n-1]=r[n-1];
	rmaxl[n-1]=l[n-1];
	for(int i=n-1-1;i>=0;i--)
	{
		rminr[i]=min(rminr[i+1], r[i]);
		rmaxl[i]=max(rmaxl[i+1], l[i]);
	}

	for(int i=0;i+1<n;i++)
	{
		int ans1st=max(lminr[i]-l[i]+1, 0);
		int ans2nd=max(rminr[i+1]-rmaxl[i+1]+1, 0);
		max_u(ans, ans1st+ans2nd);
	}
	sort(r.begin(), r.end());
	sort(l.rbegin(), l.rend());
//dump(r, "sort r");
//dump(l, "sort l");
	for(int i=0;i<n;i++)
	{
		int ar=r[0], al=l[0];
		if(al==lr[i].first) al=l[1];
		if(ar==-lr[i].second) ar=r[1];
		int aw=max(ar-al+1, 0);
		max_u(ans, w[i]+aw);
	}

	return ans;
}


int main(void)
{
	int n;

	while(scanf("%d", &n)==1)
	{
		vi l(n), r(n), w(n);
		vpii lr(n);
		int ans=0;

		for(int i=0;i<n;i++)
		{
			scanf("%d%d", &lr[i].first, &lr[i].second);
			lr[i].second=-lr[i].second;
		}
		ans=solve(lr);

		printf("%d\n", ans);
	}
	return 0;
}

