    }

    for (int i = 0, now = 0; i < end; i ++)
    {
      now += in[i];
      filled[i] = now;
      now -= out[i];
    }
    DEBUG {
      for (int i = 0; i < end; i ++) printf("%3d%c", filled[i], i < end - 1 ? ' ' : '\n');
      for (int i = 0; i < end; i ++) printf("%3lld%c", decompress[i], i < end - 1 ? ' ' : '\n');
    }

    bool got = false; int zero = 0;
    for (int i = 0; i < end; i ++)
    {
      if (filled[i] >= 2)
      {
        int j = i;
        while (j + 1 < end && filled[j + 1] >= 2) j ++;
        for (int k = i + 1; k + 1 < j; k ++)
        {
          lli now = decompress[k] - decompress[i] + 1 + decompress[j] - decompress[k + 1] + 1;
          DEBUG printf("%d %d %d %d - %lld\n", k, i, j, k + 1, now);
          ans = max(ans, now);
        }
        i = j;
        got = true;
      }
    }
    for (int i = 0; i < end; i ++)
    {
      if (filled[i] == 0)
      {
        int j = i;
        while (j + 1 < end && filled[j + 1] == 0) j ++;
        ans = max(ans, decompress[i - 1] - decompress[0] + 1 + decompress[end] - decompress[j + 1] + 1);
        i = j;
        zero ++;
      }
    }
    printf("%lld\n", ans);
  }

  return 0;
}

