		rmap[r].insert(l);
		//lmap.insert(make_pair(l, r));
		//rmap.insert(make_pair(r, l));
	}

	if(lmap.size() == 1 && rmap.size() == 1) {
		ans = len(*ls.begin(), *rs.begin()) * 2;
	}

	bool first = true;
	int cl, cr;
	while(ls.size() > 1) {
		assert(ls.size() == rs.size());

		auto li = ls.rbegin();
		auto lri = rs.begin();
		int lres = *li;
		int ll = lres;
		int lr = 1000000000;
		for(int rval : lmap[lres]) {
			lr = min(lr, rval);
			li++;

			if(rval == *lri) {
				lri++;
			}
		}

		auto ri = rs.begin();
		auto rli = ls.rbegin();
		int rres = *ri;
		int rl = 1;
		int rr = rres;
		for(auto it = rmap[rres].rbegin(); it != rmap[rres].rend(); it++) {
			int lval = *it;
			rl = max(rl, lval);
			ri++;

			if(lval == *rli) {
				rli++;
			}
		}

		if(first) {
			first = false;
		}
		else {
			ll = max(ll, cl);
			lr = min(lr, cr);

			rl = max(rl, cl);
			rr = min(rr, cr);
