using namespace std;
typedef long long ll;
template <typename T>
using V = vector<T>;
using VL = V<ll>;
using VVL = V<VL>;
template <typename T, typename U>
using P = pair<T, U>;
using PL = P<ll, ll>;
using VPL = V<PL>;

ll calc(PL range) { return range.second - range.first + 1; }

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  ll N;
  cin >> N;
  VPL cons(N);
  rep(i, N) {
    ll l, r;
    cin >> l >> r;
    cons[i] = {l, r};
  }

  PL f = cons[0];
  PL s = cons[1];

  rep(i, N) {
    if (i == 0 || i == 1) continue;
    auto c = cons[i];
    ll add_f, add_s, add_t;

    PL new_f = {max(f.first, c.first), min(f.second, c.second)};
    add_f = calc(new_f) + calc(s);

    PL new_s = {max(s.first, c.first), min(s.second, c.second)};
    add_s = calc(f) + calc(new_s);

    PL new_t = {max(f.first, s.first), min(f.second, s.second)};
    add_t = calc(c) + calc(new_t);

    ll m = max(max(add_f, add_s), add_t);
    if (m == add_f) {
      f = new_f;
    } else if (m == add_s) {
      s = new_s;
    } else if (m == add_t) {
      f = new_t;
      s = c;
    }
  }

  ll res = calc(f) + calc(s);
  cout << res << endl;
  return 0;
}

