	for(int i = 0;i < N;i++){
		if(Rmin > R[i]){
			Rmin = R[i];
			Rmin_count = 0;
		}else if(Rmin == R[i]){
			Rmin_count++;
		}
	}
	Int Lmax2 = -INF, Rmin2 = INF;
	for(int i = N - 1;i >= 0;){
		if(Rmin < L[i]){
			Lmax2 = max(Lmax2, L[i]);
			Rmin2 = min(Rmin2, R[i]);
			i--;
