  vector<pi> P(N);
  i64 ans = 0;
  REP(0, N, i) {
    cin >> P[i].first >> P[i].second;
    P[i].second += 1;

    //ans = max(ans, P[i].second - P[i].first);
  }
  sort(all(P));

  i64 L1, R1, L2, R2;
  L1 = P[0].first, R1 = P[0].second;
  L2 = P[1].first, R2 = P[1].second;
  REP(2, N, i) {
    i64 L1_1 = max(L1, L2), R1_1 = min(R1, R2);
    i64 L2_1 = P[i].first, R2_1 = P[i].second;
    i64 V1 = max(0LL, R1_1 - L1_1) + max(0LL, R2_1 - L2_1);

    i64 L1_2 = max(L1, P[i].first), R1_2 = min(R1, P[i].second);
    i64 L2_2 = L2, R2_2 = R2;
    i64 V2 = max(0LL, R1_2 - L1_2) + max(0LL, R2_2 - L2_2);

    i64 L1_3 = max(L2, P[i].first), R1_3 = min(R2, P[i].second);
    i64 L2_3 = L1, R2_3 = R1;
    i64 V3 = max(0LL, R1_3 - L1_3) + max(0LL, R2_3 - L2_3);

    if(V1 > V2 && V1 > V3) {
      L1 = L1_1, R1 = R1_1;
      L2 = L2_1, R2 = R2_1;
    }
    else if(V2 > V1 && V2 > V3) {
      L1 = L1_2, R1 = R1_2;
      L2 = L2_2, R2 = R2_2;
    }
    else {
      L1 = L1_3, R1 = R1_3;
      L2 = L2_3, R2 = R2_3;
    }
  }

  cout << max(0LL, R1 - L1) + max(0LL, R2 - L2) << endl;

  return 0;
}

