	for(int i=0; i<N; i++){
		cin >> L[i] >> R[i];
		if(Min>R[i]){
			Min=R[i];
			min_idx=i;
		}
		if(Max<L[i]){
			Max=L[i];
			max_idx=i;
		}
	}

