pair<long long, long long> find_lr (const vector<pair<long long, long long>> &a) {
    long long vl = 0, vr = numeric_limits<long long>::max();
    for (const pair<long long, long long> &p : a) {
        chmax(vl, p.first);
        chmin(vr, p.second);
    }
    return make_pair(vl, vr);
}

int main() {
    int n;
    cin >> n;
    vector<pair<long long, long long>> dat;
    for (int i = 0; i < n; i++) {
        long long l, r;
        cin >> l >> r;
        dat.emplace_back(l, r + 1);
    }

    auto [l, r] = find_lr(dat);

    auto f = [&] (const pair<long long, long long> &s, const pair<long long, long long> &t) {
        long long al = max(s.second - l, 0LL), ar = max(t.second - l, 0LL);
        if (al == ar) return (max(r - s.first, 0LL) < max(r - t.first, 0LL));
        return (al < ar);
    };
    sort(dat.begin(), dat.end(), f);

    long long vr = dat[0].second, vl = dat[n - 1].first;
    vector<long long> s(n), t(n);
    s[0] = dat[0].second - dat[0].first;
    t[n - 1] = dat[n - 1].second - dat[n - 1].first;

    for (int i = 1; i < n; i++) {
        chmin(vr, dat[i].second);
        s[i] = min(s[i - 1], max(vr - dat[i].first, 0LL));
    }
    for (int i = n - 2; i >= 0; i--) {
        chmax(vl, dat[i].first);
        t[i] = min(t[i + 1], max(dat[i].second - vl, 0LL));
    }

    long long ans = 0;
    for (int i = 0; i + 1 < n; i++) {
        chmax(ans, s[i] + t[i + 1]);
    }

    cout << ans << '\n';

    return 0;
}

