#include <bits/stdc++.h>
using namespace std;
typedef pair<int, int> P;

void solve() {
    int N; cin >> N;
    vector<P> ranges;
    for(int i = 0; i < N; ++i) {
        int l, r;
        cin >> l >> r;
        ranges.emplace_back(l, r + 1);
    }
    sort(ranges.begin(), ranges.end());

    // 連続した A, B の2つのグループに分割
    vector<int> scoreA(N), scoreB(N);
    int lmax = -1, rmin = 1e9 + 10;
    for(int i = 0; i < N; ++i) {
        lmax = max(lmax, ranges[i].first);
        rmin = min(rmin, ranges[i].second);
        scoreA[i] = max(0, rmin - lmax);
    }

    // 逆から
    lmax = -1, rmin = 1e9 + 10;
    for(int i = N - 1; i >= 0; --i) {
        lmax = max(lmax, ranges[i].first);
        rmin = min(rmin, ranges[i].second);
        scoreB[i] = max(0, rmin - lmax);
    }

    int ans = 0;
    for(int i = 0; i < N - 1; ++i) {
        ans = max(ans, scoreA[i] + scoreB[i + 1]);
    }
    cout << ans << '\n';
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    solve();
    return 0;
}

