    return rh1.second < rh2.second;
}

int gao(int a,int b,int c){
    return min(max(a,c)+b, max(b,c)+a)-2;
}

int gao(int a,int b,int c,int d){
    return min(max(a,c)+max(b,d), max(a,d)+max(b,c))-2;
}

int getMax(const multiset<int>& st){
    assert(st.size());
    return *(--st.end());
}

int l1,l2,r1,r2;
int getAns(){
    return max(0,r1-l1+1)+max(0,r2-l2+1);
}

void solve(){
    int n;
    scanf("%d",&n);
    int ans=0;
    for(int i=1;i<=n;i++){
        scanf("%d%d",&dat[i].first,&dat[i].second);
        ans=max(ans,dat[i].second-dat[i].first+1);
    }
    sort(dat+1,dat+n+1,cmp);

    multiset<int>lst,rst;
    for(int i=1;i<=n;i++) rst.insert(dat[i].first);

    for(int l=1,r=1;l<=n;l=r+1,r=l){
        while(r+1<=n && dat[r+1].second==dat[l].second) r++;
        int mi=INF,ma=0;
        for(int i=l;i<=r;i++){
            rst.erase(rst.lower_bound(dat[i].first));
            mi=min(mi,dat[i].first);
            ma=max(ma,dat[i].first);
        }
        int R=dat[1].second+dat[l].second;
        r1=dat[1].second,r2=dat[l].second;
        if(l==1 && r==n){
            ans=max(ans,R-(mi+ma-2));
        }
        else if(l==1){
            if(r-l+1==1) {}
            else{
                l1=mi,r2=max(ma,getMax(rst));
                ans=max(ans,getAns());

                l1=ma,r2=max(mi,getMax(rst));
                ans=max(ans,getAns());
            }
        }
        else if(r==n){
            l1=getMax(lst),l2=ma;
            ans=max(ans,getAns());
            if(r-l+1==1) {}
            else{
                l1=max(getMax(lst),ma),r2=mi;
                ans=max(ans,getAns());

                l1=max(getMax(lst),mi),r2=ma;
                ans=max(ans,getAns());
            }
        }
        else{
            l1=getMax(lst),l2=max(getMax(rst),ma);
            ans=max(ans,getAns());
            if(r-l+1==1) {}
            else{
                l1=max(getMax(lst),mi),l2=max(getMax(rst),ma);
