ll n, pr[600000], pl[600000];
pair<ll, ll> p[600000];

ll solve() {
  ll r = 0;
  sort(p, p + n);
  pl[0] = p[0].first;
  pr[0] = p[0].second;
  for (int i = 1; i < n; i++)
    pl[i] = max(pl[i - 1], p[i].first), pr[i] = min(pr[i - 1], p[i].second);
  ll sl = p[n - 1].first, sr = p[n - 1].second;
  for (int i = n - 2; i >= 0; i--) {
    r = max(r, max(sr - sl + 1, 0LL) + max(pr[i] - pl[i] + 1, 0LL));
    sl = max(sl, p[i].first);
    sr = min(sr, p[i].second);
  }
  return r;
}

