using namespace std;

typedef pair<int, int> pii;
typedef long long ll;

int N;

bool wrap(pii a, pii b) {
    return a.fst <= b.fst && b.snd <= a.snd;
}

int f(vector<pii> &segs) {
    int max_fst = 0, min_snd = 1e9, max_len = 0;
    int fst_p, snd_p;
    for (int i = 0; i < segs.size(); i++) {
        if (max_fst < segs[i].fst) {
            max_fst = segs[i].fst;
            fst_p = i;
        }
        if (min_snd > segs[i].snd) {
            min_snd = segs[i].snd;
            snd_p = i;
        }
        max_len = max(max_len, segs[i].snd - segs[i].fst + 1);
    }

    int same_v = max_len + max(0, min_snd - max_fst + 1);
    if (fst_p == snd_p) return same_v;

    vector<pii> incomplete;
    for (auto &seg: segs) {
        if (!wrap(seg, segs[fst_p]) && !wrap(seg, segs[snd_p])) {
            incomplete.push_back(seg);
        }
    }

    int v = 0, t_min_snd = segs[fst_p].snd;
    reverse(incomplete.begin(), incomplete.end());
    for (auto &seg: incomplete) {
        int lv = min_snd - seg.fst + 1;
        int rv = max(0, t_min_snd - max_fst + 1);
        v = max(v, lv + rv);
        t_min_snd = min(t_min_snd, seg.snd);
    }
    v = max(v, min_snd - segs[snd_p].fst + 1 + max(0, t_min_snd - max_fst + 1));

    return max(same_v, v);
}

int main() {
    scanf("%d", &N);
    vector<pii> segs;
    for(int i = 0; i < N; i++) {
        int a, b;
        scanf("%d%d", &a, &b);
        segs.emplace_back(a, b);
    }
    sort(segs.begin(), segs.end());
    printf("%d\n", f(segs));
    return 0;
}

