using namespace std;

struct interval{
	int a,b;
};

int solve(const vector<interval>& I){
	int n=I.size();
	multiset<int> L,R;
	rep(i,n-1){
		L.emplace(I[i+1].a);
		R.emplace(I[i+1].b);
	}

	int res=0;
	int l=I[0].a,r=I[0].b;
	rep(i,n-1){
		int l2=*L.rbegin();
		int r2=*R.begin();
		res=max(res,max(r-l+1,0)+max(r2-l2+1,0));
		l=max(l,I[i+1].a);
		r=min(r,I[i+1].b);
		L.erase(L.find(I[i+1].a));
		R.erase(R.find(I[i+1].b));
	}
	return res;
}

