#define rep(a,n) for(int a = 0;a < n;a++)

struct custom_compare
{
	inline bool operator() (const P& p1, const P& p2)
	{
		if (p1.first == p2.first) {
			return p1.second < p2.second;
		}
		return p1.first < p2.first;
	}
};

const ll LARGE = (ll)1e15;

ll solve1(vector<P>& range) {
	sort(range.begin(), range.end(), custom_compare());
	int n = range.size();
	vector<ll> lefts(n);
	ll m = LARGE;
	rep(i, n) {
		m = min(m, range[i].second);
		lefts[i] = m;
	}
	m = LARGE;
	vector<ll> rights(n);
	for (int i = n - 1; i >= 0; i--) {
		m = min(m, range[i].second);
		rights[i] = m;
	}
	ll value = 0;
	rep(i, n - 1) {
		ll l1 = range[i].first;
		ll r1 = lefts[i];
		ll l2 = range[n - 1].first;
		ll r2 = rights[i + 1];
		ll la = max(0LL, r1 - l1 + 1);
		ll ra = max(0LL, r2 - l2 + 1);
		value = max(value, la + ra);
	}
	return value;
}

struct custom_compare2
{
	inline bool operator() (const P& p1, const P& p2)
	{
		if (p1.first == p2.first) {
			return p1.second > p2.second;
		}
		return p1.first > p2.first;
	}
};

ll solve2(vector<P>& range) {
	sort(range.begin(), range.end(), custom_compare2());
	int n = range.size();
	vector<ll> lefts(n);
	ll m = -LARGE;
	rep(i, n) {
		m = max(m, range[i].second);
		lefts[i] = m;
	}
	m = -LARGE;
	vector<ll> rights(n);
	for (int i = n - 1; i >= 0; i--) {
		m = max(m, range[i].second);
		rights[i] = m;
	}
	ll value = 0;
	rep(i, n - 1) {
		ll r1 = range[i].first;
		ll l1 = lefts[i];
		ll r2 = range[n - 1].first;
		ll l2 = rights[i + 1];
		ll la = max(0LL, r1 - l1 + 1);
		ll ra = max(0LL, r2 - l2 + 1);
		value = max(value, la + ra);
	}
	return value;
}


int main(void)
{
	int n;
	cin >> n;
	vector<P> range1;
	vector<P> range2;
	rep(i, n) {
		ll l, r;
		cin >> l >> r;
		range1.emplace_back(l, r);
		range2.emplace_back(r, l);
	}
	auto l1 = solve1(range1);
	auto l2 = solve2(range2);
	cout << max(l1,l2) << endl;
	return 0;
}

