pair<bool,pii> get_intersection(vector<pii>& b){
	pii current = b[0];
	for(pii c:b){
		if(c.fi>current.se || c.se<current.fi) return {false,{1,1}};
		current.fi = max(current.fi,c.fi);
		current.se = min(current.se,c.se);
		if(current.fi>current.se) return {false,{1,1}};
	}
	return {true,current};
}

