ll mod_pow(ll x,ll r){
  if(r==0) return 1;
  else if(r==1) return x%mod;
  else if(r%2==0){
    ll t=mod_pow(x,r/2)%mod;
    return t*t %mod;
  } 
  else{
    ll t=mod_pow(x,r/2)%mod;
    ll k= t*t %mod;
    return k*x%mod;
  } 
}
ll mod_add(ll a,ll b){
  return (a+b)%mod;
}

ll mod_mul(ll a,ll b){
  return (a*b)%mod;
}

ll mod_div(ll a,ll b){
  return mod_mul(a,mod_pow(b,mod-2));
}

void make_fact(ll n){
  fac[0]=1;
  rep(i,n){
    fac[i+1]=mod_mul(fac[i],i+1);
  }  
}

void make_invfact(ll n){
  invfac[n]= mod_pow( fac[n] ,mod-2);
  for(int i=n-1;i>=0;i--){
    invfac[i]=mod_mul(invfac[i+1],i+1);
  }

}

#include <bits/stdc++.h>
using namespace std;
typedef pair<int, int> P;

void solve() {
    int N; cin >> N;
    vector<P> ranges;
    int ans = 0;
    for(int i = 0; i < N; ++i) {
        int l, r;
        cin >> l >> r;
        ++r;
        ans = max(ans, r - l);
        ranges.emplace_back(l, r);
    }
    sort(ranges.begin(), ranges.end());

    // 連続した A, B の2つのグループに分割
    vector<int> scoreA(N), scoreB(N);
    int lmax = -1, rmin = 1e9 + 10;
    for(int i = 0; i < N; ++i) {
        lmax = max(lmax, ranges[i].first);
        rmin = min(rmin, ranges[i].second);
        scoreA[i] = max(0, rmin - lmax);
    }

    // 逆から
    lmax = -1, rmin = 1e9 + 10;
    for(int i = N - 1; i >= 0; --i) {
        lmax = max(lmax, ranges[i].first);
        rmin = min(rmin, ranges[i].second);
        scoreB[i] = max(0, rmin - lmax);
    }

    for(int i = 0; i < N - 1; ++i) {
        ans = max(ans, scoreA[i] + scoreB[i + 1]);
    }

    cout << ans << '\n';
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    solve();
    return 0;
}

