class contest {
public:
	ll left;
	ll right;
public:
	ll getDistance() { return right - left+1; };
	ll simulateDistance(ll l, ll r) {
		ll ans;
		l = l > left ? l : left;
		r = r < right ? r : right;
		ans = r - l;
		if (ans < 0) {
			return 0;
		}
		else {
			return ans+1;
		}
	}
	ll simulateRight(ll r) {
		return r < right ? r : right;
	}
	ll simulateLeft(ll l) {
		return l > left ? l : left;
	}

};

