ll N, ans=0, tmp=0, mintmp=INF, minid, maxtmp=-INF, maxid;
vector<ll> A, ls, rs;

signed main(){
    cin >> N;
    for(int i=0;i<N;i++) {
        ll l, r;
        cin >> l >> r;
        ls.push_back(l);
        rs.push_back(r);
        tmp = max(tmp, r-l+1);
        if(mintmp>r) {
            minid = i;
            mintmp = r;
        }
        if(maxtmp<l) {
            maxid = i;
            maxtmp = l;
        }
    }
    if(minid==maxid) {
        cout << rs[minid]-ls[maxid]+1+tmp << endl;
        return 0;
    }
    else {
        ll l1 = ls[minid];
        ll r1 = rs[minid];
        ll l2 = ls[maxid];
        ll r2 = rs[maxid];
        for(int i=0;i<ls.size();i++) {
            if(i==minid||i==maxid) continue;
            ll lch1 = max(l1, ls[i]);
            ll rch1 = min(r1, rs[i]);
            ll lch2 = max(l2, ls[i]);
            ll rch2 = min(r2, rs[i]);
            if(r1-l1-(rch1-lch1)==r2-l2-(rch2-lch2)&&i<2*N) {
                ls.push_back(ls[i]);
                rs.push_back(rs[i]);
                continue;
            }
            if(max(r1-l1+1, 0LL)-max(rch1-lch1+1, 0LL)<=max(r2-l2+1, 0LL)-max(rch2-lch2+1, 0LL)) {
                l1 = lch1;
                r1 = rch1;
            }
            else {
                l2 = lch2;
                r2 = rch2;
            }
        }
        ans = max(r1-l1+1LL,0LL)+max(r2-l2+1LL,0LL);
    }
    cout << ans << endl;
    return 0;
}

