		}
		if (t == 2) {
			sort(v.begin(), v.end(), [](pii a, pii b) {
				return mp(a.y, a.x) > mp(b.y, b.x);
			});
		}
		if (t == 3) {
			sort(v.begin(), v.end(), [](pii a, pii b) {
				return a.y - a.x < b.y - b.x;
			});
		}

		vector<pii> L(n), R(n);
		L[0] = v[0];
		for (int i = 1; i < n; i++)
			L[i] = mp(max(L[i - 1].x, v[i].x), min(L[i - 1].y, v[i].y));
		R.back() = v.back();
		for (int i = n - 2; ~i; i--)
			R[i] = mp(max(R[i + 1].x, v[i].x), min(R[i + 1].y, v[i].y));
		for (int i = 0; i < n - 1; i++) {
			_max = max(_max, max(0, L[i].y - L[i].x + 1)
				+ max(0, R[i + 1].y - R[i + 1].x + 1));
		}
	}
	for (int i = 0; i < n; i++)
		_max = max(_max, v[i].y - v[i].x + 1);
	print _max;
}

