const int N = 1e5 + 5;


bool cmp(ii a, ii b){
	if(a.ff != b.ff)
		return a < b;
	return a.ss > b.ss;
}

int main(){
	int n;
	vector<ii> v;
	scanf("%d", &n);
	ll ma = 0, mir = 1e9, mal = 0;
	for(int i = 0; i < n; i++){
		ii x;
		scanf("%d %d", &x.ff, &x.ss);
		v.pb(x);
		mal = max(mal, (ll)x.ff);
		mir = min(mir, (ll)x.ss);
		ma = max(ma, (ll)x.ss - x.ff);
	}
	ll ans = ma + max(0ll, mir - mal);
	sort(v.begin(), v.end(), cmp);
	ii g1 = v.back();
	v.pop_back();
	sort(v.rbegin(), v.rend(), cmp);
	set<ii> lef, rig;
	for(int i = 0; i < (int)v.size(); i++){
		lef.insert({v[i].ff, i});
		rig.insert({v[i].ss, i});
	}
	ans = max(ans, (ll)g1.ss - g1.ff + 1) + max(0, -lef.rbegin()->ff + rig.begin()->ff + 1);
	for(int i = 0; i < (int)v.size()-1; i++){
		ll aux = max(0, min(g1.ss, v[i].ss) - g1.ff + 1);
		lef.erase({v[i].ff, i});
		rig.erase({v[i].ss, i});
		aux += max(0, -lef.rbegin()->ff + rig.begin()->ff + 1);
		ans = max(ans, aux);
	}
	printf("%lld\n", ans);
	return 0;
}

