                        tmp = max(tmp, score);
                    }
                }
            }
        }

        int sect2 = max(0, R[ridx]-L[lidx]+1);
        int tmp2 = 0;
        for(int i = 0; i < N;i++){
            int idx = rp[i].second;
            if(idx != lidx && idx != ridx){
                int idx = rp[i].second;
                tmp2 = max(tmp2, sect2 + R[idx]-L[idx]+1);
                //cout << idx << ' ' << R[idx] - L[idx] << endl;
            }
        }
        // cout << sect2 << endl;
        // cout << lidx << ' ' << ridx << endl;
        // cout << tmp << ' ' << tmp2 << endl;
        ans = max(tmp, tmp2);
    }
    cout << ans  << endl;
}

