pll intersection( pll ans, pll now )
{
    ll mn = ans.F, mx = ans.S;
    ll left = now.F, right = now.S;

    if( left < mn )
    {
        swap(left,mn);
        swap(right,mx);
    }
    if( left <= mx )
    {
        mx = min(mx, right);
        mn = max(mn, left);
        ans = {mn,mx};
    }
    else
        ans = {0,-1};

    return ans;
}


