int main()
{
    int N;
    cin >> N;
    vector<plint> LR(N), RL(N);
    lint ret = 0;
    REP(i, N)
    {
        cin >> LR[i].first >> LR[i].second;
        RL[i] = make_pair(LR[i].second, LR[i].first);
        mmax(ret, LR[i].second - LR[i].first + 1);
    }
    sort(ALL(LR));
    sort(ALL(RL));
    lint lmax = LR.back().first;
    lint rmin = RL[0].first;
    // dbg(lmax);
    // dbg(rmin);
    if (lmax > rmin)
    {
        // dbg("A");
        vector<plint> v;
        for (auto p : LR) v.emplace_back(max(rmin - p.first + 1, 0LL), max(p.second - lmax + 1, 0LL));
        sort(ALL(v));

        // dbg(v);

        lint rrr = v[0].second;
        REP(i, N + 1)
        {
            mmin(rrr, v[i].second);
            mmax(ret, rrr + v[i + 1].first);
        }
    }
    else
    {
        // dbg("B");
        vector<plint> v;
        for (auto p : LR) v.emplace_back(max(p.second - rmin + 1, 0LL), max(lmax - p.first + 1, 0LL));
        sort(ALL(v));
        // dbg(v);
        vector<plint> vacc = v;
        IREP(i, (int)v.size() - 1)
        {
            mmin(vacc[i].first, v[i + 1].first);
            mmin(vacc[i].second, v[i + 1].second);
        }
        plint vv = v[0];
        // dbg(v);
        // dbg(vacc);
        REP(i, N - 1)
        {
            mmin(vv.first, v[i].first);
            mmin(vv.second, v[i].second);
            mmax(ret, vv.first + vv.second + vacc[i + 1].first + vacc[i + 1].second + (rmin - lmax - 1) * 2);
        }
    }
    cout << ret << endl;
}

