ll
getBottom(vector<ll> & end, int start, int tail) {
  ll bottom = INT_MAX;
  int n = end.size() / 2;
  int left = start, right = tail;
  left += n, right += n;
  while (1) {
    if (left > right) break;

    if (right % 2 == 0) {
      bottom = min(bottom, end[right]);
      right--;
    }
    if (left % 2 == 1) {
      bottom = min(bottom, end[left]);
      left++;
    }

    right /= 2;
    left /= 2;
  }

  return bottom;
}

