const int maxn=111111;
pii A[maxn];
int N,L[maxn],R[maxn];
//-------------------------------------------------------------------hanshu↓
int solve()
{
	L[N]=A[N].first,R[N]=A[N].second;
	int l=A[1].first,r=A[1].second;
	for(int i=N-1;i>=1;--i)
	{
		L[i]=max(L[i+1],A[i].first);
		R[i]=min(R[i+1],A[i].second);
	}
	int ans=0;
	for(int i=2;i<=N;++i)
	{
		ans=max(ans,max(0,r-l+1)+max(0,R[i]-L[i]+1));
		r=min(r,A[i].second),l=max(l,A[i].first);
	}
	return ans;
}
bool cmp1(pii x,pii y)
{
	if(x.first!=y.first) return x.first<y.first;
	return x.second>y.second;
}
bool cmp2(pii x,pii y)
{
	if(x.first!=y.first) return x.first>y.first;
	return x.second>y.second;
}
bool cmp3(pii x,pii y)
{
	if(x.first!=y.first) return x.first>y.first;
	return x.second<y.second;
}
