	int ans=0;
	for(int i=1;i<=N;++i) A[i].first=rd(),A[i].second=rd(),ans=max(ans,A[i].second-A[i].first+1);
	sort(A+1,A+1+N);
	ans=max(ans,solve());
	sort(A+1,A+1+N,cmp1);
