void solve() {
    int n;
    cin >> n;
    vector<pair<int, int>> v(n);
    vector<pair<int, int>> w(n);
    int l, r;
    int isomax = -1;
    int lmax = -1;
    int rmin = INF;
    REP(i, n) {
        cin >> l >> r;
        l--; r--;
		chmax(lmax, l);
		chmin(rmin, r);
        v[i] = make_pair(l, r);
        w[i] = make_pair(r, l);
        chmax(isomax, r - l + 1);
    }
    sort(ALL(v));
    vector<int> lmin(n);
    vector<int> rmin(n);
    int mn = INF;
    REP(i, n) {
        chmin(mn, v[i].second);
        lmin[i] = mn;
    }
    mn = INF;
    REPR(i, n) {
        chmin(mn, v[i].second);
        rmin[i] = mn;
    }
    int ans = 0;
    REP(i, n - 1) {
        int x = lmin[i] - v[i].first + 1;
        if (x <= 0) x = 0;
        int y = rmin[i + 1] - v[n - 1].first + 1;
        if (y <= 0) y = 0;
        chmax(ans, x + y);
    }

    // ?????
    sort(ALL(w), greater<pair<int, int>>());
    vector<int> lmax(n);
    vector<int> rmax(n);
    int mx = -1;
    REP(i, n) {
        chmax(mx, w[i].second);
        lmax[i] = mx;
    }
    mx = -1;
    REPR(i, n) {
        chmax(mx, w[i].second);
        rmax[i] = mx;
    }
    REP(i, n - 1) {
        int x = w[i].first - lmax[i] + 1;
        if (x <= 0) x = 0;
        int y = w[n - 1].first - rmax[i + 1] + 1;
        if (y <= 0) y = 0;
        chmax(ans, x + y);
    }

    cout << max(ans, isomax + max(0, rmin - lmax + 1)) << EOL;
}

