#include <bits/stdc++.h>
using namespace std;

int main() {
	int n; cin >> n;
	pair<int, int> p[n];
	int lmax = -1, rmin = 1e9 + 10;
	for(int i = 0; i < n; ++i) {
		int l, r; cin >> l >> r;
		++r;
		lmax = max(lmax, l);
		rmin = min(rmin, r);
		p[i] = {l, -r};
	}
	sort(p, p + n);
	int ans = 0;
	{ // same
		int ans1 = 0, ans2 = 0;
		for(int i = 0; i < n; ++i) {
			int l, r;
			tie(l, r) = p[i];
			r = -r;
			if(l == lmax and r == rmin) {
				ans1 = max(0, rmin - lmax);
			} else {
				ans2 = max(ans2, r - l);
			}
		}
		if(ans1 > 0) {
			ans = ans1 + ans2;
		}
	}
	// (lmax, r) (l, rmin)
	{ // diff
		multiset<int> r1, l2;
		int idx = -1;
		for(int i = 0; i < n; ++i) {
			int l, r;
			tie(l, r) = p[i];
			r = -r;
			if(r == rmin) {
				if(idx == -1) {
					l2.insert(l);
					idx = i;
				}
			} else {
				r1.insert(r);
			}
		}
		for(int i = 0; i < n; ++i) {
			if(idx == i) continue;
			int l, r;
			tie(l, r) = p[i];
			r = -r;
			int ansp, ansc;
			{ // not changed
				int ans1 = max(0, *r1.begin() - lmax);
				int ans2 = max(0, rmin - *l2.rbegin());
				ansp = ans1 + ans2;
			}
			{ // changed
				r1.erase(r1.find(r));
				l2.insert(l);
				int ans1 = max(0, *r1.begin() - lmax);
				int ans2 = max(0, rmin - *l2.rbegin());
				ansc = ans1 + ans2;
			}
			if(ansp > ansc) {
				r1.insert(r);
				l2.erase(l2.find(l));
				break;
			}
		}
		ans = max(ans, max(0, *r1.begin() - lmax) + max(0, rmin - *l2.rbegin()));
	}
	cout << ans << endl;
	return 0;
}

