const int N_MAX = 100003;
std::pair<int, int> seg[N_MAX], pre[N_MAX], suf[N_MAX];
int calc(std::pair<int, int> x) {
  return std::max(0, x.second - x.first + 1);
}

int main() {
  int n;
  scanf("%d", &n);
  for (int i = 1; i <= n; ++i)
    scanf("%d%d", &seg[i].first, &seg[i].second);
  std::sort(seg + 1, seg + n + 1);
  pre[1] = seg[1];
  for (int i = 2; i <= n; ++i) {
    pre[i].first = std::max(pre[i - 1].first, seg[i].first);
    pre[i].second = std::min(pre[i - 1].second, seg[i].second);
  }
  suf[n] = seg[n];
  for (int i = n - 1; i > 0; --i) {
    suf[i].first = std::max(suf[i + 1].first, seg[i].first);
    suf[i].second = std::min(suf[i + 1].second, seg[i].second);
  }

  int ans = 0;
  for (int i = 1; i < n; ++i)
    ans = std::max(calc(pre[i]) + calc(suf[i + 1]), ans);
  printf("%d\n", ans);
  return 0;
}

