class Range {
public:
  int l, r;
  Range() {}
  Range(int l, int r) : l(l), r(r) {}
};

bool cmp(const Range &a, const Range &b)
{
  int l = a.l+a.r;
  int r = b.l+b.r;
  if (l == r) return a.l < b.l;
  return l < r;
}

vector<Range> ranges;


int common2(int i, int j) { 
  int l = max(ranges[i].l, ranges[j].l);
  int r = min(ranges[i].r, ranges[j].r);
  // cerr <<  i << " " << j << " " << l  << " " << r << endl;
  return max(r-l+1, 0);
}

int common(int i, int j, int ignore=-1) { 
  int r = -1;
  int l = -1;
  for (int k = i; k <= j; ++k) {
    if (k == ignore) continue;
    Range &rr = ranges[k];
    if (r == -1 || r > rr.r) {
      r = rr.r;
    }
    if (l == -1 || l < rr.l) {
      l = rr.l;
    }
  }
  return r-l+1;
}

