    rep(i,N) {
        ll L, R;
        cin >> L >> R;
        R++;
        len.push_back(make_pair(L,R));
    }
    sort(len.begin(), len.end(), pairCompare1);
    ll Rp = len[0].second;
    ll Lp = len[0].first;
    REP(i,1,N) {
        if (len[i].second == Rp) {
            if(len[i].first > Lp) {
                Lp = len[i].first;
            }
        } else {
            break;
        }
    }
    sort(len.begin(), len.end(), pairCompare2);
    ll Lq = len[0].first;
    ll Rq = len[0].second;
    ll qind = 0;
    REP(i,1,N) {
        if (len[i].first == Lq) {
            if(len[i].second < Rq) {
                Rq = len[i].second;
                qind = i;
            }
        } else {
            break;
        }
    }

    // pとqが同じグループに入る
    ll ans1 = 0;
    if (Rp-Lq> 0) ans1 += Rp - Lq;
    ll dif_max = 0;
    bool pflag = false;
    rep(i,N) {
        if(i == qind) continue;
        else if (len[i].first == Lp && len[i].second == Rp && !pflag) {
            pflag = true;
            continue;
        }
        if(dif_max < len[i].second - len[i].first) {
            dif_max = len[i].second - len[i].first;
        }
    }
    ans1 += dif_max;

    if(Lp == Lq && Rp == Rq) {
        cout << ans1 << endl;
        return 0;
    }

    sort(len.begin(), len.end(), pairCompare1);

    // pとqが違うグループ
    vector<pll> AB(N);
    rep(i,N) {
        ll A = 0;
        ll B = 0;
        if (Rp - len[i].first > 0) A = Rp - len[i].first;
        if (len[i].second - Lq > 0) B = len[i].second - Lq;
        AB[i] = make_pair(A, B);
    }
    sort(AB.begin(), AB.end(), pairCompare2);
    ll ans2 = 0;
    rmq_init(N);
    rep(i,N) {
        rmq_update(i, AB[i].second);
    }
    rep(i, N-1) {
        ll mina = AB[i].first;
        ll minb = rmq_query(i+1, N, 0, 0, rmq_N);
        ans2 = max(mina + minb, ans2);
    }
    ll ans = max(ans1, ans2);
    cout << ans << endl;
    return 0;
}

