struct Segmenttree {
	static const int N = 1 << 18;
	vector<ll>seg;
	vector<ll>idx;
	void st(ll p, ll v) {
		p += N - 1;
		seg[p] = v;
		idx[p] = p - N + 1;
		while (p > 0) {
			p = (p - 1) / 2;
			seg[p] = max(seg[2 * p + 1], seg[2 * p + 2]);
			if (seg[2 * p + 1] < seg[2 * p + 2])idx[p] = idx[2 * p + 2];
			else if (seg[2 * p + 1] > seg[2 * p + 2])idx[p] = idx[2 * p + 1];
			else idx[p] = min(idx[2 * p + 1], idx[2 * p + 2]);
		}
	}
	pair<ll, ll> query(ll l, ll r, ll a, ll b, ll k) {
		if (r <= a || b <= l)return { -inf,inf };
		if (l <= a && b <= r)return { seg[k],idx[k] };
		ll m = (a + b) / 2;
		auto p1 = query(l, r, a, m, 2 * k + 1);
		auto p2 = query(l, r, m, b, 2 * k + 2);
		if (p1.first > p2.first) return p1;
		else if (p1.first < p2.first)return p2;
		else return { p1.first,min(p1.second,p2.second) };
	}

	void init() {
		seg.resize(2 * N);
		idx.resize(2 * N);
		for (int i = 0; i < 2 * N; i++)seg[i] = -inf;
	}
	//[l,r]
	ll get(int l, int r) {
		return query(l, r + 1, 0, N, 0).first;
	}
	ll getidx(int l, int r) {
		return query(l, r + 1, 0, N, 0).second;
	}
	pair<ll, ll>getp(int l, int r) {
		return query(l, r + 1, 0, N, 0);
	}
};

int N;
vector<pair<ll, ll>>v;


int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);

	cin >> N;
	for (int i = 0; i < N; i++) {
		ll L, R;
		cin >> L >> R;
		v.pb({R,L});
	}
	sort(all(v));

	Segmenttree seg = Segmenttree();
	seg.init();
	for (int i = 0; i < N; i++)seg.st(i,v[i].second);


	ll ans = 0;
	for (int i = 1; i < N; i++) {
		ll Sr = v[0].first + v[i].first;
		ll Sl;
		ll maA = seg.get(0,i-1);
		ll maB = v[i].second;
		ll maC = seg.get(i+1,N-1);
		if (i <= N - 2) {
			if (maA >= maC || maB >= maC)Sl = maA + maB;
			else {
				if (maA >= maB)Sl = maB + maC;
				else Sl = maA + maC;
			}
			ans = max(Sr - Sl + 2LL, ans);
		}
		else ans = max(Sr-maA-maB+2LL,ans);
	}
	puts(ans);

	return 0;
}

