signed main() {
    int N;
    cin >> N;

    int ret = 0;
    vector<pair<int, int>> prs(N);
    rep(i, N) {
        cin >> prs[i].first >> prs[i].second;
        ret = max(ret, prs[i].second - prs[i].first + 1);
    }

    sort(all(prs));

    vector<int> v1, v2;
    vector<pair<int, int>> prs1, prs2;
    int low = 0;
    int high = INT_MAX;
    for (auto it = prs.begin(); it != prs.end(); it++) {
        low = max(low, it->first);
        high = min(high, it->second);
        v1.push_back(high - low + 1);
        prs1.push_back(mp(low, high));
    }

    low = 0;
    high = INT_MAX;
    for (auto it = prs.rbegin(); it != prs.rend(); it++) {
        low = max(low, it->first);
        high = min(high, it->second);
        v2.push_back(high - low + 1);
        prs2.push_back(mp(low, high));
    }
    reverse(all(v2));
    reverse(all(prs2));

    rep(i, N - 1) {
        ret = max(ret, v1[i] + v2[i + 1]);
    }

    REP(i, 1, N - 2) {
        int low = max(prs1[i - 1].first, prs2[i + 1].first);
        int high = min(prs1[i - 1].second, prs2[i + 1].second);
        ret = max(ret, prs[i].second - prs[i].first + 1 + max(0LL, high - low + 1));
    }

    cout << ret << endl;

    return 0;
}

