using namespace std;
typedef long long ll;
pair<ll,ll> p[100010];
vector<pair<ll,ll>> v;
int main(){
	int i,n;
	cin >> n;
	ll mx = -1,mn = 1000000001;
	int j = -1,k = -1;
	for(i=0;i<n;i++){
		ll l,r; cin >> l >> r;
		p[i] = {r,l};
		if(mx<l){
			j = i;
			mx = l;
		}
		if(mn>r){
			k = i;
			mn = r;
		}
	}
	if(j==k){
		ll sum = 0;
		sum += p[k].first - p[j].second + 1;
		mx = -1;
		for(i=0;i<n;i++){
			if(i==j) continue;
			mx = max(mx,p[i].first - p[i].second + 1LL);
		}
		cout << sum + mx << endl;
		return 0;
	}
	for(i=0;i<n;i++){
		if(i==j || i==k) continue;
		v.push_back(p[i]);
	}
	if(n==2){
		cout << p[0].first - p[0].second + p[1].first - p[1].second + 2 << endl;
		return 0;
	}
	sort(v.begin(),v.end());
	ll amnr = p[j].first,amxl = p[j].second,bmnr = p[k].first,bmxl = p[k].second;
	ll ans = 0;
	for(i=0;i<v.size();i++){
		amnr = min(p[j].first,v[i].first);
		if(i!=0) bmxl = max(bmxl,v[i - 1].second);
		ans = max(ans,max(amnr - amxl + 1LL,0LL) + max(bmnr - bmxl + 1LL,0LL));
	}
	amnr = p[j].first;
	bmxl = max(bmxl,v.back().second);
	ans = max(ans,max(amnr - amxl + 1LL,0LL) + max(bmnr - bmxl + 1LL,0LL));
	mx = -1;
	for(i=0;i<n;i++){
		if(i==j || i==k) continue;
		mx = max(mx,p[i].first - p[i].second + 1LL);
	}
	ans = max(ans,max(p[k].first - p[j].second + 1LL,0LL) + mx);
	cout << ans << endl;
}

#include <bits/stdc++.h>
using namespace std;
using PP = pair<int, int>;

const int inf = 1e9;
int n;
int m;
PP p[100000];
PP q[100000];
PP a[100001];
PP b[100001];
PP f[100001];
PP g[100001];

int len(PP p) {
  return max(0, p.second - p.first);
}

PP cap(PP p, PP q) {
  return PP(max(p.first, q.first), min(p.second, q.second));
}

void reduce() {
  int prevr = -inf;
  vector<bool> chosen(n, true);
  for (int i = 0; i < n; ++i) {
    if (p[i].second <= prevr) chosen[i - 1] = false;
    prevr = p[i].second;
  }

  for (int i = 0; i < n; ++i) {
    if (!chosen[i]) continue;
    q[m] = p[i];
    ++m;
  }
}

int main() {
  cin >> n;
  for (int i = 0; i < n; ++i) {
    int a, b;
    cin >> a >> b;
    p[i] = PP(a, b + 1);
  }
  sort(p, p + n, [](PP a, PP b) {
    return a.first < b.first || a.first == b.first && a.second > b.second;
  });

  a[0] = PP(-inf, inf);
  for (int i = 0; i < m; ++i) {
    a[i + 1] = cap(a[i], p[i]);
  }
  b[m] = PP(-inf, inf);
  for (int i = m - 1; i >= 0; --i) {
    b[i] = cap(b[i + 1], p[i]);
  }

  reduce();

  if (m == 1) {
    cout << len(p[0]) + len(p[n - 1]) << endl;
    return 0;
  }

  f[0] = PP(-inf, inf);
  for (int i = 0; i < m; ++i) {
    f[i + 1] = cap(f[i], q[i]);
  }
  g[m] = PP(-inf, inf);
  for (int i = m - 1; i >= 0; --i) {
    g[i] = cap(g[i + 1], q[i]);
  }

  int mx = 0;
  for (int i = 0; i < m; ++i) {
    PP c = cap(f[i], g[i + 1]);
    mx = max(mx, len(p[i]) + len(c));
  }

  for (int i = 1; i < m; ++i) {
    mx = max(mx, len(f[i]) + len(g[i]));
  }
  cout << mx << endl;
}

