using namespace std;
struct node{
	int L,R;
	bool operator <(const node s)const{
		if(L==s.L)return R>s.R;
		return L<s.L;
	}
}a[500010];
int al[100010],ar[100010],dl[100010],dr[100010];
int n;
int main(){
	cin>>n;
	for(int i=1;i<=n;i++)cin>>a[i].L>>a[i].R;
	sort(a+1,a+n+1);
	al[1]=a[1].L;ar[1]=a[1].R;
	for(int i=2;i<=n;i++){
		al[i]=max(al[i-1],a[i].L);
		ar[i]=min(ar[i-1],a[i].R);
	}
	dl[n]=a[n].L;dr[n]=a[n].R;
	for(int i=n-1;i>=1;i--){
		dl[i]=max(dl[i+1],a[i].L);
		dr[i]=min(dr[i+1],a[i].R);
	}
	int ans=0;
	for(int i=1;i<n;i++)ans=max(ans,max(0,ar[i]-al[i]+1)+max(0,
	dr[i+1]-dl[i+1]+1));cout<<ans;
	return 0;
}

