using namespace std;

struct Interval {
    int i, j;
    Interval(): i(0), j(1000000010) {}
    Interval(int i, int j): i(i), j(j) {}
    Interval operator&(const Interval& o) const {
        int new_i = max(i, o.i);
        int new_j = min(j, o.j);
        return Interval(new_i, new_j);
    }
    int size() {
        return max(0, j - i);
    }
    bool operator<(const Interval& o) const {
        return j < o.j;
    }
    friend istream& operator>>(istream& in, Interval& interval) {
        in >> interval.i >> interval.j;
        ++interval.j;
        return in;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n;
    cin >> n;
    vector<Interval> intervals(n);
    for (auto& interval : intervals) {
        cin >> interval;
    }
    sort(intervals.begin(), intervals.end());
    vector<Interval> from_left(n+1), from_right(n+1);
    // from_left[i] = I_0 & I_1 & ... & I_{i-1}
    // from_right[i] = I_i & I_{i+1} & ... & I_{n-1}
    for (int i = 0; i < n; ++i) {
        from_left[i+1] = from_left[i] & intervals[i];
    }
    for (int i = n-1; i >= 0; --i) {
        from_right[i] = from_right[i+1] & intervals[i];
    }
    int best = 0;

    // all but one:
    for (int i = 0; i < n; ++i) {
        auto left = from_left[i];
        auto right = from_right[i+1];
        int total_size = (left & right).size() + intervals[i].size();
        best = max(best, total_size);
    }

    // first i
    for (int i = 1; i < n; ++i) {
        auto left = from_left[i];
        auto right = from_right[i];
        int total_size = left.size() + right.size();
        best = max(best, total_size);
    }

    cout << best << endl;
    return 0;
}

