template<class T>
class segment_tree {
private:
  ll n;
  T d;
  vector<T>* v;
  T _query(ll a,ll b,ll k,ll l,ll r){
    if(r <= a || b <= l) return d;
    if(a <= l && r <= b) return this->v->at(k);
    else {
      T vl = _query(a,b,k*2+1,l,(l+r)/2);
      T vr = _query(a,b,k*2+2,(l+r)/2,r);
      return func(vl,vr);
    }
  }
public:
  segment_tree (){}
  segment_tree(ll n,T d = 0){
    this->n = 1;
    while(n > this->n) this->n <<= 1;
    v = new vector<T>(this->n*2,d);
    this->d = d;
  }
  void update(ll i,T x){
    i += n-1;
    this->v->at(i) = x;
    while(i > 0){
      i = (i-1)/2;
      this->v->at(i) = func(this->v->at(i*2+1),this->v->at(i*2+2));
    }
  }
  T query(ll a,ll b){
    return _query(a,b,0,0,n);
  }
  T func(T a,T b){
    return min(a,b);
  }
};

ll n;
