    zip[x->first] = i;
    i++;
  }
  for(ll i = 0;i < n;i++){
    sg.update(zip[l[i]],r[i]);
  }
  sort(l,l+n);
  for(ll i = 1;i < n;i++){
    ll mem = 0;
    mem += max(0ll, sg.query(0,i)-l[i-1]+1);
    mem += max(0ll, sg.query(i,n)-l[n-1]+1);
