void solve() {
    int n;
    cin >> n;
    vector<pair<int, int>> pro(n);
    for (int i=0; i<n; ++i) {
        cin >> pro.at(i).first >> pro.at(i).second;
        ++pro.at(i).second;
    }

    int maxl1 = 0, maxl2 = 0, minr1 = INF, minr2 = INF;
    for (auto p : pro) {
        int l = p.first, r = p.second;
        if (l > maxl1) maxl2 = maxl1, maxl1 = l;
        else if (l > maxl2) maxl2 = l;
        if (r < minr1) minr2 = minr1, minr1 = r;
        else if (r < minr2) minr2 = r;
    }
    int res = 0;
    for (auto p : pro) {
        int l = p.first, r = p.second;
        int maxl = maxl1 == l ? maxl2 : maxl1;
        int minr = minr1 == r ? minr2 : minr1;
        chmax(res, r - l + minr - maxl);
    }
    sort(pro.begin(), pro.end());
    vector<int> dp(n-1);
    int l = 0, r = INF;
    for (int i=0; i<n-1; ++i) {
        chmax(l, pro.at(i).first);
        chmin(r, pro.at(i).second);
        dp.at(i) += r - l;
    }
    l = 0, r = INF;
    for (int i=n-1; i>0; --i) {
        chmax(l, pro.at(i).first);
        chmin(r, pro.at(i).second);
        dp.at(i-1) += r - l;
    }
    for (auto x : dp) chmax(res, x);
    cout << res << '\n';
}

