    for(int i=0; i<N; ++i)
    {
        cin >> V[i].first >> V[i].second;
        ++V[i].second;
    }

    int ans = 0;

    // case #1 rightmost L, leftmost R in same group
    int maxv=0, maxi=0, rightl=0, leftr=(int)1e9+1;
    for(int i=0; i<N; ++i)
    {
        maxv = max(V[i].second-V[i].first, maxv);
        if(maxv==V[i].second-V[i].first) maxi = i;
    }
    for(int i=0; i<N; ++i)
    {
        if(i==maxi) continue;

        rightl = max(rightl, V[i].first);
        leftr = min(leftr, V[i].second);
    }
    ans = maxv + max(leftr-rightl, 0);


    // case #2 rightmost L, leftmost R diff group

    sort(V.begin(), V.end());
    sort(V.begin(), V.end()-1, [&](pair<int, int> a, pair<int, int> b)
    {
        return a.first > b.first;
    });

    multiset<int> Lv, Rv;
    for(int i=0; i<N-1; ++i)
    {
        Lv.insert(V[i].first);
        Rv.insert(V[i].second);
    }
    int ls = V[N-1].first, rs = V[N-1].second;

    for(int i=0; i<N-2; ++i)
    {
        rs=min(rs, V[i].second);
        Lv.erase(Lv.find(V[i].first));
        Rv.erase(Rv.find(V[i].second));
        ans = max((rs-ls)+*Rv.begin()-*Lv.rbegin(), ans);
    }
    cout << ans << endl;
}

