ll findMax(multiset<ll> ss) 
{  
    if (!ss.empty()) return *ss.rbegin();
    return 1e10;
} 

ll findMin(multiset<ll> ss) 
{ 
    if (!ss.empty()) return *(--ss.rend()); 
    return -1;
} 

ll calc()
{
	ll tem =  max(0LL,1LL + findMin(s[0][1]) - findMax(s[0][0])) + max(0LL,1LL + findMin(s[1][1]) - findMax(s[1][0]));
	return tem;
}

void erases(ll i, ll j, ll value)
{
	multiset<ll>::iterator itr = s[i][j].find(value);
	if(itr!=s[i][j].end()) s[i][j].erase(itr);
}



