using namespace std;
typedef long long ll;
typedef pair<int,int>pii;

const int N=1e5+10;
const int INF=1e9+10;
pii dat[N];

bool cmp(const pii& rh1, const pii& rh2) {
    return rh1.second < rh2.second;
}

int getMax(const multiset<int>& st){
    assert(st.size());
    return *(--st.end());
}

int l1,l2,r1,r2;
int getAns(){
    return max(0,r1-l1+1)+max(0,r2-l2+1);
}

void solve(){
    int n;
    scanf("%d",&n);
    int ans=0;
    for(int i=1;i<=n;i++){
        scanf("%d%d",&dat[i].first,&dat[i].second);
        ans=max(ans,dat[i].second-dat[i].first+1);
    }
    sort(dat+1,dat+n+1,cmp);

    multiset<int>lst,rst;
    for(int i=1;i<=n;i++) rst.insert(dat[i].first);

    for(int l=1,r=1;l<=n;l=r+1,r=l){
        while(r+1<=n && dat[r+1].second==dat[l].second) r++;
        int mi=INF,ma=0;
        for(int i=l;i<=r;i++){
            rst.erase(rst.lower_bound(dat[i].first));
            mi=min(mi,dat[i].first);
            ma=max(ma,dat[i].first);
        }
        r1=dat[1].second,r2=dat[l].second;
        if(l==1 && r==n){
            l1=mi,l2=ma;
            ans=max(ans,getAns());
        }
        else if(l==1){
            if(r-l+1==1) {}
            else{
                l1=mi,r2=max(ma,getMax(rst));
                ans=max(ans,getAns());

                l1=ma,r2=max(mi,getMax(rst));
                ans=max(ans,getAns());
            }
        }
        else if(r==n){
            l1=getMax(lst),l2=ma;
            ans=max(ans,getAns());
            if(r-l+1==1) {}
            else{
                l1=max(getMax(lst),ma),r2=mi;
                ans=max(ans,getAns());

                l1=max(getMax(lst),mi),r2=ma;
                ans=max(ans,getAns());
            }
        }
        else{
            l1=getMax(lst),l2=max(getMax(rst),ma);
            ans=max(ans,getAns());
            if(r-l+1==1) {}
            else{
                l1=max(getMax(lst),mi),l2=max(getMax(rst),ma);
                ans=max(ans,getAns());
                l1=max(getMax(lst),ma),l2=max(getMax(rst),mi);
                ans=max(ans,getAns());
            }
        }
        for(int i=l;i<=r;i++) lst.insert(dat[i].first);
    }

    lst.clear(),rst.clear();
    for(int i=1;i<=n;i++) lst.insert(dat[i].first),rst.insert(dat[i].second);
    for(int i=1;i<=n;i++){
        lst.erase(lst.lower_bound(dat[i].first));
        rst.erase(rst.lower_bound(dat[i].second));
        ans=max(ans,max(0,(*rst.begin())-(*(--lst.end()))+1)+dat[i].second-dat[i].first+1);
        lst.insert(dat[i].first);
        rst.insert(dat[i].second);
    }

    printf("%d\n",ans);
}

int main(){

    solve();
    return 0;
}

