    rep(i, n - 1) {
        l1 = v[i].first;
        r1 = v[i].second;
        r2 = min_right[i + 1];

        ll ans_temp;
        if (i != 0) {
            ll r_temp = min_left[i - 1];
            ll ans0 = max((min(r_temp, r1) - l1), 0LL) + max((r2 - l2), 0LL);
            ll ans1 = max((r1 - l1), 0LL) + max((min(r_temp, r2) - l2), 0LL);
            ans_temp = max(ans0, ans1);
        } else {
            ans_temp = max((r1 - l1), 0LL) + max((r2 - l2), 0LL);
        }

        ans = max(ans, ans_temp);
    }

    cout << ans - 2 << endl;
    return 0;
}

