int calc(pair<int,int> p, pair<int,int> q){
	int sm=0;
	if(p.x<=p.y)
		sm+=p.y-p.x+1;
	if(q.x<=q.y)
		sm+=q.y-q.x+1;
	return sm;
}

pair<int,int> mrg(pair<int,int> p, pair<int,int> q){
	return {max(p.x,q.x), min(p.y,q.y)};
}

