    else {
      r[i][0] = max(r[i+1][0], pos[i][0]);
      r[i][1] = min(r[i+1][1], pos[i][1]);
    }
  }

  int result = 0;
  rep(i,N) {
    int lp, rp;
    if (i==0) {
      lp = r[i+1][0];
      rp = r[i+1][1];
    }
    else if (i==N-1) {
      lp = l[i][0];
      rp = l[i][1];
    }
    else {
      lp = max(l[i][0], r[i+1][0]);
      rp = min(l[i][1], r[i+1][1]);
    }
    int len = pos[i][1]-pos[i][0]+1;
    result = max(result, max(0,rp-lp+1)+len);
    // cout << lp << " " << rp << " " << len << endl;

    if (i!=0) {
      int ld = max(0, l[i][1]-l[i][0]+1);
      int rd = max(0, r[i][1]-r[i][0]+1);
      result = max(result, ld+rd);
      // cout << ld << " " << rd << endl;
    }
  }

  // rep(i,N+1) cout << l[i][0] << "~" << l[i][1] << ", " << r[i][0] << "~" << r[i][1] << endl;
  cout << result << endl;
  return 0;
}

