	for (int i = 0; i < N; ++i) cin >> vec[i].first >> vec[i].second;
	sort(vec.begin(), vec.end());

	ll L = N - 1;

	ll R = -1, tmp = INF;
	for (int i = 0; i < N; ++i) {
		if (tmp > vec[i].second) {
			R = i;
			tmp = vec[i].second;
		}
		else if (tmp == vec[i].second && vec[R].first > vec[i].first) {
			R = i;
		}
	}

	if (L == R) {
		// 最大区間と最小区間の和
