int main() {
    int64_t N;
    cin >> N;
    struct Task {
        int64_t L, R;
        bool operator<(const Task& rhs) const {
            return (L != rhs.L ? L < rhs.L : R < rhs.R);
        }
    };

    vector<Task> tasks(N);
    for (int64_t i = 0; i < N; i++) {
        cin >> tasks[i].L >> tasks[i].R;
    }
    sort(tasks.begin(), tasks.end());

    //[i, N)におけるRの最小値
    vector<int64_t> R_min(N, LLONG_MAX);
    R_min[N - 1] = tasks[N - 1].R;
    for (int64_t i = N - 2; i >= 0; i--) {
        R_min[i] = min(R_min[i + 1], tasks[i].R);
    }

    int64_t ans = 0;
    int64_t R_min_i = tasks[0].R;
    for (int64_t i = 1; i < N; i++) {
        //[0, i)のタスクを1回目のコンテストに、[i, N)のタスクを2回目のコンテストに使う
        //[0, i)のLの最大値はソートしているのでtasks[i - 1].L
        //[0, i)のRの最小値はR_min_i
        int64_t rem1 = max(R_min_i - tasks[i - 1].L + 1, (int64_t)0);

        //[i, N)のLの最大値はソートしているのでtasks[N - 1].L
        //[i, N)のRの最小値はR_min[i]
        int64_t rem2 = max(R_min[i] - tasks[N - 1].L + 1, (int64_t)0);

        //答えの更新
        ans = max(ans, rem1 + rem2);

        //R_min_iの更新
        R_min_i = min(R_min_i, tasks[i].R);
    }

    cout << ans << endl;
