typedef pair <int, int> ii;

const int Maxn = 100005;
const int Inf = 1000000007;

int n;
int a[Maxn], b[Maxn];
int ind;
int mn = -Inf, mx = Inf;
vector <ii> seq;
int res;

int main()
{
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%d %d", &a[i], &b[i]);
        if (b[i] < b[ind]) ind = i;
    }
    seq.push_back(ii(a[ind], b[ind]));
    for (int i = 0; i < n; i++)
        if (i != ind && a[i] > a[ind]) seq.push_back(ii(a[i], b[i]));
    sort(seq.begin(), seq.end());
    for (int i = 0; i < n; i++) if (i != ind)
        res = max(res, b[i] - a[i] + 1 + max(0, b[ind] - seq.back().first + 1));
    while (seq.size() > 1) {
        ii p = seq.back(); seq.pop_back();
        mn = max(mn, p.first); mx = min(mx, p.second);
        res = max(res, max(0, mx - mn + 1) + max(0, b[ind] - seq.back().first + 1));
    }
    printf("%d\n", res);
