int n, u, v, le, l[200000], r[200000];
pp t[200000];

void Input()
{
    ios_base::sync_with_stdio(0);       cin.tie(0);

    cin >> n;       r[0] = 1e9+1;
    for (int i=1; i<=n; i++)
    {
        cin >> l[i] >> r[i];
        if (l[u] < l[i]) u = i;
        if (r[v] > r[i]) v = i;
    }
}

bool cmp(const pp &l, const pp &r)
{
    return l.x < r.x;
}

void Process()
{
    int ans = 0;
    for (int i=1; i<=n; i++)
    {
        t[i].x = max(r[i] - l[u] + 1, 0);
        t[i].y = max(r[v] - l[i] + 1, 0);
        if (i != u && i != v)
            le = max(le, r[i] - l[i] + 1);

    }

    sort(t + 1, t + n + 1, cmp);

    int k = 0;
    for (int i=2; i<=n; i++)
        k = max(k, t[i].y);
    ans = k + t[1].x;

    k =1e9+1;
    for (int i=2; i<=n; i++)
    {
        k = min(k, t[i-1].y);
        ans = max(ans, t[i].x + k);
    }

    cout << max(le + max(r[v] - l[u] + 1, 0), ans);
}

int main()
{
    Input();
    Process();
    return 0;
}

