		LLPair temp;

		temp.L = max(Q[0].L, Q[i].L);
		temp.R = min(Q[0].R, Q[i].R);

		if (temp.joy() < minJoy) {
			g2index = i;
			minJoy = temp.joy();
		}
		else if (temp.joy() == minJoy) {
			if (Q[i].joy() > maxWidth) {
				g2index = i;
				minJoy = temp.joy();
			}
		}
	}

	g1.L = Q[0].L;
	g1.R = Q[0].R;
	g2.L = Q[g2index].L;
