		g1next.R = min(g1.R, Q[i].R);

		LLPair g2next;
		g2next.L = max(g2.L, Q[i].L);
		g2next.R = min(g2.R, Q[i].R);

		if (g1.joy() - g1next.joy() > g2.joy() - g2next.joy()) {
			g2.L = g2next.L;
			g2.R = g2next.R;
		}
		else {
			g1.L = g1next.L;
			g1.R = g1next.R;
		}
	}

	ll result = g1.joy() + g2.joy();

	printf("%lld\n", result);
}


