using namespace std;

long long solve(int N, vector<int> L, vector<int> R)
{
    vector<pair<int,int>> tmp;
    for (int i=0; i<N; i++)
        tmp.push_back(make_pair(R[i], -L[i]));
    sort(tmp.begin(), tmp.end());
    for (int i=0; i<N; i++)
        R[i] = tmp[i].first,
        L[i] = -tmp[i].second;

    vector<int> L2, R2;
    L2.push_back(L[0]);
    R2.push_back(R[0]);
    int maxL = L[0];
    for (int i=1; i<N; i++)
    {
        if (L[i] > maxL)
        {
            L2.push_back(L[i]);
            R2.push_back(R[i]);
            maxL = L[i];
        }
    }
    int N2 = (int)L2.size();

    long long ans = 0;
    if (N2==1)
    {
        ans = R[0]-L[0]+1LL + R[N-1]-L[N-1]+1LL;
    }
    else
    {
        for (int i=0; i<N2-1; i++)
            ans = max(ans,
                max(0LL, R2[0]-L2[i]+1LL) +
                max(0LL, R2[i+1]-L2[N2-1]+1LL));
    }

    for (int i=0; i<N; i++)
        ans = max(ans, R[i]-L[i]+1LL);

    return ans;
}

long long naive(int N, vector<int> L, vector<int> R)
{
    int l1 = 1;
    int r1 = 1000000000;
    int l2 = 1;
    int r2 = 1000000000;
    long long ans = 0;

    for (int b=1; b<(1<<N)-1; b++)
    {
        for (int i=0; i<N; i++)
        {
            if (b>>i&1)
            {
                l1 = max(l1, L[i]);
                r1 = min(r1, R[i]);
            }
            else
            {
                l2 = max(l2, L[i]);
                r2 = min(r2, R[i]);
            }
        }
        ans = max(ans, max(r1-l1+1LL, 0LL)+max(r2-l2+1LL, 0LL));
    }
    return ans;
}

