bool cmp(EVENT a, EVENT b)
{
    if(a.poz!=b.poz)
        return a.poz<b.poz;
    return B[a.ind]>B[b.ind];
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

    int n;
    cin>>n;
