    for(int i=1; i<=n; i++)
    {
        cin>>A[i]>>B[i];
        Ev[i]={A[i],i};
        rez=max(rez,B[i]-A[i]+1);
    }

    sort(Ev+1,Ev+n+1,cmp);

    set<int> Min;
    for(int i=1; i<=n; i++)
    {
        Min.insert(B[Ev[i].ind]);
        int dr=*Min.begin();
        ValSt[i]=max(0,dr-Ev[i].poz+1);
    }

    Min.clear();
    int prv=0;
    for(int i=n; i>=2; i--)
    {
        Min.insert(B[Ev[i].ind]);
        int dr=*Min.begin();
        prv=max(0,dr-Ev[n].poz+1);
        rez=max(rez,prv+ValSt[i-1]);
    }

    cout<<rez<<"\n";
    return 0;
}

