  ll mx = -1; // max of l
  ll mn = INF; // min of r
  rep(i, N) {
    ll l, r;
    cin >> l >> r;
    ++r;
    lr.emplace_back(l, r);
    chmax(mx, l);
    chmin(mn, r);
  }

  ll ans = 0;

