int solve(vector<ii>& a) {
  int n = a.size();
  vector<ii> L(n), R(n);
  L[0] = a[0];
  for (int i = 1; i < n; ++i) {
    L[i] = L[i - 1];
    L[i].first = max(L[i].first, a[i].first);
    L[i].second = min(L[i].second, a[i].second);
  }
  R[n - 1] = a[n - 1];
  for (int i = n - 2; i >= 0; --i) {
    R[i] = R[i + 1];
    R[i].first = max(R[i].first, a[i].first);
    R[i].second = min(R[i].second, a[i].second);
  }
  int ret = 0;
  for (int i = 0; i < n - 1; ++i) {
    int X = max(0, L[i].second - L[i].first + 1);
    int Y = max(0, R[i + 1].second - R[i + 1].first + 1);
    // trace(i, X, Y);
    ret = max(ret, X + Y);
  }
  return ret;
}

int main() {
  int n;
  scanf("%d", &n);
  vector<ii> a(n);
  for (int i = 0; i < n; ++i) {
    scanf("%d%d", &a[i].first, &a[i].second);
  }
  sort(a.begin(), a.end());
  int ret = solve(a);
  sort(a.begin(), a.end(), [](const ii& u, const ii& v) {
                             return u.first + u.second < v.first + v.second;
                           });
  ret = max(ret, solve(a));
  for (auto& it : a) {
    it.first = -it.first;
    it.second = -it.second;
    swap(it.first, it.second);
  }
  sort(a.begin(), a.end());
  ret = max(ret, solve(a));
  printf("%d\n", ret);
  return 0;
}

