ll modPow(ll x,ll n,ll mod){
	ll r=1;
	x = x%mod;
	while(n){
		if(n&1)r = (r*x)%mod;
		x = (x*x)%mod;
		n = n>>1;
	}
	return r;
}



ll gcd(ll a,ll b,ll &x,ll &y){
	if(a==0){
		x = 0;
		y = 1;
		return b;
	}
	ll x1,y1;
	ll g = gcd(b%a,a,x1,y1);
	x = y1 - (b/a)*x1;
	y = x1;
	return g;
}

