bool prime(ll n){
	if(n==1) return false;
	if(n==2) return true;
	if(n%2==0)return false;
	ll r=0,d,i,j,k,l;
	l = n-1;
	while(l%2==0){l=l/2;r++;}
	d = l;
	vector<ll> A = {2,3,5,7,11,13,17,19,23};
	for(auto a:A){
		if(a>n-2) break;
		ll x = modPow(a,d,n);
		if(x==1||x==n-1) continue;
		bool test=false;
		for(i=0;i<r;++i){
			x = (x*x)%n;
			if(x==n-1){
				test=true;
				break;
			}
		}
		if(test)
			continue;
		return false;
	}
	return true;
}

