    MinLen = min(MinLen,LR[i].second-LR[i].first+1);
  }
  //問題をソート
  sort(LR.begin(),LR.end());
  //他を含むものを消す
  vector<pair<int,int>> LR2;
  LR2.push_back(LR[0]);
  for (int i = 1; i < N; i++){
    LR2.push_back(LR[i]);
    int a,b,c,d;
    a = LR2[LR2.size()-2].first;
    b = LR2[LR2.size()-2].second;
    c = LR2[LR2.size()-1].first;
    d = LR2[LR2.size()-1].second;
    if (a<=c && d<=b){
      //[c,d]が[a,b]に含まれるので[a,b]を消す
      LR2.pop_back();
      LR2.pop_back();
      LR2.push_back(make_pair(c,d));
    } else if (c<=a && b<=d){
      //[a,b]が[c,d]に含まれるので[c,d]を消す
      LR2.pop_back();
    }
  }
  if (LR2.size()==1){
    cout << MaxLen + MinLen;
  } else {
    int M = LR2.size();
    long long Max = 0;
    for (int i = 0; i < M-1; i++){
      long long H = LR2[0].second-LR2[i].first+1+LR2[i+1].second-LR2[M-1].first+1;
      Max = max(Max,H);
    }
    //MaxLenであるものが存在するか調べる
    bool flg = false;
    for (int i = 0; i < M; i++){
      if (LR2[i].second-LR2[i].first+1==MaxLen) flg=true;
