using namespace std;
using llong = long long;
using ldbl = long double;
using lpair = pair<llong, llong>;

#define ALL(x) x.begin(), x.end()

const llong inf = 1'000'000'000'000'007ll;
const llong mod = 1e9+7;

struct data {
	llong L;
	llong R;

	data() = default;
	data(llong L, llong R) :
		L(L),
		R(R)
	{}

	bool operator<(const data &ri) const {
		return R - L < ri.R - ri.L;
	}
};

int main() {
	llong N;
	vector<data> tasks;

	cin >> N;
	tasks.resize(N);
	for (auto &task: tasks) {
		cin >> task.L >> task.R;
	}
	sort(ALL(tasks));

	set<pair<data, data>> s1, s2;
	s1.emplace(data(-inf, inf), data(-inf, inf));
	for (auto &task: tasks) {
		while (s1.size()) {
			data fst = s1.begin()->first;
			data snd = s1.begin()->second;
			s1.erase(s1.begin());

			data next;

			// fst
			next.L = max(fst.L, task.L);
			next.R = min(fst.R, task.R);
			if (next.L > next.R) {
				next = data(inf, -inf);
			}
			if (next < snd) {
				s2.insert({next, snd});
			} else {
				s2.insert({snd, next});
			}

			// snd
			next.L = max(snd.L, task.L);
			next.R = min(snd.R, task.R);
			if (next.L > next.R) {
				next = data(inf, -inf);
			}
			if (next < fst) {
				s2.emplace(next, fst);
			} else {
				s2.emplace(fst, next);
			}
		}
		swap(s1, s2);
	}

	llong ret = 0;
	for (auto &s: s1) {
		if (s.first.R == inf || s.second.R == inf) continue;
		ret = max(ret, max(0ll, s.first.R - s.first.L + 1ll) + max(0ll, s.second.R - s.second.L + 1ll));
	}

	cout << ret << endl;

	return 0;
}


