int main(){
	int n;
	std::cin>>n;

	std::vector<seg> aList(n);

	for(int i=0; i<n; i++)
		std::cin>>aList[i].left>>aList[i].right;

	std::stable_sort(aList.begin(), aList.end(), [](const seg &x, const seg &y){return x.left < y.left;});	
	std::stable_sort(aList.begin(), aList.end(), [](const seg &x, const seg &y){return x.right-x.left > y.right-y.left;});

	std::vector<long long> maxLeftUp(n);
	std::vector<long long> minRightUp(n);
	std::vector<long long> maxLeftDn(n);
	std::vector<long long> minRightDn(n);

	maxLeftUp[0]= aList[0].left;
	minRightUp[0]= aList[0].right;

	maxLeftDn[n-1]= aList[n-1].left;
	minRightDn[n-1]= aList[n-1].right;

	for(int i=1; i<n; i++){
		maxLeftUp[i]= (aList[i].left > maxLeftUp[i-1])? aList[i].left : maxLeftUp[i-1];
		minRightUp[i]= (aList[i].right < minRightUp[i-1])? aList[i].right : minRightUp[i-1];
	}

	for(int i= n-2; i>=0; i--){
		maxLeftDn[i]= (aList[i].left > maxLeftDn[i+1])? aList[i].left : maxLeftDn[i+1];
		minRightDn[i]= (aList[i].right < minRightDn[i+1])? aList[i].right : minRightDn[i+1];		
	}

	long long ans=0;

	for(int i=0; i<n-1; i++){
		long long tmp=0;

		tmp+= (minRightUp[i]-maxLeftUp[i]+1 > 0)? minRightUp[i]-maxLeftUp[i]+1 : 0;
		tmp+= (minRightDn[i+1]-maxLeftDn[i+1]+1 > 0)? minRightDn[i+1]-maxLeftDn[i+1]+1 : 0;

		if(tmp>ans)
			ans= tmp;
	}

	std::cout<<ans<<std::endl;

	return 0;

}

