using ll = long long;
using vi = vector<int>;
using vl = vector<ll>;
using Graph = vector<vi>;  // vi <=> vl
using vb = vector<bool>;
using boolGraph = vector<vb>;
using P = pair<int, int>;  // int <=> ll
const int MOD = 1e9+7;
const double EPS = 1e-9;

int main() {
  int n; cin >> n;
  Graph G(n, vi(2));
  rep(i,n) rep(j,2) cin >> G[i][j];

  sort(all(G));

  int a = 0, b = -1;
  int a_end;
  bool zero = false;

  for (int i=1; i<n; ++i) {
    if (b == -1) {
      if (G[i][0] > G[a][1]) {
        b = i;
        a_end = i - 1;
      }
      else if (G[i][1] < G[a][1]) {
        a = i;
      }
    }

    else {
      if (G[i][0] > G[b][1]) {
        zero = true;
        break;
      }
      else if (G[i][1] < G[b][1]) {
        b = i;
      }
    }
  }

  if (zero) {
    int ans = 0;
    rep(i,n) ans = max(ans, G[i][1] - G[i][0] + 1);
    cout << ans << endl;
    return 0;
  }

  if (a == n-1) {
    int ans = G[n-1][1] - G[n-1][0] + 1;
    int tmp = 0;
    rep(i,n) tmp = max(tmp, G[i][1] - G[i][0] + 1);
    cout << ans + tmp << endl;
    return 0;
  }

  Graph rest;
  int last = b == -1 ? n-1 : a_end;
  int r = b == -1 ? n-1 : b;
  for (int i=a+1; i<=last; ++i) {
    if (G[i][1] < G[r][1]) rest.push_back(G[i]);
    else if (b != -1) a_end = i;
  }

  Graph right(rest.size(), vi(2));
  rep(i,rest.size()) {
    right[i][0] = rest[i][1];
    right[i][1] = i;
  }
  sort(all(right));

  int ans;
  if (b == -1) {
    ans = (G[a][1] - G[n-1][0] + 1) * 2 + max(G[n-1][0] - G[a][0], G[n-1][1] - G[a][1]);
    int tmp = 0;
    rep(i,n) tmp = max(tmp, G[i][1] - G[i][0] + 1);
    ans = max(ans, (G[a][1] - G[n-1][0] + 1) + tmp);
  }

  else {
    rep(i,n) ans = max(ans, G[i][1] - G[i][0] + 1);
  }

  int k = 0;
  rep(i,rest.size()-1) {
    while (right[k][1] <= i) ++k;
    ans = max(ans, (G[a][1] - rest[i][0] + 1) + (right[k][0] - G[n-1][0] + 1));
  }

  cout << ans << endl;
  return 0;
}

