const int maxn = (int)1e6 + 3, base = 998244353;
const ll llinf = 2e18 + 5;

int binpow(int a, int s) { 
    int res = 1;
    while (s) {
        if (s % 2) {
            res = 1ll * res * a % base;
        }
        a = 1ll * a * a % base;
        s /= 2;
    }
    return res;
}

