#define MOD 1000000007
#define REP(i, N) for (int i = 0; i < N; ++i)
#define REP1(i, N) for (int i = 1; i <= N; ++i)
#define RREP(i, N) for (int i = N - 1; i >= 0; --i)
#define ALL(a) a.begin(), a.end()

int main() {
  int n;
  cin >> n;
  ll l[n], r[n];
  REP(i, n) cin >> l[i] >> r[i];
  vector<LLP> vec;
  REP(i, n) vec.push_back(LLP(r[i] - l[i], P(l[i], r[i])));
  sort(ALL(vec));
  reverse(ALL(vec));
  ll Rmin1[n], Rmin2[n];
  ll Lmax1[n], Lmax2[n];
  Rmin1[0] = vec[0].second.second, Lmax1[0] = vec[0].second.first;
  for (int i = 1; i < n - 1; ++i) {
    Rmin1[i] = min(Rmin1[i - 1], vec[i].second.second);
    Lmax1[i] = max(Lmax1[i - 1], vec[i].second.first);
  }
  Rmin2[n - 1] = vec[n - 1].second.second,
            Lmax2[n - 1] = vec[n - 1].second.first;
  for (int i = n - 2; i >= 1; --i) {
    Rmin2[i] = min(Rmin2[i + 1], vec[i].second.second);
    Lmax2[i] = max(Lmax2[i + 1], vec[i].second.first);
  }
  ll ans = 0;
  REP(i, n - 1) {
    ll tmp1 = (Rmin1[i] - Lmax1[i]) + 1;
    ll tmp2 = (Rmin2[i + 1] - Lmax2[i + 1]) + 1;
    ans = max(ans, tmp1 + tmp2);
  }
  cout << ans << endl;
  return 0;
}

