constexpr ll INFLL = 1LL<<62;
constexpr long double EPS = 1e-12;
constexpr ll MOD = (ll)((1E+9)+7);

ll N;

ll search(vpll RL){
  vll L(N);
  ll L_max = RL[0].second;

  REP(i,N){
    chmax(L_max, RL[i].second);
    L[i] = max((ll)0, RL[0].first - L_max + 1);
  }

  vll R(N);
  L_max = RL[N-1].second;

  RREP(i,N-1){
    chmax(L_max, RL[i].second);
    R[i] = max((ll)0, RL[i].first - L_max + 1);
  }

  ll ans = 0;
  REP(i,N-1){
    chmax(ans, L[i]+R[i+1]);
  }

  return ans;
}

int main(){
  cin.tie(0); // cut the cin and cout (default, std::flush is performed after std::cin)
  ios::sync_with_stdio(false); // cut the iostream and stdio (DON'T endl; BUT "\n";)

  IN(N);
  vpll RL(N);
  REP(i,N){
    IN(RL[i].second, RL[i].first);
    RL[i].second = RL[i].second;
  }

  ll L_index = 0;
  ll R_index = 0;

  REP(i,N){
    if(RL[L_index].second < RL[i].second) L_index = i;
    if(RL[R_index].first > RL[i].first) R_index = i;
  }

  ll ans = 0;

  if(RL[L_index].second <= RL[R_index].first){
    ll tmp = 0;
    if(L_index!=R_index){
      REP(i,N){
        if(i==L_index) continue;
        if(i==R_index) continue;
        chmax(tmp, RL[i].first - RL[i].second);
      }
    }
    ans = tmp;
  }

  REP(i,N){
    RL[i].second = -RL[i].second;
  }

  sort(ALL(RL));

  REP(i,N){
    RL[i].second = -RL[i].second;
  }

  chmax(ans,search(RL));

  REP(i,N){
    swap(RL[i].first, RL[i].second);
    RL[i].first =  - RL[i].first;
    RL[i].second = RL[i].second;
  }

  sort(ALL(RL));

  REP(i,N){
    RL[i].second = -RL[i].second;
  }

  chmax(ans, search(RL));
  OUT(ans);

  return 0;
}

