void solve(){
  inl(N);
  vp v(N); in(v);
  sort( all(v) , [&]( P a,P b ){
    return a.fi == b.fi ? a.se > b.se : a.fi < b.fi;
  });
  // 右端をsetで管理
  map<int,int> a , b;
  vl ans(N - 1) , bns(N - 1);
  // 切れ目は[0 , i)と[i , N)の間
  rep(i , N - 1){
    // 左から入れてく
    a[v[i].se]++;
    ans[i] = max(0 , (*a.begin()).fi - v[i].fi + 1);
  }
  repr(i , N - 1){
    // 右から入れてく
    b[v[i + 1].se]++;
    bns[i] = max(0 , (*b.begin()).fi - v[N - 1].fi + 1);
  }
  ll aaa = 0;
  rep(i , N - 1) amax(aaa , ans[i] + bns[i]);
  out(aaa);
}

