	std::vector<int> L(n), R(n), com;
	std::vector<std::pair<int, int>> X, Y;
	for(int i = 0; i < n; i++) {
		scanf("%d%d", &L[i], &R[i]);
		L[i]--;

		X.push_back({L[i], R[i]});
		Y.push_back({R[i], L[i]});
		com.push_back(L[i]);
		com.push_back(R[i]);
	}
	sort(begin(X), end(X)); sort(begin(Y), end(Y));
	sort(begin(com), end(com));
	com.push_back(1e9);
	com.erase(unique(begin(com), end(com)), end(com));

	using P = std::pair<int, int>;
	std::priority_queue<P> qu;
	for(int i = 0; i < n; i++) {
		qu.push({L[i], i});
	}

	int ans = 0, kiri = 0, tan = 1 << 30;
	for(int i = 0; i < n - 1; i++) {
		int x = Y[i].second, y = Y[i].first;
		kiri = std::max(kiri, x);
		tan = std::min(tan, y);

		if(!(kiri < tan)) break;

		while(qu.size() > 1 and (qu.top().second != i and qu.top().first <= kiri)) {
	//		cout << i << " " << qu.top().first << endl;
			qu.pop();
		}
		int r = Y[i + 1].first, l = qu.top().first;
