//		cout << "ei: " << kiri << " " << tan << " " <<  l << " " << r << endl;
//		cout << (tan - kiri) << " " << (r - l) << endl;

		if(!qu.empty()) ans = std::max(ans, (tan - kiri) + (r - l));
	}
	printf("%d\n", ans);
	return 0;
}

