    int l, r;
    range() : l(0), r(0) {}
    range(int l, int r) : l(l), r(r) {
        if (l > r) this->l = this->r = -1;
    }
    bool operator< (const range& rhs) const {
        if (l != rhs.l) return l < rhs.l;
        return r < rhs.r;
    }
    range operator* (const range& rhs) const {
        if (rhs.l == 0) return *this;
        if (l == 0) return rhs;
        return range(max(l, rhs.l), min(r, rhs.r));
    }
    int length() const {
        if (l == -1) return 0;
        return r - l + 1;
    }
};

range a[100002], rsum[100002], lsum[100002];

int main() {
    cin.tie(nullptr);
    cout.tie(nullptr);
    ios_base::sync_with_stdio(false);

    int n;
    cin >> n;
    for (int i = 1; i <= n; i++) {
        cin >> a[i].l >> a[i].r;
    }
    sort(a + 1, a + n + 1);

    for (int i = n; i >= 1; i--) {
        rsum[i] = rsum[i + 1] * a[i];
    }
    for (int i = 1; i <= n; i++) {
        lsum[i] = lsum[i - 1] * a[i];
    }

    int mx = 0;
    for (int i = 1; i < n; i++) {
        mx = max(mx, lsum[i].length() + rsum[i + 1].length());
    }
    cout << mx;

    return 0;
}

