void solve() {
    ll n;
    cin >> n;
    vector<pair<ll, ll>> v(n);
    for (int i = 0; i < n; ++i) {
        cin >> v[i].first >> v[i].second;
    }
    sort(v.begin(), v.end());
    vector<pair<ll, ll>> leftIntersection(n);
    leftIntersection[0] = v[0];
    for (int i = 1; i < n; ++i) {
        if (leftIntersection[i - 1].first == 1 && leftIntersection[i - 1].second == 0) {
            leftIntersection[i] = leftIntersection[i - 1];
            continue;
        }
        leftIntersection[i].first = max(leftIntersection[i - 1].first, v[i].first);
        leftIntersection[i].second = min(leftIntersection[i - 1].second, v[i].second);
        if (leftIntersection[i].first > leftIntersection[i].second) {
            leftIntersection[i].first = 1;
            leftIntersection[i].second = 0;
        }
    }

    vector<pair<ll, ll>> rightIntersection(n);
    rightIntersection[n - 1] = v[n - 1];
    for (int i = n - 2; i >= 0; --i) {
        if (rightIntersection[i + 1].first == 1 && rightIntersection[i + 1].second == 0) {
            rightIntersection[i] = rightIntersection[i + 1];
            continue;
        }
        rightIntersection[i].first = max(rightIntersection[i + 1].first, v[i].first);
        rightIntersection[i].second = min(rightIntersection[i + 1].second, v[i].second);
        if (rightIntersection[i].first > rightIntersection[i].second) {
            rightIntersection[i].first = 1;
            rightIntersection[i].second = 0;
        }
    }
    ll ans = 0;
    for (int i = 0; i < n - 1; ++i) {
        ll left = leftIntersection[i].second - leftIntersection[i].first + 1;
        ll right = rightIntersection[i + 1].second - rightIntersection[i + 1].first + 1;
        ans = max(ans, left + right);
    }
    cout << ans << "\n";
}

int main() {
    // freopen("input.txt", "r", stdin);
    // freopen("output.txt", "w", stdout);
    solve();
    return 0;
}

