using namespace std;
typedef long long ll;

int range(int l, int r) {
    if (l > r) {
        return 0;
    } else {
        return r - l + 1;
    }
}

int range_and(int l1, int r1, int l2, int r2) {
    if (l1 > r1 || l2 > r2) {
        return 0;
    } else {
        int r = min(r1, r2);
        int l = max(l1, l2);
        return range(l, r);
    }
}

int solve(const vector<pair<int, int>> &v) {
    int N = v.size();
    vector<pair<int, int>> other(N+1);
    int l = 1;
    int r = 1000000000;
    for (int i = N-1; i >= 0; i--) {
        if (l < v[i].first) {
            l = v[i].first;
        }
        if (r > v[i].second) {
            r = v[i].second;
        }
        if (l > r) {
            l = 0;
            r = -1;
        }
        other[i].first = l;
        other[i].second = r;
    }
    //for (int i = 0; i < N; i++) {
    //    cout << ": " << v[i].first << " " << v[i].second << " " << other[i].first << " " << other[i].second << endl;
    //}
    int rmax = 0;
    int rmin = 1000000000;
    int ans = 0;
    for (int i = 0; i < N;) {
        int j = i + 1;
        for (; j < N; j++) {
            if (v[j].first != v[i].first) {
                break;
            }
        }
        rmax = max(rmax, v[j-1].second);
        rmin = min(rmin, v[i].second);
        //cout << "rmin=" << rmin << ", rmax=" << rmax << endl;
        if (i == 0 && j == i+1) {
            int s1 = range(
                other[j == N ? N-1 : j].first,
                other[j == N ? N-1 : j].second
            ) + range(v[i].first, v[i].second);
            //cout << "s1=" << s1 << endl;
            ans = max(ans, s1);
        } else if (j < N || j == i+1) {
            int s0 = range(
                other[j].first,
                other[j].second
            ) + range(v[i].first, rmin);
            int s1 = range_and(
                other[j].first,
                other[j].second,
                v[i].first,
                rmin
            ) + range(v[i].first, rmax);
            int s2 = range_and(
                other[j].first,
                other[j].second,
                v[i].first,
                rmax
            ) + range(v[i].first, rmin);
            //cout << "s0=" << s0 << ", s1=" << s1 << ", s2=" << s2 << endl;
            ans = max(ans, max(s0, max(s1, s2)));
        } else {
            int s0 = range(
                v[N-1].first,
                v[N-1].second
            ) + range(v[i].first, rmin);
            int s1 = range(
                v[i].first,
                v[i].second
            ) + range(v[i].first, rmax);
            //cout << "s0=" << s0 << ", s1=" << s1 << endl;
            ans = max(ans, max(s0, s1));
        }
        i = j;
    }
    return ans;
}

int main() {
    int N;
    cin >> N;
    vector<pair<int, int>> v(N);
    for (int i = 0; i < N; i++) {
        cin >> v[i].first >> v[i].second;
    }
    sort(v.begin(), v.end());
    int ans = solve(v);
    cout << ans << endl;
}

