    for (auto &e : a) {
        cin >> e.first >> e.second;
    }

    auto solve = [&] () -> int {
        vector<int> s(n), t(n);
        int l = 1, r = MAX;
        for (int i = 0; i < n; i++) {
            const auto &e = a[i];
            chval(l, <, e.first);
            chval(r, >, e.second);
            s[i] = max(0, r - l + 1);
        }
        l = 1; r = MAX;
        for (int i = n; i --> 0;) {
            const auto &e = a[i];
            chval(l, <, e.first);
            chval(r, >, e.second);
            t[i] = max(0, r - l + 1);
        }
        int res = 0;
        for (int i = 0; i + 1 < n; i++) {
            chval(res, <, s[i] + t[i + 1]);
        }
        return res;
    };

    using P = pair<int, int>;
    auto com1 = [](const P &l, const P &r) -> bool {
        if (l.second == r.second) return (l.first < r.first);
        return (l.second < r.second);
    };
    auto com2 = [](const P &l, const P &r) -> bool {
        if (l.first == r.first) return (l.second < r.second);
        return (l.first < r.first);
    };

    int ans = 0;
    sort(a.begin(), a.end(), com1);
    ans = max(ans, solve());
    sort(a.begin(), a.end(), com2);
    ans = max(ans, solve());

