    for (ll i = 0; i < n; ++i) {
        ll l, r;
        cin >> l >> r;
        ++r;
        lines.eb(l, r, i);
        maxlen = max(maxlen, lines.back().len());
        auto& curr = lines.back();
    }

    sort(all(lines), [](const Line& x, const Line& y) {
        if (x.r != y.r) return x.r < y.r;
        if (x.l != y.l) return x.l < y.l;
        if (x.id != y.id) return x.id < y.id;
    });
    Line left = lines.front();

    sort(all(lines), [](const Line& x, const Line& y) {
        if (x.l != y.l) return x.l > y.l;
        if (x.r != y.r) return x.r > y.r;
        if (x.id != y.id) return x.id > y.id;
    });

    Line right = lines.front();

    if (left.id == right.id) {
        ll second_maxlen = 0;
        for (ll i = 0; i < n; ++i) {
            if (lines[i].id == left.id) continue;
            second_maxlen = max(second_maxlen, lines[i].len());
        }
        cout << (second_maxlen + left.len()) << endl;
        return 0;
    }

    ll left_id = left.id;
    ll right_id = right.id;

    vector<Line> big;
    for (auto& line : lines) {
        if (line.id == left_id || line.id == right_id) continue;
        Line li = left.intersect(line);
        Line ri = right.intersect(line);

        if (li.empty()) {
            right = right.intersect(line);
        } else if (ri.empty()) {
            left = left.intersect(line);
        } else {
            big.pb(line);
        }

        if (left.empty() || right.empty()) { cout << maxlen << endl; return 0; }
    }

    if (big.empty()) {
        cout << left.len() + right.len() << endl;
        return 0;
    }

    sort(all(big), [](const Line& x, const Line& y) {
        if (x.l != y.l) return x.l < y.l;
        if (x.r != y.r) return x.r < y.r;
        if (x.id != y.id) return x.id > y.id;
    });

    ll ans = maxlen;
    multiset<ll> right_ends;
    for (Line line : big) {
        right_ends.insert(line.r);
    }
    auto kek = [&]() {
        ll left_len = left.len();
        ll right_r = min(right.r, *right_ends.begin());
        ll right_len = max(0LL, (right_r - right.l));
        upd(ans, left_len + right_len);
    };

    kek();
    ll big_size = sz(big);
    for (ll i = 0; i < big_size; ++i) {
        left = left.intersect(big[i]);
        right_ends.erase(right_ends.find(big[i].r));
        kek();
    }

    cout << ans << endl;
    print_time();
    return 0;
}

