//------------------------------- Solver ------------------------------------//

void solve()
{
    int n;
    cin >> n;
    akari<pair<i64, i64>> ps(n);
    for (int i = 0; i < n; i++)
    {
        cin >> ps[i].first >> ps[i].second;
    }
    sort(ps.begin(), ps.end());
    akari<i64> ls1(n), rs1(n), ls2(n), rs2(n);
    ls1[0] = ps[0].first;
    rs1[0] = ps[0].second;
    for (int i = 1; i < n; i++)
    {
        ls1[i] = ps[i].first;
        rs1[i] = min(rs1[i - 1], ps[i].second);
    }
    ls2[n - 1] = ps[n - 1].first;
    rs2[n - 1] = ps[n - 1].second;
    for (int i = n - 2; i >= 0; i--)
    {
        ls2[i] = max(ls2[i + 1], ps[i].first);
        rs2[i] = min(rs2[i + 1], ps[i].second);
    }
    i64 ans = 0;
    for (int i = 1; i < n - 1; i++)
    {
        ans = max(ans, ps[i].second - ps[i].first + i64(1) + max(min(rs2[i + 1], rs1[i - 1]) - ls2[i] + i64(1), i64(0)));
    }
    cout << ans << endl;
}

int main()
{
    solve();
    return 0;
}

