ll modpow(ll x, ll b){
	ll res = 1;
	while(b){
		if(b&1)res = res * x % MOD;
		x = x * x % MOD;
		b>>=1;
	}
	return res;
}

ll modinv(ll x){
	return modpow(x, MOD-2);
}

int main(){
	int n;
	cin >> n;
	vector<pll> line(n);
	foreach(i, line)cin>>i.first>>i.second;
	sort(all(line), greater<pll>());
	line.insert(line.begin(), pll(0, 0));
	set<pll> s;
	multiset<ll> als;
	multiset<ll> ars;
	multiset<ll> bls;
	multiset<ll> brs;
	repa(i, n+1){
		s.emplace(line[i].first, i);
		s.emplace(line[i].second+1, -i);
		bls.insert(line[i].first);
		brs.insert(line[i].second);
	}
	ll ans = 0;
	foreach(i, s){
		if(i.second>0){
			int place = i.second;
			als.insert(line[place].first);
			ars.insert(line[place].second);
			bls.erase(bls.find(line[place].first));
			brs.erase(brs.find(line[place].second));
			if(bls.empty())continue;
			ll sum = max(0ll, *ars.begin() - *als.rbegin() + 1) + max(0ll, *brs.begin() - *bls.rbegin() + 1);
			chmax(ans, sum);
		}else{
			int place = -i.second;
			als.erase(als.find(line[place].first));
			ars.erase(ars.find(line[place].second));
			bls.insert(line[place].first);
			brs.insert(line[place].second);
			if(als.empty())continue;
			ll sum = max(0ll, *ars.begin() - *als.rbegin() + 1) + max(0ll, *brs.begin() - *bls.rbegin() + 1);
			chmax(ans, sum);
		}
	}
	als.clear();
	ars.clear();
	repa(i, n+1){
		als.insert(line[i].first);
		ars.insert(line[i].second);
	}
	repa(i, n+1){
		ll sum = line[i].second - line[i].first + 1;
		als.erase(als.find(line[i].first));
		ars.erase(ars.find(line[i].second));
		sum += max(0ll, *ars.begin() - *als.rbegin() + 1);
		als.insert(line[i].first);
		ars.insert(line[i].second);
		chmax(ans, sum);
	}

	cout <<  ans << endl;
	return 0;
}

