const ll LLINF = (1LL<<60);
const int INF = (1LL<<30);
const double DINF = std::numeric_limits<double>::infinity();
const int MOD = 1000000007;
#define MAX_N 100010

ll N;
vector<ll> L, R;
vector< pair<ll, ll> > LR;

// 範囲 [l, r] のものを 1 問目、それ以外を 2 問目にした場合の
// 楽しさ
ll GetFun(ll l, ll r) {
    ll l_max[2] = { -LLINF, -LLINF };
    ll r_min[2] = { LLINF, LLINF };
    bool isValid[2] = {};

    for(auto& lr : LR) {
        if(l <= lr.first && lr.second <= r) {
            l_max[0] = max(l_max[0], lr.first);
            r_min[0] = min(r_min[0], lr.second);
            isValid[0] = true;
        }
        else {
            l_max[1] = max(l_max[1], lr.first);
            r_min[1] = min(r_min[1], lr.second);
            isValid[1] = true;
        }
    }

    ll ret1 = r_min[0] - l_max[0] + 1;
    if(!isValid[0] || ret1 < 0) { ret1 = 0; }
    ll ret2 = r_min[1] - l_max[1] + 1;
    if(!isValid[1] || ret2 < 0) { ret2 = 0; }

    return ret1 + ret2;
}

ll fromRight(ll l_min) {
    ll lb = 0, ub = R.size() - 1;
    while(ub - lb > 2000) {
#if 1
        // 1000 分探索
        ll sub = (ub - lb) / 1000;
        ll next_val = -LLINF;
        ll next_ind = -1;
        for(int i = lb; i <= ub; i += sub) {
            ll cand_val = GetFun(l_min, R[i]);
            if(next_val < cand_val) {
                next_val = cand_val;
                next_ind = i;
            }
        }
        lb = max(0LL, next_ind - sub);
        ub = min(static_cast<ll>(R.size()) - 1LL, next_ind + sub);
#else
        ll t1 = (2 * lb + ub) / 3;
        ll t2 = (lb + 2 * ub) / 3;
        ll cand1 = GetFun(l_min, R[t1]);
        ll cand2 = GetFun(l_min, R[t2]);
        if(cand1 < cand2) {
            if(lb == t1) { break; } // もう変化しないくらい範囲が狭くなった
            lb = t1;
        }
        else {
            if(ub == t2) { break; }
            ub = t2;
        }
#endif
    }

    ll ret = -LLINF;
    ll ret_ind = -1;
    for(ll i = lb; i <= ub; ++i) {
        ll cand = GetFun(l_min, R[i]);
        if(ret < cand) {
            ret = cand;
            ret_ind = i;
        }
    }

    // 次に左側を狭める
    lb = 0, ub = L.size() - 1;
    while(ub - lb > 2000) {
        // 1000 分探索
        ll sub = (ub - lb) / 1000;
        ll next_val = -LLINF;
        ll next_ind = -1;
        for(int i = lb; i <= ub; i += sub) {
            if(L[i] > R[ret_ind]) { break; }
            ll cand_val = GetFun(L[i], R[ret_ind]);
            if(next_val < cand_val) {
                next_val = cand_val;
                next_ind = i;
            }
        }
        lb = max(0LL, next_ind - sub);
        ub = min(static_cast<ll>(L.size()) - 1LL, next_ind + sub);
    }
    for(ll i = lb; i <= ub; ++i) {
        ret = max(ret, GetFun(L[i], R[ret_ind]));
    }

    return ret;
}


ll fromLeft(ll r_max) {
    ll lb = 0, ub = L.size() - 1;
    while(ub - lb > 2000) {
        // 1000 分探索
        ll sub = (ub - lb) / 1000;
        ll next_val = -LLINF;
        ll next_ind = -1;
        for(int i = lb; i <= ub; i += sub) {
            ll cand_val = GetFun(L[i], r_max);
            if(next_val < cand_val) {
                next_val = cand_val;
                next_ind = i;
            }
        }
        lb = max(0LL, next_ind - sub);
        ub = min(static_cast<ll>(L.size()) - 1LL, next_ind + sub);
    }

    ll ret = -LLINF;
    ll ret_ind = -1;
    for(ll i = lb; i <= ub; ++i) {
        ll cand = GetFun(L[i], r_max);
        if(ret < cand) {
            ret = cand;
            ret_ind = i;
        }
    }

    lb = 0, ub = R.size() - 1;
    while(ub - lb > 2000) {
        // 1000 分探索
        ll sub = (ub - lb) / 1000;
        ll next_val = -LLINF;
        ll next_ind = -1;
        for(int i = lb; i <= ub; i += sub) {
            if(L[ret_ind] > R[i]) { break; }
            ll cand_val = GetFun(L[ret_ind], R[i]);
            if(next_val < cand_val) {
                next_val = cand_val;
                next_ind = i;
            }
        }
        lb = max(0LL, next_ind - sub);
        ub = min(static_cast<ll>(R.size()) - 1LL, next_ind + sub);
    }
    for(ll i = lb; i <= ub; ++i) {
        ret = max(ret, GetFun(L[ret_ind], R[i]));
    }

    return ret;
}

