    ios::sync_with_stdio(false);

    cin >> N;

    ll l_min = LLINF;   // L の中で最小のもの
    ll r_max = -LLINF;  // R の中で最大のもの

    ll ans = -LLINF;

    ll longest_ind = -1;
    ll longest_val = -LLINF;
    REP(i, N) {
        ll l, r;
        cin >> l >> r;
        L.push_back(l);
        R.push_back(r);
        LR.push_back(make_pair(l, r));

        l_min = min(l_min, l);
        r_max = max(r_max, r);

        ans = max(ans, r - l + 1);

        if(longest_val < ans) {
            longest_val = ans;
            longest_ind = i;
        }
    }

    // 1 番長いのとそれ以外のパターン
    ll cand = longest_val;
    ll l_max = -LLINF;
    ll r_min = LLINF;
    REP(i, N) {
        if(i == longest_ind) { continue; }
        l_max = max(l_max, LR[i].first);
        r_min = min(r_min, LR[i].second);
    }
    if(l_max <= r_min) {
        cand += r_min - l_max + 1;
        ans = max(ans, cand);
    }

    SORT(L);
    SORT(R);
    R.erase(unique(R.begin(), R.end()), R.end());
    L.erase(unique(L.begin(), L.end()), L.end());

    ans = max(ans, fromRight(l_min));
    ans = max(ans, fromLeft(r_max));

    printf("%lld\n", ans);

    return 0;
}

