        //cout3(i,from_start[i-1], from_last[i]);
        ans = max(ans, from_start[i-1] + from_last[i]);
    }
    lli ans2 = 0;
    lli index;
    // 特定の区間だけやるケース
    REP(i,0,n) {
        if (ans2 < p[i].second - p[i].first + 1) {
            ans2 = max(ans2, p[i].second - p[i].first + 1);
            index = i;
        }
    }
    cur_s = cur_e = -1;
    is_out = false;
    lli from;
    lli to;
    REP(i,0,n) {
        if (i == index)
            continue;
        if (cur_s == -1) {
            cur_s = from = p[i].first;
            cur_e = to = p[i].second;
        }
        else {
            from = p[i].first;
            to = p[i].second;
        }
        if (cur_e < from) {
            is_out = true;
        }
        else if (cur_e >= to) {
            cur_s = from;
            cur_e = to;
        }
        else {
            cur_s = from;
        }
    }
    if (!is_out)
        ans2 += cur_e - cur_s + 1;
    cout << max(ans, ans2) << endl;
}

