  int LmaxID, RminID;
  for (int i=0; i<N; i++) {
    std::cin >> L[i] >> R[i];
    if (Lmax<L[i]) {
      Lmax = L[i];
      LmaxID = i;
    }
    if (Rmin>R[i]) {
      Rmin = R[i];
      RminID = i;
    }
  }
  long long ans = 0;
  if (LmaxID == RminID) {
    ans = Rmin-Lmax+1;
    long long othermax = 0;
    for (int i=0; i<N; i++) {
      if (i==LmaxID) continue;
      othermax = std::max(othermax, R[i]-L[i]+1);
    }
    ans += othermax;
  } else {
    // Case 1: LmaxID & RminID are in the same group
    long long ans2 = 0;
    for (int i=0; i<N; i++) {
      if (i==LmaxID || i==RminID) continue;
      ans2 = std::max(ans2, R[i]-L[i]+1);
    }
