    std::sort(A.begin(), A.end(), std::greater<pii>());

    B.reserve(n), C.reserve(n), D.reserve(n);
    FOR(i, 1, n){
        if(A[i].second >= A[0].second) D.push_back(A[i]);
        else if(A[i].second > A[0].first) C.push_back(A[i]);
        else B.push_back(A[i]);
    }
    const int b = B.size(), c = C.size(), d = D.size();
    std::sort(C.begin(), C.end(), [](pii& a, pii& b){
        if(a.second != b.second) return a.second < b.second;
        return a.first < b.first;
    });

    int res = 0;
    REP(i, c) chmax(res, C[i].second - C[i].first);
    REP(i, d) chmax(res, D[i].second - D[i].first);
    if(b > 1) REP(i, b) chmax(res, B[i].second - B[i].first);

    int l = 0, r = 1e9 + 2;
    REP(i, b){
        if(l < B[i].first) l = B[i].first;
        if(r > B[i].second) r = B[i].second;
    }
    REP(i, c){
        if(l > 0) chmax(res, C[i].second - A[0].first + 
            ((r > l) ? r - l : 0)
        );

        if(l < C[i].first) l = C[i].first;
        if(r > C[i].second) r = C[i].second;
    }

    if(l == 0) REP(i, d) chmax(res, A[0].second - A[0].first + D[i].second - D[i].first);
    else chmax(res, A[0].second - A[0].first + ((r > l) ? r - l : 0));
    printf("%d\n", res);
    return 0;
}

