int ModExp(int x,int y,int m){
    int res = 1;
    x = x % m;
    while (y > 0)
    {
        if (y & 1)
            res = (res*x) % m;

        y = y>>1;
        x = (x*x) % m;
    }
    return res;
}

pii merge(pii a,pii b){
    pii ans;
    ans.first = max(a.first,b.first);
    ans.second = min(a.second,b.second);
    if(ans.second < ans.first){
        ans.second = ans.first;
    }
    return ans;
}

