			else L1=max(L1,L2),R1=min(R1,R2),L2=l,R2=r;
		}
		else{
			if(ans2>=ans3)L2=max(L2,l),R2=min(R2,r);
			else L1=max(L1,L2),R1=min(R1,R2),L2=l,R2=r;
		}
	}
	printf("%d\n",max(0,R1-L1+1)+max(0,R2-L2+1));
	return 0;
}

