void solve() {
    in(N);
    vi L, R;
    na2(L, R, N);
    sortp(L, R);
    //一つの場合
    vi iml = L, imr = R;
    vi riml = L, rimr = R;
    rep(i, 1, N) {
        chma(iml[i], iml[i - 1]);
        chmi(imr[i], imr[i - 1]);
    }
    rer(i, N - 2) {
        chma(riml[i], riml[i + 1]);
        chmi(rimr[i], rimr[i + 1]);
    }
    deb(iml, imr);
    deb(riml, rimr);
    int best = 0;
    rep(i, 1, N - 1) {
        int l = max(iml[i - 1], riml[i + 1]);
        int r = min(imr[i - 1], rimr[i + 1]);
        chma(best, u(r - l + 1) + u(R[i] - L[i] + 1));
    }

    // Lが小さいほうからいくつか取った場合のどっちか
    //iまで
    auto a = [&]() {
        vi iml = L, imr = R;
        vi riml = L, rimr = R;
        rep(i, 1, N) {
            chma(iml[i], iml[i - 1]);
            chmi(imr[i], imr[i - 1]);
        }
        rer(i, N - 2) {
            chma(riml[i], riml[i + 1]);
            chmi(rimr[i], rimr[i + 1]);
        }

        rep(i, N - 1) {
            int res = 0;
            {
                int l = iml[i];
                int r = imr[i];
                res += u(r - l + 1);
            }
            {
                int l = riml[i + 1];
                int r = rimr[i + 1];
                res += u(r - l + 1);
            }
            chma(best, res);
        }
    };
    sortp(L, R, fisi);
    a();
    sortp(L,R,fisd);
    a();
    sortp(L,R,fdsi);
    a();
    sortp(L,R,fdsd);
    a();
    sortp(L, R, sifi);
    a();
    sortp(L,R,sifd);
    a();
    sortp(L,R,sdfi);
    a();
    sortp(L,R,sdfd);
    a();
    cout << best << endl;
}

