		aleft.insert(vleft[i]);
		aright.insert(vright[i]);
	} else {
		bleft.insert(vleft[i]);
		bright.insert(vright[i]);
	}
}

int main(void) {
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	cout.tie(NULL);
	//freopen("in.txt", "r", stdin);
	cin >> n;
	vleft.resize(n);
	vright.resize(n);
	rep(i,0,n) {
		cin >> vleft[i] >> vright[i];
	}
	int maxL = 0;
	int minR = 1000000000;
	int maxLidx;
	int minRidx;
	rep(i,0,n) {
		if(vleft[i] > maxL) {
			maxL = vleft[i];
			maxLidx = i;
		}
		if(minR > vright[i]) {
			minR = vright[i];
			minRidx = i;
		}
	}

	rep(i,0,n) {
		if(i == maxLidx || i == minRidx) {
			myput(1,i);
		} else {
			myput(0,i);
		}
	}

	int A = max(0, *aright.begin() - *aleft.rbegin() + 1);
	int B = max(0, *bright.begin() - *bleft.rbegin() + 1);
	int ret = A + B;

	aleft.clear();
	aright.clear();
	bleft.clear();
	bright.clear();

	myput(1,maxLidx);
	myput(0,minRidx);

	rep(i,0,n) {
		if(i == maxLidx || i == minRidx) continue;

		int beforeA = max(0, *aright.begin() - *aleft.rbegin() + 1);
		int beforeB = max(0, *bright.begin() - *bleft.rbegin() + 1);

		myput(1,i);
		myput(0,i);

		int afterA = max(0, *aright.begin() - *aleft.rbegin() + 1);
		int afterB = max(0, *bright.begin() - *bleft.rbegin() + 1);

		if(beforeA - afterA < beforeB - afterB) {
			bleft.erase(bleft.find(vleft[i]));
			bright.erase(bright.find(vright[i]));
		} else {
			aleft.erase(aleft.find(vleft[i]));
			aright.erase(aright.find(vright[i]));
		}
	}

	A = max(0, *aright.begin() - *aleft.rbegin() + 1);
	B = max(0, *bright.begin() - *bleft.rbegin() + 1);
	ret = max(ret, A + B);
	cout << ret << endl;
	return 0;
}

