	llint rmin = inf, rmin_i, lmax = -inf, lmax_i;
	for(int i = 1; i <= n; i++){
		if(rmin > r[i]){
			rmin = r[i], rmin_i = i;
		}
		if(lmax < l[i]){
			lmax = l[i], lmax_i = i;
		}
	}
	llint lenmax = -inf;
	for(int i = 1; i <= n; i++){
		if(i == rmin_i || i == lmax_i) continue;
		lenmax = max(lenmax, r[i]-l[i]+1);
	}
