		R[i] = make_pair(max(R[i+1].first, vec[i].first), min(R[i+1].second, vec[i].second));
	}

	llint mxlen = -inf, mnlen = inf;
	for(int i = 1; i <= n; i++){
		mxlen = max(mxlen, r[i]-l[i]+1);
		mnlen = min(mnlen, r[i]-l[i]+1);
	}
	ans = max(ans, mxlen);
	if(m == 1) ans = mxlen + mnlen;

	for(int i = 1; i < m; i++){
		ans = max(ans, max(0LL, L[i].second-L[i].first+1) + max(0LL, R[i+1].second-R[i+1].first+1));
	}
	cout << ans << endl;

	return 0;
}

