struct seg
{
	int l, r;

	seg() {}
	seg(int L, int R):
		l(L), r(R) {}

	inline int len()
	{
		return r >= l ? r - l + 1 : 0;
	}

	inline void scan()
	{
		read(l);
		read(r);
	}

	inline bool operator < (const seg &a) const
	{
		return r < a.r || r == a.r && l > a.l;
	}

	inline seg operator & (const seg &a) const 
	{
		return seg(Max(l, a.l), Min(r, a.r));
	}
}p[N], pre[N], suf[N];

inline void solve()
{
	pre[0] = seg(1, 1e9);
	for (int i = 1; i <= n; ++i)
		pre[i] = pre[i - 1] & p[i];
	suf[n + 1] = seg(1, 1e9);
	for (int i = n; i >= 1; --i)
		suf[i] = suf[i + 1] & p[i];
	for (int i = 1; i < n; ++i)
		CkMax(ans, pre[i].len() + suf[i + 1].len());
	for (int i = 1; i <= n; ++i)
		CkMax(ans, (pre[i - 1] & suf[i + 1]).len() + p[i].len());
