        ll res=max(0LL,left.se-left.fi+1)+max(0LL,min(right.se,mini)-right.fi+1);
        chmax(ans,res);
        res=max(0LL,min(left.se,mini)-left.fi+1)+max(0LL,right.se-right.fi+1);
        chmax(ans,res);
    }
    cout << ans <<endl;
}

