      DPL2[i] = max(DPL2[i + 1], P[i].first);
      DPR2[i] = min(DPR2[i + 1], P[i].second);
    }
    FOR(i, 1, N) {
      ll score =
          max(DPR1[i] - DPL1[i] + 1, 0LL) + max(DPR2[i] - DPL2[i] + 1, 0LL);
      ans = max(score, ans);
    }
  }
  cout << ans << endl;

  return 0;
}

