			ansmax = anstmp;
			LR0_nxt = LRnew;
			LR1_nxt = LR1;
		}

		anstmp = 0;
		LRnew = LRcon(LR1, LRtmp);
		anstmp += lentmp(LRnew);
		anstmp += lentmp(LR0);
		if (ansmax < anstmp) {
			ansmax = anstmp;
			LR0_nxt = LRnew;
			LR1_nxt = LR0;
		}
		LR0 = LR0_nxt;
		LR1 = LR1_nxt;
	}
	ansmax = 0;
	ansmax += lentmp(LR0);
	ansmax += lentmp(LR1);
	cout << ansmax << endl;
	return 0;
}

