seg a[N];
int c1[N], c2[N];

int calc()
{
    int mx = a[1].l, mn = a[1].r;

    for (int i = 1; i <= n; i++)
    {
        mx = max(mx, a[i].l);
        mn = min(mn, a[i].r);
        if (mn - mx + 1 >= 0)
        {
            c1[i] = mn - mx + 1;
        }
        else
        {
            c1[i] = 0;
        }
    }

    mx = a[n].l;
    mn = a[n].r;

    for (int i = n; i >= 1; i--)
    {
        mx = max(mx, a[i].l);
        mn = min(mn, a[i].r);
        if (mn - mx + 1 >= 0)
        {
            c2[i] = mn - mx + 1;
        }
        else
        {
            c2[i] = 0;
        }
    }

    int ans = 0;
    for (int i = 1; i < n; i++)
    {
        ans = max(ans, c1[i] + c2[i + 1]);
    }
    return ans;
}

