const int INF = 1e+9;

template<class T>
class segTree{
    vector<T> tree;             // 木を示す配列
    int N;                      // 木で保持しているノード数
    T def_val;                  // 範囲外などの時に返却する値
    function<T(T,T)> selector;  // 選択関数(max, min, sum etc...)

    public: 
        // 初期化
        segTree(vector<T> &v, function<T(T,T)> f, T default_val){
            int n = v.size();
            N = pow(2, ceil(log2(n))); 
            tree.resize(2*N-1);
            selector = f;
            def_val = default_val;

            for(int i=0;i<N;i++) tree[N-1+i] = (i>=n?def_val:v[i]);
            for(int i=N-2;i>=0;i--) tree[i] = selector(tree[2*i+1], tree[2*i+2]);
        };

        // 値の更新
        void update(int ind, T val){
            ind += N - 1;
            tree[ind] = val;
            while(ind > 0){
                ind = (ind - 1) / 2;
                tree[ind] = selector(tree[2*ind+1], tree[2*ind+2]);
            }
        };

        // 値の取得(半閉区間[a,b)の範囲)
        T query(int a, int b, int ind = 0, int l = 0, int r = -1){
            if(r < 0) r = N;
            if(r <= a || b <= l) return def_val;
            if(a <= l && r <= b) return tree[ind];
            else return selector(query(a, b, 2*ind+1, l, (l+r)/2), 
                                 query(a, b, 2*ind+2, (l+r)/2, r));
        };
};



int score(int u, int d){
    return max(0, u - d + 1);
}
int main(){
    int n;
    cin >> n;
    vector<p> v(n);
    for(int i=0;i<n;i++){
        cin >> v[i].first >> v[i].second;
    }
    sort(v.begin(), v.end(), [](const p x, const p y){
        if((x.second - x.first) != (y.second - y.first)) 
            return (x.second - x.first) > (y.second - y.first);
        if(x.first == y.first) return x.second < y.second;
        else return x.first > y.first;
    });

    vector<ll> l(n), r(n);
    for(int i=0;i<n;i++){
        tie(l[i], r[i]) = v[i];
    }
    segTree<ll> stl(l, [](ll x, ll y){return max(x,y);}, 0);
    segTree<ll> str(r, [](ll x, ll y){return min(x,y);}, INF);

    // はじめグループ1は最大区間を保持する1つの問題のみ
    ll gp1d, gp1u, gp2d=stl.query(1,n), gp2u=str.query(1,n);    
    tie(gp1d,gp1u) = v[0];
    ll d = 0, u = INF+1;

    for(int i=1;i<n;i++){
        ll ntl = stl.query(i+1, n); // 次移行の全ての範囲の左最大値
        ll ntr = str.query(i+1, n); // 次移行の全ての範囲の右最大値
        // 移した場合にスコアが上がるなら移す
        ll gp1 = score(gp1u, gp1d) - score(min(gp1u, r[i]), max(gp1d, l[i]));
        ll gp2 = score(min(u, ntr), max(d, ntl)) - score(gp2u, gp2d);
        if(gp1 <= gp2){
            if(i == n-1 && d == 0 && u == INF+1) {
                gp2d = l[i];
                gp2u = r[i];
                continue;
            }
            gp1d = max(gp1d, l[i]);
            gp1u = min(gp1u, r[i]);
            gp2d = max(d, ntl);
            gp2u = min(u, ntr);
        }else{
            d = max(d, l[i]);
            u = min(u, r[i]);
        }
    }
    cout << score(gp1u,gp1d) + score(gp2u,gp2d) << endl;
}

