bool ch (pair<int, int> p1, pair<int, int> p2) {
	if (p1.first != p2.first) {
		return p1.first < p2.first;
	}
	return p2.second < p1.second;
}

ll solve (vector<pair<ll, ll>> &vv) {
	int n = vv.size ();
	sort (vv.begin (), vv.end (), ch);
	ll ar[n] = {}, br[n] = {};
	ll st = 1, en = INF, ma = 0;
	for (ll i = 0; i < n; i++) {
		st = vv[i].first, en = min (en, vv[i].second);
		if (st > en) {
			break;
		}
		ar[i] = en - st + 1;
	}
	st = 1, en = INF;
	for (ll i = n - 1; i >= 0; i--) {
		st = max (vv[i].first, st), en = min (vv[i].second, en);
		if (st > en) {
			break;
		}
		br[i] = en - st + 1;
	}
	for (ll i = 0; i < n - 1; i++) {
		ma = max (ar[i] + br[i + 1], ma);
	}
	return ma;
}

int main () {
