	ll ma = 0;
	vector<pair<ll, ll>> vp, vv;
	for (ll i = 0; i < n; i++) {
		ll l, r;
		cin >> l >> r;
		ma = max (ma , r - l + 1);
		vv.push_back (make_pair (l, r));
		vp.push_back (make_pair (INF - r + 1, INF - l + 1));
	}
	ma = max (solve (vv), ma);
	ma = max (solve (vp), ma);
	cout << ma << "\n";
}

