  ll p=-LLINF,q=LLINF;
  REP(i,n){
    p=max(p,l[i]);
    q=min(q,r[i]);
  }

  ll ans=0;
  //p,qが同一グループ
  REP(i,n)ans=max(ans,r[i]-l[i]+1);
  ans+=max(0LL,q-p+1);

  //p,qが別グループ
  vpl t(n);
  REP(i,n){
    t[i].FI=max(r[i]-p+1,0LL);
    t[i].SE=max(q-l[i]+1,0LL);
  }
  auto ord=[](pll a, pll b){
    if(a.FI<b.FI)
      return true;
    if(a.FI>b.FI)
      return false;

    if(a.SE<b.SE)
      return false;
    if(a.SE>b.SE)
      return true;
  };

  sort(ALL(t),ord);

  SegmentTreeMIN seg(n);
  REP(i,n)seg.update(i,t[i].SE);
  REP(i,n){
    if(i==0)
      continue;
    ll now=t[i].FI+seg.query(0,i);
    ans=max(ans,now);
  }


  cout<<ans<<endl;
}

