int calc(int N) {
  int ans = 0;
  int L1 = 0, R1 = INF;
  int L2 = 0, R2 = INF;
  vector<P> Ls, Rs;
  for (int i = 1; i < N; i++) {
    Ls.push_back({p[i].first, i});
    Rs.push_back({p[i].second, i});
  }
  sort(ALL(Ls)); reverse(ALL(Ls));
  sort(ALL(Rs));

  chmax(L1, p[0].first);
  chmin(R1, p[0].second);

  int l = 0, r = 0;
  L2 = Ls[l].first;
  R2 = Rs[r].first;

  for (int i = 1; i < N; i++) {
    // cout << i << ": " << R1 << " " << L1 << "     " << R2 << " " << L2 << endl;
    int val = max(0, R1-L1+1) + max(0, R2-L2+1);
    chmax(ans, val);

    chmax(L1, p[i].first);
    chmin(R1, p[i].second);
    while (l < (int)Ls.size() && Ls[l].second <= i) l++;
    while (r < (int)Rs.size() && Rs[r].second <= i) r++;

    L2 = Ls[l].first;
    R2 = Rs[r].first;
  }
  return ans;
}


