  const int M = 1e9;
  int N;
  SCAND(N);
  vector<pair<lli,lli> > P(N);
  REP(i,N)
    {
      SCANLLD2(P[i].first,P[i].second);
    }
  sort(ALL(P),[](pair<lli,lli> a, pair<lli,lli> b)
       {
	 if( a.second == b.second )
	   {
	     return a.first < b.first;
	   }
	 return a.second < b.second;
       });

  vector<lli> numl(N);
  lli rl = 1;
  lli rr = M;

  REP(i,N)
    {
      rl = max(rl,P[i].first);
      rr = min(rr,P[i].second);

      numl[i] = max(rr-rl+1,0LL);
    }

  vector<lli> numr(N);
  rl = 1;
  rr = M;

  REP_R(i,N)
    {
      rl = max(rl,P[i].first);
      rr = min(rr,P[i].second);

      numr[i] = max(rr-rl+1,0LL);
    }

  lli ans = 0;
  REP(i,N-1)
    {
      ans = max(ans,numl[i]+numr[i+1]);
    }

  PRINTLLD(ans);





}

