struct st {
    int front = 0;
    vector<pair<int, int>> Q;
	st() : front(0) {}

    void insert(pair<int, int> x) {
		while (front < (int)Q.size() && x >= Q.back())
            Q.pop_back();
        Q.push_back(x);
	}

    void del(int x) {
        while (front < (int)Q.size() && Q[front].second <= x) {
            front += 1;
        }
	}

	int get() {
        if (front < (int)Q.size()) 
            return Q[front].first;
        else 
            return -(1 << 30);
	}
};

