class Contest {
    multiset<ll> start, end;
public:
    void push(ll l, ll r) {
        start.insert(l);
        end.insert(r);
    }

    void pop(ll l, ll r) {
        start.erase(start.find(l));
        end.erase(end.find(r));
    }

    ll count() {
        ll l = *start.rbegin();
        ll r = *end.begin();
        return r - l + 1;
    }

};

