int main() {
  int n; cin >> n;
  vector<long long> l(n), r(n), mids;
  REP(i, n) {
    cin >> l[i] >> r[i];
    mids.emplace_back((l[i] + r[i]) / 2);
  }
  sort(ALL(mids));
  mids.erase(unique(ALL(mids)), mids.end());
  vector<vector<int> > mid(mids.size());
  REP(i, n) mid[lower_bound(ALL(mids), (l[i] + r[i]) / 2) - mids.begin()].emplace_back(i);
  if (mids.size() == 1) {
    long long len_mn = INF, len_mx = 0;
    REP(i, n) {
      len_mn = min(len_mn, r[i] - l[i] + 1);
      len_mx = max(len_mx, r[i] - l[i] + 1);
    }
    cout << len_mn + len_mx << '\n';
    return 0;
  }
  long long L = -LINF, R = LINF, ans = 0;
  map<long long, int> ls, rs;
  REP(i, n) {
    ++ls[l[i]];
    ++rs[r[i]];
  }
  REP(i, n) {
    --ls[l[i]];
    if (ls[l[i]] == 0) ls.erase(l[i]);
    --rs[r[i]];
    if (rs[r[i]] == 0) rs.erase(r[i]);
    long long now = max((*rs.begin()).first - (*ls.rbegin()).first + 1, 0LL);
    ans = max(ans, r[i] - l[i] + 1 + now);
    ++ls[l[i]];
    ++rs[r[i]];
  }
  REP(i, mid.size() - 1) {
    for (int e : mid[i]) {
      L = max(L, l[e]);
      R = min(R, r[e]);
      --ls[l[e]];
      if (ls[l[e]] == 0) ls.erase(l[e]);
      --rs[r[e]];
      if (rs[r[e]] == 0) rs.erase(r[e]);
    }
    long long now = max(R - L + 1, 0LL) + max((*rs.begin()).first - (*ls.rbegin()).first + 1, 0LL);
    ans = max(ans, now);
  }
  cout << ans << '\n';
  return 0;
}

