using P=pair<ll,pair<ll,ll>>;
void solve(){
	ll n;
	cin>>n;
	vector<P>p(n);
	rep(i,n){
		cin>>p[i].second.first>>p[i].second.second;
		p[i].first=p[i].second.second-p[i].second.first;
	}
	sort(all(p));
	ll ans=0;
	vector<ll>val(n+1),rval(n+1);
	ll left=0,right=1e9;
	rep(i,n){
		chmax(left,p[i].second.first);
		chmin(right,p[i].second.second);
		val[i+1]=right-left+1;
	}
	left=0,right=1e9;
	for(int i=n-1;i>=0;--i){
		chmax(left,p[i].second.first);
		chmin(right,p[i].second.second);
		rval[i]=right-left+1;
	}
	REP(i,1,n){
		//cout<<val[i]<<" "<<rval[i]<<"\n";
		chmax(ans,max(val[i],0LL)+max(rval[i],0LL));
	}
	rep(i,n)p[i].first=0;
	left=0,right=1e9;
	rep(i,n){
		chmax(left,p[i].second.first);
		chmin(right,p[i].second.second);
		val[i+1]=right-left+1;
	}
	left=0,right=1e9;
	for(int i=n-1;i>=0;--i){
		chmax(left,p[i].second.first);
		chmin(right,p[i].second.second);
		rval[i]=right-left+1;
	}
	REP(i,1,n){
		//cout<<val[i]<<" "<<rval[i]<<"\n";
		chmax(ans,max(val[i],0LL)+max(rval[i],0LL));
	}
	cout<<ans<<"\n";
}

