	}
	ll ans = 0;
	{
		SORT(v);

		auto tree = SegmentTree<PAIR>(n);
		REP(i, n) {
			tree.add(i, v[i]);
		}

		REP(i, n - 1) {
			auto q1 = tree.query(0LL, i);;
			ll r1 = q1.second - q1.first + 1;
			if (r1 > 1e9) { r1 = 0; }MAX(r1, 0LL);

			auto q2 = tree.query(i + 1, n);
			ll r2 = q2.second - q2.first + 1;
			if (r2 > 1e9) { r2 = 0; }MAX(r2, 0LL);
			MAX(ans, r1 + r2);
		}

		{// 2
			VL lmn(n), rmx(n + 1, 1e10);
			lmn[0] = v[0].second;
			FOR(i, 1, n) { lmn[i] = std::min(v[i].second, lmn[i - 1]); }
			rmx[n - 1] = v[n - 1].first;
			RFOR(i, 0, n - 1) { rmx[i] = std::max(v[i].second, rmx[i + 1]); }

			unordered_map<ll, ll> toI;
