				ll val = v[i].second - v[i].first + 1;
				ll lr = lmn[i - 1] - rmx[i + 1] + 1;
				MAX(lr, 0LL);
				val += lr;
				MAX(ans, val);
			}
		}
	}

	cout << ans << endl;
	//dump(v);
}

