    vector<pair<int, int>> prs(N);
    rep(i, N) {
        cin >> prs[i].first >> prs[i].second;
    }

    int ret = solve(prs);

    for (auto &pr : prs) {
        pr.first = 1000000000 - pr.first;
        pr.second = 1000000000 - pr.second;
    }

    ret = max(ret, solve(prs));

    cout << ret << endl;

    return 0;
}

