int main()
{

    int n;
    std::cin >> n;

    for (int i = 0; i < n; ++i)
        std::cin >> p[i].first >> p[i].second;

    P l(INF, INF), r(0, 0);

    for (int i = 0; i < n; ++i)
    {
        if (l.second > p[i].second)
            l = p[i];
        if (r.first < p[i].first)
            r = p[i];
    }

    std::cerr << "DEBUG"
              << std::endl
              << "Left:"
              << l.first << ' ' << l.second
              << std::endl
              << "Right:"
              << r.first << ' ' << r.second
              << std::endl;

    ll ans;

    if (l == r)
    {
        int cnt = 0;
        ll max = 0;
        for (int i = 0; i < n; ++i)
        {
            if (p[i] == l)
                ++cnt;
            max = std::max(max, len(p[i]));
        }

        if (len(l) == max && cnt > 1)
            ans = max * 2;
        else
        {
            ll _max = 0;
            for (int i = 0; i < n; ++i)
            {
                if (l != p[i])
                    _max = std::max(_max, len(p[i]));
            }
            ans = len(l) + _max;
        }
    }

    else
    {

        ll _l = l.first, _r = r.second;
        for (int i = 0; i < n; ++i)
        {
            if (p[i] != l && p[i] != r)
            {
                vl.emplace_back(p[i].first, i);
                vr.emplace_back(p[i].second, i);
            }
        }

        std::sort(std::begin(vl), std::end(vl));
        std::sort(std::begin(vr), std::end(vr), std::greater<>());

        auto itl = std::begin(vl), itr = std::begin(vr);

        while (1)
        {

            if (itl == std::end(vl) && itr == std::end(vr))
                break;

            if (itl->first - _l > _r - itr->first)
            {
                _r = itr->first;
                flag[itr->second] = 1;
            }
            else
            {
                _l = itl->first;
                flag[itl->second] = 1;
            }

            itl = nextIt(itl, 0);
            itr = nextIt(itr, 1);

            std::cerr << ((itl == std::end(vl)) ? -1 : itl->second) << ' ' << ((itr == std::end(vr)) ? -1 : itr->second) << std::endl;
        }

        ans = len(P(_l, l.second)) + len(P(r.first, _r));
    }

    std::cout << ans << std::endl;

    return 0;
}

