} //範囲の大きさ計算

using Q = std::pair<int, int>;

std::vector<Q> vl, vr; //範囲の境界の片側とそのインデックス

bool flag[MAX]; //もう使ったかどうか

auto nextIt(std::vector<Q>::iterator it, bool f) //0:vl,1:vr
{

    for (; flag[it->second] && it != (f ? std::end(vr) : std::end(vl)); ++it)
        ;
    return it;
} //次の問題

int main()
{

    int n;
    std::cin >> n;

    for (int i = 0; i < n; ++i)
        std::cin >> p[i].first >> p[i].second;

    P l(INF, INF), r(0, 0);
    //l:範囲の右境界でソートしたときに一番左にくる問題
    //r;範囲の左境界でソートしたときに一番右にくる問題
    //lとrが同じグループにいるのは最悪

    for (int i = 0; i < n; ++i)
    {
        if (l.second > p[i].second)
            l = p[i];
        if (r.first < p[i].first)
            r = p[i];
    }

    std::cerr << "DEBUG"
              << std::endl
              << "Left:"
              << l.first << ' ' << l.second
              << std::endl
              << "Right:"
              << r.first << ' ' << r.second
              << std::endl;

    int ans;

    if (l != r)
    {

        int _l = l.first, _r = r.second;
        //_l:グループlの左端
        //_r:グループrの右端
        for (int i = 0; i < n; ++i)
        {
            if (p[i] != l && p[i] != r)
            {
                vl.emplace_back(p[i].first, i);
                vr.emplace_back(p[i].second, i);
            }
        }

        std::sort(std::begin(vl), std::end(vl));
        std::sort(std::begin(vr), std::end(vr), std::greater<>());

        auto itl = std::begin(vl), itr = std::begin(vr);

        while (1)
        {

            if (itl == std::end(vl) && itr == std::end(vr))
                break;

            if (itl->first - _l > _r - itr->first)
            {
                _r = std::min(_r, itr->first);
                flag[itr->second] = 1;
            }
            else
            {
                _l = std::max(_l, itl->first);
                flag[itl->second] = 1;
            }

            itl = nextIt(itl, 0);
            itr = nextIt(itr, 1);
            //今回新メンバーを加入させなかったグループのitはもちろんそのまんまになっている

            std::cerr << ((itl == std::end(vl)) ? -1 : itl->second)
                      << ' '
                      << ((itr == std::end(vr)) ? -1 : itr->second)
                      << std::endl;
        }

        ans = len(P(_l, l.second)) + len(P(r.first, _r));
    }

    P ll = P(r.first, l.second);

    int max = 0;
    for (int i = 0; i < n; ++i)
    {
        if (l != p[i] && r != p[i])
            max = std::max(max, len(p[i]));
    }
    if (max == 0) //全問題の範囲がl(or r)に一致するとき
        ans = std::max(ans, len(ll) * 2);
    else
    {
        ans = std::max(ans, len(ll) + max);
    }

    std::cout << ans << std::endl;

    return 0;
}

