	int ver = s[1].r;
	Build(1, 1, n);
	for(int i = 1; i < n; i++) {
		ver = min(ver, s[i].r);
		ans = max(ans, max(0, ver - s[1].l + 1) + max(0, query(1, 1, n, i + 1, n) - s[i + 1].l + 1));
	}
