        long tmp = max(long(0),long(1)+tree.rmq(0,i+1,0,0,nn)-lr[i].first);
        tmp+=max(long(0),long(1)+tree.rmq(i+1,n,0,0,nn)-lr[n-1].first);
        ans=max(ans,tmp);
        tmp=0;
        tmp+=(lr[i].second-lr[i].first)+1;
        tmp+=max(long(0),long(1)+min(tree.rmq(0,i,0,0,nn),tree.rmq(i+1,n,0,0,nn))-lr[n-1].first);
    }
    cout << ans << endl;
}

