using namespace std;

using pii = pair<int, int>;

pii merge(pii p1, pii p2) {
	int x = max(p1.first, p2.first);
	int y = min(p1.second, p2.second);
	if (x > y) y = x - 1;
	return pii(x, y);
}

int count(pii p) {
	return p.second - p.first + 1;
}

int main() {
	int N; cin >> N;
	vector<pii> LR(N);
	for (int i = 0; i < N; ++i)
		cin >> LR[i].first >> LR[i].second;
	sort(LR.begin(), LR.end());

	vector<pii> from_front(N + 1), from_back(N + 1);
	from_front[1] = LR[0];
	for (int i = 2; i <= N; ++i)
		from_front[i] = merge(from_front[i - 1], LR[i - 1]);
	from_back[1] = LR[N - 1];
	for (int i = 2; i <= N; ++i)
		from_back[i] = merge(from_back[i - 1], LR[N - i]);

	int res = 0;
	for (int i = 1; i <= N - 1; ++i) {
		// 前からi個出題
		int tmp = count(from_front[i]);
		// 後ろからN-i個出題
		tmp += count(from_back[N - i]);
		res = max(res, tmp);
	}

	sort(
		LR.begin(), LR.end(),
		[&](pii a, pii b) {
			if (a.second != b.second) return a.second > b.second;
			return a.first > b.first;
		}
	);

	from_front[1] = LR[0];
	for (int i = 2; i <= N; ++i)
		from_front[i] = merge(from_front[i - 1], LR[i - 1]);
	from_back[1] = LR[N - 1];
	for (int i = 2; i <= N; ++i)
		from_back[i] = merge(from_back[i - 1], LR[N - i]);

	for (int i = 1; i <= N - 1; ++i) {
		// 前からi個出題
		int tmp = count(from_front[i]);
		// 後ろからN-i個出題
		tmp += count(from_back[N - i]);
		res = max(res, tmp);
	}

	cout << res << endl;
}

#include <bits/stdc++.h>
using namespace std;
const int oo = 1 << 30;

int n, ans;
pair<int, int> a[100100];

int getAns(int minL, int maxL, int minR, int maxR)
{
  return max(0, maxL - minL + 1) + max(0, maxR - minR + 1);
}

void solve1()
{
  sort(a, a + n);
  vector<int> minPrefix(n, oo), minSuffix(n, oo);
  minPrefix[0] = a[0].second;
  for (int i = 1; i < n; i++)
    minPrefix[i] = min(minPrefix[i - 1], a[i].second);
  minSuffix[n - 1] = a[n - 1].second;
  for (int i = n - 2; i >= 0; i--)
    minSuffix[i] = min(minSuffix[i + 1], a[i].second);

  for (int i = 0; i < n - 1; i++)
    ans = max(ans, getAns(a[i].first, minPrefix[i], a[n - 1].first, minSuffix[i + 1]));
  cout << ans << endl;
}

void solve2(int minL, int maxL, vector<pair<int, int>> l, vector<pair<int, int>> r)
{
  int minR = r.back().first, maxR = r[0].second;
  for (auto u : r)
    maxR = min(maxR, u.second);
  if (minR >= maxR)
  {
    cout << ans << endl;
    exit(0);
  }

  vector<pair<int, int>> intersect;
  for (auto u : l)
    if (u.second < minR)
    {
      minL = u.first;
      maxL = min(maxL, u.second);
    }
    else intersect.push_back(u);

  if (minL >= maxL)
  {
    cout << ans << endl;
    exit(0);
  }

  if (intersect.empty())
  {
    ans = max(ans, getAns(minL, maxL, minR, maxR));
    cout << ans << endl;
    exit(0);
  }

  int m = intersect.size();
  vector<int> minPrefix(m, oo), minSuffix(m, oo);
  minPrefix[0] = intersect[0].second;
  for (int i = 1; i < m; i++)
    minPrefix[i] = min(minPrefix[i - 1], intersect[i].second);
  minSuffix[m - 1] = intersect[m - 1].second;
  for (int i = m - 2; i >= 0; i--)
    minSuffix[i] = min(minSuffix[i + 1], intersect[i].second);

  // put all to left
  ans = max(ans, getAns(intersect[m - 1].first, min(maxL, minPrefix[m - 1]), minR, maxR));
  // put all to right
  ans = max(ans, getAns(minL, maxL, minR, min(maxR, minPrefix[m - 1])));
  // split
  for (int i = 0; i < m - 1; i++)
    ans = max(ans, getAns(intersect[i].first, min(maxL, minPrefix[i]), minR, min(maxR, minSuffix[i + 1])));
  cout << ans << endl;
}

int main()
{
  ios_base::sync_with_stdio(0);
  cin.tie(0);

  cin >> n;
  for (int i = 0; i < n; i++)
  {
    cin >> a[i].first >> a[i].second;
    ans = max(ans, a[i].second - a[i].first + 1);
  }

  int minRId = 0;
  for (int i = 1; i < n; i++)
    if (a[i].second < a[minRId].second)
      minRId = i;

  vector<pair<int, int>> l, r;
  for (int i = 0; i < n; i++)
    if (i != minRId)
    {
      if (a[i].first > a[minRId].second) r.push_back(a[i]);
      else l.push_back(a[i]);
    }

  sort(l.begin(), l.end());
  sort(r.begin(), r.end());

  if (r.empty()) solve1();
  else solve2(a[minRId].first, a[minRId].second, l, r);
}

