/* monkukui 競技プログラミング用のテンプレート (ここまで)*/

int main(){

  lint n; cin >> n;
  vector<lint> l(n);
  vector<lint> r(n);
  for(int i = 0; i < n; i++) cin >> l[i] >> r[i];

  if(n == 2) {
    cout << r[0] - l[0] + r[1] - l[1] + 2 << endl;
    return 0;
  }

  lint mi;
  lint mr = INF;
  lint Mi;
  lint Ml = -1;
  lint lb, rb, la, ra;
  for(int i = 0; i < n; i++) {
    if(mr > r[i]) {
      mr = r[i];
      mi = i;
    }
    if(Ml < l[i]) {
      Ml = l[i];
      Mi = i;
    }
  }

  for(int i = 0; i < n; i++) {
    if(i == mi) {
      rb = r[i];
      lb = l[i];
    }
    if(i == Mi) {
      la = l[i];
      ra = r[i];
    }
  }

  vector<pair<lint, lint>> rest;
  for(int i = 0; i < n; i++) {
    if(i == mi or i == Mi) continue;
    rest.push_back({l[i], r[i]});
  }

  lint ans = 0;
  // mr, Ml を一緒にする場合
  ans = max(mr - Ml + 1, 0LL);
  lint add = 0;
  for(int i = 0; i < rest.size(); i++) {
    add = max(add, rest[i].second - rest[i].first + 1);
  }
  ans += add;

  // 一緒にしない場合
  //


  sort(ALL(rest));
  vector<lint> min_r(n - 2, INF);
  min_r[n - 3] = rest[n - 3].second;
  for(int i = n - 4; i >= 0; i--) {
    min_r[i] = min(min_r[i + 1], rest[i].second);
  }
  // rest の内から i こを青に
  for(int i = 0; i <= n - 2; i++) {
    lint ll = lb;
    if(i != 0) {
      ll = rest[i - 1].first;
    }
    lint blue = rb - ll + 1;
    lint rr = ra;
    if(i != n - 2) {
      rr = min_r[i];
    }
    lint red = rr - la + 1;
    ans = max(ans, blue + red);
  }

  cout << ans << endl;

  return 0;
}

