int main(){
    using namespace std;
    unsigned long N;
    cin >> N;
    vector<pair<unsigned long, unsigned long>> LR(N);
    for(auto& i : LR){
        cin >> i.first >> i.second;
        i.second++;
    }
    nth_element(LR.rbegin(), LR.rend() - 1, LR.rend());
    nth_element(LR.begin() + 1, LR.begin() + 2, LR.end(), [](auto i, auto j){return i.second == j.second ? i.first < j.first : i.second < j.second;});
    if(LR[0].second <= LR[1].second){
        sort(LR.begin() + 1, LR.end(), [](auto i, auto j){return i.first + i.second < j.first + j.second;});
        cout << LR[0].second - LR[0].first + LR.back().second - LR.back().first << endl;
        return 0;
    }

    abort();

    unsigned long ans{0};
    for(unsigned long i = 2; i < N; ++i){
        ans = max(ans, LR[i].second - LR[i].first);
    }
    ans += LR[1].second - min(LR[0].first, LR[1].second);

    sort(LR.begin() + 2, LR.end(), [](auto i, auto j){return i.second == j.second ? i.first < j.first : i.second > j.second;});
    auto L1 = LR[1].first, R1 = LR[1].second, L2 = LR[0].first, R2 = LR[0].second;
    reverse(LR.begin(), LR.end());
    LR.pop_back();LR.pop_back();

    unsigned long mx{L1};
    for(unsigned long i = 0; i + 2 < N; ++i){
        ans = max(ans, R1 - mx + LR[i].second - L2);
        mx = max(mx, LR[i].first);
    }
    cout << max(ans, R1 - mx + R2 - L2) << endl;

    return 0;
}

