inline int read()
{
	int neg=1,num=0;char c=getchar();
	for(;!isdigit(c);c=getchar())if(c=='-')neg=-1;
	for(;isdigit(c);c=getchar())num=(num<<1)+(num<<3)+c-'0';
	return neg*num;
}
struct node
{
	int l,r;
}q[N];
int n,ans,pre[N][2],suf[N][2];
bool cmp1(node x,node y){return (x.r^y.r)?x.r<y.r:x.l>y.l;}
bool cmp2(node x,node y){return (x.r^y.r)?x.r<y.r:x.l<y.l;}
inline void work()
{
	pre[1][0]=q[1].l;pre[1][1]=q[1].r;suf[n][0]=q[n].l;suf[n][1]=q[n].r;
	for(int i=2  ;i<=n;i++)pre[i][0]=max(pre[i-1][0],q[i].l),pre[i][1]=min(pre[i-1][1],q[i].r);
	for(int i=n-1;i>=1;i--)suf[i][0]=max(suf[i+1][0],q[i].l),suf[i][1]=min(suf[i+1][1],q[i].r);	
	for(int i=1;i<=n-1;i++)ans=max(ans,max(0ll,pre[i][1]-pre[i][0]+1)+max(0ll,suf[i+1][1]-suf[i+1][0]+1));
}
signed main()
{
	n=read();
	for(int i=1;i<=n;i++)q[i].l=read(),q[i].r=read();
	sort(q+1,q+n+1,cmp1);work();
	sort(q+1,q+n+1,cmp2);work();

	int T=500;
	while(T--)
	{
		for(int i=1;i<=n;i++)
		{
			int j=i;
			while(q[j+1].r==q[j].r)j++;
			random_shuffle(q+i,q+j+1);
			i=j;
		}
		work();
	}
	printf("%lld\n",ans);
	return 0;
}
