using namespace std;

int main()
{    
    int n;
    cin >> n;

    vector<pair<int, int>> a(n);

    for (int i = 0; i < n; i++) {
        cin >> a[i].first >> a[i].second;
    }

    sort(a.begin(), a.end());

    vector<int> rBMin(n, 2000000000);

    rBMin[n - 1] = a[n - 1].second;

    for (int i = n - 2; i >= 0; --i) {
        rBMin[i] = min(a[i].second, rBMin[i + 1]);   
    }

    int ans = 0;

    int rMin = a[0].second;
    int rMax = a[0].second;

    for (int i = 0; i < n - 1; i++) {
        int lA = a[i].first;
        int rA = a[i].second;
        int lB = a[n - 1].first;
        int rB = rBMin[i + 1];

        if (i == 0) {
            ans = max(ans, max(rA - lA + 1, 0) + max(rB - lB + 1, 0));
        } else if (i == 1) {
            ans = max(ans, max(min(a[0].second, rA) - lA + 1, 0) + max(rB - lB + 1, 0));
            ans = max(ans, max(rA - lA + 1, 0) + max(min(rB, a[0].second) - lB + 1, 0));
        } else {
            {
                ans = max(ans, max(min(rA, rMin) - lA + 1, 0) + max(rB - lB + 1, 0));
                ans = max(ans, max(min(rA, rMin) - lA + 1, 0) + max(min(rB, rMax) - lB + 1, 0));
                ans = max(ans, max(min(rA, rMax) - lA + 1, 0) + max(min(rB, rMin) - lB + 1, 0));
                ans = max(ans, max(rA - lA + 1, 0) + max(min(rB, rMin) - lB + 1, 0));
            }
        }

        rMin = min(rMin, a[i].second);
        rMax = max(rMax, a[i].second);
    }

    cout << ans << endl;
}

