multiset<ll> A,  B;
ll glast()
{
    if(A.size() == 0) return 1e16;
    return *A.rbegin();
}
ll gfst()
{
    if(B.size() == 0) return -1e16;
    return *B.begin();
}
int main(int argc, const char * argv[]) {

    cin >> n;
    pll yo = make_pair(1e16 , 1e16);
    ll id = 0;
    for(ll i=1;i<=n;i++) {
        cin >> l[i] >> r[i];
        pll xx = make_pair(r[i] , l[i]);
        if(xx < yo) {
            id = i;
            yo = xx;
        }
    }
    vector< pll > v;
    for(ll i=1;i<=n;i++) {
        if(i == id) continue;
        A.insert(l[i]);
        B.insert(r[i]);
        v.pb(make_pair(l[i] , r[i]));
    }
    sort(v.begin(), v.end());

    ll ans = yo.first - yo.second + 1;

    ll L = glast();
    ll R = gfst();
    if(R >= L) ans += (R - L + 1);
    L = yo.second;
     R = yo.first;
    //cout << "<<<" << ans << endl;
    for(ll ii = 0 ; ii < v.size() ; ii++) {
        pll i = v[ii];
        A.erase(A.find(i.first));
        B.erase(B.find(i.second));
        L = max(L , i.first);
        if(L <= R) {
            ll ret = R-L+1;
            ll X = glast();
            ll Y = gfst();
            if(X <= Y) ret += (Y - X + 1);
            ans = max(ans , ret);
        }else {

            ll j = ii + 1;
            while(j < v.size()) {
                ans = max(ans , v[j].second - v[j].first + 1);
                j++;
            }
            break;
        }
        //cout << ii << " --> " << ans << endl;
    }
        ll ln = 0;
        id = 0;
        for(ll i=1;i<=n;i++) {
                if(ln < r[i] - l[i] + 1) {
                        ln = r[i] - l[i] + 1;
                        id = i;
                }
        }
        ll maxm = 0;
        ll minm = 1e16;
        for(ll i=1;i<=n;i++) {
                if(i == id) continue;
                maxm = max(maxm , l[i]);
                minm = min(minm , r[i]);
        }
        if(minm >= maxm) ln += minm-maxm+1;
        ans = max(ans , ln);
    cout << ans << endl;


}

