int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	cout.tie(NULL);

	int n;
	cin >> n;

	multiset<int> ls, rs;
	map<int, set<int>> lmap, rmap;
	for(int i = 0; i < n; i++) {
		int l, r;
		cin >> l >> r;

		ls.insert(l);
		rs.insert(r);
		lmap[l].insert(r);
		rmap[r].insert(l);
		//lmap.insert(make_pair(l, r));
		//rmap.insert(make_pair(r, l));
	}

	int ans = 0;

	bool first = true;
	int cl, cr;
	while(ls.size() > 1) {
		auto li = ls.rbegin();
		auto lri = rs.begin();
		int lres = *li;
		int ll = lres;
		int lr = 1000000000;
		for(int rval : lmap[lres]) {
			lr = min(lr, rval);
			li++;

			if(rval == *lri) {
				lri++;
			}
		}

		auto ri = rs.begin();
		auto rli = ls.rbegin();
		int rres = *ri;
		int rl = 1;
		int rr = rres;
		for(auto it = rmap[rres].rbegin(); it != rmap[rres].rend(); it++) {
			int lval = *it;
			rl = max(rl, lval);
			ri++;

			if(lval == *rli) {
				rli++;
			}
		}

		//assert(li != ls.rend());
		//assert(ri != rs.end());

		if(first) {
			first = false;
		}
		else {
			ll = max(ll, cl);
			lr = min(lr, cr);

			rl = max(rl, cl);
			rr = min(rr, cr);
		}

		//cout << "res: " << lres << " " << rres << endl;
		//cout << "l: " << ll << " " << lr << endl;
		//cout << "r: " << rl << " " << rr << endl;
		//cout << "idx: " << *li << " " << *ri << endl;


		int lcount = 0;
		if(li != ls.rend()) {
			lcount = len(ll, lr) + len(*li, *lri);
		}

		int rcount = 0;
		if(ri != rs.end()) {
			rcount = len(rl, rr) + len(*rli, *ri);
		}

		//cout << "count: " << lcount << " " << rcount << endl;

		if(lcount > rcount) {
			cl = ll;
			cr = lr;
		}
		else {
			cl = rl;
			cr = rr;
		}

		ans = max(ans, max(lcount, rcount));

		if(lcount > rcount) {
			for(int rval : lmap[lres]) {
				rs.erase(rs.find(rval));
				if(rmap[rval].size() == 1) {
					rmap.erase(rval);
				}
				else {
					rmap[rval].erase(lres);
				}
			}

			ls.erase(lres);
			lmap.erase(lres);
		}
		else {
			for(int lval : rmap[rres]) {
				ls.erase(ls.find(lval));
				if(lmap[lval].size() == 1) {
					lmap.erase(lval);
				}
				else {
					lmap[lval].erase(rres);
				}
			}

			rs.erase(rres);
			rmap.erase(rres);
		}
		//cout << "sizes: " << ls.size() << " " << rs.size() << endl;
	}


	cout << ans << endl;

	return 0;
}

