#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef pair<int, int> pii;
typedef pair<ll, ll> pll;

const int MAXN = 1e5;

struct Line { int L, R; };

int N;
Line A[MAXN+10];
int ans, val1[MAXN+10], val2[MAXN+10];

int main()
{
    int i, j;

    scanf("%d", &N);
    for(i=1; i<=N; i++) scanf("%d%d", &A[i].L, &A[i].R);

    if(N==2)
    {
        printf("%d", A[1].R-A[1].L+A[2].R-A[2].L+2);
        return 0;
    }

    int l=-1, r=1e9+1;
    for(i=1; i<=N; i++) l=max(l, A[i].L), r=min(r, A[i].R);

    if(l<=r)
    {
        int flag=-1;
        for(i=1; i<=N; i++) if(A[i].L==l && A[i].R==r) flag=i;
        if(flag!=-1) for(i=1; i<=N; i++) if(i!=flag) ans=max(ans, A[i].R-A[i].L+r-l);
        else
        {
            pii pl={-1, 0}, pr={1e9+1, 0};
            for(i=1; i<=N; i++)
            {
                if(A[i].R==r) pl=max(pl, pii(A[i].L, i));
                if(A[i].L==l) pr=min(pr, pii(A[i].R, i));
            }
            for(i=1; i<=N; i++)
            {
                if(i==pl.second || i==pr.second) continue;
                ans=max(ans, A[i].R-A[i].L+r-l);
            }
        }
    }

    sort(A+1, A+N+1, [&](const Line &p, const Line &q)
         {
             if(p.L==q.L) return p.R>q.R;
             return p.L<q.L;
         });

    int nl=-1, nr=1e9+1;
    for(i=1; i<=N; i++)
    {
        nl=max(nl, A[i].L);
        nr=min(nr, A[i].R);
        val1[i]=nr-nl;
    }

    nl=-1, nr=1e9+1;
    for(i=N; i>=1; i--)
    {
        nl=max(nl, A[i].L);
        nr=min(nr, A[i].R);
        val2[i]=nr-nl;
    }

    for(i=1; i<N; i++) ans=max(ans, val1[i]+val2[i+1]);
    ans+=2;
    printf("%d", ans);
}

