template <class T>
class SegTree {
    int n;
    vector<T> data;
    T def;
    function<T(T, T)> operation;
    function<T(T, T)> update;

    T _query(int a, int b, int k, int l, int r) {
        if (r <= a or b <= l) return def;
        if (a <= l and r <= b) return data[k];
        else {
            T c1 = _query(a, b, 2*k+1, l, (l+r)/2);
            T c2 = _query(a, b, 2*k+2, (l+r)/2, r);
            return operation(c1, c2);
        }
    }

    public:
    SegTree(ll _n, T _def, function<T(T, T)> _operation, function<T(T, T)> _update) : def(_def), operation(_operation), update(_update) {
        n = 1;
        while (n <= _n) {
            n *= 2;
        }
        data = vector<T>(2*n-1, def);
    }

    void change(int i, T x) {
        i += n-1;
        data[i] = update(data[i], x);
        while (i > 0) {
            i = (i-1) / 2;
            data[i] = operation(data[i*2+1], data[i*2+2]);
        }
    }

    T query(int a, int b) {
        return _query(a, b, 0, 0, n);
    }

    T operator[] (int i) {
        return data[i+n-1];
    }
};

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll N;
    cin >> N;
    vector<pair<ll, ll>> section(N);
    Rep (i, N) {
        ll L, R;
        cin >> L >> R;
        L--;
        section[i] = {L, R};
    }

    sort(section.begin(), section.end());

    SegTree<ll> st1(N, -inf, [](ll a, ll b){return max(a, b);}, [](ll a, ll b){return b;});
    SegTree<ll> st2(N, inf, [](ll a, ll b){return min(a, b);}, [](ll a, ll b){return b;});

    Rep (i, N) {
        st1.change(i, section[i].first);
        st2.change(i, section[i].second);
    }

    ll ans = 0;
    Rep (i, N) {
        ll tmp = section[i].second - section[i].first;
        tmp += max<ll>(0, min(st2.query(0, i), st2.query(i+1, N)) - max(st1.query(0, i), st1.query(i+1, N)));
        chmax(ans, tmp);

        if (i < N-1) {
            tmp = max<ll>(0, st2.query(0, i+1) - st1.query(0, i+1));
            tmp += max<ll>(0, st2.query(i+1, N) - st1.query(i+1, N));
            chmax(ans, tmp);
        }
    }

    cout << ans << endl;
}

