int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n;
    cin >> n;
    vector<ll> L(n), R(n);
    for (int i = 0; i < n; i++) {
        cin >> L[i] >> R[i];
    }
    int maxL_idx = 0, minR_idx = 0;
    for (int i = 0; i < n; i++) {
        if (L[maxL_idx] < L[i] || (L[i] == L[maxL_idx] && R[i] < R[maxL_idx])) {
            maxL_idx = i;
        }

        if (R[minR_idx] > R[i] || (R[i] == R[minR_idx] && L[i] > L[minR_idx])) {
            minR_idx = i;
        }
    }

    ll ans = max(R[minR_idx] - L[maxL_idx] + 1, 0LL);
    {
        ll tmp = 0;
        for (int i = 0; i < n; i++) {
            if (i == minR_idx || i == maxL_idx) continue;
            tmp = max(tmp, R[i] - L[i] + 1);
        }
        ans += tmp;
    }

    ll L1 = L[minR_idx], R1 = R[minR_idx], L2 = L[maxL_idx], R2 = R[maxL_idx];
    for (int i = 0; i < n; i++) {
        if (i == minR_idx || i == maxL_idx) continue;
        ll nex_L1 = max(L[minR_idx], L[i]);
        ll nex_R1 = min(R[minR_idx], R[i]);
        ll diff1 = max(R[minR_idx] - L[minR_idx] + 1, 0LL) - max(nex_R1 - nex_L1 + 1, 0LL);

        ll nex_L2 = max(L[maxL_idx], L[i]);
        ll nex_R2 = min(R[maxL_idx], R[i]);
        ll diff2 = max(R[maxL_idx] - L[maxL_idx] + 1, 0LL) - max(nex_R2 - nex_L2 + 1, 0LL);
        if (diff1 < diff2) {
            L1 = max(L1, nex_L1);
            R1 = min(R1, nex_R1);
        } else {
            L2 = max(L2, nex_L2);
            R2 = min(R2, nex_R2);
        }
    }
    ans = max(ans, max(R1 - L1 + 1, 0LL) + max(R2 - L2 + 1, 0LL));
    cout << ans << "\n";
    return 0;
}

