void getse()
{
	rep(i, 1, n) if(l[i] == lmx) { l[i] = -inf; p1 = i; break; }
	rep(i, 1, n) lmxs = max(lmxs, l[i]);
	rep(i, 1, n) if(l[i] == lmxs) { l[i] = -inf-1; break; }
	rep(i, 1, n) lmxt = max(lmxt, l[i]);
	rep(i, 1, n) if(l[i] == -inf-1) l[i] = lmxs;
	rep(i, 1, n) if(l[i] == -inf) l[i] = lmx;

	rep(i, 1, n) if(r[i] == rmn) { r[i] = inf; p2 = i; break; }
	rep(i, 1, n) rmns = min(rmns, r[i]);
	rep(i, 1, n) if(r[i] == rmn) { r[i] = inf+1; break; }
	rep(i, 1, n) rmnt = min(rmnt, r[i]);
	rep(i, 1, n) if(r[i] == inf+1) r[i] = rmns;
	rep(i, 1, n) if(r[i] == inf) r[i] = rmn;

}
void init()
{
	cin >> n;
	rep(i, 1, n) 
		scanf("%lld %lld", &l[i], &r[i]), lmx = max(lmx, l[i]), rmn = min(rmn, r[i]);
	getse();
	rep(i, 1, n)
	{
		int pans = max( r[i] - l[i] + 1, 0LL );
		int lq = lmx, rq = rmn;
		if( l[i] == lmx ) lq = lmxs;
		if( r[i] == rmn ) rq = rmns;
		pans += max( (rq-lq+1), 0LL ); ans = max(ans, pans);
	}
	// p1 ~ i
	rep(i, 1, n)
	{
		int pans = max( min(r[p1], r[i]) - max(l[i], l[p1]) + 1, 0LL);
		int lq = lmxs, rq = rmn;
		if( l[i] == lmx || l[p2] == lmx ) lq = lmxs;
		if( ( l[i] == lmxs || l[p1] == lmxs ) && lq == lmxs ) lq = lmxt;
		if( r[i] == rmn || r[p1] == rmn ) rq = rmns;
		if( ( r[i] == rmns || r[p1] == rmns ) && rq == rmns ) rq = rmnt;
		pans += max( (rq-lq+1), 0LL ); 
		ans = max(ans, pans);
	}
	// p2 ~ i
	rep(i, 1, n)
	{
		int pans = max( min(r[p2], r[i]) - max(l[i], r[p2]) + 1, 0LL);
		int lq = lmx, rq = rmns;
		if( l[i] == lmx || l[p2] == lmx ) lq = lmxs;
		if( ( l[i] == lmxs || l[p1] == lmxs ) && lq == lmxs ) lq = lmxt;
		if( r[i] == rmn || r[p1] == rmn ) rq = rmns;
		if( ( r[i] == rmns || r[p1] == rmns ) && rq == rmns ) rq = rmnt;
		pans += max( (rq-lq+1), 0LL ); ans = max(ans, pans);
	}
	cout << ans;
}
