        while (its < n && start[its].x == coor) {
            int id = start[its].y;
            L[0].insert({a[id], id});
            L[1].erase({a[id], id});
            R[0].insert({b[id], id});
            R[1].erase({b[id], id});
            ++its;
        }
        while (itf < n && finish[itf].x == coor) {
            int id = finish[itf].y;
            L[1].insert({a[id], id});
            L[0].erase({a[id], id});
            R[1].insert({b[id], id});
            R[0].erase({b[id], id});
            ++itf;
        }
        int val1 = get(0), val2 = get(1);
        if (L[0].empty()) val1 = val2;
        if (L[1].empty()) val2 = val1;
        chkmax(ans, val1 + val2);
    }
    cout << ans << '\n';
}

