pair<ll,ll> insec(pair<ll,ll> a, pair<ll,ll> b) {
	if(a.first>a.second||b.first>b.second){
		return mp(-1,-2);
	}
	if(a.first>b.first){
		swap(a,b);
	}
	if(a.second<b.first){
		return mp(-1,-2);
	}
	if(a.second>=b.second){
		return b;
	} else{
		return mp(b.first,a.second);
	}
}
