        L_LR[0] = LR[0];
        R_LR[N - 1] = LR[N - 1];
        for(int i = 0; i < N - 1; i++){
            L_LR[i + 1] = {max(L_LR[i].first, LR[i + 1].first), min(L_LR[i].second, LR[i + 1].second)};
            R_LR[N - i - 2] = {max(R_LR[N - i - 1].first, LR[N - i - 2].first), min(R_LR[N - i - 1].second, LR[N - i - 2].second)};
        }/*
          for(int i = 0; i < N; i++){
