template<class T>
struct SegmentTree {
private:
    int n;
    vector<T> node;
    T def;
    function<T(T,T)> cmp;

public:
    SegmentTree(int _n, T _def, function<T(T,T)> _cmp) {
        n = 1;
        while(n < _n) n *= 2;
        def = _def; cmp = _cmp;
        node = vector<T>(2 * n - 1, def);
    }

    void update(int idx, T val) {
        idx += (n - 1);
        node[idx] = val;
        while(idx > 0) {
            idx = (idx - 1) / 2;
            node[idx] = cmp(node[idx * 2 + 1], node[idx * 2 + 2]);
        }
    }

    T query(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0) r = n;
        if ((r <= a) || (b <= l)) return def;
        if ((a <= l) && (r <= b)) return node[k];
        return cmp(query(a, b, 2 * k + 1, l, (l + r) / 2), query(a, b, 2 * k + 2, (l + r) / 2, r));
    }
};

