struct ST{
	int t[2*N], op, n;
	ST(){ }
	int Op(int a, int b){
		if(op == 0) return min(a,b);
		return max(a,b);
	}
	int Neutro(){
		if(op == 0) return 1e9;
		return -1e9;
	}
	void build(vector<int> &vec, int _op, int _n){
		op = _op;
		n = _n;
		for(int i = 0; i < n; ++i)
			t[i+n] = vec[i];
		for(int i = n-1; i > 0; --i)
			t[i] = Op(t[i<<1],t[i<<1|1]);
	}
	int query(int l, int r){
		int ans = Neutro();
		for(l += n, r += n; l < r; l >>= 1, r >>= 1){
			if(l&1) ans = Op(ans,t[l++]);
			if(r&1) ans = Op(ans,t[--r]);
		}
		return ans;
	}
};

