int main() {
    int N;
    cin >> N;
    vector<pair<int, int>> LR(N);
    rep(i, N) {
        int l, r;
        cin >> l >> r;
        r++;
        LR[i] = { l, r };
    }
    vector<int> lsort(N), rsort;
    iota(all(lsort), 0);
    rsort = lsort;
    sort(all(lsort), [&](auto&& l, auto&& r) { return LR[l].first < LR[r].first; });
    sort(all(rsort), [&](auto&& l, auto&& r) { return LR[l].second < LR[r].second; });

    int ml = rsort[0], mr = lsort[N - 1];
    int ans = 0;
    if (ml == mr) {
        rep(i, N) {
            ans = max(ans, LR[mr].second - LR[mr].first + LR[i].second - LR[i].first);
        }
    }
    else {
        // mlmr同じグループ
        rep(i, N) {
            if (i != ml && i != mr) {
                ans = max(ans, max(0, LR[ml].second - LR[mr].first) + LR[i].second - LR[i].first);
            }
        }

        // mlmr別グループ
        vector<int> minr(N + 1);
        minr[N] = LR[mr].second;
        for (int i = N - 1; i >= 0; --i) {
            if (rsort[i] == ml || lsort[i] == mr) minr[i] = minr[i + 1];
            else minr[i] = min(minr[i + 1], LR[lsort[i]].second);
        }

        int maxl = LR[ml].first;
        ans = max(ans, LR[ml].second - maxl + minr[0] - LR[mr].first);
        rep(i, N) {
            if (rsort[i] == ml || lsort[i] == mr) continue;
            maxl = max(maxl, LR[lsort[i]].first);
            ans = max(ans, LR[ml].second - maxl + minr[i + 1] - LR[mr].first);
        }
    }

    write(ans);
}

