                L[0].erase({a[id], id});
                R[1].insert({b[id], id});
                R[0].erase({b[id], id});
                ++itf;
            }
            int val1 = get(0), val2 = get(1);
            if (L[0].empty()) val1 = val2;
            if (L[1].empty()) val2 = val1;
