  void read() { scanf("%lld %lld", &l, &r); }
  bool operator<(const Problem &other) const { return l + r > other.l + other.r; }
};
Problem problems[maxN];
vector<lli> ux;
map<lli, int> compress; lli decompress[2*maxN];

int in[2*maxN], out[2*maxN + 2], filled[2*maxN];

int main()
{
  while (scanf("%d", &n) != EOF)
  {
    ux.clear(), compress.clear(); memset(decompress, 0, sizeof(decompress)), memset(filled, 0, sizeof(filled)), memset(in, 0, sizeof(in)), memset(out, 0, sizeof(out));
    lli ans = 0;
    for (int i = 0; i < n; i ++)
    {
      problems[i].read();
      ux.push_back(problems[i].l), ux.push_back(problems[i].r);
    }
    sort(problems, problems+n);
    ans = problems[0].r - problems[0].l + 1;
    lli l = problems[1].l, r = problems[1].r;
    for (int j = 2; j < n; j ++)
      l = max(l, problems[j].l), r = min(r, problems[j].r);
    ans += max(0LL, r - l + 1);

    sort(ux.begin(), ux.end());
    ux.resize(distance(ux.begin(), unique(ux.begin(), ux.end())));
    for (int i = 0; i < ux.size(); i ++)
      compress[ux[i]] = i, decompress[i] = ux[i];

    for (int i = 0; i < n; i ++)
    {
      problems[i].cl = compress[problems[i].l], problems[i].cr = compress[problems[i].r];
      in[problems[i].cl] ++, out[problems[i].cr] ++;
      DEBUG printf("%lld %lld - %d %d\n", problems[i].l, problems[i].r, problems[i].cl, problems[i].cr);
    }

    for (int i = 0, now = 0; i < 2*n; i ++)
    {
      now += in[i];
      filled[i] = now;
      now -= out[i];
    }
    DEBUG {
      for (int i = 0; i < 2*n; i ++) printf("%3d%c", filled[i], i < 2*n - 1 ? ' ' : '\n');
      for (int i = 0; i < 2*n; i ++) printf("%3lld%c", decompress[i], i < 2*n - 1 ? ' ' : '\n');
    }

    bool got = false;
    for (int i = 0; i < 2*n; i ++)
    {
      if (filled[i] >= 2)
      {
        int j = i;
        while (j + 1 < 2*n && filled[j + 1] >= 2) j ++;
        for (int k = i + 1; k + 1 < j; k ++)
        {
          lli now = decompress[k] - decompress[i] + 1 + decompress[j] - decompress[k + 1] + 1;
          DEBUG printf("%d %d %d %d - %lld\n", k, i, j, k + 1, now);
          ans = max(ans, now);
        }
        i = j;
        got = true;
      }
    }
    if (!got) ans = 0;
    printf("%lld\n", ans);
  }

  return 0;
}

