using LL = long long;
using PII = pair<LL, LL>;
#define L first
#define R second

LL len(const PII& p) {
	return max(0ll, p.R - p.L + 1);
}
PII merge(const PII& a, const PII& b) {
	return make_pair(max(a.L, b.L), min(a.R, b.R));
}

const LL MAX = 1e9;
void brute(vector<PII> range, LL ans) {
	LL best = 0;
	int n = range.size();
	for (int mask = 1; mask < (1 << n) - 1; mask++) {
		PII lt(1, MAX), rt(1, MAX);
		for (int i = 0; i < n; i++) {
			if (mask & (1 << i)) {
				lt = merge(lt, range[i]);
			} else {
				rt = merge(rt, range[i]);
			}
		}
		best = max(best, len(lt) + len(rt));
	}
	if (best != ans) {
		trace(best, ans);
		assert(false);
	}
}

int main() {
	ios_base::sync_with_stdio(false); cin.tie(NULL);

	int n; cin >> n;
	vector<PII> range;
	for (int i = 0; i < n; i++) {
		LL l, r; cin >> l >> r;
		range.emplace_back(l, r);
	}
	sort(range.begin(), range.end(), 
		[](const PII& a, const PII& b) { 
			return make_pair(a.R, a.L) < make_pair(b.R, b.L); 
		});

	LL best = 0; PII tot(1, MAX);
	for (auto& e: range) {
		best = max(best, len(e));
		tot = merge(tot, e);
	}
	LL ans = len(tot) + best;

	auto first = range[0];
	LL rmin = range[0].R;
	range.erase(range.begin());
	// sort(range.begin(), range.end());
	vector<PII> lt;
	PII rest(1, MAX);
	bool empty = true;
	for (auto& e: range) {
		if (e.L <= rmin) {
			lt.push_back(e);
		} else {
			rest = merge(rest, e);
			empty = false;
		}
	}
	sort(lt.rbegin(), lt.rend());
	for (auto& e: lt) {
		if (!empty) ans = max(ans, len(rest) + len(merge(e, first)));
		rest = merge(rest, e);
		empty = false;
	}

	cout << ans << endl;

#ifdef LOCAL_EXEC
	range.push_back(first);
	brute(range, ans);
#endif

	return 0;
}

