int main() {
  std::cin.tie(0); std::cin.sync_with_stdio(false);
  int n; std::cin >> n;
  std::vector< int > a;
  std::vector< std::pair< int, int > > pairs(n);
  rep(i, 0, n) {
    int x, y; std::cin >> x >> y;
    x--;
    pairs.at(i) = {x, y};
    a.emplace_back(x);
    a.emplace_back(y);
  }
  std::sort(all(a));
  a.resize(std::unique(all(a)) - a.begin());
  auto rev = [&] (int x) {
    auto lb = std::lower_bound(all(a), x);
    assert(*lb == x);
    return lb - a.begin();
  };
  for (auto & pair : pairs) {
    pair.first = rev(pair.first);
    pair.second = rev(pair.second);
  }

  int R = 1e9;
  int longest = 0;
  for (auto pair : pairs) {
    cmn(R, pair.second);
    cmx(longest, a.at(pair.second) - a.at(pair.first));
  }

  int ans = 0;
  std::vector< std::pair< int, int > > red = pairs;
  std::vector< std::pair< int, int > > blue;
  int blueL = 0, blueR = 1e9;
  std::sort(all(red));
  for (int L = R - 1; 0 <= L; L--) {
    while (!red.empty()) {
      int l, r; std::tie(l, r) = red.back();
      if (l <= L) break;
      blue.emplace_back(l, r);
      cmx(blueL, l);
      cmn(blueR, r);
      red.pop_back();
    }
    if (red.empty()) break;
    if (blue.empty()) continue;
    debug(red, blue);

    int x = a.at(R) - a.at(L);
    int y = std::max(0, a.at(blueR) - a.at(blueL));
    cmx(ans, x + y);
  }

  std::sort(all(pairs));
  std::vector< int > len(n);
  rep(i, 0, n) {
    len.at(i) = a.at(pairs.at(i).second) - a.at(pairs.at(i).first);
  }
  debug(pairs);
  debug(len);

  auto make = [&] {
    std::vector< int > l0(n), r0(n);
    l0.at(0) = 0;
    r0.at(0) = 1e9;
    rep(i, 0, n-1) {
      l0.at(i + 1) = std::max(l0.at(i), a.at(pairs.at(i).first));
      r0.at(i + 1) = std::min(r0.at(i), a.at(pairs.at(i).second));
    }
    return std::make_pair(l0, r0);
  };
  std::vector< int > l0(n), r0(n), l1(n), r1(n);
  std::tie(l0, r0) = make();
  std::reverse(all(pairs));
  std::tie(l1, r1) = make();
  std::reverse(all(l1));
  std::reverse(all(r1));

  std::vector< int > l2(n), r2(n);
  rep(i, 0, n) {
    l2.at(i) = std::max(l0.at(i), l1.at(i));
    r2.at(i) = std::min(r0.at(i), r1.at(i));
    int z = r2.at(i) - l2.at(i);
    debug(len.at(i), z);
    cmx(ans, len.at(i) + z);
  }
  debug(l0, r0, l1, r1, l2, r2);
  std::cout << ans << std::endl;
  return 0;
}

