void ReadInput()
{
    cin >> n;
    segs.resize(n);
    for(int i = 0; i < n; ++i)
    {
        int l, r;
        cin >> l >> r;
        ++r;
        mx = max(mx, l);
        mn = min(mn, r);
        segs[i] = pii(l, r);
    }
}

void Solve()
{
    int ans = 0;
    for(auto s: segs)
        ans = max(ans, max(0, mn - mx) + s.second - s.first);

    vector<pii> v(n);
    for(int i = 0; i < n; ++i)
    {
        int a = max(0, mn - segs[i].first);
        int b = max(0, segs[i].second - mx);
