    }
    sort(v.begin(), v.end());
    int temp = INF;
    for(int i = 0; i < n; ++i)
    {
        auto to = v[i];
        to.second = -to.second;
        if(i > 0) ans = max(ans, temp + to.first);
        temp = min(temp, to.second);
    }
    cout << ans << '\n';
}

