int joy(int q, int c1min, int c1max, int c2min, int c2max, bool c1, bool c2)
{
	int op1 = 0, op2 = 0;
	int idx = index[q].second;

	if (max(0, (c1max - c1min + 1)) + max(0, (c2max - c2min + 1)) < border) return 0;

	if (q == N) {
		if (c1 && c2) return max(0, (c1max - c1min + 1)) + max(0, (c2max - c2min + 1));
		else return 0;
	}

	op1 = joy(q + 1, max(c1min, L[idx]), min(c1max, R[idx]), c2min, c2max, c1 | true, c2);
	op2 = joy(q + 1, c1min, c1max, max(c2min, L[idx]), min(c2max, R[idx]), c1, c2 | true);

	return max(op1, op2);
}

