  }
  int INF = 1000000001;
  auto solve = [&]() {
    vector<int> max_s = vector<int>(N, 0);
    vector<int> min_e = vector<int>(N, INF);
    REP(i, N) {
      int s = lr[i].first;
      int e = lr[i].second;
      if(i == 0) {
        max_s[i] = max(s, 0);
        min_e[i] = min(e, INF);
