    ll ans = 0;
    REP(i, N - 1) {
      ll sum = 0;
      sum += min_e[i] - max_s[i] + 1;
      sum += min_er[i + 1] - max_sr[i + 1] + 1;
      ans = max(sum, ans);
    }
    return ans;
  };
  sort(ALL(lr), comp_by_second);
  sort(ALL(lr), comp_by_first);
  ll ans = solve();
