template<class T> class sparsetable {
    function<T(T, T)> fun;
    vector<vector<T>> dat;
    VI len;
    int n, log;
public:
    sparsetable(const vector<T>& a, const function<T(T, T)>& F) : n(a.size()), log(log2(n)), fun(F) {
        dat = vec<T>(log + 1, n);
        len.resize(n + 1);
        FOR(i, 0, n)dat[0][i] = a[i];
        FOR(j, 0, log)FOR(i, 0, n - (1 << j)) {
            dat[j + 1][i] = fun(dat[j][i], dat[j][i + (1 << j)]);
        }
        eFOR(i, 2, n)len[i] = len[i >> 1] + 1;
    }
    T value(int l, int r) {
        int k = len[r - l];
        return fun(dat[k][l], dat[k][r - (1 << k)]);
    }
};

int main() {
    init();

    int n; cin >> n;
    vector<pair<int, int>> lr(n); cin >> lr;
    SORT(lr);
    VI l(n), r(n);
    FOR(i, 0, n) {
        l[i] = lr[i].first - 1;
        r[i] = lr[i].second;
    }
    sparsetable<int> l_max(l, [](int a, int b) {return max(a, b); });
    sparsetable<int> r_min(r, [](int a, int b) {return min(a, b); });

    int ans = max(r[0] - l[0] + max(r_min.value(1, n) - l_max.value(1, n), 0),
        r[n - 1] - l[n - 1] + max(r_min.value(0, n - 1) - l_max.value(0, n - 1), 0));
    FOR(i, 1, n - 1) {
        chmax(ans, max(r_min.value(0, i + 1) - l_max.value(0, i + 1), 0)
            + max(r_min.value(i + 1, n) - l_max.value(i + 1, n), 0));
        chmax(ans, r[i] - l[i] + max(min(r_min.value(0, i), r_min.value(i + 1, n))
            - max(l_max.value(0, i), l_max.value(i + 1, n)), 0));
    }
    print(ans);

    return 0;
}

