    /*
    case 1. one contest includes both L and R
    -> This contest cannot be improved more than max(0, R - L)
       So just put all the problems other than the one having greatest value of r[i] - l[i]

    case 2. one has L and the other has R
    -> in this case, the objective for the one that has L is max(0, min(r[i]) - L)
       and the objective for the one that has R is max(0, R - max(l[i]))
    */

    vl ls(n), rs(n); vpl ps(n);
