int agc040b(){
    int n;
    cin >> n;

    vector<pair<int,int> > v;
    vector<int> lh;
    vector<int> rh;
    int lmax=0,lmidx;
    int rmin=1e9+1,rmidx;
    int maxLen=0;
    for(int i=0;i<n;i++){
        int l,r;
        cin >>l>>r;
        lh.push_back(l);
        rh.push_back(r);
        if(chmax(lmax,l))lmidx=i;
        if(chmin(rmin,r))rmidx=i;
        //cout <<lh[i]<< " "<<rh[i]<<endl;
    }

    //ｌの最大値とrの最小値を同じグループに含まない場合
    //その2組以外をlの昇順で並び替える
    v.push_back(make_pair(0,0));
    for(int i=0;i<n;i++){
        if(i==lmidx||i==rmidx)continue;
        chmax(maxLen,rh[i]-lh[i]+1);
        v.push_back(make_pair(lh[i],rh[i]));
    }
    v.push_back(make_pair(lh[lmidx],rh[lmidx]));
    sort(v.begin(),v.end());
    v[0]=make_pair(lh[rmidx],rh[rmidx]);
    /*
    cout << "----"<<endl;
    for(int i=0;i<v.size();i++){
        cout << v[i].first << "," << v[i].second<<endl;
    }
    */

    //rの最小値を含むグループはrの値で共通の範囲が狭くなることはない
    //liが含まれるとき、lj<=li(i!=j)となるようなljを含んでも共通の範囲は狭くならない
    //そのためlを昇順にしたものを順番に突っ込むとどこかで最適なグループとなる。

    //計算量的にあらかじめある組まで含めた時のrの最小値を求めておく
    //lは昇順に並んでるので都度更新でいい
    int ans=0;
    vector<int> nrv;
    int nr=1e9+1;
    for(int i=n-1;i>=0;i--){
        chmin(nr,v[i].second);
        nrv.push_back(nr);
    }
    reverse(nrv.begin(),nrv.end());
    //各組についてスコアを求める
    for(int i=0;i<n-1;i++){
        chmax(ans,rmin-v[i].first+1+nrv[i+1]-lmax+1);
        //cout <<"ans="<<ans<<",1:"<<rmin<<"-"<<v[i].first<<"+1="<<rmin-v[i].first+1;
        //cout <<",2:"<<nrv[i]<<"-"<<lmax<<"+1="<<nrv[i+1]-lmax+1<< endl;
    }

    //ｌの最大値とrの最小値を同じグループに含む場合
    //そのグループにどの組を入れても共通範囲は狭くならない
    //そのため最大の長さの組以外を入れてやり、最大の長さの組はそのまま使うのが最適
    chmax(ans,max(rmin-lmax+1,0)+maxLen);
    //cout <<"1:ans=" << ans <<endl;
    //cout << max(rmin-lmax+1,0) << " " << maxLen<<endl;
    cout << ans << endl;
}

