	for(ll i = 0 ; i < n ; i++){
		ll l,r;
		tie(r,l) = RL[i];
		if(i==0){
			Left_R_min[i] = r;
			Left_L_MAX[i] = l;
		}else{
			Left_L_MAX[i] = max(l,Left_L_MAX[i-1]);
			Left_R_min[i] = min(r,Left_R_min[i-1]);
		}
	}
	//次に、右から見る
