		if(i==n-1){
			Right_R_min[n-1] = r;
			Right_L_MAX[n-1] = l;
		}else{
			Right_L_MAX[i] = max(l,Right_L_MAX[i+1]);
			Right_R_min[i] = min(r,Right_R_min[i+1]);
		}
