        r1 = min(r1, pairs[i].first);
        l1 = max(l1, pairs[i].first - pairs[i].second);
        r2 = pairs[i + 1].first;
        if (l2 == pairs[i].first - pairs[i].second)
        {
            l2 = 0;
            for (int j = i + 1; j < N; ++j)
            {
                l2 = max(l2, pairs[j].first - pairs[j].second);
            }
        }
        ans = max(ans, r1 - l1 + r2 - l2);
    }
    cout << ans + 2 << endl;
}

