const int inf = 1e9 + 100;

bool cmp(pair<int, int>a, pair<int, int>b) {
	return a.second < b.second || (a.second == b.second && a.first > b.first);
}

int main() {
	ios_base::sync_with_stdio(0);
	cin.tie(0);
	int n;
	cin >> n;
	vector<pair<int, int>> segments;
	for (int i = 0; i < n; i++) {
		int l, r;
		cin >> l >> r;
		segments.emplace_back(l, r);
	}
	int ans = 0;
	sort(segments.begin(), segments.end(), cmp);
	vector<pair<int, int>> suffix(n, { inf,-inf });
	vector<pair<int, int>> prefix(n, { inf, -inf });
	suffix.back() = segments.back();
	for (int i = n - 2; i >= 0; i--) {
		int l = suffix[i + 1].first;
		int r = suffix[i + 1].second;
		l = max(l, segments[i].first);
		r = min(r, segments[i].second);
		if (l > r) {
			break;
		}
		suffix[i] = { l,r };
	}
	prefix[0] = segments[0];
	for (int i = 1; i < n; i++) {
		int l = prefix[i - 1].first;
		int r = prefix[i - 1].second;
		l = max(l, segments[i].first);
		r = min(r, segments[i].second);
		if (l > r) {
			break;
		}
		prefix[i] = { l,r };
	}

	for (int i = n - 1; i > 0; i--) {
		int l1 = suffix[i].first;
		int r1 = suffix[i].second;
		int l2 = prefix[i - 1].first;
		int r2 = prefix[i - 1].second;
		ans = max(ans, max(r2 - l2 + 1, 0) + max(r1 - l1 + 1, 0));
	}
	cout << ans;
	return 0;
}

