        vector<int> v, v2;
        for (int j = 0; j < n; j++) {
            if (i & (1 << j)) {
                v.pb(j);
            }
            else v2.pb(j);
        }
        int l = -inf, r = inf;
        int ans = 0;
        for (auto i : v) {
            l = max(l, a[i].fi);
            r = min(r, a[i].se);
            if (r < l) goto a;
        }
        ans = r- l +1;
        if (r == inf || l == -inf) continue;
        l = -inf, r = inf;
        for (auto i : v2) {
            l = max(l, a[i].fi);
            r = min(r, a[i].se);
            if (r < l) goto a;
        }
        if (r == inf || l == -inf) continue;
        ans += r - l + 1;
    //     for (auto i : v) cout << i << " ";
    //     cout << endl;
    // for (auto i : v2) cout<< i << " " ;
    // 	cout << endl;
    //     cout << ans << endl;
        mx = max(mx, ans);
        a:;
    }
    cout << mx << endl;
    return 0;
}

