#include <bits/stdc++.h>
using namespace std;
using PP = pair<int, int>;

const int inf = 1e9;
int n;
int m;
PP p[100000];
PP q[100000];
PP f[100001];
PP g[100001];

int len(PP p) {
  return max(0, p.second - p.first);
}

PP cap(PP p, PP q) {
  return PP(max(p.first, q.first), min(p.second, q.second));
}

void reduce() {
  int prevr = -inf;
  vector<bool> chosen(n, true);
  for (int i = 0; i < n; ++i) {
    if (p[i].second <= prevr) chosen[i - 1] = false;
    prevr = p[i].second;
  }

  for (int i = 0; i < n; ++i) {
    if (!chosen[i]) continue;
    q[m] = p[i];
    ++m;
  }
}

int main() {
  cin >> n;
  for (int i = 0; i < n; ++i) {
    int a, b;
    cin >> a >> b;
    p[i] = PP(a, b + 1);
  }
  sort(p, p + n, [](PP a, PP b) {
    return a.first < b.first || a.first == b.first && a.second > b.second;
  });
  reduce();

  if (m == 1) {
    cout << len(p[0]) + len(p[n - 1]) << endl;
    return 0;
  }

  f[0] = PP(-inf, inf);
  for (int i = 0; i < m; ++i) {
    f[i + 1] = cap(f[i], q[i]);
  }
  g[m] = PP(-inf, inf);
  for (int i = m - 1; i >= 0; --i) {
    g[i] = cap(g[i + 1], q[i]);
  }

  int mx = 0;
  for (int i = 1; i < m; ++i) {
    cerr << f[i].first << ' ' << f[i].second << ' '
         << g[i].first << ' ' << g[i].second << endl;
    mx = max(mx, len(f[i]) + len(g[i]));
  }
  cout << mx << endl;
}

