using namespace std;
const int maxn = 100100;
int a[maxn], b[maxn];
int main(){
	int n; cin >> n;
	for(int i = 0; i < n; i++) cin >> a[i] >> b[i], b[i]++;
	int mb = b[0];
	for(int i = 0; i < n; i++) mb = min(mb, b[i]);
	int ch = -1;
	for(int i = 0; i < n; i++){
		if(b[i] == mb){
			if(ch == -1 || a[i] > a[ch]) ch = i;
		}
	}
	assert(ch != -1);
	map<int, vector<int> > in_l, in_r;
	for(int i = 0; i < n; i++){
		in_l[a[i]].push_back(i);
		in_r[b[i]].push_back(i);
	}
	multiset<int> ls, rs;
	multiset<int> covered;
	vector<int> to_a;
	for(int i = 0; i < n; i++){
		if(a[ch] <= a[i] && a[i] < b[ch]){
			to_a.push_back(a[i]);
		}
	}
	for(int i = 0; i < n; i++){
		ls.insert(a[i]);
		rs.insert(b[i]);
	}
	vector<int> up(n, 0);
	auto check = [&](int id){
		if(up[id] == 3){
			rs.erase(rs.find(b[id]));
			ls.erase(ls.find(a[id]));
			if(id != ch) covered.insert(b[id] - a[id]);
		}
	};
	auto get = [&](){
		if(ls.empty()){
			assert(!covered.empty());
			return *prev(covered.end());
		}
		int ml = *prev(ls.end());
		int mr = *rs.begin();
		return max(0, mr - ml);
	};
	sort(to_a.begin(), to_a.end());
	int ans = 0;
	for(int i = 0; i < n; i++) ans = max(ans, b[i] - a[i]);
	for(int ca : to_a){
		while(!in_l.empty() && (*in_l.begin()).first <= ca){
			auto it = in_l.begin();
			for(int p : it->second){
				up[p] |= 1;
				check(p);
			}
			in_l.erase(it);
		}
		while(!in_r.empty() && (*prev(in_r.end())).first >= b[ch]){
			auto it = prev(in_r.end());
			for(int p : it->second){
				up[p] |= 2;
				check(p);
			}
			in_r.erase(it);
		}
		ans = max(ans, b[ch] - ca + get());
	}
	cout << ans << endl;
	return 0;
}

