const int MM = 1e5+5;

int n, ans;
pair<int, int> a[MM];

#define lc (rt<<1)
#define rc (rt<<1|1)
#define nm ((nl+nr)>>1)

struct node{
    int maxl, minr;
} tree[MM*3];

inline void push_up(int rt){
    tree[rt].maxl = max(tree[lc].maxl, tree[rc].maxl);
    tree[rt].minr = min(tree[lc].minr, tree[rc].minr);
}

void build(int l = 1, int r = MM-1, int rt = 1){
    int nl = l, nr = r;
    if(l == r){
        tree[rt].maxl = 0, tree[rt].minr = 1e9+2;
        return;
    }
    build(l, nm, lc);
    build(nm+1, r, rc);
    push_up(rt);
}

void update(int l, int vl, int vr, int nl = 1, int nr = MM-1, int rt = 1){
    if(nl == nr){
        assert(nl == l);
        tree[rt].maxl = max(tree[rt].maxl, vl);
        tree[rt].minr = min(tree[rt].minr, vr);
        return;
    }
    if(l <= nm)
        update(l, vl, vr, nl, nm, lc);
    else
        update(l, vl, vr, nm+1, nr, rc);
    push_up(rt);
}

int query1(int l, int r, int nl = 1, int nr = MM-1, int rt = 1){
    if(r < nl || l > nr)
        return 0;
    if(l <= nl && r >= nr)
        return tree[rt].maxl;
    return max(query1(l, r, nl, nm, lc), query1(l, r, nm+1, nr, rc));
}

int query2(int l, int r, int nl = 1, int nr = MM-1, int rt = 1){
    if(r < nl || l > nr)
        return 1e9+2;
    if(l <= nl && r >= nr)
        return tree[rt].minr;
    return min(query2(l, r, nl, nm, lc), query2(l, r, nm+1, nr, rc));
}

