using namespace std;

int solve(vector < pair < int, int > > v)
{
        int n = v.size();
        vector < pair < int, int > > l(n), r(n);
        l[0] = v[0];
        r[n - 1] = v[n - 1];
        for(int i = 1; i < n; i++){
                l[i].fi = max(l[i - 1].fi, v[i].fi);
                l[i].se = min(l[i - 1].se, v[i].se);
        }
        int res = 0;
        for(int i = n - 2; i >= 0; i--){
                r[i].fi = max(r[i + 1].fi, v[i].fi);
                r[i].se = min(r[i + 1].se, v[i].se);
                res = max(res, max(0, l[i].se - l[i].fi + 1) + max(0, r[i + 1].se - r[i + 1].fi + 1));
        }
        for(int i = 1; i < n - 1; i++){
                pair < int, int > p = l[i - 1];
                p.fi = max(p.fi, r[i + 1].fi);
                p.se = min(p.se, r[i + 1].se);

                res = max(res, v[i].se - v[i].fi + 1 + max(0, p.se - p.fi + 1));
        }
        return res;
}

