	for(int i=0;i<n;i++){
		ma.vec[ma.cor+i].first=ve[i].first;
		mi.vec[mi.cor+i].first=ve[i].second;

	}
	mi.shoki2();
	ma.shoki2();

	for(int i=0;i<n;i++){
		int t,s;
		if(i==0){
			 t=mi.segmin(i+1,n).first;
			 s=ma.segmax(i+1,n).first;
		}
		else if(i==n-1){
			 t=mi.segmin(0,i).first;
			 s=ma.segmax(0,i).first;	
		}
		else{
			 t=min(mi.segmin(0,i).first,mi.segmin(i+1,n).first);
			 s=max(ma.segmax(0,i).first,ma.segmax(i+1,n).first);		
		}
			ans=max(ans,ve[i].second-ve[i].first+max(0ll,t-s));

