	for(int i=0;i<n-1;i++){
			int t=mi.segmin(0,i+1).first;
			int s=ma.segmax(0,i+1).first;	

			int tt=mi.segmin(i+1,n).first;
			int ss=ma.segmax(i+1,n).first;	
		ans=max(ans,max(0ll,t-s)+max(0ll,tt-ss));


	}
	cout<<ans<<endl;

