	res += max(r-l+1, 0);
	return res;
}

int main()
{
	ios_base::sync_with_stdio(0);
	cin.tie(0); cout.tie(0);
	cin >> n;
	vector <pair<int, int>> seg(n+1);
	for (int i=1; i<=n; i++) {
		cin >> seg[i].first >> seg[i].second;
		ans = max(ans, seg[i].second - seg[i].first + 1);
	}
	sort (seg.begin(), seg.end(), 
		[](const pair<int, int>& x, pair<int, int>&y) {
			if (x.second > y.second) return 0;
			if (x.second == y.second && x.first > y.first) return 0;
			return 1;
		}
	);
	int l = 1, r = n-1;
	while (r-l > 2) {
		int mid1 = l+(r-l)/3;
		int mid2 = l+(r-l)*2/3;
		int res1 = get(mid1, seg);
		int res2 = get(mid2, seg);
		if (res2 >= res1) {
			l = mid2;
		} else {
			r = mid1;
		}
	}
	ans = max(max(ans, get(l, seg)), max(get(r, seg), get(min(l+1, r), seg)));
	cout << ans;
	return 0;
}

