  }

  int64_t p = 0, q = 0;
  int64_t tmp_l = L[0], tmp_r = R[0];
  rep(i, N) {
    if (ChMax(tmp_l, L[i])) {
      p = i;
    }
    if (ChMin(tmp_r, R[i])) {
      q = i;
    }
  }

  if (p == q) {
    int64_t ans = 0;
    rep(i, N) {
      if (i != p) {
        ChMax(ans, R[i] - L[i]);
      }
    }
