  }

  int64_t ans = 0;
  rep(i, N) { ChMax(ans, max(int64_t(0), R[q] - L[p]) + R[i] - L[i]); }

  using P = pair<int64_t, int64_t>;
  vector<P> ab(N);

  rep(i, N) {
    ab[i].first  = max(int64_t(0), R[i] - L[p]);
