  rep(i, 1, N) { c[i] = min(-ab[i - 1].second, c[i - 1]); }

  rep(i, 1, N) { ChMax(ans, ab[i].first + c[i]); }

  cout << ans << endl;

  return EXIT_SUCCESS;
}

