using pii = pair<int, int>;
using vi = vector<int>;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0); cout.tie(0);

    // put intervals in two groups
    // maximize intersection of each group
    //
    // iterate over first problem in first contest
    // can we quickly compute intersection of set of intervals?
    // yes: max(0, min r - max l)
    //
    // say we have fixed the leftmost point. As we sweep the rightmost point outwards, we lose
    // more intervals,

    int n;
    cin >> n;

    vi pts;
    vector<pii> a(n);
    int r = 1e9 + 7;
    multiset<int> ls, rs;
    for (int i = 0; i < n; ++i) {
        cin >> a[i].first >> a[i].second;
        r = min(r, a[i].second);
        ls.insert(a[i].first);
        rs.insert(a[i].second);
    }

    vector<pii> lefts;
    int ans = 0;
    for (int i = 0; i < n; ++i) {
        auto lit = prev(end(ls));
        auto rit = begin(rs);
        if (*lit == a[i].first)
            --lit;
        if (*rit == a[i].second)
            ++rit;

        ans = max(ans, a[i].second - a[i].first + 1 + max(0, *rit - *lit + 1));

        if (a[i].first <= r) {
            assert(r <= a[i].second);
            lefts.push_back(a[i]);
        }
    }

    // otherwise, one of the intersections ends at r.
    // For all intervals that contain r, add them to the left intersection
    sort(all(lefts));
    int maxl = -1;
    for (auto& p : lefts) {
        maxl = max(maxl, p.first);
        ls.erase(ls.find(p.first));
        rs.erase(rs.find(p.second));
        int second = 0;
        if (!rs.empty()) {
            second = max(second, *begin(rs) - *prev(end(ls)) + 1);
        }
        ans = max(ans, r - maxl + 1 + second);
    }

    cout << ans << '\n';

    return 0;
}

