long long ans = 0;

void calc1(int n, vector<pair<long long, long long>> &u) {
    multiset<long long> l1, r1, l2, r2;
    for (int i = 0; i < n; i++) {
        l2.insert(u[i].second); r2.insert(u[i].first);
    }
    sort(u.begin(), u.end());
    for (int i = 0; i < n-1; i++) {
        auto a = u[i].second;
        auto b = u[i].first;
        l1.insert(a); r1.insert(b);
        l2.erase(l2.find(a)); 
        r2.erase(r2.find(b));
        long long tmp = max(0LL, *r1.begin()-*l1.rbegin()+1) + max(0LL, *r2.begin()-*l2.rbegin()+1);
        ans = max(ans, tmp);
    }
}

void calc2(int n, vector<pair<long long, long long>> &u) {
    multiset<long long> l1, r1, l2, r2;
    for (int i = 0; i < n; i++) {
        l2.insert(u[i].first); r2.insert(u[i].second);
    }
    sort(u.begin(), u.end());
    for (int i = 0; i < n-1; i++) {
        auto a = u[i].first;
        auto b = u[i].second;
        l1.insert(a); r1.insert(b);
        l2.erase(l2.find(a)); 
        r2.erase(r2.find(b));
        long long tmp = max(0LL, *r1.begin()-*l1.rbegin()+1) + max(0LL, *r2.begin()-*l2.rbegin()+1);
        ans = max(ans, tmp);
    }
}

