int dp1[100010];//[0,i)
int dp2[100010];//[i,N)
void solve() {
	int N; cin >> N;
	vector<P>v;
	REP(i, N) {
		int l, r; cin >> l >> r;
		v.push_back({ r, l });
	}
	VSORT(v);
	int l = v[0].second, r = v[0].first;
	REP(i, N) {
		l = max(l, v[i].second);
		if (l > r)break;
		dp1[i + 1] = (r - l + 1);
	}
	l = v[N - 1].second, r = v[N - 1].first;
	REPR(i, N) {
		r = min(r, v[i].first);
		l = max(l, v[i].second);
		if (l > r)break;
		dp2[i] = (r - l + 1);
	}
	ll ans = 0;
	REP(i, N) {
		ans = max(ans, dp1[i] + dp2[i]);
	}
	print(ans);
}

signed main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	solve();
}

