#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
typedef long long ll;

struct Q{
    ll l,r;
};

int main(){
    int N;
    cin >> N;
    vector<Q> X;
    for(int i=0;i<N;i++){
        ll l,r;
        cin >> l >> r;
        X.push_back({l,r});
    }
    auto solve1 = [&](){
        sort(X.begin(),X.end(),[](Q& a,Q& b){
            if(a.r!=b.r) return a.r<b.r;
            else return a.l<b.l;
        });
        vector<ll> L(N),R(N),Lm(N),Rm(N);
        ll l = 0,r = 0;
        for(int i=0;i<N;i++){
            Lm[i] = max((i!=0? Lm[i-1]:0),X[i].r-X[i].l+1);
            if(i==0){
                L[i] = X[i].r-X[i].l+1;
                l = X[i].l;
                r = X[i].r;
            }else if(L[i-1]!=0){
                L[i] = max(0LL,min(X[i].r,r)-max(X[i].l,l)+1);
                l = max(X[i].l,l);
                r = min(X[i].r,r);
            }else L[i] = 0;
        }
        l = 1e9,r = 1e9;
        for(int i=N-1;i>=0;i--){
            Rm[i] = max((i!=N-1? Rm[i+1]:0),X[i].r-X[i].l+1);
            if(i==N-1){
                R[i] = X[i].r-X[i].l+1;
                l = X[i].l,r = X[i].r;
            }else if(R[i+1]!=0){
                R[i] = max(0LL,min(X[i].r,r)-max(X[i].l,l)+1);
                l = max(X[i].l,l);
                r = min(X[i].r,r);
            }else R[i] = 0;
        }
        ll ans = 0;
        for(int i=0;i<N-1;i++) ans = max({ans,L[i]+R[i+1],Lm[i],Rm[i+1]});
        return ans;
    };
    cout << solve1() << endl;
}

