            bCnt = it[1]-it[0]+1
            bL = it[0]
            bR = it[1]
            return@forEach
        }

        var nextACnt = when {
            it[1] < aL -> 0
            it[0] > aR -> 0
            it[0] >= aL && it[1] <= aR -> it[1]-it[0]+1
            it[0] >= aL && it[1] > aR -> aR-it[0]+1
            it[1] <= aR && it[0] < aL -> it[1]-aL+1
            else -> 0
        }

        var nextBCnt = when {
            it[1] < bL -> 0
            it[0] > bR -> 0
            it[0] >= bL && it[1] <= bR -> it[1]-it[0]+1
            it[0] >= bL && it[1] > bR -> bR-it[0]+1
            it[1] <= bR && it[0] < bL -> it[1]-bL+1
            else -> 0
        }

