                it[0] >= aL && it[1] <= aR -> it[0]
                it[0] >= aL && it[1] > aR -> it[0]
                it[1] <= aR && it[0] < aL -> aL
                else -> 0
            }
            aR = when {
                it[1] < aL -> aR
                it[0] > aR -> aR
                it[0] >= aL && it[1] <= aR -> it[1]
                it[0] >= aL && it[1] > aR -> aR
                it[1] <= aR && it[0] < aL -> it[1]
                else -> 0
            }
        } else {
            bCnt = nextBCnt
            bL = when {
                it[1] < bL -> bL
                it[0] > bR -> bR
                it[0] >= bL && it[1] <= bR -> it[0]
                it[0] >= bL && it[1] > bR -> it[0]
                it[1] <= bR && it[0] < bL -> bL
                else -> 0
            }
            bR = when {
                it[1] < bL -> bR
                it[0] > bR -> bR
                it[0] >= bL && it[1] <= bR -> it[1]
                it[0] >= bL && it[1] > bR -> bR
                it[1] <= bR && it[0] < bL -> it[1]
                else -> 0
            }
        }
    }

    println(aCnt + bCnt)
}

