		for (int i = 0; i < n; i++) {
			Obj o = list.get(i);
			int l = Math.max(obj1.l, o.l);
			int r = Math.min(obj1.r, o.r);
			o.v = Math.max(r - l + 1, 0);
		}
		Collections.sort(list, (o1, o2) -> o1.v - o2.v);
		Obj obj2 = list.get(0);
		obj2.t = 2;

		int al1 = obj1.l;
