 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        BTwoContests solver = new BTwoContests();
        solver.solve(1, in, out);
        out.close();
    }

    static class BTwoContests {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int[] l = new int[n];
            int[] r = new int[n];
            in.readIntArrays(l, r);
            MiscUtils.decreaseByOne(l, r);

            int ans = 0;
            IntIntPair[] a = new IntIntPair[n];
            for (int i = 0; i < n; i++) {
                a[i] = new IntIntPair(l[i], r[i]);
                ans = Math.max(ans, r[i] - l[i] + 1);
            }
            Arrays.sort(a);

            ans = getAns(n, a);

            Arrays.sort(a, (p1, p2) -> p1.second == p2.second ? p1.first - p2.first : p1.second - p2.second);
            ans = Math.max(ans, getAns(n, a));

            out.printLine(ans);
        }

        private int getAns(int n, IntIntPair[] a) {
            int ans = 0;
            int[] ll = new int[n];
            int[] rr = new int[n];
            int first = 0;
            int last = Constants.INF;
            for (int i = 0; i < n; i++) {
                first = Math.max(first, a[i].first);
                last = Math.min(last, a[i].second);
                ll[i] = Math.max(0, last - first + 1);
            }
            first = 0;
            last = Constants.INF;
            for (int i = n - 1; i >= 0; i--) {
                first = Math.max(first, a[i].first);
                last = Math.min(last, a[i].second);
                rr[i] = Math.max(0, last - first + 1);
            }

            for (int i = 0; i < n - 1; i++) {
                ans = Math.max(ans, ll[i] + rr[i + 1]);
            }
            return ans;
        }

    }

    static class OutputWriter {
