/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        MyInput in = new MyInput(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        BTwoContests solver = new BTwoContests();
        solver.solve(1, in, out);
        out.close();
    }

    static class BTwoContests {
        public void solve(int testNumber, MyInput in, PrintWriter out) {
            int n = in.nextInt();
            int[][] x = in.nextIntArray2D(n, 2);
            Arrays.sort(x, (a, b) -> {
                if (a[1] != b[1]) return a[1] - b[1];
                return (a[0] - b[0]);
            });

            long ans = 0;
            int maxL = Integer.MIN_VALUE, minR = Integer.MAX_VALUE;
            for (int[] y : x) {
                maxL = Math.max(maxL, y[0]);
                minR = Math.min(minR, y[1]);
                ans = Math.max(ans, y[1] - y[0] + 1);
            }
            ans += Math.max(0, minR - maxL + 1);

            for (int[] y : x) {
                int l = y[0];
                y[0] = Math.max(0, y[1] - maxL + 1);
                y[1] = Math.max(0, minR - l + 1);
            }
            Arrays.sort(x, (a, b) -> {
                if (a[0] != b[0]) return a[0] - b[0];
                return -(a[1] - b[1]);
            });

            long[] s = new long[n + 2];
            long[] t = new long[n + 2];
            s[n + 1] = Integer.MAX_VALUE;
            t[0] = Integer.MAX_VALUE;
            for (int i = 0; i < n; i++) {
                s[n - i] = Math.min(s[n - i + 1], x[n - 1 - i][0]);
                t[i + 1] = Math.min(t[i], x[i][1]);
            }
            for (int i = 1; i < n; i++) {
                ans = Math.max(ans, t[i] + s[i + 1]);
            }
            out.println(ans);
        }

    }

    static class MyInput {
        private final BufferedReader in;
        private static int pos;
        private static int readLen;
        private static final char[] buffer = new char[1024 * 8];
        private static char[] str = new char[500 * 8 * 2];
        private static boolean[] isDigit = new boolean[256];
        private static boolean[] isSpace = new boolean[256];
        private static boolean[] isLineSep = new boolean[256];

        static {
            for (int i = 0; i < 10; i++) {
                isDigit['0' + i] = true;
            }
            isDigit['-'] = true;
            isSpace[' '] = isSpace['\r'] = isSpace['\n'] = isSpace['\t'] = true;
            isLineSep['\r'] = isLineSep['\n'] = true;
        }

        public MyInput(InputStream is) {
            in = new BufferedReader(new InputStreamReader(is));
        }

        public int read() {
            if (pos >= readLen) {
                pos = 0;
                try {
                    readLen = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (readLen <= 0) {
                    throw new MyInput.EndOfFileRuntimeException();
                }
            }
            return buffer[pos++];
        }

        public int nextInt() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            int ret = 0;
            if (str[0] == '-') {
                i = 1;
            }
            for (; i < len; i++) ret = ret * 10 + str[i] - '0';
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

        public char nextChar() {
            while (true) {
                final int c = read();
                if (!isSpace[c]) {
                    return (char) c;
                }
            }
        }

        int reads(int len, boolean[] accept) {
            try {
                while (true) {
                    final int c = read();
                    if (accept[c]) {
                        break;
                    }
                    if (str.length == len) {
                        char[] rep = new char[str.length * 3 / 2];
                        System.arraycopy(str, 0, rep, 0, str.length);
                        str = rep;
                    }
                    str[len++] = (char) c;
                }
            } catch (MyInput.EndOfFileRuntimeException e) {
            }
            return len;
        }

        public int[] nextIntArray(final int n) {
            final int[] res = new int[n];
            for (int i = 0; i < n; i++) {
                res[i] = nextInt();
            }
            return res;
        }

        public int[][] nextIntArray2D(final int n, final int k) {
            final int[][] res = new int[n][];
            for (int i = 0; i < n; i++) {
                res[i] = nextIntArray(k);
            }
            return res;
        }

        static class EndOfFileRuntimeException extends RuntimeException {
        }

    }
}

import java.util.*;

public class Main {

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        Problem[] problems = new Problem[n];
        for (int j = 0; j < n; j++) {
            int l = in.nextInt();
            int r = in.nextInt();
            problems[j] = new Problem(l, r);
        }
        Arrays.sort(problems);
        List<Problem> remProblems = new ArrayList<>(n);
        boolean[] isRemProblem = new boolean[n];
        int maxL = 0;
        for (int j = 0; j < n; j++) {
            Problem problem = problems[j];
            if (problem.l > maxL) {
                isRemProblem[j] = true;
                maxL = problem.l;
                remProblems.add(problem);
            }
        }
        int answer = 0;
        for (int j = 0; j < n; j++) {
            if (!isRemProblem[j]) {
                Problem problem = problems[j];
                answer = Math.max(answer, problem.r - problem.l + 1);
            }
        }
        answer += Math.max(0, remProblems.get(0).r - remProblems.get(remProblems.size() - 1).l + 1);
        for (int j = 0; j < remProblems.size() - 1; j++) {
            answer = Math.max(
                    answer,
                              Math.max(0, remProblems.get(0).r - remProblems.get(j).l + 1)
                            + Math.max(0, remProblems.get(j + 1).r - remProblems.get(remProblems.size() - 1).l + 1));
        }
        for (int j = 1; j < remProblems.size() - 1; j++) {
            Problem problem = remProblems.get(j);
            answer = Math.max(answer, problem.r - problem.l + 1 + Math.max(0, remProblems.get(0).r - remProblems.get(remProblems.size() - 1).l + 1));
        }
        System.out.println(answer);
    }

    static class Problem implements Comparable<Problem> {
        final int l;
        final int r;

        Problem(int l, int r) {
            this.l = l;
            this.r = r;
        }

        @Override
        public int compareTo(Problem o) {
            if (r != o.r) {
                return r - o.r;
            } else {
                return o.l - l;
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Arrays;

public class Main {
	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		int n = Integer.parseInt(br.readLine());
		Obj[] arr = new Obj[n];
		for (int i = 0; i < n; i++) {
			String[] sa = br.readLine().split(" ");
			Obj o = new Obj();
			o.l = Integer.parseInt(sa[0]);
			o.r = Integer.parseInt(sa[1]);
			o.v = o.r - o.l + 1;
			arr[i] = o;
		}
		br.close();

		Obj maxV = new Obj();
		Obj maxL = new Obj();
		Obj minR = new Obj();
		minR.r = 1000000000;
		for (int i = 0; i < n; i++) {
			Obj o = arr[i];
			if (o.v > maxV.v) {
				maxV = o;
			}
			if (o.l > maxL.l) {
				maxL = o;
			}
			if (o.r < minR.r) {
				minR = o;
			}
		}
		int ans = maxV.v + minR.r - maxL.l + 1;
		if (maxL == minR) {
			System.out.println(ans);
			return;
		}

		Arrays.parallelSort(arr);

		int minr = maxL.r;
		for (int i = 1; i < n; i++) {
			Obj o = arr[i - 1];
			minr = Math.min(minr, o.r);
			int v1 = Math.max(minR.r - arr[i].l + 1, 0);
			int v2 = Math.max(minr - maxL.l + 1, 0);
			ans = Math.max(ans, v1 + v2);
		}
		System.out.println(ans);
	}

	static class Obj implements Comparable<Obj> {
		int l, r, v;

		@Override
		public int compareTo(Obj o) {
			if (l != o.l) {
				return o.l - l;
			}
			return o.r - r;
		}
	}
}

