import java.io.*;
import java.util.*;

public class Main {
    public static void main(String args[]) throws Exception {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int N = sc.nextInt();
        Bag left = new Bag();
        Bag right = new Bag();
        Interval[] intervals = new Interval[N];
        Interval[] intervals2 = new Interval[N];
        Interval longest = new Interval(-1, 0, 0);
        for (int i = 0; i < N; i++) {
            long lo = sc.nextLong();
            long hi = sc.nextLong();

            intervals[i] = new Interval(i, lo, hi);
            intervals2[i] = new Interval(i, lo, hi);
            right.loFreq.merge(lo, 1, Integer::sum);
            right.hiFreq.merge(hi, 1, Integer::sum);
        }
        Arrays.sort(intervals);
        Arrays.sort(intervals2, new Comparator<Interval>() {
            @Override
            public int compare(Interval o1, Interval o2) {
                return (int) ((o1.hi - o1.lo) - (o2.hi - o2.lo));
            }
        });
        longest = intervals2[N - 1];
        long totalLo = 0;
        long totalHi = (long) 2e9;
        int absorbed = 0;
        for (Interval i : intervals2) {
            if (i.idx != longest.idx) {
                if (absorbed + 1 <= N - 2 && longest.lo == i.lo && i.hi == longest.hi) {
                    absorbed++;
                    continue; // that can go into the biggest one
                }
                totalHi = Math.min(totalHi, i.hi);
                totalLo = Math.max(totalLo, i.lo);
            }
        }
        long ans = longest.hi - longest.lo + 1 + Math.max(0, totalHi - totalLo + 1); // We can at least get that best interval
        // Sweep through, transferring from right bag to left
        for (int i = 0; i < N; i++) {
            long lo = intervals[i].lo;
            long hi = intervals[i].hi;
            left.loFreq.merge(lo, 1, Integer::sum);
            left.hiFreq.merge(hi, 1, Integer::sum);

            right.loFreq.merge(lo, -1, Integer::sum);
            if (right.loFreq.get(lo) == 0) {
                right.loFreq.remove(lo);
            }
            right.hiFreq.merge(hi, -1, Integer::sum);
            if (right.hiFreq.get(hi) == 0) {
                right.hiFreq.remove(hi);
            }

            if (left.loFreq.size() > 0 && right.loFreq.size() > 0) {
                // Now compute answer! But both bags must be size >= 1
                // Choose the most limiting of each boundary, i.e.
                // highest min, lowest max
                long leftAns = Math.max(0, left.hiFreq.firstKey() - left.loFreq.lastKey() + 1);
                long rightAns = Math.max(0, right.hiFreq.firstKey() - right.loFreq.lastKey() + 1);
                ans = Math.max(ans, leftAns + rightAns);
            }
        }
        out.println(ans);

        out.close();
    }

    static class Bag {
        TreeMap<Long, Integer> loFreq, hiFreq;
        public Bag() {
            loFreq = new TreeMap<>();
            hiFreq = new TreeMap<>();
        }
    }

    static class Interval implements Comparable<Interval> {
        long lo, hi;
        int idx;
        public Interval(int i, long l, long h) {
            idx = i; lo = l; hi = h;
        }
        public int compareTo(Interval i2) {
            // We want the intervals to be close together
//            return (int) (hi - i2.hi);
            return lo - i2.lo != 0 ? (int) (lo - i2.lo) : (int) (hi - i2.hi);
        }
    }

    static class FastScanner {
        public int BS = 1<<16;
        public char NC = (char)0;
        byte[] buf = new byte[BS];
        int bId = 0, size = 0;
        char c = NC;
        double cnt = 1;
        BufferedInputStream in;

        public FastScanner() {
            in = new BufferedInputStream(System.in, BS);
        }

        public FastScanner(String s) {
            try {
                in = new BufferedInputStream(new FileInputStream(new File(s)), BS);
            }
            catch (Exception e) {
                in = new BufferedInputStream(System.in, BS);
            }
        }

        private char getChar(){
            while(bId==size) {
                try {
                    size = in.read(buf);
                }catch(Exception e) {
                    return NC;
                }
                if(size==-1)return NC;
                bId=0;
            }
            return (char)buf[bId++];
        }

        public int nextInt() {
            return (int)nextLong();
        }

        public long nextLong() {
            cnt=1;
            boolean neg = false;
            if(c==NC)c=getChar();
            for(;(c<'0' || c>'9'); c = getChar()) {
                if(c=='-')neg=true;
            }
            long res = 0;
            for(; c>='0' && c <='9'; c=getChar()) {
                res = (res<<3)+(res<<1)+c-'0';
                cnt*=10;
            }
            return neg?-res:res;
        }

        public double nextDouble() {
            double cur = nextLong();
            return c!='.' ? cur:cur+nextLong()/cnt;
        }

        public String next() {
            StringBuilder res = new StringBuilder();
            while(c<=32)c=getChar();
            while(c>32) {
                res.append(c);
                c=getChar();
            }
            return res.toString();
        }

        public String nextLine() {
            StringBuilder res = new StringBuilder();
            while(c<=32)c=getChar();
            while(c!='\n') {
                res.append(c);
                c=getChar();
            }
            return res.toString();
        }

        public boolean hasNext() {
            if(c>32)return true;
            while(true) {
                c=getChar();
                if(c==NC)return false;
                else if(c>32)return true;
            }
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.InputMismatchException;
import java.util.NoSuchElementException;

public class Main {

	static PrintWriter out;
	static InputReader ir;

	static void solve() {
		int n = ir.nextInt();
		long[][] a = new long[n][];
		long[][] b = new long[n][2];
		for (int i = 0; i < n; i++)
			a[i] = ir.nextLongArray(2);
		for (int i = 0; i < n; i++)
			for (int j = 0; j < 2; j++)
				b[i][j] = a[i][j];
		Arrays.sort(a, new Comparator<long[]>() {
			public int compare(long[] A, long[] B) {
				if (A[0] != B[0])
					return Long.compare(A[0], B[0]);
				return -Long.compare(A[1], B[1]);
			}
		});
		Arrays.sort(b, new Comparator<long[]>() {
			public int compare(long[] A, long[] B) {
				if (A[1] != B[1])
					return Long.compare(A[1], B[1]);
				return Long.compare(A[0], B[0]);
			}
		});
		long ma = 0, mi = 1L << 60;
		for (int i = 0; i < n; i++) {
			ma = Math.max(ma, a[i][0]);
			mi = Math.min(mi, a[i][1]);
		}
		long res = 0;
		if (a[n - 1][0] == ma && a[n - 1][1] == mi) {
			for (int i = 0; i < n - 1; i++) {
				res = Math.max(res, a[i][1] - a[i][0] + 1);
			}
			res += mi - ma + 1;
		} else {
			boolean f = false;
			for (int i = 0; i < n - 1; i++) {
				if (!f) {
					if (a[i][0] == b[n - 1][0] && a[i][1] == b[n - 1][1]) {
						f = true;
					} else {
						res = Math.max(res, a[i][1] - a[i][0] + 1);
					}
				} else {
					res = Math.max(res, a[i][1] - a[i][0] + 1);
				}
			}
			res += Math.max(mi - ma + 1, 0);
			long l = 0, r = 1L << 60;
			ArrayList<long[]> li = new ArrayList<>();
			for (int i = 0; i < n; i++) {
				if (a[i][0] == ma) {
					r = Math.min(r, a[i][1]);
				} else if (a[i][1] == mi) {
					l = Math.max(l, a[i][0]);
				} else {
					li.add(a[i]);
				}
			}
			long cur = 1L << 60;
			for (int i = li.size() - 1; i >= 0; i--) {
				res = Math.max(res,
						Math.max(mi - Math.max(l, li.get(i)[0]) + 1, 0) + Math.max(Math.min(cur, r) - ma + 1, 0));
				cur = Math.min(cur, li.get(i)[1]);
			}
			res = Math.max(res, Math.max(mi - l + 1, 0) + Math.max(Math.min(cur, r) - ma + 1, 0));
		}
		out.println(res);
	}

	public static void main(String[] args) {
		ir = new InputReader(System.in);
		out = new PrintWriter(System.out);
		solve();
		out.flush();
	}

	static class InputReader {

		private InputStream in;
		private byte[] buffer = new byte[1024];
		private int curbuf;
		private int lenbuf;

		public InputReader(InputStream in) {
			this.in = in;
			this.curbuf = this.lenbuf = 0;
		}

		public boolean hasNextByte() {
			if (curbuf >= lenbuf) {
				curbuf = 0;
				try {
					lenbuf = in.read(buffer);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (lenbuf <= 0)
					return false;
			}
			return true;
		}

		private int readByte() {
			if (hasNextByte())
				return buffer[curbuf++];
			else
				return -1;
		}

		private boolean isSpaceChar(int c) {
			return !(c >= 33 && c <= 126);
		}

		private void skip() {
			while (hasNextByte() && isSpaceChar(buffer[curbuf]))
				curbuf++;
		}

		public boolean hasNext() {
			skip();
			return hasNextByte();
		}

		public String next() {
			if (!hasNext())
				throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while (!isSpaceChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}

		public int nextInt() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public long nextLong() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			long res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
