public void solve() {
	int num = ni();
	long range[][] = nl(num, 2);
	Arrays.sort(range, (a, b) -> Long.compare(a[1], b[1]));
	Arrays.sort(range, (a, b) -> Long.compare(a[0], b[0]));
	long left[][] = new long[2][num];
	left[0][0] = range[0][0];
	for(int i = 1; i < num; i ++) {
		left[0][i] = max(left[0][i - 1], range[i][0]);
	}
	left[1][num - 1] = range[num - 1][0];
	for(int i = num - 2; i >= 0; i --) {
		left[1][i] = max(left[1][i + 1], range[i][0]);
	}
	long right[][] = new long[2][num];
	right[0][0] = range[0][1];
	for(int i = 1; i < num; i ++) {
		right[0][i] = min(right[0][i - 1], range[i][1]);
	}
	right[1][num - 1] = range[num - 1][1];
	for(int i = num - 2; i >= 0; i --) {
		right[1][i] = min(right[1][i + 1], range[i][1]);
	}
	long max = 0;
	for(int i = 0; i < num - 1; i ++) {
		max = max(max, max(0, right[0][i] - left[0][i] + 1) + max(0, right[1][i + 1] - left[1][i + 1] + 1));
	}
	prtln(max);
