public class Main implements Runnable{

	private void solve(FastIO io) {
		/*
		 * author: 31536000
		 * AGC040 B問題
		 * 考察メモ
		 *えーと、まずコンテストにおいて全問正解する参加者は必ず連続する
		 *つまり、その区間が分かれば解ける！
		 *コンテスト1にて全問正解する参加者の区間を決める
		 *すると、その区間を持つ問題全てはコンテスト1に出すし、そうでない問題全ては2に出すのが最適
		 *つまり、この場合のやり方は一意に定まる
		 *そして、その判定を高速化できるか？
		 *まず、必ずその区間はある区間の左端～ある区間の右端、になる
		 * 区間をソートしておけば、pop-push形式で使える区間はO(N)でおｋ
		 * 問題は、その後の判定方法
		 * ところで、一番左端の区間について考える
		 * これをもしコンテスト1で採用しない場合、コンテスト2で採用されるが……
		 * コンテスト1の区間<コンテスト2の区間、としても一般性を失わなさそう
		 * そして、コンテスト1の区間とコンテスト2の区間は交わらない
		 * つまり、コンテスト2の区間が空(ゴミを押し付けたケース)以外では必ず左端の区間はコンテスト1に入る
		 * ということは、右端が最初に来る区間について、その範囲と一意に定まる
		 * つまり、コンテスト2も考えるなら答えは一発で求まる
		 * 右端が最も小さいコンテストと、その区間を含み左端が最も大きいコンテストまでの区間がコンテスト1の楽しさ
		 * そしてそれ以外がコンテスト2、これはまぁ計算できるね
		 *
		 * 次に、コンテスト2がわくわくコンテスト(注: 楽しさは0です)の場合
		 * これはコンテスト1だけを最大化すればよくて、って最大の区間長で終わりじゃねぇか！
		 *
		 */
		int N = io.nextInt();
		IntRange[] problem = new IntRange[N];
		for (int i = 0;i < N;++ i) {
			problem[i] = IntRange.closed(io.nextInt(), io.nextInt());
		}
		Arrays.sort(problem, (l, r) -> l.lower != r.lower ? Integer.compare(l.lower, r.lower) : Integer.compare(l.upper, r.upper));
		TreeMap<Integer, Integer> left = new TreeMap<>(), right = new TreeMap<>();
		for (int i = 0;i < N;++ i) {
			left.compute(problem[i].lower, (k, v) -> v == null ? 1 : v + 1);
			right.compute(problem[i].upper, (k, v) -> v == null ? 1 : v + 1);
		}
		int leftMax, rightMin;
		leftMax = problem[0].lower;
		rightMin = problem[0].upper;
		int ans = 0;
		for (int i = 0;i < N - 1;++ i) { // これは両方のコンテストで楽しい人が出た時
			leftMax = Math.max(leftMax, problem[i].lower);
			rightMin = Math.min(rightMin, problem[i].upper);
			int prob1 = Math.max(0, rightMin - leftMax + 1);
			left.compute(problem[i].lower, (k, v) -> v == 1 ? null : v - 1);
			right.compute(problem[i].upper, (k, v) -> v == 1 ? null : v - 1);
			int prob2 = Math.max(0, right.firstKey() - left.lastKey() + 1);
			ans = Math.max(ans, prob1 + prob2);
		}
		for (int i = 0;i < N;++ i) { // これは片方がわくわくコンテストの時
			ans = Math.max(ans, problem[i].getDistance());
		}
		io.println(ans);

	}

