	public static class AbstractArray<T> extends AbstractList<T> implements RandomAccess{

		private final Object[] array;

		public AbstractArray(int size) {
			array = new Object[size];
		}

		public AbstractArray(T[] array) {
			this(array.length);
			System.arraycopy(array, 0, this.array, 0, array.length);
		}

		@Override
		public T set(int index, T element) {
			T ret = get(index);
			array[index] = element;
			return ret;
		}

		@Override
		public T get(int index) {
			@SuppressWarnings("unchecked")
			T ret = (T)array[index];
			return ret;
		}

		public Object[] get() {
			return array;
		}

		public T[] get(T[] array) {
			if (array.length < this.array.length) {
				@SuppressWarnings("unchecked")
				T[] ret  = (T[])Arrays.copyOfRange(this.array, 0, this.array.length, array.getClass());
				return ret;
			}
			System.arraycopy(this.array, 0, array, 0, this.array.length);
			return array;
		}

		@Override
		public int size() {
			return array.length;
		}

		public int length() {
			return size();
		}

		@Override
		public int hashCode() {
			return Arrays.hashCode(array);
		}

		private class Iter implements Iterator<T> {
			private int index;

			private Iter() {
				index = 0;
			}

			@Override
			public boolean hasNext() {
				return index < array.length;
			}

			@Override
			public T next() {
				return get(index++);
			}

			@Override
			public void remove() {
				throw new UnsupportedOperationException();
			}
		}

		@Override
		public Iterator<T> iterator() {
			return new Iter();
		}
	}

	public static class Array<T> extends AbstractArray<T> implements Serializable{

		private static final long serialVersionUID = 2749604433067098063L;

		public Array(int size) {
			super(size);
		}

		public Array(T[] array) {
			super(array);
		}

		public T front() {
			return get(0);
		}

		public T back() {
			return get(size() - 1);
		}
	}
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Arrays;

public class Main {
	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		int n = Integer.parseInt(br.readLine());
		Obj[] arr = new Obj[n];
		for (int i = 0; i < n; i++) {
			String[] sa = br.readLine().split(" ");
			Obj o = new Obj();
			o.l = Integer.parseInt(sa[0]);
			o.r = Integer.parseInt(sa[1]);
			o.v = o.r - o.l + 1;
			arr[i] = o;
		}
		br.close();

		Obj maxV = new Obj();
		Obj minR = new Obj();
		minR.r = 1000000000;
		for (int i = 0; i < n; i++) {
			Obj o = arr[i];
			if (o.v > maxV.v) {
				maxV = o;
			}
			if (o.r < minR.r) {
				minR = o;
			}
		}

		Arrays.parallelSort(arr);
		Obj maxL = arr[0];
		int ans = maxV.v + Math.max(minR.r - maxL.l + 1, 0);
		if (maxL == minR) {
			System.out.println(ans);
			return;
		}

		int minr = maxL.r;
		for (int i = 1; i < n; i++) {
			Obj o = arr[i - 1];
			minr = Math.min(minr, o.r);
			int v1 = Math.max(minR.r - arr[i].l + 1, 0);
			int v2 = Math.max(minr - maxL.l + 1, 0);
			ans = Math.max(ans, v1 + v2);
		}
		System.out.println(ans);
	}

	static class Obj implements Comparable<Obj> {
		int l, r, v;

		@Override
		public int compareTo(Obj o) {
			if (l != o.l) {
				return o.l - l;
			}
			return o.r - r;
		}
	}
}

