public class Main {
    public static void main(String[] args) {
        StringBuilder out = new StringBuilder();
        solve(out);
        PrintWriter pw = new PrintWriter(System.out);
        pw.println(out);
        pw.flush();
        pw.close();
    }

    public static void solve(StringBuilder out) {
        int n = In.ni();
        int[] l = new int[n];
        int[] r = new int[n];
        for (int i = 0; i < n; i++) {
            l[i] = In.ni();
            r[i] = In.ni();
        }
        int[] p = IndexSort.sortDescending(l);
        int[] fm = new int[n + 1];
        fm[0] = Const.IINF;
        for (int i = 0; i < n; i++) {
            fm[i + 1] = Math.min(fm[i], r[p[i]]);
        }
        int[] bm = new int[n + 1];
        bm[n] = Const.IINF;
        for (int i = n - 1; i >= 0; i--) {
            bm[i] = Math.min(bm[i + 1], r[p[i]]);
        }
        int max = 0;
        int l1 = l[p[0]];
        for (int i = 1; i < n; i++) {
            int l2 = l[p[i]];
            int r1 = fm[i];
            int r2 = r[p[i]];
            int mr = bm[i + 1];
            int v1 = (r1 - l1 + 1) + Math.max(0, (Math.min(mr, r2) - l2 + 1));
            int v2 = Math.max(0, (Math.min(mr, r1) - l1 + 1)) + (r2 - l2 + 1);
            max = Math.max(max, Math.max(v1, v2));
        }
        out.append(max);
    }
}


