		int n = ni();
		int q[][] = new int[n][2];
		for(int i=0;i<n;i++) {
			int l = ni(), r = ni();
			q[i][0] = l; q[i][1] = r;
		}
		Arrays.sort(q, (q1, q2)->q1[1]-q2[1]);//rでソート
		int maxL[] = new int[n+1];
		int rmaxL[] = new int[n+1];
		for(int i=0;i<n;i++) {
			int l = q[i][0];
			maxL[i+1] = max(maxL[i], l);
		}
		for(int i=n-1;i>=0;i--) {
			int l = q[i][0];
			rmaxL[i] = max(rmaxL[i+1], l);
		}
		long ans = 0;
		for(int i=0;i<n;i++) {//先のコンテストのrの値で全探索
			int l1 = q[i][0], r1 = q[i][1];
