			int l3Max = rmaxL[i];//i+1~n-1番目までの最大l

			if(l1<l2Max) {
				l2Max = max(l2Max, l3Max);
			}
			else {
				l1 = max(l1, l3Max);
			}

			long r2Min = q[0][1];
			if(i==0)r2Min = q[0][1];

