				l2 = max(l2, lMax);
			}
			else {
				l1 = max(l1, lMax);
			}

			long res = 0;
			if(r2 - l2 >= 0) res += (r2 - l2 + 1);
			if(r1 - l1 >= 0) res += (r1 - l1 + 1);
			ans = max(ans, res);
		}

