	static void solve() {
		int n = ni();
		int q[][] = new int[n][2];
		for(int i=0;i<n;i++) {
			int l = ni(), r = ni();
			q[i][0] = l; q[i][1] = r;
		}
		Arrays.sort(q, (q1, q2)->q1[1]-q2[1]);//rでソート
		int maxL[] = new int[n+1];
		int rmaxL[] = new int[n+1];
		for(int i=0;i<n;i++) {
			int l = q[i][0];
			maxL[i+1] = max(maxL[i], l);
		}
		for(int i=n-1;i>=0;i--) {
			int l = q[i][0];
			rmaxL[i] = max(rmaxL[i+1], l);
		}
		long ans = 0;
		for(int i=0;i<n;i++) {//先のコンテストのrの値で全探索
			int l1 = q[i][0], r1 = q[i][1];
			//rがr1より小さいものは、全て後のコンテストに寄せる
			int l2Max = maxL[i];//i-1番目までの最大l
			//rがr1より大きいものは、全てlが大きい方のコンテストに寄せる
			int l3Max = rmaxL[i+1];//i+1~n-1番目までの最大l

			if(l1<l2Max) {
				l2Max = max(l2Max, l3Max);
			}
			else {
				l1 = max(l1, l3Max);
			}

			long r2Min = q[0][1];
			if(i==0)r2Min = q[0][1];

			long res = 0;
			if(r2Min - l2Max >= 0) res += (r2Min - l2Max +1);
			if(r1 - l1 >= 0) res += (r1 - l1 + 1);
			ans = max(ans, res);
		}
		out.println(ans);
	}

