            sum41[i] = r41 - l41 + 1;
        }

        long[] sum31 = new long[N];
        long l31 = in[N-1].l;
        long r31 = in[N-1].r;
        sum31[N-1] = r31 - l31 + 1;
        for (int i = N-2; i >= 0; i--) {
            long li = in[i].l;
            long ri = in[i].r;
            if (ri < l31 || r31 < li)
                break;

            if (l31 < li)
                l31 = li;

            if (ri < r31)
                r31 = ri;

            sum31[i] = r31 - l31 + 1;
        }

        for (int i = 0; i < N-1; i++) {
            ans = Math.max(sum31[i] + sum41[i+1], ans);
        }

        System.out.println(ans);
    }
    static class In {
        long l;
        long r;
        In(long l, long r) {
            this.l = l;
            this.r = r;
        }
        long diff() {return r - l;};
        @Override
        public String toString() {
            return "(" + l + ", " + r + ")";
        }
    }

    public static long sum(int[] L, int[] R, int exceptIdx) {
        int l = 0;
        int r = (int) 1E9 + 1;

        for (int i = 0; i < L.length; i++) {
            if (i == exceptIdx)
                continue;

            if (R[i] < l || r < L[i])
                return 0;

            if (l < L[i])
                l = L[i];

            if (R[i] < r)
                r = R[i];
        }
        return r - l + 1;
    }

