/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author anand.oza
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        BTwoContests solver = new BTwoContests();
        solver.solve(1, in, out);
        out.close();
    }

    static class BTwoContests {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            Pair<Integer, Integer>[] problems = new Pair[n];
            for (int i = 0; i < n; i++) {
                problems[i] = Pair.of(in.nextInt(), in.nextInt() + 1);
            }

            Arrays.sort(problems, Comparator.comparingInt((Pair<Integer, Integer> p) -> p.first).thenComparingInt(p -> -p.second));
            IntMinSparseTable min = new IntMinSparseTable(n);
            for (int i = 0; i < n; i++) {
                min.update_LAZY(i, problems[i].second);
            }
            min.rebuild();

            long answer = 0;
            for (int i = 1; i < n; i++) {
                long candidate = min.query(0, i) - problems[i - 1].first;
                candidate += min.query(i, n) - problems[n - 1].first;

                //System.out.println(i + " " + candidate + " " + (min.query(0, i) - problems[i - 1].first) + " " + (min.query(i, n) - problems[n - 1].first));
                answer = Math.max(answer, candidate);
            }

            // Just have 1 good contest and give up on the other.
            for (int i = 0; i < n; i++) {
                answer = Math.max(answer, problems[i].second - problems[i].first + 1);
            }

            out.println(answer);
        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }

    static class Pair<F, S> {
        public final F first;
        public final S second;

        public Pair(F first, S second) {
            this.first = first;
            this.second = second;
        }

        public static <F, S> Pair<F, S> of(F first, S second) {
            return new Pair<>(first, second);
        }

        public boolean equals(Object o) {
            if (this == o)
                return true;
            if (o == null || getClass() != o.getClass())
                return false;
            Pair<?, ?> pair = (Pair<?, ?>) o;
            return Objects.equals(first, pair.first) && Objects.equals(second, pair.second);
        }

        public int hashCode() {
            return Objects.hash(first, second);
        }

        public String toString() {
            return "(" + first + ", " + second + ')';
        }

    }

    static class Util {
        public static void ASSERT(boolean assertion) {
            if (!assertion)
                throw new AssertionError();
        }

    }

    static class IntMinSparseTable {
        public int size;
        public int[] table;
        private int maxLength;

        public IntMinSparseTable(int[] array) {
            this.size = array.length;

            maxLength = 1 + Integer.numberOfTrailingZeros(Integer.highestOneBit(Math.max(size - 1, 1)));
            table = new int[maxLength * size];
            System.arraycopy(array, 0, table, 0, size);

            rebuild();
        }

        public IntMinSparseTable(int size) {
            this.size = size;

            maxLength = 1 + Integer.numberOfTrailingZeros(Integer.highestOneBit(Math.max(size - 1, 1)));
            table = new int[maxLength * size];
        }

        public void rebuild() {
            for (int l = 0; l + 1 < maxLength; l++) {
                for (int i = 0; i < size; i++) {
                    table[index(l + 1, i)] = table[index(l, i)];
                    if (i + (1 << l) < size) {
                        table[index(l + 1, i)] = Math.min(table[index(l + 1, i)], table[index(l, i + (1 << l))]);
                    }
                }
            }
        }

        public void update_LAZY(int i, int v) {
            table[i] = v;
        }

        private int index(int length, int start) {
            return length * size + start;
        }

        public int query(int i, int j) {
            Util.ASSERT(0 <= i && i < j && j <= size);
            int length = j - i - 1;
            int l = length == 0 ? 0 : Integer.numberOfTrailingZeros(Integer.highestOneBit(length));
            int left = table[index(l, i)];
            int right = table[index(l, j - (1 << l))];
            return Math.min(left, right);
        }

    }
}

import java.util.*;

public class Main {

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        Problem[] problems = new Problem[n];
        for (int j = 0; j < n; j++) {
            int l = in.nextInt();
            int r = in.nextInt();
            problems[j] = new Problem(l, r);
        }
        Arrays.sort(problems);
        List<Problem> remProblems = new ArrayList<>(n);
        int maxL = 0;
        for (Problem problem : problems) {
            if (problem.l > maxL) {
                maxL = problem.l;
                remProblems.add(problem);
            }
        }
        if (remProblems.size() == 1) {
            Problem soleProblem = remProblems.get(0);
            int answer = 0;
            for (Problem problem : problems) {
                if (problem != soleProblem) {
                    answer = Math.max(answer, problem.r - problem.l + 1);
                }
            }
            answer += soleProblem.r - soleProblem.l + 1;
            System.out.println(answer);
            return;
        }
        PriorityQueue<Integer> maxL2 = new PriorityQueue<>(Comparator.reverseOrder());
        PriorityQueue<Integer> minR2 = new PriorityQueue<>();
        for (Problem problem : remProblems) {
            maxL2.add(problem.l);
            minR2.add(problem.r);
        }
        int maxL1 = remProblems.get(0).l;
        int minR1 = remProblems.get(0).r;
        maxL2.remove(maxL1);
        minR2.remove(minR1);
        int answer = minR1 - maxL1 + 1 + Math.max(0, minR2.peek() - maxL2.peek() + 1);
        for (int j = 1; j < remProblems.size() - 1; j++) {
            Problem problem = remProblems.get(j);
            maxL2.remove(problem.l);
            minR2.remove(problem.r);
            maxL1 = problem.l;
            answer = Math.max(answer, Math.max(0, minR1 - maxL1 + 1) + Math.max(0, minR2.peek() - maxL2.peek() + 1));
        }
        System.out.println(answer);
    }

    static class Problem implements Comparable<Problem> {
        final int l;
        final int r;

        Problem(int l, int r) {
            this.l = l;
            this.r = r;
        }

        @Override
        public int compareTo(Problem o) {
            if (r != o.r) {
                return r - o.r;
            } else {
                return l - o.l;
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        final FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        int N = fs.nextInt();
        List<Pair<Long, Long>> lr = new ArrayList<>(N);
        for (int i = 0; i < N; i++) {
            lr.add(new Pair(fs.nextLong(), fs.nextLong()));
        }
        long max = 0;
        Collections.sort(lr, (p1, p2) -> (int) ((-(p1.s - p1.f) + (p2.s - p2.f))));
        Random rand = new Random();
        max = Math.max(max, getMax(lr, rand));
        out.println(max);
        out.flush();
    }

    public static long getMax(List<Pair<Long, Long>> lr, Random rand) {
        long aLeft = lr.get(0).f;
        long aRight = lr.get(0).s;
        long max = 0;

        for (int a = 1; a < Math.min(lr.size(), 750); a++) {
            int pickedIndex = a;
            if (pickedIndex > 1) {
                pickedIndex = rand.nextInt(lr.size() - 1);
            }
            long bLeft = lr.get(pickedIndex).f;
            long bRight = lr.get(pickedIndex).s;

            for (int i = 1; i < lr.size(); i++) {
                if (i == pickedIndex) {
                    continue;
                }

                // what if putting to a
                long li = lr.get(i).f;
                long ri = lr.get(i).s;
                long newALeft = Math.max(aLeft, li);
                long newARight = Math.min(aRight, ri);
                long scoreA = (newARight - newALeft) + (bRight - bLeft) + 2;

                long newBLeft = Math.max(bLeft, li);
                long newBRight = Math.min(bRight, ri);
                long scoreB = (aRight - aLeft) + (newBRight - newBLeft) + 2;

                if (scoreA == scoreB) {
                    if (rand.nextInt() % 2 ==0) {
                        aLeft = newALeft;
                        aRight = newARight;
                    } else {
                        bLeft = newBLeft;
                        bRight = newBRight;
                    }
                    continue;
                }

                if (scoreA > scoreB) {
                    aLeft = newALeft;
                    aRight = newARight;
                } else {
                    bLeft = newBLeft;
                    bRight = newBRight;
                }
            }

            max = Math.max(max, (aRight - aLeft) + (bRight - bLeft) + 2);
        }
        return max;
    }


    static class Pair<F extends Comparable<F>, S extends Comparable<S>> implements Comparable<Pair<F, S>> {
        F f;
        S s;

        Pair() {
        }

        Pair(F f, S s) {
            this.f = f;
            this.s = s;
        }

        Pair(Pair<F, S> p) {
            f = p.f;
            s = p.s;
        }

        @Override
        public int compareTo(Pair<F, S> p) {
            if (f.compareTo(p.f) != 0) {
                return f.compareTo(p.f);
            }
            return s.compareTo(p.s);
        }

        @Override
        public int hashCode() {
            return f.hashCode() ^ s.hashCode();
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) {
                return true;
            }
            if (o == null || this.f == null || this.s == null) {
                return false;
            }
            if (this.getClass() != o.getClass()) {
                return false;
            }
            Pair p = (Pair) o;
            return this.f.equals(p.f) && this.s.equals(p.s);
        }

        @Override
        public String toString() {
            return "{" + f.toString() + ", " + s.toString() + "}";
        }
    }

}


class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;

    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        } else {
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }

    private int readByte() {
        if (hasNextByte()) return buffer[ptr++];
        else return -1;
    }

    private boolean isPrintableChar(int c) {
        return 33 <= c && c <= 126;
    }

    public boolean hasNext() {
        while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
        return hasNextByte();
    }

    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while (isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) {
            throw new NumberFormatException();
        }
        while (true) {
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            } else if (b == -1 || !isPrintableChar(b)) {
                return minus ? -n : n;
            } else {
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }

    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
        return (int) nl;
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;
import java.io.IOException;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        ProblemB_TwoContests solver = new ProblemB_TwoContests();
        solver.solve(1, in, out);
        out.close();
    }

    static class ProblemB_TwoContests {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            Segment[] s = new Segment[n];
            for (int i = 0; i < n; i++) {
                int l = in.nextInt();
                int r = in.nextInt();
                s[i] = new Segment(l, r);
            }
            int ans = solve(s);
            for (Segment seg : s) {
                seg.reflect();
            }
            ans = Math.max(ans, solve(s));
            out.println(ans);
        }

        private int solve(Segment[] s) {
            int n = s.length;
            Arrays.sort(s);
            Segment[] pref = new Segment[n];
            for (int i = 0; i < n; i++) {
                pref[i] = s[i];
                if (i > 0) {
                    pref[i] = intersect(pref[i], pref[i - 1]);
                }
            }
            Segment[] suff = new Segment[n];
            for (int i = n - 1; i >= 0; i--) {
                suff[i] = s[i];
                if (i + 1 < n) {
                    suff[i] = intersect(suff[i], suff[i + 1]);
                }
            }

            int min = Integer.MAX_VALUE;
            int max = Integer.MIN_VALUE;
            for (Segment seg : s) {
                min = Math.min(min, seg.l);
                min = Math.min(min, seg.r);
                max = Math.max(max, seg.l);
                max = Math.max(max, seg.r);
            }

            int res = 0;
            final int N = (int) 1e9;
            for (int i = 0; i < n; i++) {
                Segment o = new Segment(min, max);
                if (i + 1 < n) {
                    o = intersect(o, suff[i + 1]);
                    res = Math.max(res, pref[i].length() + o.length());
                }
                if (i > 0) {
                    o = intersect(o, pref[i - 1]);
                }
                res = Math.max(res, s[i].length() + o.length());
            }
            return res;
        }

        Segment intersect(Segment a, Segment b) {
            return new Segment(Math.max(a.l, b.l), Math.min(a.r, b.r));
        }

        class Segment implements Comparable<Segment> {
            int l;
            int r;

            Segment(int l, int r) {
                this.l = l;
                this.r = r;
            }

            int length() {
                return Math.max(0, r - l + 1);
            }

            public int compareTo(Segment o) {
                if (l != o.l) {
                    return l < o.l ? -1 : 1;
                }
//            if (r != o.r) {
//                return r < o.r ? -1 : 1;
//            }
                return 0;
            }

            public void reflect() {
                int nl = -r;
                int nr = -l;
                l = nl;
                r = nr;
            }

        }

    }

    static class FastScanner {
        private BufferedReader in;
        private StringTokenizer st;

        public FastScanner(InputStream stream) {
            in = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String rl = in.readLine();
                    if (rl == null) {
                        return null;
                    }
                    st = new StringTokenizer(rl);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.util.*;

public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int L[] = new int[N];
		int R[] = new int[N];

		ArrayList<int[]> q = new ArrayList<int[]>(); 

		for(int i=0;i<N;i++){
			L[i]=sc.nextInt();
			R[i]=sc.nextInt();
			int tmp[] = {L[i],R[i]};
			q.add(tmp);
		}

		//リストを削るので、最初の状態をメモしておく。
		ArrayList<int[]> qmemo = (ArrayList<int[]>)q.clone();

		//左端最大の区間と、右端最小の区間を同じコンテストに出題するとき

		//左端で降順にソート
		Collections.sort(q,(q1,q2)->q2[0]-q1[0]);
		int lmax[] = q.get(0);
		//右端で昇順にソート
		Collections.sort(q,(q1,q2)->q1[1]-q2[1]);
		int rmin[] = q.get(0);
		//幅で降順にソート
		Collections.sort(q,(q1,q2)->(q2[1]-q2[0])-(q1[1]-q1[0]));
		int wmax[] = q.get(0);
		int k=0;
		while(wmax==lmax|wmax==rmin){
			k++;
			wmax = q.get(k);
		}
		long ans = Math.max((rmin[1]-lmax[0]+1),0) + (wmax[1]-wmax[0]+1);


		//左端最大の区間と、右端最小の区間が異なるコンテストに出題するとき
		//左端で降順にソート
		Collections.sort(q,(q1,q2)->q2[0]-q1[0]);
		int rmin_memo = Integer.MAX_VALUE;
		int tmp_ans=0;
		for(int i=1;i<N;i++){
			int tmp[] = q.get(i);

			if(i==1) rmin_memo = lmax[1] ;
			else{
				rmin_memo = Math.min(rmin_memo, q.get(i-1)[1]);
			}

			tmp_ans = Math.max((rmin[1]-tmp[0]+1),0) + Math.max((rmin_memo-lmax[0]+1),0);
			ans = Math.max(ans,tmp_ans);
 		}	
		System.out.println(ans);
	}
}

