  private static long solve(int[][] p) {
    int n = p.length;
    Arrays.sort(p, (o1, o2) -> o1[0] == o2[0] ? o1[1] - o2[1] : o1[0] - o2[0]);

    long[] l2 = new long[n + 1];
    long[] r2 = new long[n + 1];

