    r2[n] = Integer.MAX_VALUE;

    long ret = 0;
    for (int i = n - 1; i >= 1; i--) {
      l2[i] = Math.max(l2[i + 1], p[i][0]);
      r2[i] = Math.min(r2[i + 1], p[i][1]);
    }

    long[] l1 = new long[n + 1];
    long[] r1 = new long[n + 1];
    l1[0] = 0;
    r1[0] = Integer.MAX_VALUE;

    for (int i = 1; i <= n - 1; i++) {
      l1[i] = Math.max(l1[i - 1], p[i - 1][0]);
      r1[i] = Math.min(r1[i - 1], p[i - 1][1]);

      long cnt = Math.max(0, (r1[i] - l1[i] + 1)) + Math.max(0, (r2[i] - l2[i] + 1));
      ret = Math.max(ret, cnt);
    }


    for (int i = 0; i < n; i++) {
      long l;
      long r;
      if (i == 0) {
        l = l2[i + 1];
        r = r2[i + 1];
      } else if (i == n - 1) {
        l = l1[i];
        r = r1[i];
      } else {
        l = Math.max(l1[i], l2[i + 1]);
        r = Math.min(r1[i], r2[i + 1]);
      }

      long cnt = Math.max(0, (r - l + 1)) + (p[i][1] - p[i][0] + 1);
