        OutputWriter out = new OutputWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int N = in.nextInt();
            Point point[] = new Point[N];
            int ans = 0;
            int index = -1;
            for (int i = 0; i < N; i++) {
                point[i] = new Point(in.nextInt(), in.nextInt(), i);
                if (point[i].size > ans) {
                    ans = point[i].size;
                    index = i;
                }
            }
            int ll = 1;
            int rr = (int) 1e9;
            for (int i = 0; i < N; i++) {
                if (index != i) {
                    rr = Math.min(rr, point[i].right);
                    ll = Math.max(ll, point[i].left);
                }
            }
            ans += Math.max(0, rr - ll + 1);
            Arrays.sort(point, new Comparator<Point>() {

                public int compare(Point o1, Point o2) {
                    if (o1.left != o2.left) {
                        return Integer.compare(o1.left, o2.left);
                    } else if (o1.right != o2.right) {
                        return Integer.compare(o1.right, o2.right);
                    }
                    return Integer.compare(o1.index, o2.index);
                }
            });
            int overlapA[] = new int[N];
            int overlapB[] = new int[N];
            int left = point[0].left, right = point[0].right;
            for (int i = 0; i < N; i++) {
                left = Math.max(left, point[i].left);
                right = Math.min(right, point[i].right);
                overlapA[i] = Math.max(0, right - left + 1);
            }
            left = point[N - 1].left;
            right = point[N - 1].right;
            for (int i = N - 1; i >= 0; i--) {
                left = Math.max(left, point[i].left);
                right = Math.min(right, point[i].right);
                overlapB[i] = Math.max(0, right - left + 1);
            }
            for (int i = 0; i < N - 1; i++) {
                ans = Math.max(ans, overlapA[i] + overlapB[i + 1]);
            }
            out.printLine(ans);

        }

        class Point {
            int left;
            int right;
            int size;
            int index;

            public Point(int left, int right, int index) {
                this.left = left;
                this.right = right;
                this.size = right - left + 1;
                this.index = index;
            }

        }

    }

    static class OutputWriter {
        PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void printLine(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.close();
        }

    }

