            }
             */
            if (scoreA > scoreB) {
                aLeft = newALeft;
                aRight = newARight;
            } else {
                bLeft = newBLeft;
                bRight = newBRight;
            }
        }
        long local = Math.max((aRight - aLeft + 1), 0) + Math.max((bRight - bLeft + 1), 0);
