    public static long getMax(List<Pair<Long, Long>> lr) {
        long aLeft = lr.get(0).f;
        long aRight = lr.get(0).s;
        long max = 0;

        int pickedIndex = 1;
        long bLeft = lr.get(pickedIndex).f;
        long bRight = lr.get(pickedIndex).s;
        for (int i = 1; i < lr.size(); i++) {
            if (i == pickedIndex) {
                continue;
            }

            long li = lr.get(i).f;
            long ri = lr.get(i).s;
            long newALeft = Math.max(aLeft, li);
            long newARight = Math.min(aRight, ri);
            long scoreA = Math.max((newARight - newALeft + 1), 0) + Math.max((bRight - bLeft + 1), 0);
            long newBLeft = Math.max(bLeft, li);
            long newBRight = Math.min(bRight, ri);
            long scoreB = Math.max((aRight - aLeft + 1), 0) + Math.max((newBRight - newBLeft + 1) , 0);

            /*
            if ((newARight - newALeft + 1) <= 0 && (newBRight - newBLeft + 1) <= 0) {
                break;
            }
             */
            if (scoreA > scoreB) {
                aLeft = newALeft;
                aRight = newARight;
            } else {
                bLeft = newBLeft;
                bRight = newBRight;
            }
        }
        long local = Math.max((aRight - aLeft + 1), 0) + Math.max((bRight - bLeft + 1), 0);
        max = Math.max(local, max);

        long minCommonRange = Long.MAX_VALUE;
        for (int i = 1; i < lr.size(); i++) {
            long li = lr.get(i).f;
            long ri = lr.get(i).s;
            long newALeft = Math.max(aLeft, li);
            long newARight = Math.min(aRight, ri);
            long range = newARight - newALeft;
            if (range < minCommonRange) {
                pickedIndex = i;
                minCommonRange = range;
            }
        }
        bLeft = lr.get(pickedIndex).f;
        bRight = lr.get(pickedIndex).s;

        for (int i = 1; i < lr.size(); i++) {
            if (i == pickedIndex) {
                continue;
            }

            long li = lr.get(i).f;
            long ri = lr.get(i).s;
            long newALeft = Math.max(aLeft, li);
            long newARight = Math.min(aRight, ri);
            long scoreA = Math.max((newARight - newALeft + 1), 0) + Math.max((bRight - bLeft + 1), 0);
            long newBLeft = Math.max(bLeft, li);
            long newBRight = Math.min(bRight, ri);
            long scoreB = Math.max((aRight - aLeft + 1), 0) + Math.max((newBRight - newBLeft + 1) , 0);

            /*
            if ((newARight - newALeft + 1) <= 0 && (newBRight - newBLeft + 1) <= 0) {
                break;
            }
             */
            if (scoreA > scoreB) {
                aLeft = newALeft;
                aRight = newARight;
            } else {
                bLeft = newBLeft;
                bRight = newBRight;
            }
        }
        local = Math.max((aRight - aLeft + 1), 0) + Math.max((bRight - bLeft + 1), 0);
        max = Math.max(local, max);

        return max;
    }





