  public static int rangeReduction(int l, int r, int i, int j) {
    if(i < l) {
      if(j < l) {
        return (r - l + 1);
      }
      else if(j >= l && j <= r){
        return (r - j);
      }
      else {
        return 0;
      }
    }
    else if(i >= l && i <= r) {
      if(j <= r) {
        return (r - l + 1) - (j - i + 1);
      }
      else {
        return (i - l);
      }
    }
    else {
      return (r - l + 1);
    }
  }

