import java.util.stream.IntStream;

public class Main {
    static final Scanner sc  = new Scanner(System.in);
    static final int     MOD = (int) 1E9 + 7;

    public static void main(String[] args) {
        int N = nint();
        In[] in = new In[N];

        for (int i = 0; i < N; i++) {
            in[i] = new In(nint(), nint());
        }
        Arrays.sort(in, (a, b) -> Long.compare(a.l, b.l));

        long[] sum1 = new long[N];
        long l1 = in[0].l;
        long r1 = in[0].r;
        sum1[0] = r1 - l1 + 1;
        for (int i = 1; i < N; i++) {
            long li = in[i].l;
            long ri = in[i].r;
            if (ri < l1 || r1 < li)
                break;

            if (l1 < li)
                l1 = li;

            if (ri < r1)
                r1 = ri;

            sum1[i] = r1 - l1 + 1;
        }

        long[] sum2 = new long[N];
        long l2 = in[N-1].l;
        long r2 = in[N-1].r;
        sum2[N-1] = r2 - l2 + 1;
        for (int i = N-2; i >= 0; i--) {
            long li = in[i].l;
            long ri = in[i].r;
            if (ri < l2 || r2 < li)
                break;

            if (l2 < li)
                l2 = li;

            if (ri < r2)
                r2 = ri;

            sum2[i] = r2 - l2 + 1;
        }

        long ans = 0;
        for (int i = 0; i < N-1; i++) {
            ans = Math.max(sum1[i] + sum2[i+1], ans);
        }

        int maxDiff = Arrays.stream(in).map(In::diff).max(Integer::compare).get();
        int maxI = IntStream.range(0, N).reduce((i1, i2) -> in[i1].diff() < in[i2].diff() ? i2 : i1).getAsInt();
        ans = Math.max(ans, maxDiff + sum(in, maxI));

        System.out.println(ans);
    }
    static class In {
        int l;
        int r;
        In(int l, int r) {
            this.l = l;
            this.r = r;
        }
        int diff() {return r - l;};
        int sum() {return r + l;};
        @Override
        public String toString() {
            return "(" + l + ", " + r + ")";
        }
    }

    public static long sum(In[] in, int exceptIdx) {
        int l = 0;
        int r = (int) 1E9 + 1;

        for (int i = 0; i < in.length; i++) {
            if (i == exceptIdx)
                continue;

            int li = in[i].l;
            int ri = in[i].r;

            if (ri < l || r < li)
                return 0;

            if (l < li)
                l = li;

            if (ri < r)
                r = ri;
        }
        return r - l + 1;
    }

    private static long sumN(int n) {
        return (long) n * (n+1) / 2;
    }

