    public static void main(String[] args) {
        final FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        int N = fs.nextInt();
        List<Pair<Long, Long>> lr = new ArrayList<>(N);
        for (int i = 0; i < N; i++) {
            lr.add(new Pair(fs.nextLong(), fs.nextLong()));
        }

        long max = 0;
        Collections.sort(lr, (p1, p2) -> (int) ((-(p1.s - p1.f) + (p2.s - p2.f))));
        max = Math.max(max, getMax(lr));
        out.println(max);
        out.flush();
    }

    public static long getMax(List<Pair<Long, Long>> lr) {
        long aLeft = lr.get(0).f;
        long aRight = lr.get(0).s;
        long max = 0;

        for (int a = 1; a < Math.min(lr.size(), 1000); a++) {
            int pickedIndex = a;
            long bLeft = lr.get(pickedIndex).f;
            long bRight = lr.get(pickedIndex).s;

            for (int i = 1; i < lr.size(); i++) {
                if (i == pickedIndex) {
                    continue;
                }

                long li = lr.get(i).f;
                long ri = lr.get(i).s;
                long newALeft = Math.max(aLeft, li);
                long newARight = Math.min(aRight, ri);
                long scoreA = Math.max((newARight - newALeft + 1), 0) + Math.max((bRight - bLeft + 1), 0);

                long newBLeft = Math.max(bLeft, li);
                long newBRight = Math.min(bRight, ri);
                long scoreB = Math.max((aRight - aLeft + 1), 0) + Math.max((newBRight - newBLeft + 1) , 0);

                if (scoreA >= scoreB) {
                    aLeft = newALeft;
                    aRight = newARight;
                } else {
                    bLeft = newBLeft;
                    bRight = newBRight;
                }
            }
            long local = Math.max((aRight - aLeft + 1), 0) + Math.max((bRight - bLeft + 1), 0);
            max = Math.max(local, max);
        }

        return max;
    }





    static void debug(Object... os) {
        System.err.println(Arrays.deepToString(os));
    }

    // Execute func for all patterns can be represented with n bit.
    // O(n2^n)
    static void forAllBit(int n, Consumer<List<Boolean>> func) {
        for (int i = 0; i < (1 << n); i++) {
            List<Boolean> arg = new ArrayList();
            for (int j = 0; j < n; j++) {
                boolean isJthBitSet = ((i >> j) & 1) == 1;
                arg.add(isJthBitSet);
            }
            func.accept(arg);
        }
    }

    static class Pair<F extends Comparable<F>, S extends Comparable<S>> implements Comparable<Pair<F, S>> {
