	static void solve()
	{
		// maxL , minR
		// それ以外のうち最長を選ぶ
		// other
		// maxL minRk  maxLd minR
		int n = ni();
		int[][] lr = new int[n][];
		for(int i = 0;i < n;i++){
			lr[i] = na(2);
		}
		int maxl = -1;
		int minr = 1999999999;
		for(int[] u : lr){
			maxl = Math.max(maxl, u[0]);
			minr = Math.min(minr, u[1]);
		}

		Arrays.sort(lr, new Comparator<int[]>() {
			public int compare(int[] a, int[] b) {
				return a[1] - b[1];
			}
		});

		int lmaxd = lr[0][0];
		int ans = 0;
		for(int i = 1;i < n;i++){
