//			tr(ans, d(lmaxd, minr), d(maxl, lr[i][1]));
		}

		int maxlen = 0;
		for(int i = 0;i < n;i++){
			maxlen = Math.max(maxlen, lr[i][1] - lr[i][0] + 1);
		}
		ans = Math.max(d(maxl, minr) + maxlen, ans);
		out.println(ans);
	}

	static int d(int l, int r)
	{
		return Math.max(r-l+1, 0);
	}

