import java.io.PrintStream;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

public class Main {
	static final PrintStream out = System.out;
	static final Scanner sc = new Scanner(System.in);
	static final long Mod = 1000_000_007L;
	int N,M;

	public static void main(String[] args) {
		Main main = new Main();
		main.solve();
		System.exit(0);
	}

	void solve() {
		N = nextInt();
		long [][]LR = new long [N][3];
		long [][]l=new long[N][2],r=new long[N][2];
		for(int i=0;i<N;i++) {
			LR[i][0]=nextLong();
			LR[i][1]=nextLong();
			LR[i][2]=LR[i][1]-LR[i][0]+1;
			l[i][0] = LR[i][0];
			r[i][0] = LR[i][1];
			l[i][1] = i;
			r[i][1] = i;
		}
		Arrays.sort(l,(a1,a2)->Long.compare(a2[0],a1[0]));
		Arrays.sort(r,(a1,a2)->Long.compare(a1[0],a2[0]));

		long []onesum = new long[N];
		for(int i=0;i<N;i++) {
			long L = l[0][0];
			long R = r[0][0];
			if(l[0][1]==i)L = l[1][0];
			if(r[0][1]==i)R = r[1][0];
			long abs = R-L+1;
			if(abs <= 0)abs = 0;
			onesum[i]=LR[i][2]+abs;
		}
		Arrays.sort(onesum);

		Arrays.sort(LR,(a1,a2)->MyComparator(a1[0],a2[0],a1[1],a2[1]));
		//Arrays.sort(LR,(a1,a2)->absComp(a1[0],a2[0],a1[1],a2[1]));
		long L = LR[0][0];
		long R = LR[0][1];
		long Abs = R - L + 1;
		long []lrA = new long[N];
		lrA[0] = Abs;
		for(int i=1;i<N-1;i++) {
			L=Math.max(L,LR[i][0]);
			R=Math.min(R,LR[i][1]);
			long abs = R-L+1;
			if(abs <= 0)break;
			lrA[i] = abs;
		}
		long [] lrB = new long [N];
		L = LR[N-1][0];
		R = LR[N-1][1];
		for(int i=N-1;i>0;i--) {
			L=Math.max(L,LR[i][0]);
			R=Math.min(R,LR[i][1]);
			long abs = R-L+1;
			if(abs <= 0)break;
			lrB[i] = abs;
		}

		long max = onesum[N-1];
		for(int i=0;i<N-1;i++) {
			max = Math.max(max, lrA[i]+lrB[i+1]);
		}
		out.println(max);

	}


	private int absComp(long a1, long a2, long b1, long b2) {
		if(b1 - a1 < b2 - a2)return 1;
		if(b1 - a1 > b2 - a2)return -1;
		return 0;
	}

	private int MyComparator(long a1, long a2, long b1, long b2) {
		if(b1 - a1 < b2 - a2)return 1;
		if(b1 - a1 > b2 - a2)return -1;
		if(a1 > a2) return 1;
		else if(a1 < a2) return -1;
		if(b1 > b2) return 1;
		else if(b1 < b2) return -1;
		return 0;
	}


	public int[] nextIntArray(int n) {
		int[] a = new int[n];
		for (int i = 0; i < n; i++)a[i] = nextInt();
		return a;
	}
	public long[] nextLongArray(int n) {
		long[] a = new long[n];
		for (int i = 0; i < n; i++)a[i] = nextLong();
		return a;
	}
	public int nextInt() {
		return Integer.parseInt(next());
	}
	public long nextLong() {
		return Long.parseLong(next());
	}
	public String next() {
		return sc.next();
	}

	long gcd(long m,long n) {
		if (m<n) return gcd(n,m);
		if (n==0)return m;
		return gcd(n,m%n);
	}
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        final FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        int N = fs.nextInt();
        List<Pair<Long, Long>> lr = new ArrayList<>(N);
        for (int i = 0; i < N; i++) {
            lr.add(new Pair(fs.nextLong(), fs.nextLong()));
        }
        long max = 0;
        Collections.sort(lr, (p1, p2) -> (int) ((-(p1.s - p1.f) + (p2.s - p2.f))));
        Random rand = new Random();
        max = Math.max(max, getMax(lr, rand));
        out.println(max);
        out.flush();
    }

    public static long getMax(List<Pair<Long, Long>> lr, Random rand) {
        long aLeft = lr.get(0).f;
        long aRight = lr.get(0).s;
        long max = 0;

        for (int a = 1; a < Math.min(lr.size(), 1000); a++) {
            int pickedIndex = a;
            if (pickedIndex > 1) {
                pickedIndex = rand.nextInt(lr.size() - 1);
            }
            long bLeft = lr.get(pickedIndex).f;
            long bRight = lr.get(pickedIndex).s;

            for (int i = 1; i < lr.size(); i++) {
                if (i == pickedIndex) {
                    continue;
                }

                // what if putting to a
                long li = lr.get(i).f;
                long ri = lr.get(i).s;
                long newALeft = Math.max(aLeft, li);
                long newARight = Math.min(aRight, ri);
                long scoreA = (newARight - newALeft) + (bRight - bLeft) + 2;

                long newBLeft = Math.max(bLeft, li);
                long newBRight = Math.min(bRight, ri);
                long scoreB = (aRight - aLeft) + (newBRight - newBLeft) + 2;

                if (scoreA == scoreB) {
                    if (rand.nextInt() % 2 ==0) {
                        aLeft = newALeft;
                        aRight = newARight;
                    } else {
                        bLeft = newBLeft;
                        bRight = newBRight;
                    }
                    continue;
                }

                if (scoreA > scoreB) {
                    aLeft = newALeft;
                    aRight = newARight;
                } else {
                    bLeft = newBLeft;
                    bRight = newBRight;
                }
            }

            max = Math.max(max, (aRight - aLeft) + (bRight - bLeft) + 2);
        }
        return max;
    }


    static class Pair<F extends Comparable<F>, S extends Comparable<S>> implements Comparable<Pair<F, S>> {
        F f;
        S s;

        Pair() {
        }

        Pair(F f, S s) {
            this.f = f;
            this.s = s;
        }

        Pair(Pair<F, S> p) {
            f = p.f;
            s = p.s;
        }

        @Override
        public int compareTo(Pair<F, S> p) {
            if (f.compareTo(p.f) != 0) {
                return f.compareTo(p.f);
            }
            return s.compareTo(p.s);
        }

        @Override
        public int hashCode() {
            return f.hashCode() ^ s.hashCode();
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) {
                return true;
            }
            if (o == null || this.f == null || this.s == null) {
                return false;
            }
            if (this.getClass() != o.getClass()) {
                return false;
            }
            Pair p = (Pair) o;
            return this.f.equals(p.f) && this.s.equals(p.s);
        }

        @Override
        public String toString() {
            return "{" + f.toString() + ", " + s.toString() + "}";
        }
    }

}


class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;

    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        } else {
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }

    private int readByte() {
        if (hasNextByte()) return buffer[ptr++];
        else return -1;
    }

    private boolean isPrintableChar(int c) {
        return 33 <= c && c <= 126;
    }

    public boolean hasNext() {
        while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
        return hasNextByte();
    }

    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while (isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) {
            throw new NumberFormatException();
        }
        while (true) {
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            } else if (b == -1 || !isPrintableChar(b)) {
                return minus ? -n : n;
            } else {
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }

    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
        return (int) nl;
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }
}

