				j = nj;
			} while (j != 0);
			a[j] = ca;
		}
		int ca = a[0];
		for (int i = n - 1; i > 0; i--) {
			int j = 0;
			while ((j << 1) + 2 + Integer.MIN_VALUE < i + Integer.MIN_VALUE) {
				j <<= 1;
				j += (v[a[j + 2]] > v[a[j + 1]]) ? 2 : 1;
			}
			if ((j << 1) + 2 == i) {
				j = (j << 1) + 1;
			}
			int na = a[i];
			a[i] = ca;
			ca = na;
			int cv = v[ca];
			while (j != 0 && v[a[j]] < cv) {
				j = (j - 1) >> 1;
			}
			while (j != 0) {
				na = a[j];
				a[j] = ca;
				ca = na;
				j = (j - 1) >> 1;
			}
		}
		a[0] = ca;
	}

	static void solve() throws Exception {
		int n = scanInt();
		int l[] = new int[n], r[] = new int[n], idx[] = new int[n];
		int maxLen = 0, maxL = Integer.MIN_VALUE, minR = Integer.MAX_VALUE;
		for (int i = 0; i < n; i++) {
			l[i] = scanInt();
			r[i] = scanInt();
			maxLen = max(maxLen, r[i] - l[i] + 1);
			maxL = max(maxL, l[i]);
			minR = min(minR, r[i]);
			idx[i] = i;
		}
		int ans = maxLen + minR - maxL + 1;
		sortBy(idx, n, l);
		int r2 = Integer.MAX_VALUE;
		for (int i = n - 1; i > 0; i--) {
			r2 = min(r2, r[idx[i]]);
			int l2 = l[idx[i - 1]];
			if (l2 <= minR && maxL <= r2) {
				ans = max(ans, minR + r2 - maxL - l2 + 2);
			}
		}
		out.print(ans);
	}

