     */
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        Int[] I = new Int[N];
        for (int i = 0; i < N; i++) {
            I[i] = new Int(sc.nextLong(), sc.nextLong()+1);
        }
        Arrays.sort(I);
        Int[] X = new Int[N+1];
        X[0] = new Int(-1, Long.MAX_VALUE);
        for (int i = 0; i < N; i++) {
            X[i+1] = X[i].merge(I[i]);
        }
        Int[] Y = new Int[N+1];
        Y[N] = new Int(-1, Long.MAX_VALUE);
        for (int i = N-1; i >= 0; i--) {
            Y[i] = Y[i+1].merge(I[i]);
        }

        long res = 0;
        for (int i = 0; i < N; i++) {
            if (i < N-1) {
                res = Math.max(res, X[i+1].size() + Y[i+1].size());
            }
            res = Math.max(res, X[i].merge(Y[i+1]).size() + I[i].size());
        }
        System.out.println(res);
    }

}


class Int implements Comparable<Int> {
    long L, R;
    Int(long l, long r) {
        L = l; R = r;
    }

    Int merge(Int I) {
        return new Int(Math.max(L, I.L), Math.min(R, I.R));
    }

    long size() {
        return Math.max(R-L, 0);
    }

    @Override
    public int compareTo(Int t) {
        int res = Long.compare(L, t.L);
        if (res != 0) return res;
        return Long.compare(R, t.R);
    }
}

import static java.lang.Integer.parseInt;
import static java.lang.Long.parseLong;
import static java.lang.Math.max;
import static java.lang.Math.min;
import static java.lang.System.exit;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {

	static void sortBy(int a[], int n, int v[]) {
		if (n == 0) {
			return;
		}
		for (int i = 1; i < n; i++) {
			int j = i;
			int ca = a[i];
			int cv = v[ca];
			do {
				int nj = (j - 1) >> 1;
				int na = a[nj];
				if (cv <= v[na]) {
					break;
				}
				a[j] = na;
				j = nj;
			} while (j != 0);
			a[j] = ca;
		}
		int ca = a[0];
		for (int i = n - 1; i > 0; i--) {
			int j = 0;
			while ((j << 1) + 2 + Integer.MIN_VALUE < i + Integer.MIN_VALUE) {
				j <<= 1;
				j += (v[a[j + 2]] > v[a[j + 1]]) ? 2 : 1;
			}
			if ((j << 1) + 2 == i) {
				j = (j << 1) + 1;
			}
			int na = a[i];
			a[i] = ca;
			ca = na;
			int cv = v[ca];
			while (j != 0 && v[a[j]] < cv) {
				j = (j - 1) >> 1;
			}
			while (j != 0) {
				na = a[j];
				a[j] = ca;
				ca = na;
				j = (j - 1) >> 1;
			}
		}
		a[0] = ca;
	}

	static void solve() throws Exception {
		int n = scanInt();
		int l[] = new int[n], r[] = new int[n], idx[] = new int[n];
		int maxLen = 0, maxL = Integer.MIN_VALUE, minR = Integer.MAX_VALUE;
		for (int i = 0; i < n; i++) {
			l[i] = scanInt();
			r[i] = scanInt();
			maxLen = max(maxLen, r[i] - l[i] + 1);
			maxL = max(maxL, l[i]);
			minR = min(minR, r[i]);
			idx[i] = i;
		}
		int ans = maxLen + max(minR - maxL + 1, 0);
		sortBy(idx, n, l);
		int r2 = Integer.MAX_VALUE;
		for (int i = n - 1; i > 0; i--) {
			r2 = min(r2, r[idx[i]]);
			int l2 = l[idx[i - 1]];
			if (l2 <= minR && maxL <= r2) {
				ans = max(ans, minR + r2 - maxL - l2 + 2);
			}
		}
		out.print(ans);
	}

	static int scanInt() throws IOException {
		return parseInt(scanString());
	}

	static long scanLong() throws IOException {
		return parseLong(scanString());
	}

	static String scanString() throws IOException {
		while (tok == null || !tok.hasMoreTokens()) {
			tok = new StringTokenizer(in.readLine());
		}
		return tok.nextToken();
	}

	static BufferedReader in;
	static PrintWriter out;
	static StringTokenizer tok;

	public static void main(String[] args) {
		try {
			in = new BufferedReader(new InputStreamReader(System.in));
			out = new PrintWriter(System.out);
			solve();
			in.close();
			out.close();
		} catch (Throwable e) {
			e.printStackTrace();
			exit(1);
		}
	}
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class Main {
	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		int n = Integer.parseInt(br.readLine());
		List<Obj> listL = new ArrayList<>(n);
		List<Obj> listR = new ArrayList<>(n);
		for (int i = 0; i < n; i++) {
			String[] sa = br.readLine().split(" ");
			Obj o = new Obj();
			o.i = i;
			o.l = Integer.parseInt(sa[0]);
			o.r = Integer.parseInt(sa[1]);
			o.v = o.r - o.l + 1;
			listL.add(o);
			listR.add(o);
		}
		br.close();

		int max = 0;
		Obj obj1 = new Obj();
		for (int i = 0; i < n; i++) {
			Obj o = listL.get(i);
			if (o.v > max) {
				max = o.v;
				obj1 = o;
			}
		}
		obj1.t = 1;

		int min = Integer.MAX_VALUE;
		Obj obj2 = null;
		for (int i = 0; i < n; i++) {
			Obj o = listL.get(i);
			if (o.t == 0) {
				int l = Math.max(obj1.l, o.l);
				int r = Math.min(obj1.r, o.r);
				int v = Math.max(r - l + 1, 0);
				if (v < min) {
					min = v;
					obj2 = o;
				}
			}
		}
		obj2.t = 2;

		int al1 = obj1.l;
		int ar1 = obj1.r;
		int ans1 = Math.max(ar1 - al1 + 1, 0);
		int al2 = obj2.l;
		int ar2 = obj2.r;
		int ans2 = Math.max(ar2 - al2 + 1, 0);
		for (int i = 0; i < n; i++) {
			Obj o = listL.get(i);
			if (o.t == 0) {
				int l1 = Math.max(al1, o.l);
				int r1 = Math.min(ar1, o.r);
				int v1 = Math.max(r1 - l1 + 1, 0);
				int l2 = Math.max(al2, o.l);
				int r2 = Math.min(ar2, o.r);
				int v2 = Math.max(r2 - l2 + 1, 0);
				if (v1 + ans2 > ans1 + v2) {
					al1 = l1;
					ar1 = r1;
					ans1 = Math.max(ar1 - al1 + 1, 0);
				} else {
					al2 = l2;
					ar2 = r2;
					ans2 = Math.max(ar2 - al2 + 1, 0);
				}
			}
		}

		System.out.println(Math.max(ans1 + ans2, max));
	}

	static class Obj {
		int i, l, r, v, t;
	}
}

