class B
{
	struct LR
	{
		public int L, R;
		public int Range => R - L + 1;
	}

	static void Main()
	{
		var n = int.Parse(Console.ReadLine());
		var lr = new int[n].Select(_ => Console.ReadLine().Split().Select(int.Parse).ToArray()).Select(x => new LR { L = x[0], R = x[1] }).ToArray();

