        var R = new int[n];
        long ans = 0;
        var segs = new Segment[n];

        Segment mostLeftSeg = null;

        for (int i = 0; i < n; i++) {
            L[i] = ni();
            R[i] = ni();
            segs[i] = new Segment { Left = L[i], Right = R[i] };
            ans = Math.Max(ans, R[i] - L[i] + 1);

            if (mostLeftSeg == null ||
               mostLeftSeg.Right > segs[i].Right) {
                mostLeftSeg = segs[i];
            }
        }

        if (n == 1) {
            ans = R[0] - L[0] + 1;
        } else if (n == 2) {
            ans = R[0] - L[0] + 1 +
                  R[1] - L[1] + 1;
        } else {
            Array.Sort(segs, (s1, s2) => s1.Left.CompareTo(s2.Right));

            var Lset = new MultiSet<int>();
            var Rset = new MultiSet<int>();

            foreach (var s in segs) {
                if (s == mostLeftSeg) continue;

                Lset.Add(s.Left);
                Rset.Add(s.Right);
            }

            var left1 = mostLeftSeg.Left;
            var right1 = mostLeftSeg.Right;

            ans = Math.Max(ans, (right1 - left1 + 1) + Math.Max(Rset.At(0) - Lset.At(Lset.Count - 1) + 1, 0));

            foreach (var s in segs) {
                if (s == mostLeftSeg) continue;
                left1 = Math.Max(s.Left, left1);

                Lset.Remove(s.Left);
                Rset.Remove(s.Right);

                long sub = 0;
                sub += Math.Max(right1 - left1 + 1, 0);
                if (Lset.Count > 0 && Rset.Count > 0) {
                    sub += Math.Max(Rset.At(0) - Lset.At(Lset.Count - 1) + 1, 0);
                }
                ans = Math.Max(sub, ans);
            }
        }

