public class Solver
{
	public void Solve()
	{
		long N = GetLong();
		var L = new long[N];
		var R = new long[N];
		for(long i = 0; i < N; i++)
		{
			L[i] = GetLong();
			R[i] = GetLong() + 1;
		}

		long lmax = long.MinValue;
		long rmin = long.MaxValue;
		long p = -1;
		long q = -1;
		for(long i = 0; i < N; i++)
		{
			if(L[i] > lmax)
			{
				lmax = L[i];
				p = i;
			}
			if(R[i] < rmin)
			{
				rmin = R[i];
				q = i;
			}
		}

		long z = 0;
		var list = new List<(long, long)>();
		for(long i = 0; i < N; i++)
		{
			list.Add((Max(0, R[i] - lmax), Max(0, rmin - L[i])));
			chmax(ref z, R[i] - L[i]);
		}
		list.Sort((x, y) => x.Item1 != y.Item1 ? x.Item1.CompareTo(y.Item1) : y.Item2.CompareTo(x.Item2));

		var ast = new SegmentTree<long>(N, long.MaxValue, (x, y) => Min(x, y));
		var bst = new SegmentTree<long>(N, long.MaxValue, (x, y) => Min(x, y));
		for(long i = 0; i < N; i++)
		{
			ast.Update(i, list[(int)i].Item1);
			bst.Update(i, list[(int)i].Item2);
		}

		long ans = Max(0, rmin - lmax) + z;
		for(long i = 0; i < N - 1; i++)
			chmax(ref ans, bst.Query(0, i + 1) + ast.Query(i + 1, N));

		WriteLine(ans);
	}
}

public class SegmentTree<T>
{
	private long N;
	private T INI;
	private Func<T, T, T> Func;
	private T[] dat;

	public T this[long index]
	{
		get { return dat[index + N - 1]; }
		set { Update(index, value); }
	}

	public SegmentTree(long n, T ini, Func<T, T, T> func)
	{
		N = 1;		
		while(N < n)
			N <<= 1;

		INI = ini;
		Func = func;

		dat = new T[2 * N - 1];
		for(long i = 0; i < 2 * N - 1; i++)
			dat[i] = INI;
	}

	public void Update(long k, T a)
	{
		k += N - 1;
		dat[k] = a;
		while(k > 0)
		{
			k = (k - 1) / 2;
			dat[k] = Func(dat[k * 2 + 1], dat[k * 2 + 2]);
		}
	}

	public T Query(long a, long b, long k = 0, long l = 0, long r = -1)
	{
		if(r == -1)
			r = N;

		if(r <= a || b <= l)
			return INI;

		if(a <= l && r <= b)
			return dat[k];
		else
		{
			T vl = Query(a, b, k * 2 + 1, l, (l + r) / 2);
			T vr = Query(a, b, k * 2 + 2, (l + r) / 2, r);
			return Func(vl, vr);
		}
	}
}

