                return new LLRBTreeIterator<T>(parent);
            } else {
                for (parent = _node.Right, current = parent.Left; current != null; parent = current, current = parent.Left) {
                    ;
                }

                return new LLRBTreeIterator<T>(parent);
            }
        }
    }

    private LLRBTreeIterator<T> GetPredecessor() {
        if (0 <= _index - 1) {
