    class ProgramB
    {
        private class Question : IComparable<Question> {
            public long L {get;set;}
            public long R {get;set;}
            public long A {get;set;}
            public long B {get;set;}
            public int CompareTo(Question item) {
                if (item.A != this.A) return this.A.CompareTo(item.A);

                return - this.B.CompareTo(item.B);
            }
        }
        static void Main()
        {
            int n = NextInt;
            var questions = TakeLine(n).Select(l => new Question{L = l[0], R = l[1] + 1}).OrderBy(q => q.L).ThenBy(q => q.R).ToArray();

            long maxL = questions.Max(q => q.L), minR = questions.Min(q => q.R);
            foreach (var question in questions)
            {
                question.A = Math.Max(0, question.R - maxL);
                question.B = Math.Max(0, minR - question.L);
            }

            Array.Sort(questions);

            var arrayB = Enumerable.Repeat(questions.First().B, n - 1).ToArray();
            var arrayA = Enumerable.Repeat(questions.Last().A, n - 1).ToArray();
            for (int i = 2; i < n; i++)
            {
                arrayB[i - 1] = Math.Min(arrayB[i - 2], questions[i - 1].B);
            }
            for (int i = n - 2; i > 0; i--)
            {
                arrayA[i - 1] = Math.Min(arrayA[i], questions[i].A);
            }

            System.Console.WriteLine(Math.Max(arrayA.Zip(arrayB, (x, y) => x + y).Max(), questions.Max(q => q.R - q.L) + Math.Max(minR - maxL, 0)));
        }
    }
