			for (int i = 0; i < n; i++) {
				long l = cin.Long();
				long r = cin.Long();
				lrs[i] = new LR(l, r);
			}

			int maxIndex = 0;
			long maxCount = 0;
			for (int i = 0; i < n; i++) {
				long count = lrs[i].R - lrs[i].L + 1;
				if (count > maxCount) {
					maxIndex = i;
					maxCount = count;
				}
			}

			long remain = Count(lrs, maxIndex);
			long ans = maxCount + remain;

			int maxLIndex = 0;
			int minRIndex = 0;
			long minR = long.MaxValue;
			long maxL = -1;
			for (int i = 0; i < n; i++) {
				if (lrs[i].L > maxL) {
					maxLIndex = i;
					maxL = lrs[i].L;
				}

				if (lrs[i].R < minR) {
					minRIndex = i;
					minR = lrs[i].R;
				}
			}

			var diffsTemp = new List<LR>();
			for (int i = 0; i < n; i++) {
				if (i != maxLIndex && i != minRIndex) {
					diffsTemp.Add(new LR(Math.Max(0, minR - lrs[i].L + 1), Math.Max(0, lrs[i].R - maxL + 1)));
				}
			}

			var diffs = diffsTemp.OrderByDescending(x => x.L).ThenBy(x => x.R).ToArray();
			MultiSet<long> rs = new MultiSet<long>(diffs.Length);
			for (int i = 0; i < diffs.Length; i++) {
				rs.Add(diffs[i].R);
			}

			for (int i = 0; i <= diffs.Length; i++) {
				LR[] lr1 = new LR[Math.Max(i, 1)];

				if (i != 0) {
					rs.Remove(diffs[i  - 1].R);
				}

				for (int j = 0; j < i; j++) {
					lr1[j] = (diffs[j]);
				}

				long count1 = i == 0
					? lrs[minRIndex].R - lrs[minRIndex].L + 1
					: lr1[lr1.Length - 1].L;
				long count2 = i == diffs.Length
					? lrs[maxLIndex].R - lrs[maxLIndex].L + 1
					: rs.Min;

				ans = Math.Max(ans, count1 + count2);
			}

			Console.WriteLine(ans);
		}

		public static long Count(IReadOnlyList<LR> lrs)
		{
			if (lrs.Count == 0) {
				return 0;
			}

			long l = lrs[0].L;
			long r = lrs[0].R;
			for (int i = 1; i < lrs.Count; i++) {
				l = Math.Max(l, lrs[i].L);
				r = Math.Min(r, lrs[i].R);
				if (r < l) {
					return 0;
				}
			}

			return r - l + 1;
		}

		public static long Count(LR[] lrs, int exclude)
		{
			int first = exclude == 0 ? 1 : 0;
			if (lrs.Length <= first) {
				return 0;
			}

			long l = lrs[first].L;
			long r = lrs[first].R;
			for (int i = 1; i < lrs.Length; i++) {
				if (i == exclude) {
					continue;
				}

				l = Math.Max(l, lrs[i].L);
				r = Math.Min(r, lrs[i].R);
				if (r < l) {
					return 0;
				}
			}

			return r - l + 1;
		}

		public static long Count(LR[] lrs, int start, int end)
		{
			if (end - start <= 0) {
				return 0;
			}

			long l = lrs[start].L;
			long r = lrs[start].R;
			for (int i = 1; i < end; i++) {
				l = Math.Max(l, lrs[i].L);
				r = Math.Min(r, lrs[i].R);
				if (r < l) {
					return 0;
				}
			}

			return r - l + 1;
		}

