internal partial class Solver {
    public void Run() {
        var n = ni();
        var L = new int[n];
        var R = new int[n];

        for (int i = 0; i < n; i++) {
            L[i] = ni();
            R[i] = ni() + 1;
        }

        var segment = E.Range(0, n).Select(i => new { Left = L[i], Right = R[i] }).ToArray();

        // (min_{i in s}(li - minR, 0) + min_{i in t}(maxL - ri, 0))--> max

        var minR = R.Min();
        var maxL = L.Max();

        var x = segment
            .Select(s => new { A = Math.Max(0, minR - s.Left), B = Math.Max(0, s.Right - maxL) })
            .OrderBy(s => s.A)
            .ThenByDescending(s => s.B)
            .ToArray();
        x.Dump();
        long ans = 0;

        ans = Math.Max(0, minR - maxL) + segment.Max(s => Math.Max(0, s.Right - s.Left));

        var bmin = long.MaxValue;

        foreach (var s in x) {
            if (bmin < long.MaxValue) {
                ans = Math.Max(ans, s.A + bmin);
            }
            bmin = Math.Min(s.B, bmin);
        }

        cout.WriteLine(ans);
    }
}

