public class Program
{
    private int N;
    private int[] L, R;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        L = new int[N];
        R = new int[N];
        for (int i = 0; i < N; i++)
        {
            L[i] = sc.NextInt();
            R[i] = sc.NextInt();
        }

        // int[] rSort = new int[N];
        int[] lSort = new int[N];
        for (int i = 0; i < N; i++)
        {
            //     rSort[i] = i;
            lSort[i] = i;
        }

        Array.Sort(lSort, (aa, bb) => L[aa].CompareTo(L[bb]));

        int fL = 0;
        int fR = int.MaxValue;
        int bL = 0;
        int bR = int.MaxValue;

        int[] f = new int[N];
        int[] b = new int[N];

        for (int i = 0; i < N; i++)
        {
            fL = Math.Max(fL, L[lSort[i]]);
            fR = Math.Min(fR, R[lSort[i]]);
            f[i] = Math.Max(0, fR - fL + 1);

            bL = Math.Max(bL, L[lSort[N - 1 - i]]);
            bR = Math.Min(bR, R[lSort[N - 1 - i]]);
            b[N - 1 - i] = Math.Max(0, bR - bL + 1);
        }

        long ans = -1;
        for (int i = 0; i < N - 1; i++)
        {
            ans = Math.Max(ans, f[i] + b[i + 1]);
        }
        Console.WriteLine(ans);
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

