internal partial class Solver {
    class Segment {
        public int Left, Right;
    }

    long width(int left, int right) {
        return Math.Max(right - left + 1, 0);
    }

    public void Run() {
        var n = ni();
        var L = new int[n];
        var R = new int[n];

        for (int i = 0; i < n; i++) {
            L[i] = ni();
            R[i] = ni();
        }

#if false
        n = 100000;
        L = new int[n];
        R = new int[n];
        for (int i = 0; i < n; i++) {
            L[i] = 1 + i;
            R[i] = 10000000 + i;
        }
#endif
        long ans = 0;

        if (n == 1) {
            ans = R[0] - L[0] + 1;
        } else if (n == 2) {
            ans = R[0] - L[0] + 1 +
                  R[1] - L[1] + 1;
        } else {
            var segs = new Segment[n];

            Segment mostLeftSeg = null;

            for (int i = 0; i < n; i++) {
                segs[i] = new Segment { Left = L[i], Right = R[i] };
                ans = Math.Max(ans, R[i] - L[i] + 1);

                if (mostLeftSeg == null ||
                   mostLeftSeg.Right > segs[i].Right) {
                    mostLeftSeg = segs[i];
                }
            }

            Array.Sort(segs, (s1, s2) => s1.Left.CompareTo(s2.Left));

            var Lset = new MultiSet<int>();
            var Rset = new MultiSet<int>();

            foreach (var s in segs) {
                Lset.Add(s.Left);
                Rset.Add(s.Right);
            }

            foreach (var s in segs) {
                long sub = 0;
                sub += width(s.Left, s.Right);
                Lset.Remove(s.Left);
                Rset.Remove(s.Right);
                sub += width(Lset.At(Lset.Count - 1), Rset.At(0));
                ans = Math.Max(ans, sub);
                Lset.Add(s.Left);
                Rset.Add(s.Right);
            }

            Lset.Clear();
            Rset.Clear();

            foreach (var s in segs) {
                if (s == mostLeftSeg) continue;

                Lset.Add(s.Left);
                Rset.Add(s.Right);
            }

            var left1 = mostLeftSeg.Left;
            var right1 = mostLeftSeg.Right;

            ans = Math.Max(ans, width(left1, right1) + width(Lset.At(Lset.Count - 1), Rset.At(0)));

            foreach (var s in segs) {
                if (s == mostLeftSeg) continue;
                left1 = Math.Max(s.Left, left1);
                if (left1 > right1) break;

                Lset.Remove(s.Left);
                Rset.Remove(s.Right);

                long sub = 0;
                sub += width(left1, right1);
                if (Lset.Count > 0 && Rset.Count > 0) {
                    sub += width(Lset.At(Lset.Count - 1), Rset.At(0));
                }
                ans = Math.Max(sub, ans);
            }
        }

        cout.WriteLine(ans);
    }
