using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;
using static System.Console;
using static System.Math;

class Program
{
    static void Main()
    {
        var N = int.Parse(ReadLine());
        var L = new int[N];
        var R = new int[N];
        for (int i = 0; i < N; i++)
        {
            var LR = ReadLine().Split().Select(int.Parse).ToArray();
            L[i] = LR[0];
            R[i] = LR[1];
        }
        var a= L.Select((x, i) => new { l = x, r = R[i] }).OrderBy(x => x.r).ThenByDescending(x => x.l).ToArray();
        for (int i = 0; i < N; i++)
        {
            L[i] = a[i].l;
            R[i] = a[i].r;
        }

        var sp = new SparseTable<int>(L, Max);

        var ans = 0;
        for (int i = 1; i < N; i++)
        {
            var r1 = R[0];
            var r2 = R[i];
            var l1 = sp.Query(0, i);
            var l2 = sp.Query(i, N);
            var m = r1 - l1 + r2 - l2 + 2;
            ans = Max(ans, m);
        }
        WriteLine(ans);
    }
}

public class SparseTable<T> // where (T, F<T, T, T>): 冪等半群 
{
    T[][] buffer; // 2次元配列よりQueryもctorも速いのウケ
    Func<T, T, T> F;
    int[] log2; // floor(log2(n))

    public SparseTable(T[] init, Func<T, T, T> f)
    {
        F = f;

        var n = init.Length;

        log2 = new int[n + 1];
        log2[0] = -1;
        for (int i = 2; i < log2.Length; i++)
        {
            log2[i] = log2[i >> 1] + 1;
        }

        buffer = new T[log2[n] + 1][];
        for (int i = 0; i < buffer.Length; i++)
        {
            buffer[i] = new T[n - (1 << i) + 1];
        }

        Array.Copy(init, 0, buffer[0], 0, init.Length);
        for (int i = 1, p = 1; i < buffer.Length; i++, p <<= 1)
        {
            for (int j = 0; j < buffer[i].Length; j++)
            {
                buffer[i][j] = F(buffer[i - 1][j], buffer[i - 1][j + p]);
            }
        }
    }

    public T Query(int l, int r)//l < r   
    {
        var h = log2[r - l];
        return F(buffer[h][l], buffer[h][r - (1 << h)]);
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.RegularExpressions;
using Library;
