namespace AtCoderTemplate
{
    class ProgramB
    {
        private class Question {
            public long L {get;set;}
            public long R {get;set;}
        }
        static void Main()
        {
            int n = NextInt;
            var questions = TakeLine(n).Select(l => new Question{L = l[0], R = l[1]}).OrderBy(q => q.L).ThenBy(q => q.R).ToArray();
            var order = new Queue<int>(Enumerable.Range(0, n).OrderBy(i => questions[i].R));

            long min = long.MaxValue, result = 0;
            for (int i = 1; i < n; i++)
            {
                min = Math.Min(min, questions[i - 1].R);

                while (order.First() < i) order.Dequeue();

                result = Math.Max(min - questions[i - 1].L + questions[order.First()].R - questions.Last().L + 2, result);
            }

            System.Console.WriteLine(result);
        }
    }
}

