        class Deque<T>
        {
            T[] b; int o, c;
            public int Count;
            public T this[int i] { get { return b[gi(i)]; } set { b[gi(i)] = value; } }
            public Deque(int cap = 16) { b = new T[c = cap]; }
            int gi(int i) { if (i >= c) throw new Exception(); var r = o + i; return r >= c ? r - c : r; }
            public void PushFront(T x) { if (Count == c) e(); if (--o < 0) o += b.Length; b[o] = x; ++Count; }
            public T PopFront() { if (Count-- == 0) throw new Exception(); var r = b[o++]; if (o >= c) o -= c; return r; }
            public T Front => b[o];
            public void PushBack(T x) { if (Count == c) e(); var i = o + Count++; b[i >= c ? i - c : i] = x; }
            public T PopBack() { if (Count == 0) throw new Exception(); return b[gi(--Count)]; }
            public T Back => b[gi(Count - 1)];
            void e() { T[] nb = new T[c << 1]; if (o > c - Count) { var l = b.Length - o; Array.Copy(b, o, nb, 0, l); Array.Copy(b, 0, nb, l, Count - l); } else Array.Copy(b, o, nb, 0, Count); b = nb; o = 0; c <<= 1; }
            public void Insert(int i, T x) { if (i > Count) throw new Exception(); this.PushFront(x); for (int j = 0; j < i; j++) this[j] = this[j + 1]; this[i] = x; }
            public T RemoveAt(int i) { if (i < 0 || i >= Count) throw new Exception(); var r = this[i]; for (int j = i; j > 0; j--) this[j] = this[j - 1]; this.PopFront(); return r; }
        }
        class SegTree<T>
        {
            int n; T ti; Func<T, T, T> f; T[] dat;
            public SegTree(long _n, T _ti, Func<T, T, T> _f) { n = 1; while (n < _n) n <<= 1; ti = _ti; f = _f; dat = Repeat(ti, n << 1).ToArray(); for (var i = n - 1; i > 0; i--) dat[i] = f(dat[(i << 1) | 0], dat[(i << 1) | 1]); }
            public SegTree(List<T> l, T _ti, Func<T, T, T> _f) : this(l.Count, _ti, _f) { for (var i = 0; i < l.Count; i++) dat[n + i] = l[i]; for (var i = n - 1; i > 0; i--) dat[i] = f(dat[(i << 1) | 0], dat[(i << 1) | 1]); }
            public void Update(long i, T v) { dat[i += n] = v; while ((i >>= 1) > 0) dat[i] = f(dat[(i << 1) | 0], dat[(i << 1) | 1]); }
            public T Query(long l, long r) { var vl = ti; var vr = ti; for (long li = n + l, ri = n + r; li < ri; li >>= 1, ri >>= 1) { if ((li & 1) == 1) vl = f(vl, dat[li++]); if ((ri & 1) == 1) vr = f(dat[--ri], vr); } return f(vl, vr); }
            public T this[long idx] { get { return dat[idx + n]; } set { Update(idx, value); } }
        }
        class LazySegTree<T, E>
        {
            int n, height; T ti; E ei; Func<T, T, T> f; Func<T, E, T> g; Func<E, E, E> h; T[] dat; E[] laz;
            public LazySegTree(long _n, T _ti, E _ei, Func<T, T, T> _f, Func<T, E, T> _g, Func<E, E, E> _h) { n = 1; height = 0; while (n < _n) { n <<= 1; ++height; } ti = _ti; ei = _ei; f = _f; g = _g; h = _h; dat = Repeat(ti, n << 1).ToArray(); laz = Repeat(ei, n << 1).ToArray(); for (var i = n - 1; i > 0; i--) dat[i] = f(dat[(i << 1) | 0], dat[(i << 1) | 1]); }
            public LazySegTree(List<T> l, T _ti, E _ei, Func<T, T, T> _f, Func<T, E, T> _g, Func<E, E, E> _h) : this(l.Count, _ti, _ei, _f, _g, _h) { for (var i = 0; i < l.Count; i++) dat[n + i] = l[i]; for (var i = n - 1; i > 0; i--) dat[i] = f(dat[(i << 1) | 0], dat[(i << 1) | 1]); }
            T Reflect(long i) => laz[i].Equals(ei) ? dat[i] : g(dat[i], laz[i]);
            void Eval(long i) { if (laz[i].Equals(ei)) return; laz[(i << 1) | 0] = h(laz[(i << 1) | 0], laz[i]); laz[(i << 1) | 1] = h(laz[(i << 1) | 1], laz[i]); dat[i] = Reflect(i); laz[i] = ei; }
            void Thrust(long i) { for (var j = height; j > 0; j--) Eval(i >> j); }
            void Recalc(long i) { while ((i >>= 1) > 0) dat[i] = f(Reflect((i << 1) | 0), Reflect((i << 1) | 1)); }
            public void Update(long l, long r, E v) { Thrust(l += n); Thrust(r += n - 1); for (long li = l, ri = r + 1; li < ri; li >>= 1, ri >>= 1) { if ((li & 1) == 1) { laz[li] = h(laz[li], v); ++li; } if ((ri & 1) == 1) { --ri; laz[ri] = h(laz[ri], v); } } Recalc(l); Recalc(r); }
            public T Query(long l, long r) { Thrust(l += n); Thrust(r += n - 1); var vl = ti; var vr = ti; for (long li = l, ri = r + 1; li < ri; li >>= 1, ri >>= 1) { if ((li & 1) == 1) vl = f(vl, Reflect(li++)); if ((ri & 1) == 1) vr = f(Reflect(--ri), vr); } return f(vl, vr); }
            public T this[long idx] { get { Thrust(idx += n); return dat[idx] = Reflect(idx); } set { Thrust(idx += n); dat[idx] = value; laz[idx] = ei; Recalc(idx); } }
        }
        class SlidingWindowAggregation<T>
        {
            T[][] l; T[][] a; int[] n; Func<T, T, T> f;
            public SlidingWindowAggregation(IEnumerable<T> ary, Func<T, T, T> _f) { l = new T[2][]; a = new T[2][]; n = new int[2]; f = _f; l[0] = new T[16]; a[0] = new T[16]; n[0] = 0; if (ary.Any()) { var t = ary.ToArray(); n[1] = t.Length; l[1] = new T[n[1]]; a[1] = new T[n[1]]; for (var i = 0; i < l[1].Length; i++) { l[1][i] = t[i]; if (i == 0) a[1][i] = t[i]; else a[1][i] = this.f(a[1][i - 1], t[i]); } } else { l[1] = new T[16]; a[1] = new T[16]; n[1] = 0; } }
            public SlidingWindowAggregation(Func<T, T, T> f) : this(new T[0], f) { }
            public int Count => n[0] + n[1];
            void Push(int la, T v) { if (l[la].Length == n[la]) { var nar = new T[n[la] * 2]; var nag = new T[n[la] * 2]; Array.Copy(l[la], nar, n[la]); Array.Copy(a[la], nag, n[la]); l[la] = nar; a[la] = nag; } if (n[la] == 0) a[la][0] = v; else a[la][n[la]] = la == 0 ? f(v, a[la][n[la] - 1]) : f(a[la][n[la] - 1], v); l[la][n[la]++] = v; }
            public void PushBack(T val) => Push(1, val);
            public void PushFront(T val) => Push(0, val);
            public T Pop(int la) { var lb = 1 - la; if (n[la] == 0) { if (n[lb] == 0) throw new Exception(); var m = (n[lb] - 1) / 2; if (l[la].Length <= m) { l[la] = new T[m + 1]; a[la] = new T[m + 1]; } n[la] = 0; for (var i = m; i >= 0; i--) { if (n[la] == 0) a[la][n[la]] = l[lb][i]; else a[la][n[la]] = la == 0 ? f(l[lb][i], a[la][n[la] - 1]) : f(a[la][n[la] - 1], l[lb][i]); l[la][n[la]++] = l[lb][i]; } for (var i = m + 1; i < n[lb]; i++) { var j = i - m - 1; if (j == 0) a[lb][j] = l[lb][i]; else a[lb][j] = la == 0 ? f(l[lb][i], a[lb][j - 1]) : f(a[lb][j - 1], l[lb][i]); l[lb][j] = l[lb][i]; } n[lb] -= n[la]; } return l[la][--n[la]]; }
            public T PopBack() => Pop(1);
            public T PopFront() => Pop(0);
            public T Aggregate() { if (n[0] == 0 && n[1] == 0) throw new Exception(); else if (n[1] == 0) return a[0][n[0] - 1]; else if (n[0] == 0) return a[1][n[1] - 1]; else return f(a[0][n[0] - 1], a[1][n[1] - 1]); }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;
using static System.Console;
using static System.Math;

class Program
{
    static void Main()
    {
        var N = int.Parse(ReadLine());
        var L = new int[N];
        var R = new int[N];
        for (int i = 0; i < N; i++)
        {
            var LR = ReadLine().Split().Select(int.Parse).ToArray();
            L[i] = LR[0];
            R[i] = LR[1];
        }
        var a= L.Select((x, i) => new { l = x, r = R[i] }).OrderBy(x => x.r).ThenByDescending(x => x.l).ToArray();
        for (int i = 0; i < N; i++)
        {
            L[i] = a[i].l;
            R[i] = a[i].r;
        }

        var sp = new SparseTable<int>(L, Max);

        var ans = 0;
        for (int i = 1; i < N; i++)
        {
            var r1 = R[0];
            var r2 = R[i];
            var l1 = sp.Query(0, i);
            var l2 = sp.Query(i, N);
            var m = r1 - l1 + r2 - l2 + 2;
            ans = Max(ans, m);
        }

        var b = R.Select((x, i) => new { l = L[i], r = x }).OrderBy(x => x.l).ThenByDescending(x => x.r).ToArray();
        for (int i = 0; i < N; i++)
        {
            L[i] = b[i].l;
            R[i] = b[i].r;
        }

        var sp1 = new SparseTable<int>(R, Min);

        for (int i = 1; i < N; i++)
        {
            var r1 = sp1.Query(0, i);
            var r2 = sp1.Query(i, N);
            var l1 = L[i-1];
            var l2 = L[N-1];
            var m = r1 - l1 + r2 - l2 + 2;
            ans = Max(ans, m);
        }


        var lmax = 0;
        var rmin = 0;
        for (int i = 0; i < N; i++)
        {
            if (L[i] > L[lmax]) lmax = i;
            if (R[i] < R[rmin]) rmin = i;
        }
        var d = new int[N];
        d[lmax] = -1;
        d[rmin] = 1;
        var ll = L[lmax];
        var llen = R[lmax] - ll+1;
        var rr = R[rmin];
        var rlen = rr - L[rmin] + 1;

        for (int i = 0; i < N; i++)
        {
            if (d[i] != 0) continue;
            var s = Min(rr - L[i] + 1, rlen);
            var t = Min(R[i]- ll + 1, rlen);
            if(s<t)
            {
                d[i] = -1;
            }
            else
            {
                d[i] = 1;
            }
        }
        var aa = 0;
        var bb = 0;
        var tt = 0;
        var vv = 0;
        for (int i = 0; i < N; i++)
        {
            if(d[i]==1)
            {
                if (L[aa] < L[i]) aa = i;
                if (R[bb] > R[i]) bb = i;
            }
            else
            {
                if (L[tt] < L[i]) tt = i;
                if (R[vv] > R[i]) vv = i;
            }
        }
        WriteLine(Max(ans,bb-aa+vv-tt+2));
    }
}

public class SparseTable<T> // where (T, F<T, T, T>): 冪等半群 
{
    T[][] buffer; // 2次元配列よりQueryもctorも速いのウケ
    Func<T, T, T> F;
    int[] log2; // floor(log2(n))

    public SparseTable(T[] init, Func<T, T, T> f)
    {
        F = f;

        var n = init.Length;

        log2 = new int[n + 1];
        log2[0] = -1;
        for (int i = 2; i < log2.Length; i++)
        {
            log2[i] = log2[i >> 1] + 1;
        }

        buffer = new T[log2[n] + 1][];
        for (int i = 0; i < buffer.Length; i++)
        {
            buffer[i] = new T[n - (1 << i) + 1];
        }

        Array.Copy(init, 0, buffer[0], 0, init.Length);
        for (int i = 1, p = 1; i < buffer.Length; i++, p <<= 1)
        {
            for (int j = 0; j < buffer[i].Length; j++)
            {
                buffer[i][j] = F(buffer[i - 1][j], buffer[i - 1][j + p]);
            }
        }
    }

    public T Query(int l, int r)//l < r   
    {
        var h = log2[r - l];
        return F(buffer[h][l], buffer[h][r - (1 << h)]);
    }
}

