using System;
using System.Linq;//リストの使用
using System.Collections.Generic;
using System.Text;//テキストの高速出力に必要
class Program
{
	static void Main()
	{
		int n = int.Parse(Console.ReadLine());
    long[][] vertexes = new long[n][];
    long[] leftMax = new long[2];
    long[] rightMin = new long[2];
    long[,] rightUsed = new long[n,2];
    int rightLooking = 0;
    for(int i = 0; i < n; i++)
    {
      vertexes[i] = new long[3];
      long[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
      vertexes[i][0] = nums[0];
      vertexes[i][1] = nums[1];
    }
    Array.Sort(vertexes, (a, b) => a[1].CompareTo(b[1]));
    for(int i = 0; i < n; i++)
    {
      vertexes[i][2] = i;
      rightUsed[i,0] = vertexes[i][1];
    }

    var sorted = vertexes.OrderBy(a => a[0]).ThenByDescending(a => a[1]).ToList();
    long answer = 0;
    leftMax[1] = sorted[n-1][0];
    rightMin[0] = long.MaxValue;
    rightMin[1] = long.MaxValue;
    for(int i = 0; i < n; i++) rightMin[1] = Math.Min(rightMin[1], sorted[i][1]);

    for(int i = 1; i <= n-1; i++)
    {
      leftMax[0] = sorted[i-1][0];
      rightMin[0] = Math.Min(rightMin[0], sorted[i-1][1]);
      rightUsed[sorted[i-1][2], 1] = 1;

      while(true)
      {
        if(rightUsed[rightLooking,1] == 0) break;
        else
        {
          rightLooking++;
          rightMin[1] = rightUsed[rightLooking,0];
        }
      }

      //Console.WriteLine(leftMax[0]+" "+leftMax[1]+" "+rightMin[0]+" "+rightMin[1]);

      long answerMemo = Math.Max(0, rightMin[0]-leftMax[0]+1)
        +Math.Max(0, rightMin[1]-leftMax[1]+1);
      answer = Math.Max(answerMemo, answer);
    }

		Console.WriteLine(answer);
	}
}

