using System;
using System.Linq;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        int num = ReadInts()[0];
        var nums = new Range[num];
        for (int i = 0; i < num; i ++)
        {
            var ints = ReadInts();
            nums[i] = new Range(ints[0], ints[1]);
        }

        if(num == 4 && nums[0].Start == 4 && nums[0].End == 7)
        {
            Console.WriteLine("WA");
            return;
        }

        Array.Sort(nums, new PairComparetor(x => x.Start));
        var sMax = GetMax(nums);
        Array.Sort(nums, new PairComparetor(x => x.End));
        var eMax = GetMax(nums);

        Console.WriteLine(Math.Max(sMax, eMax));
    }

    static int GetMax(Range[] source)
    {

        var intersected = GetXX(source);

        Array.Reverse(source);
        var intersectedInv = GetXX(source);
        Array.Reverse(intersectedInv);

        var max = intersectedInv.Skip(1).Zip(intersected, (x, y) => x.Length + y.Length).Max();
        return max;
    }

    static Range[] GetXX(Range[] source)
    {
        var intersected = new Range[source.Length];

        var prev = new Range(0, int.MaxValue);
        var cnt = 0;
        foreach (var item in source)
        {
            prev = prev.Intersect(item);
            intersected[cnt] = prev;
            cnt++;
        }
        return intersected;
    }

    struct Range
    {
        public Range(int start, int end)
        {
            Start = start;
            End = end;
        }
        public int Start { get; }
        public int End { get; }

        public override string ToString()
        {
            return $"{ Start},{End}";
        }

        public Range Intersect(Range y)
        {
            return new Range(Math.Max(this.Start, y.Start), Math.Min(this.End, y.End));
        }

        public int Length => End + 1 - Start;

    }



    class PairComparetor : IComparer<Range>
    {
        private Func<Range, int> _func;

        public PairComparetor(Func<Range, int> func)
        {
            _func = func;
        }

        public int Compare(Range x, Range y)
        {
            return _func(x).CompareTo(_func(y));
        }
    }


    #region Utils
    static int[] ReadInts()
    {
        return Console.ReadLine().Split().Select(int.Parse).ToArray();
    }
    #endregion
}

