package main

import "fmt"
import "sort"

type entry struct {
	lower int
	upper int
}

func main() {
	var N int
	fmt.Scan(&N)

	ee := make([]entry, N)

	var iMaxL, iMinU = 0, 0
	for i := 0; i < N; i++ {
		fmt.Scan(&ee[i].lower, &ee[i].upper)
	}

	sort.Sort(byUpper(ee))

	for i := 0; i < N; i++ {
		if ee[iMaxL].lower < ee[i].lower {
			iMaxL = i
		}
		if ee[iMinU].upper > ee[i].upper {
			iMinU = i
		}
	}

	if iMaxL == iMinU {
		max := 0
		for i := 0; i < N; i++ {
			if i == iMaxL {
				continue
			}
			max = Max(max, ee[i].upper-ee[i].lower+1)
		}

		fmt.Println(max + Max(ee[iMaxL].upper-ee[iMaxL].lower+1, 0))
		return
	}

	for i := 0; i < N; i++ {
		if i == iMaxL || i == iMinU {
			continue
		}
		if ee[i].upper >= ee[iMaxL].upper {
			continue
		}
		if ee[i].lower <= ee[iMinU].lower {
			continue
		}
		scoreL := ee[i].upper - ee[iMinU].lower
		scoreU := ee[iMaxL].upper - ee[i].lower
		if scoreL > scoreU {
			ee[iMaxL].upper = ee[i].upper
		} else {
			ee[iMinU].lower = ee[i].lower
		}
	}

	result := Max(ee[iMaxL].upper-ee[iMaxL].lower+1, 0) + Max(ee[iMinU].upper-ee[iMinU].lower+1, 0)
	fmt.Println(result)
}

type byUpper []entry

func (a byUpper) Len() int           { return len(a) }
func (a byUpper) Swap(i, j int)      { a[i], a[j] = a[j], a[i] }
func (a byUpper) Less(i, j int) bool { return a[i].upper < a[j].upper }

func Max(x, y int) int {
	if x > y {
		return x
	}
