import "fmt"

type ran struct {
	l int
	r int
}

func calc(s []ran, fl int, fr int, sl int, sr int, x int) int {
	var ans_first, ans_second int
	if x == len(s) {
		if fl != -1 && sl != -1{
			return (fr-fl+1+sr-sl+1)
		} else {
			return -1
		}
	}
	if fl == -1 {
		ans_first = calc(s,s[x].l,s[x].r,sl,sr,x+1)
	} else {
		if fl <= s[x].l {
			if s[x].r <= fr {
				ans_first = calc(s,s[x].l,s[x].r,sl,sr,x+1)
			} else {
				ans_first = calc(s,s[x].l,fr,sl,sr,x+1)
			}
		} else {
			if s[x].r <= fr {
				ans_first = calc(s,fl,s[x].r,sl,sr,x+1)
			} else {
				ans_first = calc(s,fl,fr,sl,sr,x+1)
			}
		}
	}

	if sl == -1{
		ans_second = calc(s,fl,fr,s[x].l,s[x].r,x+1)
	} else {
		if sl <= s[x].l {
			if s[x].r <= sr {
				ans_second = calc(s,fl,fr,s[x].l,s[x].r,x+1)
			} else {
				ans_second = calc(s,fl,fr,s[x].l,sr,x+1)
			}
		} else {
			if s[x].r <= sr {
				ans_second = calc(s,fl,fr,sl,s[x].r,x+1)
			} else {
				ans_second = calc(s,fl,fr,sl,sr,x+1)
			}
		}
	}
	if ans_first <= ans_second {
		return ans_second
	} else {
		return ans_first
	}
}

func main(){
	var n int
	fmt.Scan(&n)
	s := make([]ran,n)
	for i:=0 ; i<n ; i++ {
		fmt.Scan(&s[i].l,&s[i].r)
	}
	ans := calc(s,-1,-1,-1,-1,0)
	fmt.Println(ans)
}

