			minLIndex = i
		}

		if maxR <= r[i] {
			preMaxR = maxR
			preMaxRIndex = maxRIndex

			maxRIndex = i
			maxR = r[i]
		}
	}

	if minLIndex == maxRIndex {
		maxRIndex = preMaxRIndex
		maxR = preMaxR
	}

	leftMin := minL
	leftMax := r[minLIndex]
	rightMin := l[maxRIndex]
	rightMax := maxR
	for i:=0;i<n ; i++ {
		leftDelta := delta(leftMin, leftMax, l[i], r[i])
		rightDelta := delta(rightMin, rightMax, l[i], r[i])
		if leftDelta >= rightDelta {
			rightMin = Max(l[i], rightMin)
			rightMax = Min(r[i], rightMax)
		} else {
			leftMin = Max(l[i], leftMin)
			leftMax = Min(r[i], leftMax)
		}
	}

	fmt.Printf("%d", ZeroOr(leftMax - leftMin) + ZeroOr(rightMax - rightMin) + 2)
}

func Max(x ...int) int {
	max := x[0]
	for _, v := range x {
		if v > max {
			max = v
		}
	}
	return max
}

func Min(x ...int) int {
	min := x[0]
	for _, v := range x {
		if v < min {
			min = v
		}
	}
	return min
}

func ZeroOr(x int) int {
	if x < 0 {
		return 0
	}
	return x
}

func delta(l1, r1, l2, r2 int) int {
	return ZeroOr(l2 - l1) + ZeroOr(r1 - r2)
}

