	r2 := int(1e10 + 1)

	for i := 0; i < N; i++ {
		// 1回目に入れるか2回目に入れるかを決める
		c1 := score(min(r1, Q[i].r), max(l1, Q[i].l)) + score(r2, l2)
		c2 := score(min(r2, Q[i].r), max(l2, Q[i].l)) + score(r1, l1)

		if c1 > c2 {
			r1 = min(r1, Q[i].r)
			l1 = max(l1, Q[i].l)
		} else {
			r2 = min(r2, Q[i].r)
			l2 = max(l2, Q[i].l)
		}
	}

	fmt.Println(score(r1, l1) + score(r2, l2))
}

