type pair struct{ l, r int }
type ps []pair

func (p ps) Len() int           { return len(p) }
func (p ps) Less(i, j int) bool { return p[i].r < p[j].r }
func (p ps) Swap(i, j int)      { p[i], p[j] = p[j], p[i] }

// github.com/EndlessCheng/codeforces-go
func run(_r io.Reader, _w io.Writer) {
	in := bufio.NewReader(_r)
	max := func(a, b int) int {
		if a > b {
			return a
		}
		return b
	}

	var n, ans int
	Fscan(in, &n)
	a := make(ps, n)
	for i := range a {
		Fscan(in, &a[i].l, &a[i].r)
	}
	sort.Sort(a)
	pMax := make([]int, n+1)
	for i, p := range a {
		pMax[i+1] = max(pMax[i], p.l)
	}
	sMax := make([]int, n+1)
	for i := n - 1; i >= 0; i-- {
		sMax[i] = max(sMax[i+1], a[i].l)
	}
	for i := 1; i < n; i++ {
		s := 0
		r := a[0].r
		l := pMax[i]
		if l <= r {
			s += r - l + 1
		}
		r = a[i].r
		l = sMax[i]
		if l <= r {
			s += r - l + 1
		}
		ans = max(ans, s)
	}
	Fprint(_w, ans)
}

func main() { run(os.Stdin, os.Stdout) }

