enum long INF = long.max/5;
enum long MOD = 10L^^9+7;

void main() {
  long N;
  scanln(N);

  struct P {
    long l, r;
  }
  P[] ps = new P[N];
  foreach(i; 0..N) {
    scanln(ps[i].l, ps[i].r);
    ps[i].l--;
    ps[i].r--;
  }

  ps.sort!"a.l != b.l ? a.l > b.l : a.r > b.r";

  long[] r1s = new long[N];
  foreach_reverse(i; 0..N) {
    r1s[i] = ps[i].r;
    if (i < N-1) {
      r1s[i].ch!min(r1s[i+1]);
    }
  }

  long ans = 0;

  {
    long l2 = -1;
    long r2 = INF;
    long l3 = -1;
    long r3 = -1;
    foreach(i; 0..N) {
      const long l1 = ps[i].l;
      const long r1 = r1s[i];

      if (l2 >= 0) {
        if (r1 >= l1) {
          ans.ch!max(
            max(0, r1-l1+1) + max(0, r2-l2+1)
          );
        }
      } else if (r3 >= 0) {
        if (r1 >= l1) {
          ans.ch!max(
            max(0, r1-l1+1) + max(0, r3-l3+1)
          );
        }
      }

      if (i < N-1 && ps[i+1].l == ps[i].l) {
        l3 = ps[i].l;
        r3.ch!max(ps[i].r);
      } else {
        l3 = -1;
        r3 = -1;
        l2.ch!max(ps[i].l);
        r2.ch!min(ps[i].r);
      }
    }
  }

  {
    const l1 = ps[0].l;
    long r1 = ps[0].r;
    long l2 = -1;
    long r2 = INF;
    foreach(i; 0..N) {
      if (ps[i].l == l1) {
        r1.ch!min(ps[i].r);
      } else {
        l2.ch!max(ps[i].l);
        r2.ch!min(ps[i].r);
      }
    }
    if (l2>=0) {
      ans.ch!max(
        max(0, r1-l1+1) + max(0, r2-l2+1)
      );
    }
  }

  ans.writeln;
}

