def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap


@mt
def slv(N, LR):
    LR.sort(key=lambda x: x[1], reverse=True)
    LR.sort(key=lambda x: x[0])

    @lru_cache(maxsize=None)
    def f(li, ri):
        l = 0
