fn solve() {
    let n = get!(usize);
    let mut lr = get!(usize, usize; n);
    lr.sort();
    let mx = 1_000_000_000;
    let mut forward = vec![(0,0); n+1];
    let mut back = vec![(0,0); n+1];
    forward[0] = (0,mx);
    for i in 0..n {
        forward[i+1] = (max!(forward[i].0, lr[i].0), min!(forward[i].1, lr[i].1));
    }
    back[n] = (0,mx);
    for i in (0..n).rev() {
        back[i] = (max!(back[i+1].0, lr[i].0), min!(back[i+1].1, lr[i].1));
    }

    let mut res = 0;
    for i in 1..n {
        let (fl,fr) = forward[i];
        let (bl,br) = back[i];
        let fl = fl as isize;
        let fr = fr as isize;
        let bl = bl as isize;
        let br = br as isize;
        res = max!(res, (max!(fr-fl+1,0)+max!(br-bl+1,0)) as usize);
    }
    println!("{}",res);
}

