fn main() {
    let mut buf = String::new();
    std::io::stdin().read_to_string(& mut buf).unwrap();
    let mut iter = buf.split_whitespace();

    let n = iter.next().unwrap().parse::<usize>().unwrap();
    let mut segments: Vec<(usize, usize)> = (0..n).map(|_| {
        let l = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let r = iter.next().unwrap().parse::<usize>().unwrap();
        (l, r)
    }).collect();

    let mut max_l = segments.iter().map(|&(l, _)| l).max().unwrap();
    let mut min_r = segments.iter().map(|&(_, r)| r).min().unwrap();
    let mut max_size = segments.iter().map(|&(l, r)| r - l).max().unwrap();
    let mut res = max_size + max(min_r - max_l, 0);
    segments.sort_by(|p1, p2| if p1.0 != p2.0 {
        return p1.0.cmp(&p2.0);
    } else {
        return p2.1.cmp(&p1.1);
    });
    let mut fl = vec![0; n + 1];
    let mut fr = vec![1000_000_000; n + 1];
    for i in 0..n {
        fl[i + 1] = max(fl[i], segments[i].0);
        fr[i + 1] = min(fr[i], segments[i].1);
    }
    let mut bl = vec![0; n + 1];
    let mut br = vec![1000_000_000; n + 1];
    for i in 0..n {
        let j = n - 1 - i;
        bl[j] = max(bl[j + 1], segments[j].0);
        br[j] = min(br[j + 1], segments[j].1);
    }

    for i in 1..n {
