use std::io::{stdin, BufRead};
use std::cmp;

fn main() {
    let stdin = stdin();
    let mut cin = stdin.lock();
    let n = {
        let mut buf = String::new();
        cin.read_line(&mut buf).unwrap();
        buf.trim().parse::<usize>().unwrap()
    };
    let mut lr = Vec::with_capacity(n);
    for _ in 0..n {
        let (l, r) = {
            let mut buf = String::new();
            cin.read_line(&mut buf).unwrap();
            let mut words = buf.split(' ');
            (
                words.next().unwrap().trim().parse::<i32>().unwrap(),
                words.next().unwrap().trim().parse::<i32>().unwrap(),
            )
        };
        lr.push((l, r));
    }
    lr.sort();

    let mut l_start = Vec::new();
    let mut l_end = Vec::new();
    let mut min = 2000000000;
    for &(l, r) in lr.iter() {
        l_start.push(l);
        min = cmp::min(min, r);
        l_end.push(min);
    }
    let mut r_start = vec![lr.last().unwrap().0; n];
    let mut r_end = Vec::new();
    let mut min = 2000000000;
    for &(_, r) in lr.iter().rev() {
        min = cmp::min(min, r);
        r_end.push(min);
    }
    r_start = r_start.iter().rev().map(|x| *x).collect::<Vec<_>>();
    r_end = r_end.iter().rev().map(|x| *x).collect::<Vec<_>>();

    let mut best = lr.iter().map(|&(l, r)| r - l + 1).max().unwrap();
    for i in 1..n {
        let l_widht = cmp::max(0, l_end[i-1] - l_start[i-1] + 1);
        let r_widht = cmp::max(0, r_end[i] - r_start[i] + 1);
        best = cmp::max(best, l_widht + r_widht);
    }
    println!("{}", best);
}

#[allow(unused_macros)]
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, bytes) => {
        read_value!($next, String).into_bytes()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

