use std::cmp::{max, min};
use std::collections::BTreeMap;
use std::io::{stdin, Read};

#[allow(unused_macros)]
macro_rules! parse {
    ($it: ident ) => {};
    ($it: ident, ) => {};
    ($it: ident, $var:ident : $t:tt $($r:tt)*) => {
        let $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
    ($it: ident, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
}

#[allow(unused_macros)]
macro_rules! parse_val {
    ($it: ident, [$t:tt; $len:expr]) => {
        (0..$len).map(|_| parse_val!($it, $t)).collect::<Vec<_>>();
    };
    ($it: ident, ($($t: ty),*)) => {
        ($(parse_val!($it, $t)),*)
    };
    ($it: ident, $t: ty) => {
        $it.next().unwrap().parse::<$t>().unwrap()
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: usize, lr: [(usize, usize); n]);
    let mut lr: Vec<(usize, usize)> = lr.iter().map(|&(l, r)| (l, r + 1)).collect();
    let (rmin, _, rmini) = lr
        .iter()
        .enumerate()
        .map(|(i, &(l, r))| (r, r - l, i))
        .min()
        .unwrap();
    let (lmax, _, lmaxi) = lr
        .iter()
        .enumerate()
        .map(|(i, &(l, r))| (l, r - l, i))
        .max()
        .unwrap();
    if rmini == lmaxi {
        let ret = rmin - lmax + lr.iter().map(|&(l, r)| r - l).max().unwrap();
        println!("{}", ret);
    } else {
        let mut la = lr[rmini].0;
        lr.remove(rmini);
        let mut rb = !0;
        let mut rs = BTreeMap::new();
        for &(_, r) in lr.iter() {
            let e = rs.entry(r).or_insert(0);
            *e += 1;
            rb = min(rb, r);
        }
        let mut ret = rmin - la + rb.saturating_sub(lmax);
        lr.sort();
        for &(l, r) in lr.iter() {
            let x = rs[&r] - 1;
            if x == 0 {
                rs.remove(&r);
            } else {
                rs.insert(r, x);
            }
            rb = *rs.iter().next().map(|(k, v)| k).unwrap_or(&rb);
            la = l;
            ret = max(ret, rmin.saturating_sub(la) + rb.saturating_sub(lmax));
        }
        println!("{}", ret);
    }
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    solve(&s);
}

