        (0..$len).map(|_| parse_val!($it, $t)).collect::<Vec<_>>();
    };
    ($it: ident, ($($t: ty),*)) => {
        ($(parse_val!($it, $t)),*)
    };
    ($it: ident, $t: ty) => {
        $it.next().unwrap().parse::<$t>().unwrap()
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: usize, lr: [(usize, usize); n]);
    let mut lr: Vec<(usize, usize)> = lr.iter().map(|&(l, r)| (l, r + 1)).collect();
    let (rmin, _, rmini) = lr
        .iter()
        .enumerate()
        .map(|(i, &(l, r))| (r, r - l, i))
        .min()
        .unwrap();
    let (lmax, _, lmaxi) = lr
        .iter()
        .enumerate()
        .map(|(i, &(l, r))| (l, r - l, i))
        .max()
        .unwrap();
    let mut ret = 0;
    for &(l, r) in lr.iter() {
        ret = max(ret, r.saturating_sub(l) + rmin.saturating_sub(lmax));
    }

    lr.sort_by_key(|&(l, r)| (r, l));
    let mut ls = !0;
    let mut rs = rmin.saturating_sub(lmax);
    for &(l, r) in lr.iter() {
        rs = r.saturating_sub(lmax);
        if ls != !0 {
            ret = max(ret, ls + rs);
        }
        ls = min(ls, rmin.saturating_sub(l));
    }
    println!("{}", ret);
}

