use std::io::{stdin, BufRead};
use std::cmp;

fn main() {
    let stdin = stdin();
    let mut cin = stdin.lock();
    let n = {
        let mut buf = String::new();
        cin.read_line(&mut buf).unwrap();
        buf.trim().parse::<usize>().unwrap()
    };
    let mut lr = Vec::with_capacity(n);
    for _ in 0..n {
        let (l, r) = {
            let mut buf = String::new();
            cin.read_line(&mut buf).unwrap();
            let mut words = buf.split(' ');
            (
                words.next().unwrap().trim().parse::<i32>().unwrap(),
                words.next().unwrap().trim().parse::<i32>().unwrap(),
            )
        };
        lr.push((l, r));
    }
    lr.sort();

    let mut l_start = Vec::new();
    let mut l_end = Vec::new();
    let mut min = 2000000000;
    for &(l, r) in lr.iter() {
        l_start.push(l);
        min = cmp::min(min, r);
        l_end.push(min);
    }
    let mut r_start = vec![lr.last().unwrap().0; n];
    let mut r_end = Vec::new();
    let mut min = 2000000000;
    for &(_, r) in lr.iter().rev() {
        min = cmp::min(min, r);
        r_end.push(min);
    }
    r_start = r_start.iter().rev().map(|x| *x).collect::<Vec<_>>();
    r_end = r_end.iter().rev().map(|x| *x).collect::<Vec<_>>();

    let mut best = -1;
    for i in 1..n {
        let l_widht = cmp::max(0, l_end[i-1] - l_start[i-1] + 1);
        let r_widht = cmp::max(0, r_end[i] - r_start[i] + 1);
        best = cmp::max(best, l_widht + r_widht);
    }
    for i in 1..n-1 {
        let start = cmp::max(l_start[i-1], r_start[i+1]);
        let end = cmp::min(l_end[i-1], r_end[i+1]);
        let width = cmp::max(0, end - start + 1) + lr[i].1 - lr[i].0 + 1;
        best = cmp::max(best, width);
    }

    println!("{}", best);
}

use std::cmp::{max, min};
use std::io::Read;

fn main() {
    let mut buf = String::new();
    std::io::stdin().read_to_string(& mut buf).unwrap();
    let mut iter = buf.split_whitespace();

    let n = iter.next().unwrap().parse::<usize>().unwrap();
    let mut segments= (0..n).map(|_| {
        let l = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let r = iter.next().unwrap().parse::<usize>().unwrap();
        (l, r)
    }).collect::<Vec<(usize, usize)>>();

    let mut max_l = segments.iter().map(|&(l, _)| l).max().unwrap();
    let mut min_r = segments.iter().map(|&(_, r)| r).min().unwrap();
    let mut max_size = segments.iter().map(|&(l, r)| r - l).max().unwrap();
    let mut res = max_size + max(min_r - max_l, 0);

    segments.sort_by(|p1, p2| if p1.0 != p2.0 {
        return p1.0.cmp(&p2.0);
    } else {
        return p2.1.cmp(&p1.1);
    });
    let mut fl = vec![0; n + 1];
    for i in 0..n {
        fl[i + 1] = max(fl[i], segments[i].0);
    }
    let mut br = vec![1000_000_000; n + 1];
    for i in 0..n {
        let j = n - 1 - i;
        br[j] = min(br[j + 1], segments[j].1);
    }
    for i in 1..n {
        res = max(res, max(min_r - fl[i], 0) + max(br[i] - max_l, 0));
    }

    println!("{}", res)
}

