fn main() {
    let n: usize = read();
    let mut lr1: Vec<Vec<u32>> = read_vec2(n);
    lr1.sort_by(|x, y| {
        if x[0] != y[0] {
            x[0].partial_cmp(&y[0]).unwrap()
        } else {
            y[1].partial_cmp(&x[1]).unwrap()
        }
    });

    let mut lr: Vec<Vec<u32>> = vec![];
    let tmpl = lr1[0][0];
    let mut tmpr = lr1[0][1];
    lr.push(vec![tmpl, tmpr]);
    for i in 1..lr1.len() {
        let l = lr1[i][0];
        let r = lr1[i][1];
        if r > tmpr {
            lr.push(vec![l, r]);
            tmpr = r;
        }
    }

    let l = lr.len();

    let mut ans: u32 = 0;

    if l == 1 {
        ans += lr1[0][1] - lr1[0][0] + 1;
        let mut l = lr1[0][0];
        let mut r = lr1[0][1];
        for i in 1..lr1.len() {
            if l < lr1[i][0] {
                l = lr1[i][0];
            }
            if lr1[i][1] < r {
                r = lr1[i][1];
            }
        }
        if r >= l {
            ans += r - l + 1;
        }
    } else {
        let mut lmin = lr[0][0];
        let lmax = lr[0][1];
        let rmin = lr[l - 1][0];
        let mut rmax = lr[1][1];
        if lmax >= lmin {
            ans += lmax - lmin + 1;
        }
        if rmax >= rmin {
            ans += rmax - rmin + 1;
        }
        for i in 1..l - 1 {
            lmin = lr[i][0];
            rmax = lr[i + 1][1];
            let mut tmp = 0;
            if lmax >= lmin {
                tmp += lmax - lmin + 1;
            }
            if rmax >= rmin {
                tmp += rmax - rmin + 1;
            }
            if tmp > ans {
                ans = tmp;
            }
        }
    }
    println!("{}", ans);
}

#[allow(unused_macros)]
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, bytes) => {
        read_value!($next, String).into_bytes()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

