    fn find(n: usize, ps: &Vec<(i64,i64)>, e: usize) -> i64 {
        let (mut l1, mut r1) = ps[0];
        let (mut l2, mut r2) = ps[e];
        use std::cmp::{max, min};
        for i in 1 .. n {
            if i == e {
                continue;
            }
            let (l, r) = ps[i];
            let tl1 = max(l1, l);
            let tr1 = min(r1, r);
            let tl2 = max(l2, l);
            let tr2 = min(r2, r);
            if max(0,tr1-tl1)+max(0,r2-l2)>max(0,r1-l1)+max(0,tr2-tl2) {
                l1 = tl1;
                r1 = tr1;
            } else {
                l2 = tl2;
                r2 = tr2;
              }
        }
        max(0, r1-l1+1) + max(0, r2-l2+1)
    }

