fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let p = (0..n)
        .map(|_| (sc.read::<i64>(), sc.read::<i64>()))
        .collect::<Vec<_>>();

    let mut p = p
        .into_iter()
        .map(|(left, right)| (right, (left, right)))
        .collect::<Vec<_>>();
    p.sort();

    let (last_left, last_right) = p[n - 1].1;
    let mut last_min_right = last_left;

    let mut first_head = 1;
    let mut first_tail = 1e9 as i64;
    let mut last = vec![];
    for i in 0..n {
        let (left, right) = p[i].1;
        if last_left <= right {
            last.push((right, (left, right)));
            last_min_right = cmp::min(last_min_right, right);
        } else {
            first_head = cmp::max(first_head, left);
            first_tail = cmp::min(first_tail, right);
        }
    }
    last.sort();
    if last.len() == n {
        let (_, (left, right)) = last.remove(0);
        first_head = cmp::max(first_head, left);
        first_tail = cmp::min(first_tail, right);
    }

    let mut ans =
        cmp::max(first_tail - first_head + 1, 0) + cmp::max(last_min_right - last_left + 1, 0);
    for i in 0..(last.len() - 1) {
        let (_, (left, right)) = last[i];
        first_head = cmp::max(first_head, left);
        first_tail = cmp::min(first_tail, right);

        let (_, (_, next_right)) = last[i + 1];
        let next_right = cmp::min(next_right, last_right);

        let first = cmp::max(first_tail - first_head + 1, 0);
        let last = cmp::max(next_right - last_left + 1, 0);
        ans = cmp::max(ans, first + last);
    }

    println!("{}", ans);
}

