        let mut lsum = 0;
        let mut rsum = 0;
        if lto >= lfrom {
            lsum = lto - lfrom + 1;
        }
        if rto >= rfrom {
            rsum = rto - rfrom + 1;
        }
        ans = std::cmp::max(ans, lsum + rsum);
    }
    p(ans);
}

use std::io::stdin;
use std::cmp::{max, min};

fn read_line() -> Vec<String> {
    let mut line = String::new();
    stdin().read_line(&mut line).expect("Failed to read line");
    return line.trim().split_whitespace().map(|s| s.to_string()).collect();
}

struct Reader {
    v: Vec<String>,
    n: usize,
}

impl Reader {
    fn new() -> Reader {
        let v = read_line();
        return Reader { v: v, n: 0 };
    }
    fn next<T>(&mut self) -> T where T: std::str::FromStr, T::Err: std::fmt::Debug {
        if self.n == self.v.len() {
            self.v = read_line();
            self.n = 0;
        }
        let x = self.v[self.n].parse().expect(&self.v[self.n]);
        self.n += 1;
        return x;
    }
    fn nexts<T>(&mut self, n: usize) -> Vec<T>
    where T: std::str::FromStr, T::Err: std::fmt::Debug {
        let mut v = Vec::with_capacity(n);
        for _ in 0..n {
            v.push(self.next());
        }
        return v;
    }
}

fn main() {
    let mut r = Reader::new();
    let n: usize = r.next();
    let mut ls: Vec<i64> = Vec::with_capacity(n);
    let mut rs: Vec<i64> = Vec::with_capacity(n);

    for _ in 0..n {
        ls.push(r.next());
        rs.push(r.next());
    }


    let mut lm = [ls[0], ls[1]];
    let mut rm = [rs[0], rs[1]];

    for i in 2..n {
        let x = [
            max(0, min(rm[0], rs[i]) - max(lm[0], ls[i]) + 1) +
                max(0, rm[1] - lm[1] + 1),
            max(0, rm[0] - lm[0] + 1) +
                max(0, min(rm[1], rs[i]) - max(lm[1], ls[i]) + 1),
            max(0, min(rm[0], rm[1]) - max(lm[0], lm[1]) + 1) +
                max(0, rs[i] - ls[i] + 1),
        ];

        if x[0] > x[1] && x[0] > x[2] {
            lm[0] = max(lm[0], ls[i]);
            rm[0] = min(rm[0], rs[i]);
        } else if x[1] > x[0] && x[1] > x[2] {
            lm[1] = max(lm[1], ls[i]);
            rm[1] = min(rm[1], rs[i]);
        } else {
            lm[0] = max(lm[0], lm[1]);
            rm[0] = min(rm[0], rm[1]);
            lm[1] = ls[i];
            rm[1] = rs[i];
        }
    }

    println!("{}", max(0, rm[0] - lm[0] + 1) + max(0, rm[1] - lm[1] + 1));
}

