fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize,
        lr: [(i64, i64); n],
    }
    let lr: Vec<_> = lr.into_iter().map(|(l, r)| (l, r + 1))
        .collect();
    let mut ev = vec![];
    for i in 0..n {
        let (l, r) = lr[i];
        ev.push((l, n + i));
        ev.push((r, i));
    }
    ev.sort();
    // Do we have two segments s1, s2 s.t. s1 /\ s2 = {}?
    let mut idx = 2 * n;
    for i in 0..2 * n - 1 {
        if ev[i].1 < n && ev[i + 1].1 >= n {
            idx = i;
            break;
        }
    }
    eprintln!("idx = {:?}", idx);
    let mut ma = 0;
    for &(l, r) in &lr {
        ma = max(ma, r - l);
    }
    if idx >= 2 * n {
        let mut ls = vec![];
        let mut rs = vec![];
        for &(l, r) in &lr {
            ls.push(l);
            rs.push(r);
        }
        ls.sort(); ls.reverse();
        rs.sort();
        for i in 0..n {
            let (l, r) = lr[i];
            let ol = if ls[0] == l {
                ls[1]
            } else {
                ls[0]
            };
            let or = if rs[0] == r {
                rs[1]
            } else {
                rs[0]
            };
            ma = max(ma, r - l + max(0, or - ol));
        }
    } else {
        let i1 = ev[idx].1;
        let i2 = ev[idx + 1].1 - n;
        let (mut l1, mut r1) = lr[i1];
        let (mut l2, mut r2) = lr[i2];
        let mut pool = vec![];
        for &(l, r) in &lr {
            if r <= l2 {
                l1 = max(l1, l);
                r1 = min(r1, r);
            } else if l >= r1 {
                l2 = max(l2, l);
                r2 = min(r2, r);
            } else {
                pool.push((l, r));
            }
        }
        pool.sort();
        let m = pool.len();
        const INF: i64 = 1 << 50;
        let mut acc = vec![INF; m + 1];
        for i in (0..m).rev() {
            let (_, r) = pool[i];
            acc[i] = min(acc[i + 1], r);
        }
        ma = max(ma, r1 - l1 + max(0, min(acc[0], r2) - l2));
        for i in 1..m + 1 {
            ma = max(ma, max(0, r1 - max(l1, pool[i - 1].0)) +
                     max(0, min(acc[i], r2) - l2));
        }
    }
    puts!("{}\n", ma);
}

