        v.sort();
        let l = cmp::max(v[0][0], v[1][0]);
        let r = cmp::min(v[0][1], v[1][1]);
        m[i+1][0] = l;
        m[i+1][1] = r;
    }
    lr.reverse();
    let mut m2 = vec![vec![0, INF as usize];N+1];
    for i in 0..N{
        let mut v= vec![];
        v.push(lr[i].clone());
        v.push(m2[i].clone());
        v.sort();
        let l = cmp::max(v[0][0], v[1][0]);
        let r = cmp::min(v[0][1], v[1][1]);
        if l<=r{
            m2[i+1][0] = l;
            m2[i+1][1] = r;
        }
        else{
            m2[i+1][0] = 0;
            m2[i+1][1] = 0;
        }
