fn main() {
    let n = read::<usize>();
    let mut pairs = vec![];
    for i in 0..n {
        let v = read_vec::<i64>();
        pairs.push((v[0], v[1]));
    }
    if n == 2 {
        let mut ans = pairs[0].1 - pairs[0].0 + 1;
        ans += pairs[1].1 - pairs[1].0 + 1;
        println!("{}", ans);
        return;
    }
    let r_min = pairs.iter().map(|&x| x.1).min().unwrap();
    let l_max = pairs.iter().map(|&x| x.0).max().unwrap();

    let mut max_left_idx = 0;
    let mut max_length = 0;
    for (i, &(l, r)) in pairs.iter().enumerate() {
        if l_max == l && r - l > max_length {
            max_length = r - l;
            max_left_idx = i;
        }
    }
    let mut min_right_idx = 0;
    let mut max_length = 0;
    for (i, &(l, r)) in pairs.iter().enumerate() {
        if r_min == r && r - l > max_length {
            max_length = r - l;
            min_right_idx = i;
        }
    }
    if max_left_idx == min_right_idx {
        let mut ans = pairs[max_left_idx].1 - pairs[max_left_idx].0 + 1;
        ans += pairs.iter().map(|&x| x.1 - x.0 + 1).max().unwrap();
        println!("{}", ans);
        return;
    }

    let mut unused = vec![];
    for i in 0..n {
        if i == max_left_idx || i == min_right_idx {
            continue;
        }
        unused.push(pairs[i]);
    }
    unused.sort_by_key(|x| (x.1, -x.0));
    unused.reverse();
    //debug!(unused);
    let mut accum_l_max = vec![0; unused.len() + 1];
    accum_l_max[unused.len()] = pairs[min_right_idx].0;
    accum_l_max[unused.len() - 1] = max(unused[unused.len() - 1].0, accum_l_max[unused.len()]);
    for i in 0..accum_l_max.len() - 1 {
        accum_l_max[i] = max(unused[i].0, accum_l_max[i + 1]);
    }
    let base_pair_rmin = pairs[min_right_idx].1;
    let base_pair_lmax = pairs[max_left_idx].0;
    let part1 = pairs[max_left_idx].1 - pairs[max_left_idx].0 + 1;
    let part2 = base_pair_rmin - accum_l_max[0] + 1;
    let mut ans = 0;
    if part1 > 0 {
        ans += part1;
    }
    if part2 > 0 {
        ans += part2;
    }

    for (i, (_, r)) in unused.into_iter().enumerate() {
        let mut temp = 0;
        let part1 = r - base_pair_lmax + 1;
        if part1 > 0 {
            temp += part1;
        }
        let part2 = base_pair_rmin - accum_l_max[i + 1] + 1;
        if part2 > 0 {
            temp += part2;
        }
        ans = max(ans, temp);
    }

    let mut length_max = pairs.iter().map(|&x| x.1 - x.0 + 1).max().unwrap();
    if r_min >= l_max {
        length_max += r_min - l_max + 1;
    }
    ans = max(ans, length_max);
    println!("{}", ans);
}

fn argsort<T: std::cmp::Ord + std::marker::Copy>(v: &Vec<T>) -> Vec<usize> {
    let mut sort_v = Vec::new();
    for i in 0..v.len() {
        sort_v.push((v[i], i));
    }
    sort_v.sort();
    sort_v.iter().map(|x| x.1).collect::<Vec<usize>>()
}

