fn main() {
    input! {
        n:usize,
        vlr0:[(u64,u64);n],
    }

    let calc = |l, r| {
        // スコアの計算
        if l <= r {
            r - l + 1
        } else {
            0
        }
    };
    /*
       2回目のコンテストで正解者が0の場合 → 1問とそれ以外に分ける
       2回のコンテストの両方とも正解者が0でない場合
         → 1問とそれ以外に分けた場合
         → 2つに分けた場合
       の2パターン
    */
    let mut max_score = 0;

    /* 1問とそれ以外に分けた場合 */
    let mut lmax = vlr0.clone();
    lmax.sort_by_key(|x| 1000000001 - x.0);
    let mut rmin = vlr0.clone();
    rmin.sort_by_key(|x| x.1);
    for lr in vlr0.iter() {
        let (l, r) = *lr;
        let lother = if l == lmax[0].0 { lmax[1].0 } else { lmax[0].0 };
        let rother = if r == rmin[0].1 { rmin[1].1 } else { rmin[0].1 };
        let score = calc(l, r) + calc(lother, rother);
        //println!("l:{} r:{} lrem:{} rrem:{} / {}", l, r, lrem, rrem, score);
        max_score = max(max_score, score);
    }

    /* 2つに分けた場合。 r0を含むグループか、l1を含むグループ の2つ。  */
    let r0 = vlr0.iter().min_by_key(|x| x.1).unwrap().1; // rの最小値
    let l1 = vlr0.iter().max_by_key(|x| x.0).unwrap().0; // lの最大値

    let mut vlr = vlr0.clone();
    vlr.sort_by_key(|p| p.1 * 0x100000000u64 + p.0);
    // vlr[0..i) を1回目のコンテストにする [l0,r0]
    // vlr[i..n) を2回目のコンテストにする [l1,r1]
    let mut l0 = 0;
    for i in 1..vlr.len() {
        if vlr[i - 1].0 > l0 {
            l0 = vlr[i - 1].0;
        }
        let r1 = vlr[i].1;
        let score = calc(l0, r0) + calc(l1, r1);
        //println!("l0:{} r:0{} l1:{}, r1:{} / {}", l0, r0, l1, r1, score);
        max_score = max(max_score, score);
    }

    println!("{}", max_score);
}

