fn solve() {
    let n = get!(usize);
    let mut lr = get!(usize, usize; n);

    let mut mxl = lr[0].0;
    let mut mnr = lr[0].1;
    let mut mxrange = 0;
    for &(l,r) in &lr {
        mxrange = max!(mxrange, r-l);
        mxl = max!(mxl, l);
        mnr = min!(mnr, r);
    }
    let mut mx = mxrange + mnr.saturating_sub(mxl);
    lr.sort_by(|&(l1,r1), &(l2,r2)| {
        let a1 = r1.saturating_sub(mxl);
        let a2 = r2.saturating_sub(mxl);
        if a1 == a2 {
            let b1 = mnr.saturating_sub(l1);
            let b2 = mnr.saturating_sub(l2);
            b2.cmp(&b1)
        } else {
            a1.cmp(&a2)
        }
    });

    let mut sums = vec![(0, 1_000_000_000); n+1];
    for i in 0..n {
        sums[i+1] = (max!(lr[i].0,sums[i].0), min!(lr[i].1, sums[i].1));
    }

    let mut rsums = vec![(0, 1_000_000_000); n+1];
    for i in (0..n).rev() {
        rsums[i] = (max!(lr[i].0,rsums[i+1].0), min!(lr[i].1, rsums[i+1].1));
    }

    for i in 0..n-1 {
        mx = max!(mx, (sums[i+1].1+1).saturating_sub(sums[i+1].0)+(rsums[i+1].1+1).saturating_sub(rsums[i+1].0));
    }
    println!("{}", mx);
}

