    lr.sort_by_key(|&(l, r)| (l, -r));

    for i in 0..(n - 1) {
        let (l, r) = lr[i];
        remove(l, &mut left_set);
        remove(r, &mut right_set);
        push(l, &mut left_set2);
        push(r, &mut right_set2);

        let ans1 = solver(&left_set, &right_set);
        let ans2 = solver(&left_set2, &right_set2);
        ans = cmp::max(ans, ans1 + ans2);
    }

    println!("{}", ans);
}

fn solver(left_set: &BTreeMap<i64, usize>, right_set: &BTreeMap<i64, usize>) -> i64 {
    let max_l = *left_set.keys().next_back().unwrap();
    let min_r = *right_set.keys().next().unwrap();
    cmp::max(min_r - max_l + 1, 0)
}

fn push(v: i64, map: &mut BTreeMap<i64, usize>) {
    let t = map.entry(v).or_insert(0);
    *t += 1;
}

fn remove(v: i64, map: &mut BTreeMap<i64, usize>) {
    let t = map.get(&v).cloned().unwrap();
    if t == 1 {
        assert_eq!(map.remove(&v), Some(1));
    } else {
        map.insert(v, t - 1);
    }
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> IO<R, W> {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: std::ops::Deref<Target = str>>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.as_bytes()).unwrap();
    }
