fn f(xs: &Vec<(i64, i64)>) -> i64 {
    let n = xs.len();
    let mut res = 0;
    for iter in 0..2 {
        let mut xs = xs.clone();
        if iter == 0 {
            xs.sort();
        } else {
            let mut ys = vec![];
            for &(l, r) in &xs {
                ys.push((l, -r));
            }
            ys.sort();
            xs.clear();
            for &(l, r) in &ys {
                xs.push((l, -r));
            }
            /*
            xs.sort_by(|&x,&y| {
                if x.0 != y.0 {
                    x.0.cmp(&y.0)
                }
                else {
                    y.0.cmp(&x.0)
                }
            })*/
        }
        // eprintln!("iter = {}, xs = {:?}", iter, xs);
        let n = xs.len();
        let inf = 1i64 << 50;
        let mut lower_left_max = vec![inf; n];
        let mut t = 0;
        for i in 0..n {
            t = max(t, xs[i].0);
            lower_left_max[i] = t;
        }
        let mut lower_right_min = vec![0; n];
        let mut t = inf;
        for i in 0..n {
            t = min(t, xs[i].1);
            lower_right_min[i] = t;
        }
        let mut upper_left_max = vec![inf; n];
        let mut t = 0;
        for i in (0..n).rev() {
            t = max(t, xs[i].0);
            upper_left_max[i] = t;
        }
        let mut upper_right_min = vec![0; n];
        let mut t = inf;
        for i in (0..n).rev() {
            t = min(t, xs[i].1);
            upper_right_min[i] = t;
        }
        for i in 0..n - 1 {
            let t = max(0, lower_right_min[i] - lower_left_max[i] + 1);
            let u = max(0, upper_right_min[i + 1] - upper_left_max[i + 1] + 1);
            res = max(res, t + u);
        }
        for i in 0..n {
            let t = max(0, xs[i].1 - xs[i].0 + 1);
            let mut right_min = inf;
            if i > 0 {
                right_min = min(right_min, lower_right_min[i - 1]);
            }
            if i < n - 1 {
                right_min = min(right_min, upper_right_min[i + 1]);
            }
            let mut left_max = 0;
            if i > 0 {
                left_max = max(left_max, lower_left_max[i - 1]);
            }
            if i < n - 1 {
                left_max = max(left_max, upper_left_max[i + 1]);
            }
            res = max(res, t + max(0, right_min - left_max + 1));
        }
    }
    res
}

fn g(xs: &Vec<(i64, i64)>) -> i64 {
    let n = xs.len();
    let inf = 1i64 << 50;
    let mut res = 0;
    for i in 1..(1 << n - 1) {
        let mut left_max = [0, 0];
        let mut right_min = [inf, inf];
        for k in 0..n {
            if i & (1 << k) == 0 {
                left_max[0] = max(left_max[0], xs[k].0);
                right_min[0] = min(right_min[0], xs[k].1);
            } else {
                left_max[1] = max(left_max[1], xs[k].0);
                right_min[1] = min(right_min[1], xs[k].1);
            }
        }
        let s = max(0, right_min[0] - left_max[0] + 1);
        let t = max(0, right_min[1] - left_max[1] + 1);
        res = max(res, s + t);
    }
    res
}

