    let mut rsum = vec![0; n - 1];

    {
        let mut l = lr[0].0;
        let mut r = lr[0].1;

        for i in 1..n {
            if r >= l {
                lsum[i - 1] = r - l + 1;
            }
            l = max(l, lr[i].0);
            r = min(r, lr[i].1);
        }
    }

    lr.reverse();
    {
        let mut l = lr[0].0;
        let mut r = lr[0].1;

        for i in 1..n {
