                rsum[i - 1] = r - l + 1;
            }
            l = max(l, lr[i].0);
            r = min(r, lr[i].1);
        }
    }
    rsum.reverse();

    // dbg!(&lsum, &rsum);

    let mut ans = 0;

    for i in 0..n - 1 {
        ans = max(ans, lsum[i] + rsum[i]);
    }

