fn main(){
    let mut buf = String::new();
    std::io::stdin().read_to_string(&mut buf).unwrap();
    let mut iter = buf.split_whitespace();
    let N = iter.next().unwrap().parse::<usize>().unwrap();

    let mut LR = (0..N).map(|_| (
        iter.next().unwrap().parse::<isize>().unwrap(),
        iter.next().unwrap().parse::<isize>().unwrap()
    )).collect::<Vec<_>>();
    LR.sort();

    let mut ra = (0..N).map(|_| LR[0].1).collect::<Vec<_>>();
    let mut rb = (0..N).map(|_| LR[N-1].1).collect::<Vec<_>>();
    for i in 1..N{
        ra[i] = min(ra[i-1],LR[i].1);
        let i = N-1-i;
        rb[i] = min(rb[i+1],LR[i].1);
    }

    let lf = LR[N-1].0;
    let mut ans = ra[0]-LR[0].0+1 + max(0,rb[1]-lf+1);
    for i in 1..N-1{
        let (li,ri) = LR[i];
        let mut tmp = max(0,min(ri,ra[i-1])-li+1)+max(0,rb[i+1]-lf+1);
        tmp = max(tmp,max(0,ri-li+1)+max(0,min(ra[i-1],rb[i+1])-lf+1));
        ans = max(ans,tmp);
    }

    println!("{}",ans);
}

