pub struct SegmentTree<T: Clone, F: Fn(&T, &T) -> T> {
    heap: Vec<T>,
    identity: T,
    aggregate: F,
}
mod segment_tree_internal {
    pub fn parent_of(heap_index: usize) -> usize {
        (heap_index - 1) / 2
    }
    pub fn left_of(heap_index: usize) -> usize {
        heap_index * 2 + 1
    }
    pub fn right_of(heap_index: usize) -> usize {
        left_of(heap_index) + 1
    }
    pub fn is_root_or_right(heap_index: usize) -> bool {
        heap_index % 2 == 0
    }
}
impl<T: Clone, F: Fn(&T, &T) -> T> SegmentTree<T, F> {
    pub fn new(len: usize, identity: T, aggregate: F) -> SegmentTree<T, F> {
        SegmentTree {
            heap: vec![identity.clone(); (len * 2).saturating_sub(1)],
            identity: identity,
            aggregate: aggregate,
        }
    }
    pub fn from_vec(mut items: Vec<T>, identity: T, aggregate: F) -> SegmentTree<T, F> {
        use self::segment_tree_internal::*;
        let node_count = items.len().saturating_sub(1);
        let mut heap = Vec::with_capacity(node_count + items.len());
        unsafe {
            heap.set_len(node_count);
        }
        heap.append(&mut items);
        for i in (0..node_count).rev() {
            heap[i] = aggregate(&heap[left_of(i)], &heap[right_of(i)]);
        }
        SegmentTree {
            heap: heap,
            identity: identity,
            aggregate: aggregate,
        }
    }
    fn node_count(&self) -> usize {
        self.heap.len() / 2
    }
    pub fn len(&self) -> usize {
        self.heap.len() - self.node_count()
    }
    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }
    pub fn items(&self) -> &[T] {
        &self.heap[self.node_count()..self.node_count() + self.len()]
    }
    pub fn query(&self, range: std::ops::Range<usize>) -> Option<T> {
        if self.len() <= range.start {
            return None;
        }
        if self.len() < range.end {
            return None;
        }
        if range.start <= range.end {
            Some(self.aggregate_interval(
                self.node_count() + range.start,
                self.node_count() + range.end,
                self.identity.clone(),
                self.identity.clone(),
            ))
        } else {
            None
        }
    }
    fn aggregate_interval(
        &self,
        mut heap_start: usize,
        mut heap_end: usize,
        mut acc_left: T,
        mut acc_right: T,
    ) -> T {
        use self::segment_tree_internal::*;
        if heap_end == heap_start {
            (self.aggregate)(&acc_left, &acc_right)
        } else {
            if is_root_or_right(heap_start) {
                acc_left = (self.aggregate)(&acc_left, &self.heap[heap_start]);
                heap_start += 1;
            }
            if is_root_or_right(heap_end) {
                heap_end -= 1;
                acc_right = (self.aggregate)(&self.heap[heap_end], &acc_right);
            }
            self.aggregate_interval(
                parent_of(heap_start),
                parent_of(heap_end),
                acc_left,
                acc_right,
            )
        }
    }
    pub fn get_mut(&mut self, index: usize) -> Option<SegmentTreeItemRef<T, F>> {
        if index < self.len() {
            let heap_index = self.node_count() + index;
            Some(SegmentTreeItemRef {
                tree: self,
                heap_index: heap_index,
            })
        } else {
            None
        }
    }
    pub fn at(&mut self, index: usize) -> SegmentTreeItemRef<T, F> {
        self.get_mut(index).unwrap()
    }
    fn update_ancestors(&mut self, heap_index: usize) {
        use self::segment_tree_internal::*;
        if heap_index != 0 {
            let parent = parent_of(heap_index);
            let l = left_of(parent);
            let r = right_of(parent);
            self.heap[parent] = (self.aggregate)(&self.heap[l], &self.heap[r]);
            self.update_ancestors(parent);
        }
    }
}
pub struct SegmentTreeItemRef<'a, T: 'a + Clone, F: 'a + Fn(&T, &T) -> T> {
    tree: &'a mut SegmentTree<T, F>,
    heap_index: usize,
}
impl<'a, T, F> std::ops::Deref for SegmentTreeItemRef<'a, T, F>
where
    T: Clone,
    F: Fn(&T, &T) -> T,
{
    type Target = T;
    fn deref(&self) -> &T {
        &self.tree.heap[self.heap_index]
    }
}
impl<'a, T, F> std::ops::DerefMut for SegmentTreeItemRef<'a, T, F>
where
    T: Clone,
    F: Fn(&T, &T) -> T,
{
    fn deref_mut(&mut self) -> &mut T {
        &mut self.tree.heap[self.heap_index]
    }
}
impl<'a, T, F> Drop for SegmentTreeItemRef<'a, T, F>
where
    T: Clone,
    F: Fn(&T, &T) -> T,
{
    fn drop(&mut self) {
        self.tree.update_ancestors(self.heap_index);
    }
}
pub trait IteratorExtForSegmentTree: Sized + Iterator
where
    Self::Item: Clone,
{
    fn segment_tree<F>(self, identity: Self::Item, aggregate: F) -> SegmentTree<Self::Item, F>
    where
        F: Fn(&Self::Item, &Self::Item) -> Self::Item,
    {
        SegmentTree::from_vec(self.collect(), identity, aggregate)
    }
}
impl<I: Iterator> IteratorExtForSegmentTree for I where <I as Iterator>::Item: Clone {}

use std::cmp;

fn main() {
    read!(n = usize);
    let mut itvs = readx::<(u32_, u32)>();
    itvs.sort_by_key(|&(l, _)| l);
    let rs: Vec<u32> = itvs.iter().map(|&(_, r)| r).collect();
    let rmq = SegmentTree::from_vec(rs, u32::max_value(), |&a, &b| cmp::min(a, b));
    let ans1 = (1..n).map(|end| {
        let l1 = itvs[end-1].0;
        let r1 = rmq.query(0..end).unwrap();
        let l2 = itvs[n-1].0;
        let r2 = rmq.query(end..n).unwrap();
        r1.saturating_sub(l1) + r2.saturating_sub(l2)
    }).max().unwrap();

    let ans2 = (0..n).map(|i| {
        let n1 = itvs[i].1 - itvs[i].0;
        let l = if i == n-1 { itvs[n-2].0 } else { itvs[n-1].0 };
        let r = if i == n-1 {
            rmq.query(0..n).unwrap()
        } else {
            cmp::min(rmq.query(0..i).unwrap(), rmq.query(i+1..n).unwrap())
        };
        n1 + r.saturating_sub(l)
    }).max().unwrap();
    println!("{}", cmp::max(ans1, ans2));
}

