fn solve() {
    let n = get!(usize);
    let mut lr = get!(usize, usize; n);
    lr.sort_by(|&(l1,r1), &(l2,r2)| {
        if l1.cmp(&l2) == Ordering::Equal {
            r2.cmp(&r1)
        } else {
            l1.cmp(&l2)
        }
    });
    let mx = 1_000_000_000;
    let mut mnr = mx;
    let mut mxl = 0;
    let mut mxlength = 0;
    for &(l,r) in &lr {
        mnr = min!(mnr, r);
        mxl = max!(mxl, l);
        mxlength = max!(mxlength, r-l+1);
    }
    let mut res = mxlength+min!(mnr as isize - mxl as isize+1, 0) as usize;
    let mut forward = vec![(0,0); n+1];
    let mut back = vec![(0,0); n+1];
    forward[0] = (0,mx);
    for i in 0..n {
        forward[i+1] = (max!(forward[i].0, lr[i].0), min!(forward[i].1, lr[i].1));
    }
    back[n] = (0,mx);
    for i in (0..n).rev() {
        back[i] = (max!(back[i+1].0, lr[i].0), min!(back[i+1].1, lr[i].1));
    }

    for i in 1..n {
        let (fl,fr) = forward[i];
        let (bl,br) = back[i];
        let fl = fl as isize;
        let fr = fr as isize;
        let bl = bl as isize;
        let br = br as isize;
        res = max!(res, (max!(fr-fl+1,0)+max!(br-bl+1,0)) as usize);
    }
    println!("{}",res);
}

