    let mut ps = vec![];
    for i in 0 .. n {
        let l = get!();
        let r = get!();
        ps.push((l, r));
    }
    ps.sort();

    use std::collections::BTreeMap;

    let mut l1s = BTreeMap::new();
    let mut r1s = BTreeMap::new();
    let mut l2s = BTreeMap::new();
    let mut r2s = BTreeMap::new();
    let mut mem = vec![false; n];

    use std::cmp::{max, min};
    let mut cnt = 1;

    let ans = {
        let e = n - 1;
        let (mut l1, mut r1) = ps[0];
        let (mut l2, mut r2) = ps[e];
        mem[0] = true;
        *l1s.entry(-l1).or_insert(0) += 1;
        *r1s.entry(r1).or_insert(0) += 1;
        *l2s.entry(-l2).or_insert(0) += 1;
        *r2s.entry(r2).or_insert(0) += 1;
        for i in 1 .. n {
            if i == e {
                continue;
            }
            let (l, r) = ps[i];
            let tl1 = max(l1, l);
            let tr1 = min(r1, r);
            let tl2 = max(l2, l);
            let tr2 = min(r2, r);
            if max(0,tr1-tl1)+max(0,r2-l2)>max(0,r1-l1)+max(0,tr2-tl2) {
                l1 = tl1;
                r1 = tr1;
                *l1s.entry(-l).or_insert(0) += 1;
                *r1s.entry(r).or_insert(0) += 1;
                mem[i] = true;
                cnt += 1;
            } else {
                l2 = tl2;
                r2 = tr2;
                *l2s.entry(-l).or_insert(0) += 1;
                *r2s.entry(r).or_insert(0) += 1;
              }
        }

