use std::cmp;

fn main() {
    read!(n = usize);
    let mut itvs = readx::<(u32_, u32)>();
    itvs.sort_by_key(|&(l, _)| l);
    let rs: Vec<u32> = itvs.iter().map(|&(_, r)| r).collect();
    let rmq = SegmentTree::from_vec(rs, u32::max_value(), |&a, &b| cmp::min(a, b));
    let ans1 = (1..n).map(|end| {
        let l1 = itvs[end-1].0;
        let r1 = rmq.query(0..end).unwrap();
        let l2 = itvs[n-1].0;
        let r2 = rmq.query(end..n).unwrap();
        r1.saturating_sub(l1) + r2.saturating_sub(l2)
    }).max().unwrap();

    let ans2 = (0..n).map(|i| {
        let n1 = itvs[i].1 - itvs[i].0;
        let l = if i == n-1 { itvs[n-2].0 } else { itvs[n-1].0 };
        let r = if i == n-1 {
            rmq.query(0..n).unwrap()
        } else {
            cmp::min(rmq.query(0..i).unwrap(), rmq.query(i+1..n).unwrap())
        };
        n1 + r-l
    }).max().unwrap();
    println!("{}", cmp::max(ans1, ans2));
}

#[allow(unused_macros)]
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, bytes) => {
        read_value!($next, String).into_bytes()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

