    std::io::stdin().read_to_string(& mut buf).unwrap();
    let mut iter = buf.split_whitespace();

    let n = iter.next().unwrap().parse::<usize>().unwrap();
    let mut segments= (0..n).map(|_| {
        let l = iter.next().unwrap().parse::<i64>().unwrap() - 1;
        let r = iter.next().unwrap().parse::<i64>().unwrap();
        (l, r)
    }).collect::<Vec<(i64, i64)>>();

    let max_l = segments.iter().map(|&(l, _)| l).max().unwrap();
    let min_r = segments.iter().map(|&(_, r)| r).min().unwrap();
    let max_size = segments.iter().map(|&(l, r)| r - l).max().unwrap();
    let mut res = max_size + cmp::max(min_r - max_l, 0);

    segments.sort_by(|p1, p2| if p1.0 != p2.0 {
        return p1.0.cmp(&p2.0);
    } else {
        return p2.1.cmp(&p1.1);
    });
    let mut fl = vec![0; n + 1];
    for i in 0..n {
        fl[i + 1] = cmp::max(fl[i], segments[i].0);
    }
    let mut br = vec![1000_000_000; n + 1];
    for i in 0..n {
        let j = n - 1 - i;
        br[j] = cmp::min(br[j + 1], segments[j].1);
    }

    for i in 1..n {
        res = cmp::max(res, cmp::max(min_r - fl[i], 0) + cmp::max(br[i] - max_l, 0));
    }

    println!("{}", res);
}

