const INF: i64 = 1e10 as i64;

// ===

fn d2(a: i64, b: i64) -> i64 {
    max(0, b-a+1)
}

fn main() {
    input! {
        n: usize,
        ranges: [(i64, i64); n]
    };

    let mut lt = Treap::new();
    let mut rt = Treap::new();
    for i in 0..n {
        lt.push((ranges[i].0, i));
        rt.push((ranges[i].1, i));
    }
    let mut best = 0;
    // case1
    for i in 0..n {
        lt.remove((ranges[i].0, i));
        rt.remove((ranges[i].1, i));
        let ll = lt.max().unwrap().0;
        let rr = rt.min().unwrap().0;
        best = max(best, (ranges[i].1 - ranges[i].0 + 1) + max(0, rr-ll+1));
        lt.push((ranges[i].0, i));
        rt.push((ranges[i].1, i));
    }

    // case2
    let mut lmax = (0, 0);
    let mut rmin = (INF, 0);
    for i in 0..n {
        lmax = max(lmax, (ranges[i].0, i));
        rmin = min(rmin, (ranges[i].1, i));
    }
    if lmax.1 != rmin.1 {
        //
        let mut w = vec![];
        let mut rset = Treap::new();
        for i in 0..n {
            if i == lmax.1 || i == rmin.1 {
                continue;
            }
            w.push((ranges[i].0, ranges[i].1, i));
            rset.push((ranges[i].1, ranges[i].0, i));
        }
        rset.push((INF, INF, n));
        w.sort();


        let mut l_rmin = ranges[rmin.1].0;
        let mut r_lmax = ranges[lmax.1].1;

        // debug!(l_rmin, rmin.0, lmax.0, r_lmax);

        for (l, r, idx) in w {
            let r_lmaxl = min(r_lmax, rset.min().unwrap().0);
            best = max(best, d2(l_rmin, rmin.0) + d2(lmax.0, r_lmaxl));
            l_rmin = max(l_rmin, l);
            rset.remove((r, l, idx));
        }
        let r_lmaxl = min(r_lmax, rset.min().unwrap().0);
        best = max(best, d2(l_rmin, rmin.0) + d2(lmax.0, r_lmaxl));
    }

    println!("{}", best);
}

