fn main() {
    input! {
        n: usize,
        xs: [(i64,i64); n],
    }
    let mut xs = xs;
    xs.sort();
    let inf = 1i64 << 50;
    let mut lower_left_max = vec![inf; n];
    let mut t = 0;
    for i in 0..n {
        t = max(t, xs[i].0);
        lower_left_max[i] = t;
    }
    let mut lower_right_min = vec![0; n];
    let mut t = inf;
    for i in 0..n {
        t = min(t, xs[i].1);
        lower_right_min[i] = t;
    }
    let mut upper_left_max = vec![inf; n];
    let mut t = 0;
    for i in (0..n).rev() {
        t = max(t, xs[i].0);
        upper_left_max[i] = t;
    }
    let mut upper_right_min = vec![0; n];
    let mut t = inf;
    for i in (0..n).rev() {
        t = min(t, xs[i].1);
        upper_right_min[i] = t;
    }
    let mut res = 0;
    for i in 0..n - 1 {
        let t = max(0, lower_right_min[i] - lower_left_max[i] + 1);
        let u = max(0, upper_right_min[i + 1] - upper_left_max[i + 1] + 1);
        res = max(res, t + u);
    }
    println!("{}", res);
}

